  ('rol_cuoc', 'Oficiales de las Fuerzas Militares', '01100', 'Seguridad', 4, false, '{"codigo":"01100","nombre":"Oficiales de las Fuerzas Militares","descripcion":"Planean, organizan, comandan y ejecutan la implementación de procedimientos y políticas militares en todos los niveles jerárquicos; adiestran y comandan al personal de las fuerzas militares para garantizar la soberanía del territorio nacional y la defensa y promoción de los derechos humanos; dan instrucción del uso de armas y demás equipo militar; pasan revista a los destacamentos; asumen la responsabilidad por el bienestar de los subalternos; tienen las destrezas, habilidades y competencias requeridas para adelantar operaciones marítimas, fluviales, aéreas y terrestres, en función del desarrollo y la seguridad nacional, y llevan a cabo funciones similares a las realizadas en una variedad de ocupaciones civiles ajenas a las Fuerzas Militares. Se pueden desempeñar en ocupaciones exclusivas de las mismas Fuerzas, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"0","nombre":"FUERZAS MILITARES"},"subgrupo_principal":{"codigo":"01","nombre":"OFICIALES DE LAS FUERZAS MILITARES"},"subgrupo":{"codigo":"011","nombre":"Oficiales de las Fuerzas Militares"},"grupo_primario":{"codigo":"0110","nombre":"Oficiales de las Fuerzas Militares"}},"funciones":[{"consecutivo":1,"texto":"Planear, organizar, comandar e implementar las políticas y actividades de divisiones, brigadas, bases, batallones o unidades militares de combate en el Ejército Nacional, Armada Nacional o Fuerza Aérea colombiana."},{"consecutivo":2,"texto":"Comandar y participar en las operaciones de las fuerzas especiales y de tarea conjunta."},{"consecutivo":3,"texto":"Desarrollar operaciones militares con base en el conocimiento de las capacidades y acciones de la unidad a su cargo."},{"consecutivo":4,"texto":"Dirigir operaciones de despliegue rápido."},{"consecutivo":5,"texto":"Asumir la responsabilidad por el bienestar moral y disciplina de los batallones, destacamentos o unidades a su cargo."},{"consecutivo":6,"texto":"Comandar e intervenir en actividades de vigilancia y protección del territorio, espacio aéreo y aguas territoriales."},{"consecutivo":7,"texto":"Capacitar y preparar al personal en operaciones militares, el uso de armas y demás equipos de combate."},{"consecutivo":8,"texto":"Dirigir y orientar a los subordinados en el entrenamiento y las actividades de unidades de acuerdo con prácticas militares."},{"consecutivo":9,"texto":"Orientar los ejercicios de combate y otros entrenamientos de actividades de carácter ceremonial y público."},{"consecutivo":10,"texto":"Evitar cualquier práctica abusiva, arbitraria o discriminatoria."},{"consecutivo":11,"texto":"Organizar y brindar ayuda en operaciones de apoyo a las autoridades civiles en el control del orden público, apoyo en desastres naturales y otras situaciones de emergencia."},{"consecutivo":12,"texto":"Realizar tareas civiles bajo el grado de oficiales."},{"consecutivo":13,"texto":"Pasar revista a las unidades, preparar informes y rendir partes a sus superiores."},{"consecutivo":14,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"01100.001","nombre":"Almirante"},{"codigo":"01100.002","nombre":"Almirante de la Armada Nacional"},{"codigo":"01100.003","nombre":"Brigadier General"},{"codigo":"01100.004","nombre":"Brigadier General de Infantería de Marina"},{"codigo":"01100.005","nombre":"Brigadier General del Ejército Nacional"},{"codigo":"01100.006","nombre":"Brigadier General Fuerza Aérea"},{"codigo":"01100.007","nombre":"Cadete de la Fuerza Aérea"},{"codigo":"01100.008","nombre":"Cadete de las Fuerzas Armadas"},{"codigo":"01100.009","nombre":"Cadete del Ejército Nacional"},{"codigo":"01100.010","nombre":"Capitán de corbeta de la Armada Nacional"},{"codigo":"01100.011","nombre":"Capitán de fragata de la Armada Nacional"},{"codigo":"01100.012","nombre":"Capitán de Infantería de Marina"},{"codigo":"01100.013","nomb