  ('rol_cuoc', 'Otros miembros de las Fuerzas Militares', '03100', 'Seguridad', 1, false, '{"codigo":"03100","nombre":"Otros miembros de las Fuerzas Militares","descripcion":"Actúan y apoyan unidades de combate en operaciones de las Fuerzas Militares para la conservación, restablecimiento del orden público; realizan acciones de defensa para proteger el territorio, las aguas, el espacio aéreo nacional; defienden la soberanía, la independencia, la integridad del territorio nacional y el orden constitucional, y ejecutan funciones similares a las que se llevan a cabo en diversas ocupaciones civiles, ajenas a las Fuerzas Armadas. Se pueden desempeñar en ocupaciones exclusivas de las mismas fuerzas, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"0","nombre":"FUERZAS MILITARES"},"subgrupo_principal":{"codigo":"03","nombre":"OTROS MIEMBROS DE LAS FUERZAS MILITARES"},"subgrupo":{"codigo":"031","nombre":"Otros miembros de las Fuerzas Militares"},"grupo_primario":{"codigo":"0310","nombre":"Otros miembros de las Fuerzas Militares"}},"funciones":[{"consecutivo":1,"texto":"Acatar procedimientos con base en las directrices de los comandantes de las unidades militares y normas de disciplina."},{"consecutivo":2,"texto":"Atender actividades de vigilancia y protección del territorio, espacio aéreo y aguas territoriales."},{"consecutivo":3,"texto":"Operar vehículos blindados, artillería, armamento y otros equipos de combate militar y sistemas de defensa."},{"consecutivo":4,"texto":"Participar en ejercicios de combate y otros entrenamientos de preparación y en actividades de carácter ceremonial y público."},{"consecutivo":5,"texto":"Participar y brindar ayuda en operaciones de apoyo a las autoridades civiles en el control del orden público, en funciones de socorro en desastres naturales y otras situaciones de emergencia."},{"consecutivo":6,"texto":"Ejercer funciones de guardia."},{"consecutivo":7,"texto":"Operar y asistir en el mantenimiento del equipo de comunicación fijo, aéreo transportable, móvil y naval en las Fuerzas Armadas."},{"consecutivo":8,"texto":"Desempeñar funciones administrativas."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"03100.001","nombre":"Alumno de Infantería de Marina"},{"codigo":"03100.002","nombre":"Artillero"},{"codigo":"03100.003","nombre":"Bombardero"},{"codigo":"03100.004","nombre":"Dragoneante"},{"codigo":"03100.005","nombre":"Grumete"},{"codigo":"03100.006","nombre":"Grumete Infantería de Marina"},{"codigo":"03100.007","nombre":"Infante de Marina"},{"codigo":"03100.008","nombre":"Infante de Marina profesional"},{"codigo":"03100.009","nombre":"Infante de Marina regular"},{"codigo":"03100.010","nombre":"Operador de radio militar"},{"codigo":"03100.011","nombre":"Soldado"},{"codigo":"03100.012","nombre":"Soldado bachiller"},{"codigo":"03100.013","nombre":"Soldado campesino"},{"codigo":"03100.014","nombre":"Soldado de Infantería"},{"codigo":"03100.015","nombre":"Soldado del Ejército"},{"codigo":"03100.016","nombre":"Soldado Fuerza Aérea"},{"codigo":"03100.017","nombre":"Soldado profesional"},{"codigo":"03100.018","nombre":"Soldado profesional Armada"},{"codigo":"03100.019","nombre":"Soldado profesional del Ejército Nacional"},{"codigo":"03100.020","nombre":"Soldado recluta"},{"codigo":"03100.021","nombre":"Soldado regular"},{"codigo":"03100.022","nombre":"Soldado regular del Ejército Nacional"},{"codigo":"03100.023","nombre":"Soldado regular Fuerza Aérea"}],"conocimientos":[{"id":"66","nombre":"Educación militar y de defensa"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"27","nombre":"Seguridad pública"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"15","nombre":"Orientación al servicio"},{"id":"37","nombre":"Proactividad"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"11","nombre":"Trabajo 