  ('rol_cuoc', 'Jefes de comunidades étnicas / Jefas de comunidades étnicas', '11130', 'Administración, finanzas y derecho', 4, false, '{"codigo":"11130","nombre":"Jefes de comunidades étnicas / Jefas de comunidades étnicas","descripcion":"Planean, organizan, dirigen y controlan funciones legislativas, administrativas y ceremoniales basadas tanto en la tradición de su comunidad como en la repartición de los poderes y responsabilidades entre los dirigentes o jefes de sus colectividades y las autoridades locales, regionales y nacionales. Se pueden desempeñar en cargos del gobierno, sector público, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"1","nombre":"DIRECTORES Y GERENTES"},"subgrupo_principal":{"codigo":"11","nombre":"DIRECTORES EJECUTIVOS, PERSONAL DIRECTIVO DE LA ADMINISTRACIÓN Y LEGISLATIVOS"},"subgrupo":{"codigo":"111","nombre":"Miembros del poder ejecutivo y de los cuerpos legislativos"},"grupo_primario":{"codigo":"1113","nombre":"Jefes de comunidades étnicas"}},"funciones":[{"consecutivo":1,"texto":"Establecer objetivos de la organización de acuerdo con políticas estatales y leyes establecidas por los cuerpos legislativos; formular y aprobar programas y procedimientos conjuntamente con comités principales."},{"consecutivo":2,"texto":"Gobernar y administrar territorios indígenas conforme a sus costumbres y constitución."},{"consecutivo":3,"texto":"Garantizar el desarrollo e implementación de sistemas y procedimientos apropiados para el control presupuestal."},{"consecutivo":4,"texto":"Solucionar y sancionar los conflictos y las violaciones a las reglas y costumbres que se presenten entre los miembros de la comunidad o etnia."},{"consecutivo":5,"texto":"Representar a su comunidad o etnia en los consejos locales o regionales e incluso ante otros gobiernos de carácter municipal, regional, nacional o internacional o de su competencia."},{"consecutivo":6,"texto":"Informar y garantizar el cumplimiento de las normas, disposiciones y los proyectos que rigen a los miembros de la comunidad ."},{"consecutivo":7,"texto":"Recoger y distribuir entre las familias de la comunidad el excedente de producción o del usufructo de la tierra y demás recursos comunales."},{"consecutivo":8,"texto":"Dirigir y organizar las ceremonias que tengan lugar en relación con los nacimientos, los matrimonios, las defunciones, las cosechas y las fiestas tradicionales."},{"consecutivo":9,"texto":"Asesorar a los órganos del poder público."},{"consecutivo":10,"texto":"Coordinar con otros directores y funcionarios las actividades que lo requieran."},{"consecutivo":11,"texto":"Elaborar y presentar a los cuerpos legislativos y otras instancias, planes programas y presupuestos."},{"consecutivo":12,"texto":"Dirigir, asesorar, interpretar e implementar las políticas de gobierno."},{"consecutivo":13,"texto":"Supervisar a otros trabajadores."},{"consecutivo":14,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"11130.001","nombre":"Gobernador de comunidad indígena / Gobernadora de comunidad indígena"},{"codigo":"11130.002","nombre":"Jefe de comunidad indígena / Jefa de comunidad indígena"},{"codigo":"11130.003","nombre":"Jefe de etnia indígena / Jefa de etnia indígena"},{"codigo":"11130.004","nombre":"Jefe de pueblo / Jefa de pueblo"},{"codigo":"11130.005","nombre":"Jefe tradicional de pequeña población / Jefa tradicional de pequeña población"}],"conocimientos":[{"id":"1","nombre":"Gerencia y administración"},{"id":"6","nombre":"Gestión del talento humano y de personal"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"76","nombre":"Literatura y lingüística"}],"destrezas":[{"id":"17","nombre":"Análisis de necesidades"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"16","nombre":"Resolución de problemas complejos"}],"ocupaciones_afines":[{"codigo":"11110","nombre":"Directores formuladores y ejecutores de políticas y normas / Directoras formuladoras y ejecutoras de políticas y normas"},{"codigo":"11120","nombre":"Directores del gobierno / Directoras del gobierno"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"1113","ciuo08_obs":"Denominaciones completas","cno_codigo":"0012*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Dirigentes de organizaciones con un interés específico (partidos políticos, sindicatos y organizaciones sociales)', '11140', 'Administración, finanzas y derecho', 4, false, '{"codigo":"11140","nombre":"Dirigentes de organizaciones con un interés específico (partidos políticos, sindicatos y organizaciones sociales)","descripcion":"Planean, formulan, definen e implementan las políticas, estatutos y reglamentos de la organización de membresía como partidos políticos, organizaciones sindicales, asociaciones de profesionales, comerciales y gremiales, asociaciones deportivas o de fines particulares; velan por su cumplimiento y actúan en su nombre y representación. Se pueden desempeñar en organizaciones deportivas, asociaciones de profesionales, sindicatos estatales, gremios, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"1","nombre":"DIRECTORES Y GERENTES"},"subgrupo_principal":{"codigo":"11","nombre":"DIRECTORES EJECUTIVOS, PERSONAL DIRECTIVO DE LA ADMINISTRACIÓN Y LEGISLATIVOS"},"subgrupo":{"codigo":"111","nombre":"Miembros del poder ejecutivo y de los cuerpos legislativos"},"grupo_primario":{"codigo":"1114","nombre":"Dirigentes de organizaciones con un interés específico (partidos políticos, sindicatos y organizaciones sociales)"}},"funciones":[{"consecutivo":1,"texto":"Planear, formular, establecer y ejecutar las políticas, los objetivos, los estatutos y los reglamentos de organizaciones de membresía como partidos políticos, organizaciones sindicales, asociaciones de profesionales, comerciales, gremiales, entre otros de acuerdo con políticas estatales y leyes establecidas."},{"consecutivo":2,"texto":"Representar a la organización o delegar en representantes para que actúen en nombre de ella o de sus miembros y de sus clientes en negociaciones u otras funciones oficiales."},{"consecutivo":3,"texto":"Planificar y organizar campañas, eventos, grupos de trabajo, proyectos y establecer procedimientos para cumplir los objetivos establecidos por la administración principal en la organización de membresía como partidos políticos, organizaciones sindicales, asociaciones de profesionales, comerciales y gremiales."},{"consecutivo":4,"texto":"Asesorar a los órganos del poder público."},{"consecutivo":5,"texto":"Planificar, organizar, asignar y dirigir las actividades de grupos encargados de vigilar y controlar el manejo del presupuesto, la aplicación de las políticas, los estatutos y los reglamentos de la organización política."},{"consecutivo":6,"texto":"Contratar, coordinar y asesorar a directores y otros trabajadores sobre la prestación de servicios y programas al público en general, de organizaciones de membresía como partidos políticos, organizaciones sindicales, asociaciones de profesionales, comerciales y gremiales."},{"consecutivo":7,"texto":"Elaborar y presentar a los cuerpos legislativos y otras instancias, planes programas y presupuestos."},{"consecutivo":8,"texto":"Preparar y proclamar arengas o discursos en sitios públicos."},{"consecutivo":9,"texto":"Proteger y defender los intereses de la organización y de sus miembros ante los cuerpos legislativos, el gobierno y el público en general."},{"consecutivo":10,"texto":"Implementar políticas de gobierno."},{"consecutivo":11,"texto":"Ejercer la representación legal de organizaciones de membresía como partidos políticos, organizaciones sindicales, asociaciones de profesionales, comerciales y gremiales con el propósito de servir de enlace o vocero ante el gobierno."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"11140.001","nombre":"Defensor del pueblo / Defensora del pueblo"},{"codigo":"11140.002","nombre":"Director asociación de profesionales / Directora asociación de profesionales"},{"codigo":"11140.003","nombre":"Director asociación deportiva / Directora asociación deportiva"},{"codigo":"11140.004","nombre":"Director de establecimiento adaptación social / Directora de establecimiento adaptación soc