nte administrativo de banca / Vicepresidenta administrativa de banca"},{"codigo":"12113.025","nombre":"Vicepresidente comercial de entidades financieras / Vicepresidenta comercial de entidades financieras"},{"codigo":"12113.026","nombre":"Vicepresidente de mercadeo entidades financieras de telecomunicaciones / Vicepresidenta de mercadeo entidades financieras de telecomunicaciones"},{"codigo":"12113.027","nombre":"Vicepresidente de operaciones de banca / Vicepresidenta de operaciones de banca"},{"codigo":"12113.028","nombre":"Vicepresidente de operaciones entidades financieras de telecomunicaciones / Vicepresidenta de operaciones entidades financieras de telecomunicaciones"},{"codigo":"12113.029","nombre":"Vicepresidente de producción entidades financieras de telecomunicaciones / Vicepresidenta de producción entidades financieras de telecomunicaciones"}],"conocimientos":[{"id":"32","nombre":"Contabilidad e impuestos"},{"id":"3","nombre":"Economía"},{"id":"1","nombre":"Gerencia y administración"},{"id":"6","nombre":"Gestión del talento humano y de personal"},{"id":"33","nombre":"Gestión financiera, administración bancaria y seguros"},{"id":"28","nombre":"Leyes y gobierno"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"33","nombre":"Liderazgo"},{"id":"6","nombre":"Pensamiento crítico"}],"ocupaciones_afines":[{"codigo":"11200","nombre":"Directores y gerentes generales / Directoras y gerentas generales"},{"codigo":"12111","nombre":"Directores y gerentes financieros / Directoras y gerentas financieras"},{"codigo":"12112","nombre":"Directores y gerentes de seguros, bienes raíces y corretaje financiero / Directoras y gerentas de seguros, bienes raíces y corretaje financiero"},{"codigo":"13460","nombre":"Directores y gerentes de sucursales de bancos, de servicios fin