  ('rol_cuoc', 'Directores y gerentes de gestión de talento humano / Directoras y gerentas de gestión de talento humano', '12120', 'Administración, finanzas y derecho', 4, false, '{"codigo":"12120","nombre":"Directores y gerentes de gestión de talento humano / Directoras y gerentas de gestión de talento humano","descripcion":"Planean, diseñan, implementan y evalúan políticas, programas, proyectos y procedimientos de talento humano, contratos, salarios, beneficios laborales, capacitación y desarrollo de personal; consultan y asesoran a los directivos de otros departamentos y demás empleados sobre la interpretación de políticas de personal, materia de seguridad y salud ocupacional, acuerdos colectivos y análisis ocupacional, ya sea como director de un departamento de una gran empresa u organización o de una empresa que ofrece este tipo de servicios a otras empresas y organizaciones. Se pueden desempeñar en sector público y privado, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"1","nombre":"DIRECTORES Y GERENTES"},"subgrupo_principal":{"codigo":"12","nombre":"DIRECTORES ADMINISTRATIVOS Y COMERCIALES"},"subgrupo":{"codigo":"121","nombre":"Directores de administración y servicios"},"grupo_primario":{"codigo":"1212","nombre":"Directores y gerentes de gestión de talento humano"}},"funciones":[{"consecutivo":1,"texto":"Planear, dirigir y controlar actividades de departamentos de personal o talento humano según normativa y políticas organizacionales."},{"consecutivo":2,"texto":"Planear e implementar políticas y procesos de reclutamiento, contratación, evaluación, formación, entrenamiento, movilidad y desvinculación del personal de acuerdo con normativa, marco estratégico y procedimientos de la organización."},{"consecutivo":3,"texto":"Planear y organizar manuales de funciones, políticas de compensación, beneficios, procedimientos sobre fijación de la escala y los niveles salariales según procedimientos y normativa."},{"consecutivo":4,"texto":"Supervisar y verificar el cumplimiento del reglamento interno de trabajo y los programas de salud, seguridad y bienestar de acuerdo con políticas y normativa."},{"consecutivo":5,"texto":"Planear, administrar y controlar los presupuestos y contratos asociados al talento humano de acuerdo con políticas de la organización."},{"consecutivo":6,"texto":"Establecer, organizar y dirigir los procedimientos operativos, administrativos y las estrategias de comunicación organizacional según marco estratégico."},{"consecutivo":7,"texto":"Coordinar la implementación de los sistemas de información asociados a los procesos de la gestión del talento humano."},{"consecutivo":8,"texto":"Negociar acuerdos colectivos y mediar las relaciones laborales que mantengan un buen clima organizacional según normativa."},{"consecutivo":9,"texto":"Elaborar informes de gestión del talento humano de acuerdo con lineamientos organizacionales."},{"consecutivo":10,"texto":"Coordinar programas de evaluación del desempeño de acuerdo con normativa."},{"consecutivo":11,"texto":"Consultar y asesorar a la alta dirección, responsables de otros departamentos y colaboradores sobre la interpretación y administración de políticas y programas de talento humano de acuerdo con normativa y lineamientos organizacionales."},{"consecutivo":12,"texto":"Implementar manuales de funciones, estructurar planta de personal y programas de capacitación y desarrollo."},{"consecutivo":13,"texto":"Orientar y garantizar el cumplimiento de las normas legislativas relacionadas con los derechos de los empleados, salud, seguridad, igualdad de oportunidades y cuestiones conexas ."},{"consecutivo":14,"texto":"Verificar las novedades de nómina y el pago de seguridad social de acuerdo con normativa."},{"consecutivo":15,"texto":"Dirigir y controlar la formación, el entrenamiento, la programación, el rendimiento, la selección y la contratación del personal de acuerdo con políticas y normativa de la organización."},{"consecutivo":16,"texto":"Representar el departamento, la empresa y la organización en las relaciones con entidades externas."},{"consecutivo":17,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"12120.001","nombre":"Director de contratación / Directora de contratación"},{"codigo":"12120.002","nombre":"Director de departamento de desarrollo de personal / Directora de departamento de desarrollo de personal"},{"codigo":"12120.003","nombre":"Director de departamento de gestión humana / Directora de departamento de gestión humana"},{"codigo":"12120.004","nombre":"Director de departamento de seguridad industrial / Directora de departamento de seguridad industrial"},{"codigo":"12120.005","nombre":"Director de departamento de selección personal / Directora de departamento de selección personal"},{"codigo":"12120.006","nombre":"Director de personal / Directora de personal"},{"codigo":"12120.007","nombre":"Director de recursos humanos / Directora de recursos humanos"},{"codigo":"12120.008","nombre":"Director de relaciones industriales / Directora de relaciones industriales"},{"codigo":"12120.009","nombre":"Director de relaciones laborales / Directora de relaciones laborales"},{"codigo":"12120.010","nombre":"Director de desarrollo de personal / Directora de desarrollo de personal"},{"codigo":"12120.011","nombre":"Director en talento humano / Directora en talento humano"},{"codigo":"12120.012","nombre":"Director de seguridad industrial / Directora de seguridad industrial"},{"codigo":"12120.013","nombre":"Gerente de gestión humana / Gerenta de gestión humana"},{"codigo":"12120.014","nombre":"Gerente de recursos humanos / Gerenta de recursos humanos"},{"codigo":"12120.015","nombre":"Gerente de relaciones industriales / Gerenta de relaciones industriales"},{"codigo":"12120.016","nombre":"Gerente de talento humano / Gerenta de talento humano"},{"codigo":"12120.017","nombre":"Gerente HSEQ / Gerenta HSEQ (salud, seguridad, medio ambiente y calidad)"},{"codigo":"12120.018","nombre":"Jefe de bien