  ('rol_cuoc', 'Directores y gerentes de políticas y planeación / Directoras y gerentas de políticas y planeación', '12130', 'Administración, finanzas y derecho', 4, false, '{"codigo":"12130","nombre":"Directores y gerentes de políticas y planeación / Directoras y gerentas de políticas y planeación","descripcion":"Planean, organizan, dirigen y coordinan las actividades de asesoramiento sobre políticas, programas y planeación estratégica; gestionan las actividades de empresas que prestan servicios de desarrollo de planeación estratégica, comercio internacional, transporte, agricultura, entre otros para promover el desarrollo de negocios comerciales e industriales en áreas rurales y urbanas, ya sea como director de un departamento de una gran empresa u organización o de una empresa que ofrece este tipo de servicios a otras empresas y organizaciones. Se pueden desempeñar en el gobierno, sector público, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"1","nombre":"DIRECTORES Y GERENTES"},"subgrupo_principal":{"codigo":"12","nombre":"DIRECTORES ADMINISTRATIVOS Y COMERCIALES"},"subgrupo":{"codigo":"121","nombre":"Directores de administración y servicios"},"grupo_primario":{"codigo":"1213","nombre":"Directores y gerentes de políticas y planeación"}},"funciones":[{"consecutivo":1,"texto":"Planear, administrar y coordinar las investigaciones y el análisis de política, proyectos y programas de desarrollo económico y social."},{"consecutivo":2,"texto":"Elaborar, coordinar, aplicar y supervisar planes, programas y procedimientos estratégicos para lograr las metas, los objetivos, las normas de trabajo y proporcionar asesoría a otros funcionarios."},{"consecutivo":3,"texto":"Organizar y dirigir grupos de trabajo, comités de evaluación de proyectos, programas y los procedimientos para cumplir los objetivos establecidos por la administración principal."},{"consecutivo":4,"texto":"Consultar y asesorar con la alta dirección y con los directivos de otros departamentos de desarrollo económico u otro personal que administre programas para promover inversiones comerciales e industriales, en áreas rurales y urbanas."},{"consecutivo":5,"texto":"Planear, administrar y controlar el presupuesto, medidas de rendición de cuentas para el manejo de política, proyectos y programas de desarrollo económico y social."},{"consecutivo":6,"texto":"Dirigir, asesorar y supervisar al personal que hace investigación económica, preparan informes o administran programas en áreas como impuestos, comercio internacional, transporte o agricultura."},{"consecutivo":7,"texto":"Planear, dirigir y supervisar la formación, el entrenamiento, el rendimiento, la selección y la contratación del personal según políticas de la institución, el centro o el departamento."},{"consecutivo":8,"texto":"Planear, conducir y gestionar las actividades del personal en la elaboración de políticas y de planificación estratégica."},{"consecutivo":9,"texto":"Representar a la organización, el departamento o delegar en representantes para que actúe en nombre de ella en negociaciones, convenciones, seminarios, audiencias públicas, medios de comunicación, foros u otras funciones oficiales."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"12130.001","nombre":"Coordinador de política de gobierno / Coordinadora de política de gobierno"},{"codigo":"12130.002","nombre":"Director de análisis de política económica / Directora de análisis de política económica"},{"codigo":"12130.003","nombre":"Director de planeación empresarial / Directora de planeación empresarial"},{"codigo":"12130.004","nombre":"Director de planeación estratégica / Directora de planeación estratégica"},{"codigo":"12130.005","nombre":"Director de planeación social / Directora de planeación social"},{"codigo":"12130.006","nombre":"Director de política pública / Directora de política pública"},{"codigo":"12130.007","nombre":"Director de política y planeación / Directora de política y planeación"},{"codigo":"12130.008","nombre":"Director de políticas de impuestos / Directora de políticas de impuestos"},{"codigo":"12130.009","nombre":"Gerente de desarrollo de políticas / Gerenta de desarrollo de políticas"},{"codigo":"12130.010","nombre":"Gerente de programas de política de desarrollo económico / Gerenta de programas de política de desarrollo económico"}],"conocimientos":[{"id":"32","nombre":"Contabilidad e impuestos"},{"id":"1","nombre":"Gerencia y administración"},{"id":"6","nombre":"Gestión del talento humano y de personal"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"14","nombre":"Matemáticas"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"32","nombre":"Gestión del Talento Humano y de Personal"},{"id":"33","nombre":"Liderazgo"},{"id":"6","nombre":"Pensamiento crítico"}],"ocupaciones_afines":[{"codigo":"11120","nombre":"Directores del gobierno / Directoras del gobierno"},{"codigo":"11130","nombre":"Jefes de comunidades étnicas / Jefas de comunidades étnicas"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"1213","ciuo08_obs":"Denominaciones completas","cno_codigo":"0412*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Directores y gerentes de limpieza y mantenimiento / Directoras y gerentas de limpieza y mantenimiento', '12191', 'Administración, finanzas y derecho', 4, false, '{"codigo":"12191","nombre":"Directores y gerentes de limpieza y mantenimiento / Directoras y gerentas de limpieza y mantenimiento","descripcion":"Planean, organizan, dirigen y controlan las operaciones de limpieza y mantenimiento de instalaciones (infraestructura locativa), mantenimiento de equipos y herramientas, ya sea como director de un departamento de una gran empresa u organización o de una empresa que ofrece este tipo de servicios a otras empresas y organizaciones. Se pueden desempeñar en constructoras, centros comerciales, aeropuertos, puertos, bodegas de almacenamiento, terminales de transporte, conjuntos residenciales, departamentos de mantenimiento en empresas manufactureras, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"1","nombre":"DIRECTORES Y GERENTES"},"subgrupo_principal":{"codigo":"12","nombre":"DIRECTORES ADMINISTRATIVOS Y COMERCIALES"},"subgrupo":{"codigo":"121","nombre":"Directores de administración y servicios"},"grupo_primario":{"codigo":"1219","nombre":"Directores y gerentes de administración y servicios no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Planear, desarrollar e implementar los servicios, los procedimientos y las programaciones para el personal de limpieza, seguridad y mantenimiento de las instalaciones."},{"consecutivo":2,"texto":"Dirigir, gestionar y administrar el correcto desarrollo de las actividades de mantenimiento, reparación de maquinaria, equipo, sistemas eléctricos, mecánicos, entre otros y el suministro de información precisa y oportuna."},{"consecutivo":3,"texto":"Elaborar y presentar informes y documentos correspondientes a la prestación de los servicios de limpieza, seguridad y mantenimiento de las instalaciones."},{"consecutivo":4,"texto":"Planear, dirigir y supervisar la formación, el entrenamiento, el rendimiento, la selección y la contratación del personal de acuerdo con políticas y normativa de la empresa o el departamento."},{"consecutivo":5,"texto":"Desarrollar, establecer y gestionar los presupuestos y los contratos de servicios de limpieza y mantenimiento, controlar los gastos y los suministros, garantizar el uso eficiente de los equipos, los recursos y las instalaciones."},{"consecutivo":6,"texto":"Representar a la organización, el departamento o la institución o delegar en representantes para que actúe en nombre de ella en negociaciones, convenciones, seminarios, audiencias públicas, medios de comunicación, foros u otras funciones oficiales."},{"consecutivo":7,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"12191.001","nombre":"Director de departamento de limpieza / Directora de departamento de limpieza"},{"codigo":"12191.002","nombre":"Director de servicios de limpieza / Directora de servicios de limpieza"},{"codigo":"12191.003","nombre":"Gerente de mantenimiento / Gerenta de mantenimiento"},{"codigo":"12191.004","nombre":"Jefe de mantenimiento e infraestructura / Jefa de mantenimiento e infraestructura"},{"codigo":"12191.005","nombre":"Jefe de mantenimiento locativo / Jefa de mantenimiento locativo"},{"codigo":"12191.006","nombre":"Jefe del departamento de mantenimiento industrial / Jefa del departamento de mantenimiento industrial"},{"codigo":"12191.007","nombre":"Jefe de mantenimiento / Jefa de mantenimiento"},{"codigo":"12191.008","nombre":"Jefe de servicios de apoyo de mantenimiento / Jefa de servicios de apoyo de mantenimiento"},{"codigo":"12191.009","nombre":"Director de control de calidad de mantenimiento aeronáutico / Directora de control de calidad de mantenimiento aeronáutico"},{"codigo":"12191.010","nombre":"Director de aseguramiento de la calidad de mantenimiento / Directora de aseguramiento de la calidad de mantenimiento"},{"codigo":"12191.011","nombre":"Director de mantenimiento aeronáutico / Directora de mantenimiento aeronáutico"},{"codigo":"12191.012","nombre":"Gerente de mantenimiento aeronáutico / Gerenta de mantenimiento aeronáutico"}],"conocimientos":[{"id":"1","nombre":"Gerencia y administración"},{"id":"6","nombre":"Gestión del talento humano y de personal"},{"id":"38","nombre":"Mantenimiento"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"32","nombre":"Gestión del Talento Humano y de Personal"},{"id":"33","nombre":"Liderazgo"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"24","nombre":"Mantenimiento de equipos"}],"ocupaciones_afines":[{"codigo":"51510","nombre":"Supervisores de mantenimiento y limpieza en oficinas, hoteles y otros establecimientos / Supervisoras de mantenimiento y limpieza en oficinas, hoteles y otros establecimientos"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[{"sigla":"FAMA","nombre":"Fabricación, transformación de materiales, instalación, mantenimiento y reparación"}],"equivalencias":[{"ciuo08_codigo":"1219*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"0822","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Directores y gerentes de administración y servicios no clasificados en otras ocupaciones / Directoras y gerentas de administración y servicios no clasificados en otras ocupaciones', '12199', 'Administración, finanzas y derecho', 4, false, '{"codigo":"12199","nombre":"Directores y gerentes de administración y servicios no clasificados en otras ocupaciones / Directoras y gerentas de administración y servicios no clasificados en otras ocupaciones","descripcion":"Esta ocupación abarca a directores de administración y servicios del Grupo Primario 1219: Directores y gerentes de administración y servicios no clasificados en otras ocupaciones. Por ejemplo, incluye aquellos que planean, organizan, dirigen y controlan actividades de departamentos y de unidades administrativas y comerciales no clasificadas anteriormente, se incluyen ocupaciones como director de instalaciones, director de servicios de limpieza, director de servicios administrativos, entre otros, ya sea como director de un departamento de una gran empresa u organización o de una empresa que ofrece este tipo de servicios a otras empresas y organizaciones. Se pueden desempeñar en firmas de consultoría administrativa, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"1","nombre":"DIRECTORES Y GERENTES"},"subgrupo_principal":{"codigo":"12","nombre":"DIRECTORES ADMINISTRATIVOS Y COMERCIALES"},"subgrupo":{"codigo":"121","nombre":"Directores de administración y servicios"},"grupo_primario":{"codigo":"1219","nombre":"Directores y gerentes de administración y servicios no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Planear, organizar, dirigir y controlar las actividades que proveen servicios de apoyo, estudio y asesoramiento en los procesos administrativos, de acuerdo con políticas, estrategias de gestión y mercadeo."},{"consecutivo":2,"texto":"Coordinar, desarrollar y gestionar las actividades, los recursos administrativos y los físicos de la organización de acuerdo con estrategias de gestión y procesos administrativos."},{"consecutivo":3,"texto":"Elaborar, dirigir y asesorar al personal administrativo y hacer seguimiento a las actividades de seguridad, manejo financiero, provisión de recursos de acuerdo con políticas y protocolos administrativos."},{"consecutivo":4,"texto":"Analizar, elaborar y presentar informes de estados financieros y de gestión, documentos correspondientes a la prestación de los servicios, los métodos, los sistemas, los procedimientos, los programas y las operaciones de las áreas a cargo de la organización de acuerdo con estrategias y procesos administrativos."},{"consecutivo":5,"texto":"Desarrollar, establecer y gestionar los presupuestos, los contratos, controlar los gastos, los suministros y los inventarios, garantizar el uso eficiente de los equipos, los recursos y las instalaciones."},{"consecutivo":6,"texto":"Desarrollar, promover, gestionar y asesorar sobre métodos y organización administrativa, políticas, planes, programas, proyectos de gestión y cultura ambiental a nivel local, regional y nacional."},{"consecutivo":7,"texto":"Planear, dirigir y supervisar la formación, entrenamiento, rendimiento, selección y contratación del personal de acuerdo con políticas y normativa de la empresa o departamento."},{"consecutivo":8,"texto":"Planear, dirigir y gestionar al personal administrativo para asegurar el correcto desarrollo de las actividades y el suministro de información precisa y oportuna de acuerdo con protocolos y normativa de la organización ."},{"consecutivo":9,"texto":"Representar a la organización, departamento o institución o delegar en representantes para que actúe en nombre de ella en negociaciones, convenciones, seminarios, audiencias públicas, medios de comunicación, foros u otras funciones oficiales."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"12199.002","nombre":"Director administrativo / Directora administrativa"},{"codigo":"12199.003","nombre":"Director ambiental / Directora ambiental"},{"codigo":"12199.004","nombre":"Director de gestión ambiental / Directora de gestión ambiental"},{"codigo":"12199.005","nombre":"Director de servicios a empresas / Directora de servicios a empresas"},{"codigo":"12199.006","nombre":"Director de servicios administrativos / Directora de servicios administrativos"},{"codigo":"12199.007","nombre":"Director de servicios corporativos / Directora de servicios corporativos"},{"codigo":"12199.008","nombre":"Director de departamento administrativo / Directora de departamento administrativo"},{"codigo":"12199.009","nombre":"Director de departamento de seguridad / Directora de departamento de seguridad"},{"codigo":"12199.010","nombre":"Gerente administrativo / Gerenta administrativa"},{"codigo":"12199.011","nombre":"Gerente ambiental / Gerenta ambiental"},{"codigo":"12199.012","nombre":"Gerente de otros servicios administrativos / Gerenta de otros servicios administrativos"},{"codigo":"12199.013","nombre":"Gerente de servicios administrativos / Gerenta de servicios administrativos"},{"codigo":"12199.014","nombre":"Jefe administrativo / Jefa administrativa"},{"codigo":"12199.015","nombre":"Jefe de admisiones y registro / Jefa de admisiones y registro"},{"codigo":"12199.016","nombre":"Jefe de departamento de seguridad / Jefa de departamento de seguridad"},{"codigo":"12199.017","nombre":"Jefe de servicios administrativos / Jefa de servicios administrativos"},{"codigo":"12199.018","nombre":"Subdirector administrativo / Subdirectora administrativa"},{"codigo":"12199.019","nombre":"Subgerente administrativo / Subgerenta administrativa"},{"codigo":"12199.020","nombre":"Director de seguridad operacional aeronáutica / Directora de seguridad operacional aeronáutica"},{"codigo":"12199.021","nombre":"Director de sostenibilidad  / Directora de sostenibilidad"},{"codigo":"12199.022","nombre":"Director de operaciones de vigilancia y seguridad privada / Directora de operacion