  ('rol_cuoc', 'Directores y gerentes de ventas y mercadeo / Directoras y gerentas de ventas y mercadeo', '12211', 'Administración, finanzas y derecho', 4, false, '{"codigo":"12211","nombre":"Directores y gerentes de ventas y mercadeo / Directoras y gerentas de ventas y mercadeo","descripcion":"Planean, organizan, dirigen y controlan las actividades de ventas y mercadeo, ya sea como director de un departamento de una gran empresa u organización o de una empresa que ofrece este tipo de servicios a otras empresas y organizaciones. Se pueden desempeñar en empresas de comercio, empresas de consultoría de mercadeo, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"1","nombre":"DIRECTORES Y GERENTES"},"subgrupo_principal":{"codigo":"12","nombre":"DIRECTORES ADMINISTRATIVOS Y COMERCIALES"},"subgrupo":{"codigo":"122","nombre":"Directores de ventas, comercialización y desarrollo"},"grupo_primario":{"codigo":"1221","nombre":"Directores y gerentes de ventas y comercialización"}},"funciones":[{"consecutivo":1,"texto":"Planear, organizar y dirigir actividades de ventas y programas de mercadeo basados en los registros y las evaluaciones de mercado."},{"consecutivo":2,"texto":"Planear, desarrollar e implementar estrategias de comunicación y programas de información de promociones, métodos de ventas, incentivos y campañas especiales para publicitar actividades, eventos y venta de productos y servicios."},{"consecutivo":3,"texto":"Analizar, establecer y dirigir estudios, resultados y estrategias de mercadeo para crear o fortalecer cadenas de distribución de los productos y servicios."},{"consecutivo":4,"texto":"Planear, dirigir y gestionar las actividades del personal de ventas y mercadeo."},{"consecutivo":5,"texto":"Desarrollar, establecer y gestionar los presupuestos, controlar los gastos y suministros, garantizar el uso eficiente de los equipos y recursos."},{"consecutivo":6,"texto":"Establecer y dirigir los procedimientos operativos y administrativos relacionados con las ventas y actividades de mercadeo."},{"consecutivo":7,"texto":"Manejar la imagen, comunicación corporativa y las relaciones con los medios de comunicación en nombre de empresas, gobiernos y otras organizaciones."},{"consecutivo":8,"texto":"Planear, dirigir y supervisar la formación, el entrenamiento, el rendimiento, la selección y la contratación del personal de acuerdo con políticas y normativa de la empresa o el departamento."},{"consecutivo":9,"texto":"Coordinar el trabajo de departamentos o divisiones regionales."},{"consecutivo":10,"texto":"Representar a la organización, el departamento o la institución o delegar en representantes para que actúe en nombre de ella en negociaciones, convenciones, seminarios, audiencias públicas, medios de comunicación, foros u otras funciones oficiales."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"12211.001","nombre":"Director comercial / Directora comercial"},{"codigo":"12211.002","nombre":"Director comercial de ventas / Directora comercial de ventas"},{"codigo":"12211.003","nombre":"Director de comercialización / Directora de comercialización"},{"codigo":"12211.004","nombre":"Director de departamento comercial / Directora de departamento comercial"},{"codigo":"12211.005","nombre":"Director de departamento de desarrollo comercial / Directora de departamento de desarrollo comercial"},{"codigo":"12211.006","nombre":"Director de departamento de marketing / Directora de departamento de marketing"},{"codigo":"12211.007","nombre":"Director de departamento de servicios investigación mercados / Directora de departamento de servicios investigación mercados"},{"codigo":"12211.008","nombre":"Director de departamento de ventas y mercadeo / Directora de departamento de ventas y mercadeo"},{"codigo":"12211.009","nombre":"Director de mercadeo / Directora de mercadeo"},{"codigo":"12211.010","nombre":"Director de telemercadeo / Directora de telemercadeo"},{"codigo":"12211.011","nombre":