  ('rol_cuoc', 'Directores y gerentes de comercio exterior / Directoras y gerentas de comercio exterior', '12212', 'Administración, finanzas y derecho', 4, false, '{"codigo":"12212","nombre":"Directores y gerentes de comercio exterior / Directoras y gerentas de comercio exterior","descripcion":"Planean, organizan, dirigen y controlan actividades de comercio internacional, ya sea como director de un departamento u organización o de una empresa que ofrece este tipo de servicios a otras empresas y organizaciones. Se pueden desempeñar en empresas de servicios de aduanas, sector público, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"1","nombre":"DIRECTORES Y GERENTES"},"subgrupo_principal":{"codigo":"12","nombre":"DIRECTORES ADMINISTRATIVOS Y COMERCIALES"},"subgrupo":{"codigo":"122","nombre":"Directores de ventas, comercialización y desarrollo"},"grupo_primario":{"codigo":"1221","nombre":"Directores y gerentes de ventas y comercialización"}},"funciones":[{"consecutivo":1,"texto":"Planear, dirigir, monitorear y evaluar las operaciones de ingreso, salida, tránsito y depósito de mercancías de acuerdo normativa y políticas de comercio exterior."},{"consecutivo":2,"texto":"Planear, establecer y controlar los términos de entrega, precios, costos, y soluciones a las contingencias para el transporte de mercancías según modos y medios a nivel internacional y nacional."},{"consecutivo":3,"texto":"Establecer, dirigir y gestionar los procedimientos operativos y administrativos para cumplir los objetivos relacionados con el comercio exterior y las compras."},{"consecutivo":4,"texto":"Planear, dirigir y gestionar las actividades del personal de comercio exterior y compras."},{"consecutivo":5,"texto":"Desarrollar, establecer y gestionar los presupuestos de operaciones de logística y servicios conexos para el ingreso, la salida, el tránsito y el depósito de mercancías, controlar los gastos y garantizar el uso eficiente de los recursos según requerimientos del cliente y normativa de comercio exterior ."},{"consecutivo":6,"texto":"Negociar y elaborar términos técnicos sobre los servicios logísticos y de comercio exterior con los proveedores y clientes de acuerdo políticas de la organización."},{"consecutivo":7,"texto":"Representar a la organización, el departamento o delegar en representantes para que actúe en nombre de ella en negociaciones, entidades gubernamentales, convenciones, exposiciones comerciales, seminarios, foros u otras funciones oficiales."},{"consecutivo":8,"texto":"Planear, dirigir y supervisar la formación, el entrenamiento, el rendimiento, la selección y la contratación del personal de comercio exterior de acuerdo con políticas y normativa de la empresa o el departamento."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"12212.001","nombre":"Administrador de aduana / Administradora de aduana"},{"codigo":"12212.002","nombre":"Director de comercio exterior / Directora de comercio exterior"},{"codigo":"12212.003","nombre":"Director de departamento de importaciones y exportaciones / Directora de departamento de importaciones y exportaciones"},{"codigo":"12212.004","nombre":"Director del departamento internacional / Directora del departamento internacional"},{"codigo":"12212.005","nombre":"Director de importaciones y exportaciones / Directora de importaciones y exportaciones"},{"codigo":"12212.006","nombre":"Gerente de departamento de comercio exterior / Gerenta de departamento de comercio exterior"},{"codigo":"12212.007","nombre":"Gerente de exportaciones / Gerenta de exportaciones"},{"codigo":"12212.008","nombre":"Gerente de negocios internacionales / Gerenta de negocios internacionales"},{"codigo":"12212.009","nombre":"Gerente de servicios de comercio exterior / Gerenta de servicios de comercio exterior"},{"codigo":"12212.010","nombre":"Jefe de aduanas / Jefa de aduanas"},{"codigo":"12212.011","nombre":"Jefe de comercio exterior / Jefa de comercio exterior"},{"codigo"