  ('rol_cuoc', 'Directores y gerentes de publicidad y relaciones públicas / Directoras y gerentas de publicidad y relaciones públicas', '12220', 'Administración, finanzas y derecho', 4, false, '{"codigo":"12220","nombre":"Directores y gerentes de publicidad y relaciones públicas / Directoras y gerentas de publicidad y relaciones públicas","descripcion":"Planean, organizan, dirigen y controlan las actividades y estrategias de publicidad, relaciones públicas e información; divulgan actividades, eventos y mantienen buenas relaciones con los medios, las agencias de comunicación, publicitaria y de diseño, ya sea como director de un departamento de una gran empresa u organización o de una empresa que ofrece este tipo de servicios a otras empresas y organizaciones. Se pueden desempeñar en firmas de consultoría, corporaciones, asociaciones, gobierno, instituciones sociales, medios de comunicación, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"1","nombre":"DIRECTORES Y GERENTES"},"subgrupo_principal":{"codigo":"12","nombre":"DIRECTORES ADMINISTRATIVOS Y COMERCIALES"},"subgrupo":{"codigo":"122","nombre":"Directores de ventas, comercialización y desarrollo"},"grupo_primario":{"codigo":"1222","nombre":"Directores y gerentes de publicidad y relaciones públicas"}},"funciones":[{"consecutivo":1,"texto":"Planear, implementar, dirigir y controlar las actividades y estrategias de publicidad y relaciones públicas de una empresa, un departamento o una organización para promocionar la venta de productos y servicios."},{"consecutivo":2,"texto":"Planear, desarrollar, ejecutar y evaluar estrategias y programas de comunicación diseñados para informar a clientes, empleados y público en general sobre iniciativas, políticas, planes, logros y puntos de vista, mantener buenas relaciones con medios de comunicación en nombre de una empresa, departamento u organización."},{"consecutivo":3,"texto":"Negociar contratos de publicidad con los clientes o con los periódicos, las estaciones de radio televisión, organizaciones deportivas y culturales y agencias de publicidad de acuerdo con la normativa y el protocolo de una empresa, un departamento o una organización."},{"consecutivo":4,"texto":"Desarrollar, establecer y gestionar los presupuestos, las políticas y los procedimientos, controlar los gastos y garantizar el uso eficiente de los recursos ."},{"consecutivo":5,"texto":"Establecer, dirigir y supervisar los procedimientos operativos y administrativos como programación de informes, resúmenes, bibliografías, boletines, discursos, presentaciones, comunicados de prensa y otro material."},{"consecutivo":6,"texto":"Planear, dirigir y gestionar las actividades del personal de publicidad y de relaciones públicas del trabajo, de acuerdo con normativa y protocolo de una empresa, departamento u organización."},{"consecutivo":7,"texto":"Planear, dirigir y supervisar la formación, el entrenamiento, el rendimiento, la selección y la contratación del personal de acuerdo con políticas y normativa de la organización."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"12220.001","nombre":"Director de comunicaciones y publicidad / Directora de comunicaciones y publicidad"},{"codigo":"12220.002","nombre":"Director de departamento de publicidad / Directora de departamento de publicidad"},{"codigo":"12220.003","nombre":"Director de departamento de servicios publicitarios / Directora de departamento de servicios publicitarios"},{"codigo":"12220.004","nombre":"Director de relaciones públicas / Directora de relaciones públicas"},{"codigo":"12220.005","nombre":"Director de publicaciones / Directora de publicaciones"},{"codigo":"12220.006","nombre":"Director de publicidad / Directora de publicidad"},{"codigo":"12220.007","nombre":"Director de relaciones públicas e información / Directora de relaciones públicas e información"},{"codigo":"12220.008","nombre":"Director de servicios publicitarios / Directora de servicios publi