  ('rol_cuoc', 'Directores y gerentes de ingeniería, investigación y desarrollo / Directoras y gerentas de ingeniería, investigación y desarrollo', '12230', 'Administración, finanzas y derecho', 4, false, '{"codigo":"12230","nombre":"Directores y gerentes de ingeniería, investigación y desarrollo / Directoras y gerentas de ingeniería, investigación y desarrollo","descripcion":"Planean, dirigen y coordinan las actividades de investigación y desarrollo científico de una empresa u organización que proporcionan servicios afines a otras empresas y organizaciones; preparan reportes, proveen consultoría y administran programas relacionados, ya sea como director de un departamento de una gran empresa u organización o de una empresa que ofrece este tipo de servicios a otras empresas y organizaciones. Se pueden desempeñar en empresas de consultoría e investigación científica, bebidas y alimentos, laboratorios farmacéuticos, organizaciones reguladoras, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"1","nombre":"DIRECTORES Y GERENTES"},"subgrupo_principal":{"codigo":"12","nombre":"DIRECTORES ADMINISTRATIVOS Y COMERCIALES"},"subgrupo":{"codigo":"122","nombre":"Directores de ventas, comercialización y desarrollo"},"grupo_primario":{"codigo":"1223","nombre":"Directores y gerentes de ingeniería, investigación y desarrollo"}},"funciones":[{"consecutivo":1,"texto":"Planear, dirigir y coordinar las actividades de investigación y desarrollo dentro de la empresa, o encomendadas por otras organizaciones de investigación para crear o mejorar procesos técnicos, productos, conocimientos o modos de utilización de materiales y minimizar el impacto ambiental."},{"consecutivo":2,"texto":"Planear, dirigir, coordinar y supervisar investigaciones y programas de desarrollo técnico y científico y asesorar sobre nuevas aplicaciones, productos, técnicas, entre otros de una empresa u organización."},{"consecutivo":3,"texto":"Desarrollar, establecer y gestionar el presupuesto, garantizar el uso eficiente de los recursos según protocolos de gestión del departamento o empresa."},{"consecutivo":4,"texto":"Desarrollar, establecer e implementar políticas, estrategias, normas y procedimientos para el trabajo técnico y científico ejecutado en el departamento, la empresa o el laboratorio."},{"consecutivo":5,"texto":"Planear, dirigir y evaluar el trabajo técnico del personal de investigación y desarrollo del departamento, la empresa o el laboratorio."},{"consecutivo":6,"texto":"Consultar y negociar con los clientes para explicar propuestas, preparar especificaciones o presentar informes y conclusiones de investigaciones de ingeniería y desarrollo."},{"consecutivo":7,"texto":"Planear, dirigir y supervisar la formación, el entrenamiento, el rendimiento, la selección y la contratación del personal de acuerdo con políticas y normativa del departamento, la empresa o el laboratorio."},{"consecutivo":8,"texto":"Representar a la organización, el departamento o delegar en representantes para que actúe en nombre de ella en negociaciones, convenciones, conferencias, seminarios, audiencias públicas, medios de comunicación, foros u otras funciones oficiales."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"12230.001","nombre":"Director científico / Directora científica"},{"codigo":"12230.002","nombre":"Director de consultoría científica / Directora de consultoría científica"},{"codigo":"12230.003","nombre":"Director de departamento de ingeniería / Directora de departamento de ingeniería"},{"codigo":"12230.004","nombre":"Director de departamento de investigación / Directora de departamento de investigación"},{"codigo":"12230.005","nombre":"Director de departamento de investigación y desarrollo / Directora de departamento de investigación y desarrollo"},{"codigo":"12230.006","nombre":"Director de desarrollo de productos / Directora de desarrollo de productos"},{"codigo":"12230.007","nombre":"Director de ingeniería / Direct