  ('rol_cuoc', 'Directores y gerentes de producción agropecuaria y silvicultura / Directoras y gerentas de producción agropecuaria y silvicultura', '13110', 'Administración, finanzas y derecho', 4, false, '{"codigo":"13110","nombre":"Directores y gerentes de producción agropecuaria y silvicultura / Directoras y gerentas de producción agropecuaria y silvicultura","descripcion":"Planean, organizan, dirigen y controlan las operaciones de producción de explotación a gran escala de agricultura, horticultura, silvicultura y ganadería teniendo en cuenta parámetros de calidad definidos, buscando la optimización de recursos, productividad del cultivo y mejora continua, mercadean productos de una finca. Se pueden desempeñar en fincas, grandes haciendas, granjas colectivas, cooperativas agrícolas, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"1","nombre":"DIRECTORES Y GERENTES"},"subgrupo_principal":{"codigo":"13","nombre":"DIRECTORES Y GERENTES EN SECTORES DE PRODUCCIÓN Y SERVICIOS"},"subgrupo":{"codigo":"131","nombre":"Directores de producción agropecuaria, silvicultura y pesca"},"grupo_primario":{"codigo":"1311","nombre":"Directores y gerentes de producción agropecuaria y silvicultura"}},"funciones":[{"consecutivo":1,"texto":"Elaborar, desarrollar y actualizar seguimientos de los mercados de la agricultura y la silvicultura, implementar correctivos de promoción, publicidad de producto y comunicación para cumplir con los requisitos del contrato y la demanda del mercado."},{"consecutivo":2,"texto":"Establecer, gestionar y preparar los presupuestos, informes administrativos, financieros, técnicos y de proceso productivo; registrar información de inventarios."},{"consecutivo":3,"texto":"Concertar, mercadear e informar las condiciones de venta de productos agrícolas y ganado con su respectivo cuidado."},{"consecutivo":4,"texto":"Planificar, dirigir, controlar y desarrollar procesos de comercialización y fidelización con clientes, abastecedores, otras organizaciones, propietarios independientes, entre otros."},{"consecutivo":5,"texto":"Planear, dirigir y controlar las operaciones de producción agrícola, ganadera, pecuaria acuícola según el tipo, la intensidad, la secuencia y el ganado a criar o levantar."},{"consecutivo":6,"texto":"Analizar y recomendar cambios operacionales para asegurar el cumplimiento de procedimientos que permitan aumentar los niveles de producción."},{"consecutivo":7,"texto":"Comprar maquinaria, equipos, suministros para granja, ganado, semillas, entre otros suministros y mantener inventarios."},{"consecutivo":8,"texto":"Investigar sobre las características, posibilidades de utilización, control de toxinas ambientales agrícolas y forestales, productividad de los suelos y los recursos naturales, aplicar los resultados al perfeccionamiento de las buenas prácticas agrícolas, pecuarias y silvícolas."},{"consecutivo":9,"texto":"Dirigir y coordinar las actividades de explotación agropecuaria y silvicultura."},{"consecutivo":10,"texto":"Inspeccionar, evaluar y supervisar las plantaciones y los campos para determinar la eficiencia de la producción y el uso adecuado de recursos humanos, físicos y tecnológicos."},{"consecutivo":11,"texto":"Contratar, controlar y supervisar la selección, la formación y el rendimiento del personal y velar por el entrenamiento y garantizar el cumplimiento de las normas de seguridad."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"13110.001","nombre":"Administrador agroindustrial / Administradora agroindustrial"},{"codigo":"13110.002","nombre":"Administrador agropecuario / Administradora agropecuaria"},{"codigo":"13110.003","nombre":"Administrador de finca agropecuaria / Administradora de finca agropecuaria"},{"codigo":"13110.004","nombre":"Administrador de granja / Administradora de granja"},{"codigo":"13110.005","nombre":"Administrador de hacienda / Administradora de hacienda"},{"codigo":"13110.006","nombre":"Administrador de hato ganadero / Administradora de hato ganadero"},{"codigo":"13110.007","nombre":"Administrador de vivero / Administradora de vivero"},{"codigo":"13110.008","nombre":"Administrador de finca / Administradora de finca"},{"codigo":"13110.009","nombre":"Administrador general de aprovechamiento agrícola / Administradora general de aprovechamiento agrícola"},{"codigo":"13110.010","nombre":"Administrador general de aprovechamiento pecuario / Administradora general de aprovechamiento pecuario"},{"codigo":"13110.011","nombre":"Administrador general de plantación agrícola / Administradora general de plantación agrícola"},{"codigo":"13110.012","nombre":"Administrador general de explotación agrícola / Administradora general de explotación agrícola"},{"codigo":"13110.013","nombre":"Administrador general de explotación pecuaria / Administradora general de explotación pecuaria"},{"codigo":"13110.014","nombre":"Administrador de granja integral / Administradora de granja integral"},{"codigo":"13110.016","nombre":"Administrador o gerente de planta / Administradora o gerenta de planta"},{"codigo":"13110.017","nombre":"Agregado de finca / Agregada de finca"},{"codigo":"13110.018","nombre":"Agricultor administrador agropecuaria / Agricultora administradora agropecuaria"},{"codigo":"13110.019","nombre":"Agricultor empresario / Agricultora empresaria"},{"codigo":"13110.020","nombre":"Director agronómico / Directora agronómica"},{"codigo":"13110.021","nombre":"Director de calidad agropecuaria / Directora de calidad agropecuaria"},{"codigo":"13110.022","nombre":"Director de cosecha / Directora de cosecha"},{"codigo":"13110.023","nombre":"Director de explotación forestal / Directora de explotación forestal"},{"codigo":"13110.024","nombre":"Director de hacienda / Directora de hacienda"},{"codigo":"13110.025","nombre":"Director de plantación / Directora de plantación"},{"codigo":"13110.026","nombre":"Director de producción agropecuaria / Directora de producción agropecuaria"},{"codigo":"13110.027","nombre":"Director de producción avícola / Directora de producción avícola"},{"codigo":"13110.028","nombre":"Director de vivero / Directora de vivero"},{"codigo":"13110.029","nombre":"Director del departamento agronómico / Directora del departamento agronómico"},{"codigo":"13110.030","nombre":"Director general agropecuario / Directora general agropecuaria"},{"codigo":"13110.031","nombre":"Director de MIPE (manejo integrado de plagas y enfermedades) / Directora de MIPE (manejo integrado de plagas y enfermedades)"},{"codigo":"13110.032","nombre":"Director de postcosecha / Directora de postcosecha"},{"codigo":"13110.033","nombre":"Ganadero empresario / Ganadera empresaria"},{"codigo":"13110.034","nombre":"Gerente de aprovechamiento agrícola / Gerenta de aprovechamiento agrícola"},{"codigo":"13110.035","nombre":"Gerente de aprovechamiento forestal / Gerenta de aprovechamiento forestal"},{"codigo":"13110.036","nombre":"Gerente de aprovechamiento silvícola / Gerenta de aprovechamiento silvícola"},{"codigo":"13110.037","nombre":"Gerente de empresa agrícola / Gerenta de empresa agrícola"},{"codigo":"13110.038","nombre":"Gerente de operaciones de silvicultura / Gerenta de operaciones de silvicultura"},{"codigo":"13110.039","nombre":"Gerente de planta de beneficio animal / Gerenta de planta de beneficio animal"},{"codigo":"13110.040","nombre":"Gerente de planta de incubación / Gerenta de planta de incubación"},{"codigo":"13110.041","nombre":"Gerente de plantación / Gerenta de plantación"},{"codigo":"13110.042","nombre":"Gerente de producción agrícola / Gerenta de producción agrícola"},{"codigo":"13110.044","nombre":"Gerente de producción agropecuaria / Gerenta de producción agropecuaria"},{"codigo":"13110.045","nombre":"Gerente de producción pecuaria / Gerenta de producción pecuaria"},{"codigo":"13110.046","nombre":"Gerente de explotación agrícola / Gerenta de explotación agrícola"},{"codigo":"13110.047","nombre":"Gerente de explotación forestal / Gerenta de explotación for