  ('rol_cuoc', 'Directores y gerentes de cadena de suministro / Directoras y gerentas de cadena de suministro', '13244', 'Administración, finanzas y derecho', 4, false, '{"codigo":"13244","nombre":"Directores y gerentes de cadena de suministro / Directoras y gerentas de cadena de suministro","descripcion":"Planean, organizan, dirigen y controlan las actividades relacionadas con los eslabones de la cadena de suministro y colaboran entre las empresas de los diferentes sectores productivos; ya sea como director de un departamento o como el gerente general de una empresa u organización que no cuenta con una estructura jerarquizada de directivos. Se pueden desempeñar en empresas de transporte, despacho y embarque de carga, departamentos de transporte de empresas manufactureras, comercio al por mayor y al por menor, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"1","nombre":"DIRECTORES Y GERENTES"},"subgrupo_principal":{"codigo":"13","nombre":"DIRECTORES Y GERENTES EN SECTORES DE PRODUCCIÓN Y SERVICIOS"},"subgrupo":{"codigo":"132","nombre":"Directores de industrias manufactureras, minería, construcción y distribución"},"grupo_primario":{"codigo":"1324","nombre":"Directores y gerentes de abastecimiento, distribución, transporte y afines"}},"funciones":[{"consecutivo":1,"texto":"Planear, organizar, dirigir y coordinar las estrategias, las políticas y los planes en materia de sistemas de almacenamiento e inventario para cumplir las previsiones de abastecimiento, y control de niveles de existencias según mejores prácticas, modelos de gestión y protocolo de seguimiento del departamento, empresa u organización."},{"consecutivo":2,"texto":"Identificar, seleccionar y evaluar contratos con los proveedores de acuerdo con los términos de negociación y criterios técnicos en sistemas de almacenamiento e inventario para cumplir las previsiones de abastecimiento y control de niveles de existencias, según políticas de la organización."},{"consecutivo":3,"texto":"Examinar, operar y supervisar los sistemas de registro para el seguimiento de todos los movimientos de mercancías y para cumplir las previsiones de abastecimiento y el control de niveles de existencias en tiempos óptimos, según mejores prácticas y modelos de gestión."},{"consecutivo":4,"texto":"Planear la integración con otros departamentos y con clientes sobre los requisitos aplicables a los sistemas de almacenamiento e inventario para cumplir las previsiones de abastecimiento, y el control de niveles de existencias, según mejores prácticas y modelos de gestión."},{"consecutivo":5,"texto":"Controlar el registro de las operaciones de almacenamiento e inventario para cumplir las previsiones de abastecimiento y el control de niveles de existencias, según mejores prácticas y modelos de gestión."},{"consecutivo":6,"texto":"Determinar y proyectar la demanda de los clientes, según métodos de compras y pronósticos atendiendo a políticas de la empresa o la organización."},{"consecutivo":7,"texto":"Desarrollar, establecer y gestionar los presupuestos, las políticas y los procedimientos de almacenamiento e inventario para cumplir las previsiones de abastecimiento y el control de niveles de existencias, controlar los costos y los gastos para garantizar el uso eficiente de los recursos."},{"consecutivo":8,"texto":"Establecer, desarrollar y dirigir programas, informes y procedimientos operativos y administrativos de almacenamiento e inventario para cumplir las previsiones de abastecimiento y el control de niveles de existencias, según modelos de gestión y protocolo de seguimiento del departamento, la empresa o la organización."},{"consecutivo":9,"texto":"Planear, dirigir y supervisar la selección, la formación, el entrenamiento y el rendimiento del personal según políticas de la organización."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"13244.001","nombre":"Administrador de bodega / Administradora de bodega"},{"codigo":"13244.002","nombre":"Director de abastecimiento y distribución / Directora de abastecimiento y distribución"},{"codigo":"13244.003","nombre":"Director de cadena de suministros / Directora de cadena de suministros"},{"codigo":"13244.004","nombre":"Director de departamento de almacenamiento / Directora de departamento de almacenamiento"},{"codigo":"13244.005","nombre":"Director de departamento de recursos físicos / Directora de departamento de recursos físicos"},{"codigo":"13244.006","nombre":"Director de operaciones cadena de suministros / Directora de operaciones cadena de suministros"},{"codigo":"13244.007","nombre":"Gerente de cadena de suministros / Gerenta de cadena de suministros"},{"codigo":"13244.008","nombre":"Gerente de departamento de logística y distribución / Gerenta de departamento de logística y distribución"},{"codigo":"13244.009","nombre":"Gerente de operaciones cadena de suministros / Gerenta de operaciones cadena de suministros"},{"codigo":"13244.010","nombre":"Gerente de supply chain / Gerenta de supply chain"},{"codigo":"13244.011","nombre":"Jefe de control de inventarios / Jefa de control de inventarios"},{"codigo":"13244.012","nombre":"Jefe de área de rotación y existencias / Jefa de área de rotación y existencias"},{"codigo":"13244.013","nombre":"Jefe de departamento de inventarios / Jefa de departamento de inventarios"},{"codigo":"13244.014","nombre":"Jefe de recursos físicos / Jefa de recursos físicos"},{"codigo":"13244.015","nombre":"Jefe de sección de bodega producto terminado / Jefa de sección de bodega producto terminado"},{"codigo":"13244.016","nombre":"Jefe de sección de materiales y suministros / Jefa de sección de materiales y suministros"},{"codigo":"13244.017","nombre":"Jefe de sección de suministros / Jefa de sección de suministros"},{"codigo":"13244.018","nombre":"Jefe de inventarios / Jefa de inventarios"},{"codigo":"13244.019","nombre":"Jefe de rotación y existencias / Jefa de rotación y existencias"}],"conocimientos":[{"id":"100","nombre":