  ('rol_cuoc', 'Directores y gerentes de telecomunicaciones / Directoras y gerentas de telecomunicaciones', '13301', 'Administración, finanzas y derecho', 4, false, '{"codigo":"13301","nombre":"Directores y gerentes de telecomunicaciones / Directoras y gerentas de telecomunicaciones","descripcion":"Planean, dirigen y coordinan las políticas, planes, programas, mantenimiento y utilización de telecomunicaciones para cumplir objetivos y metas propuestas, ya sea como director de un departamento o como el gerente general de una empresa u organización que no tiene una estructura jerarquizada de directivos. Se pueden desempeñar en empresas prestadoras de servicios, operadoras o todas aquellas que requieran infraestructura de telecomunicaciones, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"1","nombre":"DIRECTORES Y GERENTES"},"subgrupo_principal":{"codigo":"13","nombre":"DIRECTORES Y GERENTES EN SECTORES DE PRODUCCIÓN Y SERVICIOS"},"subgrupo":{"codigo":"133","nombre":"Directores de servicios de tecnología de la información y las comunicaciones"},"grupo_primario":{"codigo":"1330","nombre":"Directores de servicios de tecnología de la información y las comunicaciones"}},"funciones":[{"consecutivo":1,"texto":"Formular, dirigir, planear, evaluar y controlar las estrategias, los proyectos, las políticas y los planes de empresas, departamentos o instalaciones de telecomunicaciones."},{"consecutivo":2,"texto":"Consultar con los directivos, gerentes, vendedores, técnicos y usuarios para evaluar las instalaciones, los servicios de operación, mantenimiento, necesidades informáticas y determinar los recursos tecnológicos que hacen falta para satisfacer las necesidades y formular las recomendaciones para mejorar el servicio de acuerdo con los protocolos y niveles de servicio."},{"consecutivo":3,"texto":"Dirigir y controlar las operaciones y las instalaciones de los recursos de telecomunicaciones, analizar el flujo de trabajo, elaborar y establecer normas, prioridades, plazos y suministrar capacitación para el usuario, a través de supervisores y personal técnico."},{"consecutivo":4,"texto":"Desarrollar, establecer y gestionar los presupuestos y las políticas; controlar los costos y los gastos para garantizar el uso eficiente de los recursos según protocolos de empresas, departamentos o instalaciones de telecomunicaciones."},{"consecutivo":5,"texto":"Establecer y dirigir los procedimientos operativos y administrativos según modelos de gestión y protocolo de seguimiento del departamento, empresa u organización."},{"consecutivo":6,"texto":"Planear, dirigir y supervisar la formación, el entrenamiento, el rendimiento, la selección y la contratación del personal de acuerdo con políticas y normativa de la empresa o el departamento."},{"consecutivo":7,"texto":"Garantizar el cumplimiento de normativa en telecomunicaciones conforme a las agencias reguladoras y directrices gubernamentales."},{"consecutivo":8,"texto":"Coordinar con directivos de empresas relacionadas para resolver problemas conjuntos y asegurar la eficiencia de operaciones del sistema de telecomunicación."},{"consecutivo":9,"texto":"Representar a la organización, el departamento o delegar en representantes para que actúe en nombre de ella en negociaciones, convenciones, seminarios, audiencias públicas, medios de comunicación, foros u otras funciones oficiales."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"13301.001","nombre":"Gerente de aplicaciones / Gerenta de aplicaciones"},{"codigo":"13301.002","nombre":"Gerente de empresa servicios telecomunicaciones / Gerenta de empresa servicios telecomunicaciones"},{"codigo":"13301.003","nombre":"Gerente de operaciones de telecomunicaciones / Gerenta de operaciones de telecomunicaciones"},{"codigo":"13301.004","nombre":"Gerente de servicios de operación y transmisión de telecomunicaciones / Gerenta de servicios de operación y transmisión de telecomunicaciones"},{"codigo":"13301.005","nombre":"Gerente de servicios de telecomunicaciones / Gerenta de servicios de telecomunicaciones"},{"codigo":"13301.006","nombre":"Gerente de telecomunicaciones / Gerenta de telecomunicaciones"},{"codigo":"13301.007","nombre":"Gerente de instalaciones de telecomunicaciones / Gerenta de instalaciones de telecomunicaciones"},{"codigo":"13301.008","nombre":"Gerente de sistema de telecomunicaciones / Gerenta de sistema de telecomunicaciones"},{"codigo":"13301.009","nombre":"Jefe de departamento de operaciones de servicios de telecomunicaciones / Jefa de departamento de operaciones de servicios de telecomunicaciones"},{"codigo":"13301.010","nombre":"Jefe de departamento de operaciones de telecomunicaciones / Jefa de departamento de operaciones de telecomunicaciones"},{"codigo":"13301.011","nombre":"Jefe de departamento de telecomunicaciones / Jefa de departamento de telecomunicaciones"},{"codigo":"13301.012","nombre":"Jefe de servicios de telecomunicaciones / Jefa de servicios de telecomunicaciones"}],"conocimientos":[{"id":"63","nombre":"Desarrollo y análisis de software y aplicaciones"},{"id":"1","nombre":"Gerencia y administración"},{"id":"10","nombre":"Ingeniería y tecnología"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"29","nombre":"Telecomunicación"}],"destrezas":[{"id":"17","nombre":"Análisis de necesidades"},{"id":"1","nombre":"Comprensión de lectura"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"16","nombre":"Resolución de problemas complejos"},{"id":"14","nombre":"Transmisión de conocimiento"},{"id":"23","nombre":"Vigilancia de las operaciones"}],"ocupaciones_afines":[{"codigo":"11200","nombre":"Directores y gerentes generales / Directoras y gerentas generales"},{"codigo":"13303","nombre":"Directores y gerentes de comunicaciones y audiovisuales / Directoras y gerentas de comunicaciones y audiovisuales"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"1330*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"0131","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Directores y gerentes de sistemas de información y procesamiento de datos / Directoras y gerentas de sistemas de información y procesamiento de datos', '13302', 'Administración, finanzas y derecho', 4, false, '{"codigo":"13302","nombre":"Directores y gerentes de sistemas de información y procesamiento de datos / Directoras y gerentas de sistemas de información y procesamiento de datos","descripcion":"Planean, dirigen y coordinan los recursos y actividades de sistemas de información; formulan y definen estrategias para cumplir objetivos y metas propuestas; ya sea como director de un departamento o como el gerente general de una empresa u organización que no tiene una estructura jerarquizada de directivos. Se pueden desempeñar en departamentos y empresas de procesamiento electrónico de datos, servicios de BPO, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"1","nombre":"DIRECTORES Y GERENTES"},"subgrupo_principal":{"codigo":"13","nombre":"DIRECTORES Y GERENTES EN SECTORES DE PRODUCCIÓN Y SERVICIOS"},"subgrupo":{"codigo":"133","nombre":"Directores de servicios de tecnología de la información y las comunicaciones"},"grupo_primario":{"codigo":"1330","nombre":"Directores de servicios de tecnología de la información y las comunicaciones"}},"funciones":[{"consecutivo":1,"texto":"Planear, elaborar, analizar y dirigir las operaciones de sistemas de información, prioridades y plazos de entrega, flujo de trabajo y procesamiento electrónico en departamentos y empresas."},{"consecutivo":2,"texto":"Establecer y dirigir los procedimientos operativos y administrativos para el procesamiento electrónico de información y el desarrollo de sistemas computarizados, según modelos de gestión y protocolo de seguimiento del departamento, la empresa o la organización."},{"consecutivo":3,"texto":"Consultar con los directivos, gerentes, vendedores, técnicos y usuarios para evaluar los sistemas de información y procesamiento de datos, necesidades informáticas y determinar los recursos tecnológicos que hacen falta para satisfacer necesidades; formular las recomendaciones para mejorar el servicio de acuerdo con los protocolos y los niveles de servicio."},{"consecutivo":4,"texto":"Analizar requerimientos y ejecución de la información para desarrollar e implementar nuevos sistemas o modificaciones a los existentes."},{"consecutivo":5,"texto":"Desarrollar, establecer y gestionar los presupuestos y las políticas; controlar los costos y gastos en los sistemas de información y procesamiento de datos para garantizar el uso eficiente de los recursos, según protocolos de empresas o departamentos."},{"consecutivo":6,"texto":"Dirigir y supervisar la selección, la formación, el entrenamiento, el desarrollo profesional y el rendimiento del personal, según políticas de la organización."},{"consecutivo":7,"texto":"Evaluar el uso de recursos tecnológicos y las necesidades en la organización y recomendar mejoras, tales como hardware y actualizaciones de software."},{"consecutivo":8,"texto":"Formular, planear, evaluar y controlar las estrategias, la seguridad, los riesgos, los proyectos, las políticas y los planes de sistemas de información y procesamiento de datos de empresas o departamentos."},{"consecutivo":9,"texto":"Coordinar el trabajo de departamentos o divisiones regionales según modelos de gestión y protocolo de seguimiento del departamento, empresa u organización."},{"consecutivo":10,"texto":"Asignar, gestionar, verificar y dirigir el trabajo de los analistas de sistemas, programadores y otros profesionales relacionados con la informática de acuerdo con el protocolo y las políticas del departamento, empresa u organización."},{"consecutivo":11,"texto":"Representar a la empresa u organización o delegar un representante en congresos, seminarios, conferencias otras funciones relacionados con los sistemas de información y procesamiento de datos."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"13302.001","nombre":"Director de departamento de informática / Directora de departamento de informática"},{"codigo":"13302.002","nombre":"Director de departamento de sistemas informáticos / Directora de departamento de sistemas informáticos"},{"codigo":"13302.003","nombre":"Director de desarrollo de aplicaciones / Directora de desarrollo de aplicaciones"},{"codigo":"13302.004","nombre":"Director de desarrollo de TIC (tecnologías de la información y las comunicaciones) / Directora de desarrollo de TIC (tecnologías de la información y las comunicaciones)"},{"codigo":"13302.005","nombre":"Director de informática / Directora de informática"},{"codigo":"13302.006","nombre":"Director de procesamiento de datos / Directora de procesamiento de datos"},{"codigo":"13302.007","nombre":"Director de sistemas de información / Directora de sistemas de información"},{"codigo":"13302.008","nombre":"Director de tecnología de la información / Directora de tecnología de la información"},{"codigo":"13302.009","nombre":"Director de seguridad informática / Directora de seguridad informática"},{"codigo":"13302.010","nombre":"Director de sistemas informáticos / Directora de sistemas informáticos"},{"codigo":"13302.011","nombre":"Gerente de departamento de informática / Gerenta de departamento de informática"},{"codigo":"13302.012","nombre":"Gerente de departamento de internet / Gerenta de departamento de internet"},{"codigo":"13302.013","nombre":"Gerente de departamento de servicios informáticos / Gerenta de departamento de servicios informáticos"},{"codigo":"13302.014","nombre":"Gerente de empresa de servicios informáticos / Gerenta de empresa de servicios informáticos"},{"codigo":"13302.015","nombre":"Gerente de operaciones de datos / Gerenta de operaciones de datos"},{"codigo":"13302.016","nombre":"Gerente de sistemas informáticos / Gerenta de sistemas informáticos"},{"codigo":"13302.017","nombre":"Gerente proveedor de servicios de internet / Gerenta proveedora de servicios de internet