  ('rol_cuoc', 'Gerentes y administradores de servicios de alimentos y restaurantes / Gerentas y administradoras de servicios de alimentos y restaurantes', '14120', 'Administración, finanzas y derecho', 3, false, '{"codigo":"14120","nombre":"Gerentes y administradores de servicios de alimentos y restaurantes / Gerentas y administradoras de servicios de alimentos y restaurantes","descripcion":"Planean, organizan, dirigen y supervisan actividades de establecimientos que ofrecen servicios de alimentos y bebidas; coordinan actividades del personal y cumplen con las normas sanitarias y de higiene. Se pueden desempeñar en establecimientos de servicio de alimentos y bebidas, restaurantes, hospitales, hoteles, clubes, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"1","nombre":"DIRECTORES Y GERENTES"},"subgrupo_principal":{"codigo":"14","nombre":"GERENTES DE HOTELES, RESTAURANTES, COMERCIOS Y OTROS SERVICIOS"},"subgrupo":{"codigo":"141","nombre":"Gerentes de hoteles y restaurantes"},"grupo_primario":{"codigo":"1412","nombre":"Gerentes y administradores de servicios de alimentos y restaurantes"}},"funciones":[{"consecutivo":1,"texto":"Planear, organizar, dirigir y controlar las operaciones y los procedimientos de establecimientos de servicios de alimentos de acuerdo normativa."},{"consecutivo":2,"texto":"Planear, disponer y entregar los menús en consulta con los chefs, cocineros y dietistas."},{"consecutivo":3,"texto":"Mantener y controlar el inventario, el almacenamiento y la distribución de suministros y provisiones para el servicio de alimentos."},{"consecutivo":4,"texto":"Planear, organizar y dirigir eventos especiales de acuerdo con servicio contratado."},{"consecutivo":5,"texto":"Establecer, desarrollar y gestionar los presupuestos, las políticas y los procedimientos de compra, precio de los productos, las transacciones financieras; controlar los gastos y garantizar el uso eficiente de los recursos."},{"consecutivo":6,"texto":"Asegurar que las instalaciones de comedor, cocina y almacenamiento de alimentos cumplan con las normas sanitarias y de higiene, sean funcionales y de apariencia adecuada."},{"consecutivo":7,"texto":"Asegurar el cumplimiento de los reglamentos sobre salud ocupacional y seguridad."},{"consecutivo":8,"texto":"Negociar con proveedores el suministro de alimentos y bebidas."},{"consecutivo":9,"texto":"Negociar con clientes los servicios, la atención o uso de instalaciones para banquetes o recepciones."},{"consecutivo":10,"texto":"Verificar que los alimentos y el servicio cumplan los requisitos de control de calidad."},{"consecutivo":11,"texto":"Tomar y atender reservas, órdenes, sugerencias y consultas de clientes, evaluar su satisfacción con el servicio prestado."},{"consecutivo":12,"texto":"Supervisar y verificar los menús, las dietas especiales y la distribución de alimentos a pacientes en hospitales elaborados por los dietistas."},{"consecutivo":13,"texto":"Coordinar, programar y supervisar el cumplimiento de las actividades y los horarios del personal de servicio de alimentos ."},{"consecutivo":14,"texto":"Planear, dirigir y supervisar la formación, el entrenamiento, el rendimiento, la selección y la contratación del personal, hacer que se cumplan las normas de higiene y seguridad, según normativa y políticas de servicio y cocina."},{"consecutivo":15,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"14120.001","nombre":"Administrador de bar / Administradora de bar"},{"codigo":"14120.002","nombre":"Administrador de café / Administradora de café"},{"codigo":"14120.003","nombre":"Administrador de cafetería / Administradora de cafetería"},{"codigo":"14120.004","nombre":"Administrador de restaurante / Administradora de restaurante"},{"codigo":"14120.005","nombre":"Gerente de casa de banquetes / Gerenta de casa de banquetes"},{"codigo":"14120.006","nombre":"Gerente de bar / Gerenta de bar"},{"codigo":"14120.007","nombre":"Gerente de café / Gerenta de café"},{"codigo":"1