  ('rol_cuoc', 'Directores y gerentes de recreación, actividad física y deportes / Directoras y gerentes de recreación, actividad física y deportes', '14312', 'Administración, finanzas y derecho', 3, false, '{"codigo":"14312","nombre":"Directores y gerentes de recreación, actividad física y deportes / Directoras y gerentes de recreación, actividad física y deportes","descripcion":"Gerencian, administran y gestionan planes programas y proyectos en organizaciones públicas y privadas que ofertan productos y servicios asociados al deporte, recreación, actividad física y aprovechamiento del tiempo libre. Se pueden desempeñar en organizaciones deportivas estatales y privadas, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"1","nombre":"DIRECTORES Y GERENTES"},"subgrupo_principal":{"codigo":"14","nombre":"GERENTES DE HOTELES, RESTAURANTES, COMERCIOS Y OTROS SERVICIOS"},"subgrupo":{"codigo":"143","nombre":"Otros gerentes de servicios"},"grupo_primario":{"codigo":"1431","nombre":"Directores y gerentes de deportes, esparcimiento y cultura"}},"funciones":[{"consecutivo":1,"texto":"Planear, organizar, dirigir y controlar las operaciones, programas, eventos y servicios de recreación, deporte y acondicionamiento físico que ofrece el centro."},{"consecutivo":2,"texto":"Asesorar y promover los servicios disponibles, planes promocionales, estrategias de mercadeo y contratos de publicidad de eventos, espectáculos y actividades de recreación, deporte y acondicionamiento físico."},{"consecutivo":3,"texto":"Desarrollar, establecer y gestionar el presupuesto de programas deportivos, recreativos o de actividad física, controlar los gastos y garantizar el uso eficiente de los recursos según protocolos de gestión."},{"consecutivo":4,"texto":"Planear, dirigir y supervisar la formación, entrenamiento, rendimiento, selección y contratación del personal de acuerdo con políticas y normativa."},{"consecutivo":5,"texto":"Planear, dirigir e implementar políticas, programas, cronogramas y procedimientos para el personal ."},{"consecutivo":6,"texto":"Dirigir y gestionar campañas para conseguir fondos o patrocinio de organizaciones del sector público o privado para eventos de en materia de recreación, deporte y actividad física."},{"consecutivo":7,"texto":"Velar por el cumplimiento de los reglamentos en materia de seguridad y salud en materia de recreación, deporte y actividad física."},{"consecutivo":8,"texto":"Proveer asesoría técnica y profesional en materia de recreación, deporte y actividad física."},{"consecutivo":9,"texto":"Asegurar que las instalaciones se mantengan limpias y en buen estado para las de actividades de recreación, deporte y actividad física."},{"consecutivo":10,"texto":"Negociar contratos con proveedores el suministro de materiales, insumos, servicios, entre otros para la prestación del servicio."},{"consecutivo":11,"texto":"Atender, responder y resolver los problemas, sugerencias o reclamos de clientes."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"14312.001","nombre":"Administrador de centro vacacional / Administradora de centro vacacional"},{"codigo":"14312.002","nombre":"Administrador de gimnasio / Administradora de gimnasio"},{"codigo":"14312.003","nombre":"Administrador deportivo / Administradora deportiva"},{"codigo":"14312.004","nombre":"Director de centro de recreación / Directora de centro de recreación"},{"codigo":"14312.005","nombre":"Director de centro vacacional / Directora de centro vacacional"},{"codigo":"14312.006","nombre":"Director de departamento de actividades recreativas / Directora de departamento de actividades recreativas"},{"codigo":"14312.007","nombre":"Director de festival / Directora de festival"},{"codigo":"14312.008","nombre":"Director de operaciones de espectáculos / Directora de operaciones de espectáculos"},{"codigo":"14312.009","nombre":"Director de programa de actividad física / Directora de programa de actividad física"},{"codigo":"143