  ('rol_cuoc', 'Gerentes y administradores de propiedad horizontal / Gerentas y administradoras de propiedad horizontal', '14391', 'Administración, finanzas y derecho', 3, false, '{"codigo":"14391","nombre":"Gerentes y administradores de propiedad horizontal / Gerentas y administradoras de propiedad horizontal","descripcion":"Planifican, dirigen, representan y coordinan la prestación de servicios de administración y gestión de la propiedad horizontal, contratan y supervisan servicios de seguridad, mantenimiento, aseo, entre otros de acuerdo con normas técnicas y legales. Se pueden desempeñar empresas de administración de propiedad horizontal, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"1","nombre":"DIRECTORES Y GERENTES"},"subgrupo_principal":{"codigo":"14","nombre":"GERENTES DE HOTELES, RESTAURANTES, COMERCIOS Y OTROS SERVICIOS"},"subgrupo":{"codigo":"143","nombre":"Otros gerentes de servicios"},"grupo_primario":{"codigo":"1439","nombre":"Otros gerentes y administradores de servicios no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Planear, organizar, dirigir e implementar programas para la administración de la propiedad horizontal de acuerdo con normas técnicas y legales."},{"consecutivo":2,"texto":"Contratar, dirigir y controlar los servicios para la administración y la operación de la propiedad horizontal de acuerdo con normas técnicas y legales, tales como seguridad, mantenimiento, aseo, entre otros."},{"consecutivo":3,"texto":"Gestionar y supervisar los servicios de la propiedad horizontal aspectos administrativos como seguridad, mantenimiento, aseo, entre otros de acuerdo con normas técnicas y legales."},{"consecutivo":4,"texto":"Recaudar cuota de administración de acuerdo con normativa legal."},{"consecutivo":5,"texto":"Organizar y liderar reuniones administrativas y actividades de la copropiedad de acuerdo con procedimientos organizacionales."},{"consecutivo":6,"texto":"Atender, responder y resolver los problemas, las sugerencias o reclamos de clientes de acuerdo con protocolos de servicio."},{"consecutivo":7,"texto":"Controlar inventarios de la copropiedad de acuerdo con procedimientos técnicos."},{"consecutivo":8,"texto":"Desarrollar, establecer y gestionar los presupuestos de mantenimiento y la operación de la propiedad horizontal, controlar los gastos, garantizar el uso eficiente de los recursos."},{"consecutivo":9,"texto":"Representar legalmente a la propiedad horizontal o delegar en representantes para que actúe en nombre de ella en funciones oficiales de acuerdo con la normatividad técnica y legal."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"14391.001","nombre":"Administrador de bienes inmuebles / Administradora de bienes inmuebles"},{"codigo":"14391.002","nombre":"Administrador de condominio / Administradora de condominio"},{"codigo":"14391.003","nombre":"Administrador de conjunto residencial / Administradora de conjunto residencial"},{"codigo":"14391.004","nombre":"Administrador de copropiedad mixta / Administradora de copropiedad mixta"},{"codigo":"14391.005","nombre":"Administrador de inmuebles / Administradora de inmuebles"},{"codigo":"14391.006","nombre":"Administrador de propiedad horizontal / Administradora de propiedad horizontal"},{"codigo":"14391.007","nombre":"Administrador de edificio / Administradora de edificio"},{"codigo":"14391.008","nombre":"Gerente de condominio / Gerenta de condominio"},{"codigo":"14391.009","nombre":"Gerente de conjunto residencial / Gerenta de conjunto residencial"},{"codigo":"14391.010","nombre":"Gerente de copropiedad / Gerenta de copropiedad"},{"codigo":"14391.011","nombre":"Gerente de edificio / Gerenta de edificio"},{"codigo":"14391.012","nombre":"Gerente de propiedad horizontal / Gerenta de propiedad horizontal"},{"codigo":"14391.013","nombre":"Gestor de propiedades horizontal / Gestora de propiedades horizontal"}],"conocimientos":[{"id":"32","nombre":"Contabilidad e impuestos"},{"id":"1","nombre":"Gerencia y administración"},{"id":"6","nombre":"Gestión del talento humano y de personal"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"85","nombre":"Seguridad y salud en el trabajo"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"13","nombre":"Conciliación"},{"id":"2","nombre":"Escucha activa"},{"id":"33","nombre":"Liderazgo"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"15","nombre":"Orientación al servicio"},{"id":"6","nombre":"Pensamiento crítico"}],"ocupaciones_afines":[{"codigo":"33340","nombre":"Agentes inmobiliarios / Agentes inmobiliarias"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"1439*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"1222","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Otros gerentes y administradores de servicios no clasificados en otras ocupaciones / Otras gerentas y administradoras de servicios no clasificados en otras ocupaciones', '14399', 'Administración, finanzas y derecho', 3, false, '{"codigo":"14399","nombre":"Otros gerentes y administradores de servicios no clasificados en otras ocupaciones / Otras gerentas y administradoras de servicios no clasificados en otras ocupaciones","descripcion":"Esta ocupación abarca a otros gerentes de servicios del Grupo Primario 1439: Otros gerentes y administradores de servicios no clasificados en otras ocupaciones. Por ejemplo, incluye aquellos que planean, organizan, dirigen y controlan las actividades de establecimientos que proveen servicios no clasificados anteriormente como son los gerentes de agencias de viajes, centros de conferencias, gerente escuela de conducción, centros de contacto y centros comerciales. Se pueden desempeñar en empresas de aeropuertos, puertos, centros comerciales, de convenciones, escuelas de conducción, modelaje, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"1","nombre":"DIRECTORES Y GERENTES"},"subgrupo_principal":{"codigo":"14","nombre":"GERENTES DE HOTELES, RESTAURANTES, COMERCIOS Y OTROS SERVICIOS"},"subgrupo":{"codigo":"143","nombre":"Otros gerentes de servicios"},"grupo_primario":{"codigo":"1439","nombre":"Otros gerentes y administradores de servicios no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Planear, organizar, dirigir y controlar las operaciones de intermediación, comercialización, organización y realización de proyectos, planes e itinerarios, diseño y venta de productos turísticos."},{"consecutivo":2,"texto":"Planear, organizar, dirigir y controlar las actividades en establecimientos que prestan servicio de educación no formal como escuelas modelaje, conducción, entre otras."},{"consecutivo":3,"texto":"Planear, organizar, dirigir y controlar las operaciones y los servicios administrativos de espacios en las instalaciones con el propósito de juntar asambleas, conferencias, seminarios o agrupaciones de diferentes caracteres, sea comercial, empresarial, científico o religioso."},{"consecutivo":4,"texto":"Desarrollar e implementar estrategias de mercadeo para publicitar los productos y los servicios del establecimiento, innovaciones de productos, determinar demanda del consumidor, volúmenes potenciales de ventas y comportamiento de la competencia en ventas."},{"consecutivo":5,"texto":"Desarrollar, establecer y gestionar los presupuestos de mantenimiento y la operación del establecimiento, controlar los gastos para garantizar el uso eficiente de los recursos."},{"consecutivo":6,"texto":"Preparar los informes y las estadísticas relacionadas con las áreas que estén bajo su responsabilidad."},{"consecutivo":7,"texto":"Atender las sugerencias o los reclamos de clientes y resolver problemas."},{"consecutivo":8,"texto":"Planear, dirigir y supervisar la formación, el entrenamiento, la programación, el rendimiento, la selección y la contratación del personal según normativa y políticas del establecimiento."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"14399.001","nombre":"Gerente de agencia de viajes / Gerenta de agencia de viajes"},{"codigo":"14399.002","nombre":"Gerente de camping / Gerenta de camping"},{"codigo":"14399.003","nombre":"Gerente de camping para autocaravanas / Gerenta de camping para autocaravanas"},{"codigo":"14399.004","nombre":"Gerente de centro de conferencias / Gerenta de centro de conferencias"},{"codigo":"14399.005","nombre":"Gerente de centro de contactos / Gerenta de centro de contactos"},{"codigo":"14399.006","nombre":"Gerente de centro de convenciones / Gerenta de centro de convenciones"},{"codigo":"14399.007","nombre":"Gerente de servicios personales / Gerenta de servicios personales"},{"codigo":"14399.008","nombre":"Gerente de escuela de conducción / Gerenta de escuela de conducción"},{"codigo":"14399.009","nombre":"Gerente de escuela de modelaje / Gerenta de escuela de modelaje"},{"codigo":"14399.010","nombre":"Gerente de servicios de aseo y limpieza / Gerenta de servicios de aseo y limpieza"},{"codigo":"14399.011","nombre":"Jefe de agencia de viajes / Jefa de agencia de viajes"},{"codigo":"14399.012","nombre":"Administrador de agencia webcam  / Administradora de agencia webcam"},{"codigo":"14399.013","nombre":"Administrador de Parqueadero  / Administradora de Parqueadero"},{"codigo":"14399.014","nombre":"Gerente de servicio al cliente de comercio al por menor / Gerenta de servicio al cliente de comercio al por menor"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"1","nombre":"Gerencia y administración"},{"id":"6","nombre":"Gestión del talento humano y de personal"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"33","nombre":"Liderazgo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"16","nombre":"Resolución de problemas complejos"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"33320","nombre":"Coordinadores y productores de conferencias, eventos y espectáculos / Coordinadoras y productoras de conferencias, eventos y espectáculos"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[{"sigla":"EDFO","nombre":"Educación y formación"},{"sigla":"SEPC","nombre":"Servicios Personales y a la Comunidad"},{"sigla":"TUHG","nombre":"Turismo, hotelería y gastronomía"}],"equivalencias":[{"ciuo08_codigo":"1439*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"0621*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"0651*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"0821*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Físicos y astrónomos / Físicas y astrónomas', '21110', 'Ciencias naturales, matemáticas y estadística', 4, false, '{"codigo":"21110","nombre":"Físicos y astrónomos / Físicas y astrónomas","descripcion":"Dirigen, realizan investigaciones teóricas y aplicadas, desarrollan conceptos, instrumentos, software y métodos operacionales relativos a la materia, espacio, tiempo, energía, fuerzas y campos, y la interrelación entre estos fenómenos físicos en actividades como: la electrónica, las comunicaciones, la generación y la distribución de energía, aerodinámica, óptica, rayos láser, medicina y salud, y la astronomía. Se pueden desempeñar en empresas de fabricación eléctrica, electrónica, universidades, compañías de telecomunicaciones, laboratorios, firmas consultoras y de investigación científica, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"21","nombre":"PROFESIONALES DE LAS CIENCIAS Y DE LA INGENIERÍA"},"subgrupo":{"codigo":"211","nombre":"Físicos, químicos y afines"},"grupo_primario":{"codigo":"2111","nombre":"Físicos y astrónomos"}},"funciones":[{"consecutivo":1,"texto":"Diseñar, dirigir y evaluar investigaciones en la física teórica y experimental formulando conclusiones."},{"consecutivo":2,"texto":"Asesorar y consultar con los médicos y otros profesionales de la salud para la optimización del balance entre los efectos beneficiosos y nocivos de las radiaciones."},{"consecutivo":3,"texto":"Elaborar protocolos técnicos especializados para la exposición segura y efectiva de pacientes en las aplicaciones médicas de radiaciones (ionizantes o no-ionizantes) en resultados diagnósticos o terapéuticos, que han sido prescritos por el médico. Evaluando equipos utilizados en aplicaciones como imágenes, tratamientos médicos y dosimetría."},{"consecutivo":4,"texto":"Desarrollar, implementar y mantener normas y protocolos para la medición de los fenómenos físicos y para la utilización de tecnología nuclear en aplicaciones industriales y médicas."},{"consecutivo":5,"texto":"Realizar experimentos, pruebas y análisis sobre la estructura y las propiedades de la materia en campos como la mecánica, la termodinámica, la electrónica, las comunicaciones, la generación y la distribución de energía, aerodinámica, óptica y láser, sensores remotos, medicina, acústica, magnetismo, física nuclear, astronomía, entre otros."},{"consecutivo":6,"texto":"Investigar la naturaleza y el comportamiento de los electrones, que incrementen el conocimiento científico para el diseño, la creación y el perfeccionamiento de aparatos electrónicos utilizados en las comunicaciones y la industria en general incluyendo la armamentista."},{"consecutivo":7,"texto":"Desarrollar o mejorar las aplicaciones prácticas de los principios, los procesos y las técnicas de física o astronomía en las actividades industriales, médicas, militares y de otra índole."},{"consecutivo":8,"texto":"Investigar, observar, analizar e interpretar fenómenos celestes y desarrollar métodos, modelos numéricos y técnicas para aplicar y ampliar los conocimientos de campos como: navegación aérea y marítima, comunicación vía satélite, exploración espacial, cuerpos celestes y radiación cósmica."},{"consecutivo":9,"texto":"Diseñar, crear y/o participar en el desarrollo de software o instrumentos para la investigación y el análisis de la física y la astronomía."},{"consecutivo":10,"texto":"Participar como miembro de un equipo de investigación o desarrollo en el diseño de equipos médicos, industriales y experimentales, procedimientos e instrumentación."},{"consecutivo":11,"texto":"Preparar ponencias, análisis e informes de carácter científico."},{"consecutivo":12,"texto":"Analizar, documentar y tomar las acciones correspondientes de los resultados de ensayos, calibraciones, verificaciones, calificaciones y las mediciones presentadas según técnicas de aseguramiento metrológico."},{"consecutivo":13,"texto":"Realizar auditorías para asegurar la calidad de las mediciones, según normativa técnica y procedimientos establecidos."},{"consecutivo":14,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"21110.001","nombre":"Astrofísico / Astrofísica"},{"codigo":"21110.002","nombre":"Astrónomo / Astrónoma"},{"codigo":"21110.003","nombre":"Astrónomo de radio / Astrónoma de radio"},{"codigo":"21110.004","nombre":"Balístico / Balística"},{"codigo":"21110.005","nombre":"Científico investigador de física / Científica investigadora de física"},{"codigo":"21110.006","nombre":"Experto en aerodinámica / Experta en aerodinámica"},{"codigo":"21110.007","nombre":"Físico / Física"},{"codigo":"21110.008","nombre":"Físico astrónomo / Física astrónoma"},{"codigo":"21110.009","nombre":"Físico atmosférico / Física atmosférica"},{"codigo":"21110.010","nombre":"Físico en acústica / Física en acústica"},{"codigo":"21110.011","nombre":"Físico en aerodinámica / Física en aerodinámica"},{"codigo":"21110.012","nombre":"Físico en balística / Física en balística"},{"codigo":"21110.013","nombre":"Físico en electricidad y magnetismo / Física en electricidad y magnetismo"},{"codigo":"21110.014","nombre":"Físico en electrónica / Física en electrónica"},{"codigo":"21110.015","nombre":"Físico en estática / Física en estática"},{"codigo":"21110.016","nombre":"Físico en mecánica / Física en mecánica"},{"codigo":"21110.017","nombre":"Físico en óptica / Física en óptica"},{"codigo":"21110.018","nombre":"Físico en reología / Física en reología"},{"codigo":"21110.019","nombre":"Físico en sólidos / Física en sólidos"},{"codigo":"21110.020","nombre":"Físico en térmica / Física en térmica"},{"codigo":"21110.021","nombre":"Físico en termodinámica / Física en termodinámica"},{"codigo":"21110.022","nombre":"Físico en física teórica / Física en física teórica"},{"codigo":"21110.023","nombre":"Físico de estado sólido / Física de estado sólido"},{"codigo":"21110.024","nombre":"Físico experimental / Física experimental"},{"codigo":"21110.025","nombre":"Físico molecular / Física molecular"},{"codigo":"21110.026","nombre":"Físico nuclear / Física nuclear"},{"codigo":"21110.027","nombre":"Hidrodinámico / Hidrodinámica"},{"codigo":"21110.028","nombre":"Investigador de física / Investigadora de física"},{"codigo":"21110.029","nombre":"Radioastrónomo / Radioastrónoma"},{"codigo":"21110.030","nombre":"Reologista"},{"codigo":"21110.031","nombre":"Reólogo / Reóloga"},{"codigo":"21110.032","nombre":"Termodinamicista"},{"codigo":"21110.033","nombre":"Físico clínico / Física clínica"},{"codigo":"21110.034","nombre":"Físico médico / Física médica"},{"codigo":"21110.035","nombre":"Físico analista de laboratorio metrológico / Física analista de laboratorio metrológico"},{"codigo":"21110.036","nombre":"Físico gestor de calidad de laboratorio metrológico / Física gestora de calidad de laboratorio metrológico"}],"conocimientos":[{"id":"58","nombre":"Ciencias de la tierra"},{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"63","nombre":"Desarrollo y análisis de software y aplicaciones"},{"id":"11","nombre":"Diseño"},{"id":"22","nombre":"Educación y capacitación"},{"id":"15","nombre":"Física"},{"id":"34","nombre":"Herramientas de simulación y diseño"}],"destrezas":[{"id":"7","nombre":"Aprendizaje aplicado"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"5","nombre":"Lógica matemática"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"21","nombre":"Programación"},{"id":"16","nombre":"Resolución de problemas complejos"},{"id":"23","nombre":"Vigilancia de las operaciones"}],"ocupaciones_afines":[{"codigo":"12230","nombre":"Directores y gerentes de ingeniería, investigación y desarrollo / Directoras y gerentas de ingeniería, investigación y desarrollo"},{"codigo":"21120","nombre":"Meteorólogos / Meteorólogas"},{"codigo":"21130","nombre":"Químicos / Químicas"},{"codigo":"21310","nombre":"Biólogos, botánicos, zoólogos y afines / Biólogas, botánicas, zoólogas y afines"},{"codigo":"22120","nombre":"Médicos especialistas / Médicas especialistas"},{"codigo":"31199","nombre":"Técnicos en ciencias físicas y en ingeniería no clasificados en otras ocupaciones / Técnicas en ciencias físicas y en ingeniería no clasificados en otras ocupaciones"},{"codigo":"32111","nombre":"Técnicos y tecnólogos en imágenes diagnósticas / Técnicas y tecnólogas en imágenes diagnósticas"}],"area_principal":{"sigla":"CNME","nombre":"Ciencias naturales, matemáticas y estadística"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"2111","ciuo08_obs":"Denominaciones completas","cno_codigo":"","cno_obs":""}]}'::jsonb),
  ('rol_cuoc', 'Meteorólogos / Meteorólogas', '21120', 'Ciencias naturales, matemáticas y estadística', 4, false, '{"codigo":"21120","nombre":"Meteorólogos / Meteorólogas","descripcion":"Analizan, preparan pronósticos meteorológicos y dirigen investigaciones relacionadas con el estado del tiempo, los cambios y los fenómenos climáticos y atmosféricos en su composición, estructura y dinámica. Se pueden desempeñar en entidades del gobierno, empresas de aviación, instituciones meteorológicas, medios de comunicación, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"21","nombre":"PROFESIONALES DE LAS CIENCIAS Y DE LA INGENIERÍA"},"subgrupo":{"codigo":"211","nombre":"Físicos, químicos y afines"},"grupo_primario":{"codigo":"2112","nombre":"Meteorólogos"}},"funciones":[{"consecutivo":1,"texto":"Dirigir y realizar investigaciones en diferentes ramas de la meteorología teórica y aplicada sobre fenómenos climáticos y atmosféricos para perfeccionar o desarrollar conceptos, teorías, leyes y métodos operacionales relacionados con la composición, la estructura y la dinámica de la atmósfera, la temperatura, grados de humedad, transformación física y química de los contaminantes y otros fenómenos, tales como formación de nubes y precipitaciones, perturbaciones eléctricas o radiación solar."},{"consecutivo":2,"texto":"Asesorar y dirigir investigaciones sobre la acumulación, dispersión, transformación física y química en la atmósfera de programas de modificación del clima y de contaminantes, así como desarrollar y hacer modelos matemáticos para explicar estos sucesos."},{"consecutivo":3,"texto":"Analizar e interpretar datos obtenidos de las estaciones meteorológicas, imágenes de radar y satélite, modelos matemáticos e informáticos para uso experimental o práctico."},{"consecutivo":4,"texto":"Preparar y elaborar documentos, informes y presentaciones científicas con mapas meteorológicos, pronósticos y advertencias a corto o a largo plazo, relacionadas con los fenómenos atmosféricos como ciclones, tormentas y otras amenazas para la vida y los bienes."},{"consecutivo":5,"texto":"Trazar la cartografía climática, establecer las condiciones y el pronóstico del tiempo en la agricultura, la navegación aérea y marítima, las industrias forestales, entre otras."},{"consecutivo":6,"texto":"Difundir información sobre las condiciones atmosféricas a través de diversos medios de comunicación, incluyendo radio, televisión, medios impresos como artículos y textos populares para especialistas e internet."},{"consecutivo":7,"texto":"Observar, analizar y participar en estudios relativos a los efectos del tiempo y clima sobre el medio ambiente y el cuerpo humano."},{"consecutivo":8,"texto":"Analizar el impacto de los proyectos industriales y la actividad humana sobre el clima y la calidad del aire, trabajar con las comunidades de ciencias sociales, ingeniería y ciencias económicas para desarrollar estrategias apropiadas de mitigación."},{"consecutivo":9,"texto":"Asesorar a entidades, investigadores, profesionales y diferentes áreas relativas al control del medio ambiente, predicción meteorológica e interpretación de información climatológica."},{"consecutivo":10,"texto":"Participar en el diseño y desarrollo de nuevos equipos y procedimientos para la recopilación de datos meteorológicos y sensores remotos, o para aplicaciones relacionadas."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"21120.001","nombre":"Climatólogo / Climatóloga"},{"codigo":"21120.002","nombre":"Hidrometeorólogo / Hidrometeoróloga"},{"codigo":"21120.003","nombre":"Meteorólogo / Meteoróloga"},{"codigo":"21120.004","nombre":"Meteorólogo del tiempo / Meteoróloga del tiempo"},{"codigo":"21120.005","nombre":"Pronosticador del tiempo / Pronosticadora del tiempo"}],"conocimientos":[{"id":"58","nombre":"Ciencias de la tierra"},{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"69","nombre":"Estadística"},{"id":"15","nombre":"Física"},{"id":"20","nombre":"Geografía y territorio"},{"id":"74","nombre":"Ingeniería y procesos químicos"},{"id":"14","nombre":"Matemáticas"}],"destrezas":[{"id":"27","nombre":"Análisis de procesos"},{"id":"7","nombre":"Aprendizaje aplicado"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"3","nombre":"Redacción de textos"},{"id":"16","nombre":"Resolución de problemas complejos"},{"id":"23","nombre":"Vigilancia de las operaciones"}],"ocupaciones_afines":[{"codigo":"21110","nombre":"Físicos y astrónomos / Físicas y astrónomas"},{"codigo":"21310","nombre":"Biólogos, botánicos, zoólogos y afines / Biólogas, botánicas, zoólogas y afines"},{"codigo":"21331","nombre":"Profesionales ambientales y ecologistas"},{"codigo":"21430","nombre":"Ingenieros medioambientales / Ingenieras medioambientales"},{"codigo":"31113","nombre":"Técnicos en meteorología / Técnicas en meteorología"}],"area_principal":{"sigla":"CNME","nombre":"Ciencias naturales, matemáticas y estadística"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"2112","ciuo08_obs":"Denominaciones completas","cno_codigo":"2114","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Químicos / Químicas', '21130', 'Industria química', 4, false, '{"codigo":"21130","nombre":"Químicos / Químicas","descripcion":"Investigan, mejoran y/o desarrollan conceptos, teorías y métodos operacionales, aplican los conocimientos científicos relacionados con la química como apoyo a las operaciones industriales, innovación de nuevos compuestos químicos, materiales, productos o procesos, así como desarrollan e implementan el control de calidad de productos o procesos, el monitoreo y control del medio ambiente, y otras aplicaciones relacionadas con la química. Se pueden desempeñar en laboratorios de control de calidad, investigación y desarrollo, industrias químicas, petroquímicas, industrias y laboratorios de alimentos, industrias de procesamiento de metales, de minerales metálicos y no metálicos y otras empresas relacionadas, establecimientos del gobierno, servicios públicos, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"21","nombre":"PROFESIONALES DE LAS CIENCIAS Y DE LA INGENIERÍA"},"subgrupo":{"codigo":"211","nombre":"Físicos, químicos y afines"},"grupo_primario":{"codigo":"2113","nombre":"Químicos"}},"funciones":[{"consecutivo":1,"texto":"Coordinar, participar y evaluar técnica y científicamente investigaciones, innovación y desarrollo de conceptos, instrumentos, teorías, leyes, métodos y fórmulas químicas aplicadas a la industria, el medio ambiente, la salud, el manejo de desechos, entre otros."},{"consecutivo":2,"texto":"Apoyar en la investigación de aspectos de los mecanismos de acción de medicamentos, diagnóstico y tratamiento de enfermedades, funciones orgánicas y valoración de la salud."},{"consecutivo":3,"texto":"Diseñar fórmulas, métodos analíticos, métodos de fabricación de pruebas y análisis para la industria de alimentos, petroquímica, plásticos, caucho, minera, agroquímica, pulpa y papel, jabones, entre otros."},{"consecutivo":4,"texto":"Diseñar, coordinar y realizar experimentos, pruebas, ensayos, caracterizaciones y análisis de las composiciones químicas, bioquímicas, materiales, productos naturales y sintéticos, utilizando diferentes técnicas como la cromatografía, la espectroscopia, las técnicas de separación química y física, microscopia, entre otros."},{"consecutivo":5,"texto":"Estudiar, determinar, analizar, desarrollar, reproducir, diseñar, desarrollar y mejorar materias primas, sustancias existentes naturales y artificiales, nuevos productos como moléculas, materiales químicos, entre otros."},{"consecutivo":6,"texto":"Recoger y analizar muestras de tierra y agua, registrar las observaciones y el análisis de datos para el apoyo de geólogos o geofísicos."},{"consecutivo":7,"texto":"Preparar estimaciones detalladas de cantidades y costos de materiales y mano de obra necesarios para los proyectos, de acuerdo con las especificaciones establecidas."},{"consecutivo":8,"texto":"Participar en investigaciones multidisciplinarias y desarrollo de proyectos con ingenieros químicos, químicos farmacéuticos, biólogos, microbiólogos, agrónomos, geólogos y otros profesionales."},{"consecutivo":9,"texto":"Realizar consultoría técnica y asesorar sobre productos químicos y manejo de residuos peligrosos."},{"consecutivo":10,"texto":"Dirigir, monitorear y desarrollar procedimientos, parámetros y estándares de control de calidad de suministros de laboratorio, análisis de muestras, materias primas, agentes y productos químicos."},{"consecutivo":11,"texto":"Inspeccionar, auditar y supervisar procesos, análisis, laboratorios y productos químicos."},{"consecutivo":12,"texto":"Vigilar el mantenimiento y validación de equipos e instrumentos de laboratorio, la preparación de soluciones, reactivos y evaluar fórmulas."},{"consecutivo":13,"texto":"Dirigir estudios químicos y procedimientos de prueba de diferentes materiales en la industria metalmecánica, entre otros."},{"consecutivo":14,"texto":"Diseñar, dirigir y gestionar programas de control, recuperación medio ambiental y cuantificación de sustancias tóxicas del ambiente por medio de toma de muestras químicas, análisis de datos y métodos analíticos de medición de impacto ambiental."},{"consecutivo":15,"texto":"Realizar consultoría técnica en un campo particular de especialización de la química."},{"consecutivo":16,"texto":"Apoyar el desarrollo y análisis de patentes de sustancias, materiales, productos y procesos derivados de la química."},{"consecutivo":17,"texto":"Redactar y preparar ponencias e informes de carácter científico y técnico."},{"consecutivo":18,"texto":"Validar métodos de laboratorio y de investigación."},{"consecutivo":19,"texto":"Analizar, documentar y tomar las acciones correspondientes de los resultados de ensayos, calibraciones, verificaciones, calificaciones y las mediciones presentadas, según técnicas de aseguramiento metrológico."},{"consecutivo":20,"texto":"Realizar auditorías para asegurar la calidad de las mediciones, según normativa técnica y procedimientos establecidos."},{"consecutivo":21,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"21130.001","nombre":"Analista de control de calidad para laboratorio"},{"codigo":"21130.002","nombre":"Analista de riesgo químico"},{"codigo":"21130.003","nombre":"Analista químico / Analista química"},{"codigo":"21130.004","nombre":"Analista químico de suelos / Analista química de suelos"},{"codigo":"21130.005","nombre":"Analista químico profesional / Analista química profesional"},{"codigo":"21130.006","nombre":"Asesor químico / Asesora química"},{"codigo":"21130.007","nombre":"Científico investigador de química / Científica investigadora de química"},{"codigo":"21130.008","nombre":"Coordinador de investigación y desarrollo químico / Coordinadora de investigación y desarrollo químico"},{"codigo":"21130.009","nombre":"Coordinador profesional de laboratorio químico / Coordinadora profesional de laboratorio químico"},{"codigo":"2