  ('rol_cuoc', 'Oceanógrafos / Oceanógrafas', '21143', 'Ciencias naturales, matemáticas y estadística', 4, false, '{"codigo":"21143","nombre":"Oceanógrafos / Oceanógrafas","descripcion":"Identifican, analizan, evalúan y generan información de los procesos físicos, químicos, biológicos y geológicos del océano y su relación con la sociedad, las actividades marítimas, el medio ambiente, la atmósfera y zona costera a través de actividades científicas, administrativas, organizativas o asesoría experta. Se pueden desempeñar en firmas consultoras de medio ambiente, geofísicas y de ingeniería costera, marina, marítima, portuaria y fluvial, empresas de energía, ingeniería civil, petroleras y mineras, instituciones del gobierno, empresas de investigación, innovación y desarrollo, entre otros","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"21","nombre":"PROFESIONALES DE LAS CIENCIAS Y DE LA INGENIERÍA"},"subgrupo":{"codigo":"211","nombre":"Físicos, químicos y afines"},"grupo_primario":{"codigo":"2114","nombre":"Geólogos, geofísicos y geoquímicos"}},"funciones":[{"consecutivo":1,"texto":"Investigar, analizar y gestionar la conservación y uso sostenible del mar y sus recursos, zonas costeras y fluviomarinas según estándares y lineamientos de las autoridades marítima y ambiental."},{"consecutivo":2,"texto":"Realizar estudios e investigaciones de los procesos físicos, químicos, biológicos, geológicos y atmosféricos en el mar, zonas costera y fluviomarina, de acuerdo con estándares nacionales e internacionales."},{"consecutivo":3,"texto":"Asesorar científica y técnicamente en políticas referente a diseño de estrategias de economía azul, seguimiento de políticas y reglamentación marítima nacional e internacional."},{"consecutivo":4,"texto":"Gestionar estudios e investigaciones científicos en el mar y sus recursos, las zonas costeras y fluviomarinas para la gestión de amenazas y riesgos que contribuyan a la toma de decisiones en proyectos marino-costeros."},{"consecutivo":5,"texto":"Estudiar la factibilidad técnica para el desarrollo de terminales marítimos y fluviales en obras de ingeniería civil en la zona costera y marítima."},{"consecutivo":6,"texto":"Establecer las condiciones oceanográficas, hidrográficas y batimétricas presentes durante la ocurrencia de siniestros marinos como hundimientos o colisiones de buques, artefactos navales, entre si o con obras de infraestructuras en el mar o zona costera."},{"consecutivo":7,"texto":"Elaborar peritazgos en oceanografía e hidrografía según requerimiento de jueces, autoridad marítima y ambiental nacional o del sector privado."},{"consecutivo":8,"texto":"Analizar e interpretar datos oceanográficos procedentes de sistemas de medición oceanográfica y los resultados de los modelos numéricos de predicción oceanográfica."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"21143.001","nombre":"Ingeniero oceanográfico / Ingeniera oceanográfica"},{"codigo":"21143.002","nombre":"Ingeniero oceanólogo / Ingeniera oceanóloga"},{"codigo":"21143.003","nombre":"Oceanógrafo / Oceanógrafa"},{"codigo":"21143.004","nombre":"Oceanógrafo de geofísica / Oceanógrafa de geofísica"},{"codigo":"21143.005","nombre":"Oceanógrafo de geología / Oceanógrafa de geología"},{"codigo":"21143.006","nombre":"Oceanógrafo físico / Oceanógrafa física"},{"codigo":"21143.007","nombre":"Oceanógrafo geológico / Oceanógrafa geológica"},{"codigo":"21143.008","nombre":"Oceanógrafo químico / Oceanógrafa química"},{"codigo":"21143.009","nombre":"Oceanólogo / Oceanóloga"}],"conocimientos":[{"id":"59","nombre":"Ciencias del medio ambiente"},{"id":"15","nombre":"Física"},{"id":"20","nombre":"Geografía y territorio"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"14","nombre":"Matemáticas"},{"id":"102","nombre":"Metodología e investigación"},{"id":"16","nombre":"Química"}],"destrezas":[{"id":"27","nombre":"Análisis de procesos"},{"id":"39","nombre":"Creatividad"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"40","nombre":"Interpretación"},{"id":"5","nombre":"Lógica matemática"},{"id":"6","nombre":"Pensamiento crítico"}],"ocupaciones_afines":[{"codigo":"21141","nombre":"Geólogos, geofísicos y geoquímicos / Geólogas, geofísicas y geoquímicas"},{"codigo":"21650","nombre":"Cartógrafos e ingenieros topográficos y catastrales / Cartógrafas e ingenieras topográficas y catastrales"}],"area_principal":{"sigla":"CNME","nombre":"Ciencias naturales, matemáticas y estadística"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"2114*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"2113*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"2115","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Matemáticos, actuarios y estadísticos / Matemáticas, actuarias y estadísticas', '21200', 'Ciencias naturales, matemáticas y estadística', 4, false, '{"codigo":"21200","nombre":"Matemáticos, actuarios y estadísticos / Matemáticas, actuarias y estadísticas","descripcion":"Investigan, perfeccionan o desarrollan conceptos, teorías, métodos operacionales y técnicas matemáticas, actuariales y estadísticas; asesoran o participan en su aplicación práctica en campos como la analítica de datos de  información catastral, de ingeniería,  entre otros campos; actualizan y mejoran la metodología estadística relacionada con la recolección, organización, análisis e interpretación de datos expresados en forma alfanumérica, cuantitativa y espacial; aplican técnicas para resolver problemas en campos científicos; trabajan en su aplicación práctica o en el asesoramiento pertinente que  respaldan la toma de decisiones, aplican los conocimientos en matemáticas, estadística y asuntos financieros al establecimiento y gestión de sistemas de pensiones y de seguros de vida, enfermedad, accidentes y demás análisis de riesgo. Se pueden desempeñar en entidades y organizaciones nacionales, territoriales, universidades, bancos, fiduciarias, compañías de seguros, firmas consultoras y de ingeniería, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"21","nombre":"PROFESIONALES DE LAS CIENCIAS Y DE LA INGENIERÍA"},"subgrupo":{"codigo":"212","nombre":"Matemáticos, actuarios y estadísticos"},"grupo_primario":{"codigo":"2120","nombre":"Matemáticos, actuarios y estadísticos"}},"funciones":[{"consecutivo":1,"texto":"Estudiar, perfeccionar o desarrollar teorías y técnicas matemáticas, actuariales y estadísticas."},{"consecutivo":2,"texto":"Conducir investigaciones para ampliar los conocimientos en áreas tradicionales de las matemáticas como álgebra, geometría, probabilidad y lógica matemática y aplicar técnicas matemáticas para la solución de problemas en campos científicos como las ciencias físicas, la ingeniería, la informática y otros campos como la investigación de operaciones, el comercio y la administración."},{"consecutivo":3,"texto":"Asesorar y aplicar diversos métodos de recopilación de datos y otros métodos y técnicas estadísticas y determinar la confiabilidad de los resultados, especialmente en campos como los negocios o medicina, así como en otras áreas de las ciencias naturales, sociales o biológicas."},{"consecutivo":4,"texto":"Realizar análisis lógicos de problemas de gestión, especialmente en lo relativo a modelos eficientes de insumo-producto, y formular modelos matemáticos de cada problema, por lo general, para su programación y búsqueda de soluciones por computador."},{"consecutivo":5,"texto":"Analizar y aplicar datos y principios matemáticos y estadísticos, para establecer probabilidades relacionadas con mortalidad, accidentes, enfermedades, invalidez, desempleo y retiro."},{"consecutivo":6,"texto":"Dirigir el trabajo de asistentes y auxiliares matemáticos, actuariales y estadísticos y empleados estadísticos."},{"consecutivo":7,"texto":"Asesorar y aplicar principios, métodos, teorías, modelos y técnicas matemáticas y estadísticas para proveer información en una amplia gama de campos como en la ingeniería, las ciencias naturales, sociales, agricultura, ciencias económicas, físicas, biológicas, entre otros."},{"consecutivo":8,"texto":"Aplicar teoría matemática, estadística, probabilidad y riesgo para evaluar los posibles impactos financieros de contingencias futuras, riesgos asociados a seguros, regímenes de pensión, previsión social."},{"consecutivo":9,"texto":"Planificar y organizar censos, encuestas y otros medios de recopilación estadística y diseñar los cuestionarios."},{"consecutivo":10,"texto":"Proveer evidencias legales sobre el monto de futuros salarios, con aplicación de técnicas como las ya mencionadas."},{"consecutivo":11,"texto":"Evaluar, procesar, analizar e interpretar los datos estadísticos y prepararlos para su publicación."},{"consecutivo":12,"texto":"Diseñar y poner en funcionamiento sistemas de pensiones y de seguros de vida, de salud, de previsión social y otro tipo de sistemas de seguros."},{"consecutivo":13,"texto":"Preparar ponencias e informes de carácter académico o científico."},{"consecutivo":14,"texto":"Proponer modelo de analítica de datos de la información catastral para la administración del territorio teniendo en cuenta necesidades y requerimientos técnicos de los procesos de la gestión catastral."},{"consecutivo":15,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"21200.001","nombre":"Actuario / Actuaria"},{"codigo":"21200.002","nombre":"Analista de investigación de operaciones"},{"codigo":"21200.003","nombre":"Analista en estadística"},{"codigo":"21200.004","nombre":"Bioestadístico / Bioestadística"},{"codigo":"21200.005","nombre":"Biometrista"},{"codigo":"21200.006","nombre":"Demógrafo / Demógrafa"},{"codigo":"21200.007","nombre":"Estadígrafo / Estadígrafa"},{"codigo":"21200.008","nombre":"Estadígrafo de estadística aplicada / Estadígrafa de estadística aplicada"},{"codigo":"21200.009","nombre":"Estadístico / Estadística"},{"codigo":"21200.010","nombre":"Estadístico en agricultura / Estadística en agricultura"},{"codigo":"21200.011","nombre":"Estadístico en biometría / Estadística en biometría"},{"codigo":"21200.012","nombre":"Estadístico en ciencias físicas / Estadística en ciencias físicas"},{"codigo":"21200.013","nombre":"Estadístico en demografía / Estadística en demografía"},{"codigo":"21200.014","nombre":"Estadístico en economía / Estadística en economía"},{"codigo":"21200.015","nombre":"Estadístico en educación / Estadística en educación"},{"codigo":"21200.016","nombre":"Estadístico en encuestas / Estadística en encuestas"},{"codigo":"21200.017","nombre":"Estadístico en estadística aplicada / Estadística en estadística apli