  ('rol_cuoc', 'Agrónomos, agroecólogos, agrícolas, pecuarios y zootecnistas / Agrónomas, agroecólogas, agrícolas, pecuarias y zootecnistas', '21321', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 4, false, '{"codigo":"21321","nombre":"Agrónomos, agroecólogos, agrícolas, pecuarios y zootecnistas / Agrónomas, agroecólogas, agrícolas, pecuarias y zootecnistas","descripcion":"Investigan, estudian y suministran asesoría, asistencia, consultoría y técnicas sobre diversos aspectos de la planificación de la producción, explotación, gestión de las unidades productivas, de tecnología y de recursos agropecuarios y ambientales, cultivos, manejo de praderas, fertilización, cosecha, postcosecha, agroindustria, manejo integrado del suelo, prevención de plagas, enfermedades y arvenses; nutrición, mejoramiento de la producción, comercialización de los productos y derivados, entre otras prácticas de manejo. Se pueden desempeñar en fincas, empresas rurales, agroindustrias, firmas de consultoría, entidades del gobierno para asistir a la comunidad agropecuaria, empresas agrícolas, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"21","nombre":"PROFESIONALES DE LAS CIENCIAS Y DE LA INGENIERÍA"},"subgrupo":{"codigo":"213","nombre":"Profesionales en ciencias biológicas"},"grupo_primario":{"codigo":"2132","nombre":"Agrónomos, silvicultores, zootecnistas y afines"}},"funciones":[{"consecutivo":1,"texto":"Apoyar y supervisar el proceso de adquisición de equipos e insumos."},{"consecutivo":2,"texto":"Asesorar y prestar servicio de consultoría sobre técnicas para mejorar la producción, la sostenibilidad y la rentabilidad de cultivos, fertilización, adecuación de tierras; diseño y construcción de distritos de riego y drenaje; diseño y montaje de unidades de postcosecha y recolección de cosechas; cuidado de especies pecuarias y acuáticas; prevención de enfermedades fito y zoosanitarias, producciones alternativas, administración de fincas, finanzas, proyectos, mercadeo y otros aspectos agropecuarios."},{"consecutivo":3,"texto":"Promover y asesorar a educadores, administradores de fincas, empresas rurales y agroindustriales, proveedores de insumos agropecuarios, negociantes y agentes del gobierno en territorio, sobre aspectos relacionados con la empresa, finca, agricultura y agroindustria, actividades pecuarias y acuícolas, planificación, gestión, genética, nutrición, normatividad nacional e internacional, las enfermedades, control de plagas, mejora del suelo, cría de animales, programas de alimentación, entre otros."},{"consecutivo":4,"texto":"Investigar y estudiar sobre las características, técnicas, las posibilidades de utilización y la productividad de los cultivos, suelos y los recursos naturales, insectos, enfermedades y prácticas pesqueras, y aplicar los resultados al rendimiento de la producción pesquera, pecuaria y faenas agrícolas."},{"consecutivo":5,"texto":"Investigar, experimentar e idear métodos nuevos o mejorados sobre genética animal, técnicas de ganadería en fertilidad, manejo de enfermedades, mejoramiento de razas, cría reproducción y cruce de animales."},{"consecutivo":6,"texto":"Investigar sobre la conservación de la fauna salvaje e idear métodos nuevos o perfeccionarlos."},{"consecutivo":7,"texto":"Diseñar e implementar métodos de producción, extracción, transformación, conservación y mercadeo optimizando el aprovechamiento de la materia prima pesquera para el consumo humano, teniendo en cuenta pautas de migración, crecimiento, alimentación, desove de peces, métodos de fertilización, incubación y nacimiento de peces."},{"consecutivo":8,"texto":"Estudiar los factores ambientales que afectan la producción de cultivos comerciales, el crecimiento de los pastos, la cría de animales y las poblaciones de peces."},{"consecutivo":9,"texto":"Dirigir investigaciones, desarrollar procedimientos y técnicas para resolver problemas agropecuarios y mejorar la eficiencia de la producción implementando biosistemas relacionados con la adecuación de tierras, mecanización agrícola, manejo de recursos hídricos, construcciones rurales, postcosecha y procesamiento de productos, con criterios de sostenibilidad y competitividad."},{"consecutivo":10,"texto":"Administrar los recursos agrícolas, pecuarios y pesqueros para maximizar a largo plazo sus beneficios comerciales, recreativos y ambientales."},{"consecutivo":11,"texto":"Investigar, planificar y ejecutar procedimientos de gestión para hacer frente a los efectos de los incendios, las inundaciones, las sequías, la erosión del suelo, las plagas, las enfermedades y el cambio climático."},{"consecutivo":12,"texto":"Realizar o asesorar estudios acerca de métodos y medios para mejorar la calidad de los productos, aumentar el rendimiento, la producción, la eficiencia de las faenas agrícolas o las operaciones forestales y conservar los recursos naturales y el medio ambiente."},{"consecutivo":13,"texto":"Preparar informes científicos y realizar sesiones de asesoramiento, charlas y lecturas informativas para productores, comunidades de agricultura, pecuario y pesca, grupos empresariales, entre otros grupos."},{"consecutivo":14,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"21321.001","nombre":"Agente de servicio de campo agrícola"},{"codigo":"21321.002","nombre":"Agrólogo / Agróloga"},{"codigo":"21321.003","nombre":"Agrónomo / Agrónoma"},{"codigo":"21321.004","nombre":"Agrónomo de ecología / Agrónoma de ecología"},{"codigo":"21321.005","nombre":"Agrónomo de edafología / Agrónoma de edafología"},{"codigo":"21321.006","nombre":"Agrónomo de floricultura / Agrónoma de floricultura"},{"codigo":"21321.007","nombre":"Agrónomo de horticultura / Agrónoma de horticultura"},{"codigo":"21321.008","nombre":"Agrónomo de silvicultura / Agrónoma de silvicultura"},{"codigo":"21321.009","nombre":"Analista de calidad agropecuaria"},{"codigo":"21321.010","nombre":"Analista pecuario / Analista pecuaria"},{"codigo":"21321.011","nombre":"Científico agrícola / Científica agrícola"},{"codigo":"21321.012","nombre":"Científico de investigación de cultivos / Científica de investigación de cultivos"},{"codigo":"21321.013","nombre":"Científico hortícola / Científica hortícola"},{"codigo":"21321.014","nombre":"Consejero agrícola / Consejera agrícola"},{"codigo":"21321.015","nombre":"Edafólogo / Edafóloga"},{"codigo":"21321.016","nombre":"Especialista agrícola"},{"codigo":"21321.017","nombre":"Especialista agrícola y pecuario / Especialista agrícola y pecuaria"},{"codigo":"21321.018","nombre":"Especialista en cultivos"},{"codigo":"21321.019","nombre":"Especialista en extensión agrícola"},{"codigo":"21321.020","nombre":"Especialista en gestión de la pesca"},{"codigo":"21321.021","nombre":"Especialista en riegos"},{"codigo":"21321.022","nombre":"Experto agrícola / Experta agrícola"},{"codigo":"21321.023","nombre":"Experto agrícola y pecuario / Experta agrícola y pecuaria"},{"codigo":"21321.024","nombre":"Experto en bienestar animal / Experta en bienestar animal"},{"codigo":"21321.025","nombre":"Experto en comportamiento animal / Experta en comportamiento animal"},{"codigo":"21321.026","nombre":"Experto evaluador de calidad de cosecha agrícola / Experta evaluadora de calidad de cosecha agrícola"},{"codigo":"21321.027","nombre":"Experto evaluador de cosecha agrícola / Experta evaluadora de cosecha agrícola"},{"codigo":"21321.028","nombre":"Experto pecuario zootecnista / Experta pecuaria zootecnista"},{"codigo":"21321.029","nombre":"Implementador de buenas prácticas pecuarias (BPP) / Implementadora de buenas prácticas pecuarias (BPP)"},{"codigo":"21321.030","nombre":"Ingeniero agrícola / Ingeniera agrícola"},{"codigo":"21321.031","nombre":"Ingeniero agrónomo / Ingeniera agrónoma"},{"codigo":"21321.032","nombre":"Ingeniero agropecuario / Ingeniera agropecuaria"},{"codigo":"21321.033","nombre":"Investigador agropecuario / Invest