  ('rol_cuoc', 'Profesionales en gestión de riesgo de desastres', '21332', 'Ciencias naturales, matemáticas y estadística', 4, false, '{"codigo":"21332","nombre":"Profesionales en gestión de riesgo de desastres","descripcion":"Planean, dirigen, organizan, evalúan, formulan, vigilan y ejecutan políticas, estrategias, planes, programas y proyectos de gestión del riesgo de desastres, a través de procesos de conocimiento, reducción de riesgos y manejo de desastres, emergencias y procesos de recuperación. Se pueden desempeñar en entidades públicas territoriales y nacionales, organizaciones privadas, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"21","nombre":"PROFESIONALES DE LAS CIENCIAS Y DE LA INGENIERÍA"},"subgrupo":{"codigo":"213","nombre":"Profesionales en ciencias biológicas"},"grupo_primario":{"codigo":"2133","nombre":"Profesionales de la protección medioambiental y gestión de riesgo de desastres"}},"funciones":[{"consecutivo":1,"texto":"Planear y dirigir la gestión del riesgo de acuerdo con políticas."},{"consecutivo":2,"texto":"Evaluar estrategias, planes, programas y proyectos en la gestión de riesgo de desastres de acuerdo con política."},{"consecutivo":3,"texto":"Coordinar el proceso de gestión de riesgo de desastres a través de los procesos de conocimiento y reducción del riesgo, manejo de desastres y procesos de recuperación."},{"consecutivo":4,"texto":"Planear, coordinar y orientar acciones de gestión de riesgo de desastres de acuerdo con procedimientos técnicos y políticas."},{"consecutivo":5,"texto":"Diseñar estrategias de gestión de riesgo de desastres de acuerdo con políticas."},{"consecutivo":6,"texto":"Monitorear amenazas de riesgo de desastres y peligros inminentes de acuerdo con procedimientos técnicos y políticas."},{"consecutivo":7,"texto":"Vigilar la ejecución de los procesos de la gestión del riesgo de acuerdo con políticas."},{"consecutivo":8,"texto":"Promover acciones de preparación y rehabilitación en caso de desastres o situaciones de peligro inminente de acuerdo con políticas."},{"consecutivo":9,"texto":"Tramitar recursos para el manejo de emergencias y desastres de acuerdo con políticas."},{"consecutivo":10,"texto":"Elaborar instrumentos de gestión de riesgo de acuerdo con procedimientos técnicos."},{"consecutivo":11,"texto":"Valorar el riesgo de desastres de acuerdo con lineamientos técnicos y políticas."},{"consecutivo":12,"texto":"Revisar y evaluar el impacto y riesgos de desastres que las actividades y los proyectos de un territorio puedan tener sobre el medio ambiente y formular recomendaciones."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"21332.001","nombre":"Analista de gestión del riesgo de desastres"},{"codigo":"21332.002","nombre":"Asesor en gestión de riesgo de desastres / Asesora en gestión de riesgo de desastres"},{"codigo":"21332.003","nombre":"Consultor en gestión de riesgos de desastres / Consultora en gestión de riesgos de desastres"},{"codigo":"21332.004","nombre":"Coordinador de gestión de riesgo de desastres / Coordinadora de gestión de riesgo de desastres"},{"codigo":"21332.005","nombre":"Especialista en análisis de riesgos de desastres"},{"codigo":"21332.006","nombre":"Gestor de riesgo de desastres / Gestora de riesgo de desastres"},{"codigo":"21332.007","nombre":"Gestor de riesgos y emergencias / Gestora de riesgos y emergencias"}],"conocimientos":[{"id":"58","nombre":"Ciencias de la tierra"},{"id":"59","nombre":"Ciencias del medio ambiente"},{"id":"60","nombre":"Ciencias políticas y educación cívica"},{"id":"20","nombre":"Geografía y territorio"},{"id":"1","nombre":"Gerencia y administración"},{"id":"45","nombre":"Gestión del riesgo de desastres"},{"id":"6","nombre":"Gestión del talento humano y de personal"}],"destrezas":[{"id":"17","nombre":"Análisis de necesidades"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"13","nombre":"Conciliación"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"32","nombre":"Gestión del Talento Humano y de Personal"},{"id":"30","nombre":"Gestión de recursos financieros"}],"ocupaciones_afines":[{"codigo":"21331","nombre":"Profesionales ambientales y ecologistas"},{"codigo":"21499","nombre":"Ingenieros no clasificados en otras ocupaciones / Ingenieras no clasificadas en otras ocupaciones"},{"codigo":"26320","nombre":"Sociólogos, antropólogos y afines / Sociólogas, antropólogas y afines"},{"codigo":"32571","nombre":"Inspectores de sanidad, seguridad y salud en el trabajo / Inspectoras de sanidad, seguridad y salud en el trabajo"},{"codigo":"54111","nombre":"Oficiales de bomberos"}],"area_principal":{"sigla":"CNME","nombre":"Ciencias naturales, matemáticas y estadística"},"areas_complementarias":[{"sigla":"CPSA","nombre":"Conservación, protección y saneamiento ambiental"},{"sigla":"SEGU","nombre":"Seguridad"},{"sigla":"COIF","nombre":"Construcción e infraestructura"},{"sigla":"CISH","nombre":"Ciencias sociales y humanidades"}],"equivalencias":[{"ciuo08_codigo":"2133*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"4176*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Ingenieros industriales y de producción / Ingenieras industriales y de producción', '21410', 'Fabricación, transformación de materiales, instalación, mantenimiento y reparación', 4, false, '{"codigo":"21410","nombre":"Ingenieros industriales y de producción / Ingenieras industriales y de producción","descripcion":"Dirigen e implementan investigaciones y estudios, diseñan, desarrollan, organizan, supervisan y controlan la operación y mantenimiento de los procesos e instalaciones para lograr eficiencia en la fabricación, la producción industrial, la optimización del recurso humano, la maquinaria y materiales; establecen programas para coordinar las actividades de fabricación, evaluando la rentabilidad y su nivel de seguridad y calidad. Se pueden desempeñar en firmas consultoras, empresas servicios, de fabricación y procesamiento, financieras, de salud, organizaciones del sector público o privado, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"21","nombre":"PROFESIONALES DE LAS CIENCIAS Y DE LA INGENIERÍA"},"subgrupo":{"codigo":"214","nombre":"Ingenieros (excluyendo Ingenieros en electrotecnología)"},"grupo_primario":{"codigo":"2141","nombre":"Ingenieros industriales y de producción"}},"funciones":[{"consecutivo":1,"texto":"Dirigir y realizar estudios sobre localización, distribución, confiabilidad y funcionalidad de las plantas de procesos productivos o sistemas de administración y asesorar sobre la disposición más eficiente de las instalaciones, maquinaria y equipo, o reformas a métodos, sistemas, procedimientos, programas y operaciones de las áreas de la organización."},{"consecutivo":2,"texto":"Desarrollar, coordinar y establecer programas, normas y políticas para la instalación, modificación, control y aseguramiento de calidad, inventarios, pruebas de funcionamiento, inspección y mantenimiento de acuerdo con los principios de ingeniería y normas de seguridad."},{"consecutivo":3,"texto":"Desarrollar procedimientos y variables de fabricación y procesamiento, de control de máquinas o equipos, vigilar la producción e inspeccionar los procesos y la planta con el fin de mejorar y mantener el rendimiento."},{"consecutivo":4,"texto":"Desarrollar, dirigir y asesorar programas de métodos, tiempos, organización administrativa, medición del trabajo y análisis de muestras de actividad laboral para desarrollar normas en cuanto a la utilización de mano de obra y simplificación del trabajo."},{"consecutivo":5,"texto":"Dirigir estudios, implementar programas y desarrollar especificaciones para la fabricación y determinar niveles óptimos de inventario para producción, equipos, flujos de materiales, capacidades, diseño de instalaciones y sistemas, y la máxima utilización de maquinaria y recursos."},{"consecutivo":6,"texto":"Planear, diseñar, organizar y gestionar la fuerza de trabajo ocupada en los proyectos, entrega de materiales, maquinaria, equipo y la distribución de plantas e instalaciones."},{"consecutivo":7,"texto":"Generar estrategias y asesorar a la dirección sobre nuevos métodos y técnicas de manufactura, administración, tecnología y equipos de producción."},{"consecutivo":8,"texto":"Estudiar y asesorar sobre el diseño, la tecnología y la ingeniería de procesos de fabricación especiales, desarrollar sistemas y procesos de producción flexibles, para mejorar eficiencia, optimizar recursos o aprovechar espacio físico y viabilidad de los productos."},{"consecutivo":9,"texto":"Realizar estudios de métodos, tiempos y movimientos para localizar e investigar el origen de fallas y corregir deficiencias."},{"consecutivo":10,"texto":"Formular, evaluar y controlar proyectos de inversión, estudios de factibilidad, información financiera y contable, planeación y preinversión para el análisis de alternativas de producción y las operaciones de la organización."},{"consecutivo":11,"texto":"Proponer y adecuar métodos y técnicas de producción que aseguren la calidad exigida del producto y/o servicio aceptable, controlando los procesos de producción, estableciendo sistemas y especificaciones de inspección, y adecuando instrumentos para control de calidad."},{"consecutivo":12,"texto":"Analizar, recomendar y asesorar técnicamente sobre la utilización de fuerza de trabajo, diseño de las instalaciones, datos operativos, programas de producción y costos, para determinar la disposición y nivel óptimo de eficiencia de las instalaciones, los trabajadores, la maquinaria y los equipos."},{"consecutivo":13,"texto":"Coordinar el mantenimiento de los edificios de la planta y los equipos productivos, y los requisitos para disponer los nuevos diseños, estudios y programas de mantenimiento."},{"consecutivo":14,"texto":"Desarrollar aplicaciones para el control de tecnologías, procesos y operaciones de fabricación."},{"consecutivo":15,"texto":"Desarrollar, implementar y dirigir programas y estudios de salud ocupacional, seguridad industrial, sistemas de evaluación del desempeño, escala salarial e incentivos."},{"consecutivo":16,"texto":"Estudiar manuales de funciones, organigramas e información del proyecto para determinar las funciones y responsabilidades de los trabajadores y las unidades de trabajo para identificar áreas de duplicación de funciones."},{"consecutivo":17,"texto":"Diseñar, desarrollar, implementar, administrar y mejorar sistemas y procesos de gestión, así como su integración."},{"consecutivo":18,"texto":"Formular, evaluar y hacer seguimiento a proyectos de mejoramiento continuo."},{"consecutivo":19,"texto":"Determinar requisitos y cálculo de datos técnicos que sean necesarios para efectuar los procesos de fabricación, para establecer las cantidades, estimar costos de materiales, recurso humano y de producción, programas de entrenamiento, proyectos y vigilar su cumplimiento."},{"consecutivo":20,"texto":"Coordinar la articulación entre los departamentos de compras de materiales, almacenamiento y departamentos de control para garantizar un flujo constante de suministros."},{"consecutivo":21,"texto":"Coordinar a tecnólogos, técnicos, analistas, personal administrativo y otros ingenieros."},{"consecutivo":22,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"21410.001","nombre":"Asesor de organización y métodos de producción / Asesora de organización y métodos de producción"},{"codigo":"21410.002","nombre":"Coordinador de planta de producción / Coordinadora de planta de producción"},{"codigo":"21410.003","nombre":"Ingeniero administrativo / Ingeniera administrativa"},{"codigo":"21410.004","nombre":"Ingeniero asesor de organización industrial / Ingeniera asesora de organización industrial"},{"codigo":"21410.005","nombre":"Ingeniero de calidad / Ingeniera de calidad"},{"codigo":"21410.006","nombre":"Ingeniero de control de calidad / Ingeniera de control de calidad"},{"codigo":"21410.007","nombre":"Ingeniero de diseño de productos industriales / Ingeniera de diseño de productos industriales"},{"codigo":"21410.008","nombre":"Ingeniero de diseño industrial / Ingeniera de diseño industrial"},{"codigo":"21410.009","nombre":"Ingeniero de eficiencia industrial / Ingeniera de eficiencia industrial"},{"codigo":"21410.010","nombre":"Ingeniero de estudio de tiempos y movimientos / Ingeniera de estudio de tiempos y movimientos"},{"codigo":"21410.011","nombre":"Ingeniero de estudio y trabajo / Ingeniera de estudio y trabajo"},{"codigo":"21410.012","nombre":"Ingeniero de fabricación / Ingeniera de fabricación"},{"codigo":"21410.013","nombre":"Ingeniero de instalaciones industriales / Ingeniera de instalaciones industriales"},{"codigo":"21410.014","nombre":"Ingeniero de métodos / Ingeniera de métodos"},{"codigo":"21410.015","nombre":"Ingeniero de organización industrial / Ingeniera de organización industrial"},{"codigo":"21410.016","nombre":"Ingeniero de organización y métodos / Ingeniera de organización y métodos"},{"codigo":"21410.017","nombre":"I