  ('rol_cuoc', 'Ingenieros navales / Ingenieras navales', '21442', 'Fabricación, transformación de materiales, instalación, mantenimiento y reparación', 4, false, '{"codigo":"21442","nombre":"Ingenieros navales / Ingenieras navales","descripcion":"Planean, dirigen, asesoran, diseñan, controlan e inspeccionan proyectos de construcción y fabricación naval, materiales, reparaciones, modificaciones, mantenimientos y desguace de naves y artefactos navales. Se pueden desempeñar en firmas consultoras, astilleros, empresas portuarias, sociedades de clasificación naval, empresas navieras, aseguradoras, autoridades marítimas, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"21","nombre":"PROFESIONALES DE LAS CIENCIAS Y DE LA INGENIERÍA"},"subgrupo":{"codigo":"214","nombre":"Ingenieros (excluyendo Ingenieros en electrotecnología)"},"grupo_primario":{"codigo":"2144","nombre":"Ingenieros mecánicos, navales y aeronáuticos"}},"funciones":[{"consecutivo":1,"texto":"Asesorar proyectos de construcción, reparación, modificación y mantenimiento de naves y artefactos navales de acuerdo con requerimientos técnicos y normativa."},{"consecutivo":2,"texto":"Diseñar naves y artefactos navales para la navegación de acuerdo con requerimientos del cliente y normativa."},{"consecutivo":3,"texto":"Asesorar y diseñar cascos, superestructuras y sistemas de propulsión de embarcaciones, mecanismos de dirección, bombas y otros equipos mecánicos."},{"consecutivo":4,"texto":"Dirigir, planear, supervisar y controlar la construcción, el mantenimiento y la reparación de naves, artefactos navales y sistemas marinos según requerimientos técnicos y normativa."},{"consecutivo":5,"texto":"Realizar inspecciones, peritajes, calcular estabilidad de naves y artefactos navales existentes según requerimientos técnicos y normativa."},{"consecutivo":6,"texto":"Investigar procesos, métodos, diseños, materiales, técnicas, entre otras, para naves y artefactos navales según tendencias tecnológicas y requerimientos de innovación."},{"consecutivo":7,"texto":"Planear, diseñar, instalar, construir, operar y mantener unidades flotantes, buques, embarcaciones y artefactos navales, con aplicación marítima y fluvial."},{"consecutivo":8,"texto":"Programar mantenimiento en naves y artefactos según estándares de calidad y técnicos."},{"consecutivo":9,"texto":"Investigar el origen de fallas mecánicas inesperadas y solucionar problemas de mantenimiento."},{"consecutivo":10,"texto":"Coordinar a técnicos, tecnólogos y otros ingenieros y revisar y aprobar diseños, cálculos y costos estimados."},{"consecutivo":11,"texto":"Planear, organizar y desarrollar estudios de factibilidad, costos y demás, relacionados con: la fabricación, la instalación, el funcionamiento, el mantenimiento y la reparación de máquinas, equipos e instalaciones de funcionamiento mecánico naval."},{"consecutivo":12,"texto":"Preparar contratos, evaluar propuestas para construcción o mantenimiento de naves y artefactos navales según normativa."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"21442.001","nombre":"Arquitecto de construcciones navales / Arquitecta de construcciones navales"},{"codigo":"21442.002","nombre":"Arquitecto marino / Arquitecta marina"},{"codigo":"21442.003","nombre":"Arquitecto naval / Arquitecta naval"},{"codigo":"21442.004","nombre":"Ingeniero de construcción de buques / Ingeniera de construcción de buques"},{"codigo":"21442.005","nombre":"Ingeniero de construcción naval / Ingeniera de construcción naval"},{"codigo":"21442.006","nombre":"Ingeniero marino / Ingeniera marina"},{"codigo":"21442.007","nombre":"Ingeniero mecánico de construcción de embarcaciones / Ingeniera mecánica de construcción de embarcaciones"},{"codigo":"21442.008","nombre":"Ingeniero mecánico de motores marinos / Ingeniera mecánica de motores marinos"},{"codigo":"21442.009","nombre":"Ingeniero naval / Ingeniera naval"}],"conocimientos":[{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"11","nombre":"Diseño"},{"id":"67","nombre":"Electricidad y energía"},{"id":"15","nombre":"Física"},{"id":"10","nombre":"Ingeniería y tecnología"},{"id":"94","nombre":"Mecánica e ingeniería de vehículos, barcos y aeronaves de motor"},{"id":"13","nombre":"Mecánica y metalistería"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"7","nombre":"Aprendizaje aplicado"},{"id":"18","nombre":"Diseño de tecnología"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"24","nombre":"Mantenimiento de equipos"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"16","nombre":"Resolución de problemas complejos"}],"ocupaciones_afines":[{"codigo":"12230","nombre":"Directores y gerentes de ingeniería, investigación y desarrollo / Directoras y gerentas de ingeniería, investigación y desarrollo"},{"codigo":"21441","nombre":"Ingenieros mecánicos / Ingenieras mecánicas"},{"codigo":"21443","nombre":"Ingenieros aeronáuticos / Ingenieras aeronáuticas"},{"codigo":"21510","nombre":"Ingenieros electricistas / Ingenieras electricistas"},{"codigo":"21521","nombre":"Ingenieros electrónicos / Ingenieras electrónicas"},{"codigo":"21522","nombre":"Ingenieros de automatización e instrumentación / Ingenieras de automatización e instrumentación"},{"codigo":"31150","nombre":"Técnicos en ingeniería mecánica / Técnicas en ingeniería mecánica"},{"codigo":"31181","nombre":"Delineantes y dibujantes técnicos / Delineantes y dibujantes técnicas"},{"codigo":"31226","nombre":"Supervisores de fabricación y tratamiento de productos mecánicos, metálicos y minerales / Supervisoras de fabricación y tratamiento de productos mecánicos, metálicos y minerales"},{"codigo":"31510","nombre":"Oficiales maquinistas en navegación"},{"codigo":"72310","nombre":"Mecánicos y reparadores de vehículos de motor / Mecánicas y reparadoras de vehículos de motor"}],"area_principal":{"sigla":"FAMA","nombre":"Fabricación, transformación de materiales, instalación, mantenimiento y reparación"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"2144*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"2132*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"2138","cno_obs":"Denominaciones completas"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"2146*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Ingenieros aeronáuticos / Ingenieras aeronáuticas', '21443', 'Fabricación, transformación de materiales, instalación, mantenimiento y reparación', 4, false, '{"codigo":"21443","nombre":"Ingenieros aeronáuticos / Ingenieras aeronáuticas","descripcion":"Investigan, asesoran, diseñan y desarrollan directamente todo tipo de aparatos que puedan volar, aeronaves, misiles, satélites, radares, vehículos espaciales y generación de energía; asesoran, evalúan y dirigen su fabricación, instalación, funcionamiento, mantenimiento y reparación o estudian y asesoran sobre aspectos mecánicos y aerodinámicos de determinados materiales, productos o procesos; en ocasiones se desplazan a laboratorios o hangares, para probar o inspeccionar las aeronaves. Se pueden desempeñar en institutos e instituciones científicas o públicas, de generación de energía, industria de aviación, transporte aéreo, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"21","nombre":"PROFESIONALES DE LAS CIENCIAS Y DE LA INGENIERÍA"},"subgrupo":{"codigo":"214","nombre":"Ingenieros (excluyendo Ingenieros en electrotecnología)"},"grupo_primario":{"codigo":"2144","nombre":"Ingenieros mecánicos, navales y aeronáuticos"}},"funciones":[{"consecutivo":1,"texto":"Estudiar y dirigir investigaciones de factibilidad, diseño, operación y funcionamiento de mecanismos, componentes y sistemas, aspectos tecnológicos de determinados materiales, productos o procesos, y asesorar al respecto en el campo de la aeronáutica."},{"consecutivo":2,"texto":"Construir y mantener maquinaria, herramientas, sistemas, componentes y equipos mecánicos para aerodinámica, aviónica, misiles, radares, vehículos espaciales, satélites y en general para el sector aeronáutico."},{"consecutivo":3,"texto":"Diseñar y asesorar en el diseño fuselajes, trenes de aterrizaje y otros equipos para aeronaves."},{"consecutivo":4,"texto":"Diseñar y asesorar en motores de vapor, de combustión interna y otros motores y máquinas que no sean eléctricos utilizados para la propulsión de aeronaves o para hacer funcionar maquinaria industrial asociada a la aeronáutica."},{"consecutivo":5,"texto":"Diseñar cascos, superestructuras y sistemas de propulsión, control y utilización de energía, sistemas de calefacción, ventilación y refrigeración, mecanismos de dirección, bombas y otros equipos mecánicos para aeronaves, misiles, satélites y vehículos espaciales."},{"consecutivo":6,"texto":"Organizar, dirigir y desarrollar estándares de mantenimiento y reparación de máquinas, mecanismos, herramientas, motores, dispositivos, instalaciones, equipos o sistemas aeronáuticos."},{"consecutivo":7,"texto":"Establecer normas y procedimientos de control con estándares de seguridad, especificaciones de diseño y material, operaciones, funcionamientos y mantenimientos aeronáuticos."},{"consecutivo":8,"texto":"Supervisar el diseño, la construcción, el mantenimiento y la reparación de vehículos, máquinas y sistemas aeronáuticos."},{"consecutivo":9,"texto":"Planear, organizar y determinar materiales, cálculos de tiempo, especificaciones de diseño, costos y demás, relacionados con: la fabricación, el funcionamiento, el mantenimiento y la reparación de aeronaves, misiles, satélites y vehículos espaciales."},{"consecutivo":10,"texto":"Investigar el origen de fallas mecánicas inesperadas y solucionar problemas de mantenimiento."},{"consecutivo":11,"texto":"Coordinar a técnicos, tecnólogos y otros ingenieros y revisar y aprobar diseños, cálculos y costos estimados."},{"consecutivo":12,"texto":"Preparar contratos, evaluar propuestas para construcción, investigación, diseño, fabricación y mantenimiento de aeronaves, misiles, satélites y vehículos espaciales."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"21443.001","nombre":"Diseñador de aviones / Diseñadora de aviones"},{"codigo":"21443.002","nombre":"Ingeniero aeroespacial / Ingeniera aeroespacial"},{"codigo":"21443.003","nombre":"Ingeniero aeroespacial de estructuras / Ingeniera aeroespacial de estructuras"},{"codigo":"21443.004","nombre":"Ingeniero aeronáutico / Ingeniera aeronáutica"},{"codigo":"21443.005","nombre":"Ingeniero de comunicaciones aeronáutica / Ingeniera de comunicaciones aeronáutica"},{"codigo":"21443.006","nombre":"Ingeniero de construcción aeronáutica / Ingeniera de construcción aeronáutica"},{"codigo":"21443.007","nombre":"Ingeniero de mantenimiento aeronáutico / Ingeniera de mantenimiento aeronáutico"},{"codigo":"21443.008","nombre":"Ingeniero mecánico de aeromecánica / Ingeniera mecánica de aeromecánica"},{"codigo":"21443.009","nombre":"Ingeniero mecánico de mantenimiento aeronáutico / Ingeniera mecánica de mantenimiento aeronáutico"},{"codigo":"21443.010","nombre":"Ingeniero aeronáutico de ensayos en tierra​ / Ingeniera aeronáutica de ensayos en tierra​"},{"codigo":"21443.011","nombre":"Ingeniero aeronáutico de ensayos en vuelo​ / Ingeniera aeronáutica de ensayos en vuelo​"},{"codigo":"21443.012","nombre":"Ingeniero de diseño aeronáutico ​ / Ingeniera de diseño aeronáutico ​"},{"codigo":"21443.013","nombre":"Ingeniero de seguridad operacional aeronáutico / Ingeniera de seguridad operacional aeronáutico"},{"codigo":"21443.014","nombre":"Ingeniero de diseño y desarrollo aeronáutico / Ingeniera de diseño y desarrollo aeronáutico"}],"conocimientos":[{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"11","nombre":"Diseño"},{"id":"15","nombre":"Física"},{"id":"10","nombre":"Ingeniería y tecnología"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"14","nombre":"Matemáticas"},{"id":"94","nombre":"Mecánica e ingeniería de vehículos, barcos y aeronaves de motor"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"27","nombre":"Análisis de procesos"},{"id":"18","nombre":"Diseño de tecnología"},{"id":"5","nombre":"Lógica matemática"},{"id":"24","nombre":"Mantenimiento de equipos"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"16","nombre":"Resolución de problemas complejos"}],"ocupaciones_afines":[{"codigo":"12230","nombre":"Directores y gerentes de ingeniería, investigación y desarrollo / Directoras y gerentas de ingeniería, investigación y desarrollo"},{"codigo":"21441","nombre":"Ingenieros mecánicos / Ingenieras mecánicas"},{"codigo":"21442","nombre":"Ingenieros navales / Ingenieras navales"},{"codigo":"21499","nombre":"Ingenieros no clasificados en otras ocupaciones / Ingenieras no clasificadas en otras ocupaciones"},{"codigo":"21510","nombre":"Ingenieros electricistas / Ingenieras electricistas"},{"codigo":"21521","nombre":"Ingenieros electrónicos / Ingenieras electrónicas"},{"codigo":"21522","nombre":"Ingenieros de automatización e instrumentación / Ingenieras de automatización e instrumentación"},{"codigo":"31141","nombre":"Técnicos en electrónica / Técnicas en electrónica"},{"codigo":"31150","nombre":"Técnicos en ingeniería mecánica / Técnicas en ingeniería mecánica"},{"codigo":"31181","nombre":"Delineantes y dibujantes técnicos / Delineantes y dibujantes técnicas"},{"codigo":"72310","nombre":"Mecánicos y reparadores de vehículos de motor / Mecánicas y reparadoras de vehículos de motor"}],"area_principal":{"sigla":"FAMA","nombre":"Fabricación, transformación de materiales, instalación, mantenimiento y reparación"},"areas_complementarias":[{"sigla":"ELCA","nombre":"Electrónica y automatización"}],"equivalencias":[{"ciuo08_codigo":"2142*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"2131*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"2144*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"2132*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"2152*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"2146*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Ingenieros químicos / Ingenieras químicas', '21450', 'Industria química', 4, false, '{"codigo":"21450","nombre":"Ingenieros químicos / Ingenieras químicas","descripcion":"Investigan, diseñan, desarrollan y asesoran procesos químicos, y producción a escala comercial de diversas sustancias, materiales, productos y equipos. Vigilan la operación y el mantenimiento de industrias químicas, plásticos, farmacéutico, derivados del petróleo y petroquímico, plantas procesadoras de alimentos y bebidas, medicamentos, materiales sintéticos, entre otros. Asesoran en temas relacionados con el mantenimiento y la reparación de plantas químicas, así como el aseguramiento de calidad, el control de procesos en plantas químicas, la disposición de residuos químicos, bioquímica y biotécnica. Se pueden desempeñar en empresas de fabricación y procesamiento, firmas de consultoría, instituciones educativas y  de investigación, en áreas comerciales técnicas, en el sector público y privado, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"21","nombre":"PROFESIONALES DE LAS CIENCIAS Y DE LA INGENIERÍA"},"subgrupo":{"codigo":"214","nombre":"Ingenieros (excluyendo Ingenieros en electrotecnología)"},"grupo_primario":{"codigo":"2145","nombre":"Ingenieros químicos"}},"funciones":[{"consecutivo":1,"texto":"Investigar, planear, dirigir, desarrollar y asesorar estudios de factibilidad técnica y económica relacionados con la producción a escala comercial y la transformación de procesos y sustancias químicas, para refinar el petróleo crudo y otros líquidos o gases, y producir sustancias y objetos tales como: derivados del petróleo, explosivos, productos alimenticios y bebidas, medicamentos, papel, materiales sintéticos, etc."},{"consecutivo":2,"texto":"Establecer normas, procedimientos, pautas y especificaciones de control para garantizar la seguridad y la eficiencia de las operaciones de producción de sustancias químicas, la seguridad de los trabajadores en el manejo de químicos peligrosos, la protección ambiental o estándares para alimentos, materiales y bienes de consumo."},{"consecutivo":3,"texto":"Desarrollar y determinar métodos, materiales y estándares de producción en plantas con procesos químicos, evaluar la tecnología y el equipo de procesamiento industrial y asegurar que se ajusten a las especificaciones establecidas."},{"consecutivo":4,"texto":"Determinar y verificar las especificaciones, variables del proceso, montaje, modificación, operación, mantenimiento de plantas y unidades, y los requisitos que deben reunir las fábricas de productos químicos, hidrocarburos, pulpa y papel, alimentos y otras industrias de procesamiento."},{"consecutivo":5,"texto":"Diseñar, evaluar, implementar, probar y poner a punto tecnología, equipos y procesos de fabricación de sustancias y productos en plantas químicas."},{"consecutivo":6,"texto":"Realizar el diseño conceptual y detallado de procesos en plantas con procesos químicos, agroquímicos y bioquímicos."},{"consecutivo":7,"texto":"Diseñar, desarrollar y operar equipos y procesos para el manejo, la transformación, la conservación y el aprovechamiento integral de las materias primas alimentarias bajo parámetros de calidad, desde el momento de su producción primaria hasta su consumo."},{"consecutivo":8,"texto":"Realizar pruebas en todas las etapas de producción para determinar el grado de control sobre las variables, como: temperatura, densidad, peso específico y presión."},{"consecutivo":9,"texto":"Estudiar aspectos tecnológicos, conducir investigaciones y asesorar el desarrollo y mejoramiento de productos, procesos químicos y bioquímicos, reacciones, materiales, nuevas materias primas y sustitutos."},{"consecutivo":10,"texto":"Establecer y dirigir programas de aseguramiento de calidad, procedimientos operativos y estrategias de control para garantizar la consistencia y el cumplimiento de estándares de materia prima y productos."},{"consecutivo":11,"texto":"Realizar estudios de laboratorio sobre las etapas en la fabricación de nuevos productos y poner a prueba las propuestas de procesos en instalaciones a pequeña escala, tales como una planta piloto."},{"consecutivo":12,"texto":"Realizar el escalamiento de procesos mejorados o desarrollados en el laboratorio."},{"consecutivo":13,"texto":"Localizar e investigar el origen de fallas y corregir deficiencias."},{"consecutivo":14,"texto":"Inspeccionar el montaje, la adecuación, la operación y el mantenimiento de plantas de producción, organizar y dirigir el mantenimiento y reparación de equipos."},{"consecutivo":15,"texto":"Coordinar a técnicos, tecnólogos y otros ingenieros en las plantas de producción."},{"consecutivo":16,"texto":"Liderar, difundir y hacer seguimiento a la aplicación de las normas y los procedimientos de la medición de hidrocarburos en yacimientos de petróleo y gas, la calidad en la medición, los equipos certificados y los procedimientos estandarizados."},{"consecutivo":17,"texto":"Asesorar sobre métodos, técnicas, equipos y procedimientos de separación y tratamiento de diferentes materiales, elementos y componentes químicos."},{"consecutivo":18,"texto":"Asesorar y dirigir técnicamente la elaboración y la transformación de alimentos y bebidas, verificando las condiciones óptimas de acuerdo con la temperatura, la humedad, la luz, la ausencia de vibraciones, los olores, entre otros."},{"consecutivo":19,"texto":"Asesorar, realizar interventorías y apoyar en la resolución de problemas de contaminación y aprovechamiento de desechos."},{"consecutivo":20,"texto":"Preparar documentos, estimaciones de los costos de producción e informes sobre los avances para la dirección y la evaluación de propuestas para la contratación de procesos y fabricación industrial."},{"consecutivo":21,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"21450.001","nombre":"Consultor de ingeniería química / Consultora de ingeniería química"},{"codigo":"21450.002","nombre":"Enólogo / Enóloga"},{"codigo":"21450.003","nombre":"Fabricante de vino"},{"codigo":"21450.004","nombre":"Ingeniero de alimentos / Ingeniera de alimentos"},{"codigo":"21450.005","nombre":"Ingeniero de bioquímica / Ingeniera de bioquímica"},{"codigo":"21450.006","nombre":"Ingeniero de combustibles / Ingeniera de combustibles"},{"codigo":"21450.007","nombre":"Ingeniero de control de procesos químicos / Ingeniera de control de procesos químicos"},{"codigo":"21450.008","nombre":"Ingeniero de petroquímica / Ingeniera de petroquímica"},{"codigo":"21450.009","nombre":"Ingeniero de plásticos / Ingeniera de plásticos"},{"codigo":"21450.010","nombre":"Ingeniero de procesamiento de alimentos / Ingeniera de procesamiento de alimentos"},{"codigo":"21450.011","nombre":"Ingeniero de procesamiento de refinería de petróleo / Ingeniera de procesamiento de refinería de petróleo"},{"codigo":"21450.012","nombre":"Ingeniero de procesamiento químico / Ingeniera de procesamiento químico"},{"codigo":"21450.013","nombre":"Ingeniero de procesos de refinería / Ingeniera de procesos de refinería"},{"codigo":"21450.014","nombre":"Ingeniero de procesos químicos / Ingeniera de procesos químicos"},{"codigo":"21450.015","nombre":"Ingeniero de procesos químicos industriales / Ingeniera de procesos químicos industriales"},{"codigo":"21450.016","nombre":"Ingeniero de procesos y facilidades / Ingeniera de procesos y facilidades"},{"codigo":"21450.017","nombre":"Ingeniero de producción y distribución de gas natural / Ingeniera de producción y distribución de gas natural"},{"codigo":"21450.018","nombre":"Ingeniero de proyectos químicos / Ingeniera de proyectos químicos"},{"codigo":"21450.019","nombre":"Ingeniero de refinería de petróleo / Ingeniera de refinería de petróleo"},{"codigo":"21450.020","nombre":"Ingeniero farmacéutico / Ingeniera farmacéutica"},{"codigo":"21450.021","nombre":"Ingeniero petroquímico / Ingeniera petroquímica"},{"co