  ('rol_cuoc', 'Ingenieros electricistas / Ingenieras electricistas', '21510', 'Producción de energía y electricidad', 4, false, '{"codigo":"21510","nombre":"Ingenieros electricistas / Ingenieras electricistas","descripcion":"Investigan, analizan, asesoran, diseñan, modelan, administran, planean, seleccionan y vigilan la construcción, el funcionamiento, el mantenimiento, la reparación, la prueba de sistemas eléctricos y de producción, la generación, la transmisión, la distribución y el transporte de energía eléctrica, componentes, motores, equipos eléctricos e instrumentos de medición de variables eléctricas; estudian y asesoran sobre aspectos tecnológicos de los materiales, productos y procesos propios de la ingeniería eléctrica. Se pueden desempeñar en empresas de servicio de energía eléctrica, de comunicaciones, fabricantes de equipos eléctricos, firmas de consultoría e industrias de transporte y procesamiento, del sector público y privado, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"21","nombre":"PROFESIONALES DE LAS CIENCIAS Y DE LA INGENIERÍA"},"subgrupo":{"codigo":"215","nombre":"Ingenieros en electrotecnología"},"grupo_primario":{"codigo":"2151","nombre":"Ingenieros electricistas"}},"funciones":[{"consecutivo":1,"texto":"Asesorar, diseñar, operar y mantener las centrales eléctricas y los sistemas que generan, transmiten, transportan, distribuyen y comercializan energía eléctrica."},{"consecutivo":2,"texto":"Revisar, controlar y monitorear la operación de sistemas de generación, transmisión, y distribución eléctrica."},{"consecutivo":3,"texto":"Diseñar y asesorar en circuitos, sistemas eléctricos, motores eléctricos, medios de tracción eléctrica, componentes y otros equipos eléctricos o aparatos electrodomésticos."},{"consecutivo":4,"texto":"Elaborar especificaciones de instalaciones eléctricas y diseñar sistemas integrales de protección eléctrica, en sistemas de potencia en redes de alta, media y baja tensión aplicados a las instalaciones industriales, residenciales y comerciales de otra índole y en artefactos."},{"consecutivo":5,"texto":"Planear, coordinar, desarrollar y evaluar estudios e investigaciones de proyectos de infraestructura, mejora operacional, de factibilidad, gestionando el alcance, el tiempo, la integración, la calidad, los recursos humanos, las comunicaciones, los riesgos, los costos y demás relacionados con el diseño, la operación y el funcionamiento de instalaciones y redes de generación y distribución eléctrica, sistemas, maquinaria, componentes y equipos eléctricos."},{"consecutivo":6,"texto":"Localizar e investigar el origen de fallas y corregir deficiencias de sistemas y equipos eléctricos."},{"consecutivo":7,"texto":"Organizar y vigilar el mantenimiento y la reparación de sistemas, motores y equipos eléctricos, desarrollar manuales de operación, mantenimiento de sistemas y equipo eléctrico."},{"consecutivo":8,"texto":"Establecer normas y supervisar procedimientos de control, instalación, funcionamiento y seguridad de los sistemas de generación y redes de distribución de energía eléctrica, motores y equipos eléctricos, teniendo en cuenta el impacto ambiental y el beneficio social."},{"consecutivo":9,"texto":"Determinar los métodos de fabricación para sistemas eléctricos, así como de mantenimiento y reparación de los sistemas, motores y equipos eléctricos existentes."},{"consecutivo":10,"texto":"Determinar materiales, costos y tiempo estimado, especificaciones de diseño y métodos de instalación de sistemas y equipos eléctricos."},{"consecutivo":11,"texto":"Desarrollar aplicaciones y usos de naturaleza eléctrica en sistemas de telecomunicaciones, electrónica, automatización y control de procesos."},{"consecutivo":12,"texto":"Participar en los estudios de preparación de contratos, formular y evaluar propuestas para construcción o mantenimiento eléctrico."},{"consecutivo":13,"texto":"Coordinar a ingenieros y técnicos en el desarrollo y el desempeño de proyectos eléctricos."},{"consecutivo":14,"texto":"Coordinar, ejecutar, planear y verificar las actividades relacionadas con el análisis post operativo integrado, aseguramiento de la integralidad y calidad de la información, disponibilidad de herramientas tecnológicas que soportan la operación del sistema de transmisión y distribución de energía eléctrica."},{"consecutivo":15,"texto":"Identificar, analizar, diseñar, proponer, desarrollar y evaluar estrategias de gestión de activos optimizando el valor generado al sistema de transmisión y distribución de energía eléctrica durante su ciclo de vida."},{"consecutivo":16,"texto":"Coordinar, ejecutar y verificar las actividades asociadas con el desarrollo de proyectos de expansión, reposición y mantenimiento del sistema de transmisión y distribución de energía eléctrica, garantizando la disponibilidad, continuidad, calidad y seguridad en la prestación del servicio de energía eléctrica."},{"consecutivo":17,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"21510.001","nombre":"Diseñador de máquina eléctrica / Diseñadora de máquina eléctrica"},{"codigo":"21510.002","nombre":"Diseñador de motor eléctrico / Diseñadora de motor eléctrico"},{"codigo":"21510.003","nombre":"Ingeniero de alto voltaje / Ingeniera de alto voltaje"},{"codigo":"21510.004","nombre":"Ingeniero de diseño de instalaciones eléctricas / Ingeniera de diseño de instalaciones eléctricas"},{"codigo":"21510.005","nombre":"Ingeniero de diseño eléctrico / Ingeniera de diseño eléctrico"},{"codigo":"21510.006","nombre":"Ingeniero de distribución de energía / Ingeniera de distribución de energía"},{"codigo":"21510.007","nombre":"Ingeniero de distribución de energía eléctrica / Ingeniera de distribución de energía eléctrica"},{"codigo":"21510.008","nombre":"Ingeniero de electricidad industrial y de potencia / Ingeniera de electricidad industrial y de potencia"},{"codigo":"21510.0