  ('rol_cuoc', 'Ingenieros de telecomunicaciones / Ingenieras de telecomunicaciones', '21531', 'Tecnologías de la información y las comunicaciones', 4, false, '{"codigo":"21531","nombre":"Ingenieros de telecomunicaciones / Ingenieras de telecomunicaciones","descripcion":"Investigan, asesoran, diseñan, planean, dirigen y controlan la construcción, el funcionamiento, el mantenimiento y la reparación de sistemas y equipos de telecomunicaciones. Adicionalmente, analizan, estudian y asesoran sobre aspectos tecnológicos de materiales, productos o procesos de la ingeniería de telecomunicaciones. Se pueden desempeñar en empresas de telecomunicaciones, firmas de consultoría y todas aquellas que requieran infraestructura de telecomunicaciones del sector público y privado, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"21","nombre":"PROFESIONALES DE LAS CIENCIAS Y DE LA INGENIERÍA"},"subgrupo":{"codigo":"215","nombre":"Ingenieros en electrotecnología"},"grupo_primario":{"codigo":"2153","nombre":"Ingenieros de telecomunicaciones, audio y sonido"}},"funciones":[{"consecutivo":1,"texto":"Asesorar y diseñar dispositivos o componentes, sistemas, servicios, equipos y centros de distribución de telecomunicaciones."},{"consecutivo":2,"texto":"Especificar métodos de producción o instalación, materiales y normas de calidad y seguridad de la información en telecomunicaciones."},{"consecutivo":3,"texto":"Dirigir, gestionar, analizar, evaluar y supervisar los trabajos de implementación de sistemas de telecomunicaciones para garantizar su operación."},{"consecutivo":4,"texto":"Coordinar, organizar y dirigir el mantenimiento y la reparación de sistemas, motores y equipos de telecomunicaciones."},{"consecutivo":5,"texto":"Investigar y asesorar sobre sistemas, tecnología y equipos de telecomunicaciones."},{"consecutivo":6,"texto":"Planificar y diseñar redes de comunicaciones basadas en medios de transmisión por cable, fibra óptica e inalámbrica."},{"consecutivo":7,"texto":"Organizar y vigilar el mantenimiento y la reparación de dispositivos, componentes, servicios, sistemas y equipos de telecomunicaciones, y desarrollar manuales de operación y mantenimiento."},{"consecutivo":8,"texto":"Asesorar desde el área técnica de comunicaciones sobre la información de la inteligencia del negocio para la toma de decisiones."},{"consecutivo":9,"texto":"Diseñar redes de telecomunicaciones y sistemas de distribución de radio y televisión, incluyendo tanto los sistemas de transmisión por cable como por aire."},{"consecutivo":10,"texto":"Asesorar, desarrollar y analizar manuales de operación y mantenimiento de sistemas de telecomunicación."},{"consecutivo":11,"texto":"Interactuar con los clientes de acuerdo con los protocolos y los niveles de servicio."},{"consecutivo":12,"texto":"Diseñar y desarrollar algoritmos de procesamiento de señales y aplicarlos mediante la elección apropiada de equipos y programas informáticos para telecomunicaciones."},{"consecutivo":13,"texto":"Localizar e investigar el origen de fallas en los sistemas y los equipos de telecomunicaciones y corregir deficiencias."},{"consecutivo":14,"texto":"Dirigir y supervisar la interpretación de diseños, planos, procedimientos y manuales requeridos en la implementación de redes de telecomunicaciones."},{"consecutivo":15,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"21531.001","nombre":"Analista de sistemas en telecomunicaciones"},{"codigo":"21531.002","nombre":"Arquitecto de infraestructura en telecomunicaciones / Arquitecta de infraestructura en telecomunicaciones"},{"codigo":"21531.003","nombre":"Ingeniero de difusión / Ingeniera de difusión"},{"codigo":"21531.004","nombre":"Ingeniero de emisión / Ingeniera de emisión"},{"codigo":"21531.005","nombre":"Ingeniero de radar / Ingeniera de radar"},{"codigo":"21531.006","nombre":"Ingeniero de radio / Ingeniera de radio"},{"