  ('rol_cuoc', 'Diseñadores de servicios / Diseñadoras de servicios', '21634', 'Administración, finanzas y derecho', 4, false, '{"codigo":"21634","nombre":"Diseñadores de servicios / Diseñadoras de servicios","descripcion":"Diseñan soluciones integrales, con base a oportunidades identificadas y a través de métodos proyectuales y pensamiento divergente, enmarcadas en la planificación, organización y generación de sistemas de prestación, adquisición y uso de servicios, para mejorar la calidad, la interacción entre el proveedor y usuarios, así como la experiencia de estas. Se pueden desempeñar en agencias, organizaciones públicas y privadas, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"21","nombre":"PROFESIONALES DE LAS CIENCIAS Y DE LA INGENIERÍA"},"subgrupo":{"codigo":"216","nombre":"Arquitectos, planificadores, topógrafos y diseñadores"},"grupo_primario":{"codigo":"2163","nombre":"Diseñadores industriales, de moda, espacios y servicios"}},"funciones":[{"consecutivo":1,"texto":"Determinar y negociar las condicionantes y requerimientos de diseño del servicio en consulta con los clientes y demás partes involucradas."},{"consecutivo":2,"texto":"Investigar las necesidades de los usuarios, comprender la relación hombre-servicio- entorno e identificar el estado del arte relevante para el diseño de servicios requerido."},{"consecutivo":3,"texto":"Proponer y representar conceptos de diseño de servicios a través de bocetos, diagramas, ilustraciones, muestras o modelos."},{"consecutivo":4,"texto":"Idear y proyectar servicios, desde una visión holística, a partir de las oportunidades de diseño identificadas y la investigación realizada."},{"consecutivo":5,"texto":"Proponer y representar alternativas de servicios a través de bocetos, modelos virtuales o físicos, imágenes fotorrealistas o prototipos."},{"consecutivo":6,"texto":"Dirigir la elaboración de prototipos o muestras de los servicios diseñados."},{"consecutivo":7,"texto":"Validar los servicios diseñados a nivel técnico y de usuario."},{"consecutivo":8,"texto":"Definir las especificaciones de los servicios diseñados."},{"consecutivo":9,"texto":"Seleccionar y optimizar el uso, aprovechamiento de materiales y recursos para la puesta en marcha de los servicios diseñados."},{"consecutivo":10,"texto":"Estimar costos y tiempos para la puesta en marcha de los servicios diseñados."},{"consecutivo":11,"texto":"Documentar el diseño del servicio seleccionado."},{"consecutivo":12,"texto":"Gestionar proyectos de diseño de servicios."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"21634.001","nombre":"Analista de contextos y tendencias de diseño de servicios"},{"codigo":"21634.002","nombre":"Analista de mercado para el diseño de servicios"},{"codigo":"21634.003","nombre":"Desarrollador de planes estratégicos e iniciativas de proyectos / Desarrolladora de planes estratégicos e iniciativas de proyectos"},{"codigo":"21634.004","nombre":"Desarrollador de portafolios y propuestas de valor / Desarrolladora de portafolios y propuestas de valor"},{"codigo":"21634.005","nombre":"Diseñador de escenarios futuros de negocios / Diseñadora de escenarios futuros de negocios"},{"codigo":"21634.006","nombre":"Diseñador de experiencias / Diseñadora de experiencias"},{"codigo":"21634.007","nombre":"Diseñador de experiencias de servicio / Diseñadora de experiencias de servicio"},{"codigo":"21634.008","nombre":"Diseñador de servicios alimentarios / Diseñadora de servicios alimentarios"},{"codigo":"21634.009","nombre":"Diseñador de servicios culinarios / Diseñadora de servicios culinarios"},{"codigo":"21634.010","nombre":"Diseñador de servicios gastronómicos / Diseñadora de servicios gastronómicos"},{"codigo":"21634.011","nombre":"Diseñador de servicios para la innovación social / Diseñadora de servicios para la innovación social"},{"codigo":"21634.012","nombre":"Diseñador de sistemas de producto-servicio / Diseñadora de sistemas de producto-servicio"},{"codigo":"21634.013","nombre":"Diseñador del servicio de atención al cliente / Diseñadora del servicio de atención al cliente"},{"codigo":"21634.014","nombre":"Gestor de la innovación en el negocio y el servicio / Gestora de la innovación en el negocio y el servicio"},{"codigo":"21634.015","nombre":"Gestor de valor de marca y pilares del servicio al usuario / Gestora de valor de marca y pilares del servicio al usuario"},{"codigo":"21634.016","nombre":"Diseñador de negocios / Diseñadora de negocios"},{"codigo":"21634.017","nombre":"Diseñador de servicios / Diseñadora de servicios"},{"codigo":"21634.018","nombre":"Ejecutivo de cuenta de diseño / Ejecutiva de cuenta de diseño"},{"codigo":"21634.019","nombre":"Asesor de diseño / Asesora de diseño"},{"codigo":"21634.020","nombre":"Asesor comercial de diseño / Asesora comercial de diseño"},{"codigo":"21634.021","nombre":"Asesor de ventas de diseño / Asesora de ventas de diseño"}],"conocimientos":[{"id":"24","nombre":"Bellas artes"},{"id":"11","nombre":"Diseño"},{"id":"1","nombre":"Gerencia y administración"},{"id":"34","nombre":"Herramientas de simulación y diseño"},{"id":"4","nombre":"Mercadotecnia y publicidad"}],"destrezas":[{"id":"17","nombre":"Análisis de necesidades"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"39","nombre":"Creatividad"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"15","nombre":"Orientación al servicio"},{"id":"12","nombre":"Persuasión"},{"id":"16","nombre":"Resolución de problemas complejos"}],"ocupaciones_afines":[{"codigo":"21631","nombre":"Diseñadores industriales y de productos / Diseñadoras industriales y de productos"},{"codigo":"21632","nombre":"Diseñadores de vestuario y moda / Diseñadoras de vestuario y moda"},{"codigo":"21633","nombre":"Diseñadores de espacios / Diseñadoras de espacios"},{"codigo":"21661","nombre":"Diseñadores gráficos / Diseñadoras gráficas"},{"codigo":"21