  ('rol_cuoc', 'Médicos generales / Médicas generales', '22110', 'Salud y bienestar', 4, false, '{"codigo":"22110","nombre":"Médicos generales / Médicas generales","descripcion":"Previenen, diagnostican y tratan enfermedades, trastornos físicos, lesiones y otros problemas de salud físicos y mentales, mantienen la salud general de los seres humanos mediante la aplicación de los principios y los procedimientos de la medicina moderna. Sus facultades no se limitan a la práctica de determinadas categorías de enfermedades o métodos de tratamiento, ya que pueden asumir la responsabilidad de la prestación de atención médica continua e integral para las personas, las familias y las comunidades. Se pueden desempeñar en clínicas, hospitales, centros médicos o pueden trabajar de forma independiente en consultorios privados, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"22","nombre":"PROFESIONALES DE LA SALUD"},"subgrupo":{"codigo":"221","nombre":"Médicos"},"grupo_primario":{"codigo":"2211","nombre":"Médicos generales"}},"funciones":[{"consecutivo":1,"texto":"Realizar exámenes físicos de los pacientes, así como entrevistarlos y a sus familias para determinar su estado de salud."},{"consecutivo":2,"texto":"Examinar, diagnosticar, tratar enfermedades y ordenar pruebas de laboratorio, radiografías y otros procedimientos de diagnóstico y analizar e interpretar los resultados para determinar la naturaleza de los trastornos o las enfermedades."},{"consecutivo":3,"texto":"Proporcionar atención médica continua para los pacientes, incluyendo: la prescripción, la administración, el asesoramiento y el monitoreo de medicamentos, tratamientos curativos y medidas preventivas."},{"consecutivo":4,"texto":"Realizar intervenciones quirúrgicas, aplicar otros procedimientos clínicos y asistir cirugías de rutina."},{"consecutivo":5,"texto":"Asesorar a las personas, las familias y las comunidades en materia de hábitos de salud, nutrición y estilo de vida que contribuyen a la prevención o el tratamiento de enfermedades y trastornos."},{"consecutivo":6,"texto":"Valorar estados de salud de pacientes, hacer seguimiento a los tratamientos y la evolución de las enfermedades y asistirlos en los procesos de recuperación."},{"consecutivo":7,"texto":"Informar, orientar, asesorar y aconsejar a pacientes sobre estados médicos, tratamientos, prevención y cuidados de la salud."},{"consecutivo":8,"texto":"Remitir a los pacientes y sus familias para la atención especializada en hospitales, centros de rehabilitación u otro tipo de centros de atención de salud."},{"consecutivo":9,"texto":"Detectar, gestionar o derivar a las pacientes para tratar las complicaciones antes, durante y después del parto."},{"consecutivo":10,"texto":"Registrar la información e historia médica de los pacientes e intercambiar información con los médicos especialistas y otro personal de salud, según sea necesario para continuar con la atención médica."},{"consecutivo":11,"texto":"Notificar nacimientos, muertes y enfermedades de declaración obligatoria a las autoridades competentes y gubernamentales para cumplir con los requisitos legales y profesionales."},{"consecutivo":12,"texto":"Realizar investigaciones sobre la salud humana y los servicios médicos y difundir los resultados a través de informes científicos."},{"consecutivo":13,"texto":"Planificar y participar en programas destinados a prevenir la aparición y la propagación de enfermedades comunes."},{"consecutivo":14,"texto":"Inocular y vacunar pacientes."},{"consecutivo":15,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"22110.003","nombre":"Doctor de medicina general / Doctora de medicina general"},{"codigo":"22110.006","nombre":"Médico clínico general / Médica clínica general"},{"codigo":"22110.007","nombre":"Médico de atención primaria / Médica de atención primaria"},{"codigo":"22110.012","nombre":"Médico general de urgencias / Médica general de urgencias"},{"codigo":"22110.013","nombre":"Médico domiciliario / Médica domiciliaria"},{"codigo":"22110.014","nombre":"Médico general / Médica general"}],"conocimientos":[{"id":"40","nombre":"Anatomía"},{"id":"17","nombre":"Biología"},{"id":"57","nombre":"Bioquímica"},{"id":"70","nombre":"Farmacia"},{"id":"21","nombre":"Medicina"},{"id":"41","nombre":"Primeros auxilios"},{"id":"91","nombre":"Tecnología de diagnóstico y tratamiento médico"}],"destrezas":[{"id":"7","nombre":"Aprendizaje aplicado"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"16","nombre":"Resolución de problemas complejos"},{"id":"14","nombre":"Transmisión de conocimiento"}],"ocupaciones_afines":[{"codigo":"21110","nombre":"Físicos y astrónomos / Físicas y astrónomas"},{"codigo":"21310","nombre":"Biólogos, botánicos, zoólogos y afines / Biólogas, botánicas, zoólogas y afines"},{"codigo":"22120","nombre":"Médicos especialistas / Médicas especialistas"},{"codigo":"22210","nombre":"Profesionales de enfermería"},{"codigo":"22401","nombre":"Paramédicos / Paramédicas"},{"codigo":"22611","nombre":"Odontólogos generales / Odontólogas generales"},{"codigo":"22612","nombre":"Odontólogos especialistas / Odontólogas especialistas"},{"codigo":"22699","nombre":"Profesionales de la salud no clasificados en otras ocupaciones"},{"codigo":"26340","nombre":"Psicólogos / Psicólogas"},{"codigo":"32560","nombre":"Asistentes médicos / Asistentas médicas"}],"area_principal":{"sigla":"SABI","nombre":"Salud y bienestar"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"2211","ciuo08_obs":"Denominaciones completas","cno_codigo":"3112","cno_obs":"Denominaciones completas"},{"ciuo08_codigo":"2212*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"","cno_obs":""}]}'::jsonb),
  ('rol_cuoc', 'Médicos especialistas / Médicas especialistas', '22120', 'Salud y bienestar', 4, false, '{"codigo":"22120","nombre":"Médicos especialistas / Médicas especialistas","descripcion":"Diagnostican, tratan y previenen trastornos físicos, enfermedades, lesiones y otros problemas de salud físicos y mentales en los seres humanos, mediante pruebas especializadas y técnicas de diagnóstico, tratamientos médicos, quirúrgicos, físicos y psiquiátricos mediante la aplicación de principios y procedimientos de la medicina moderna. Estudian e investigan la naturaleza, la causa y el desarrollo de enfermedades humanas y áreas especializadas, practican intervenciones quirúrgicas. Estos profesionales se especializan en ciertas categorías de enfermedades, tipos de paciente o métodos de tratamiento, pueden impartir la docencia médica. Se pueden desempeñar en hospitales, clínicas, centros de atención médica, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"22","nombre":"PROFESIONALES DE LA SALUD"},"subgrupo":{"codigo":"221","nombre":"Médicos"},"grupo_primario":{"codigo":"2212","nombre":"Médicos especialistas"}},"funciones":[{"consecutivo":1,"texto":"Diagnosticar, realizar exámenes físicos de los pacientes, así como entrevistarlos y a sus familias para determinar su estado de salud, tratar enfermedades, trastornos físicos o psiquiátricos."},{"consecutivo":2,"texto":"Verificar la información médica proporcionada por el médico que ha referido al paciente u otro proveedor de atención de salud."},{"consecutivo":3,"texto":"Ordenar la realización de pruebas de diagnóstico especializadas para determinar la naturaleza de los trastornos o enfermedades, como pruebas de laboratorio, rayos X y otros diagnósticos e interpretar sus resultados. Prescribir, administrar y hacer seguimiento de las respuestas de los pacientes a los tratamientos especializados, medicamentos, anestésicos, psicoterapias, programas de rehabilitación física, otras medidas preventivas y curativas, y remitir pacientes a cirugía."},{"consecutivo":4,"texto":"Realizar o supervisar procedimientos e intervenciones quirúrgicas de carácter general o especializado entre ellas la corrección de anormalidades, deficiencias físicas, de estética, entre otras."},{"consecutivo":5,"texto":"Tratar las complicaciones antes, durante y después del parto."},{"consecutivo":6,"texto":"Conducir análisis microscópicos y químicos de pruebas y muestras de laboratorio."},{"consecutivo":7,"texto":"Valorar enfermedades y trastornos de pacientes para determinar el procedimiento quirúrgico apropiado."},{"consecutivo":8,"texto":"Elaborar protocolos de tratamiento de enfermedades y quirúrgicos."},{"consecutivo":9,"texto":"Hacer seguimiento a la evolución de las enfermedades de sus pacientes y asistirlos en su proceso de recuperación."},{"consecutivo":10,"texto":"Realizar investigaciones y experimentos sobre los procesos y las funciones vitales de órganos, tejidos, glándulas, células y sistemas de los seres humanos, en condiciones normales o anormales y excepcionales."},{"consecutivo":11,"texto":"Realizar investigaciones y experimentos sobre la estructura y las funciones de las células vivas y sobre la influencia de factores físicos y químicos en células normales y anormales."},{"consecutivo":12,"texto":"Notificar nacimientos, muertes y enfermedades de declaración obligatoria a las autoridades gubernamentales para cumplir con los requisitos legales y profesionales."},{"consecutivo":13,"texto":"Registrar la información médica de los pacientes, actuar como asesor e intercambiar información con otros profesionales de la salud para garantizar la prestación de atención médica integral."},{"consecutivo":14,"texto":"Realizar investigaciones médicas y experimentos sobre la naturaleza, causas y desarrollo de enfermedades humanas, trastornos en los seres humanos, cambios funcionales causados por enfermedades, métodos preventivos o curativos y difundir los resultados, por ejemplo, a través de informes científicos."},{"consecutivo":15,"texto":"Proporcionar información a los pacientes y sus familias y comunidades acerca de las medidas de prevención, el tratamiento y la atención para enfermedades específicas."},{"consecutivo":16,"texto":"Realizar autopsias para determinar la causa de la muerte de personas."},{"consecutivo":17,"texto":"Planificar y participar en los programas destinados a prevenir la aparición y propagación de enfermedades específicas."},{"consecutivo":18,"texto":"Participar en labores de seguimiento de eventos relacionados con la salud pública acorde con los lineamientos de las autoridades competentes y para brindar información oportuna al sistema de salud y vigilancia."},{"consecutivo":19,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"22120.001","nombre":"Alergólogo / Alergóloga"},{"codigo":"22120.002","nombre":"Anestesiólogo / Anestesióloga"},{"codigo":"22120.004","nombre":"Cardiólogo / Cardióloga"},{"codigo":"22120.005","nombre":"Cardiólogo hemodinamista / Cardióloga hemodinamista"},{"codigo":"22120.007","nombre":"Cirujano cardiotorácico / Cirujana cardiotorácica"},{"codigo":"22120.008","nombre":"Cirujano de cardiología / Cirujana de cardiología"},{"codigo":"22120.009","nombre":"Cirujano de estética y reconstrucción / Cirujana de estética y reconstrucción"},{"codigo":"22120.012","nombre":"Cirujano general / Cirujana general"},{"codigo":"22120.014","nombre":"Cirujano ortopédico / Cirujana ortopédica"},{"codigo":"22120.016","nombre":"Cirujano plástico / Cirujana plástica"},{"codigo":"22120.017","nombre":"Cirujano de tórax / Cirujana de tórax"},{"codigo":"22120.018","nombre":"Cirujano vascular / Cirujana vascular"},{"codigo":"22120.021","nombre":"Dermatólogo / Dermatóloga"},{"codigo":"22120.022","nombre":"Diabetólogo / Diabetóloga"},{"codigo":"22120.036","nombre":"Endocrinólogo / Endocrinóloga"},{"codigo":"22120.038","nombre":"Especialis