  ('rol_cuoc', 'Profesionales de la salud no clasificados en otras ocupaciones', '22699', 'Salud y bienestar', 4, false, '{"codigo":"22699","nombre":"Profesionales de la salud no clasificados en otras ocupaciones","descripcion":"Esta ocupación abarca a profesionales de la salud no clasificados en otras ocupaciones del Grupo Primario 2269: Otros profesionales de la salud no clasificados en otros grupos primarios. Por ejemplo, incluye aquellos que diagnostican, administran tratamientos y terapias a pacientes con enfermedades o lesiones músculo esqueléticas, de la columna y otras articulaciones del cuerpo. Prescriben tratamientos y diagnostican condiciones que afectan las estructuras del pie, tobillo y afines de la pierna. Realizan procedimientos quirúrgicos menores, como por ejemplo en pies y tobillos, entre otros. Auditan la prestación de servicios de salud. Se pueden desempeñar en hospitales, clínicas y centros de servicios de salud, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"22","nombre":"PROFESIONALES DE LA SALUD"},"subgrupo":{"codigo":"226","nombre":"Otros profesionales de la salud"},"grupo_primario":{"codigo":"2269","nombre":"Otros profesionales de la salud no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Identificar, prescribir tratamientos y diagnosticar condiciones que afectan las estructuras del pie, tobillo y afines de la pierna debido a una dolencia, deformidad, enfermedad u otro impedimento físico tratando a los pacientes con uso de abrazaderas, tablillas, yesos, terapias físicas, droga o cirugía; prescribiendo calzado correctivo y asesorando sobre el cuidado de los pies para manejar las enfermedades presentadas."},{"consecutivo":2,"texto":"Diagnosticar enfermedades y lesiones músculo esqueléticas, circulatorias y del sistema nervioso y tratar a los pacientes con terapia manipulativa, medicamentos o cirugía."},{"consecutivo":3,"texto":"Diagnosticar enfermedades de la columna y otras articulaciones del cuerpo."},{"consecutivo":4,"texto":"Administrar la atención terapéutica y tratamientos a los pacientes con problemas músculo esqueléticos y articulares, mediante la aplicación de quiropráctica manual y física, técnicas osteopáticas que incluye la manipulación de la columna vertebral y otros tratamientos como aplicación de calor, luz u otros masajes."},{"consecutivo":5,"texto":"Realizar procedimientos quirúrgicos menores, como por ejemplo en pies y tobillos."},{"consecutivo":6,"texto":"Evaluar y documentar el progreso de los pacientes a través de planes de tratamiento, y remitir a los pacientes y sus familias a los médicos u otros proveedores de atención de salud para los servicios de atención especializada, de rehabilitación o de otro tipo que sean necesarios."},{"consecutivo":7,"texto":"Evaluar, diseñar y entrenar en el uso de ortesis y ayudas tecnológicas y funcionales."},{"consecutivo":8,"texto":"Consultar y determinar con la junta directiva el establecimiento de los estándares para la prestación del servicio de salud y el mantenimiento de estos."},{"consecutivo":9,"texto":"Desarrollar sistemas de evaluación para controlar la calidad de los servicios de salud prestados a los pacientes."},{"consecutivo":10,"texto":"Desarrollar planes y programas de auditoría de campo y cuentas médicas."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"22699.001","nombre":"Auditor en salud / Auditora en salud"},{"codigo":"22699.004","nombre":"Podólogo / Podóloga"},{"codigo":"22699.006","nombre":"Quiropráctico / Quiropráctica"}],"conocimientos":[{"id":"40","nombre":"Anatomía"},{"id":"49","nombre":"Atención integral en salud"},{"id":"71","nombre":"Fisioterapia, fonoaudiología, terapia ocupacional, nutrición y afines"},{"id":"21","nombre":"Medicina"},{"id":"41","nombre":"Primeros auxilios"},{"id":"50","nombre":"Servicio a la persona y humanización"},{"id":"91","nombre":"Tecnología de diagnóstico y tratamiento médico"}],"destrezas":[{"id":"17","nombre":"Análisis de necesidades"},{"id":"27","nombre":"Análisis de procesos"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"15","nombre":"Orientación al servicio"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"23","nombre":"Vigilancia de las operaciones"}],"ocupaciones_afines":[{"codigo":"13420","nombre":"Directores y gerentes de servicios de salud / Directoras y gerentas de servicios de salud"},{"codigo":"22120","nombre":"Médicos especialistas / Médicas especialistas"},{"codigo":"22210","nombre":"Profesionales de enfermería"},{"codigo":"22300","nombre":"Profesionales de medicina tradicional y alternativa"},{"codigo":"22640","nombre":"Fisioterapeutas"},{"codigo":"22691","nombre":"Terapeutas ocupacionales"},{"codigo":"26340","nombre":"Psicólogos / Psicólogas"},{"codigo":"32301","nombre":"Técnicos y profesionales del nivel medio en medicina alternativa / Técnicas y profesionales del nivel medio en medicina alternativa"},{"codigo":"32550","nombre":"Técnicos y asistentes terapeutas / Técnicas y asistentes terapeutas"},{"codigo":"32571","nombre":"Inspectores de sanidad, seguridad y salud en el trabajo / Inspectoras de sanidad, seguridad y salud en el trabajo"}],"area_principal":{"sigla":"SABI","nombre":"Salud y bienestar"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"2269*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"0311*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"3122","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Profesores de instituciones de educación superior / Profesoras de instituciones de educación superior', '23100', 'Educación y formación', 4, false, '{"codigo":"23100","nombre":"Profesores de instituciones de educación superior / Profesoras de instituciones de educación superior","descripcion":"Facilitan el aprendizaje a través de la orientación de la educación en clases y tutorías en los diferentes ambientes de formación y extensión; diseñan, desarrollan y evalúan programas académicos para pregrado o postgrado; planean actividades de formación; definen mecanismos de evaluación y seguimiento; adelantan procesos de investigación para ampliar, mejorar o generar nuevos contenidos y metodologías para la resolución de problemas; elaboran trabajos, artículos, publicaciones y libros de carácter académico o científico. Se pueden desempeñar en programas académicos de pregrado y postgrado en universidades o en instituciones de educación superior, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"23","nombre":"PROFESIONALES DE LA EDUCACIÓN"},"subgrupo":{"codigo":"231","nombre":"Profesores de instituciones de educación superior"},"grupo_primario":{"codigo":"2310","nombre":"Profesores de instituciones de educación superior"}},"funciones":[{"consecutivo":1,"texto":"Diseñar, desarrollar y evaluar planes y programas de estudio de acuerdo con los requisitos institucionales y las normas técnicas."},{"consecutivo":2,"texto":"Orientar y facilitar la formación de estudiantes de pregrado y postgrado, en modalidad presencial, semipresencial, virtual y a distancia."},{"consecutivo":3,"texto":"Preparar, ejecutar y evaluar sesiones de aprendizaje en clases, tutorías, seminarios, conferencias, talleres, experimentos, prácticas de laboratorio y de campo."},{"consecutivo":4,"texto":"Promover el intercambio de conocimientos y experiencias en función del aprendizaje, la enseñanza y la evaluación."},{"consecutivo":5,"texto":"Coordinar y acompañar trabajos individuales y de grupo de acuerdo con objetivos de aprendizaje."},{"consecutivo":6,"texto":"Guiar los trabajos experimentales y prácticos realizados por los estudiantes en los ambientes de aprendizaje, según protocolos de bioseguridad y requerimientos del programa."},{"consecutivo":7,"texto":"Diseñar, validar y aplicar instrumentos de evaluación para contenidos teóricos, prácticos, productos y servicios terminados."},{"consecutivo":8,"texto":"Promover, evaluar y dirigir proyectos de docencia, investigación, proyección social y extensión universitaria."},{"consecutivo":9,"texto":"Evaluar y dirigir investigaciones, proyectos de grado, seminarios de estudiantes de pregrado o postgrado y de miembros del departamento institucional y obtener sus productos para publicaciones en libros o revistas indexadas o no indexadas."},{"consecutivo":10,"texto":"Dirigir programas y semilleros de investigación con estudiantes de pregrado y postgrado, brindando asesorías sobre los diferentes aspectos de la investigación y los trabajos de grado desarrollando conceptos, teorías, métodos operacionales para su aplicación en sectores industriales y de otro tipo."},{"consecutivo":11,"texto":"Preparar materiales de apoyo para el aprendizaje como libros académicos, documentos, artículos, entre otros."},{"consecutivo":12,"texto":"Participar en reuniones, conferencias y seminarios del departamento y la facultad."},{"consecutivo":13,"texto":"Participar y asesorar en temas estratégicos a través de centros de estudio de pensamiento, en actividades de generación de documentos de políticas públicas en su área de experticia."},{"consecutivo":14,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"23100.001","nombre":"Asistente de investigación en educación superior / Asistenta de investigación en educación superior"},{"codigo":"23100.003","nombre":"Docente de educación superior"},{"codigo":"23100.004","nombre":"Docente de educación superior de tecnología"},{"codigo":"23100.005","nombre":"Docente de educación superior técnica"},{"codigo":"23100.006","nombre":"Docente de universidad"},{"codigo":"23100.010","nombre":"Profesor adjunto de universidad / Profesora adjunta de universidad"},{"codigo":"23100.014","nombre":"Profesor de educación superior de administración / Profesora de educación superior de administración"},{"codigo":"23100.019","nombre":"Profesor de educación superior de arquitectura y construcción / Profesora de educación superior de arquitectura y construcción"},{"codigo":"23100.029","nombre":"Profesor de educación superior de ciencias naturales / Profesora de educación superior de ciencias naturales"},{"codigo":"23100.031","nombre":"Profesor de educación superior de ciencias sociales y del comportamiento / Profesora de educación superior de ciencias sociales y del comportamiento"},{"codigo":"23100.032","nombre":"Profesor de educación superior de periodismo e información / Profesora de educación superior de periodismo e información"},{"codigo":"23100.035","nombre":"Profesor de educación superior de derecho / Profesora de educación superior de derecho"},{"codigo":"23100.041","nombre":"Profesor de educación superior de filosofía y ética / Profesora de educación superior de filosofía y ética"},{"codigo":"23100.046","nombre":"Profesor de educación superior de idiomas / Profesora de educación superior de idiomas"},{"codigo":"23100.048","nombre":"Profesor de educación superior de ingeniería / Profesora de educación superior de ingeniería"},{"codigo":"23100.062","nombre":"Profesor de educación superior de matemáticas y estadística / Profesora de educación superior de matemáticas y estadística"},{"codigo":"23100.082","nombre":"Profesor de educación superior de veterinaria / Profesora de educación superior de veterinaria"},{"codigo":"23100.085","nombre":"Profesor de educación superior técnica / Profesora de educación superior técnica"},{"codigo":"23100.086","no