  ('rol_cuoc', 'Profesores de formación profesional / Profesoras de formación profesional', '23200', 'Educación y formación', 4, false, '{"codigo":"23200","nombre":"Profesores de formación profesional / Profesoras de formación profesional","descripcion":"Enseñan e imparten formación técnica, vocacional y ocupacional a adultos y estudiantes de últimos años de escuelas secundarias y de formación en áreas u ocupaciones específicas para las cuales normalmente no se requiere educación universitaria o superior; capacitan y actualizan a trabajadores en empresas y organizaciones para el desempeño de funciones laborales. Se pueden desempeñar en universidades e instituciones de educación superior, escuelas de formación para adultos y de formación vocacional, institutos técnicos y escuelas secundarias, empresas y organizaciones, instituciones de formación para el trabajo, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"23","nombre":"PROFESIONALES DE LA EDUCACIÓN"},"subgrupo":{"codigo":"232","nombre":"Profesores de formación profesional"},"grupo_primario":{"codigo":"2320","nombre":"Profesores de formación profesional"}},"funciones":[{"consecutivo":1,"texto":"Elaborar, planificar y establecer programas curriculares, competencias requeridas y contenidos, métodos y material didáctico de enseñanza incluyendo sesiones, demostraciones prácticas, talleres, seminarios y trabajo en equipo, entre otros."},{"consecutivo":2,"texto":"Determinar las necesidades de formación de los estudiantes o de los trabajadores y servir de enlace entre los individuos, la industria y otros sectores de la educación para garantizar la prestación de una educación y programas de formación pertinentes."},{"consecutivo":3,"texto":"Orientar cursos, dirigir y facilitar el proceso de formación complementaria para el desarrollo de conocimientos, actitudes, habilidades y destrezas en actividades técnicas para la elaboración de productos y servicios propios de la ocupación laboral."},{"consecutivo":4,"texto":"Planear y ejecutar actividades como conferencias, debates, talleres y demás, para aumentar competencias, conocimientos en áreas fundamentales y complementarias."},{"consecutivo":5,"texto":"Instruir y supervisar a los estudiantes en el uso de herramientas, equipos, materiales, prevención de daños y lesiones."},{"consecutivo":6,"texto":"Observar, administrar y aplicar pruebas orales, escritas o de rendimiento para medir el progreso y aprendizaje, dar opinión y hacer propuestas de mejoras o evaluar la efectividad del entrenamiento y la competencia."},{"consecutivo":7,"texto":"Preparar informes y mantener registros tales como las calificaciones del estudiante, listas de asistencia y detalles de las actividades de formación."},{"consecutivo":8,"texto":"Supervisar proyectos independientes o de grupo, prácticas de campo, trabajos de laboratorio o de otro tipo de capacitación."},{"consecutivo":9,"texto":"Proporcionar instrucción individualizada y tutorial o clases de recuperación."},{"consecutivo":10,"texto":"Llevar a cabo en el lugar de trabajo sesiones de entrenamiento para enseñar y demostrar los principios, las técnicas, los procedimientos o los métodos de las materias designadas."},{"consecutivo":11,"texto":"Suministrar orientación a los estudiantes sobre alternativas de carrera u oficio."},{"consecutivo":12,"texto":"Participar en comités técnicos de diseño curricular, presupuesto, requisitos de ingreso y certificación."},{"consecutivo":13,"texto":"Adelantar actividades de acompañamiento y orientación en procesos de investigación aplicada."},{"consecutivo":14,"texto":"Proponer estrategias de tránsito de la educación media a la educación superior."},{"consecutivo":15,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"23200.001","nombre":"Docente de educación media técnica"},{"codigo":"23200.002","nombre":"Docente de educación técnica"},{"codigo":"23200.003","nombre":"Etnoeducador / Etnoeducadora"},{"codigo":"23200.004","nombre":"Instructor de acción social / Instructora de acción social"},{"codigo":"23200.005","nombre":"Instructor de agroindustria / Instructora de agroindustria"},{"codigo":"23200.006","nombre":"Instructor de banca y seguros / Instructora de banca y seguros"},{"codigo":"23200.007","nombre":"Instructor de cocina / Instructora de cocina"},{"codigo":"23200.008","nombre":"Instructor de confecciones / Instructora de confecciones"},{"codigo":"23200.009","nombre":"Instructor de construcción / Instructora de construcción"},{"codigo":"23200.010","nombre":"Instructor de contabilidad / Instructora de contabilidad"},{"codigo":"23200.011","nombre":"Instructor de alfarería / Instructora de alfarería"},{"codigo":"23200.012","nombre":"Instructor de arte country / Instructora de arte country"},{"codigo":"23200.013","nombre":"Instructor de arte ruso / Instructora de arte ruso"},{"codigo":"23200.014","nombre":"Instructor de artesanías / Instructora de artesanías"},{"codigo":"23200.015","nombre":"Instructor de bordados / Instructora de bordados"},{"codigo":"23200.016","nombre":"Instructor de carpintería / Instructora de carpintería"},{"codigo":"23200.017","nombre":"Instructor de cestería / Instructora de cestería"},{"codigo":"23200.018","nombre":"Instructor de comercio / Instructora de comercio"},{"codigo":"23200.019","nombre":"Instructor de cosmetología / Instructora de cosmetología"},{"codigo":"23200.020","nombre":"Instructor de ebanistería / Instructora de ebanistería"},{"codigo":"23200.021","nombre":"Instructor de educación vocacional / Instructora de educación vocacional"},{"codigo":"23200.022","nombre":"Instructor de electricidad / Instructora de electricidad"},{"codigo":"23200.023","nombre":"Instructor de electrónica / Instructora de electrónica"},{"codigo":"23200.024","nombre":"Instructor de enfermería / Instructora de enfermería"},{"codigo":"23200.025","nombre":"Instructor de escuela vocacional / Instr