  ('rol_cuoc', 'Otros profesores de artes / Otras profesoras de artes', '23550', 'Educación y formación', 4, false, '{"codigo":"23550","nombre":"Otros profesores de artes / Otras profesoras de artes","descripcion":"Imparten enseñanza, orientan programas y sesiones formativas para el desarrollo de habilidades, destrezas y conocimientos en técnicas relacionadas con la práctica, la teoría y la interpretación de danza, arte dramático, artes visuales y otras disciplinas artísticas (con excepción de la música) en entornos ajenos al sistema general de educación primaria, secundaria y superior, aun cuando también pueden dar clases particulares individuales o en pequeños grupos como actividades extraescolares. Se pueden desempeñar en academias, centros educativos, centros de recreación y bienestar, comunidades, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"23","nombre":"PROFESIONALES DE LA EDUCACIÓN"},"subgrupo":{"codigo":"235","nombre":"Otros profesionales de la educación"},"grupo_primario":{"codigo":"2355","nombre":"Otros profesores de artes"}},"funciones":[{"consecutivo":1,"texto":"Evaluar el nivel de capacidad de los alumnos y determinar sus necesidades de aprendizaje."},{"consecutivo":2,"texto":"Planificar, preparar e impartir programas de estudio, clases y talleres para estudiantes a nivel individual o en grupos."},{"consecutivo":3,"texto":"Preparar y presentar materiales sobre la teoría de la disciplina artística objeto de estudio."},{"consecutivo":4,"texto":"Enseñar y demostrar los aspectos prácticos del arte dramático, danza, artes plásticas u otras disciplinas artísticas."},{"consecutivo":5,"texto":"Asignar ejercicios y tareas que correspondan al nivel de capacidad, intereses y talento de los alumnos."},{"consecutivo":6,"texto":"Evaluar a los alumnos y brindarles asesoramiento, críticas y estímulo."},{"consecutivo":7,"texto":"Revisar planes de estudios, contenidos de cursos, materiales para los mismos y métodos de enseñanza."},{"consecutivo":8,"texto":"Preparar a los alumnos para exámenes, actuaciones y evaluaciones."},{"consecutivo":9,"texto":"Organizar visitas y excursiones para asistir a exposiciones y actuaciones."},{"consecutivo":10,"texto":"Organizar y prestar asistencia en actuaciones o exposiciones de trabajos de los estudiantes."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"23550.001","nombre":"Artista formador / Artista formadora"},{"codigo":"23550.002","nombre":"Artista formador de artes / Artista formadora de artes"},{"codigo":"23550.003","nombre":"Entrenador de personal de actuación / Entrenadora de personal de actuación"},{"codigo":"23550.004","nombre":"Entrenador de actores y actrices de reparto / Entrenadora de actores y actrices de reparto"},{"codigo":"23550.005","nombre":"Entrenador de actores y actrices infantiles / Entrenadora de actores y actrices infantiles"},{"codigo":"23550.006","nombre":"Entrenador de baile deportivo / Entrenadora de baile deportivo"},{"codigo":"23550.007","nombre":"Entrenador de combate escénico / Entrenadora de combate escénico"},{"codigo":"23550.008","nombre":"Entrenador de danza / Entrenadora de danza"},{"codigo":"23550.009","nombre":"Entrenador de drama / Entrenadora de drama"},{"codigo":"23550.010","nombre":"Formador en artes / Formadora en artes"},{"codigo":"23550.011","nombre":"Instructor de danza / Instructora de danza"},{"codigo":"23550.012","nombre":"Instructor de danza en clases particulares / Instructora de danza en clases particulares"},{"codigo":"23550.013","nombre":"Instructor de danza y teatro / Instructora de danza y teatro"},{"codigo":"23550.014","nombre":"Instructor de teatro / Instructora de teatro"},{"codigo":"23550.015","nombre":"Maestro de arte (excepto educación básica y superior) / Maestra de arte (excepto educación básica y superior)"},{"codigo":"23550.016","nombre":"Maestro de academia de baile / Ma