  ('rol_cuoc', 'Instructores de tecnología de la información / Instructoras de tecnología de la información', '23560', 'Educación y formación', 4, false, '{"codigo":"23560","nombre":"Instructores de tecnología de la información / Instructoras de tecnología de la información","descripcion":"Desarrollan, planifican, dirigen y orientan programas y cursos de formación para usuarios de informática u otras tecnologías de la información, al margen del sistema general de educación primaria, secundaria y superior. Se pueden desempeñar en escuelas de formación profesional y vocacional, institutos e instituciones de educación y formación, empresas y organizaciones para el desempeño de funciones laborales, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"23","nombre":"PROFESIONALES DE LA EDUCACIÓN"},"subgrupo":{"codigo":"235","nombre":"Otros profesionales de la educación"},"grupo_primario":{"codigo":"2356","nombre":"Instructores de tecnología de la información"}},"funciones":[{"consecutivo":1,"texto":"Identificar las necesidades y los requerimientos de formación en tecnología de la información de los usuarios individualmente y de las organizaciones."},{"consecutivo":2,"texto":"Dirigir y facilitar el proceso para que los estudiantes elaboren los productos y servicios de las tecnologías de la información con base en el desarrollo de conocimientos, técnicas, habilidades, destrezas y actitudes."},{"consecutivo":3,"texto":"Diseñar, coordinar, planificar y llevar a la práctica programas de inducción, formación y desarrollo que puedan impartirse de forma individual o en grupo, y facilitar la celebración de talleres, reuniones, sesiones de aprendizaje, demostraciones prácticas, talleres, seminarios, conferencias y trabajo en equipo, coordinando los recursos educativos de acuerdo con el currículo y el requerimiento formativo."},{"consecutivo":4,"texto":"Monitorear, realizar seguimiento continuo y evaluar el desempeño, la calidad y eficacia de la formación, revisar y modificar los objetivos, métodos y resultados del curso."},{"consecutivo":5,"texto":"Diseñar programas curriculares, recopilar, investigar, examinar, preparar y elaborar material didáctico y de apoyo e instrucción tales como manuales, ayudas visuales, tutoriales en línea, modelos de demostración y documentación de referencia para obtener una plena comprensión de la materia y de los sistemas de informáticos."},{"consecutivo":6,"texto":"Investigar y actualizar contenidos con las nuevas versiones de los productos, avances en materia de software y tendencias generales de la tecnología de la información, productos y materiales para los usuarios finales, tales como manuales de formación, tutoriales y de instrucciones, ayuda en línea, e instrucciones de funcionamiento y mantenimiento."},{"consecutivo":7,"texto":"Suministrar orientación a los estudiantes sobre alternativas de carrera u oficio relacionadas a la informática o que tengan inmerso un componente informático."},{"consecutivo":8,"texto":"Participar en comités técnicos de diseño curricular, presupuesto, requisitos de ingreso y certificación."},{"consecutivo":9,"texto":"Orientar formación presencial, E- learning e investigación formativa de acuerdo con procedimientos técnicos, normativa y referentes técnicos."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"23560.001","nombre":"Consultor de capacitación en informática / Consultora de capacitación en informática"},{"codigo":"23560.002","nombre":"Consultor e instructor en tecnología de la información / Consultora e instructora en tecnología de la información"},{"codigo":"23560.003","nombre":"Instructor de escuela de informática / Instructora de escuela de informática"},{"codigo":"23560.004","nombre":"Instructor de informática / Instructora de informática"},{"codigo":"23560.005","nombre":"Instructor de internet / Instructora de internet"},{"codigo":"23560.006","nombre":"Instructor de software / Instructora de software"},{"codigo":"23560.007","nombre":"Instructor de tecnologías de la información TI (Tecnologías de la Información) / Instructora de tecnologías de la información TI (Tecnologías de la Información)"},{"codigo":"23560.008","nombre":"Instructor de telecomunicaciones e informática / Instructora de telecomunicaciones e informática"},{"codigo":"23560.009","nombre":"Instructor de teleinformática / Instructora de teleinformática"},{"codigo":"23560.010","nombre":"Instructor de virtualización de las TIC (tecnologías de la información y las comunicaciones) / Instructora de virtualización de las TIC (tecnologías de la información y las comunicaciones)"},{"codigo":"23560.011","nombre":"Profesor de sistemas / Profesora de sistemas"}],"conocimientos":[{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"63","nombre":"Desarrollo y análisis de software y aplicaciones"},{"id":"65","nombre":"Diseño y administración de redes y bases de datos"},{"id":"22","nombre":"Educación y capacitación"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"14","nombre":"Matemáticas"},{"id":"29","nombre":"Telecomunicación"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"8","nombre":"Estrategias para el aprendizaje"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"24","nombre":"Mantenimiento de equipos"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"21","nombre":"Programación"},{"id":"14","nombre":"Transmisión de conocimiento"}],"ocupaciones_afines":[{"codigo":"23100","nombre":"Profesores de instituciones de educación superior / Profesoras de instituciones de educación superior"},{"codigo":"23200","nombre":"Profesores de formación profesional / Profesoras de formación profesional"},{"codigo":"23300","nombre":"Profesores de educación secundaria / Profesoras de educación secundaria"},{"codigo":"23410","nombre":"Profesores de educación básica primaria / Profesoras de educación básica primaria"},{"codigo":"23521","nombre":"Profesores e instructores de educación especial e inclusiva / Profesoras e instructoras de educación especial e inclusiva"},{"codigo":"24242","nombre":"Evaluadores de competencias laborales / Evaluadoras de competencias laborales"}],"area_principal":{"sigla":"EDFO","nombre":"Educación y formación"},"areas_complementarias":[{"sigla":"TICO","nombre":"Tecnologías de la información y las comunicaciones"}],"equivalencias":[{"ciuo08_codigo":"2356","ciuo08_obs":"Denominaciones completas","cno_codigo":"4131*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Orientadores educativos / Orientadoras educativas', '23591', 'Educación y formación', 4, false, '{"codigo":"23591","nombre":"Orientadores educativos / Orientadoras educativas","descripcion":"Asesoran a estudiantes sobre asuntos educativos, orientación vocacional y desarrollo personal; coordinan la provisión de servicios de consejería a estudiantes, padres y profesores. Se pueden desempeñar en instituciones públicas y privadas de educación superior, de formación para el trabajo, educación secundaria y básica primaria, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"23","nombre":"PROFESIONALES DE LA EDUCACIÓN"},"subgrupo":{"codigo":"235","nombre":"Otros profesionales de la educación"},"grupo_primario":{"codigo":"2359","nombre":"Otros profesionales de la educación no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Evaluar el nivel de capacidad de las personas, determinar sus necesidades de aprendizaje, brindarles asesoramiento, críticas y estímulo a través de la aplicación de pruebas estandarizadas de inteligencia, aptitud e intereses y elaborar informes de resultados."},{"consecutivo":2,"texto":"Planificar, preparar y asesorar en el desarrollo de programas de estudio, clases y talleres de forma individual o en grupo."},{"consecutivo":3,"texto":"Preparar y presentar materiales sobre la teoría del tema objeto de estudio."},{"consecutivo":4,"texto":"Enseñar y demostrar los aspectos prácticos del tema objeto de estudio."},{"consecutivo":5,"texto":"Asesorar en ejercicios y trabajos adecuados al nivel de capacidad, intereses y aptitudes de los alumnos."},{"consecutivo":6,"texto":"Revisar planes de estudios, contenidos, materiales y métodos de enseñanza de los cursos."},{"consecutivo":7,"texto":"Desarrollar estrategia de estudio para preparar a los alumnos para exámenes y evaluaciones."},{"consecutivo":8,"texto":"Asesorar y aconsejar a las personas para ayudarles a comprender y superar los problemas personales, sociales o de comportamiento que afectan su educación como la interrelación con compañeros, profesores, problemas familiares, problemas de drogadicción, depresión, sexualidad y autoestima, entre otros."},{"consecutivo":9,"texto":"Asesorar y aconsejar a las personas sobre asuntos educativos como la selección de cursos y programas, horarios de las clases, su adaptación al entorno escolar, ausentismo, hábitos de estudio, perspectivas y planificación de la educación superior o vocacional, entre otros."},{"consecutivo":10,"texto":"Preparar a los alumnos para experiencias educativas ulteriores, alentándoles a explorar las oportunidades de aprendizaje y a perseverar en la realización de tareas difíciles."},{"consecutivo":11,"texto":"Preparar y coordinar el suministro de servicios de consejería, talleres de orientación e información para estudiantes, padres y profesores, como orientación vocacional, sesiones de desarrollo profesional e interacciones con otras instituciones educativas presentando informes con recomendaciones a las directivas del centro educativo y a los padres que los requieran."},{"consecutivo":12,"texto":"Recibir capacitación y actualizarse sobre métodos de orientación educativa y personal."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"23591.001","nombre":"Asesor de estudiantes / Asesora de estudiantes"},{"codigo":"23591.002","nombre":"Asesor de estudios / Asesora de estudios"},{"codigo":"23591.003","nombre":"Asesor estudiantil / Asesora estudiantil"},{"codigo":"23591.004","nombre":"Consejero de escuela / Consejera de escuela"},{"codigo":"23591.005","nombre":"Consejero de universidad / Consejera de universidad"},{"codigo":"23591.006","nombre":"Consejero educativo / Consejera educativa"},{"codigo":"23591.007","nombre":"Consejero escolar / Consejera escolar"},{"codigo":"23591.008","nombre":"Consejero estudiantil / Consejera estudiantil"},{"codigo":"23591.009","nombre":"Orientador educativo / Orientadora educativa"},{"codigo":"23591.010","nombre":"Orientador escolar / Orientadora escolar"},{"codigo":"23591.011","nombre":"Orientador vocacional / Orientadora vocacional"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"26","nombre":"Filosofía y ética"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"5","nombre":"Servicio al cliente"},{"id":"18","nombre":"Sicología / psicología"},{"id":"19","nombre":"Sociología, antropología y estudios culturales"},{"id":"93","nombre":"Trabajo social"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"13","nombre":"Conciliación"},{"id":"2","nombre":"Escucha activa"},{"id":"8","nombre":"Estrategias para el aprendizaje"},{"id":"15","nombre":"Orientación al servicio"},{"id":"12","nombre":"Persuasión"},{"id":"14","nombre":"Transmisión de conocimiento"}],"ocupaciones_afines":[{"codigo":"23100","nombre":"Profesores de instituciones de educación superior / Profesoras de instituciones de educación superior"},{"codigo":"23200","nombre":"Profesores de formación profesional / Profesoras de formación profesional"},{"codigo":"23300","nombre":"Profesores de educación secundaria / Profesoras de educación secundaria"},{"codigo":"23410","nombre":"Profesores de educación básica primaria / Profesoras de educación básica primaria"},{"codigo":"23510","nombre":"Especialistas en métodos y procesos pedagógicos"},{"codigo":"23521","nombre":"Profesores e instructores de educación especial e inclusiva / Profesoras e instructoras de educación especial e inclusiva"},{"codigo":"26340","nombre":"Psicólogos / Psicólogas"},{"codigo":"26351","nombre":"Profesionales del trabajo social y consejeros"},{"codigo":"34120","nombre":"Trabajadores y asistentes sociales y comunitarios / Trabajadoras y asistentes sociales y comunitarias"}],"area_principal":{"sigla":"EDFO","nombre":"Educación y formación"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"2359*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"4144*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Otros profesionales de la educación no clasificados en otras ocupaciones / Otras profesionales de la educación no clasificados en otras ocupaciones', '23599', 'Educación y formación', 4, false, '{"codigo":"23599","nombre":"Otros profesionales de la educación no clasificados en otras ocupaciones / Otras profesionales de la educación no clasificados en otras ocupaciones","descripcion":"Esta ocupación abarca a otros profesionales de la educación no clasificados en otras ocupaciones del Grupo Primario 2359: Otros profesionales de la educación no clasificados en otros grupos primarios. Por ejemplo, incluye aquellos que imparten clases particulares en materias distintas de las lenguas extranjeras, artes, música, agrícola y oficios. Se pueden desempeñar en escuelas de formación profesional, vocacional y de capacitación, correccionales, empresas, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"23","nombre":"PROFESIONALES DE LA EDUCACIÓN"},"subgrupo":{"codigo":"235","nombre":"Otros profesionales de la educación"},"grupo_primario":{"codigo":"2359","nombre":"Otros profesionales de la educación no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Preparar, evaluar y aplicar pruebas de verificación del aprendizaje y nivel de capacidad de los alumnos, brindar asesoramiento, crítica y estímulo. y determinar las necesidades de aprendizaje."},{"consecutivo":2,"texto":"Dirigir y facilitar el proceso para que los estudiantes desarrollen conocimientos, técnicas, habilidades, destrezas y actitudes que le permitan alcanzar un nivel más elevado de formación en la materia."},{"consecutivo":3,"texto":"Diseñar y presentar programas curriculares, planes de estudios, contenidos, sesiones y métodos de aprendizaje, demostraciones prácticas, talleres, seminarios, materiales didácticos incluyendo el trabajo de forma individual o en equipo."},{"consecutivo":4,"texto":"Enseñar y demostrar los aspectos prácticos del tema objeto de estudio."},{"consecutivo":5,"texto":"Asignar ejercicios y trabajos adecuados al nivel de capacidad, intereses y aptitudes de los alumnos."},{"consecutivo":6,"texto":"Preparar a los alumnos para exámenes y evaluaciones."},{"consecutivo":7,"texto":"Participar en comités técnicos de diseño curricular, presupuesto, requisitos de ingreso y certificación."},{"consecutivo":8,"texto":"Preparar talleres de orientación dirigidos a alumnos, profesores y padres de familia y presentar informes y recomendaciones a las directivas del centro educativo y a los padres que los requieran."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"23599.001","nombre":"Educador de correccional / Educadora de correccional"},{"codigo":"23599.002","nombre":"Entrenador de debates / Entrenadora de debates"},{"codigo":"23599.003","nombre":"Instructor de matemáticas / Instructora de matemáticas"},{"codigo":"23599.004","nombre":"Instructor de matemáticas en clases particulares / Instructora de matemáticas en clases particulares"},{"codigo":"23599.005","nombre":"Maestro de correccional / Maestra de correccional"},{"codigo":"23599.006","nombre":"Profesor de alfabetización en clases particulares / Profesora de alfabetización en clases particulares"},{"codigo":"23599.007","nombre":"Profesor de correccional / Profesora de correccional"},{"codigo":"23599.008","nombre":"Profesor de matemáticas en clases particulares / Profesora de matemáticas en clases particulares"},{"codigo":"23599.009","nombre":"Profesor particular de educación formal / Profesora particular de educación formal"},{"codigo":"23599.010","nombre":"Tutor de alfabetización en clases particulares / Tutora de alfabetización en clases particulares"},{"codigo":"23599.011","nombre":"Tutor de alfabetización y aritmética en clases particulares / Tutora de alfabetización y aritmética en clases particulares"},{"codigo":"23599.0