  ('rol_cuoc', 'Contadores / Contadoras', '24111', 'Administración, finanzas y derecho', 4, false, '{"codigo":"24111","nombre":"Contadores / Contadoras","descripcion":"Planifican, organizan y administran sistemas contables y financieros para personas y organizaciones de acuerdo con la normativa nacional e internacional; evalúan, controlan y cumplen con las obligaciones fiscales, establecen los procedimientos para la gestión de la información, contable, financiera y tributaria, garantizan y proporcionan información veraz, oportuna y de acuerdo con normatividad; asesoran en materia contable. Se pueden desempeñar en organizaciones con departamentos contables y financieros, empresas especializadas en servicios contables y de auditoría, el sector público y privado, servicio a personas naturales y jurídicas, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"24","nombre":"PROFESIONALES DE NEGOCIOS Y DE ADMINISTRACIÓN"},"subgrupo":{"codigo":"241","nombre":"Profesionales en finanzas"},"grupo_primario":{"codigo":"2411","nombre":"Contadores y auditores financieros"}},"funciones":[{"consecutivo":1,"texto":"Asesorar, planificar y establecer políticas y sistemas presupuestarios, de control de cuentas y de otra índole."},{"consecutivo":2,"texto":"Preparar, elaborar, estructurar y certificar información financiera para su presentación a la gerencia, accionistas y organismos de derecho público o de otra índole, según normativa vigente y políticas institucionales."},{"consecutivo":3,"texto":"Gestionar, preparar e informar las obligaciones tributarias, asesorar sobre problemas fiscales e impugnar reclamaciones en disputa ante la administración fiscal, de acuerdo con normativa fiscal vigente."},{"consecutivo":4,"texto":"Preparar, analizar e informar sobre proyecciones financieras y de inversiones, de acuerdo con la normativa vigente y planes financieros."},{"consecutivo":5,"texto":"Supervisar procesos de auditoría financiera y contable de acuerdo con estándares de calidad internos de la entidad u organización."},{"consecutivo":6,"texto":"Investigar y brindar asesoramiento a la dirección sobre: impuestos, aspectos financieros de la productividad, participaciones accionarias, ventas, nuevos productos, etc."},{"consecutivo":7,"texto":"Preparar, gestionar y apoyar en la elaboración de informes detallados de auditoría o revisoría, control de planes financieros y presupuestales de acuerdo con estrategias económicas, normatividad vigente y recomendaciones para mejorar prácticas contables y administrativas."},{"consecutivo":8,"texto":"Calcular los costos de operaciones de acuerdo con métodos y tipo de costo."},{"consecutivo":9,"texto":"Realizar capacitaciones constantes en materia contable, financiera y tributaria a empleados antiguos en caso de que haya actualización en los procesos o la falta de conocimiento por parte de los auxiliares o coordinadores."},{"consecutivo":10,"texto":"Coordinar y orientar el trabajo del personal a cargo y auxiliares de las áreas contables o financieras."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"24111.001","nombre":"Asesor fiscal / Asesora fiscal"},{"codigo":"24111.002","nombre":"Cesionario de insolvencia / Cesionaria de insolvencia"},{"codigo":"24111.003","nombre":"Cesionario de quiebra / Cesionaria de quiebra"},{"codigo":"24111.004","nombre":"Consultor de contabilidad / Consultora de contabilidad"},{"codigo":"24111.005","nombre":"Contable"},{"codigo":"24111.006","nombre":"Contador / Contadora"},{"codigo":"24111.007","nombre":"Contador administrativo / Contadora administrativa"},{"codigo":"24111.008","nombre":"Contador certificado / Contadora certificada"},{"codigo":"24111.009","nombre":"Contador de costos / Contadora de costos"},{"codigo":"24111.010","nombre":"Contador de gestión / Contadora de gestión"},{"codigo":"24111.011","nombre":"Contador de impuestos / Contadora de impuestos"},{"codigo":"24111.012","nombre":"Contador de inversiones financieras / Contadora de inversiones financieras"},{"codigo":"24111.013","nombre":"Contador de navío o nave / Contadora de navío o nave"},{"codigo":"24111.014","nombre":"Contador público / Contadora pública"},{"codigo":"24111.015","nombre":"Contador público financiero / Contadora pública financiera"},{"codigo":"24111.016","nombre":"Contador tributario / Contadora tributaria"},{"codigo":"24111.017","nombre":"Controlador financiero / Controladora financiera"},{"codigo":"24111.018","nombre":"Ecónomo tesorero / Economa tesorera"},{"codigo":"24111.019","nombre":"Especialista en insolvencia"},{"codigo":"24111.020","nombre":"Examinador de insolvencia / Examinadora de insolvencia"},{"codigo":"24111.021","nombre":"Examinador de quiebra / Examinadora de quiebra"},{"codigo":"24111.022","nombre":"Fideicomisario de quiebra / Fideicomisaria de quiebra"},{"codigo":"24111.023","nombre":"Fiduciario de insolvencia / Fiduciaria de insolvencia"},{"codigo":"24111.024","nombre":"Interventor de cuentas / Interventora de cuentas"},{"codigo":"24111.025","nombre":"Liquidador de empresa / Liquidadora de empresa"},{"codigo":"24111.026","nombre":"Liquidador financiero / Liquidadora financiera"},{"codigo":"24111.027","nombre":"Liquidador oficial / Liquidadora oficial"},{"codigo":"24111.028","nombre":"Profesional en contabilidad y costos"},{"codigo":"24111.029","nombre":"Profesional contable"},{"codigo":"24111.030","nombre":"Profesional contable tributario / Profesional contable tributaria"},{"codigo":"24111.031","nombre":"Profesional de insolvencia"},{"codigo":"24111.032","nombre":"Tesorero contable / Tesorera contable"}],"conocimientos":[{"id":"32","nombre":"Contabilidad e impuestos"},{"id":"69","nombre":"Estadística"},{"id":"1","nombre":"Gerencia y administración"},{"id":"33","nombre":"Gestión financiera, administración bancaria y seguros"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"14","nombre":"Matemáticas"}],"destrezas":[{"id":"17","nombre":"Análisis de necesidades"},{"id":"27","nombre":"Análisis de procesos"},{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"}],"ocupaciones_afines":[{"codigo":"12111","nombre":"Directores y gerentes financieros / Directoras y gerentas financieras"},{"codigo":"24112","nombre":"Auditores financieros y contables / Auditoras financieras y contables"},{"codigo":"24120","nombre":"Asesores financieros y de inversiones / Asesoras financieras y de inversiones"},{"codigo":"24130","nombre":"Analistas financieros / Analistas financieras"},{"codigo":"24210","nombre":"Profesionales y analistas de gestión y organización"},{"codigo":"33131","nombre":"Asistentes contables / Asistentas contables"},{"codigo":"33132","nombre":"Asistentes financieros / Asistentas financieras"},{"codigo":"33133","nombre":"Asistentes de tesorería / Asistentas de tesorería"},{"codigo":"43110","nombre":"Auxiliares de contabilidad, costos y tesorería"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"2411*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"1111*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Auditores financieros y contables / Auditoras financieras y contables', '24112', 'Administración, finanzas y derecho', 4, false, '{"codigo":"24112","nombre":"Auditores financieros y contables / Auditoras financieras y contables","descripcion":"Examinan y analizan la información contable y financiera de personas naturales y organizaciones; evalúan, supervisan y realizan seguimiento de los riesgos del sistema de control interno e identifican las oportunidades de mejora y alternativas para optimizar alternativas que garantizar exactitud y cumplimiento de los procedimientos y normativas vigentes para la elaboración, implementación y presentación de informes; prestan servicios de auditoría, acompañamiento, revisoría o verificación de cuentas. Se pueden desempeñar en organizaciones con departamentos contables y financieros, empresas especializadas en servicios contables y de auditoría, en el sector público y privado, servicio a personas naturales y jurídicas, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"24","nombre":"PROFESIONALES DE NEGOCIOS Y DE ADMINISTRACIÓN"},"subgrupo":{"codigo":"241","nombre":"Profesionales en finanzas"},"grupo_primario":{"codigo":"2411","nombre":"Contadores y auditores financieros"}},"funciones":[{"consecutivo":1,"texto":"Revisar el cumplimiento de los sistemas de gestión según el marco estratégico y normativa financiera y de auditoría."},{"consecutivo":2,"texto":"Verificar y analizar la información contable y financiera de acuerdo con normativa financiera y de auditoría."},{"consecutivo":3,"texto":"Evaluar los riesgos del sistema de control e información financiera y contable de acuerdo con procedimientos técnicos y normativa financiera y de auditoría."},{"consecutivo":4,"texto":"Investigar e identificar oportunidades de mejora y optimización para los diferentes procesos financieros y contables de acuerdo con procedimientos técnicos y normativa financiera y de auditoría."},{"consecutivo":5,"texto":"Preparar informes detallados de auditoría y demás de acuerdo con procedimientos técnicos y normativa financiera y de auditoría."},{"consecutivo":6,"texto":"Realizar investigaciones financieras en asuntos tales como la sospecha de fraude, insolvencia y quiebra."},{"consecutivo":7,"texto":"Asesorar sobre declaraciones de impuestos, problemas fiscales e impugnar reclamaciones en disputa ante la administración fiscal."},{"consecutivo":8,"texto":"Promover la adopción de correctivos, actualizaciones, seguimiento e implementación del efectivo, eficiente y oportuno funcionamiento del sistema de autocontrol y gestión del riesgo de lavado de activos y financiación del terrorismo de acuerdo con normatividad y protocolos establecidos."},{"consecutivo":9,"texto":"Participar y formular junto a demás profesionales del área, estrategias para establecer los controles necesarios teniendo en cuenta el grado de exposición al riesgo de lavado de activos y financiación del terrorismo."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"24112.001","nombre":"Auditor contable / Auditora contable"},{"codigo":"24112.002","nombre":"Auditor financiero / Auditora financiera"},{"codigo":"24112.003","nombre":"Auditor financiero y contable / Auditora financiera y contable"},{"codigo":"24112.004","nombre":"Auditor forense / Auditora forense"},{"codigo":"24112.005","nombre":"Auditor general financiero y contable / Auditora general financiera y contable"},{"codigo":"24112.006","nombre":"Auditor interno / Auditora interna"},{"codigo":"24112.007","nombre":"Consultor de auditoría / Consultora de auditoría"},{"codigo":"24112.008","nombre":"Contador auditor / Contadora auditora"},{"codigo":"24112.009","nombre":"Contralor auditor / Contralora auditora"},{"codigo":"24112.010","nombre":"Especialista en auditoría"},{"codigo":"24112.011","nombre":"Examinador de auditoría / Examinadora de auditoría"},{"codigo":"24112.012","nombre":"Oficial de cumplimiento SARLAFT (sistema de administración de riesgo de lavado de activos y de la financiación del terrorismo) y SAGRLAFT (sistema de autocontrol y gestión del riesgo de lavado de activos y financiación del terrorismo)"},{"codigo":"24112.013","nombre":"Revisor fiscal / Revisora fiscal"}],"conocimientos":[{"id":"32","nombre":"Contabilidad e impuestos"},{"id":"3","nombre":"Economía"},{"id":"1","nombre":"Gerencia y administración"},{"id":"33","nombre":"Gestión financiera, administración bancaria y seguros"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"14","nombre":"Matemáticas"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"27","nombre":"Análisis de procesos"},{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"16","nombre":"Resolución de problemas complejos"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"12111","nombre":"Directores y gerentes financieros / Directoras y gerentas financieras"},{"codigo":"24111","nombre":"Contadores / Contadoras"},{"codigo":"24120","nombre":"Asesores financieros y de inversiones / Asesoras financieras y de inversiones"},{"codigo":"24130","nombre":"Analistas financieros / Analistas financieras"},{"codigo":"24210","nombre":"Profesionales y analistas de gestión y organización"},{"codigo":"33131","nombre":"Asistentes contables / Asistentas contables"},{"codigo":"33132","nombre":"Asistentes financieros / Asistentas financieras"},{"codigo":"33133","nombre":"Asistentes de tesorería / Asistentas de tesorería"},{"codigo":"43110","nombre":"Auxiliares de contabilidad, costos y tesorería"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"2411*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"1111*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"1113*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Asesores financieros y de inversiones / Asesoras financieras y de inversiones', '24120', 'Administración, finanzas y derecho', 4, false, '{"codigo":"24120","nombre":"Asesores financieros y de inversiones / Asesoras financieras y de inversiones","descripcion":"Desarrollan planes financieros para personas y organizaciones recopilando y analizando información de estados financieros, rendimientos, obligaciones financieras, inversiones, comportamiento del mercado de valores; hacen inversiones de títulos, acciones, obligaciones y otros valores financieros y administran fondos por cuenta propia. Se pueden desempeñar en empresas u organizaciones del sector público y privado, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"24","nombre":"PROFESIONALES DE NEGOCIOS Y DE ADMINISTRACIÓN"},"subgrupo":{"codigo":"241","nombre":"Profesionales en finanzas"},"grupo_primario":{"codigo":"2412","nombre":"Asesores financieros y de inversiones"}},"funciones":[{"consecutivo":1,"texto":"Atender y fidelizar los clientes de acuerdo con políticas institucionales, construir y mantener un registro de estos."},{"consecutivo":2,"texto":"Obtener y analizar información del mercado financiero con respecto a históricos, pronósticos económicos, antecedentes financieros, rendimientos y opciones de inversión utilizando reportes diarios."},{"consecutivo":3,"texto":"Recoger y analizar registros financieros de un negocio o cliente, como estados y obligaciones financieras, rendimientos, inversiones, presupuestos, proyecciones e información de ventas para valorar su competitividad o estimar su valor en el mercado, nivel de solvencia, tolerancia al riesgo y otra información necesaria para formular planes y recomendaciones financieras y estrategias de inversión."},{"consecutivo":4,"texto":"Asesorar, elaborar planes de inversión, estrategias, objetivos financieros y metas para empresas y clientes determinado por el análisis de tendencias de mercado de acuerdo con normativa y guía técnica."},{"consecutivo":5,"texto":"Intermediar en la compra y venta de títulos, obligaciones y otros valores de empresas o clientes particulares."},{"consecutivo":6,"texto":"Operar los negocios fiduciarios asignados y revisar transacciones e identificar potenciales inversiones para los clientes."},{"consecutivo":7,"texto":"Manejar portafolios de inversión, efectuar el seguimiento y evaluación del desempeño de las inversiones, examinar y revisar los planes de inversión sobre la base de la evolución de las necesidades y de las fluctuaciones de los mercados y garantizar que las transacciones de inversión se realicen de acuerdo con las regulaciones vigentes, metodología de riesgo de mercado de valores y utilizando herramientas especializadas."},{"consecutivo":8,"texto":"Gestionar y manejar la compra y venta de acciones, bonos y títulos para sus clientes."},{"consecutivo":9,"texto":"Recomendar y organizar la cobertura de seguro para los clientes."},{"consecutivo":10,"texto":"Administrar bienes, personales, de sociedades y otro tipo de fiducias, dirigir las cuentas de inversión, recibir y registrar cuentas de ingreso y desembolsar fondos fiduciarios."},{"consecutivo":11,"texto":"Desarrollar estrategias comerciales, revisando información y monitoreando condiciones del mercado desde la bolsa y a través de contactos con departamentos comerciales de otras firmas inversionistas y analistas financieros."},{"consecutivo":12,"texto":"Gestionar, monitorear y valorar contratos fiduciarios y de negocios de acuerdo con normativa, tipo de negocio, manual técnico y operativo y parámetros de mercado de valores."},{"consecutivo":13,"texto":"Identificar y buscar mecanismos de mitigación de riesgos de inversión, de tasas de cambio, liquidez y mercado."},{"consecutivo":14,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"24120.001","nombre":"Asesor de deuda / Asesora de deuda"},{"codigo":"24120.002","nombre":"Asesor de gestión de patrimonio / Asesora de gestión de patrimonio"},{"codigo":"24120.003","nombre":"Asesor de inversiones / Asesora de inversiones"},{"codigo":"24120.004","nombre":"Asesor de jubilación / Asesora de jubilación"},{"codigo":"24120.005","nombre":"Asesor de negocios institucional PYME (pequeña y mediana empresa) / Asesora de negocios institucional PYME (pequeña y mediana empresa)"},{"codigo":"24120.006","nombre":"Asesor de pensiones / Asesora de pensiones"},{"codigo":"24120.007","nombre":"Asesor de servicios financieros / Asesora de servicios financieros"},{"codigo":"24120.008","nombre":"Asesor financiero / Asesora financiera"},{"codigo":"24120.009","nombre":"Asistente fiduciario y de entidades financieras / Asistenta fiduciaria y de entidades financieras"},{"codigo":"24120.010","nombre":"Consultor de pensiones / Consultora de pensiones"},{"codigo":"24120.011","nombre":"Consultor de propiedad en inversión / Consultora de propiedad en inversión"},{"codigo":"24120.012","nombre":"Consultor en asesoramiento financiero / Consultora en asesoramiento financiero"},{"codigo":"24120.013","nombre":"Consultor financiero / Consultora financiera"},{"codigo":"24120.014","nombre":"Consultor y asesor a los clientes en inversión / Consultora y asesora a los clientes en inversión"},{"codigo":"24120.015","nombre":"Consultor y asesor de jubilación / Consultora y asesora de jubilación"},{"codigo":"24120.016","nombre":"Planificador de bienes raíces / Planificadora de bienes raíces"},{"codigo":"24120.017","nombre":"Planificador de patrimonio inmobiliario / Planificadora de patrimonio inmobiliario"},{"codigo":"24120.018","nombre":"Planificador financiero / Planificadora financiera"}],"conocimientos":[{"id":"3","nombre":"Economía"},{"id":"69","nombre":"Estadística"},{"id":"33","nombre":"Gestión financiera, administración bancaria y seguros"},{"id":"23","nombre":"Idioma extranjero"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"14","nombre":"Matemáticas"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"27","nombre":"Análisis de procesos"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"30","nombre":"Gestión de recursos financieros"},{"id":"5","nombre":"Lógica matemática"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"16","nombre":"Resolución de problemas complejos"},{"id":"34","nombre":"Trabajo bajo presión"}],"ocupaciones_afines":[{"codigo":"12112","nombre":"Directores y gerentes de seguros, bienes raíces y corretaje financiero / Directoras y gerentas de seguros, bienes raíces y corretaje financiero"},{"codigo":"12113","nombre":"Directores y gerentes de banca, crédito e inversiones / Directoras y gerentas de banca, crédito e inversiones"},{"codigo":"24111","nombre":"Contadores / Contadoras"},{"codigo":"24130","nombre":"Analistas financieros / Analistas financieras"},{"codigo":"24311","nombre":"Profesionales en mercadeo y publicidad"},{"codigo":"26310","nombre":"Economistas"},{"codigo":"33110","nombre":"Agentes de bolsa, cambio y otros servicios financieros"},{"codigo":"33132","nombre":"Asistentes financieros / Asistentas financieras"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"2412","ciuo08_obs":"Denominaciones completas","cno_codigo":"1112*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"1232*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Analistas financieros / Analistas financieras', '24130', 'Administración, finanzas y derecho', 4, false, '{"codigo":"24130","nombre":"Analistas financieros / Analistas financieras","descripcion":"Realizan el análisis cuantitativo de estados, rendimientos, obligaciones, inversiones financieras y sobre el comportamiento del mercado de valores y demás información que incida en los programas de inversión de las instituciones públicas o privadas de acuerdo con la normativa nacional e internacional. Se pueden desempeñar en organizaciones y departamentos contables y financieros, empresas especializadas de auditoría y análisis de mercados de valores, instituciones públicas y privadas, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"24","nombre":"PROFESIONALES DE NEGOCIOS Y DE ADMINISTRACIÓN"},"subgrupo":{"codigo":"241","nombre":"Profesionales en finanzas"},"grupo_primario":{"codigo":"2413","nombre":"Analistas financieros"}},"funciones":[{"consecutivo":1,"texto":"Analizar la información y proyecciones e inversiones financieras con el fin de elaborar pronósticos de las condiciones de negocios, la industria y la economía de acuerdo con normativa vigente y planes financieros para usar en la toma de decisiones de inversión y estimar su valor en el mercado."},{"consecutivo":2,"texto":"Actualizar permanentemente los conocimientos y permanecer al tanto de las novedades en los campos de la tecnología industrial, de negocios, las finanzas y la teoría económica para preparar, gestionar, ayudar en la elaboración y el control de planes financieros y presupuestales."},{"consecutivo":3,"texto":"Interpretar los datos de factores que inciden en los programas de inversión como los precios, la rentabilidad, la estabilidad, las tendencias futuras en cuanto a los riesgos de inversión y las influencias económicas."},{"consecutivo":4,"texto":"Efectuar el seguimiento de la evolución de la economía, industrial y empresarial mediante el análisis de la información obtenida de publicaciones y servicios financieros, entidades de la banca de inversión, organismos públicos, publicaciones comerciales, fuentes empresariales y entrevistas personales."},{"consecutivo":5,"texto":"Hacer recomendaciones de inversión en particular sobre los momentos más favorables a las empresas, al personal de las empresas de inversión o al público inversor en general."},{"consecutivo":6,"texto":"Analizar y determinar los precios a los que los valores deben ser sindicados para su oferta al público."},{"consecutivo":7,"texto":"Analizar y evaluar procesos de auditoría financiera y contable de acuerdo con estándares de calidad internos de la entidad u organización."},{"consecutivo":8,"texto":"Preparar, elaborar y estructurar planes de acción en materia de inversión con base en información y análisis financieros según normativa vigente y políticas institucionales."},{"consecutivo":9,"texto":"Evaluar y comparar la calidad relativa de diversos valores y costos de operaciones de acuerdo con métodos y tipo de costo en determinada industria."},{"consecutivo":10,"texto":"Presentar informes orales y escritos sobre las tendencias económicas generales, así como sobre determinadas empresas y de una rama de actividad completa."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"24130.001","nombre":"Analista agente de inversiones y finanzas"},{"codigo":"24130.002","nombre":"Analista de bonos"},{"codigo":"24130.003","nombre":"Analista de impuestos"},{"codigo":"24130.004","nombre":"Analista de inversiones"},{"codigo":"24130.005","nombre":"Analista de negocios fiduciarios"},{"codigo":"24130.006","nombre":"Analista de renta fija"},{"codigo":"24130.007","nombre":"Analista de valores"},{"codigo":"24130.008","nombre":"Analista financiero / Analista financiera"},{"codigo":"24130.009","nombre":"Analista financiero de inversiones / Analista financiera de inversiones"},{"codigo":"24130.010","nombre":"Analista y agente de inversiones"},{"codigo":"24130.011","nombre":"Consultor de análisis financiero de inversión / Consultora de análisis financiero de inversión"},{"codigo":"24130.012","nombre":"Consultor de valores / Consultora de valores"},{"codigo":"24130.013","nombre":"Analista de coberturas y mercados"},{"codigo":"24130.014","nombre":"Operador o negociante por cuenta propia (Trader) / Operadora o negociante por cuenta propia (Trader)"}],"conocimientos":[{"id":"32","nombre":"Contabilidad e impuestos"},{"id":"3","nombre":"Economía"},{"id":"69","nombre":"Estadística"},{"id":"33","nombre":"Gestión financiera, administración bancaria y seguros"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"14","nombre":"Matemáticas"},{"id":"4","nombre":"Mercadotecnia y publicidad"}],"destrezas":[{"id":"17","nombre":"Análisis de necesidades"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"30","nombre":"Gestión de recursos financieros"},{"id":"5","nombre":"Lógica matemática"},{"id":"6","nombre":"Pensamiento crítico"}],"ocupaciones_afines":[{"codigo":"12111","nombre":"Directores y gerentes financieros / Directoras y gerentas financieras"},{"codigo":"12112","nombre":"Directores y gerentes de seguros, bienes raíces y corretaje financiero / Directoras y gerentas de seguros, bienes raíces y corretaje financiero"},{"codigo":"12113","nombre":"Directores y gerentes de banca, crédito e inversiones / Directoras y gerentas de banca, crédito e inversiones"},{"codigo":"24112","nombre":"Auditores financieros y contables / Auditoras financieras y contables"},{"codigo":"24120","nombre":"Asesores financieros y de inversiones / Asesoras financieras y de inversiones"},{"codigo":"24311","nombre":"Profesionales en mercadeo y publicidad"},{"codigo":"26310","nombre":"Economistas"},{"codigo":"33110","nombre":"Agentes de bolsa, cambio y otros servicios financieros"},{"codigo":"33131","nombre":"Asistentes contables / Asistentas contables"},{"codigo":"33132","nombre":"Asistentes financieros / Asistentas financieras"},{"codigo":"33133","nombre":"Asistentes de tesorería / Asistentas de tesorería"},{"codigo":"43110","nombre":"Auxiliares de contabilidad, costos y tesorería"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"2413","ciuo08_obs":"Denominaciones completas","cno_codigo":"1111*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"1112*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"1232*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Profesionales y analistas de gestión y organización', '24210', 'Administración, finanzas y derecho', 4, false, '{"codigo":"24210","nombre":"Profesionales y analistas de gestión y organización","descripcion":"Orientan y acompañan a las organizaciones a lograr una mayor eficiencia, productividad, calidad, competitividad, a identificar sus necesidades y resolver problemas organizacionales, para lo cual diagnostican, planean, sensibilizan, implementan cambios y coordinan su ejecución, por medio del análisis y estudio de las estructuras, métodos, sistemas, operaciones y procedimientos de la organización, considerando también el diseño, optimización, mejoramiento, innovación y la gestión de los procesos empresariales, de acuerdo con la planeación estratégica. Se pueden desempeñar en firmas de consultoría administrativa, en empresas de producción y fabricación, en organizaciones del sector público o privado, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"24","nombre":"PROFESIONALES DE NEGOCIOS Y DE ADMINISTRACIÓN"},"subgrupo":{"codigo":"242","nombre":"Profesionales de la administración"},"grupo_primario":{"codigo":"2421","nombre":"Profesionales y analistas de gestión y organización"}},"funciones":[{"consecutivo":1,"texto":"Liderar procesos de mentoría para el fortalecimiento de modelos de negocio y el fomento del emprendimiento."},{"consecutivo":2,"texto":"Analizar, proponer, asesorar y evaluar los sistemas y las estructuras existentes, los métodos y los procesos de las empresas y las organizaciones."},{"consecutivo":3,"texto":"Planear y ejecutar rediseños a métodos, sistemas, procedimientos, programas y operaciones actuales incluyendo la perspectiva del personal y la observación de los sistemas en todos los procesos de la organización de acuerdo con estrategias de gestión administrativa."},{"consecutivo":4,"texto":"Orientar a los clientes internos y externos hacia una organización más eficiente, tomar decisiones y desarrollar soluciones a problemas organizacionales de acuerdo con políticas, estrategias de gestión y procesos administrativos."},{"consecutivo":5,"texto":"Emprender, coordinar, desarrollar y revisar estudios de dimensionamiento y optimización de la estructura organizacional del trabajo mediante el análisis del entorno, los métodos y los procedimientos existentes y propuestos."},{"consecutivo":6,"texto":"Diseñar, determinar e implementar estrategias de mercado de acuerdo con la situación de la organización, la competencia, el posicionamiento, la satisfacción del cliente y los procesos administrativos."},{"consecutivo":7,"texto":"Planear, orientar y coordinar procesos de atención a clientes de acuerdo con investigaciones, estrategias de gestión y procesos administrativos."},{"consecutivo":8,"texto":"Analizar y emitir informes asociados a la gestión y los procesos organizacionales, para la toma de decisiones de acuerdo con estándares nacionales e internacionales."},{"consecutivo":9,"texto":"Elaborar, analizar, ajustar, documentar e implementar diagramas de flujo de trabajo, manuales de procedimientos, de competencias y de funciones de acuerdo con registros, informes, recomendaciones, instrucciones y otros tipos de documentos, que aporten al mejoramiento de los procesos de la organización."},{"consecutivo":10,"texto":"Preparar analizar y formular propuestas, proyectos para revisar métodos y procedimientos, resolver problemas organizacionales de acuerdo con estrategias de gestión y procesos administrativos."},{"consecutivo":11,"texto":"Revisar y realizar seguimientos a las actividades de la organización, los procedimientos operativos y brindar asesoramiento en planes de acción, sobre las desviaciones y las oportunidades de mejora con respecto a los procedimientos y las normas de acuerdo con los procesos administrativos."},{"consecutivo":12,"texto":"Planear, administrar y controlar presupuestos incluyendo la clasificación, la verificación, la comparación y la cuantificación de costos operacionales, estudios de métodos, tiempos y movimientos, de acuerdo con métodos vigentes de la entidad o la organización, estrategias de gestión y procesos administrativos."},{"consecutivo":13,"texto":"Analizar, planear, coordinar y evaluar la definición o los ajustes del modelo de gestión de procesos."},{"consecutivo":14,"texto":"Definir, ajustar y documentar los métodos que definen el modelo de procesos, así como el diseño y el ajuste de los procesos organizacionales."},{"consecutivo":15,"texto":"Diseñar, proponer, desarrollar, coordinar y hacer seguimiento a la implementación de planes y estrategias de aprendizaje y desarrollo del recurso humano, para cerrar brechas, lograr y fortalecer las competencias necesarias en los trabajadores y mejorar el desempeño."},{"consecutivo":16,"texto":"Asesorar en la formulación, el desarrollo, la coordinación y la evaluación de proyectos de inversión de la organización."},{"consecutivo":17,"texto":"Diseñar, implementar y hacer seguimiento a los instrumentos de medición de clima organizacional, desarrollo de competencias y gestión del cambio dentro de la organización."},{"consecutivo":18,"texto":"Proponer, diseñar y liderar la ejecución de actividades internas enfocadas en afianzar la cultura organizacional y el buen clima de esta."},{"consecutivo":19,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"24210.001","nombre":"Analista administrativo / Analista administrativa"},{"codigo":"24210.002","nombre":"Analista de clima y cultura organizacional"},{"codigo":"24210.003","nombre":"Analista de costos"},{"codigo":"24210.004","nombre":"Analista de costos y economía financiera"},{"codigo":"24210.005","nombre":"Analista de cultura organizacional"},{"codigo":"24210.006","nombre":"Analista de desarrollo organizacional"},{"codigo":"24210.007","nombre":"Analista de gestión"},{"codigo":"24210.008","nombre":"Analista de gestión del cambio organizacional"},{"codigo":"24210.009","nombre":"Analista de métodos y procedimientos"},{"codigo":"24210.010","nombre":"Analista de organización y métodos"},{"codigo":"24210.011","nombre":"Analista de producción"},{"codigo":"24210.012","nombre":"Analista de tiempos y movimientos"},{"codigo":"24210.013","nombre":"Analista organizacional"},{"codigo":"24210.014","nombre":"Asesor de empresas / Asesora de empresas"},{"codigo":"24210.015","nombre":"Consultor administrativo / Consultora administrativa"},{"codigo":"24210.016","nombre":"Consultor de gestión / Consultora de gestión"},{"codigo":"24210.017","nombre":"Consultor de negocios / Consultora de negocios"},{"codigo":"24210.018","nombre":"Consultor empresarial / Consultora empresarial"},{"codigo":"24210.019","nombre":"Consultor organizacional / Consultora organizacional"},{"codigo":"24210.020","nombre":"Especialista en eficiencia empresarial"},{"codigo":"24210.021","nombre":"Facilitador de calidad / Facilitadora de calidad"},{"codigo":"24210.022","nombre":"Inspector de calidad de servicios / Inspectora de calidad de servicios"},{"codigo":"24210.023","nombre":"Profesional de diseño y desarrollo organizacional"},{"codigo":"24210.025","nombre":"Analista de prospectiva e innovación empresarial"},{"codigo":"24210.026","nombre":"Asesor de emprendimiento / Asesora de emprendimiento"},{"codigo":"24210.028","nombre":"Consultor en dirección de empresa / Consultora en dirección de empresa"},{"codigo":"24210.029","nombre":"Consultor en gestión general y estratégica empresarial / Consultora en gestión general y estratégica empresarial"},{"codigo":"24210.030","nombre":"Consultor en privatización / Consultora en privatización"},{"codigo":"24210.031","nombre":"Consultor en sector no estructurado / Consultora en sector no estructurado"},{"codigo":"24210.032","nombre":"Analista de calidad en la organización"},{"codigo":"24210.033","nombre":"Analista de prospectiva empresarial"},{"codigo":"24210.034","nombre":"Asesor en privatización / Asesora en privatización"},{"codigo":"24210.035","nombre":"Asesor de organización y métodos / Asesora de organización y métodos"},{"codigo":"24210.036","nombre":"Gestor de calidad en la organización / Gestora de calidad en la organización"},{"codigo":"24210.037","nombre":"Gestor de emprendimiento / Gestora de emprendimiento"},{"codigo":"24210.038","nombre":"Gestor de proyectos organizacionales / Gestora de proyectos organizacionales"},{"codigo":"24210.039","nombre":"Profesional socioempresarial"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"1","nombre":"Gerencia y administración"},{"id":"6","nombre":"Gestión del talento humano y de personal"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"102","nombre":"Metodología e investigación"},{"id":"7","nombre":"Producción y procesamiento"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"16","nombre":"Resolución de problemas complejos"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"12199","nombre":"Directores y gerentes de administración y servicios no clasificados en otras ocupaciones / Directoras y gerentas de administración y servicios no clasificados en otras ocupaciones"},{"codigo":"21410","nombre":"Ingenieros industriales y de producción / Ingenieras industriales y de producción"},{"codigo":"24231","nombre":"Profesionales de talento humano"},{"codigo":"24241","nombre":"Profesionales de formación y desarrollo de personal"},{"codigo":"33411","nombre":"Supervisores administrativos / Supervisoras administrativas"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"2421","ciuo08_obs":"Denominaciones completas","cno_codigo":"1122*","cno_obs":"Denominaciones parciales"},