  ('rol_cuoc', 'Profesionales de talento humano', '24231', 'Administración, finanzas y derecho', 4, false, '{"codigo":"24231","nombre":"Profesionales de talento humano","descripcion":"Administran, diseñan, implementan y evalúan políticas, programas, proyectos y procedimientos de talento humano; asesoran a gerentes, líderes de procesos y empleados en temas de talento humano. Se pueden desempeñar en empresas particulares, entidades del gobierno, organizaciones de consultoría organizacional, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"24","nombre":"PROFESIONALES DE NEGOCIOS Y DE ADMINISTRACIÓN"},"subgrupo":{"codigo":"242","nombre":"Profesionales de la administración"},"grupo_primario":{"codigo":"2423","nombre":"Profesionales de gestión de talento humano"}},"funciones":[{"consecutivo":1,"texto":"Asesorar a gerentes y empleados sobre la contratación, la selección, la formación y el desarrollo, la promoción, la remuneración, los programas de beneficios a los empleados, los acuerdos colectivos, el análisis ocupacional y la estructura organizacional, la gestión de las relaciones de los empleados u otras áreas de las políticas, los procesos y los procedimientos en talento humano."},{"consecutivo":2,"texto":"Estudiar, analizar y elaborar la escala salarial y la descripción de cargos en un determinado empleo según las políticas y la estructura de la organización."},{"consecutivo":3,"texto":"Diseñar e implementar políticas, programas y procedimientos de talento humano y relaciones laborales."},{"consecutivo":4,"texto":"Implementar y desarrollar procesos de atracción, evaluación, selección y contratación de personal de acuerdo con las políticas y la normativa de la organización."},{"consecutivo":5,"texto":"Construir e implementar programas de bienestar de personal, calidad de vida, clima y cultura y el apoyo a la implementación de la seguridad y la salud en el trabajo, de acuerdo con las políticas y la normativa de la organización."},{"consecutivo":6,"texto":"Analizar y preparar información profesional, ocupacional y funcional basados en los sistemas de clasificación de ocupaciones."},{"consecutivo":7,"texto":"Asesorar y analizar los puestos de trabajo y las ocupaciones en ámbitos como la administración de personal, la investigación y la planificación de la fuerza laboral, la capacitación o la información ocupacional y la orientación profesional."},{"consecutivo":8,"texto":"Construir e implementar programas y/o procesos de formación, capacitación, desarrollo y evaluación del desempeño que permita potencializar el perfil de los empleados de acuerdo con las políticas y la normativa de la organización."},{"consecutivo":9,"texto":"Implementar estrategias de retención del talento humano a través de las políticas, los programas y los mecanismos establecidos por la organización."},{"consecutivo":10,"texto":"Desarrollar planes y programas de compensación y beneficios para los empleados de acuerdo con las políticas y la normativa de la organización."},{"consecutivo":11,"texto":"Realizar acompañamientos a los procesos disciplinarios y/o de relaciones laborales de acuerdo con las políticas y la normativa de la organización."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"24231.001","nombre":"Analista de empleos"},{"codigo":"24231.003","nombre":"Analista de gestión humana"},{"codigo":"24231.004","nombre":"Analista de ocupaciones"},{"codigo":"24231.005","nombre":"Analista de puestos de trabajo"},{"codigo":"24231.006","nombre":"Analista de salarios"},{"codigo":"24231.007","nombre":"Analista de selección"},{"codigo":"24231.008","nombre":"Analista de talento humano"},{"codigo":"24231.009","nombre":"Analista de trabajo"},{"codigo":"24231.010","nombre":"Analista ocupacional"},{"codigo":"24231.011","nombre":"Árbitro de relaciones laborales / Árbitra de relaciones laborales"},{"codigo":"24231.012","no