  ('rol_cuoc', 'Consejeros de servicios de empleo / Consejeras de servicios de empleo', '24232', 'Administración, finanzas y derecho', 4, false, '{"codigo":"24232","nombre":"Consejeros de servicios de empleo / Consejeras de servicios de empleo","descripcion":"Suministran asistencia, consejería e información a solicitantes de empleo sobre aspectos relacionados con su búsqueda y orientación profesional, asesoran e informan a empleadores sobre oferta laboral y mercado de trabajo. Se pueden desempeñar en organizaciones de consultoría, entidades del gobierno, agencias de servicio de empleo público y privadas, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"24","nombre":"PROFESIONALES DE NEGOCIOS Y DE ADMINISTRACIÓN"},"subgrupo":{"codigo":"242","nombre":"Profesionales de la administración"},"grupo_primario":{"codigo":"2423","nombre":"Profesionales de gestión de talento humano"}},"funciones":[{"consecutivo":1,"texto":"Estudiar y asesorar a las personas sobre las oportunidades de empleo, elección de carrera y la educación o formación que pueda convenirles."},{"consecutivo":2,"texto":"Coordinar el suministro de servicios de consejería e información para estudiantes, padres, profesores y empleadores, sobre mercado laboral, empleabilidad, orientación ocupacional, sesiones de desarrollo profesional e interacciones con otras instituciones."},{"consecutivo":3,"texto":"Entrevistar a los solicitantes para obtener la historia laboral, los antecedentes educativos y las aspiraciones laborales."},{"consecutivo":4,"texto":"Identificar las dificultades para emplearse y ayudar al interesado a desarrollar habilidades, aptitudes y estrategias de búsqueda de trabajo."},{"consecutivo":5,"texto":"Establecer la necesidad de orientación, rehabilitación, entrenamiento o capacitación y remitir los interesados a los servicios correspondientes."},{"consecutivo":6,"texto":"Administrar e interpretar pruebas diseñadas para determinar los intereses, las aptitudes y las habilidades del solicitante de empleo."},{"consecutivo":7,"texto":"Recopilar información del mercado laboral relacionada con vacantes, requisitos, funciones y otra información ocupacional."},{"consecutivo":8,"texto":"Asesorar a empleadores sobre oferta laboral y aspectos relacionados con el mercado de trabajo."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"24232.001","nombre":"Asesor de empleo / Asesora de empleo"},{"codigo":"24232.002","nombre":"Asesor de orientación profesional / Asesora de orientación profesional"},{"codigo":"24232.003","nombre":"Cazatalentos"},{"codigo":"24232.004","nombre":"Consejero de adaptación laboral / Consejera de adaptación laboral"},{"codigo":"24232.005","nombre":"Consejero de empleo / Consejera de empleo"},{"codigo":"24232.006","nombre":"Consejero de orientación profesional / Consejera de orientación profesional"},{"codigo":"24232.007","nombre":"Consejero de readaptación laboral / Consejera de readaptación laboral"},{"codigo":"24232.008","nombre":"Consejero de servicios de empleo / Consejera de servicios de empleo"},{"codigo":"24232.009","nombre":"Consejero educativo de orientación vocacional / Consejera educativa de orientación vocacional"},{"codigo":"24232.010","nombre":"Consejero ocupacional / Consejera ocupacional"},{"codigo":"24232.011","nombre":"Consultor de empleo / Consultora de empleo"},{"codigo":"24232.012","nombre":"Especialista en orientación profesional"},{"codigo":"24232.013","nombre":"Experto en recolocación / Experta en recolocación"},{"codigo":"24232.014","nombre":"Experto en recolocación laboral / Experta en recolocación laboral"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"6","nombre":"Gestión del talento humano y de personal"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"50","nombre":"Servicio a la persona y humanización"},{