  ('rol_cuoc', 'Profesionales de formación y desarrollo de personal', '24241', 'Administración, finanzas y derecho', 4, false, '{"codigo":"24241","nombre":"Profesionales de formación y desarrollo de personal","descripcion":"Planifican, desarrollan, implementan y evalúan programas de capacitación y desarrollo a fin de asegurar que la dirección y el personal adquieran las destrezas y perfeccionen las competencias que las organizaciones requieren para cumplir con los objetivos organizacionales. Se pueden desempeñar en organizaciones de consultoría, entidades del gobierno, empresas privadas, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"24","nombre":"PROFESIONALES DE NEGOCIOS Y DE ADMINISTRACIÓN"},"subgrupo":{"codigo":"242","nombre":"Profesionales de la administración"},"grupo_primario":{"codigo":"2424","nombre":"Profesionales en formación, desarrollo de personal y evaluación de competencias"}},"funciones":[{"consecutivo":1,"texto":"Identificar las necesidades y los requerimientos de formación de las personas y organizaciones."},{"consecutivo":2,"texto":"Establecer los objetivos de desarrollo de recursos humanos y evaluar los resultados del aprendizaje."},{"consecutivo":3,"texto":"Preparar y elaborar material didáctico y ayudas de formación que prestan apoyo a la formación, tales como: manuales, medios visuales, tutoriales en línea, modelos de demostración y documentación de referencia."},{"consecutivo":4,"texto":"Diseñar, coordinar, programar y desarrollar programas de capacitación del talento humano que pueden ser impartidos en forma individual y en grupo, y facilitar la realización de talleres, reuniones, demostraciones y conferencias."},{"consecutivo":5,"texto":"Servir de contacto con los proveedores externos de capacitación para organizar la aplicación de programas específicos de formación y desarrollo."},{"consecutivo":6,"texto":"Promover interna y externamente la formación y el desarrollo de programas de capacitación y evaluar esas actividades promocionales."},{"consecutivo":7,"texto":"Realizar el seguimiento y la evaluación continua de la calidad y la eficacia de la formación interna y externa y revisar y modificar los objetivos y métodos de la formación, así como los resultados concretos previstos para los cursos."},{"consecutivo":8,"texto":"Buscar, reunir y examinar materiales de apoyo con el objeto de comprender los diversos temas y sistemas objeto de la formación."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"24241.001","nombre":"Asesor de capacitación / Asesora de capacitación"},{"codigo":"24241.002","nombre":"Consultor de formación y desarrollo de personal / Consultora de formación y desarrollo de personal"},{"codigo":"24241.003","nombre":"Coordinador de capacitación / Coordinadora de capacitación"},{"codigo":"24241.004","nombre":"Entrenador ejecutivo / Entrenadora ejecutiva"},{"codigo":"24241.005","nombre":"Especialista en desarrollo de fuerza de trabajo"},{"codigo":"24241.006","nombre":"Especialista en desarrollo de fuerza laboral"},{"codigo":"24241.007","nombre":"Especialista en desarrollo de personal"},{"codigo":"24241.008","nombre":"Funcionario de desarrollo de personal / Funcionaria de desarrollo de personal"},{"codigo":"24241.009","nombre":"Funcionario de entrenamiento de personal / Funcionaria de entrenamiento de personal"},{"codigo":"24241.010","nombre":"Instructor de desarrollo de personal / Instructora de desarrollo de personal"},{"codigo":"24241.011","nombre":"Profesional de desarrollo de personal"},{"codigo":"24241.012","nombre":"Profesional de formación de personal"},{"codigo":"24241.013","nombre":"Coach de vida"},{"codigo":"24241.014","nombre":"Coach ejecutivo / Coach ejecutiva"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"6","nombre":"Gestión del talento humano y de personal"},{"id":"28","nombre":"Leyes y gobierno"}