  ('rol_cuoc', 'Evaluadores de competencias laborales / Evaluadoras de competencias laborales', '24242', 'Administración, finanzas y derecho', 4, false, '{"codigo":"24242","nombre":"Evaluadores de competencias laborales / Evaluadoras de competencias laborales","descripcion":"Planifican, desarrollan, implementan y evalúan programas de evaluación de destrezas y competencias laborales. Emiten juicio sobre las capacidades de las personas para el desempeño laboral en ocupaciones específicas, con referencia a competencias estandarizadas, establecidas por el Estado, organizaciones empresariales sectoriales o empresas. Desarrollan procesos, procedimientos e instrumentos de recopilación de evidencias de los desempeños con base en su conocimiento y experiencia en los procesos y resultados propios de la ocupación o campo ocupacional en que se evalúan y de los principios y métodos de evaluación. Se pueden desempeñar en organizaciones de consultoría, organismos certificadores de competencias, empresas privadas, entidades públicas, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"24","nombre":"PROFESIONALES DE NEGOCIOS Y DE ADMINISTRACIÓN"},"subgrupo":{"codigo":"242","nombre":"Profesionales de la administración"},"grupo_primario":{"codigo":"2424","nombre":"Profesionales en formación, desarrollo de personal y evaluación de competencias"}},"funciones":[{"consecutivo":1,"texto":"Coordinar programas empresariales, sectoriales o regionales de evaluación de competencias laborales."},{"consecutivo":2,"texto":"Elaborar proyectos de evaluación de competencias laborales, establecer los objetivos del desarrollo de los proyectos y evaluar los resultados de estos."},{"consecutivo":3,"texto":"Concertar planes de evaluación con directores de recursos humanos, gerentes y coordinadores de proyectos de evaluación de competencias laborales."},{"consecutivo":4,"texto":"Programar actividades de evaluación de competencia laborales con las personas sujetos de evaluación."},{"consecutivo":5,"texto":"Asesorar a las personas sujetos de evaluación para el desarrollo del proceso de evaluación, en actividades, como el análisis de los estándares de competencia, la autoevaluación de competencias, la recopilación de evidencias de competencia, las opciones para superar deficiencias, los instrumentos de evaluación."},{"consecutivo":6,"texto":"Asistir a las personas sujetos de evaluación de competencias laborales en la especificación de necesidades de formación para satisfacer los estándares de competencia de una ocupación y, también, para desarrollar itinerarios de avance en campos ocupacionales y áreas de desempeño laboral."},{"consecutivo":7,"texto":"Emitir juicio sobre las competencias de las personas sujetos de evaluación, aplicando los principios, procedimientos y técnicas de evaluación establecidos."},{"consecutivo":8,"texto":"Registrar los resultados de los procesos de evaluación de competencias laborales."},{"consecutivo":9,"texto":"Mantener la integridad y confidencialidad de la información que se genera en los procesos de evaluación de competencias laborales."},{"consecutivo":10,"texto":"Realizar el seguimiento continuo de la calidad y la eficacia de la evaluación de competencia laborales, y revisar y modificar los objetivos y métodos de la evaluación, así como los resultados concretos previstos para las evaluaciones."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"24242.001","nombre":"Analista evaluador de desempeño / Analista evaluadora de desempeño"},{"codigo":"24242.002","nombre":"Consultor de competencias laborales / Consultora de competencias laborales"},{"codigo":"24242.003","nombre":"Evaluador de competencias laborales / Evaluadora de competencias laborales"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"6","nombre":"Gestión del talento humano y de personal"},{"id":"34","nombr