  ('rol_cuoc', 'Profesionales en mercadeo y publicidad', '24311', 'Comercio, mercadeo y publicidad', 4, false, '{"codigo":"24311","nombre":"Profesionales en mercadeo y publicidad","descripcion":"Detectan, planifican y desarrollan oportunidades en mercados tradicionales y digitales para bienes y servicios nuevos y existentes mediante la investigación del consumidor y la proyección de tendencias del entorno; crean, diseñan, elaboran, editan y coordinan programas estratégicos de mercadeo, campañas, mensajes publicitarios y posicionamiento de marca a través de diferentes canales; determinan, gestionan, ejecutan y evalúan las acciones estratégicas y tácticas asociadas a las actividades de mercadeo y publicidad; establecen y mantienen relaciones corporativas con sus clientes, actuando bajo criterios de responsabilidad social corporativa, sostenibilidad y sustentabilidad. Se pueden desempeñar en empresas y organizaciones oficiales o privadas, agencias de publicidad, mercadeo y relaciones públicas, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"24","nombre":"PROFESIONALES DE NEGOCIOS Y DE ADMINISTRACIÓN"},"subgrupo":{"codigo":"243","nombre":"Profesionales de las ventas, la comercialización y las relaciones públicas"},"grupo_primario":{"codigo":"2431","nombre":"Profesionales de la publicidad y la comercialización"}},"funciones":[{"consecutivo":1,"texto":"Detectar oportunidades en mercados tradicionales y digitales para bienes y servicios nuevos y existentes."},{"consecutivo":2,"texto":"Gestionar y desarrollar programas estratégicos, campañas, marcas y políticas de mercadeo, publicidad y promoción de acuerdo con los objetivos comerciales, los lineamientos, los planes organizacionales y las tendencias del entorno."},{"consecutivo":3,"texto":"Realizar actividades de asesoría, consultoría y asistencia sobre estrategias de mercadeo y campañas publicitarias, motivar el consumo y promover eficazmente las cualidades de los bienes y los servicios ofrecidos para llegar al mercado objetivo de acuerdo con requerimientos del cliente y del consumidor, según condiciones del mercado."},{"consecutivo":4,"texto":"Coordinar la preparación, el acopio, la selección, la redacción y la edición de material publicitario con el fin de conseguir el efecto deseado según las necesidades de los clientes y las estrategias de mercadeo."},{"consecutivo":5,"texto":"Planear, orientar y desarrollar investigaciones sobre el consumidor, las condiciones, las características y las tendencias del mercado local, regional, nacional e internacional, relacionados con el mercadeo y la publicidad."},{"consecutivo":6,"texto":"Planear y desarrollar estrategias de mercadeo y publicidad de acuerdo con necesidades del cliente, objetivos de la organización o los resultados de la investigación de mercado."},{"consecutivo":7,"texto":"Monitorear y evaluar el impacto de las estrategias y las campañas de acuerdo con el plan estratégico de mercadeo y sus resultados."},{"consecutivo":8,"texto":"Desarrollar e implementar modelos y métodos de comercialización tradicional y digital fundamentado en estudios e investigaciones relacionadas con el comportamiento del consumidor y/o las necesidades del sector"},{"consecutivo":9,"texto":"Diseñar y coordinar el desarrollo de piezas publicitarias y organizar la producción y la colocación de estas en medios de comunicación convencionales y digitales de acuerdo con los resultados de los estudios de marketing."},{"consecutivo":10,"texto":"Diseñar, proponer, implementar y gestionar políticas, objetivos, planes y programas de mercadeo para el crecimiento y el desarrollo de la actividad empresarial."},{"consecutivo":11,"texto":"Generar y promover procesos de investigación, innovación y desarrollo (I+I+D) de conceptos, productos y servicios asociados a mercadeo y publicidad, junto a clientes y grupos de interés."},{"consecutivo":12,"texto":"Construir, redactar y modificar textos publicitarios y guiones para medios de comunicación y producción audiovisual."},{"consecutivo":13,"texto":"Detectar oportunidades en mercados tradicionales y digitales para bienes y servicios nuevos y existentes."},{"consecutivo":14,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"24311.001","nombre":"Analista de comportamiento del consumidor"},{"codigo":"24311.002","nombre":"Analista de datos de mercado"},{"codigo":"24311.003","nombre":"Analista de estudio de mercados"},{"codigo":"24311.004","nombre":"Analista de investigación de mercados"},{"codigo":"24311.005","nombre":"Analista de mercadeo"},{"codigo":"24311.006","nombre":"Analista de mercados"},{"codigo":"24311.007","nombre":"Asesor de mercadeo / Asesora de mercadeo"},{"codigo":"24311.008","nombre":"Asesor de publicidad / Asesora de publicidad"},{"codigo":"24311.009","nombre":"Autor publicitario / Autora publicitaria"},{"codigo":"24311.010","nombre":"Consultor comercial / Consultora comercial"},{"codigo":"24311.011","nombre":"Consultor de investigación de mercados / Consultora de investigación de mercados"},{"codigo":"24311.012","nombre":"Consultor de mercadeo / Consultora de mercadeo"},{"codigo":"24311.013","nombre":"Consultor de mercados / Consultora de mercados"},{"codigo":"24311.014","nombre":"Consultor de publicidad / Consultora de publicidad"},{"codigo":"24311.015","nombre":"Consultor publicista / Consultora publicista"},{"codigo":"24311.016","nombre":"Creativo de publicidad / Creativa de publicidad"},{"codigo":"24311.017","nombre":"Ejecutivo de cuenta en mercadeo / Ejecutiva de cuenta en mercadeo"},{"codigo":"24311.018","nombre":"Ejecutivo de cuenta en publicidad / Ejecutiva de cuenta en publicidad"},{"codigo":"24311.019","nombre":"Ejecutivo de cuenta publicitaria / Ejecutiva de cuenta publicitaria"},{"codigo":"24311.021","nombre":"Especialista en mercadeo"},{"codigo":"24311.022","nombre":"Especialista en métodos de promoción en ventas"},{"codigo":"2431