  ('rol_cuoc', 'Profesionales en negocios internacionales', '24313', 'Comercio, mercadeo y publicidad', 4, false, '{"codigo":"24313","nombre":"Profesionales en negocios internacionales","descripcion":"Analizan e identifican oportunidades comerciales en mercados internacionales e intermedian en procesos de negociación comercial con clientes o socios extranjeros. Se pueden desempeñar en agencias del gobierno, empresas multinacionales o firmas especializadas en negocios internacionales, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"24","nombre":"PROFESIONALES DE NEGOCIOS Y DE ADMINISTRACIÓN"},"subgrupo":{"codigo":"243","nombre":"Profesionales de las ventas, la comercialización y las relaciones públicas"},"grupo_primario":{"codigo":"2431","nombre":"Profesionales de la publicidad y la comercialización"}},"funciones":[{"consecutivo":1,"texto":"Investigar, analizar y recolectar información sobre el comportamiento de los mercados internacionales."},{"consecutivo":2,"texto":"Analizar el mercado nacional e internacional utilizando metodologías y técnicas de comparación de indicadores clave de negocio, entre otras."},{"consecutivo":3,"texto":"Identificar oportunidades y socios comerciales en mercados extranjeros."},{"consecutivo":4,"texto":"Contactar y gestionar negociaciones con clientes, proveedores o socios identificados a nivel internacional."},{"consecutivo":5,"texto":"Planear, realizar y coordinar la apertura de nuevos mercados en el exterior de acuerdo con normatividad y protocolos establecidos."},{"consecutivo":6,"texto":"Intermediar, en representación de la empresa, como negociador con socios o aliados comerciales internacionales."},{"consecutivo":7,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"24313.001","nombre":"Analista de negocios internacionales"},{"codigo":"24313.002","nombre":"Profesional en negocios internacionales"}],"conocimientos":[{"id":"3","nombre":"Economía"},{"id":"1","nombre":"Gerencia y administración"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"4","nombre":"Mercadotecnia y publicidad"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"5","nombre":"Lógica matemática"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"12","nombre":"Persuasión"},{"id":"16","nombre":"Resolución de problemas complejos"},{"id":"34","nombre":"Trabajo bajo presión"}],"ocupaciones_afines":[{"codigo":"12212","nombre":"Directores y gerentes de comercio exterior / Directoras y gerentas de comercio exterior"},{"codigo":"24311","nombre":"Profesionales en mercadeo y publicidad"},{"codigo":"26310","nombre":"Economistas"}],"area_principal":{"sigla":"COMP","nombre":"Comercio, mercadeo y publicidad"},"areas_complementarias":[{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"}],"equivalencias":[{"ciuo08_codigo":"2431*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"","cno_obs":""}]}'::jsonb),
  ('rol_cuoc', 'Profesionales de relaciones públicas y comunicaciones', '24320', 'Comercio, mercadeo y publicidad', 4, false, '{"codigo":"24320","nombre":"Profesionales de relaciones públicas y comunicaciones","descripcion":"Planifican, desarrollan y evalúan estrategias de información y comunicación que gestionan una comprensión y reputación favorable de las organizaciones, sus productos y servicios, y la relación con los grupos de interés. Se pueden desempeñar en entidades públicas y organizaciones privadas como firmas de consultoría, agencias, corporaciones, asociaciones, instituciones sociales, educativas, medios de comunicación, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"24","nombre":"PROFESIONALES DE NEGOCIOS Y DE ADMINISTRACIÓN"},"subgrupo":{"codigo":"243","nombre":"Profesionales de las ventas, la comercialización y las relaciones públicas"},"grupo_primario":{"codigo":"2432","nombre":"Profesionales de relaciones públicas y comunicaciones"}},"funciones":[{"consecutivo":1,"texto":"Planificar, organizar, desarrollar y evaluar campañas promocionales, estrategias y programas de comunicación diseñados para informar a clientes, empleados y público en general sobre iniciativas y políticas de los negocios, los gobiernos y otras organizaciones."},{"consecutivo":2,"texto":"Brindar asesoramiento a los directivos sobre las repercusiones que sus políticas, programas y prácticas tienen sobre las relaciones públicas."},{"consecutivo":3,"texto":"Llevar a cabo o encomendar estudios de opinión pública, analizar los resultados y planificar campañas de relaciones públicas y promocionales."},{"consecutivo":4,"texto":"Investigar, preparar y vigilar la programación de informes, resúmenes, bibliografías, discursos, presentaciones, folletos, boletines, comunicados de prensa y otro material."},{"consecutivo":5,"texto":"Revisar y proponer los contenidos y la preparación de folletos, informes, boletines, fotografías y otros materiales ilustrativos, controlando su divulgación."},{"consecutivo":6,"texto":"Seleccionar, evaluar y revisar el material presentado por escritores de promoción de relaciones públicas, fotógrafos, ilustradores y otros profesionales para crear publicidad favorable."},{"consecutivo":7,"texto":"Organizar eventos especiales, seminarios, espectáculos, concursos y eventos sociales para promover el buen nombre y la publicidad favorable."},{"consecutivo":8,"texto":"Asistir a eventos empresariales, sociales y de otra índole para promover a la organización."},{"consecutivo":9,"texto":"Representar a organizaciones y concertar entrevistas con medios publicitarios y conferencias."},{"consecutivo":10,"texto":"Actuar como portavoz de una organización y responder preguntas orales, escritas, en medios digitales y redes sociales."},{"consecutivo":11,"texto":"Acopiar, investigar y redactar material para auditorios internos y externos."},{"consecutivo":12,"texto":"Iniciar y mantener relaciones con medios de comunicación."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"24320.001","nombre":"Agente promotor de relaciones públicas / Agente promotora de relaciones públicas"},{"codigo":"24320.002","nombre":"Agente de relaciones públicas"},{"codigo":"24320.003","nombre":"Analista de relaciones interinstitucionales"},{"codigo":"24320.004","nombre":"Analista de relaciones internacionales"},{"codigo":"24320.005","nombre":"Asesor de comunicaciones / Asesora de comunicaciones"},{"codigo":"24320.006","nombre":"Cabildero / Cabildera"},{"codigo":"24320.007","nombre":"Consultor de comunicaciones / Consultora de comunicaciones"},{"codigo":"24320.008","nombre":"Consultor de relaciones públicas / Consultora de relaciones públicas"},{"codigo":"24320.009","nombre":"Coordinador de medios de comunicación / Coordinadora de medios de comunicación"},{"codigo":"24320.010","nombre":"Ejecutivo de cuenta de relaciones públicas / Ejecutiva de cuenta de relaciones públicas"},{"codigo":"24320.011","nombre":"Escritor de promoción de relaciones públicas / Escritora de promoción de relaciones públicas"},{"codigo":"24320.012","nombre":"Especialista en asuntos públicos"},{"codigo":"24320.013","nombre":"Especialista en enlace de prensa"},{"codigo":"24320.014","nombre":"Especialista en información pública"},{"codigo":"24320.015","nombre":"Especialista en relaciones públicas"},{"codigo":"24320.016","nombre":"Funcionario de enlace de prensa / Funcionaria de enlace de prensa"},{"codigo":"24320.017","nombre":"Funcionario de relaciones públicas / Funcionaria de relaciones públicas"},{"codigo":"24320.018","nombre":"Gerente de cuenta de relaciones públicas / Gerenta de cuenta de relaciones públicas"},{"codigo":"24320.019","nombre":"Planificador de medios / Planificadora de medios"},{"codigo":"24320.020","nombre":"Profesional de relaciones públicas"},{"codigo":"24320.021","nombre":"Profesional en relaciones públicas y comunicaciones"},{"codigo":"24320.022","nombre":"Promotor de relaciones públicas / Promotora de relaciones públicas"},{"codigo":"24320.023","nombre":"Redactor de promoción de relaciones públicas / Redactora de promoción de relaciones públicas"},{"codigo":"24320.024","nombre":"Redactor de relaciones públicas / Redactora de relaciones públicas"},{"codigo":"24320.025","nombre":"Relacionista público / Relacionista pública"},{"codigo":"24320.026","nombre":"Relator de relaciones públicas / Relatora de relaciones públicas"},{"codigo":"24320.027","nombre":"Secretario de prensa / Secretaria de prensa"},{"codigo":"24320.028","nombre":"Profesional de comunicaciones internas"},{"codigo":"24320.029","nombre":"Profesional de relaciones internacionales"}],"conocimientos":[{"id":"23","nombre":"Idioma extranjero"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"4","nombre":"Mercadotecnia y publicidad"},{"id":"30","nombre":"Periodismo, comunicación y reportajes"},{"id":"5","nombre":"Servicio al cliente"},{"id":"29","nombre":"Telecomunicación"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"12","nombre":"Persuasión"},{"id":"3","nombre":"Redacción de textos"},{"id":"10","nombre":"Relaciones interpersonales"}],"ocupaciones_afines":[{"codigo":"24210","nombre":"Profesionales y analistas de gestión y organización"},{"codigo":"24220","nombre":"Profesionales en políticas sociales y de administración"},{"codigo":"24311","nombre":"Profesionales en mercadeo y publicidad"},{"codigo":"33320","nombre":"Coordinadores y productores de conferencias, eventos y espectáculos / Coordinadoras y productoras de conferencias, eventos y espectáculos"},{"codigo":"33392","nombre":"Asistentes de mercadeo, publicidad y comunicaciones / Asistentas de mercadeo, publicidad y comunicaciones"}],"area_principal":{"sigla":"COMP","nombre":"Comercio, mercadeo y publicidad"},"areas_complementarias":[{"sigla":"CISH","nombre":"Ciencias sociales y humanidades"}],"equivalencias":[{"ciuo08_codigo":"2432","ciuo08_obs":"Denominaciones completas","cno_codigo":"5125*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Profesionales de ventas técnicas y médicas (excluyendo las TIC)', '24330', 'Comercio, mercadeo y publicidad', 4, false, '{"codigo":"24330","nombre":"Profesionales de ventas técnicas y médicas (excluyendo las TIC)","descripcion":"Representan a empresas y venden diversos bienes y servicios técnicos industriales, médicos, farmacéuticos, servicios de computación y telecomunicaciones, a establecimientos industriales, comerciales, profesionales y de otra índole. Se pueden desempeñar en establecimientos que producen o proveen bienes y servicios técnicos, laboratorios farmacéuticos, fábricas de equipo industrial, firmas de servicios de cómputo, firmas de ingeniería, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"24","nombre":"PROFESIONALES DE NEGOCIOS Y DE ADMINISTRACIÓN"},"subgrupo":{"codigo":"243","nombre":"Profesionales de las ventas, la comercialización y las relaciones públicas"},"grupo_primario":{"codigo":"2433","nombre":"Profesionales de ventas técnicas y médicas (excluyendo las TIC)"}},"funciones":[{"consecutivo":1,"texto":"Identificar y compilar listas de posibles clientes empresariales utilizando directorios y otras fuentes de referencia, y contactar clientes potenciales."},{"consecutivo":2,"texto":"Vender bienes y servicios técnicos a establecimientos industriales, instituciones y empresas."},{"consecutivo":3,"texto":"Visitar negocios de los clientes habituales y potenciales para desarrollar y aprovechar sobre las oportunidades de mercado."},{"consecutivo":4,"texto":"Adquirir y actualizar los conocimientos sobre los bienes y servicios de los empresarios y competidores, así como sobre las condiciones del mercado."},{"consecutivo":5,"texto":"Identificar y evaluar las necesidades y los recursos de los clientes y recomendarles los bienes o servicios apropiados."},{"consecutivo":6,"texto":"Contribuir en el diseño de productos en los casos en que los bienes o servicios deben ajustarse a las necesidades específicas y exclusivas de los clientes."},{"consecutivo":7,"texto":"Preparar informes y propuestas para incluir en las presentaciones de venta para ilustrar sobre los beneficios del uso de los bienes o servicios ofrecidos."},{"consecutivo":8,"texto":"Suministrar información general y especializada sobre características y funcionamiento de equipos, productos y servicios y demostrar su utilización."},{"consecutivo":9,"texto":"Vigilar las necesidades cambiantes de los clientes y las actividades de los competidores e informar esta evolución a la dirección de ventas."},{"consecutivo":10,"texto":"Cotizar y negociar precios y condiciones de crédito, y preparar y gestionar contratos de venta."},{"consecutivo":11,"texto":"Organizar la entrega de bienes, la instalación de equipos y la prestación de servicios."},{"consecutivo":12,"texto":"Informar a la gerencia de ventas sobre las ventas realizadas y la comercialización de los bienes y servicios."},{"consecutivo":13,"texto":"Estimar los costos de instalación y mantenimiento de equipos y servicios."},{"consecutivo":14,"texto":"Consultar con los clientes después de la venta para resolver y dar solución satisfactoria a los problemas y proporcionar soporte técnico continuo como garantía."},{"consecutivo":15,"texto":"Integrar herramientas digitales de acuerdo con normativa de comercio electrónico y plan de ventas."},{"consecutivo":16,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"24330.001","nombre":"Agente de ventas de ingeniería"},{"codigo":"24330.002","nombre":"Agente de ventas médicas"},{"codigo":"24330.003","nombre":"Agente de ventas técnicas"},{"codigo":"24330.004","nombre":"Agente de ventas técnicas excepto las TIC (tecnologías de la información y las comunicaciones)"},{"codigo":"24330.005","nombre":"Asesor de ventas técnicas excepto las TIC (tecnologías de la información y las comunicaciones) / Asesora de ventas técnicas excepto las TI