  ('rol_cuoc', 'Programadores de aplicaciones / Programadoras de aplicaciones', '25140', 'Tecnologías de la información y las comunicaciones', 4, false, '{"codigo":"25140","nombre":"Programadores de aplicaciones / Programadoras de aplicaciones","descripcion":"Escriben, mantienen, desarrollan e implementan códigos de programación expresados en instrucciones técnicas y especificaciones para las aplicaciones de software y los sistemas operativos; analizan los requisitos, revisan, amplían y prueban programas y aplicaciones. Se pueden desempeñar en organizaciones de tecnologías de la información y las comunicaciones, las firmas consultoras y los departamentos de tecnología en empresas del sector público y privado, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"25","nombre":"PROFESIONALES DE TECNOLOGÍA DE LA INFORMACIÓN Y LAS COMUNICACIONES"},"subgrupo":{"codigo":"251","nombre":"Desarrolladores y analistas de software y multimedia"},"grupo_primario":{"codigo":"2514","nombre":"Programadores de aplicaciones"}},"funciones":[{"consecutivo":1,"texto":"Evaluar requisitos de aplicaciones informáticas de acuerdo con metodologías de análisis y estándares."},{"consecutivo":2,"texto":"Redactar y mantener códigos de programación expresados en instrucciones y especificaciones conformes con normas de calidad establecidas."},{"consecutivo":3,"texto":"Revisar, reparar o ampliar los programas existentes para ampliar su eficiencia operativa o adaptarlos a nuevos requerimientos."},{"consecutivo":4,"texto":"Planear y desarrollar programación de aplicaciones informáticas y el diseño de la arquitectura de las soluciones del software de acuerdo con metodologías, arquetipos y requisitos técnicos."},{"consecutivo":5,"texto":"Implementar la programación de aplicaciones informáticas de acuerdo con requisitos de operación y modelos de referencia."},{"consecutivo":6,"texto":"Realizar series de pruebas de programas y aplicaciones de software para confirmar que van a generar la información deseada."},{"consecutivo":7,"texto":"Compilar y redactar documentos sobre el desarrollo de programas."},{"consecutivo":8,"texto":"Realizar soporte, identificar y comunicar problemas técnicos, procesos y soluciones a usuarios."},{"consecutivo":9,"texto":"Coordinar al personal a cargo de acuerdo con procesos administrativos."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"25140.001","nombre":"Ingeniero de sistemas programación / Ingeniera de sistemas programación"},{"codigo":"25140.002","nombre":"Ingeniero de sistemas programador / Ingeniera de sistemas programador"},{"codigo":"25140.003","nombre":"Programador de aplicaciones / Programadora de aplicaciones"},{"codigo":"25140.004","nombre":"Programador de aplicaciones informáticas / Programadora de aplicaciones informáticas"},{"codigo":"25140.005","nombre":"Programador de sistemas / Programadora de sistemas"},{"codigo":"25140.006","nombre":"Programador de sistemas informáticos / Programadora de sistemas informáticos"},{"codigo":"25140.007","nombre":"Programador de sistemas operativos / Programadora de sistemas operativos"},{"codigo":"25140.008","nombre":"Programador de software / Programadora de software"},{"codigo":"25140.009","nombre":"Programador informático / Programadora informática"}],"conocimientos":[{"id":"63","nombre":"Desarrollo y análisis de software y aplicaciones"},{"id":"65","nombre":"Diseño y administración de redes y bases de datos"},{"id":"34","nombre":"Herramientas de simulación y diseño"},{"id":"23","nombre":"Idioma extranjero"},{"id":"10","nombre":"Ingeniería y tecnología"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"17","nombre":"Análisis de necesidades"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"18","nombre":"Diseño de tecnología"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"41","nombre":"Pensamiento sistémico"},{"id":"21","nombre":"Programación"}],"ocupaciones_afines":[{"codigo":"21661","nombre":"Diseñadores gráficos / Diseñadoras gráficas"},{"codigo":"25110","nombre":"Analistas de sistemas"},{"codigo":"25120","nombre":"Desarrolladores de software / Desarrolladoras de software"},{"codigo":"25130","nombre":"Desarrolladores Web y multimedia / Desarrolladoras Web y multimedia"},{"codigo":"25190","nombre":"Desarrolladores y analistas de software y multimedia no clasificados en otras ocupaciones / Desarrolladoras y analistas de software y multimedia no clasificadas en otras ocupaciones"},{"codigo":"25210","nombre":"Diseñadores y administradores de bases de datos / Diseñadoras y administradoras de bases de datos"},{"codigo":"25220","nombre":"Administradores de sistemas / Administradoras de sistemas"},{"codigo":"25230","nombre":"Profesionales en redes de computadores"},{"codigo":"25290","nombre":"Profesionales en bases de datos y en redes de computadores no clasificados en otras ocupaciones"},{"codigo":"35121","nombre":"Técnicos en asistencia y soporte de tecnologías de la información / Técnicas en asistencia y soporte de tecnologías de la información"},{"codigo":"35130","nombre":"Técnicos en redes y tecnologías de la información / Técnicas en redes y tecnologías de la información"},{"codigo":"35140","nombre":"Técnicos de la web / Técnicas de la web"}],"area_principal":{"sigla":"TICO","nombre":"Tecnologías de la información y las comunicaciones"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"2514","ciuo08_obs":"Denominaciones completas","cno_codigo":"2145*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"2173*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Desarrolladores y analistas de software y multimedia no clasificados en otras ocupaciones / Desarrolladoras y analistas de software y multimedia no clasificadas en otras ocupaciones', '25190', 'Tecnologías de la información y las comunicaciones', 4, false, '{"codigo":"25190","nombre":"Desarrolladores y analistas de software y multimedia no clasificados en otras ocupaciones / Desarrolladoras y analistas de software y multimedia no clasificadas en otras ocupaciones","descripcion":"Esta ocupación abarca a los desarrolladores y analistas de software y multimedia no clasificados en otras ocupaciones del Subgrupo 251: Desarrolladores y analistas de software y multimedia. Por ejemplo, incluye aquellos que investigan, planifican, diseñan, evalúan, integran e implementan soluciones informáticas, sistemas operativos, almacenes de datos y software, siguiendo planes de prueba garantizando la calidad y seguridad de los datos de tecnologías de la información y las comunicaciones. Se pueden desempeñar en organizaciones de tecnologías de la información y las comunicaciones, firmas consultoras y departamentos de tecnología en empresas del sector público y privado, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"25","nombre":"PROFESIONALES DE TECNOLOGÍA DE LA INFORMACIÓN Y LAS COMUNICACIONES"},"subgrupo":{"codigo":"251","nombre":"Desarrolladores y analistas de software y multimedia"},"grupo_primario":{"codigo":"2519","nombre":"Desarrolladores y analistas de software y multimedia no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Desarrollar, ejecutar, analizar y documentar los planes y resultados de proyectos multimedia, aplicación de las pruebas de software, sistemas de información y sistemas de telecomunicaciones."},{"consecutivo":2,"texto":"Establecer requisitos de la solución y estructurar propuesta técnica de servicios y/o productos de tecnología de la información y las comunicaciones de acuerdo con requisitos, procedimiento técnico y normativa."},{"consecutivo":3,"texto":"Evaluar técnicamente, auditar y verificar que las soluciones de software, los programas y demás servicios y productos de tecnologías de la información y las comunicaciones funcionan de acuerdo con las necesidades de los usuarios, directrices establecidas, modelos de referencia y metodología de buenas prácticas."},{"consecutivo":4,"texto":"Desarrollar e implementar políticas, procedimientos, secuencias de instrucciones y diseño de pruebas de software y sistemas de información de acuerdo con estándares y marcos de referencia."},{"consecutivo":5,"texto":"Diseñar la arquitectura de tecnologías de la información y las comunicaciones como el software, centro de datos, sistema de seguridad, entre otros, de acuerdo con modelos, arquetipos, requisitos técnicos, estándares y marcos de referencia."},{"consecutivo":6,"texto":"Sistematizar e integrar datos masivos de acuerdo con métodos de analítica, técnicas de visualización y herramientas tecnológicas."},{"consecutivo":7,"texto":"Instalar software y equipos informáticos y configurar software de los sistemas operativos en preparación para las pruebas de funcionamiento."},{"consecutivo":8,"texto":"Gestionar los riesgos de las soluciones de las tecnologías de la información y las comunicaciones de acuerdo con estándares y marco de referencia."},{"consecutivo":9,"texto":"Asesorar a los clientes y solucionar requerimientos de acuerdo con procedimientos técnicos y normativa de procesos de negocios."},{"consecutivo":10,"texto":"Coordinar a otros ingenieros y técnicos en el desarrollo de las actividades de implementación de servicios o productos de las tecnologías de la información y la comunicación."},{"consecutivo":11,"texto":"Controlar la calidad del servicio y probar la solución del software de acuerdo con los estándares técnicos, parámetros y modelos de referencia."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"25190.001","nombre":"Analista computacional de pruebas de software"},{"codigo":"25190.002","nombre":"Analista de aseguramiento de la calidad de los computadores"},{"codigo":"25190.003","nombre":"Analista de aseguramiento de la calidad informática"},{"codigo":"25190.004","nombre":"Analista de negocio de pruebas de software"},{"codigo":"25190.005","nombre":"Analista de prueba de software"},{"codigo":"25190.006","nombre":"Analista de pruebas - tester"},{"codigo":"25190.007","nombre":"Analista de software de pruebas"},{"codigo":"25190.008","nombre":"Coordinador de proyecto informático / Coordinadora de proyecto informático"},{"codigo":"25190.009","nombre":"Coordinador de prueba de programas informáticos / Coordinadora de prueba de programas informáticos"},{"codigo":"25190.010","nombre":"Coordinador de prueba de software / Coordinadora de prueba de software"},{"codigo":"25190.011","nombre":"Gerente de despliegue de tecnología de información y comunicaciones TIC (tecnologías de la información y las comunicaciones) / Gerenta de despliegue de tecnología de información y comunicaciones TIC (tecnologías de la información y las comunicaciones)"},{"codigo":"25190.012","nombre":"Gerente de lanzamiento de proyectos TIC (tecnologías de la información y las comunicaciones) / Gerenta de lanzamiento de proyectos TIC (tecnologías de la información y las comunicaciones)"},{"codigo":"25190.013","nombre":"Gerente de lanzamiento de sistemas TIC (tecnologías de la información y las comunicaciones) / Gerenta de lanzamiento de sistemas TIC (tecnologías de la información y las comunicaciones)"},{"codigo":"25190.014","nombre":"Líder de pruebas"},{"codigo":"25190.015","nombre":"Probador de sistemas / Probadora de sistemas"},{"codigo":"25190.016","nombre":"Probador de software / Probadora de software"},{"codigo":"25190.017","nombre":"Programador informático de pruebas de aplicaciones / Programadora informática de p