  ('rol_cuoc', 'Diseñadores y administradores de bases de datos / Diseñadoras y administradoras de bases de datos', '25210', 'Tecnologías de la información y las comunicaciones', 4, false, '{"codigo":"25210","nombre":"Diseñadores y administradores de bases de datos / Diseñadoras y administradoras de bases de datos","descripcion":"Diseñan, desarrollan, administran, controlan, mantienen y apoyan el óptimo rendimiento, operación de servicios y seguridad de las bases de datos. Se pueden desempeñar en organizaciones de tecnologías de la información y las comunicaciones, firmas consultoras y departamentos de tecnología en empresas del sector público y privado, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"25","nombre":"PROFESIONALES DE TECNOLOGÍA DE LA INFORMACIÓN Y LAS COMUNICACIONES"},"subgrupo":{"codigo":"252","nombre":"Profesionales en bases de datos y en redes de computadores"},"grupo_primario":{"codigo":"2521","nombre":"Diseñadores y administradores de bases de datos"}},"funciones":[{"consecutivo":1,"texto":"Administrar la solución y la infraestructura tecnológica de red de datos acuerdo con procedimientos técnicos y estándares."},{"consecutivo":2,"texto":"Diseñar y desarrollar arquitecturas de bases de datos, centros y estructuras de datos, cuadros, diccionarios y convenciones de nomenclatura para proyectos de sistemas de información de acuerdo con modelos y estándares técnicos."},{"consecutivo":3,"texto":"Diseñar, construir, modificar, integrar, poner en funcionamiento y probar sistemas de gestión de bases de datos, de acuerdo con los estándares y los requisitos técnicos."},{"consecutivo":4,"texto":"Investigar y brindar asesoramiento en la selección, aplicación e implementación de herramientas de gestión de bases de datos."},{"consecutivo":5,"texto":"Formular políticas y procedimientos para el acceso, la utilización de bases de datos, así como sobre las copias de seguridad y la recuperación de datos."},{"consecutivo":6,"texto":"Realizar el establecimiento operacional y el mantenimiento preventivo de las copias de seguridad de las bases de datos, procedimientos de recuperación y hacer cumplir los controles de seguridad e integridad de estos."},{"consecutivo":7,"texto":"Controlar el centro de datos de acuerdo con procedimiento técnico y estándares."},{"consecutivo":8,"texto":"Elaborar y aplicar políticas de administración y gestión de riesgos para el manejo de datos de acuerdo con los documentos de referencia, normas, modelos, metodologías y estándares."},{"consecutivo":9,"texto":"Implementar y controlar el sistema de seguridad de la información y de bases de datos de acuerdo con estándares y marcos de referencia."},{"consecutivo":10,"texto":"Coordinar a otros ingenieros y técnicos en el desarrollo de las actividades de implementación de servicios o productos de las tecnologías de la información y la comunicación."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"25210.001","nombre":"Administrador de base de datos / Administradora de base de datos"},{"codigo":"25210.002","nombre":"Administrador de data center / Administradora de data center"},{"codigo":"25210.003","nombre":"Administrador de datos / Administradora de datos"},{"codigo":"25210.004","nombre":"Analista de base de datos"},{"codigo":"25210.005","nombre":"Analista de datos comerciales"},{"codigo":"25210.006","nombre":"Arquitecto de bases de datos / Arquitecta de bases de datos"},{"codigo":"25210.007","nombre":"Data manager"},{"codigo":"25210.008","nombre":"Desarrollador de base de datos / Desarrolladora de base de datos"},{"codigo":"25210.009","nombre":"Diseñador de bases de datos / Diseñadora de bases de datos"},{"codigo":"25210.010","nombre":"DIT (Técnico en imagen digital / Técnica en imagen digital)"},{"codigo":"25210.011","nombre":"DIT data (Técnico en imagen digital - data / Técnica en imagen digital - data)