  ('rol_cuoc', 'Bibliotecólogos, documentalistas y afines / Bibliotecólogas, documentalistas y afines', '26220', 'Artes visuales, plásticas y del patrimonio cultural', 4, false, '{"codigo":"26220","nombre":"Bibliotecólogos, documentalistas y afines / Bibliotecólogas, documentalistas y afines","descripcion":"Recopilan, seleccionan, organizan, catalogan y conservan obras literarias, colecciones de la biblioteca y otros repositorios de información; organizan y controlan los servicios de bibliotecas y asesoran a usuarios; generan contenidos, estructuran y participan en actividades de promoción y fomento a la lectura, así como gestionan unidades de información. Se pueden desempeñar en bibliotecas, unidades de información o departamentos especializados dentro de bibliotecas, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"26","nombre":"PROFESIONALES EN DERECHO, EN CIENCIAS SOCIALES Y CULTURALES"},"subgrupo":{"codigo":"262","nombre":"Bibliotecarios, archivistas y curadores de arte"},"grupo_primario":{"codigo":"2622","nombre":"Bibliotecólogos, documentalistas y afines"}},"funciones":[{"consecutivo":1,"texto":"Organizar, desarrollar y mantener colecciones sistemáticas de libros, periódicos y otros materiales impresos gráficos, fotográficos, cartográficos o manuscritos, grabaciones sonoras, audiovisuales y portadores de información digital."},{"consecutivo":2,"texto":"Identificar, seleccionar y proponer la adquisición de libros, periódicos y otros materiales impresos, gráficos, fotográficos, cartográficos o manuscritos, grabaciones sonoras, audiovisuales, portadores de información digital para la biblioteca y otros repositorios de información."},{"consecutivo":3,"texto":"Organizar, clasificar y catalogar materiales documentales nuevos y existentes de las colecciones de la biblioteca y otros repositorios de información."},{"consecutivo":4,"texto":"Organizar, administrar y gestionar servicios, préstamos, redes de información a usuarios entre bibliotecas y otros repositorios de información."},{"consecutivo":5,"texto":"Desarrollar y aplicar sistemas, esquemas, modelos conceptuales para el almacenamiento, organización, clasificación, recuperación de información, acceso y uso de las colecciones la biblioteca y otros repositorios de información."},{"consecutivo":6,"texto":"Recuperar materiales y facilitar información a empresas y otros usuarios basándose en la propia colección o en los sistemas de bibliotecas, otros repositorios y redes de información."},{"consecutivo":7,"texto":"Llevar a cabo investigaciones y analizar o modificar los servicios de biblioteca y de información en función de los cambios en las necesidades de los usuarios."},{"consecutivo":8,"texto":"Preparar bibliografías, índices, catálogos, guías, documentos, informes académicos, otras ayudas de búsqueda, entre otras."},{"consecutivo":9,"texto":"Realizar búsquedas de referencias manuales, en línea y mediante medios interactivos; realizar préstamos entre bibliotecas, otros repositorios de información y llevar a cabo otras funciones para ayudar a los usuarios a acceder a sus materiales."},{"consecutivo":10,"texto":"Implementar programas especializados como visitas guiadas, lecturas infantiles, audiciones, proyecciones, exposiciones, foros, encuentros, formación de usuarios, entre otros."},{"consecutivo":11,"texto":"Dirigir la información de la biblioteca y otros repositorios de información mediante sesiones de entrenamiento y orientación."},{"consecutivo":12,"texto":"Coordinar los procesos relacionados con la planeación, la ejecución, el mercadeo, la promoción y la animación a la lectura, la escritura, la documentación gráfica, fotográfica, sonora y audiovisual de acuerdo con los planes y los programas establecidos."},{"consecutivo":13,"texto":"Administrar la unidad de información y los procesos de generación de conocimiento e investigación."},{"consecutivo":14,"texto":"Gestionar el tratamiento técnico de documentos musicales, clasificando, describiendo y normalizando la información de la música contenida en diversos soportes y formatos."},{"consecutivo":15,"texto":"Coordinar y asignar trabajo a técnicos auxiliares y oficinistas de la biblioteca y otros repositorios de información."},{"consecutivo":16,"texto":"Diseñar y gestionar la promoción de la cultura digital en el acceso a información."},{"consecutivo":17,"texto":"Desarrollar, ejecutar y complementar los procesos de implementación de innovación en la prestación de los servicios bibliotecarios y el acceso a la información."},{"consecutivo":18,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"26220.001","nombre":"Analista de información en biblioteca"},{"codigo":"26220.002","nombre":"Bibliógrafo / Bibliógrafa"},{"codigo":"26220.003","nombre":"Bibliotecólogo / Bibliotecóloga"},{"codigo":"26220.004","nombre":"Bibliotecólogo en música / Bibliotecóloga en música"},{"codigo":"26220.005","nombre":"Bibliotecólogo musical / Bibliotecóloga musical"},{"codigo":"26220.006","nombre":"Catalogador / Catalogadora"},{"codigo":"26220.007","nombre":"Catalogador audiovisual / Catalogadora audiovisual"},{"codigo":"26220.008","nombre":"Catalogador de documentación audiovisual / Catalogadora de documentación audiovisual"},{"codigo":"26220.009","nombre":"Catalogador de documentación musical / Catalogadora de documentación musical"},{"codigo":"26220.010","nombre":"Catalogador de material bibliográfico / Catalogadora de material bibliográfico"},{"codigo":"26220.011","nombre":"Catalogador musical / Catalogadora musical"},{"codigo":"26220.012","nombre":"Cataloguista"},{"codigo":"26220.013","nombre":"Cataloguista audiovisual"},{"codigo":"26220.014","nombre":"Científico de la información / Científica de la información"},{"codigo":"26220.015","nombre":"Clasificador audiovisual / Clasificadora audiovisual"},{"codigo":"26220.016","nombre":"Clasificador de material bibliográfico / Clasificadora de material bibliográfico"},{"codigo":"26220.017","nombre":"Codicólogo de biblioteca / Codicóloga de biblioteca"},{"codigo":"26220.018","nombre":"Coordinador de biblioteca / Coordinadora de biblioteca"},{"codigo":"26220.019","nombre":"Coordinador de catalogación / Coordinadora de catalogación"},{"codigo":"26220.020","nombre":"Coordinador de servicios o de biblioteca / Coordinadora de servicios o de biblioteca"},{"codigo":"26220.021","nombre":"Coordinador fonotecario / Coordinadora fonotecaria"},{"codigo":"26220.022","nombre":"Documentalista de información"},{"codigo":"26220.023","nombre":"Documentalista de información musical"},{"codigo":"26220.024","nombre":"Especialista en información"},{"codigo":"26220.025","nombre":"Fonotecario / Fonotecaria"},{"codigo":"26220.026","nombre":"Gestor de información audiovisual / Gestora de información audiovisual"},{"codigo":"26220.027","nombre":"Líder de biblioteca / Lideresa de biblioteca"},{"codigo":"26220.028","nombre":"Profesional de preservación digital"},{"codigo":"26220.029","nombre":"Profesional en bibliotecología"},{"codigo":"26220.030","nombre":"Profesional en ciencias de la información"},{"codigo":"26220.031","nombre":"Profesional en sistemas de información y documentación"},{"codigo":"26220.032","nombre":"Analista de desarrollo de colecciones bibliotecarias"},{"codigo":"26220.033","nombre":"Analista de procesos técnicos bibliotecarios"},{"codigo":"26220.034","nombre":"Coordinador de contenidos bibliotecarios / Coordinadora de contenidos bibliotecarios"},{"codigo":"26220.035","nombre":"Coordinador de cultura bibliotecaria / Coordinadora de cultura bibliotecaria"},{"codigo":"26220.036","nombre":"Coordinador de procesos técnicos de biblioteca / Coordinadora de procesos técnicos de biblioteca"},{"codigo":"26220.037","nombre":"Coordinador de servicios de la unidad de información de bibliotecas / Coordinadora de servicios de la unidad de información de bibliotecas"},{"codigo":"26220.038","nombre":"Profesional en b