  ('rol_cuoc', 'Traductores, intérpretes y lingüistas / Traductoras, intérpretes y lingüistas', '26431', 'Ciencias sociales y humanidades', 4, false, '{"codigo":"26431","nombre":"Traductores, intérpretes y lingüistas / Traductoras, intérpretes y lingüistas","descripcion":"Traducen o interpretan de un idioma a otro, estudian el origen, el desarrollo y la estructura de las lenguas; conducen la investigación requerida para traducir e interpretar vocabulario y material técnico, profesional y científico. Se pueden desempeñar en firmas de traducción, el gobierno, organizaciones internacionales, medios de comunicación, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"26","nombre":"PROFESIONALES EN DERECHO, EN CIENCIAS SOCIALES Y CULTURALES"},"subgrupo":{"codigo":"264","nombre":"Autores, periodistas y lingüistas"},"grupo_primario":{"codigo":"2643","nombre":"Traductores, intérpretes y otros lingüistas"}},"funciones":[{"consecutivo":1,"texto":"Estudiar e investigar el origen, estructura, desarrollo y las relaciones entre lenguas antiguas matrices y grupos lingüísticos modernos aplicando teorías lingüísticas a la enseñanza, traducción, comunicaciones, evolución de las palabras, formas gramaticales y lingüísticas y presentar los resultados."},{"consecutivo":2,"texto":"Asesorar, preparar sistemas o archivos tecnológicos como, por ejemplo: la clasificación de lenguas, gramáticas, diccionarios y materiales afines utilizando la investigación documental y terminológica."},{"consecutivo":3,"texto":"Interpretar la comunicación oral de un idioma a otro, simultánea (a medida que el orador habla), o consecutivamente (después que el orador habla), en conferencias, reuniones y encuentros similares, procurando transmitir el significado correcto de lo manifestado originalmente, su sentido o intención real."},{"consecutivo":4,"texto":"Revisar, corregir y confrontar el material traducido."},{"consecutivo":5,"texto":"Interpretar o traducir oralmente o de un lenguaje de señas o signos a otro idioma hablado o firmado y viceversa, en particular en conferencias, reuniones y ocasiones similares, y asegurar, en la medida de lo posible, que el significado correcto y el espíritu del original se transmitan."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"26431.001","nombre":"Escritor de diccionario / Escritora de diccionario"},{"codigo":"26431.002","nombre":"Etimologista"},{"codigo":"26431.003","nombre":"Filólogo / Filóloga"},{"codigo":"26431.004","nombre":"Filólogo de fonética / Filóloga de fonética"},{"codigo":"26431.005","nombre":"Filólogo de grafología / Filóloga de grafología"},{"codigo":"26431.006","nombre":"Filólogo de morfología / Filóloga de morfología"},{"codigo":"26431.007","nombre":"Fonólogo / Fonóloga"},{"codigo":"26431.008","nombre":"Grafólogo / Grafóloga"},{"codigo":"26431.009","nombre":"Intérprete"},{"codigo":"26431.010","nombre":"Intérprete de conferencias"},{"codigo":"26431.011","nombre":"Lexicógrafo / Lexicógrafa"},{"codigo":"26431.012","nombre":"Lingüista"},{"codigo":"26431.013","nombre":"Morfologista"},{"codigo":"26431.014","nombre":"Semasiólogo / Semasióloga"},{"codigo":"26431.015","nombre":"Subtitulador / Subtituladora"},{"codigo":"26431.016","nombre":"Terminologista"},{"codigo":"26431.017","nombre":"Traductor / Traductora"},{"codigo":"26431.018","nombre":"Traductor de documentos técnicos / Traductora de documentos técnicos"},{"codigo":"26431.019","nombre":"Traductor literario / Traductora literaria"},{"codigo":"26431.020","nombre":"Traductor revisor / Traductora revisora"},{"codigo":"26431.021","nombre":"Traductor simultáneo / Traductora simultánea"}],"conocimientos":[{"id":"52","nombre":"Adquisición del lenguaje"},{"id":"26","nombre":"Filosofía y ética"},{"id":"23","nombre":"Idioma extranjero"},{"id":"76","nombre":"Literatura y lingüística"},{"id":"43","nombre":"Patrimonio cultural"},{"id":"5","nombre":"Servicio al cliente"},{"id":"19","nombre":"Sociología, antropología y estudios culturales"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"3","nombre":"Redacción de textos"},{"id":"14","nombre":"Transmisión de conocimiento"}],"ocupaciones_afines":[{"codigo":"23100","nombre":"Profesores de instituciones de educación superior / Profesoras de instituciones de educación superior"},{"codigo":"23530","nombre":"Otros profesores de idiomas / Otras profesoras de idiomas"},{"codigo":"26410","nombre":"Autores y otros escritores / Autoras y otras escritoras"},{"codigo":"26422","nombre":"Editores y redactores / Editoras y redactoras"},{"codigo":"26433","nombre":"Intérpretes de lengua de señas"}],"area_principal":{"sigla":"CISH","nombre":"Ciencias sociales y humanidades"},"areas_complementarias":[{"sigla":"SEPC","nombre":"Servicios Personales y a la Comunidad"}],"equivalencias":[{"ciuo08_codigo":"2643*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"4162*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"5124*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Traductores e intérpretes de lenguas nativas / Traductoras e intérpretes de lenguas nativas', '26432', 'Ciencias sociales y humanidades', 4, false, '{"codigo":"26432","nombre":"Traductores e intérpretes de lenguas nativas / Traductoras e intérpretes de lenguas nativas","descripcion":"Interpretan y traducen de una lengua a otra en tiempo real, las acciones primordialmente se centran en expresar de forma oral el mensaje de la lengua nativa fuente, los sistemas de pensamiento como factores de identidad e integración de los grupos humanos mediante la producción de versiones habladas en la lengua, principalmente con los sectores de la justicia, salud, educación y la administración pública para la garantía de los derechos culturales y otros que se requieran. Se pueden desempeñar con comunidades étnicas, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"26","nombre":"PROFESIONALES EN DERECHO, EN CIENCIAS SOCIALES Y CULTURALES"},"subgrupo":{"codigo":"264","nombre":"Autores, periodistas y lingüistas"},"grupo_primario":{"codigo":"2643","nombre":"Traductores, intérpretes y otros lingüistas"}},"funciones":[{"consecutivo":1,"texto":"Asistir a las comunidades de las diversas lenguas nativas para expresarse haciendo uso de la lengua propia en diversos contextos."},{"consecutivo":2,"texto":"Interpretar las lenguas nativas, en el ámbito cultural, laboral, social, para comunicar las diferentes actividades dentro del territorio asegurando, en la medida de lo posible que el significado y el espíritu del original del mensaje se transmita."},{"consecutivo":3,"texto":"Traducir las lenguas nativas al español y viceversa de manera simultánea (a medida que el orador habla), o consecutivamente (después que el orador habla), asegurando, en la medida de lo posible que el significado y el espíritu del original del mensaje se transmita."},{"consecutivo":4,"texto":"Apoyar a las comunidades a través de la traducción e interpretación en el acceso a derechos fundamentales, como el derecho a la salud, la justicia, comunicación, la educación y la identidad, asegurando, en la medida de lo posible que el significado y el espíritu del original del mensaje se transmita."},{"consecutivo":5,"texto":"Aportar a la difusión de bienes culturales de las comunidades para crear espacios que permitan intercambiar experiencias, compartir puntos de encuentro y desafíos comunes."},{"consecutivo":6,"texto":"Asistir a la comunidad o al hablante de las lenguas nativas en las necesidades lingüísticas de traducción e interpretación para la garantía de sus derechos."},{"consecutivo":7,"texto":"Asistir la garantía del debido proceso en los procesos que se contemplan cuando el individuo se encuentra en situación vulnerable y de desventaja frente a procesos legales, juicios y defensas entre otros."},{"consecutivo":8,"texto":"Apoyar procesos de educación y formación con la traducción e interpretación de las lenguas nativas en espacios de formación, elaboración de materiales pedagógicos haciendo uso de terminologías y tecnicismos específicos de las lenguas nativas."},{"consecutivo":9,"texto":"Interpretar y traducir la interacción del hablante de lengua nativa para el acceso a programas y servicios de salud."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"26432.001","nombre":"Intérprete de lengua romani"},{"codigo":"26432.002","nombre":"Intérprete de lenguas criollas (ri palenque y raizal) colombianas"},{"codigo":"26432.003","nombre":"Intérprete de lenguas indígenas colombianas"},{"codigo":"26432.004","nombre":"Traductor de lengua romani colombianas / Traductora de lengua romani colombianas"},{"codigo":"26432.005","nombre":"Traductor de lenguas criollas (ri palenque y raizal) de Colombia / Traductora de lenguas criollas (ri palenque y raizal) de Colombia"},{"codigo":"26432.006","nombre":"Traductor de lenguas indígenas colombianas / Traductora de lenguas indígenas colombianas"}],"conocimientos":[{"id":"52","nombre":"Adquisición del lenguaje"},{"id":"23","nombre":"Idioma extranjero"},{"id":"43","nombre":"Patrimonio cultural"},{"id":"5","nombre":"Servicio al cliente"},{"id":"19","nombre":"Sociología, antropología y estudios culturales"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"8","nombre":"Estrategias para el aprendizaje"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"15","nombre":"Orientación al servicio"},{"id":"3","nombre":"Redacción de textos"}],"ocupaciones_afines":[{"codigo":"26431","nombre":"Traductores, intérpretes y lingüistas / Traductoras, intérpretes y lingüistas"},{"codigo":"26433","nombre":"Intérpretes de lengua de señas"},{"codigo":"26434","nombre":"Guías-intérpretes"}],"area_principal":{"sigla":"CISH","nombre":"Ciencias sociales y humanidades"},"areas_complementarias":[{"sigla":"AVPP","nombre":"Artes visuales, plásticas y del patrimonio cultural"},{"sigla":"SEPC","nombre":"Servicios Personales y a la Comunidad"}],"equivalencias":[{"ciuo08_codigo":"2643*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"","cno_obs":""}]}'::jsonb),
  ('rol_cuoc', 'Intérpretes de lengua de señas', '26433', 'Ciencias sociales y humanidades', 3, false, '{"codigo":"26433","nombre":"Intérpretes de lengua de señas","descripcion":"Interpretan, traducen y describen (según el caso) mensajes y contextos de lengua de señas, incluyendo la colombiana a español y viceversa. Se pueden desempeñar en firmas de interpretación, fundaciones, institutos para personas sordas, privados y públicos, el gobierno y organizaciones internacionales, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"26","nombre":"PROFESIONALES EN DERECHO, EN CIENCIAS SOCIALES Y CULTURALES"},"subgrupo":{"codigo":"264","nombre":"Autores, periodistas y lingüistas"},"grupo_primario":{"codigo":"2643","nombre":"Traductores, intérpretes y otros lingüistas"}},"funciones":[{"consecutivo":1,"texto":"Traducir comunicación oral a lenguaje de señas y viceversa de manera simultánea (a medida que el orador habla), o consecutivamente (después que el orador habla)."},{"consecutivo":2,"texto":"Interpretar oralmente o de un lenguaje de señas a otro idioma hablado o firmado o viceversa, de forma fiel, clara y comprensible, cumpliendo con los respectivos principios éticos y haciendo uso de las técnicas de interpretación en particular en conferencias, reuniones y ocasiones similares, y asegurar, en la medida de lo posible, que el significado correcto y el espíritu del original se transmitan."},{"consecutivo":3,"texto":"Traducir de forma fiel y precisa textos escritos a Lengua de Señas Colombiana y viceversa."},{"consecutivo":4,"texto":"Preparar el servicio previa entrega de los documentos e información necesarios para realizar la interpretación y traducción."},{"consecutivo":5,"texto":"Planificar, ejecutar y controlar la prestación del servicio desde su rol de intérprete, de acuerdo con la información necesaria para el servicio y previo acuerdo con la persona sorda para realizar su labor."},{"consecutivo":6,"texto":"Brindar el servicio de interpretación garantizando en la medida de lo posible que el significado correcto y el espíritu del original se transmita de forma fiel, clara, comprensible y con principios éticos."},{"consecutivo":7,"texto":"Establecer acuerdos con la persona sorda atendiendo a su condición lingüística particular a través del sistema de comunicación utilizado por el usuario."},{"consecutivo":8,"texto":"Contextualizar a la persona sorda describiendo el lugar, el espacio, las personas (sus emociones y reacciones) y los objetos presentes, teniendo en cuenta la información auditiva y visual no lingüística relevante en el contexto comunicativo y de acuerdo con los requerimientos del usuario."},{"consecutivo":9,"texto":"Realizar seguimiento y evaluación permanente de la interpretación o traducción de señas y del servicio, incluyendo la revisión de grabaciones o medios en los que reposa la traducción."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"26433.001","nombre":"Intérprete de lengua de señas colombiana"},{"codigo":"26433.002","nombre":"Intérprete de lenguaje de señas"},{"codigo":"26433.003","nombre":"Intérprete de lenguaje de signos"},{"codigo":"26433.004","nombre":"Intérprete de sordos"},{"codigo":"26433.005","nombre":"Intérprete para personas sordas"},{"codigo":"26433.006","nombre":"Traductor de lengua de señas / Traductora de lengua de señas"}],"conocimientos":[{"id":"52","nombre":"Adquisición del lenguaje"},{"id":"26","nombre":"Filosofía y ética"},{"id":"23","nombre":"Idioma extranjero"},{"id":"5","nombre":"Servicio al cliente"},{"id":"19","nombre":"Sociología, antropología y estudios culturales"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"3","nombre":"Redacción de textos"},{"id":"14","nombre":"Transmisión de conocimiento"}],"ocupaciones_afines":[{"codigo":"22691","nombre":"Terapeutas ocupacionales"},{"codigo":"23100","nombre":"Profesores de instituciones de educación superior / Profesoras de instituciones de educación superior"},{"codigo":"23521","nombre":"Profesores e instructores de educación especial e inclusiva / Profesoras e instructoras de educación especial e inclusiva"},{"codigo":"26431","nombre":"Traductores, intérpretes y lingüistas / Traductoras, intérpretes y lingüistas"},{"codigo":"26434","nombre":"Guías-intérpretes"},{"codigo":"32550","nombre":"Técnicos y asistentes terapeutas / Técnicas y asistentes terapeutas"}],"area_principal":{"sigla":"CISH","nombre":"Ciencias sociales y humanidades"},"areas_complementarias":[{"sigla":"SEPC","nombre":"Servicios Personales y a la Comunidad"}],"equivalencias":[{"ciuo08_codigo":"2643*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"5124*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"6263","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Guías-intérpretes', '26434', 'Ciencias sociales y humanidades', 3, false, '{"codigo":"26434","nombre":"Guías-intérpretes","descripcion":"Contextualizan, describen, interpretan, dan soporte permanente y guían en la movilidad de personas con sordoceguera, adicionalmente transmiten la información visual y comunicativa de manera personalizada y de acuerdo con las características, las metodologías, los sistemas de comunicación y las técnicas de cada usuario, para facilitar la comunicación, el conocimiento del entorno y el desenvolvimiento en el mismo. Se pueden desempeñar en firmas de interpretación, institutos, fundaciones para personas sordociegas, privados y públicos, el gobierno y organizaciones internacionales, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"26","nombre":"PROFESIONALES EN DERECHO, EN CIENCIAS SOCIALES Y CULTURALES"},"subgrupo":{"codigo":"264","nombre":"Autores, periodistas y lingüistas"},"grupo_primario":{"codigo":"2643","nombre":"Traductores, intérpretes y otros lingüistas"}},"funciones":[{"consecutivo":1,"texto":"Contextualizar a través del sistema de comunicación empleado por la persona sordociega, la descripción física de lugares, personas, movimientos, intensiones, reacciones, contextos, entre otros."},{"consecutivo":2,"texto":"Guiar y asistir la movilidad de la persona sordociega, apoyando sus desplazamientos utilizando técnicas de orientación y ubicación personalizadas, manejo espacial, movilidad, y guía vidente, tratando de eliminar las barreras del entorno."},{"consecutivo":3,"texto":"Comunicar de manera objetiva e imparcial a través de sistemas, metodologías, técnicas y tecnologías de la comunicación utilizadas por la persona sordociega, información lingüística y paralingüística transmitida por otras personas al usuario y del usuario a otras personas."},{"consecutivo":4,"texto":"Transmitir información sobre contextos, hechos, entre otros, por medio de la lectura de diarios, noticieros, contenidos de entretenimiento, situaciones sociales, y demás medios de comunicación."},{"consecutivo":5,"texto":"Manipular herramientas tecnológicas, formatos y técnicas que faciliten su comunicación e interacción con la persona sordociega."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"26434.001","nombre":"Facilitador de sordociegos / Facilitadora de sordociegos"},{"codigo":"26434.002","nombre":"Guía intérprete para sordociegos / Guía intérprete para sordociegas"},{"codigo":"26434.003","nombre":"Guía de sordociegos"},{"codigo":"26434.004","nombre":"Guía-intérprete"},{"codigo":"26434.005","nombre":"Intérprete de sordociegos"}],"conocimientos":[{"id":"52","nombre":"Adquisición del lenguaje"},{"id":"22","nombre":"Educación y capacitación"},{"id":"26","nombre":"Filosofía y ética"},{"id":"5","nombre":"Servicio al cliente"},{"id":"18","nombre":"Sicología / psicología"},{"id":"19","nombre":"Sociología, antropología y estudios culturales"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"8","nombre":"Estrategias para el aprendizaje"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"15","nombre":"Orientación al servicio"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"14","nombre":"Transmisión de conocimiento"}],"ocupaciones_afines":[{"codigo":"22691","nombre":"Terapeutas ocupacionales"},{"codigo":"23100","nombre":"Profesores de instituciones de educación superior / Profesoras de instituciones de educación superior"},{"codigo":"23521","nombre":"Profesores e instructores de educación especial e inclusiva / Profesoras e instructoras de educación especial e inclusiva"},{"codigo":"26433","nombre":"Intérpretes de lengua de señas"}],"area_principal":{"sigla":"CISH","nombre":"Ciencias sociales y humanidades"},"areas_complementarias":[{"sigla":"SEPC","nombre":"Servicios Personales y a la Comunidad"}],"equivalencias":[{"ciuo08_codigo":"2643*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"6264","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Artistas plásticos y visuales / Artistas plásticas y visuales', '26511', 'Artes visuales, plásticas y del patrimonio cultural', 4, false, '{"codigo":"26511","nombre":"Artistas plásticos y visuales / Artistas plásticas y visuales","descripcion":"Desarrollan actividades de investigación, creación, elaboración, producción, conservación, circulación y exhibición de obras de arte antiguas, modernas y contemporáneas; que  generan un bien de una dimensión visual, material y de contenidos simbólicos, desarrollados desde un conjunto de disciplinas orientadas a la creación artística que van desde las artes plásticas tradicionales como la pintura, la escultura y el grabado, entre otras hasta especialidades que incorporan el uso de nuevas tecnologías como el arte digital o el arte transmedia, entre otras. Se pueden desempeñar en galerías de arte, ferias de arte, espacios culturales, universidades, escuelas de bellas artes, bibliotecas, museos, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"26","nombre":"PROFESIONALES EN DERECHO, EN CIENCIAS SOCIALES Y CULTURALES"},"subgrupo":{"codigo":"265","nombre":"Artistas creativos e interpretativos"},"grupo_primario":{"codigo":"2651","nombre":"Escultores, pintores artísticos y afines"}},"funciones":[{"consecutivo":1,"texto":"Concebir y desarrollar ideas, diseños y estilos para obras de pintura artística, dibujo y escultura."},{"consecutivo":2,"texto":"Colocar objetos, disponer la ubicación y postura de los modelos y seleccionar paisajes y demás formas visuales de acuerdo con el tema elegido."},{"consecutivo":3,"texto":"Seleccionar medios, métodos y materiales artísticos."},{"consecutivo":4,"texto":"Crear esculturas, estatuas y otros trabajos artísticos figurativos o abstractos tridimensionales o en relieve, utilizando técnicas de moldeo y tallado, combinando diversos materiales como madera, piedra, arcilla, metal, hielo, papel, entre otros."},{"consecutivo":5,"texto":"Crear dibujos, pinturas y otros trabajos artísticos originales figurativos o abstractos, empleando lápices, tinta, tiza, pasteles, pinturas al óleo, acuarelas, carboncillos o mediante la aplicación de otras técnicas."},{"consecutivo":6,"texto":"Crear dibujos y transferirlos mediante grabado mecánico o grabado químico a soportes de metal, madera u otros materiales."},{"consecutivo":7,"texto":"Restaurar pinturas y otros objetos de arte deteriorados, sucios o descoloridos."},{"consecutivo":8,"texto":"Orientar y asesorar en la aplicación de técnicas y métodos de dibujo, pintura, escultura y otras formas de expresión artística."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"26511.001","nombre":"Acuarelista"},{"codigo":"26511.002","nombre":"Artista de cerámica"},{"codigo":"26511.003","nombre":"Artista de paisaje"},{"codigo":"26511.004","nombre":"Artista pintor / Artista pintora"},{"codigo":"26511.005","nombre":"Artista plástico / Artista plástica"},{"codigo":"26511.006","nombre":"Artista visual"},{"codigo":"26511.007","nombre":"Dibujante artístico / Dibujante artística"},{"codigo":"26511.008","nombre":"Escultor / Escultora"},{"codigo":"26511.009","nombre":"Escultor modelador / Escultora modeladora"},{"codigo":"26511.010","nombre":"Escultor pintor artístico / Escultora pintora artística"},{"codigo":"26511.011","nombre":"Grabador de aguafuerte artístico / Grabadora de aguafuerte artístico"},{"codigo":"26511.012","nombre":"Muralista"},{"codigo":"26511.013","nombre":"Pintor artístico / Pintora artística"},{"codigo":"26511.014","nombre":"Pintor de arte / Pintora de arte"},{"codigo":"26511.015","nombre":"Pintor de miniaturas / Pintora de miniaturas"},{"codigo":"26511.016","nombre":"Pintor paisajista / Pintora paisajista"},{"codigo":"26511.017","nombre":"Pintor retratista / Pintora retratista"},{"codigo":"26511.018","nombre":"Retratista"}],"conocimientos":[{"id":"46","nombre":"Armonía y composición"},{"id":"54","nombre":"Artesanías"},{"id":"24","nombre":"Bellas artes"},{"id":"11","nombre":"Diseño"},{"id":"34","nombre":"Herramientas de simulación y diseño"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"43","nombre":"Patrimonio cultural"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"39","nombre":"Creatividad"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"10","nombre":"Relaciones interpersonales"}],"ocupaciones_afines":[{"codigo":"21661","nombre":"Diseñadores gráficos / Diseñadoras gráficas"},{"codigo":"23100","nombre":"Profesores de instituciones de educación superior / Profesoras de instituciones de educación superior"},{"codigo":"26212","nombre":"Curadores de artes visuales y plásticas y de patrimonio cultural / Curadoras de artes visuales y plásticas y de patrimonio cultural"},{"codigo":"26512","nombre":"Ilustradores artísticos / Ilustradoras artísticas"},{"codigo":"73160","nombre":"Rotulistas, pintores decorativos y grabadores / Rotulistas, pintoras decorativas y grabadoras"},{"codigo":"73510","nombre":"Talladores de piezas artesanales de madera / Talladoras de piezas artesanales de madera"},{"codigo":"73520","nombre":"Decoradores de piezas artesanales en madera / Decoradoras de piezas artesanales en madera"},{"codigo":"73620","nombre":"Orfebres y plateros / Orfebres y plateras"},{"codigo":"73700","nombre":"Artesanos del cuero / Artesanas del cuero"},{"codigo":"73920","nombre":"Artesanos del hierro y otros metales / Artesanas del hierro y otros metales"},{"codigo":"73930","nombre":"Artesanos de las semillas y cortezas vegetales / Artesanas de las semillas y cortezas vegetales"},{"codigo":"73999","nombre":"Artesanos de otros materiales no clasificados en otras ocupaciones / Artesanas de otros materiales no clasificados en otras ocupaciones"}],"area_principal":{"sigla":"AVPP","nombre":"Artes visuales, plásticas y del patrimonio cultural"},"areas_complementarias":[{"sigla":"AVPP","nombre":"Artes visuales, plásticas y del patrimonio cultural"},{"sigla":"LIAG","nombre":"Literatura y artes gráficas"}],"equivalencias":[{"ciuo08_codigo":"2651*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"5136","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Ilustradores artísticos / Ilustradoras artísticas', '26512', 'Artes visuales, plásticas y del patrimonio cultural', 3, false, '{"codigo":"26512","nombre":"Ilustradores artísticos / Ilustradoras artísticas","descripcion":"Crean material gráfico artístico a partir de ilustraciones, como herramienta para mejorar la comunicación escrita a través de representaciones visuales para libros, publicidad, periódicos, revistas, páginas web y producciones audiovisuales. Se pueden desempeñar en escuelas de bellas artes, empresas editoriales, producción gráfica, prensa, compañías de producción de cine, vídeo y televisión, galerías y exposiciones entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"26","nombre":"PROFESIONALES EN DERECHO, EN CIENCIAS SOCIALES Y CULTURALES"},"subgrupo":{"codigo":"265","nombre":"Artistas creativos e interpretativos"},"grupo_primario":{"codigo":"2651","nombre":"Escultores, pintores artísticos y afines"}},"funciones":[{"consecutivo":1,"texto":"Concebir y desarrollar ideas, diseños y estilos para ilustraciones artísticas."},{"consecutivo":2,"texto":"Investigar y recoger información sobre el tema, concepto y objetivo a ilustrar de acuerdo con los requerimientos del cliente."},{"consecutivo":3,"texto":"Realizar bocetos, organizar elementos visuales, crear conceptos y dibujos animados y de la figura humana para representar a personajes, acontecimientos, caricaturas e imágenes para diferentes medios y campañas."},{"consecutivo":4,"texto":"Hacer ilustraciones conceptualizando la intención comunicativa, dibujando y coloreando digital o análogamente, y manejando técnicas específicas y software para la elaboración de proyecto."},{"consecutivo":5,"texto":"Elaborar story boards para animaciones, videos y películas como guía para la comprensión de historias, pre-visualización de una animación o estructura de la película."},{"consecutivo":6,"texto":"Manejar técnicas y procesos para la presentación gráfica de ilustraciones artísticas."},{"consecutivo":7,"texto":"Representar grafitis de acuerdo con técnicas y diseño artístico."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"26512.001","nombre":"Artista gráfico / Artista gráfica"},{"codigo":"26512.002","nombre":"Artista ilustrador / Artista ilustradora"},{"codigo":"26512.003","nombre":"Artista ilustrador de afiche / Artista ilustradora de afiche"},{"codigo":"26512.004","nombre":"Caricaturista"},{"codigo":"26512.005","nombre":"Caricaturista y dibujante cómico e historietista / Caricaturista y dibujante cómica e historietista"},{"codigo":"26512.006","nombre":"Dibujante caricaturista"},{"codigo":"26512.007","nombre":"Dibujante de historietas"},{"codigo":"26512.008","nombre":"Dibujante ilustrador / Dibujante ilustradora"},{"codigo":"26512.009","nombre":"Grafitero / Grafitera"},{"codigo":"26512.010","nombre":"Historietista"},{"codigo":"26512.011","nombre":"Humorista gráfico / Humorista gráfica"},{"codigo":"26512.012","nombre":"Ilustrador artístico / Ilustradora artística"}],"conocimientos":[{"id":"46","nombre":"Armonía y composición"},{"id":"24","nombre":"Bellas artes"},{"id":"11","nombre":"Diseño"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"30","nombre":"Periodismo, comunicación y reportajes"},{"id":"90","nombre":"Técnicas audiovisuales y producción para medios de comunicación"}],"destrezas":[{"id":"17","nombre":"Análisis de necesidades"},{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"39","nombre":"Creatividad"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"6","nombre":"Pensamiento crítico"}],"ocupaciones_afines":[{"codigo":"21661","nombre":"Diseñadores gráficos / Diseñadoras gráficas"},{"codigo":"21662","nombre":"Diseñadores de imágenes computarizadas e interacción digital / Diseñadoras de imágenes computarizadas e interacción digital"},{"codigo":"26421","nombre":"Periodistas"},{"codigo":"31181","nombre":"Delineantes y dibujantes técnicos / Delineantes y dibujantes técnicas"}],"area_principal":{"sigla":"AVPP","nombre":"Artes visuales, plásticas y del patrimonio cultural"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"2651*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"5141*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"5246","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Intérpretes musicales', '26521', 'Audiovisuales, Artes Escénicas y Música', 4, false, '{"codigo":"26521","nombre":"Intérpretes musicales","descripcion":"Interpretan composiciones y obras musicales con uno o varios instrumentos entre los que puede estar incluida la voz, en conciertos en vivo o sesiones grabadas o colaboraciones con otros artistas. Se pueden desempeñar en agrupaciones musicales instrumentales y vocales, festivales de música, establecimientos que ofrecen música en vivo, estudios de grabación, proyectos musicales o empresas que realizan contrataciones para eventos y giras nacionales e internacionales, compañías de teatro, productoras de cine, televisión, radio y publicidad, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"2","nombre":"PROFESIONALES, CIENTÍFICOS E INTELECTUALES"},"subgrupo_principal":{"codigo":"26","nombre":"PROFESIONALES EN DERECHO, EN CIENCIAS SOCIALES Y CULTURALES"},"subgrupo":{"codigo":"265","nombre":"Artistas creativos e interpretativos"},"grupo_primario":{"codigo":"2652","nombre":"Compositores, músicos y cantantes"}},"funciones":[{"consecutivo":1,"texto":"Interpretar uno o varios instrumentos musicales como solista o como miembro de un grupo musical, en conciertos en vivo o en estudios de grabación en formato pequeño o en agrupaciones de gran formato, orquestas sinfónicas, bandas sinfónicas, grandes corales o agrupaciones sinfónicas con solistas y coros, orquestas de salón, orquesta de baile y agrupaciones de música popular y tradicional entre otros."},{"consecutivo":2,"texto":"Cantar o interpretar instrumentos de manera precisa en tiempo, afinación, intensión, estilo, técnica y ejecución como solista o como miembro de una agrupación musical, en eventos, presentaciones, conciertos en vivo, estudios de grabación o para grabar en estudio en pocas tomas, eventos musicales especializados y en diferentes formatos."},{"consecutivo":3,"texto":"Interpretar partituras de obras instrumentales y vocales de diferente nivel de complejidad."},{"consecutivo":4,"texto":"Interpretar versiones, arreglos o adaptaciones musicales como solistas o miembros de grupos instrumentales o vocales en eventos públicos o para grabación."},{"consecutivo":5,"texto":"Transcribir y adaptar obras para instrumentos y registro vocal."},{"consecutivo":6,"texto":"Improvisar o crear con el instrumento o la voz estructuras armónicas, rítmicas y melódicas de cierta complejidad."},{"consecutivo":7,"texto":"Practicar y ensayar para conseguir y mantener un alto nivel interpretativo."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"26521.001","nombre":"Acompañante musical"},{"codigo":"26521.002","nombre":"Acordeonista"},{"codigo":"26521.003","nombre":"Arpista"},{"codigo":"26521.004","nombre":"Artista lírico / Artista lírica"},{"codigo":"26521.005","nombre":"Bajista"},{"codigo":"26521.006","nombre":"Bajo"},{"codigo":"26521.007","nombre":"Bajo barítono"},{"codigo":"26521.008","nombre":"Bajo buffo"},{"codigo":"26521.009","nombre":"Bajonista"},{"codigo":"26521.010","nombre":"Baritenor"},{"codigo":"26521.011","nombre":"Barítono"},{"codigo":"26521.012","nombre":"Baterista"},{"codigo":"26521.013","nombre":"Campanero / Campanera"},{"codigo":"26521.014","nombre":"Cantante"},{"codigo":"26521.015","nombre":"Cantante bajo"},{"codigo":"26521.016","nombre":"Cantante barítono"},{"codigo":"26521.017","nombre":"Cantante contralto"},{"codigo":"26521.018","nombre":"Cantante coral"},{"codigo":"26521.019","nombre":"Cantante de cabaret"},{"codigo":"26521.020","nombre":"Cantante de concierto"},{"codigo":"26521.021","nombre":"Cantante de discoteca"},{"codigo":"26521.022","nombre":"Cantante de jingles"},{"codigo":"26521.023","nombre":"Cantante de música popular"},{"codigo":"26521.024","nombre":"Cantante de ópera"},{"codigo":"26521.025","nombre":"Cantante de música clásica"},{"codigo":"26521.026","nombre":"Cantante organista"},{"codigo":"26521.027","nombre":"Cantante vocalista"},{"codi