  ('rol_cuoc', 'Técnicos en física y química / Técnicas en física y química', '31111', 'Ciencias naturales, matemáticas y estadística', 3, false, '{"codigo":"31111","nombre":"Técnicos en física y química / Técnicas en física y química","descripcion":"Realizan funciones técnicas para ayudar en la investigación básica y aplicada de la química y bioquímica, química industrial, química farmacéutica y la física, análisis en procesos de producción, controles y supervisiones de procesos, programaciones y control de calidad químico. Se pueden desempeñar en laboratorios, empresas químicas, industrias, procesamiento químico, petroquímico, farmacéuticas, biotécnicas e instituciones educativas y de salud, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"311","nombre":"Técnicos en ciencias físicas y en ingeniería"},"grupo_primario":{"codigo":"3111","nombre":"Técnicos en ciencias de la tierra, físicas y químicas"}},"funciones":[{"consecutivo":1,"texto":"Tomar muestras y preparar materiales y equipos para experimentos, pruebas, medición, calibración y análisis."},{"consecutivo":2,"texto":"Realizar pruebas de laboratorio de rutina y desempeñar una variedad de funciones de apoyo técnico como soporte a los químicos y físicos en la investigación, experimentos, pruebas, desarrollo, análisis y ensayos utilizando técnicas como: la cromatografía, espectroscopia, microscopia y técnicas de separación química y física."},{"consecutivo":3,"texto":"Preparar y realizar estimaciones detalladas de la cantidad de suministros, el uso y el monitoreo de materiales, análisis de muestras, control de calidad, costos y mano de obra necesarios para el laboratorio y los proyectos de acuerdo con las especificaciones establecidas."},{"consecutivo":4,"texto":"Hacer mantenimiento a los instrumentos y los equipos de laboratorio, el seguimiento y el monitoreo a los experimentos."},{"consecutivo":5,"texto":"Apoyar técnicamente la recolección, el registro, la realización de observaciones, el cálculo, el análisis de datos y la interpretación de resultados de mediciones e indicadores."},{"consecutivo":6,"texto":"Ayudar en la programación y preparación de experimentos, pruebas y análisis y ejecutar las tareas técnicas pertinentes."},{"consecutivo":7,"texto":"Apoyar investigaciones y experimentos sobre los efectos de la medicina y otras sustancias en el organismo humano y en el de los animales."},{"consecutivo":8,"texto":"Apoyar en el desarrollo de procesos de ingeniería química, inspección y mantenimiento y en el desarrollo de estándares procedimientos y medidas de salud, seguridad industrial y gestión documental."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31111.001","nombre":"Asistente de producción química / Asistenta de producción química"},{"codigo":"31111.002","nombre":"Inspector químico de calidad / Inspectora química de calidad"},{"codigo":"31111.003","nombre":"Laboratorista químico / Laboratorista química"},{"codigo":"31111.004","nombre":"Supervisor de dispensación de materias primas químicas / Supervisora de dispensación de materias primas químicas"},{"codigo":"31111.005","nombre":"Supervisor de pesaje químico / Supervisora de pesaje químico"},{"codigo":"31111.006","nombre":"Técnico analista de control de calidad química / Técnica analista de control de calidad química"},{"codigo":"31111.007","nombre":"Técnico analista químico / Técnica analista química"},{"codigo":"31111.008","nombre":"Técnico de aseguramiento de calidad química / Técnica de aseguramiento de calidad química"},{"codigo":"31111.009","nombre":"Técnico de control de calidad de procesamiento químico / Técnica de control de calidad de procesamiento químico"},{"codigo":"31111.010","nombre":"Técnico de laboratorio químico / Técnica de laboratorio químico"},{"codigo":"31111.011","nombre":"Técnico físico / Técnica física"},{"codigo":"31111.012","nombre":"Técnico químico / Técnica química"},{"codigo":"31111.013","nombre":"Tecnólogo químico / Tecnóloga química"}],"conocimientos":[{"id":"17","nombre":"Biología"},{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"10","nombre":"Ingeniería y tecnología"},{"id":"14","nombre":"Matemáticas"},{"id":"7","nombre":"Producción y procesamiento"},{"id":"16","nombre":"Química"}],"destrezas":[{"id":"7","nombre":"Aprendizaje aplicado"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"3","nombre":"Redacción de textos"},{"id":"16","nombre":"Resolución de problemas complejos"}],"ocupaciones_afines":[{"codigo":"12230","nombre":"Directores y gerentes de ingeniería, investigación y desarrollo / Directoras y gerentas de ingeniería, investigación y desarrollo"},{"codigo":"21130","nombre":"Químicos / Químicas"},{"codigo":"21310","nombre":"Biólogos, botánicos, zoólogos y afines / Biólogas, botánicas, zoólogas y afines"},{"codigo":"22620","nombre":"Farmacéuticos y químicos farmacéuticos / Farmacéuticas y químicas farmacéuticas"},{"codigo":"31115","nombre":"Auxiliares de laboratorio"},{"codigo":"31160","nombre":"Técnicos en química industrial / Técnicas en química industrial"},{"codigo":"31199","nombre":"Técnicos en ciencias físicas y en ingeniería no clasificados en otras ocupaciones / Técnicas en ciencias físicas y en ingeniería no clasificados en otras ocupaciones"},{"codigo":"31330","nombre":"Controladores de instalaciones de procesamiento de productos químicos / Controladoras de instalaciones de procesamiento de productos químicos"},{"codigo":"31410","nombre":"Técnicos en ciencias biológicas (excluyendo la medicina) / Técnicas en ciencias biológicas (excluyendo la medicina)"},{"codigo":"81311","nombre":"Operadores de máquinas de planta química / Operadoras de máquinas de planta química"}],"area_principal":{"sigla":"CNME","nombre":"Ciencias naturales, matemáticas y estadística"},"areas_complementarias":[{"sigla":"INQU","nombre":"Industria química"}],"equivalencias":[{"ciuo08_codigo":"2113*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"2211*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"3111*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"","cno_obs":""}]}'::jsonb),
  ('rol_cuoc', 'Técnicos en geología / Técnicas en geología', '31112', 'Ciencias naturales, matemáticas y estadística', 3, false, '{"codigo":"31112","nombre":"Técnicos en geología / Técnicas en geología","descripcion":"Realizan funciones técnicas para ayudar en la investigación de la geología y la geofísica, apoyan técnicamente en los campos de exploración y producción de gas y petróleo y en la mineralogía. Se pueden desempeñar en empresas de petróleo y minería, instituciones educativas, entidades del gobierno y firmas consultoras, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"311","nombre":"Técnicos en ciencias físicas y en ingeniería"},"grupo_primario":{"codigo":"3111","nombre":"Técnicos en ciencias de la tierra, físicas y químicas"}},"funciones":[{"consecutivo":1,"texto":"Recoger y analizar muestras de tierra y agua, registrar las observaciones y el análisis de datos para el apoyo de geólogos o geofísicos."},{"consecutivo":2,"texto":"Realizar o participar en reconocimientos geológicos, geofísicos, geoquímicos, hidrográficos y oceanográficos, perforación exploratoria, prospección de campos o programas de inspección de minas subterráneas."},{"consecutivo":3,"texto":"Preparar estimaciones detalladas de cantidades y costos de materiales y mano de obra necesarios para los proyectos, de acuerdo con las especificaciones establecidas."},{"consecutivo":4,"texto":"Apoyar a ingenieros y geólogos en la evaluación y el análisis de pozos petrolíferos y yacimientos de minerales."},{"consecutivo":5,"texto":"Operar, organizar, mantener y reparar los instrumentos, el equipo de registro, de medición geofísica y material de investigación."},{"consecutivo":6,"texto":"Aplicar conocimientos técnicos para identificar y resolver los problemas que surjan en el curso de su trabajo."},{"consecutivo":7,"texto":"Preparar, transcribir o analizar información sísmica, gravimétrica y otros datos de inspección geofísica."},{"consecutivo":8,"texto":"Preparar notas, bosquejos y secciones especiales de mapas geológicos."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31112.001","nombre":"Asistente de geología / Asistenta de geología"},{"codigo":"31112.002","nombre":"Auxiliar de geología"},{"codigo":"31112.003","nombre":"Técnico de geología / Técnica de geología"},{"codigo":"31112.004","nombre":"Técnico de hidrología / Técnica de hidrología"},{"codigo":"31112.005","nombre":"Técnico de oceanografía / Técnica de oceanografía"},{"codigo":"31112.006","nombre":"Técnico en geología y minería / Técnica en geología y minería"},{"codigo":"31112.007","nombre":"Técnico en geofísica / Técnica en geofísica"},{"codigo":"31112.008","nombre":"Técnico geofísico / Técnica geofísica"},{"codigo":"31112.009","nombre":"Técnico geólogo / Técnica geóloga"}],"conocimientos":[{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"10","nombre":"Ingeniería y tecnología"},{"id":"14","nombre":"Matemáticas"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"6","nombre":"Pensamiento crítico"}],"ocupaciones_afines":[{"codigo":"21420","nombre":"Ingenieros civiles / Ingenieras civiles"},{"codigo":"21650","nombre":"Cartógrafos e ingenieros topográficos y catastrales / Cartógrafas e ingenieras topográficas y catastrales"},{"codigo":"31121","nombre":"Técnicos en construcción y arquitectura / Técnicas en construcción y arquitectura"},{"codigo":"31123","nombre":"Técnicos en cartografía / Técnicas en cartografía"},{"codigo":"31181","nombre":"Delineantes y dibujantes técnicos / Delineantes y dibujantes técnicas"},{"codigo":"31211","nombre":"Supervisores de minería y canteras / Supervisoras de minería y canteras"}],"area_principal":{"sigla":"CNME","nombre":"Ciencias naturales, matemáticas y estadística"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"3111*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"2212*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Técnicos en meteorología / Técnicas en meteorología', '31113', 'Ciencias naturales, matemáticas y estadística', 3, false, '{"codigo":"31113","nombre":"Técnicos en meteorología / Técnicas en meteorología","descripcion":"Realizan funciones técnicas para ayudar en la investigación de la meteorología y la astronomía, en el desarrollo de aplicaciones industriales, prácticas médicas, militares y de otro tipo de resultados de investigación; observan condiciones atmosféricas, registran e interpretan información meteorológica, transmiten y reportan la información obtenida al público en general, a los medios de comunicación y empresas de transporte. Se pueden desempeñar en empresas de consultoría ambiental, aeropuertos, fuerzas armadas, instituciones educativas, científicas y del gobierno, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"311","nombre":"Técnicos en ciencias físicas y en ingeniería"},"grupo_primario":{"codigo":"3111","nombre":"Técnicos en ciencias de la tierra, físicas y químicas"}},"funciones":[{"consecutivo":1,"texto":"Observar, registrar y transmitir información de las condiciones climáticas y atmosféricas, incluida la presión del aire, temperatura, humedad, precipitación, viento, condiciones de la radiación ultravioleta y participar en programas de control de avalanchas y erupciones."},{"consecutivo":2,"texto":"Aplicar conocimientos técnicos para analizar, interpretar la información climática e identificar y resolver los problemas que surjan en el curso de su trabajo."},{"consecutivo":3,"texto":"Informar a pilotos, industrias navieras, finqueros, medios de comunicación y otros usuarios sobre las condiciones climáticas."},{"consecutivo":4,"texto":"Mantener base de datos climatológicos y participar en la elaboración de mapas y cartas del clima."},{"consecutivo":5,"texto":"Inspeccionar instalaciones y mantener equipos e instrumentos."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31113.001","nombre":"Inspector meteorológico de puerto / Inspectora meteorológica de puerto"},{"codigo":"31113.002","nombre":"Técnico de astronomía / Técnica de astronomía"},{"codigo":"31113.003","nombre":"Técnico de meteorología / Técnica de meteorología"},{"codigo":"31113.004","nombre":"Técnico meteorólogo / Técnica meteoróloga"},{"codigo":"31113.005","nombre":"Técnico de operaciones de estación meteorológica / Técnica de operaciones de estación meteorológica"},{"codigo":"31113.006","nombre":"Técnico de servicio climatológico / Técnica de servicio climatológico"}],"conocimientos":[{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"14","nombre":"Matemáticas"},{"id":"27","nombre":"Seguridad pública"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"6","nombre":"Pensamiento crítico"}],"ocupaciones_afines":[{"codigo":"21120","nombre":"Meteorólogos / Meteorólogas"}],"area_principal":{"sigla":"CNME","nombre":"Ciencias naturales, matemáticas y estadística"},"areas_complementarias":[{"sigla":"CPSA","nombre":"Conservación, protección y saneamiento ambiental"}],"equivalencias":[{"ciuo08_codigo":"3111*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"2213*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Técnicos en metrología / Técnicas en metrología', '31114', 'Ciencias naturales, matemáticas y estadística', 3, false, '{"codigo":"31114","nombre":"Técnicos en metrología / Técnicas en metrología","descripcion":"Realizan funciones técnicas para ayudar en la investigación de la metrología; realizan mediciones y calibraciones de instrumentos e ítems; registran pruebas y generan informes; gestionan y realizan mantenimiento preventivo de equipos e instrumentos de medición. Se pueden desempeñar en laboratorios de ensayo, calibración y medición, empresas de química, ingeniería, de fabricación y procesamiento industrial e instituciones del gobierno, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"311","nombre":"Técnicos en ciencias físicas y en ingeniería"},"grupo_primario":{"codigo":"3111","nombre":"Técnicos en ciencias de la tierra, físicas y químicas"}},"funciones":[{"consecutivo":1,"texto":"Apoyar el desarrollo de manuales de operación y mantenimiento de instrumentos de medición de acuerdo con procedimientos técnicos."},{"consecutivo":2,"texto":"Registrar y apoyar el procesamiento de datos de los instrumentos y de los procesos de acuerdo con requerimientos y metodología estadística."},{"consecutivo":3,"texto":"Manejar y operar los equipos de medición, ensayos, calibración y de las aplicaciones de software asociadas a los mismos, validando y verificando actividades de calibración y ajustes en los sistemas de acuerdo con procedimientos técnicos y normativa."},{"consecutivo":4,"texto":"Ensayar o probar ítems de acuerdo con procedimientos técnicos y normativa."},{"consecutivo":5,"texto":"Identificar causa raíz de anomalías y realizar el mantenimiento preventivo y correctivo de equipos e instrumentos de medición de acuerdo con procedimientos técnicos."},{"consecutivo":6,"texto":"Apoyar en la administración y control del aseguramiento metrológico de los procesos."},{"consecutivo":7,"texto":"Aplicar conocimientos técnicos para identificar y resolver los problemas que surjan en el curso de su trabajo."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31114.001","nombre":"Laboratorista en metrología"},{"codigo":"31114.002","nombre":"Metrólogo / Metróloga"},{"codigo":"31114.003","nombre":"Técnico de laboratorio en calibración y ensayo / Técnica de laboratorio en calibración y ensayo"},{"codigo":"31114.004","nombre":"Técnico en calibración y aseguramiento metrológico / Técnica en calibración y aseguramiento metrológico"},{"codigo":"31114.005","nombre":"Técnico en medición y ensayos / Técnica en medición y ensayos"},{"codigo":"31114.006","nombre":"Técnico en metrología / Técnica en metrología"},{"codigo":"31114.007","nombre":"Técnico en servicios de calibración / Técnica en servicios de calibración"},{"codigo":"31114.008","nombre":"Tecnólogo en aseguramiento metrológico / Tecnóloga en aseguramiento metrológico"},{"codigo":"31114.009","nombre":"Laboratorista de ensayos y calibraciones"}],"conocimientos":[{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"15","nombre":"Física"},{"id":"10","nombre":"Ingeniería y tecnología"},{"id":"14","nombre":"Matemáticas"},{"id":"13","nombre":"Mecánica y metalistería"},{"id":"101","nombre":"Principios éticos"},{"id":"16","nombre":"Química"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"23","nombre":"Vigilancia de las operaciones"}],"ocupaciones_afines":[{"codigo":"31150","nombre":"Técnicos en ingeniería mecánica / Técnicas en ingeniería mecánica"},{"codigo":"72331","nombre":"Mecánicos industriales / Mecánicas industriales"},{"codigo":"73110","nombre":"