  ('rol_cuoc', 'Auxiliares de laboratorio', '31115', 'Industria química', 2, false, '{"codigo":"31115","nombre":"Auxiliares de laboratorio","descripcion":"Realizan funciones técnicas para ayudar en la investigación y en el desarrollo de aplicaciones industriales y prácticas médicas, realizan actividades de alistamiento, almacenamiento de ítems, productos y materiales; análisis y ensayos básicos de laboratorio; medición a los procesos de ensayo y calibración; operación y mantenimiento básico de equipos e instrumentos y preparación de soluciones e insumos necesarios para el funcionamiento de laboratorios. Llevan registros y reportan información sobre resultados de análisis y ensayos de muestras. Se pueden desempeñar en laboratorios, empresas de química, ingeniería, de fabricación y procesamiento e instituciones del gobierno, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"311","nombre":"Técnicos en ciencias físicas y en ingeniería"},"grupo_primario":{"codigo":"3111","nombre":"Técnicos en ciencias de la tierra, físicas y químicas"}},"funciones":[{"consecutivo":1,"texto":"Tomar muestras, preparar materiales y equipos para experimentos, pruebas y análisis especiales de laboratorio según procedimientos técnicos y normativa."},{"consecutivo":2,"texto":"Realizar el control de calidad, cantidad y monitoreo de los suministros de laboratorio de análisis, muestras y usos."},{"consecutivo":3,"texto":"Operar y mantener equipos e instrumentos de laboratorio según procedimientos técnicos y normativa."},{"consecutivo":4,"texto":"Monitorear experimentos, realizar observaciones, calcular y registrar los resultados."},{"consecutivo":5,"texto":"Ayudar en la programación y preparación de experimentos, pruebas y análisis y ejecución de funciones técnicas pertinentes."},{"consecutivo":6,"texto":"Preparar soluciones, reactivos e insumos de uso en el laboratorio de acuerdo con los requerimientos técnicos, normativa y asegurando el estricto cumplimiento de normas de seguridad."},{"consecutivo":7,"texto":"Cumplir con el programa de implementación de buenas prácticas del laboratorio según normativa."},{"consecutivo":8,"texto":"Realizar operaciones de recepción, almacenamiento de ítems, productos y materiales de laboratorios según procedimientos técnicos y normativa para análisis, ensayos, calibración, entre otros."},{"consecutivo":9,"texto":"Preparar estimaciones detalladas de cantidades, costos de materiales y mano de obra necesarios para los proyectos, de acuerdo con las especificaciones establecidas."},{"consecutivo":10,"texto":"Organizar el mantenimiento, reparación y realización de operaciones de alistamiento del equipo, material de investigación y del laboratorio según procedimientos técnicos y normativa."},{"consecutivo":11,"texto":"Aplicar conocimientos técnicos para identificar y resolver los problemas que surjan en el curso de su trabajo."},{"consecutivo":12,"texto":"Mantener condiciones de salud y seguridad en el laboratorio según normativa."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31115.001","nombre":"Asistente de laboratorio de procesamiento químico / Asistenta de laboratorio de procesamiento químico"},{"codigo":"31115.002","nombre":"Asistente de laboratorio químico / Asistenta de laboratorio químico"},{"codigo":"31115.003","nombre":"Asistente o auxiliar de laboratorio acuícola / Asistenta o auxiliar de laboratorio acuícola"},{"codigo":"31115.004","nombre":"Auxiliar de laboratorio de calibraciones y ensayos"},{"codigo":"31115.005","nombre":"Auxiliar de laboratorio procesamiento químico"},{"codigo":"31115.006","nombre":"Auxiliar de laboratorio químico"},{"codigo":"31115.007","nombre":"Auxiliar de mediciones y ensayos"},{"codigo":"31115.008","nombre":"Auxiliar de pruebas y ensayos de laboratorio"},{"codigo":"31115.010","nombre":"Auxiliar de control de calidad de laboratorio"},{"codigo":"31115.011","nombre":"Auxiliar documental de laboratorio"}],"conocimientos":[{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"15","nombre":"Física"},{"id":"14","nombre":"Matemáticas"},{"id":"16","nombre":"Química"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"7","nombre":"Aprendizaje aplicado"},{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"6","nombre":"Pensamiento crítico"}],"ocupaciones_afines":[{"codigo":"21130","nombre":"Químicos / Químicas"},{"codigo":"21450","nombre":"Ingenieros químicos / Ingenieras químicas"},{"codigo":"31111","nombre":"Técnicos en física y química / Técnicas en física y química"},{"codigo":"31160","nombre":"Técnicos en química industrial / Técnicas en química industrial"},{"codigo":"31330","nombre":"Controladores de instalaciones de procesamiento de productos químicos / Controladoras de instalaciones de procesamiento de productos químicos"},{"codigo":"31410","nombre":"Técnicos en ciencias biológicas (excluyendo la medicina) / Técnicas en ciencias biológicas (excluyendo la medicina)"}],"area_principal":{"sigla":"INQU","nombre":"Industria química"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"3111*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"2312","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Técnicos en construcción y arquitectura / Técnicas en construcción y arquitectura', '31121', 'Construcción e infraestructura', 3, false, '{"codigo":"31121","nombre":"Técnicos en construcción y arquitectura / Técnicas en construcción y arquitectura","descripcion":"Apoyan técnicamente en la ingeniería civil, ingeniería de vías y transporte, ingeniería hidráulica y arquitectura, en lo relacionado con el diseño y la supervisión de construcción de proyectos edificación e infraestructura. Se pueden desempeñar en compañías de construcción, obras públicas, transporte, entidades del gobierno y privadas, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"311","nombre":"Técnicos en ciencias físicas y en ingeniería"},"grupo_primario":{"codigo":"3112","nombre":"Técnicos en ingeniería civil"}},"funciones":[{"consecutivo":1,"texto":"Vigilar y supervisar el cumplimiento de las especificaciones de diseño, legislación y reglamentaciones pertinentes y las normas establecidas en cuanto a materiales y trabajo."},{"consecutivo":2,"texto":"Efectuar trabajos técnicos relacionados con los estudios y la construcción de edificios y de obras de infraestructura incluyendo la elaboración de informes."},{"consecutivo":3,"texto":"Aplicar conocimientos técnicos de los principios y prácticas de la ingeniería civil para identificar y resolver los problemas que surjan en el curso de su trabajo."},{"consecutivo":4,"texto":"Asistir en el desarrollo de diseños arquitectónicos y de ingeniería civil preparando dibujos y modelos de acuerdo con requerimientos técnicos."},{"consecutivo":5,"texto":"Asistir en la planeación y preparación de las especificaciones de construcción, procesos de planeación, elaboración de documentos de propuestas, contratos de planeación, programación