  ('rol_cuoc', 'Técnicos en topografía / Técnicas en topografía', '31122', 'Construcción e infraestructura', 3, false, '{"codigo":"31122","nombre":"Técnicos en topografía / Técnicas en topografía","descripcion":"Realizan funciones técnicas relacionadas con la topografía; efectúan levantamientos y replanteos topográficos para determinar la localización y ubicación exacta y posiciones relativas y otras características de un terreno y su relieve, ejecutan acciones de georreferenciación, control de niveles, control de asentamientos y control de excavaciones. Se pueden desempeñar en empresas o departamentos de agrimensura y geomática, construcción, infraestructura, consultorías, ciencias forenses, tránsito, minería y demás organizaciones del sector público y privado, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"311","nombre":"Técnicos en ciencias físicas y en ingeniería"},"grupo_primario":{"codigo":"3112","nombre":"Técnicos en ingeniería civil"}},"funciones":[{"consecutivo":1,"texto":"Realizar funciones técnicas relacionadas con la ejecución de obras de ingeniería civil, levantamientos topográficos e informes al respecto."},{"consecutivo":2,"texto":"Efectuar levantamientos topográficos y operar instrumentos de medición de distancias, altimetría, ángulos, elevaciones, contornos del suelo y subsuelo, modelo digital del terreno según especificaciones técnicas de topografía y fotogrametría para toda clase de obras incluyendo las especiales como túneles, viaductos y puentes."},{"consecutivo":3,"texto":"Realizar visitas de campo y registrar dimensiones y otra información obtenida durante actividades de campo."},{"consecutivo":4,"texto":"Analizar la latitud, la longitud, los ángulos y la cartera topográfica; realizar cálculos trigonométricos para trazar las características, contornos y áreas en una escala específica."},{"consecutivo":5,"texto":"Apoyar a los ingenieros y otros profesionales a desarrollar métodos y procedimientos de mediciones de campo."},{"consecutivo":6,"texto":"Preparar representaciones gráficas, planos, cartas, digitalización de mapas, procesamiento de datos, informes y reportes de levantamientos topográficos, catastrales y geodésicos, proponer diseños y rutas topográficas."},{"consecutivo":7,"texto":"Localizar proyectos viales, obras de urbanismo e hidráulicas de acuerdo con planos y especificaciones técnicas."},{"consecutivo":8,"texto":"Coordinar actividades topográficas de campo."},{"consecutivo":9,"texto":"Supervisar la preparación y compilación de todos los datos, planos, cartas, registros y documentos relacionados con la medición de linderos de propiedad raíz y levantamiento topográfico de agrimensura y catastro multipropósito."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31122.001","nombre":"Agrimensor / Agrimensora"},{"codigo":"31122.002","nombre":"Agrimensor catastral / Agrimensora catastral"},{"codigo":"31122.003","nombre":"Agrimensor de edificio / Agrimensora de edificio"},{"codigo":"31122.004","nombre":"Agrimensor de minas / Agrimensora de minas"},{"codigo":"31122.005","nombre":"Agrimensor de topografía / Agrimensora de topografía"},{"codigo":"31122.006","nombre":"Agrimensor de topografía aérea / Agrimensora de topografía aérea"},{"codigo":"31122.007","nombre":"Agrimensor geodésico / Agrimensora geodésica"},{"codigo":"31122.008","nombre":"Agrimensor hidrográfico / Agrimensora hidrográfica"},{"codigo":"31122.009","nombre":"Agrimensor marino / Agrimensora marina"},{"codigo":"31122.010","nombre":"Capataz topotrocha"},{"codigo":"31122.011","nombre":"Geomensor /Geomensora"},{"codigo":"31122.012","nombre":"Técnico agrimensor / Técnica agrimensora"},{"codigo":"31122.013","nombre":"Técnico de soporte en geomática / Técnica de soporte en geomática"},