  ('rol_cuoc', 'Técnicos en cartografía / Técnicas en cartografía', '31123', 'Construcción e infraestructura', 3, false, '{"codigo":"31123","nombre":"Técnicos en cartografía / Técnicas en cartografía","descripcion":"Apoyan la operación de equipos, objetos e instrumentos cartográficos para la elaboración de mapas temáticos y salidas gráficas utilizando sistemas de información geográfica y software especializados. Se pueden desempeñar en compañías de cartografía, firmas consultoras, gobierno, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"311","nombre":"Técnicos en ciencias físicas y en ingeniería"},"grupo_primario":{"codigo":"3112","nombre":"Técnicos en ingeniería civil"}},"funciones":[{"consecutivo":1,"texto":"Apoyar en el desarrollo de pruebas de campo y/o laboratorio de suelos para la concepción y producción de representaciones gráficas y mapas."},{"consecutivo":2,"texto":"Aplicar especificaciones de diseño, normas, legislación y reglamentación en materiales y trabajo de productos cartográficos."},{"consecutivo":3,"texto":"Asistir en la elaboración de estimaciones de cantidades y costos de materiales y mano de obra para proyectos, de acuerdo con las especificaciones técnicas."},{"consecutivo":4,"texto":"Apoyar en la creación del contenido, formato y diseño de mapas de acuerdo con requerimientos técnicos."},{"consecutivo":5,"texto":"Apoyar la recolección de información requerida con base en fotografías, aéreas, mediciones, registros, reportes y otros mapas."},{"consecutivo":6,"texto":"Asistir en la generación de mapas, gráficas y cartas relacionadas utilizando técnicas cartográficas y digitales, programas interactivos de graficación o métodos de dibujo e instrumentos tradicionales de trazado."},{"consecutivo":7,"texto":"Inspeccionar el trabajo final para garantizar su terminación y exactitud."},{"consecutivo":8,"texto":"Examinar e interpretar fotografías aéreas para apoyar la elaboración de mapas topográficos, mosaicos de fotografía aérea y cartas relacionadas."},{"consecutivo":9,"texto":"Operar el diagramador estereoscópico y el graficador del computador para generar modelos ópticos tridimensionales de terreno, trazar mapas y preparar cartas y tablas."},{"consecutivo":10,"texto":"Operar equipo censor remoto desde el aire como cámaras de medición, censores y scanners para aplicaciones en geología, explotación forestal, planeación urbana y otros campos de la ciencia."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31123.001","nombre":"Técnico cartógrafo marino / Técnica cartógrafa marina"},{"codigo":"31123.002","nombre":"Técnico compilador cartográfico / Técnica compiladora cartográfica"},{"codigo":"31123.003","nombre":"Técnico de cartografía / Técnica de cartografía"},{"codigo":"31123.004","nombre":"Técnico fotogrametrista / Técnica fotogrametrista"},{"codigo":"31123.005","nombre":"Técnico en sistemas de información geográfica / Técnica en sistemas de información geográfica"}],"conocimientos":[{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"12","nombre":"Construcción e ingeniería civil"},{"id":"20","nombre":"Geografía y territorio"},{"id":"14","nombre":"Matemáticas"},{"id":"27","nombre":"Seguridad pública"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"1","nombre":"Comprensión de lectura"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"11","nombre":"Trabajo en equipo"},{"id":"23","nombre":"Vigilancia de las operaciones"}],"ocupaciones_afines":[{"codigo":"21420","nombre":"Ingenieros civiles / Ingenieras civiles"},{"codigo":"22630","nombre":"Profesionales de la salud y la higie