  ('rol_cuoc', 'Técnicos en electrónica / Técnicas en electrónica', '31141', 'Electrónica y automatización', 3, false, '{"codigo":"31141","nombre":"Técnicos en electrónica / Técnicas en electrónica","descripcion":"Apoyan técnicamente en la investigación de la ingeniería electrónica y eléctrica, en el diseño, desarrollo, fabricación, montaje, construcción, integración, programación, operación, prueba, inspección, mantenimiento, reparación de equipos y componentes electrónicos. Ensamblan equipos y partes electrónicas de acuerdo con protocolos de producción. Se pueden desempeñar en empresas de ingeniería, de fabricación y procesamiento e instituciones del gobierno, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"311","nombre":"Técnicos en ciencias físicas y en ingeniería"},"grupo_primario":{"codigo":"3114","nombre":"Técnicos en electrónica, automatización e instrumentación"}},"funciones":[{"consecutivo":1,"texto":"Prestar y apoyar técnicamente actividades de investigación, desarrollo y pruebas de equipos y prototipos electrónicos."},{"consecutivo":2,"texto":"Proyectar, preparar y alistar planos de instalaciones y circuitos electrónicos de acuerdo con especificaciones establecidas."},{"consecutivo":3,"texto":"Preparar estimaciones detalladas de cantidades y costos de materiales y mano de obra necesarios para la fabricación e instalación de equipos electrónicos, de acuerdo con las especificaciones establecidas."},{"consecutivo":4,"texto":"Preparar y contribuir en el diseño, el desarrollo, las especificaciones, la instalación, la operación y el mantenimiento de sistemas de transmisión de energía, máquinas, calefacción, aire acondicionado, componentes electrónicos incluyendo, entre otros."},{"consecutivo":5,"texto":"Planificar los métodos de instalación, comprobando la seguridad de los equipos instalados y el correcto funcionamiento de los nuevos equipos o sistemas electrónicos."},{"consecutivo":6,"texto":"Describir especificaciones, programaciones e informes técnicos y controlar las programaciones y los presupuestos."},{"consecutivo":7,"texto":"Efectuar el control técnico de la fabricación, la utilización de equipos electrónicos aplicando conocimientos técnicos de los principios y las prácticas de electrónica."},{"consecutivo":8,"texto":"Realizar actividades de calibración y ajustar los equipos, instrumentos electrónicos de acuerdo con los manuales y las instrucciones establecidas."},{"consecutivo":9,"texto":"Realizar pruebas y análisis de productos electrónicos, máquinas, componentes y materiales para determinar su funcionamiento, resistencia y otras características de acuerdo con protocolos y especificaciones técnicas."},{"consecutivo":10,"texto":"Ensamblar prototipos y dispositivos electrónicos de acuerdo con los requerimientos de los clientes y la normatividad técnica."},{"consecutivo":11,"texto":"Realizar y brindar soporte técnico y pos-venta de los proyectos y productos desarrollados por la empresa, de acuerdo con los manuales técnicos, de instalación y programación."},{"consecutivo":12,"texto":"Reparar tarjetas electrónicas de acuerdo con técnicas especializadas de diagnóstico."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31141.001","nombre":"Asistente de ingeniería de hardware / Asistenta de ingeniería de hardware"},{"codigo":"31141.002","nombre":"Asistente informático de ingeniería hardware / Asistenta informática de ingeniería hardware"},{"codigo":"31141.003","nombre":"Auxiliar de pruebas en electrónica"},{"codigo":"31141.004","nombre":"Auxiliar de desarrollo de hardware"},{"codigo":"31141.005","nombre":"Estimador de ingeniería electrónica / Estimadora de ingeniería electrónica"},{"codigo":"31141.006","nombre":"Regulador de la calidad de productos electrónico