  ('rol_cuoc', 'Auxiliares de producción gráfica', '31182', 'Literatura y artes gráficas', 2, false, '{"codigo":"31182","nombre":"Auxiliares de producción gráfica","descripcion":"Prestan apoyo en los diferentes procesos de la producción gráfica como en la calidad, los acabados, la revisión de impresos, los reportes del almacén, la bodega, los despachos, el inventario de insumos y el archivo de planchas. Se pueden desempeñar en encuadernadoras, empresas comerciales de impresión, periódicos, revistas y otras empresas de publicaciones y establecimientos tanto del sector público como del privado con departamentos de impresión y encuadernación, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"311","nombre":"Técnicos en ciencias físicas y en ingeniería"},"grupo_primario":{"codigo":"3118","nombre":"Delineantes y dibujantes técnicos"}},"funciones":[{"consecutivo":1,"texto":"Revisar el material impreso y verificar las cantidades empacadas de acuerdo con el pedido del cliente."},{"consecutivo":2,"texto":"Apoyar a los operarios de impresión con el abastecimiento de insumos y limpieza de las máquinas de impresión."},{"consecutivo":3,"texto":"Apoyar los procesos de terminados y acabados de productos gráficos."},{"consecutivo":4,"texto":"Alistar materia prima e insumos que salen y entran del almacén y bodega."},{"consecutivo":5,"texto":"Realizar y transferir dibujos, ilustraciones y pinturas de copia a piezas o planchas metálicas para impresión."},{"consecutivo":6,"texto":"Organizar los dibujos completos para ser reproducidos para su uso como dibujos de trabajo."},{"consecutivo":7,"texto":"Medir las soluciones fuentes antes de iniciar operaciones de impresión."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31182.001","nombre":"Auxiliar de calidad en producción gráfica"},{"codigo":"31182.002","nombre":"Auxiliar de dibujo publicitario"},{"codigo":"31182.003","nombre":"Auxiliar de diseño gráfico"},{"codigo":"31182.004","nombre":"Auxiliar de producción gráfica"},{"codigo":"31182.005","nombre":"Auxiliar de suministros en producción gráfica"},{"codigo":"31182.006","nombre":"Auxiliar de terminados y acabados en producción gráfica"}],"conocimientos":[{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"11","nombre":"Diseño"},{"id":"30","nombre":"Periodismo, comunicación y reportajes"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"6","nombre":"Pensamiento crítico"}],"ocupaciones_afines":[{"codigo":"21661","nombre":"Diseñadores gráficos / Diseñadoras gráficas"},{"codigo":"31181","nombre":"Delineantes y dibujantes técnicos / Delineantes y dibujantes técnicas"},{"codigo":"31183","nombre":"Graficadores de imágenes computarizadas / Graficadoras de imágenes computarizadas"},{"codigo":"73211","nombre":"Pre-impresores y pre-prensistas de artes gráficas / Pre-impresoras y pre-prensistas de artes gráficas"},{"codigo":"73212","nombre":"Tipógrafos / Tipógrafas"}],"area_principal":{"sigla":"LIAG","nombre":"Literatura y artes gráficas"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"3118*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"9398*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Graficadores de imágenes computarizadas / Graficadoras de imágenes computarizadas', '31183', 'Literatura y artes gráficas', 3, false, '{"codigo":"31183","nombre":"Graficadores de imágenes computarizadas / Graficadoras de imágenes computarizadas","descripcion":"Crean imágenes por medio del computador utilizando programas de diseño, renderización y modelación digital. Se pueden desempeñar en empresas de diseño gráfico y publicidad, departamentos de publicidad y productoras audiovisuales, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"311","nombre":"Técnicos en ciencias físicas y en ingeniería"},"grupo_primario":{"codigo":"3118","nombre":"Delineantes y dibujantes técnicos"}},"funciones":[{"consecutivo":1,"texto":"Revisar el material computarizado y hacer control de calidad de acuerdo con los requerimientos del cliente."},{"consecutivo":2,"texto":"Crear y controlar imágenes en programas digitales interactivos."},{"consecutivo":3,"texto":"Validar imágenes para el proceso de pre-prensa."},{"consecutivo":4,"texto":"Realizar ajustes, pruebas a imágenes y retoques digitales a las imágenes sobre el balance, contraste, nitidez, etc."},{"consecutivo":5,"texto":"Graficar elementos, empaques e imágenes para espacios y productos gráficos, además de modelar, renderizar y generar efectos especiales."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31183.001","nombre":"Colorista gráfico / Colorista gráfica"},{"codigo":"31183.002","nombre":"Graficador de imágenes computarizadas / Graficadora de imágenes computarizadas"},{"codigo":"31183.003","nombre":"Modelador gráfico / Modeladora gráfica"},{"codigo":"31183.004","nombre":"Renderizador gráfico / Renderizadora gráfica"},{"codigo":"31183.005","nombre":"Retocador de imágenes digitales / Retocadora de imágenes digitales"},{"codigo":"31183.006","nombre":"Graficador de imágenes 3D  / Graficadora de imágenes 3D"}],"conocimientos":[{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"11","nombre":"Diseño"},{"id":"10","nombre":"Ingeniería y tecnología"},{"id":"14","nombre":"Matemáticas"}],"destrezas":[{"id":"7","nombre":"Aprendizaje aplicado"},{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"6","nombre":"Pensamiento crítico"}],"ocupaciones_afines":[{"codigo":"21610","nombre":"Arquitectos / Arquitectas"},{"codigo":"21661","nombre":"Diseñadores gráficos / Diseñadoras gráficas"},{"codigo":"21662","nombre":"Diseñadores de imágenes computarizadas e interacción digital / Diseñadoras de imágenes computarizadas e interacción digital"},{"codigo":"26512","nombre":"Ilustradores artísticos / Ilustradoras artísticas"},{"codigo":"31121","nombre":"Técnicos en construcción y arquitectura / Técnicas en construcción y arquitectura"},{"codigo":"31181","nombre":"Delineantes y dibujantes técnicos / Delineantes y dibujantes técnicas"},{"codigo":"73211","nombre":"Pre-impresores y pre-prensistas de artes gráficas / Pre-impresoras y pre-prensistas de artes gráficas"}],"area_principal":{"sigla":"LIAG","nombre":"Literatura y artes gráficas"},"areas_complementarias":[{"sigla":"COIF","nombre":"Construcción e infraestructura"}],"equivalencias":[{"ciuo08_codigo":"3118*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"5141*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"5247*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Técnicos en fabricación industrial / Técnicas en fabricación industrial', '31191', 'Fabricación, transformación de materiales, instalación, mantenimiento y reparación', 3, false, '{"codigo":"31191","nombre":"Técnicos en fabricación industrial / Técnicas en fabricación industrial","descripcion":"Apoyan técnicamente en el desarrollo de métodos y sistemas de producción, distribución de planta y en la planeación, cálculo, medición y programación del trabajo. Se pueden desempeñar en empresas industriales y de fabricación, entidades gubernamentales, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"311","nombre":"Técnicos en ciencias físicas y en ingeniería"},"grupo_primario":{"codigo":"3119","nombre":"Técnicos en ciencias físicas y en ingeniería no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Modificar y realizar pruebas de equipos y dispositivos utilizados en la prevención, el control y la remediación de la contaminación ambiental, el saneamiento de los lugares contaminados para la recuperación de tierras."},{"consecutivo":2,"texto":"Recopilar datos y prestar asistencia técnica en relación con: la utilización eficiente, segura y rentable de la mano de obra, los materiales y equipos, métodos de trabajo y la secuencia de las operaciones y la supervisión de su ejecución."},{"consecutivo":3,"texto":"Recopilar datos y prestar asistencia técnica y de asesoría en relación con: el diseño y disposición eficiente de las instalaciones de planta y equipos de producción, la utilización eficiente, segura y rentable de la mano de obra, los materiales y equipos, métodos de trabajo y la secuencia de las operaciones y la supervisión de su ejecución."},{"consecutivo":4,"texto":"Ayudar a identificar los peligros potenciales e implantar los procedimientos de seguridad y dispositivos."},{"consecutivo":5,"texto":"Asistir a los ingenieros encargados de realizar pruebas y diseño de equipos de robótica."},{"consecutivo":6,"texto":"Apoyar experimentos, ensayos y análisis químicos utilizando técnicas como: la cromatografía, espectroscopia, técnicas de separación química y física y microscopia."},{"consecutivo":7,"texto":"Apoyar en el desarrollo de programas de muestreos y análisis para mantener parametrización y estándares de calidad de materias primas, agentes químicos y productos."},{"consecutivo":8,"texto":"Apoyar en el diseño y la fabricación de aparatos experimentales, nuevos productos y acabados de los mismos."},{"consecutivo":9,"texto":"Apoyar en la gestión documental y registros de prácticas de manufactura."},{"consecutivo":10,"texto":"Realizar estudios de métodos, tiempos y movimientos apoyando en las validaciones de métodos, técnicas y analíticas, estabilidades del proceso y sistemas de apoyo crítico."},{"consecutivo":11,"texto":"Verificar, inspeccionar y manejar los inventarios, reintegro de materiales y capacidad de la producción, dispensación de materias primas, fraccionamiento y cálculos para el correcto procesamiento de productos."},{"consecutivo":12,"texto":"Apoyar la implementación de programas de salud ocupacional, seguridad industrial y prevención de incendios y coordinar programas de entrenamiento en seguridad industrial."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31191.001","nombre":"Técnico analista de tiempos y movimientos / Técnica analista de tiempos y movimientos"},{"codigo":"31191.002","nombre":"Técnico de control de procesos / Técnica de control de procesos"},{"codigo":"31191.003","nombre":"Técnico de control de producción / Técnica de control de producción"},{"codigo":"31191.004","nombre":"Técnico de diseño de empaques / Técnica de diseño de empaques"},{"codigo":"31191.005","nombre":"Técnico de diseño de moldes / T