  ('rol_cuoc', 'Supervisores de minería y canteras / Supervisoras de minería y canteras', '31211', 'Exploración y extracción de minas, canteras, petróleo y gas', 3, false, '{"codigo":"31211","nombre":"Supervisores de minería y canteras / Supervisoras de minería y canteras","descripcion":"Supervisan y coordinan las actividades de los trabajadores de minería bajo tierra, a cielo abierto y en canteras; operaciones de extracción y extracción. Se pueden desempeñar en compañías mineras y canteras, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"312","nombre":"Supervisores en la minería, la industria manufacturera y la construcción"},"grupo_primario":{"codigo":"3121","nombre":"Supervisores de minas y perforación"}},"funciones":[{"consecutivo":1,"texto":"Supervisar, coordinar y programar actividades de trabajadores que extraen de la tierra minerales y otros depósitos naturales y que operan los medios de transporte subterráneos, equipo pesado, perforadores, operarios de voladura y otros trabajadores de minas a cielo abierto y canteras de acuerdo con técnicas establecidas, parámetros normativos y estándares para labores de desarrollo, preparación y explotación."},{"consecutivo":2,"texto":"Establecer e implementar métodos para asegurar el cumplimiento y control de asistencia de personal, horarios de trabajo, despachos de turno, asignación de funciones, establecimiento de metas y medidas para mejorar la productividad y realizar recomendaciones a los directores de las explotaciones mineras."},{"consecutivo":3,"texto":"Trabajar juntamente con el personal directivo y técnico, con otros departamentos y contratistas para resolver los problemas operativos y coordinar actividades."},{"consecutivo":4,"texto":"Preparar, elaborar y proporcionar informes de producción, datos relativos a los aspectos de la minería o las operaciones de explotación de canteras y otros reportes en explotaciones mineras a los administradores de la minería, entre otros."},{"consecutivo":5,"texto":"Establecer métodos para cumplir con las metas de producción y coordinar actividades de trabajo con otros departamentos."},{"consecutivo":6,"texto":"Instruir y entrenar al personal sobre sus deberes y funciones a realizar en el trabajo, las normas de seguridad y políticas de la empresa."},{"consecutivo":7,"texto":"Resolver problemas de trabajo y recomendar medidas que mejoren la productividad."},{"consecutivo":8,"texto":"Vigilar y hacer recomendaciones a los clientes internos y externos sobre las normas y los protocoles de seguridad en la explotación en minas y canteras."},{"consecutivo":9,"texto":"Determinar las necesidades del personal y aprovisionamiento, hacer requisiciones de materiales y suministros de acuerdo con requerimientos técnicos en explotaciones mineras en minas o canteras."},{"consecutivo":10,"texto":"Hacer recomendaciones sobre incentivos y ascensos del personal."},{"consecutivo":11,"texto":"Realizar inspecciones periódicas en los frentes de trabajo."},{"consecutivo":12,"texto":"Suministrar la información de resultados operativos con la oportunidad y la calidad establecidos por la gerencia de minas."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31211.001","nombre":"Analista de minería a cielo abierto"},{"codigo":"31211.002","nombre":"Capataz de cantera"},{"codigo":"31211.003","nombre":"Capataz de minas"},{"codigo":"31211.004","nombre":"Capataz de minería a cielo abierto"},{"codigo":"31211.005","nombre":"Capataz de minería bajo tierra"},{"codigo":"31211.006","nombre":"Capataz de mina subterránea"},{"codigo":"31211.008","nombre":"Controlador de materiales de minería / Controladora de materiales de minería"},{"codigo":"31211.009","nombre":"Coordinador de operaciones subterráneas / Coordinadora de operac