  ('rol_cuoc', 'Supervisores y analistas de producción de hidrocarburos / Supervisoras y analistas de producción de hidrocarburos', '31213', 'Exploración y extracción de minas, canteras, petróleo y gas', 3, false, '{"codigo":"31213","nombre":"Supervisores y analistas de producción de hidrocarburos / Supervisoras y analistas de producción de hidrocarburos","descripcion":"Supervisan, controlan y aseguran la ejecución de las actividades de la operación, el mantenimiento y la integridad en superficie de los fluidos y equipos, así como la buena administración del recurso humano a su cargo. Se pueden desempeñar en plantas de hidrocarburos, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"312","nombre":"Supervisores en la minería, la industria manufacturera y la construcción"},"grupo_primario":{"codigo":"3121","nombre":"Supervisores de minas y perforación"}},"funciones":[{"consecutivo":1,"texto":"Supervisar, programar y coordinar las actividades de trabajadores que operan en refinerías de petróleo, plantas químicas y oleoductos."},{"consecutivo":2,"texto":"Supervisar las técnicas y los aspectos operativos en el sistema de suministro de gas y transporte de tanques."},{"consecutivo":3,"texto":"Verificar condiciones de operación, para garantizar la producción proyectada de la planta de hidrocarburos."},{"consecutivo":4,"texto":"Instruir y dar inducción al personal sobre sus deberes en el trabajo verificando el cumplimiento de normas de seguridad industrial y vigilancia y políticas de la empresa."},{"consecutivo":5,"texto":"Establecer métodos para asegurar el cumplimiento de los horarios de trabajo, programas de producción, coordinar actividades con otras áreas y recomendar a los directores de explotaciones de hidrocarburos medidas para mejorar la productividad."},{"consecutivo":6,"texto":"Trabajar con el personal directivo y técnico, con otros departamentos y contratistas para resolver los problemas operativos y coordinar actividades."},{"consecutivo":7,"texto":"Verificar e inspeccionar instalaciones para suministro de gas, artefactos a gas, equipos de medición y regulación, sistemas de ventilación y evacuación."},{"consecutivo":8,"texto":"Determinar las necesidades de personal, materiales, herramientas y equipos del proyecto, y realizar la requisición para posibilitar su suministro."},{"consecutivo":9,"texto":"Identificar, investigar, documentar e informar sobre potenciales problemas, ambientales y de seguridad industrial."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31213.001","nombre":"Analista en la industria petrolera"},{"codigo":"31213.002","nombre":"Asistente de perforación de petróleo y gas / Asistenta de perforación de petróleo y gas"},{"codigo":"31213.003","nombre":"Asistente de producción en la industria petrolera / Asistenta de producción en la industria petrolera"},{"codigo":"31213.004","nombre":"Capataz de cuadrilla de mantenimiento industria petrolera"},{"codigo":"31213.005","nombre":"Capataz de cuadrilla de rocería industria petrolera"},{"codigo":"31213.006","nombre":"Capataz de planta de producción de gas"},{"codigo":"31213.007","nombre":"Capataz de planta de gas"},{"codigo":"31213.008","nombre":"Coordinador de facilidades y producción de petróleo y gas / Coordinadora de facilidades y producción de petróleo y gas"},{"codigo":"31213.009","nombre":"Jefe de cuadrilla de mantenimiento industria petrolera / Jefa de cuadrilla de mantenimiento industria petrolera"},{"codigo":"31213.010","nombre":"Jefe de cuadrilla de rocería industria petrolera / Jefa de cuadrilla de rocería industria petrolera"},{"codigo":"31213.011","nombre":"Jefe de planta de producción de gas / Jefa de planta de producción de gas"},{"codigo":"31213.012","nombre":"Jefe de taller de industria pe