  ('rol_cuoc', 'Supervisores de procesamiento de alimentos y bebidas / Supervisoras de procesamiento de alimentos y bebidas', '31221', 'Elaboración y transformación de alimentos', 3, false, '{"codigo":"31221","nombre":"Supervisores de procesamiento de alimentos y bebidas / Supervisoras de procesamiento de alimentos y bebidas","descripcion":"Supervisan y coordinan las actividades de trabajadores que operan máquinas de procesamiento, empaque o clasificación de alimentos y bebidas. Se pueden desempeñar en harineras, plantas procesadoras de frutas y verduras, carnes y pescados, productos lácteos, ingenios azucareros, cervecerías, plantas procesadoras de alimentos y de bebidas, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"312","nombre":"Supervisores en la minería, la industria manufacturera y la construcción"},"grupo_primario":{"codigo":"3122","nombre":"Supervisores de industrias manufactureras"}},"funciones":[{"consecutivo":1,"texto":"Supervisar, programar, orientar y coordinar las actividades de los trabajadores, los técnicos en control de procesos, operadores de máquinas, ensambladores y en las diferentes líneas de producción y de la industria manufacturera."},{"consecutivo":2,"texto":"Garantizar la seguridad de los trabajadores, mediante instrucción en normas de seguridad y condiciones de trabajo; resolver problemas laborales."},{"consecutivo":3,"texto":"Establecer medidas para mejorar la productividad de los procesos y la calidad del producto."},{"consecutivo":4,"texto":"Supervisar el cumplimiento de los protocolos de bioseguridad, ambientales, de producción, calidad, trazabilidad y cadena de custodia, mantenimiento e inventarios."},{"consecutivo":5,"texto":"Establecer métodos y llevar registros de producción, control de calidad, elaborar indicadores de gestión y de los supervisados para cumplir con los programas de producción y coordinar actividades con otras áreas."},{"consecutivo":6,"texto":"Vigilar y coordinar el cumplimiento en la programación de la producción y solicitar materiales e insumos."},{"consecutivo":7,"texto":"Organizar y planificar el trabajo diario siguiendo planes preestablecidos, teniendo en cuenta aspectos económicos, medioambientales y de personal."},{"consecutivo":8,"texto":"Preparar estimaciones de costos, registros y reportes de gastos, de producción y funcionamiento de la planta, de acuerdo con su área de trabajo."},{"consecutivo":9,"texto":"Generar alertas y proponer las acciones de mejora a los superiores cuando se identifique la falta de personal, de insumos o alguna otra variable que afecte los procesos o se encuentre fuera de control."},{"consecutivo":10,"texto":"Prestar apoyo a las actividades programadas por el superior inmediato."},{"consecutivo":11,"texto":"Dar inducción e instrucción al personal sobre sus deberes en el trabajo, normas de seguridad industrial y políticas de la empresa."},{"consecutivo":12,"texto":"Hacer recomendaciones sobre incentivos y ascensos de personal."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31221.001","nombre":"Coordinador de personal de empaque de productos agrícolas / Coordinadora de personal de empaque de productos agrícolas"},{"codigo":"31221.002","nombre":"Inspector auxiliar de planta de beneficio animal / Inspectora auxiliar de planta de beneficio animal"},{"codigo":"31221.003","nombre":"Inspector de calidad de leche / Inspectora de calidad de leche"},{"codigo":"31221.004","nombre":"Inspector de calidad productos pecuario / Inspectora de calidad productos pecuario"},{"codigo":"31221.005","nombre":"Inspector de planta de beneficio animal / Inspectora de planta de beneficio animal"},{"codigo":"31221.006","nombre":"Inspector en planta y beneficio / Inspectora en planta y beneficio"},{"codigo":