  ('rol_cuoc', 'Supervisores de fabricación y procesamiento de productos de plástico y caucho / Supervisoras de fabricación y procesamiento de productos de plástico y caucho', '31222', 'Industria química', 3, false, '{"codigo":"31222","nombre":"Supervisores de fabricación y procesamiento de productos de plástico y caucho / Supervisoras de fabricación y procesamiento de productos de plástico y caucho","descripcion":"Supervisan y coordinan las actividades de los trabajadores que: operan máquinas de procesamiento, fabricación, ensamblaje e inspección de productos de plástico o caucho y otros trabajadores de industrias manufactureras. Se pueden desempeñar en compañías manufactureras de productos de plástico y caucho, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"312","nombre":"Supervisores en la minería, la industria manufacturera y la construcción"},"grupo_primario":{"codigo":"3122","nombre":"Supervisores de industrias manufactureras"}},"funciones":[{"consecutivo":1,"texto":"Supervisar, programar y coordinar las actividades de los técnicos en control de procesos, operadores de máquinas, procesadoras, ensambladoras, y otros trabajadores de industrias manufactureras que dan acabado e inspeccionan productos y partes de plástico y caucho."},{"consecutivo":2,"texto":"Organizar y programar el trabajo diario y solicitar materiales e insumos, de acuerdo con planes preestablecidos en aspectos económicos, medioambientales y de personal."},{"consecutivo":3,"texto":"Realizar seguimiento a los programas y los procesos de producción para su cumplimiento y coordinar actividades con otras áreas de acuerdo con los métodos establecidos."},{"consecutivo":4,"texto":"Velar por el cumplimiento de las políticas, los reglamentos y las normas para los trabajadores, de acuerdo con el sistema de gestión de la organización, entre ellos el de seguridad y salud en el trabajo, ambiental, inocuidad, calidad, entre otros."},{"consecutivo":5,"texto":"Preparar y elaborar informes, registros y reportes de producción, inspección de productos, seguimiento de indicadores, entre otros."},{"consecutivo":6,"texto":"Resolver problemas de trabajo y recomendar medidas para mejorar la productividad de los procesos y la calidad del producto."},{"consecutivo":7,"texto":"Supervisar la inspección de los productos acabados para identificar defectos de fabricación, visualmente o utilizando instrumentos para garantizar especificaciones y estándares de calidad."},{"consecutivo":8,"texto":"Dar inducción y preparar al personal sobre sus deberes en el trabajo, las normas de seguridad industrial y las políticas de la empresa."},{"consecutivo":9,"texto":"Identificar y hacer recomendaciones sobre incentivos, ascensos y la falta de personal o de insumos."},{"consecutivo":10,"texto":"Promover la preservación, la conservación, el mantenimiento y el buen uso de las instalaciones, las máquinas y las herramientas asignadas a los puestos de trabajo y demás propiedades de la organización."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31222.002","nombre":"Supervisor de ensamble de productos de caucho / Supervisora de ensamble de productos de caucho"},{"codigo":"31222.003","nombre":"Supervisor de ensamble de productos de plástico / Supervisora de ensamble de productos de plástico"},{"codigo":"31222.004","nombre":"Supervisor de extrusión para fabricación de productos de caucho / Supervisora de extrusión para fabricación de productos de caucho"},{"codigo":"31222.005","nombre":"Supervisor de extrusión para fabricación de productos de plástico / Supervisora de extrusión para fabricación de productos de plástico"},{"codigo":"31222.007","nombre":"Supervisor de fabricación de neumáticos / Supervisora de fabricación de neumáticos"},{"codigo"