  ('rol_cuoc', 'Supervisores de impresión y ocupaciones relacionadas / Supervisoras de impresión y ocupaciones relacionadas', '31225', 'Literatura y artes gráficas', 3, false, '{"codigo":"31225","nombre":"Supervisores de impresión y ocupaciones relacionadas / Supervisoras de impresión y ocupaciones relacionadas","descripcion":"Supervisan y coordinan las actividades de los técnicos en control de procesos, operadores de máquinas, ensambladores, operadores de pre-prensa, impresión y acabado de producto. Se pueden desempeñar en compañías especializadas en impresión comercial, acabados, reproducción a color, compañías de publicidad e impresión, periódicos y revistas, en empresas públicas o privadas que cuenten con departamento de impresión, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"312","nombre":"Supervisores en la minería, la industria manufacturera y la construcción"},"grupo_primario":{"codigo":"3122","nombre":"Supervisores de industrias manufactureras"}},"funciones":[{"consecutivo":1,"texto":"Planificar, coordinar y supervisar las actividades de trabajadores de industrias manufactureras de acuerdo con los planes de producción."},{"consecutivo":2,"texto":"Inspeccionar, realizar y autorizar las pruebas o muestras para garantizar la calidad del trabajo del producto impreso y el cumplimiento de las especificaciones del cliente."},{"consecutivo":3,"texto":"Establecer métodos y operar procesos de producción según programas requeridos teniendo en cuenta actividades laborales con otros departamentos."},{"consecutivo":4,"texto":"Realizar y controlar el proceso de impresión según especificaciones del cliente y la calidad del producto."},{"consecutivo":5,"texto":"Programar y solicitar materiales e insumos de acuerdo con el plan de producción."},{"consecutivo":6,"texto":"Preparar estimaciones de costos e informes de gastos y producción de acuerdo con especificaciones."},{"consecutivo":7,"texto":"Capacitar al personal sobre sus deberes en el trabajo, normas de seguridad industrial y políticas de la empresa."},{"consecutivo":8,"texto":"Proporcionar asesoría técnica y de personal para mejorar la productividad y la calidad del trabajo."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31225.001","nombre":"Director de producción de impresión / Directora de producción de impresión"},{"codigo":"31225.002","nombre":"Gestor de calidad de impresión / Gestora de calidad de impresión"},{"codigo":"31225.003","nombre":"Jefe operativo en la industria gráfica / Jefa operativa en la industria gráfica"},{"codigo":"31225.004","nombre":"Líder de transformación e impresión / Lideresa de transformación e impresión"},{"codigo":"31225.005","nombre":"Supervisor de acabado de impresión / Supervisora de acabado de impresión"},{"codigo":"31225.006","nombre":"Supervisor de artes gráficas / Supervisora de artes gráficas"},{"codigo":"31225.007","nombre":"Supervisor de encuadernación / Supervisora de encuadernación"},{"codigo":"31225.008","nombre":"Supervisor de impresión / Supervisora de impresión"},{"codigo":"31225.009","nombre":"Supervisor de industria gráfica / Supervisora de industria gráfica"},{"codigo":"31225.010","nombre":"Supervisor de preimpresión / Supervisora de preimpresión"},{"codigo":"31225.011","nombre":"Supervisor de taller de composición de impresión / Supervisora de taller de composición de impresión"},{"codigo":"31225.012","nombre":"Supervisor de planta en la industria gráfica / Supervisora de planta en la industria gráfica"},{"codigo":"31225.013","nombre":"Supervisor de producción de impresos / Supervisora de producción de impresos"},{"codigo":"31225.014","nombre":"Jefe en producción gráfica / Jefa en producción gráfica"},{"codigo":"31225.015","nombre":"Supervisor de acabado de industria