  ('rol_cuoc', 'Supervisores de fabricación y procesamiento de productos textiles, cuero y piel / Supervisoras de fabricación y procesamiento de productos textiles, cuero y piel', '31227', 'Textil, cuero, confección y diseño de modas', 3, false, '{"codigo":"31227","nombre":"Supervisores de fabricación y procesamiento de productos textiles, cuero y piel / Supervisoras de fabricación y procesamiento de productos textiles, cuero y piel","descripcion":"Supervisan y coordinan las actividades de los operadores de máquinas y trabajadores relacionados con la fabricación y la inspección de productos textiles, curtiembre y fabricación de productos de tela, piel y cuero. Se pueden desempeñar en empresas de confección, curtiembres, fábricas de calzado y otros productos, tintorerías y marroquinerías, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"312","nombre":"Supervisores en la minería, la industria manufacturera y la construcción"},"grupo_primario":{"codigo":"3122","nombre":"Supervisores de industrias manufactureras"}},"funciones":[{"consecutivo":1,"texto":"Supervisar, programar y coordinar las actividades de los trabajadores de fabricación y procesamiento de productos textiles, cuero y piel de acuerdo con planes de producción."},{"consecutivo":2,"texto":"Supervisar el proceso de fabricación y procesamiento de productos textiles, cuero y piel de acuerdo con especificaciones técnicas y de calidad."},{"consecutivo":3,"texto":"Establecer métodos y proporcionar asesoría técnica y de personal para mejorar la productividad y calidad del trabajo."},{"consecutivo":4,"texto":"Preparar estimaciones de costos e informes de gastos y producción de acuerdo con especificaciones."},{"consecutivo":5,"texto":"Capacitar al personal sobre sus deberes en el trabajo, normas de seguridad industrial y políticas de la empresa."},{"consecutivo":6,"texto":"Programar y solicitar materiales e insumos de acuerdo con plan de producción."},{"consecutivo":7,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31227.001","nombre":"Capataz de curtiembre"},{"codigo":"31227.002","nombre":"Jefe de corte y confección / Jefa de corte y confección"},{"codigo":"31227.003","nombre":"Jefe de taller de confección / Jefa de taller de confección"},{"codigo":"31227.004","nombre":"Supervisor acabador del cuero / Supervisora acabadora del cuero"},{"codigo":"31227.005","nombre":"Supervisor de acabado de textiles / Supervisora de acabado de textiles"},{"codigo":"31227.006","nombre":"Supervisor de confección de prendas de vestir / Supervisora de confección de prendas de vestir"},{"codigo":"31227.007","nombre":"Supervisor de corte de productos de tela piel y cuero / Supervisora de corte de productos de tela piel y cuero"},{"codigo":"31227.008","nombre":"Supervisor de corte de tela, piel y cuero / Supervisora de corte de tela, piel y cuero"},{"codigo":"31227.009","nombre":"Supervisor de corte y confección / Supervisora de corte y confección"},{"codigo":"31227.010","nombre":"Supervisor de curtiembre / Supervisora de curtiembre"},{"codigo":"31227.011","nombre":"Supervisor de ensamble de productos textiles / Supervisora de ensamble de productos textiles"},{"codigo":"31227.012","nombre":"Supervisor de fabricación de calzado / Supervisora de fabricación de calzado"},{"codigo":"31227.013","nombre":"Supervisor de fabricación de prendas de vestir / Supervisora de fabricación de prendas de vestir"},{"codigo":"31227.014","nombre":"Supervisor de fabricación de productos de cuero / Supervisora de fabricación de productos de cuero"},{"codigo":"31227.015","nombre":"Supervisor de fabricación de productos de tela, cuero y piel / Supervisora de fabricación de productos de tela, cuero y piel"},{"codigo":"31227.016","nombre":"Supervisor de fabricación de productos textile