  ('rol_cuoc', 'Supervisores de la construcción, maestros generales de obra, instalación y reparación / Supervisoras de la construcción, maestros generales de obra, instalación y reparación', '31231', 'Construcción e infraestructura', 3, false, '{"codigo":"31231","nombre":"Supervisores de la construcción, maestros generales de obra, instalación y reparación / Supervisoras de la construcción, maestros generales de obra, instalación y reparación","descripcion":"Coordinan, supervisan y programan las actividades de los trabajadores que participan en obras de construcción de edificios, estructuras, infraestructuras, instalación de tuberías, plomería, sistemas de aspersión, al igual que redes y equipos a gas. Se pueden desempeñar en compañías de construcción o trabajar de forma independiente, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"312","nombre":"Supervisores en la minería, la industria manufacturera y la construcción"},"grupo_primario":{"codigo":"3123","nombre":"Supervisores de la construcción, maestros generales de obra, instalación y reparación"}},"funciones":[{"consecutivo":1,"texto":"Coordinar, supervisar y llevar control del avance de las obras de infraestructuras viales y edificaciones de acuerdo con planos, especificaciones técnicas y normatividad."},{"consecutivo":2,"texto":"Supervisar, coordinar y programar el recurso humano y los materiales requeridos para la construcción, instalación y reparación en edificaciones."},{"consecutivo":3,"texto":"Inspeccionar los sitios de construcción o remodelación de edificaciones y otras estructuras para detectar y reportar defectos estructurales, riesgos de incendio y amenazas de seguridad."},{"consecutivo":4,"texto":"Inspeccionar la construcción de las redes internas de la edificación de acuerdo con planos y especificaciones de diseño de redes hidráulicas, sanitarias, de protección contra incendio, gas , entre otras que hayan sido contempladas para el proyecto."},{"consecutivo":5,"texto":"Leer e interpretar planos y especificaciones de diseño de los componentes del proyecto a fin de determinar los requerimientos técnicos."},{"consecutivo":6,"texto":"Supervisar la construcción de elementos no estructurales de acuerdo con especificaciones de diseño, requerimientos técnicos y normativa asociada."},{"consecutivo":7,"texto":"Controlar la ejecución de acabados de acuerdo con los planos, especificaciones y del proceso constructivo."},{"consecutivo":8,"texto":"Supervisar la reparación o restauración de obras de edificación y de infraestructura de acuerdo con especificaciones, normativa asociada y requerimientos del proyecto."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31231.001","nombre":"Administrador de obra en construcción / Administradora de obra en construcción"},{"codigo":"31231.002","nombre":"Capataz de construcción"},{"codigo":"31231.003","nombre":"Capataz de demolición"},{"codigo":"31231.004","nombre":"Capataz de perforación y voladura construcción"},{"codigo":"31231.005","nombre":"Capataz de restauración en construcción"},{"codigo":"31231.006","nombre":"Coordinador de campo de construcción / Coordinadora de campo de construcción"},{"codigo":"31231.007","nombre":"Coordinador de edificio en construcción / Coordinadora de edificio en construcción"},{"codigo":"31231.008","nombre":"Coordinador de emplazamiento de la obra / Coordinadora de emplazamiento de la obra"},{"codigo":"31231.009","nombre":"Coordinador de obra en construcción / Coordinadora de obra en construcción"},{"codigo":"31231.010","nombre":"Gestor de obra de gas / Gestora de obra de gas"},{"codigo":"31231.011","nombre":"Inspector de construcción / Inspectora de construcción"},{"codigo":"31231.012","nombre":"Inspector de construcción de vías / Inspectora d