  ('rol_cuoc', 'Inspectores de sistemas e instalaciones de gas / Inspectoras de sistemas e instalaciones de gas', '31232', 'Construcción e infraestructura', 3, false, '{"codigo":"31232","nombre":"Inspectores de sistemas e instalaciones de gas / Inspectoras de sistemas e instalaciones de gas","descripcion":"Inspeccionan y verifican el cumplimiento de la normatividad, operatividad y reglamentación de componentes de instalaciones, artefactos a gas, equipos de medición y regulación, sistemas de ventilación y evacuación, instalaciones y sistemas de almacenamiento y suministro de gases combustibles y medicinales, en la ejecución de los montajes de tanques, unidades de vaporización, unidades de aire propanado y estación de bombeo, desde la estación de almacenamiento hasta el sistema de regulación. Se pueden desempeñar en empresas distribuidoras de gas, organismos de certificación e inspección acreditados, firmas contratistas independientes, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"312","nombre":"Supervisores en la minería, la industria manufacturera y la construcción"},"grupo_primario":{"codigo":"3123","nombre":"Supervisores de la construcción, maestros generales de obra, instalación y reparación"}},"funciones":[{"consecutivo":1,"texto":"Verificar y evaluar el cumplimiento normativo y reglamentario en el sistema de suministro y tanques de gas."},{"consecutivo":2,"texto":"Verificar y evaluar las condiciones técnicas y de seguridad en instalaciones de gas residenciales, comerciales, industriales o especiales."},{"consecutivo":3,"texto":"Inspeccionar, evaluar y certificar las instalaciones asistidas, los sistemas de protección y ventilación en la infraestructura de las instalaciones para suministro de gas."},{"consecutivo":4,"texto":"Verificar e inspeccionar instalaciones para suministro de gas, artefactos a gas, equipos de medición y regulación, sistemas de ventilación y evacuación."},{"consecutivo":5,"texto":"Identificar y clasificar hallazgos y defectos encontrados en las instalaciones para suministro de gas y equipos a gas."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31232.001","nombre":"Inspector de instalaciones de gas / Inspectora de instalaciones de gas"},{"codigo":"31232.002","nombre":"Inspector de instalaciones de gas licuado del petróleo / Inspectora de instalaciones de gas licuado del petróleo"},{"codigo":"31232.003","nombre":"Inspector de instalaciones industriales de gas / Inspectora de instalaciones industriales de gas"},{"codigo":"31232.004","nombre":"Inspector de instalaciones para el suministro de gas / Inspectora de instalaciones para el suministro de gas"},{"codigo":"31232.005","nombre":"Inspector de instalaciones residenciales y comerciales de gas / Inspectora de instalaciones residenciales y comerciales de gas"},{"codigo":"31232.006","nombre":"Inspector de redes de gas / Inspectora de redes de gas"},{"codigo":"31232.007","nombre":"Inspector de sistemas e instalaciones de gas / Inspectora de sistemas e instalaciones de gas"},{"codigo":"31232.008","nombre":"Inspector del sistema de suministro de gas licuado del petróleo GLP / Inspectora del sistema de suministro de gas licuado del petróleo GLP"},{"codigo":"31232.009","nombre":"Inspector integral de instalaciones para suministros de gas / Inspectora integral de instalaciones para suministros de gas"},{"codigo":"31232.010","nombre":"Inspector técnico de cilindros de gas / Inspectora técnica de cilindros de gas"},{"codigo":"31232.011","nombre":"Inspector técnico de gas licuado del petróleo / Inspectora técnica de gas licuado del petróleo"},{"codigo":"31232.012","nombre":"Localizador de escapes de gas (planta de gas) / Localizadora de escapes de gas (planta de gas)"},{"codigo":"31232.013","nombre":"Revisor de instalaciones de gas licuado del petróleo / Revisora de instalaciones de gas licuado del petróleo"},{"codigo":"31232.014","nombre":"Revisor de instalaciones de gas natural / Revisora de instalaciones de gas natural"},{"codigo":"31232.015","nombre":"Supervisor de personal de instalación de sistemas de gas / Supervisora de personal de instalación de sistemas de gas"},{"codigo":"31232.016","nombre":"Supervisor de personal de instalación de sistemas de tuberías de gas / Supervisora de personal de instalación de sistemas de tuberías de gas"},{"codigo":"31232.017","nombre":"Técnico en inspecciones de redes de gas / Técnica en inspecciones de redes de gas"}],"conocimientos":[{"id":"15","nombre":"Física"},{"id":"10","nombre":"Ingeniería y tecnología"},{"id":"35","nombre":"Interpretación de planos"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"38","nombre":"Mantenimiento"},{"id":"14","nombre":"Matemáticas"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"11","nombre":"Trabajo en equipo"},{"id":"23","nombre":"Vigilancia de las operaciones"}],"ocupaciones_afines":[{"codigo":"31231","nombre":"Supervisores de la construcción, maestros generales de obra, instalación y reparación / Supervisoras de la construcción, maestros generales de obra, instalación y reparación"},{"codigo":"71263","nombre":"Instaladores de redes y equipos a gas / Instaladoras de redes y equipos a gas"}],"area_principal":{"sigla":"COIF","nombre":"Construcción e infraestructura"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"3123*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"7213*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8213*","cno_obs":"Denominaciones parciales"