  ('rol_cuoc', 'Operadores de plantas de generación y distribución de energía / Operadoras de plantas de generación y distribución de energía', '31310', 'Producción de energía y electricidad', 2, false, '{"codigo":"31310","nombre":"Operadores de plantas de generación y distribución de energía / Operadoras de plantas de generación y distribución de energía","descripcion":"Manejan, operan y mantienen los tableros de control y los equipos técnicos relacionados que se utilizan en los centros de control eléctrico que rigen la producción y la distribución de energía eléctrica a través de redes de transmisión. El equipo operador incluye reactores, turbinas, generadores y otros equipos auxiliares empleados en las estaciones generadoras de energía eléctrica. Se pueden desempeñar en empresas de energía eléctrica, por grandes instalaciones industriales, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"313","nombre":"Técnicos en control de procesos"},"grupo_primario":{"codigo":"3131","nombre":"Operadores de plantas de generación y distribución de energía"}},"funciones":[{"consecutivo":1,"texto":"Operar y controlar los sistemas y los equipos de generación de energía como: calderas, turbinas, generadores, condensadores, reactores y equipo auxiliar de centrales hidroeléctricas, térmicas de carbón, de petróleo, gas natural y centrales de energía nuclear para efectos de la producción y distribución de energía eléctrica."},{"consecutivo":2,"texto":"Monitorear e inspeccionar equipos de generación y distribución de energía para detectar problemas de operación y efectuar mantenimiento preventivo o correctivo."},{"consecutivo":3,"texto":"Accionar, controlar y vigilar las instalaciones de plantas de generación y distribución de energía y coordinar con otros operadores de sistemas las cargas de transmisión, frecuencia y voltajes de línea."},{"consecutivo":4,"texto":"Realizar mantenimiento de equipos en plantas de generación y distribución de energía, y proveer información para apoyar planes que garanticen el cumplimiento de los objetivos de mantenimiento y producción."},{"consecutivo":5,"texto":"Establecer métodos y proporcionar asesoría técnica y de personal para mejorar la productividad y la calidad del trabajo."},{"consecutivo":6,"texto":"Identificar, investigar, documentar e informar sobre incidentes en la operación y el funcionamiento de los equipos en plantas de generación y distribución de energía, así como ambientales y de seguridad industrial."},{"consecutivo":7,"texto":"Programar y solicitar materiales e insumos de acuerdo con plan de producción."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31310.001","nombre":"Despachador de carga eléctrica de estación central / Despachadora de carga eléctrica de estación central"},{"codigo":"31310.002","nombre":"Despachador de estación de generación / Despachadora de estación de generación"},{"codigo":"31310.003","nombre":"Inspector de sistemas e instalaciones térmicas / Inspectora de sistemas e instalaciones térmicas"},{"codigo":"31310.004","nombre":"Operador de central de estación de energía eléctrica / Operadora de central de estación de energía eléctrica"},{"codigo":"31310.005","nombre":"Operador de central de energía eléctrica / Operadora de central de energía eléctrica"},{"codigo":"31310.006","nombre":"Operador de control de distribución de energía / Operadora de control de distribución de energía"},{"codigo":"31310.007","nombre":"Operador de control de distribución energía eléctrica / Operadora de control de distribución energía eléctrica"},{"codigo":"31310.008","nombre":"Operador de controlador central de planta generadora de electricidad / Operadora de controlador central de planta generadora de electricidad"},{"codigo":"31310.009","n