  ('rol_cuoc', 'Controladores de instalaciones de procesamiento de productos químicos / Controladoras de instalaciones de procesamiento de productos químicos', '31330', 'Industria química', 3, false, '{"codigo":"31330","nombre":"Controladores de instalaciones de procesamiento de productos químicos / Controladoras de instalaciones de procesamiento de productos químicos","descripcion":"Operan y controlan instalaciones y máquinas multifuncionales de control de procesos conexas; ajustan y mantienen las unidades y equipos de procesamiento utilizados para destilar, filtrar, separar, calentar o refinar sustancias químicas. Se pueden desempeñar en industrias químicas, o en departamentos de procesamiento químico de otras industrias, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"313","nombre":"Técnicos en control de procesos"},"grupo_primario":{"codigo":"3133","nombre":"Controladores de instalaciones de procesamiento de productos químicos"}},"funciones":[{"consecutivo":1,"texto":"Operar panel de control computarizado o electrónico desde una sala de control central para monitorear y optimizar los procesos físicos y químicos de varias unidades de procesamiento."},{"consecutivo":2,"texto":"Monitorear medidores, equipos e instrumentos de control de procesamiento de productos químicos para verificar que el proceso se desarrolla según las condiciones establecidas y hacer los ajustes necesarios."},{"consecutivo":3,"texto":"Controlar el arranque, la parada y el cierre del proceso de elaboración de productos químicos de acuerdo con procedimientos técnicos."},{"consecutivo":4,"texto":"Inspeccionar el funcionamiento de los equipos de planta, para detectar averías o fallas y organizar su mantenimiento para garantizar su operación."},{"consecutivo":5,"texto":"Registrar y controlar la información de producción de instalaciones de procesamiento de productos químicos."},{"consecutivo":6,"texto":"Recolectar muestras, registrar datos y realizar pruebas químicas a productos de acuerdo con procedimientos técnicos."},{"consecutivo":7,"texto":"Apoyar en el desarrollo de los procedimientos operativos para un normal funcionamiento del arranque o el cierre de unidades de procesamiento de productos químicos."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31330.001","nombre":"Compresorista"},{"codigo":"31330.002","nombre":"Destilador de productos químicos excepto petróleo / Destiladora de productos químicos excepto petróleo"},{"codigo":"31330.003","nombre":"Operador de alambique procesos químicos (excepto petróleo y gas natural) / Operadora de alambique procesos químicos (excepto petróleo y gas natural)"},{"codigo":"31330.004","nombre":"Operador de autoclave de procesos químicos (excepto petróleo y gas natural) / Operadora de autoclave de procesos químicos (excepto petróleo y gas natural)"},{"codigo":"31330.005","nombre":"Operador de compresor de aire / Operadora de compresor de aire"},{"codigo":"31330.006","nombre":"Operador de compresor de gas / Operadora de compresor de gas"},{"codigo":"31330.007","nombre":"Operador de congelador / Operadora de congelador"},{"codigo":"31330.008","nombre":"Operador de control central de producción de cemento / Operadora de control central de producción de cemento"},{"codigo":"31330.009","nombre":"Operador de equipo de destilación y de reacción química / Operadora de equipo de destilación y de reacción química"},{"codigo":"31330.010","nombre":"Operador de equipo de filtro prensa sustancias químicas / Operadora de equipo de filtro prensa sustancias químicas"},{"codigo":"31330.011","nombre":"Operador de equipo de ventilación / Operadora de equipo de ventilación"},{"codigo":"31330.012","nombre":"Operador de filtrado químico y equipos de separación / Operadora de filtra