  ('rol_cuoc', 'Inspectores de oleoductos y gasoductos / Inspectoras de oleoductos y gasoductos', '31342', 'Exploración y extracción de minas, canteras, petróleo y gas', 3, false, '{"codigo":"31342","nombre":"Inspectores de oleoductos y gasoductos / Inspectoras de oleoductos y gasoductos","descripcion":"Supervisan, inspeccionan y verifican las instalaciones, ajustan y mantienen las unidades y los equipos de procesamiento utilizados para refinar, destilar y tratar los productos y los subproductos derivados del petróleo o gas natural. Llevan registro y reportan información sobre códigos, normas y estándares relacionados con tubería para oleoductos y gasoductos. Se pueden desempeñar en oleoductos y gasoductos, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"313","nombre":"Técnicos en control de procesos"},"grupo_primario":{"codigo":"3134","nombre":"Operadores e inspectores de instalaciones de refinación de petróleo y gas natural"}},"funciones":[{"consecutivo":1,"texto":"Interpretar y reportar información técnica relacionada con: códigos, especificaciones, documentos contractuales y planos utilizados en la construcción de oleoductos y gasoductos."},{"consecutivo":2,"texto":"Verificar el alistamiento de equipo y maquinaria requerido en los procedimientos para la construcción de oleoductos y gasoductos."},{"consecutivo":3,"texto":"Analizar muestras de productos, realizar pruebas, mantener registrados los datos de producción."},{"consecutivo":4,"texto":"Realizar inspecciones en tuberías para la construcción de oleoductos y gasoductos, asegurando condiciones de calidad y seguridad industrial."},{"consecutivo":5,"texto":"Verificar condiciones de transporte, acopio y tendido de la tubería para poliductos y gasoductos."},{"consecutivo":6,"texto":"Verificar condiciones de realización de ensayos sobre tubería para poliductos y gasoductos."},{"consecutivo":7,"texto":"Inspeccionar productos terminados resultado del trabajo realizado sobre tuberías para la conducción de petróleo, sus derivados y gas."},{"consecutivo":8,"texto":"Asegurar las condiciones de seguridad industrial y medio ambiente en la construcción de las tuberías para poliductos y gasoductos."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31342.001","nombre":"Inspector de construcción de oleoductos y gasoductos / Inspectora de construcción de oleoductos y gasoductos"},{"codigo":"31342.002","nombre":"Inspector de instalaciones de gas combustible para uso industrial / Inspectora de instalaciones de gas combustible para uso industrial"},{"codigo":"31342.003","nombre":"Inspector de obras y servicios de oleoductos y gasoductos / Inspectora de obras y servicios de oleoductos y gasoductos"}],"conocimientos":[{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"14","nombre":"Matemáticas"},{"id":"13","nombre":"Mecánica y metalistería"},{"id":"7","nombre":"Producción y procesamiento"},{"id":"27","nombre":"Seguridad pública"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"1","nombre":"Comprensión de lectura"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"23","nombre":"Vigilancia de las operaciones"}],"ocupaciones_afines":[{"codigo":"31321","nombre":"Operadores de plantas de tratamiento de agua / Operadoras de plantas de tratamiento de agua"},{"codigo":"31212","nombre":"Supervisores de perforación y servicio a pozos de petróleo y gas / Supervisoras de perforación y servicio a pozos de petróleo y gas"},{"codigo":"31226","nombre":"Supervisores de fabricación y tratamiento de productos mecánicos, metálicos y minerales / Supervisoras de fabricación y tratamiento de productos mecánicos, metálicos y minerales"},{"codigo":"72120",