  ('rol_cuoc', 'Controladores de procesos de producción y tratamiento de metales / Controladoras de procesos de producción y tratamiento de metales', '31350', 'Fabricación, transformación de materiales, instalación, mantenimiento y reparación', 3, false, '{"codigo":"31350","nombre":"Controladores de procesos de producción y tratamiento de metales / Controladoras de procesos de producción y tratamiento de metales","descripcion":"Manejan y supervisan máquinas y equipos multifuncionales de control de procesos que se utilizan para controlar el funcionamiento de los hornos de conversión y refinado, los trenes de laminación, las instalaciones de tratamiento térmico de los metales y las instalaciones de extrusión de metal. Se pueden desempeñar en plantas procesadoras de metal como refinerías de cobre, plomo y zinc, acerías, plantas de aluminio, refinerías de metales preciosos, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"313","nombre":"Técnicos en control de procesos"},"grupo_primario":{"codigo":"3135","nombre":"Controladores de procesos de producción y tratamiento de metales"}},"funciones":[{"consecutivo":1,"texto":"Coordinar y supervisar el funcionamiento del procesamiento y producción de metales, utilizando paneles, terminales de computador y otros medios de control, para verificar que el proceso se desarrolla según las condiciones establecidas y hacer los ajustes necesarios."},{"consecutivo":2,"texto":"Operar maquinaria de función simple y multifuncional para el procesamiento de metales."},{"consecutivo":3,"texto":"Coordinar, supervisar y capacitar al personal del proceso de producción y tratamiento de metales de acuerdo con lineamientos de la organización."},{"consecutivo":4,"texto":"Disponer y ajustar la maquinaria utilizada en las operaciones de procesamiento de metales."},{"consecutivo":5,"texto":"Realizar informes del proceso de producción y tratamiento de metales según requerimientos, e informar oportunamente al supervisor cualquier variación anómala en el proceso."},{"consecutivo":6,"texto":"Poner en marcha y parar el sistema de producción en caso de emergencia o cuando se requiera por el horario de trabajo."},{"consecutivo":7,"texto":"Probar la resistencia, la durabilidad de los productos y la conformidad con las especificaciones."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31350.001","nombre":"Moldeador de control central / Moldeadora de control central"},{"codigo":"31350.002","nombre":"Operador de control central de procesos de tratamiento de metales / Operadora de control central de procesos de tratamiento de metales"},{"codigo":"31350.003","nombre":"Operador de alto horno / Operadora de alto horno"},{"codigo":"31350.004","nombre":"Operador de control central de laminación de metales / Operadora de control central de laminación de metales"},{"codigo":"31350.005","nombre":"Operador de control central fundición de metales / Operadora de control central fundición de metales"},{"codigo":"31350.006","nombre":"Operador de control central tratamiento de metales / Operadora de control central tratamiento de metales"},{"codigo":"31350.007","nombre":"Operador de control de laminación / Operadora de control de laminación"},{"codigo":"31350.008","nombre":"Operador de control de tren de laminación / Operadora de control de tren de laminación"},{"codigo":"31350.009","nombre":"Operador de convertidor de acero / Operadora de convertidor de acero"},{"codigo":"31350.010","nombre":"Operador de convertidor de acero martin siemens / Operadora de convertidor de acero martin siemens"},{"codigo":"31350.011","nombre":"Operador de convertidor de acero procedimiento bessemer / Operadora de convertidor de acero procedimiento bessemer"},{"codigo":"31350.012","nombre":"Operador de 