  ('rol_cuoc', 'Promotores de servicios agrícolas y relacionados / Promotoras de servicios agrícolas y relacionados', '31426', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 3, false, '{"codigo":"31426","nombre":"Promotores de servicios agrícolas y relacionados / Promotoras de servicios agrícolas y relacionados","descripcion":"Suministran asesoría y asistencia sobre diversos aspectos de la administración de fincas, cultivos, fertilización, cosecha, postcosecha, erosión y composición del suelo, prevención de enfermedades, nutrición, rotación de cultivos y venta de cosechas. Se pueden desempeñar en fincas, entidades del gobierno para asistir a la comunidad agropecuaria, empresas agrícolas, de forma independiente, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"314","nombre":"Técnicos y profesionales de nivel medio en ciencias biológicas y afines"},"grupo_primario":{"codigo":"3142","nombre":"Técnicos, supervisores e inspectores agropecuarios"}},"funciones":[{"consecutivo":1,"texto":"Dirigir investigaciones, analizar información agrícola y preparar reportes."},{"consecutivo":2,"texto":"Asesorar y prestar servicio de consultoría sobre cultivos, fertilización, adecuación de tierras, recolección de cosechas, cuidado de especies menores, prevención de enfermedades, manejo de fincas, finanzas, mercadeo y otros aspectos agrícolas."},{"consecutivo":3,"texto":"Investigar sobre las características, posibilidades de utilización y productividad de los suelos y aplicar los resultados al perfeccionamiento de las prácticas y las faenas agrícolas y silvícolas."},{"consecutivo":4,"texto":"Preparar y dirigir sesiones y lecturas para información y asesoría a los finqueros y otros grupos empresariales."},{"consecutivo":5,"texto":"Promover reuniones con investigadores, educadores, administradores, negociantes y agentes del gobierno para discutir aspectos relacionados con la finca y la agricultura."},{"consecutivo":6,"texto":"Suministrar servicios de recolección de cosechas, irrigación, arado y fumigación."},{"consecutivo":7,"texto":"Negociar los servicios a proveer con agricultores y propietarios de explotaciones agrícolas."},{"consecutivo":8,"texto":"Administrar y operar los negocios que ofrecen servicios a la agricultura y ganadería, y participar en la provisión del servicio y en la operación."},{"consecutivo":9,"texto":"Elaborar proyectos para la prestación de servicios agrícolas como: recopilar datos y preparar estimaciones de cantidades y costos de materiales y mano de obra necesarios para su ejecución."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31426.001","nombre":"Promotor agrícola / Promotora agrícola"},{"codigo":"31426.002","nombre":"Promotor de servicios agrícolas / Promotora de servicios agrícolas"},{"codigo":"31426.003","nombre":"Promotor de servicios de fumigación / Promotora de servicios de fumigación"},{"codigo":"31426.004","nombre":"Promotor de servicios de inseminación artificial / Promotora de servicios de inseminación artificial"},{"codigo":"31426.005","nombre":"Promotor de servicios de preparación suelos / Promotora de servicios de preparación suelos"},{"codigo":"31426.006","nombre":"Promotor de servicios de recolección cosechas / Promotora de servicios de recolección cosechas"},{"codigo":"31426.007","nombre":"Promotor de servicios de riego / Promotora de servicios de riego"},{"codigo":"31426.008","nombre":"Promotor rural / Promotora rural"},{"codigo":"31426.009","nombre":"Promotor de desarrollo rural / Promotora de desarrollo rural"},{"codigo":"31426.010","nombre":"Promotor agroecológico / Promotora agroecológica"}],"conocimientos":[{"id":"17","nombre":"Biología"},{"id":"22","nombre":"Educación y capacitación"},{"id":"1","nombre":"Gerencia y administración"},{"id":"6","nombre":"Gestión del talento humano y de personal"},{"id":"13","nombre":"Mecánica y metalistería"},{"id":"8","nombre":"Procesamiento de alimentos"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"23","nombre":"Vigilancia de las operaciones"}],"ocupaciones_afines":[{"codigo":"21310","nombre":"Biólogos, botánicos, zoólogos y afines / Biólogas, botánicas, zoólogas y afines"},{"codigo":"21321","nombre":"Agrónomos, agroecólogos, agrícolas, pecuarios y zootecnistas / Agrónomas, agroecólogas, agrícolas, pecuarias y zootecnistas"},{"codigo":"21430","nombre":"Ingenieros medioambientales / Ingenieras medioambientales"},{"codigo":"31424","nombre":"Supervisores de producción agrícola / Supervisoras de producción agrícola"},{"codigo":"32400","nombre":"Técnicos y asistentes veterinarios / Técnicas y asistentes veterinarias"},{"codigo":"61132","nombre":"Trabajadores agrícolas calificados de huertas, invernaderos, viveros y jardines / Trabajadoras agrícolas calificadas de huertas, invernaderos, viveros y jardines"},{"codigo":"61211","nombre":"Criadores de animales (excepto aves de corral) / Criadoras de animales (excepto aves de corral)"},{"codigo":"61221","nombre":"Avicultores / Avicultoras"},{"codigo":"61230","nombre":"Criadores y trabajadores calificados de la apicultura y la sericicultura / Criadoras y trabajadoras calificadas de la apicultura y la sericicultura"}],"area_principal":{"sigla":"AGVE","nombre":"Agropecuario, silvicultura, pesca, acuicultura y veterinaria"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"3142*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"2125*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":