  ('rol_cuoc', 'Oficiales maquinistas en navegación', '31510', 'Logística y transporte', 3, false, '{"codigo":"31510","nombre":"Oficiales maquinistas en navegación","descripcion":"Controlan equipos y aparatos mecánicos, eléctricos y electrónicos utilizados a bordo de buques y participan en su manejo, mantenimiento y reparación; llevan a cabo funciones de apoyo relacionadas en tierra; supervisan y coordinan las actividades del personal de la sala de máquinas. Se pueden desempeñar en compañías de transporte marítimo y las fuerzas militares, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"31","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LAS CIENCIAS Y LA INGENIERIA"},"subgrupo":{"codigo":"315","nombre":"Técnicos y controladores en navegación marítima y aeronáutica"},"grupo_primario":{"codigo":"3151","nombre":"Oficiales maquinistas en navegación"}},"funciones":[{"consecutivo":1,"texto":"Controlar y participar en la operación ,instalación, mantenimiento y reparación de máquinas y equipo de que se disponen a bordo de los buques para asegurar el cumplimiento de las especificaciones, las normas y los reglamentos."},{"consecutivo":2,"texto":"Inspeccionar y dirigir el mantenimiento y reparación de motores, maquinaria y equipo auxiliar."},{"consecutivo":3,"texto":"Supervisar y coordinar actividades del equipo de la sala de máquinas."},{"consecutivo":4,"texto":"Realizar órdenes de pedidos de combustible y otros suministros y mantener un registro de las operaciones."},{"consecutivo":5,"texto":"Aplicar conocimientos técnicos de los principios y las prácticas relativas a las operaciones y la navegación de los buques para identificar y resolver los problemas que surjan en el curso de su trabajo."},{"consecutivo":6,"texto":"Operar y controlar el funcionamiento de motores, máquinas y equipo auxiliar a bordo de embarcaciones."},{"consecutivo":7,"texto":"Monitorear y registrar el funcionamiento de motores, maquinaria y equipo auxiliar en la sala de máquinas."},{"consecutivo":8,"texto":"Llevar registros y preparar informes sobre el funcionamiento y las fallas de motores."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"31510.001","nombre":"Ingeniero de navegación / Ingeniera de navegación"},{"codigo":"31510.002","nombre":"Ingeniero jefe de buque / Ingeniera jefa de buque"},{"codigo":"31510.003","nombre":"Inspector de máquinas de barcos / Inspectora de máquinas de barcos"},{"codigo":"31510.004","nombre":"Jefe de equipos / Jefa de equipos (toolpusher)"},{"codigo":"31510.005","nombre":"Jefe de maquinas de barco / Jefa de maquinas de barco"},{"codigo":"31510.006","nombre":"Maquinista de marina"},{"codigo":"31510.007","nombre":"Oficial de máquinas"},{"codigo":"31510.008","nombre":"Oficial maquinista"},{"codigo":"31510.009","nombre":"Oficial maquinista de barco"},{"codigo":"31510.010","nombre":"Oficial maquinista de navegación"},{"codigo":"31510.011","nombre":"Primer oficial maquinista de barco"},{"codigo":"31510.012","nombre":"Segundo oficial maquinista de barco"},{"codigo":"31510.013","nombre":"Superintendente técnico de marina / Superintendenta técnica de marina"}],"conocimientos":[{"id":"20","nombre":"Geografía y territorio"},{"id":"1","nombre":"Gerencia y administración"},{"id":"14","nombre":"Matemáticas"},{"id":"13","nombre":"Mecánica y metalistería"},{"id":"27","nombre":"Seguridad pública"},{"id":"5","nombre":"Servicio al cliente"},{"id":"31","nombre":"Servicios de transporte"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"11","nombre":"Trabajo en equipo"},{"id":"23","nombre":"Vigilancia de las operaciones"}],"ocupaciones_afines":[{"codigo":"21441","nombre":"Ingenieros mecánicos / Ingenieras m