  ('rol_cuoc', 'Técnicos y tecnólogos en radioterapia / Técnicas y tecnólogas en radioterapia', '32112', 'Salud y bienestar', 3, false, '{"codigo":"32112","nombre":"Técnicos y tecnólogos en radioterapia / Técnicas y tecnólogas en radioterapia","descripcion":"Aplican procedimientos y protocolos para garantizar la eficacia de los tratamientos y la protección de los tejidos y los órganos adyacentes contra los efectos nocivos de la radiación durante las etapas de simulación, verifican los campos de radiación previstos, ejecutan labores técnicas de operación de equipos de radioterapia para administrar tratamientos de radiación, registran el tratamiento y producen imágenes diagnosticas para tratar lesiones y enfermedades. Se pueden desempeñar en hospitales, centros de tratamiento del cáncer, laboratorios clínicos y radiológicos, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"32","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LA SALUD"},"subgrupo":{"codigo":"321","nombre":"Técnicos médicos y farmacéuticos"},"grupo_primario":{"codigo":"3211","nombre":"Técnicos en aparatos de diagnóstico y tratamiento médico"}},"funciones":[{"consecutivo":1,"texto":"Producir, revisar y evaluar imágenes diagnósticas, radiografías, cintas de vídeo o información generada con fines diagnósticos por computadores para registrar los resultados de los procedimientos desarrollados de acuerdo con normativa de salud y procedimientos técnicos."},{"consecutivo":2,"texto":"Asistir y orientar a personas, pacientes y respondientes observando las condiciones y el estado de salud e informar al personal médico sobre señales anormales, de acuerdo con los protocolos y la normativa de salud."},{"consecutivo":3,"texto":"Medir y registrar dosis de radiación o radiofármacos por administrar a pacientes, de acuerdo con tratamiento, protocolo de radioterapia, tomografía computarizada y prescripción médica."},{"consecutivo":4,"texto":"Controlar infecciones, materiales radiactivos y almacenar radiofármacos siguiendo procedimientos de seguridad radiológica, protocolos y normativa de salud."},{"consecutivo":5,"texto":"Administrar teleterapia de acuerdo con parámetros clínicos y dosimétricos."},{"consecutivo":6,"texto":"Asistir la braquiterapia según la normativa de salud y de protección radiológica."},{"consecutivo":7,"texto":"Operar equipos biomédicos de acuerdo con el manual técnico y especificaciones del fabricante."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"32112.001","nombre":"Radioterapeuta"},{"codigo":"32112.003","nombre":"Técnico en radiología / Técnica en radiología"},{"codigo":"32112.004","nombre":"Técnico de radioterapia / Técnica de radioterapia"},{"codigo":"32112.005","nombre":"Técnico radiólogo / Técnica radióloga"},{"codigo":"32112.007","nombre":"Tecnólogo en radiología / Tecnóloga en radiología"},{"codigo":"32112.009","nombre":"Tecnólogo de radioterapia / Tecnóloga de radioterapia"},{"codigo":"32112.011","nombre":"Tecnólogo radiólogo / Tecnóloga radióloga"},{"codigo":"32112.012","nombre":"Tecnólogo en radiodiagnóstico y radioterapia / Tecnóloga en radiodiagnóstico y radioterapia"}],"conocimientos":[{"id":"40","nombre":"Anatomía"},{"id":"34","nombre":"Herramientas de simulación y diseño"},{"id":"21","nombre":"Medicina"},{"id":"5","nombre":"Servicio al cliente"},{"id":"91","nombre":"Tecnología de diagnóstico y tratamiento médico"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"10","nombre":"Relaciones interpersonales"}],"ocupaciones_afines":[{"codigo":"13420","nombre":"Directores y gerentes de servicios de salud / Directoras y gerentas de servicios de salud"},{"codigo":"21310","nombre":"Biólogos, botánicos, zoólogos y afines / Biólogas, botánicas, zoólogas y afines"},{"codigo":"22401","nombre":"Paramédicos / Paramédicas"},{"codigo":"22630","nombre":"Profesionales de la salud y la higiene laboral y ambiental"},{"codigo":"32111","nombre":"Técnicos y tecnólogos en imágenes diagnósticas / Técnicas y tecnólogas en imágenes diagnósticas"},{"codigo":"32113","nombre":"Técnicos y tecnólogos en medicina nuclear / Técnicas y tecnólogas en medicina nuclear"},{"codigo":"53299","nombre":"Trabajadores de los cuidados personales en servicios de salud no clasificados en otras ocupaciones / Trabajadoras de los cuidados personales en servicios de salud no clasificados en otras ocupaciones"}],"area_principal":{"sigla":"SABI","nombre":"Salud y bienestar"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"3211*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"3214","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Técnicos y tecnólogos en medicina nuclear / Técnicas y tecnólogas en medicina nuclear', '32113', 'Salud y bienestar', 3, false, '{"codigo":"32113","nombre":"Técnicos y tecnólogos en medicina nuclear / Técnicas y tecnólogas en medicina nuclear","descripcion":"Manejan, preparan y administran sustancias radioactivas en forma de fuentes abiertas de acuerdo con prescripción médica y normativa de salud, bioseguridad y radioprotección. Operan equipos biomédicos, producen estudios diagnósticos de medicina nuclear. Se pueden desempeñar en hospitales, clínicas, radiofarmacias y centros especializados de diagnóstico y tratamiento médico, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"32","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LA SALUD"},"subgrupo":{"codigo":"321","nombre":"Técnicos médicos y farmacéuticos"},"grupo_primario":{"codigo":"3211","nombre":"Técnicos en aparatos de diagnóstico y tratamiento médico"}},"funciones":[{"consecutivo":1,"texto":"Conocer la fisiología del paciente, la reacción de las drogas que está utilizando y la solución a posibles complicaciones que se le puedan presentar."},{"consecutivo":2,"texto":"Orientar a usuarios de acuerdo con el estado de salud, las condiciones, la normativa de salud, e informar a los médicos sobre señales anormales."},{"consecutivo":3,"texto":"Producir estudios de medicina nuclear según la normativa de salud y de protección radiológica."},{"consecutivo":4,"texto":"Preparar radiofármacos de acuerdo con normativa de salud y de protección radiológica."},{"consecutivo":5,"texto":"Administrar medicamentos según delegación y normativa de salud."},{"consecutivo":6,"texto":"Operar equipos biomédicos de acuerdo con manual técnico y especificaciones del fabricante."},{"consecutivo":7,"texto":"Controlar infecciones de acuerdo con los protocolos y la normativa de salud."},{"consecutivo":8,"texto":"Manejar las fuentes abiertas radiactivas de acuerdo con la normativa de salud y de protección radiológica."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"32113.002","nombre":"Tecnólogo de medicina nuclear / Tecnóloga de medicina nuclear"},{"codigo":"32113.003","nombre":"Tecnólogo en manejo de fuentes abiertas de uso diagnóstico y terapéutico / Tecnóloga en manejo de fuentes abiertas de uso diagnóstico y terapéutico"},{"codigo":"32113.005","nombre":"Tecnólogo en gammagrafía / Tecnóloga en gammagrafía"}],"conocimientos":[{"id":"40","nombre":"Anatomía"},{"id":"34","nombre":"Herramientas de simulación y diseño"},{"id":"23","nombre":"Idioma extranjero"},{"id":"21","nombre":"Medicina"},{"id":"5","nombre":"Servicio al cliente"},{"id":"91","nombre":"Tecnología de diagnóstico y tratamiento médico"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"10","nombre":"Relaciones interpersonales"}],"ocupaciones_afines":[{"codigo":"13420","nombre":"Directores y gerentes de servicios de salud / Directoras y gerentas de servicios de salud"},{"codigo":"21310","nombre":"Biólogos, botánicos, zoólogos y afines / Biólogas, botánicas, zoólogas y afines"},{"codigo":"22401","nombre":"Paramédicos / Paramédicas"},{"codigo":"22630","nombre":"Profesionales de la salud y la higiene laboral y ambiental"},{"codigo":"32111","nombre":"Técnicos y tecnólogos en imágenes diagnósticas / Técnicas y tecnólogas en imágenes diagnósticas"},{"codigo":"32112","nombre":"Técnicos y tecnólogos en radioterapia / Técnicas y tecnólogas en radioterapia"},{"codigo":"53299","nombre":"Trabajadores de los cuidados personales en servicios de salud no clasificados en otras ocupaciones / Trabajadoras de los cuidados personales en servicios de salud no clasificados en otras ocupaciones"}],"area_principal":{"sigla":"SABI","nombre":"Salud y bienestar"}