  ('rol_cuoc', 'Otros técnicos en aparatos de diagnóstico y tratamiento médico no clasificados en otras ocupaciones / Otras técnicas en aparatos de diagnóstico y tratamiento médico no clasificados en otras ocupaciones', '32119', 'Salud y bienestar', 3, false, '{"codigo":"32119","nombre":"Otros técnicos en aparatos de diagnóstico y tratamiento médico no clasificados en otras ocupaciones / Otras técnicas en aparatos de diagnóstico y tratamiento médico no clasificados en otras ocupaciones","descripcion":"Esta ocupación abarca a los otros técnicos en aparatos de diagnóstico y tratamiento médico no clasificados en otras ocupaciones del Grupo Primario 3211 Técnicos en aparatos de diagnóstico y tratamiento médico. Por ejemplo, incluye aquellos que operan equipo audiométrico, perfusionistas y técnicos de polisomnografía. Se pueden desempeñar en entidades administradoras de planes de beneficios, instituciones prestadoras de servicios de salud, laboratorios que desarrollan dispositivos de asistencia en salud, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"32","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO DE LA SALUD"},"subgrupo":{"codigo":"321","nombre":"Técnicos médicos y farmacéuticos"},"grupo_primario":{"codigo":"3211","nombre":"Técnicos en aparatos de diagnóstico y tratamiento médico"}},"funciones":[{"consecutivo":1,"texto":"Operar y supervisar uso de equipos de radiología, ecografía, resonancia magnética y ultrasonido para obtener imágenes del cuerpo con fines diagnósticos."},{"consecutivo":2,"texto":"Accionar y controlar aparatos utilizados para diagnosticar enfermedades y trastornos del sistema nervioso o de distintos órganos para hacer radiografías o para anestesiar."},{"consecutivo":3,"texto":"Posicionar equipos de imágenes o tratamiento observando las pantallas de visualización y ajustando parámetros y controles de acuerdo con especificaciones técnicas."},{"consecutivo":4,"texto":"Revisar y evaluar radiografías, cintas de vídeo, o información generada por computadores para determinar si las imágenes son satisfactorias para fines de diagnóstico y registrar los resultados de los procedimientos desarrollados."},{"consecutivo":5,"texto":"Conocer la fisiología del paciente, la reacción de las drogas que está utilizando y la solución a posibles complicaciones que se le puedan presentar."},{"consecutivo":6,"texto":"Observar las condiciones y el estado de salud de los pacientes, informar a un médico sobre señales anormales."},{"consecutivo":7,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"32119.001","nombre":"Operador de equipo audiométrico / Operadora de equipo audiométrico"},{"codigo":"32119.002","nombre":"Operador del sonógrafo / Operadora del sonógrafo"},{"codigo":"32119.003","nombre":"Técnico de polisomnografía / Técnica de polisomnografía"},{"codigo":"32119.004","nombre":"Tecnólogo de polisomnografía / Tecnóloga de polisomnografía"},{"codigo":"32119.006","nombre":"Operador de audiometría / Operadora de audiometría"},{"codigo":"32119.007","nombre":"Operador de electroencefalografía / Operadora de electroencefalografía"},{"codigo":"32119.008","nombre":"Operador de equipo de electrocardiografía / Operadora de equipo de electrocardiografía"},{"codigo":"32119.009","nombre":"Operador de equipo de escaneo óptico / Operadora de equipo de escaneo óptico"},{"codigo":"32119.010","nombre":"Operador de equipo electroencefalográfico / Operadora de equipo electroencefalográfico"},{"codigo":"32119.011","nombre":"Operador de escáner óptico / Operadora de escáner óptico"},{"codigo":"32119.012","nombre":"Operador de ultrasonido médico / Operadora de ultrasonido médico"},{"codigo":"32119.013","nombre":"Operador electrocardiográfico / Operadora electrocardiográfica"},{"codigo":"32119.015","nombre":"Perfusionista cardiovascular"},{"codigo":"32119.016","nombre":"Técnico de ecografía / Técnica de ecografía"},{"codigo":"32119.017","nombre":"Técnico de electrocardiografía / Técnica de electrocardiografía"},{"codigo":"32119.018","nombre":"Técnico de electroencefalografía / Técnica de electroencefalografía"},{"codigo":"32119.019","nombre":"Técnico de equipo electrocardiográfico / Técnica de equipo electrocardiográfico"},{"codigo":"32119.020","nombre":"Técnico de equipo electroencefalográfico / Técnica de equipo electroencefalográfico"},{"codigo":"32119.021","nombre":"Técnico de equipos audiométricos / Técnica de equipos audiométricos"}],"conocimientos":[{"id":"17","nombre":"Biología"},{"id":"23","nombre":"Idioma extranjero"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"21","nombre":"Medicina"},{"id":"5","nombre":"Servicio al cliente"},{"id":"18","nombre":"Sicología / psicología"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"10","nombre":"Relaciones interpersonales"}],"ocupaciones_afines":[{"codigo":"13420","nombre":"Directores y gerentes de servicios de salud / Directoras y gerentas de servicios de salud"},{"codigo":"21310","nombre":"Biólogos, botánicos, zoólogos y afines / Biólogas, botánicas, zoólogas y afines"},{"codigo":"22401","nombre":"Paramédicos / Paramédicas"},{"codigo":"22691","nombre":"Terapeutas ocupacionales"},{"codigo":"32111","nombre":"Técnicos y tecnólogos en imágenes diagnósticas / Técnicas y tecnólogas en imágenes diagnósticas"},{"codigo":"32550","nombre":"Técnicos y asistentes terapeutas / Técnicas y asistentes terapeutas"},{"codigo":"53299","nombre":"Trabajadores de los cuidados personales en servicios de salud no clasificados en otras ocupaciones / Trabajadoras de los cuidados personales en servicios de salud no clasificados en otras ocupaciones"}],"area_principal":{"sigla":"SABI","nombre":"Salud y bienestar"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"3211*","ciuo08_obs":"Denominaciones parcia