  ('rol_cuoc', 'Asistentes contables / Asistentas contables', '33131', 'Administración, finanzas y derecho', 3, false, '{"codigo":"33131","nombre":"Asistentes contables / Asistentas contables","descripcion":"Realizan la medición y reconocimiento de las transacciones contables, depuran y generan informes, soportan y liquidan impuestos; realizan seguimiento y análisis del comportamiento presupuestal; consolidan y depuran cuentas, apoyan y liquidan los procesos de nómina; verifican inventarios, elaboran, verifican y registran comprobantes y documentos relacionados de una empresa o persona natural. Se pueden desempeñar en el sector público y privado, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"331","nombre":"Técnicos y profesionales del nivel medio en finanzas y matemáticas"},"grupo_primario":{"codigo":"3313","nombre":"Técnicos de contabilidad, asistentes y afines"}},"funciones":[{"consecutivo":1,"texto":"Identificar y resolver los problemas contables que surjan en el curso de su trabajo de acuerdo con principios y normativa."},{"consecutivo":2,"texto":"Recolectar y organizar información para la atención de requerimientos tributarios de acuerdo con procedimiento técnico vigente."},{"consecutivo":3,"texto":"Elaborar y soportar informes y documentos financieros de acuerdo con el sistema de gestión documental y políticas institucionales vigentes."},{"consecutivo":4,"texto":"Medir y reconocer los recursos económicos de acuerdo con metodologías y normativa vigente."},{"consecutivo":5,"texto":"Realizar cálculos contables utilizando aplicaciones de software estándar."},{"consecutivo":6,"texto":"Organizar archivos de gestión documental de acuerdo con normativa vigente y procedimientos."},{"consecutivo":7,"texto":"Elaborar y soportar procesos de liquidación tributaría según procedimientos y normativa fiscal vigente."},{"consecutivo":8,"texto":"Cuantificar los resultados financieros de acuerdo con indicadores y metodologías vigentes."},{"consecutivo":9,"texto":"Atender clientes de acuerdo con normas técnicas y políticas institucionales vigentes."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33131.001","nombre":"Analista contable de inventarios"},{"codigo":"33131.002","nombre":"Analista de contabilidad"},{"codigo":"33131.003","nombre":"Analista de cuentas"},{"codigo":"33131.004","nombre":"Asistente de auditoría"},{"codigo":"33131.005","nombre":"Asistente central de cuentas por pagar / Asistenta central de cuentas por pagar"},{"codigo":"33131.006","nombre":"Asistente contable / Asistenta contable"},{"codigo":"33131.007","nombre":"Asistente de contabilidad / Asistenta de contabilidad"},{"codigo":"33131.008","nombre":"Asistente de costos / Asistenta de costos"},{"codigo":"33131.009","nombre":"Asistente de cuentas / Asistenta de cuentas"},{"codigo":"33131.010","nombre":"Asistente de revisoría fiscal / Asistenta de revisoría fiscal"}],"conocimientos":[{"id":"32","nombre":"Contabilidad e impuestos"},{"id":"3","nombre":"Economía"},{"id":"33","nombre":"Gestión financiera, administración bancaria y seguros"},{"id":"23","nombre":"Idioma extranjero"},{"id":"14","nombre":"Matemáticas"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"5","nombre":"Lógica matemática"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"11120","nombre":"Directores del gobierno / Directoras del gobierno"},{"codigo":"12111","nombre":"Directores y gerentes financieros / Directoras y gerentas financieras"},{"codigo":"24111","nombre":"Contadores / Contadoras"},{"codigo":"24112","nombre":"Auditores financieros y contables / Auditoras financieras y contables"},{"codigo":"24130",