  ('rol_cuoc', 'Asistentes financieros / Asistentas financieras', '33132', 'Administración, finanzas y derecho', 3, false, '{"codigo":"33132","nombre":"Asistentes financieros / Asistentas financieras","descripcion":"Recolectan, organizan, proyectan, verifican, supervisan y ajustan información para la elaboración de planes financieros, presupuestales e informes financieros, recopilan y codifican información financiera, proyectan inversiones, realizan seguimiento a los compromisos financieros, elaboran flujos de caja y demás funciones administrativas del cargo. Se pueden desempeñar en el público y privado, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"331","nombre":"Técnicos y profesionales del nivel medio en finanzas y matemáticas"},"grupo_primario":{"codigo":"3313","nombre":"Técnicos de contabilidad, asistentes y afines"}},"funciones":[{"consecutivo":1,"texto":"Mantener un registro completo de todas las transacciones financieras de una empresa, de acuerdo con los principios generales de contabilidad, con la orientación de los contadores."},{"consecutivo":2,"texto":"Verificar la exactitud de los documentos y registrar lo relativo a los pagos, los recibos y otras transacciones financieras."},{"consecutivo":3,"texto":"Apoyar el proceso y elaboración de presupuestos, informes y planes financieros de acuerdo con metodologías, planes estratégicos, guía técnica vigente, sistema de gestión documental y políticas institucionales."},{"consecutivo":4,"texto":"Realizar seguimiento a la ejecución presupuestal de acuerdo con procedimientos técnicos y normativa vigente."},{"consecutivo":5,"texto":"Realizar cálculos contables utilizando aplicaciones de software estándar."},{"consecutivo":6,"texto":"Revisar y soportar información financiera de acuerdo con indicadores y metodologías vigentes."},{"consecutivo":7,"texto":"Apoyar en la evaluación de inversión de acuerdo con normativa y metodología de riesgo de mercado de valores."},{"consecutivo":8,"texto":"Atender clientes del área financiera de acuerdo con normas técnicas y políticas institucionales vigentes."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33132.001","nombre":"Asistente de costos financiero / Asistenta de costos financiero"},{"codigo":"33132.002","nombre":"Asistente de planeación financiera / Asistenta de planeación financiera"},{"codigo":"33132.003","nombre":"Asistente de presupuesto / Asistenta de presupuesto"},{"codigo":"33132.004","nombre":"Asistente financiero / Asistenta financiera"}],"conocimientos":[{"id":"32","nombre":"Contabilidad e impuestos"},{"id":"3","nombre":"Economía"},{"id":"33","nombre":"Gestión financiera, administración bancaria y seguros"},{"id":"23","nombre":"Idioma extranjero"},{"id":"14","nombre":"Matemáticas"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"5","nombre":"Lógica matemática"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"11120","nombre":"Directores del gobierno / Directoras del gobierno"},{"codigo":"24111","nombre":"Contadores / Contadoras"},{"codigo":"24210","nombre":"Profesionales y analistas de gestión y organización"},{"codigo":"26551","nombre":"Actores / Actrices"},{"codigo":"33131","nombre":"Asistentes contables / Asistentas contables"},{"codigo":"33133","nombre":"Asistentes de tesorería / Asistentas de tesorería"},{"codigo":"33140","nombre":"Técnicos y profesionales del nivel medio de servicios estadísticos, matemáticos y afines / Técnicas y profesionales del nivel medio de servicios estadísticos, matemáticos y afines"},{"codigo":"41322","nombre":"Digitadores / Digitadoras"},{"codigo":"43110","nombre":"Auxiliares de contabilidad, 