  ('rol_cuoc', 'Asistentes de tesorería / Asistentas de tesorería', '33133', 'Administración, finanzas y derecho', 3, false, '{"codigo":"33133","nombre":"Asistentes de tesorería / Asistentas de tesorería","descripcion":"Revisan y verifican el funcionamiento de los procesos de tesorería, consolidan cuentas, cobran, remiten y registran pagos, realizan seguimiento de los movimientos monetario, manejan proveedores y clientes, elaboran informes, preparan estados periódicos, elaboran y revisan soportes de pago. Se pueden desempeñar en el sector público y privado, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"331","nombre":"Técnicos y profesionales del nivel medio en finanzas y matemáticas"},"grupo_primario":{"codigo":"3313","nombre":"Técnicos de contabilidad, asistentes y afines"}},"funciones":[{"consecutivo":1,"texto":"Recolectar y consolidar información para la elaboración del plan de tesorería de acuerdo con metodología y procedimiento técnico organizacionales u institucional vigente."},{"consecutivo":2,"texto":"Realizar seguimiento de los movimientos monetarios según procedimientos técnicos y tipo de recaudo financiero."},{"consecutivo":3,"texto":"Preparar documentos, estados e informes de tesorería de los períodos determinados de acuerdo con normativa y políticas organizacionales u institucionales vigentes."},{"consecutivo":4,"texto":"Clasificar y registrar información financiera de acuerdo con las políticas del ente económico, usando sistemas manuales y/o electrónicos."},{"consecutivo":5,"texto":"Identificar y resolver los problemas contables de tesorería que surjan en el curso de su trabajo."},{"consecutivo":6,"texto":"Medir y reconocer recursos monetarios de acuerdo con la normativa vigente."},{"consecutivo":7,"texto":"Realizar cálculos contables utilizando aplicaciones de software estándar."},{"consecutivo":8,"texto":"Organizar y archivar documentos del área de tesorería de acuerdo con normativa vigente."},{"consecutivo":9,"texto":"Atender clientes de acuerdo con normas técnicas y políticas institucionales vigentes."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33133.001","nombre":"Analista de tesorería"},{"codigo":"33133.002","nombre":"Asistente de pagos y desembolsos / Asistenta de pagos y desembolsos"},{"codigo":"33133.003","nombre":"Asistente de tesorería / Asistenta de tesorería"}],"conocimientos":[{"id":"32","nombre":"Contabilidad e impuestos"},{"id":"3","nombre":"Economía"},{"id":"23","nombre":"Idioma extranjero"},{"id":"14","nombre":"Matemáticas"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"5","nombre":"Lógica matemática"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"34","nombre":"Trabajo bajo presión"}],"ocupaciones_afines":[{"codigo":"11120","nombre":"Directores del gobierno / Directoras del gobierno"},{"codigo":"24111","nombre":"Contadores / Contadoras"},{"codigo":"24210","nombre":"Profesionales y analistas de gestión y organización"},{"codigo":"33131","nombre":"Asistentes contables / Asistentas contables"},{"codigo":"33132","nombre":"Asistentes financieros / Asistentas financieras"},{"codigo":"33140","nombre":"Técnicos y profesionales del nivel medio de servicios estadísticos, matemáticos y afines / Técnicas y profesionales del nivel medio de servicios estadísticos, matemáticos y afines"},{"codigo":"41322","nombre":"Digitadores / Digitadoras"},{"codigo":"43110","nombre":"Auxiliares de contabilidad, costos y tesorería"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"3313*","ciuo08_obs":"Denominaciones parciales","c