  ('rol_cuoc', 'Técnicos de contabilidad y afines / Técnicas de contabilidad y afines', '33134', 'Administración, finanzas y derecho', 3, false, '{"codigo":"33134","nombre":"Técnicos de contabilidad y afines / Técnicas de contabilidad y afines","descripcion":"Mantienen un registro completo de las transacciones contables de una empresa y verifican la exactitud de los documentos; coordinan actividades de gestión de cuentas de ahorros. Se pueden desempeñar en bancos, instituciones financieras, compañías de seguros, empresas de cobranza y otros establecimientos similares del sector público y privado, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"331","nombre":"Técnicos y profesionales del nivel medio en finanzas y matemáticas"},"grupo_primario":{"codigo":"3313","nombre":"Técnicos de contabilidad, asistentes y afines"}},"funciones":[{"consecutivo":1,"texto":"Mantener un registro completo de todas las transacciones financieras de una empresa, de acuerdo con los principios generales de contabilidad, con la orientación de los contadores."},{"consecutivo":2,"texto":"Identificar y resolver los problemas contables que surjan en el curso de su trabajo."},{"consecutivo":3,"texto":"Verificar la exactitud de los documentos y registrar lo relativo a los pagos, los recibos y otras transacciones financieras."},{"consecutivo":4,"texto":"Supervisar, coordinar, asignar y revisar el trabajo de empleados que apoyan el ejercicio contable, teneduría de libros, manejo de cuentas por pagar y cobrar, procesamiento, verificación y registro de documentos financieros, manejo de nómina, servicio a clientes en bancos, fiduciarias y otras entidades financieras; atención y registro de reclamos, entre otros."},{"consecutivo":5,"texto":"Realizar cálculos contables utilizando aplicaciones de software estándar."},{"consecutivo":6,"texto":"Establecer programas y procedimientos de trabajo y coordinar actividades con otros grupos o departamentos."},{"consecutivo":7,"texto":"Preparar, presentar informes y atender problemas de trabajo."},{"consecutivo":8,"texto":"Entrenar a los empleados en el desarrollo de sus funciones, normas de seguridad y reglamentos de la empresa."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33134.001","nombre":"Analista de nómina"},{"codigo":"33134.002","nombre":"Asistente de auditoría contable / Asistenta de auditoría contable"},{"codigo":"33134.003","nombre":"Coordinador de cuentas de ahorros / Coordinadora de cuentas de ahorros"},{"codigo":"33134.004","nombre":"Tenedor de libros / Tenedora de libros"}],"conocimientos":[{"id":"3","nombre":"Economía"},{"id":"23","nombre":"Idioma extranjero"},{"id":"14","nombre":"Matemáticas"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"2","nombre":"Escucha activa"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"16","nombre":"Resolución de problemas complejos"}],"ocupaciones_afines":[{"codigo":"11120","nombre":"Directores del gobierno / Directoras del gobierno"},{"codigo":"12111","nombre":"Directores y gerentes financieros / Directoras y gerentas financieras"},{"codigo":"12113","nombre":"Directores y gerentes de banca, crédito e inversiones / Directoras y gerentas de banca, crédito e inversiones"},{"codigo":"13460","nombre":"Directores y gerentes de sucursales de bancos, de servicios financieros y de seguros / Directoras y gerentas de sucursales de bancos, de servicios financieros y de seguros"},{"codigo":"24111","nombre":"Contadores / Contadoras"},{"codigo":"33140","nombre":"Técnicos y profesionales del nivel medio de servi