  ('rol_cuoc', 'Técnicos y profesionales del nivel medio de servicios estadísticos, matemáticos y afines / Técnicas y profesionales del nivel medio de servicios estadísticos, matemáticos y afines', '33140', 'Administración, finanzas y derecho', 3, false, '{"codigo":"33140","nombre":"Técnicos y profesionales del nivel medio de servicios estadísticos, matemáticos y afines / Técnicas y profesionales del nivel medio de servicios estadísticos, matemáticos y afines","descripcion":"Ayudan a planificar, recopilar, procesar y presentar datos estadísticos, matemáticos o actuariales y a llevar a cabo estas operaciones actuando por lo general bajo la dirección de estadísticos, matemáticos y actuarios, para resolver problemas en campos como la ciencia, la ingeniería, los negocios y las ciencias sociales. Se pueden desempeñar en universidades, bancos y fiduciarias, compañías de seguros, firmas consultoras y de ingeniería, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"331","nombre":"Técnicos y profesionales del nivel medio en finanzas y matemáticas"},"grupo_primario":{"codigo":"3314","nombre":"Técnicos y profesionales del nivel medio de servicios estadísticos, matemáticos y afines"}},"funciones":[{"consecutivo":1,"texto":"Ayudar a planificar y realizar cálculos estadísticos, matemáticos, actuarios y afines, aplicados a riesgos asociados con seguros y regímenes de pensión y, previsión social, entre otros."},{"consecutivo":2,"texto":"Recopilar datos y realizar operaciones de control de calidad en los censos y encuestas."},{"consecutivo":3,"texto":"Preparar resultados estadísticos, matemáticos, actuariales, contables y otros resultados para su presentación en forma gráfica o tabular."},{"consecutivo":4,"texto":"Identificar y resolver los problemas matemáticos, estadísticos y actuariales en campos científicos como las ciencias físicas, la ingeniería, la informática y otros campos como la investigación de operaciones, el comercio y la administración."},{"consecutivo":5,"texto":"Preparar estimaciones detalladas de cantidades y costos de materiales y mano de obra necesarios para llevar a cabo actividades de censo estadístico y encuestas."},{"consecutivo":6,"texto":"Apoyar en el establecimiento, mantenimiento y uso de registros y marcos de muestreo para las operaciones de censos y encuestas."},{"consecutivo":7,"texto":"Utilizar aplicaciones de software estándar para realizar cálculos matemáticos, actuarios, estadísticos, contables y afines."},{"consecutivo":8,"texto":"Apoyar investigaciones para ampliar los conocimientos en áreas tradicionales de las matemáticas, estadística y actuarial."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33140.001","nombre":"Asistente actuarial / Asistenta actuarial"},{"codigo":"33140.002","nombre":"Asistente estadístico / Asistenta estadística"},{"codigo":"33140.003","nombre":"Asistente matemático / Asistenta matemática"}],"conocimientos":[{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"23","nombre":"Idioma extranjero"},{"id":"14","nombre":"Matemáticas"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"5","nombre":"Lógica matemática"},{"id":"6","nombre":"Pensamiento crítico"}],"ocupaciones_afines":[{"codigo":"21200","nombre":"Matemáticos, actuarios y estadísticos / Matemáticas, actuarias y estadísticas"},{"codigo":"24111","nombre":"Contadores / Contadoras"},{"codigo":"24120","nombre":"Asesores financieros y de inversiones / Asesoras financieras y de inversiones"},{"codigo":"24130","nombre":"Analistas financieros / Analistas financieras"},{"codigo":"25120","nombre":"Desarrolladores de software / Desarrolladoras de software"},{"codigo":"25290","nombre":"Profesionales en bases de datos y en redes de computadores no clasificados en otras ocupaciones"},{"codigo":"33110","nombre":"Agentes de bolsa, cambio y otros servicios financieros"},{"codigo":"43121","nombre":"Auxiliares de servicios estadísticos y financieros"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"3314","ciuo08_obs":"Denominaciones completas","cno_codigo":"2161*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Tasadores, avaluadores y liquidadores de seguros / Tasadoras, avaluadoras y liquidadoras de seguros', '33150', 'Administración, finanzas y derecho', 3, false, '{"codigo":"33150","nombre":"Tasadores, avaluadores y liquidadores de seguros / Tasadoras, avaluadoras y liquidadoras de seguros","descripcion":"Investigan, calculan y determinan el valor de bienes asegurables, propiedades, mercancías, estimando la cuantía, y evalúan las pérdidas cubiertas por las pólizas de seguros, objetos siniestrados, daños, pérdidas y riesgos para la cobertura de las pólizas; determinan valores de inmuebles, predios y demás componentes del territorio urbano o rural, mediante procesos de estudios masivos, aplicación de métodos valuatorios y verificación de calidad. Se pueden desempeñar en compañías de seguros, reaseguros e intermediarios de seguros, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"331","nombre":"Técnicos y profesionales del nivel medio en finanzas y matemáticas"},"grupo_primario":{"codigo":"3315","nombre":"Tasadores, avaluadores y liquidadores de seguros"}},"funciones":[{"consecutivo":1,"texto":"Inspeccionar, determinar y estimar la calidad, cuantía, valor de intercambio y encargo valuatorio de bienes tangibles, intangibles y los derechos relacionados con los mismos según normativa y manual técnico."},{"consecutivo":2,"texto":"Evaluar la cuantía de los daños o pérdidas incurridos en un siniestro y las responsabilidades de indemnización de las compañías de seguros y reaseguros por las pérdidas cubiertas en sus pólizas."},{"consecutivo":3,"texto":"Obtener los documentos de compraventa de objetos siniestrados e información sobre el valor de artículos o bienes similares."},{"consecutivo":4,"texto":"Preparar y presentar informes y análisis sobre la determinación de valores, destacando los factores y métodos de estimación utilizados con su respectiva memoria de cargo."},{"consecutivo":5,"texto":"Investigar las circunstancias que originaron la reclamación del seguro y determinar la validez de la reclamación."},{"consecutivo":6,"texto":"Garantizar el cumplimiento de las políticas y normas establecidas por la compañía para la expedición de pólizas, minimizando el riesgo a través del análisis y revisión de documentos."},{"consecutivo":7,"texto":"Revisar, examinar, calcular y autorizar reclamaciones investigadas por el área correspondiente."},{"consecutivo":8,"texto":"Revisar las pólizas que se expiden para controlar que las condiciones otorgadas cumplan con las directrices de la compañía."},{"consecutivo":9,"texto":"Valorar riesgo de aseguramiento según normativa y manual técnico."},{"consecutivo":10,"texto":"Determinar y liquidar los montos económicos que por pérdida o daño cubre la póliza de seguro."},{"consecutivo":11,"texto":"Preparar, organizar y presentar la documentación relacionada con requisitos para las pólizas de seguros."},{"consecutivo":12,"texto":"Examinar informes del liquidador y reclamaciones similares, para determinar el monto de cubrimiento del seguro."},{"consecutivo":13,"texto":"Seleccionar métodos valuatorios y rutas en estudios masivos y visitas a predios teniendo en cuenta la dinámica territorial y la información catastral."},{"consecutivo":14,"texto":"Establecer programas y procedimientos de trabajo y coordinar actividades con otros grupos o departamentos."},{"consecutivo":15,"texto":"Aplicar procesos de valuación de todo tipo de bienes tangibles e intangibles siguiendo procedimientos y normatividad vigente."},{"consecutivo":16,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33150.001","nombre":"Analista de indemnizaciones"},{"codigo":"33150.002","nombre":"Analista de siniestros"},{"codigo":"33150.003","nombre":"Analista de suscripción"},{"codigo":"33150.004"