  ('rol_cuoc', 'Agentes y corredores de seguros / Agentes y corredoras de seguros', '33210', 'Administración, finanzas y derecho', 3, false, '{"codigo":"33210","nombre":"Agentes y corredores de seguros / Agentes y corredoras de seguros","descripcion":"Asesoran y venden seguros de vida, de automóviles, contra accidentes e incendios, marítimos, de responsabilidad civil y otro tipo de seguros individuales o colectivos, a nuevos clientes o los ya establecidos. Se pueden desempeñar en compañías de seguros, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"332","nombre":"Agentes comerciales y corredores"},"grupo_primario":{"codigo":"3321","nombre":"Agentes y corredores de seguros"}},"funciones":[{"consecutivo":1,"texto":"Vender contratos de seguros para determinados proyectos, instalaciones, actividades que comprenden riesgos especiales o de gran magnitud, vehículos, salud, vida, propiedad, accidentes, incendio, entre otros."},{"consecutivo":2,"texto":"Aprobar la venta de pólizas y garantizar el cumplimiento de las coberturas de seguros de acuerdo con las regulaciones del gobierno."},{"consecutivo":3,"texto":"Garantizar el cumplimiento de las políticas y normas establecidas por la compañía para la expedición de pólizas, minimizando el riesgo a través del análisis y revisión de documentos."},{"consecutivo":4,"texto":"Obtener información sobre las circunstancias de los clientes para determinar el tipo apropiado de seguros que puede convenirles."},{"consecutivo":5,"texto":"Evaluar y liquidar solicitudes nuevas y renovadas para determinar el seguro de riesgos, primas, extensión, cubrimiento, tipo y nivel de cobertura, formas de pago y otras condiciones del contrato; con base en los reportes médicos, tablas promedio, materiales de referencia, normativa, manual técnico y otros documentos."},{"consecutivo":6,"texto":"Negociar con los clientes a fin de determinar el tipo y el grado de riesgo que necesitan cubrir con una póliza del seguro."},{"consecutivo":7,"texto":"Preparar informes de valoración y análisis para agencias de arrendamiento, compañías de seguros, departamentos de gobierno, juzgados, abogados, acreedores, compradores y subastadores."},{"consecutivo":8,"texto":"Suministrar información respecto a los paquetes de seguros en grupo o individuales, la cobertura del riesgo, forma de pago, beneficios y otras características de las pólizas."},{"consecutivo":9,"texto":"Revisar que las solicitudes sean apropiadas y que los exámenes médicos y otros requisitos de las pólizas se cumplan."},{"consecutivo":10,"texto":"Negociar y suscribir pólizas de reaseguro."},{"consecutivo":11,"texto":"Procesar reclamaciones de acuerdo con protocolo y tipo de seguro."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33210.001","nombre":"Agente corredor de seguros / Agente corredora de seguros"},{"codigo":"33210.002","nombre":"Agente de seguros"},{"codigo":"33210.003","nombre":"Agente de seguros colectivos"},{"codigo":"33210.004","nombre":"Agente de ventas de seguros"},{"codigo":"33210.005","nombre":"Analista de reaseguros"},{"codigo":"33210.006","nombre":"Analista de seguros"},{"codigo":"33210.007","nombre":"Asegurador / Aseguradora"},{"codigo":"33210.008","nombre":"Corredor de seguros / Corredora de seguros"},{"codigo":"33210.009","nombre":"Negociador de seguros / Negociadora de seguros"},{"codigo":"33210.010","nombre":"Representante de ventas de seguros"},{"codigo":"33210.011","nombre":"Suscriptor de seguros / Suscriptora de seguros"},{"codigo":"33210.012","nombre":"Vendedor de seguros / Vendedora de seguros"}],"conocimientos":[{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"1","nombre":"Gerencia y administración"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"14","nombre":"Matemáticas"},{"id":"4","nombre":"Mercadotecnia y publicidad"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"2","nombre":"Escucha activa"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"3","nombre":"Redacción de textos"}],"ocupaciones_afines":[{"codigo":"12111","nombre":"Directores y gerentes financieros / Directoras y gerentas financieras"},{"codigo":"12112","nombre":"Directores y gerentes de seguros, bienes raíces y corretaje financiero / Directoras y gerentas de seguros, bienes raíces y corretaje financiero"},{"codigo":"24130","nombre":"Analistas financieros / Analistas financieras"},{"codigo":"33110","nombre":"Agentes de bolsa, cambio y otros servicios financieros"},{"codigo":"33120","nombre":"Analistas y asistentes financieros en préstamos y créditos / Analistas y asistentes financieras en préstamos y créditos"},{"codigo":"33150","nombre":"Tasadores, avaluadores y liquidadores de seguros / Tasadoras, avaluadoras y liquidadoras de seguros"},{"codigo":"33220","nombre":"Representantes comerciales"},{"codigo":"33412","nombre":"Supervisores de entidades financieras / Supervisoras de entidades financieras"},{"codigo":"43121","nombre":"Auxiliares de servicios estadísticos y financieros"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"3321","ciuo08_obs":"Denominaciones completas","cno_codigo":"1233*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"6231","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Representantes comerciales', '33220', 'Comercio, mercadeo y publicidad', 3, false, '{"codigo":"33220","nombre":"Representantes comerciales","descripcion":"Representan a las empresas y conducen sus operaciones de venta de diversos bienes y servicios a otras empresas y organizaciones; proporcionan información especializada del producto según se requiera; venden mercancías y servicios no técnicos para clientes mayoristas, al detal, comerciantes, industriales y profesionales. Se pueden desempeñar en empresas que producen, distribuyen o proveen bienes y servicios, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"332","nombre":"Agentes comerciales y corredores"},"grupo_primario":{"codigo":"3322","nombre":"Representantes comerciales"}},"funciones":[{"consecutivo":1,"texto":"Identificar necesidades y recursos de los clientes y recomendar los servicios y productos apropiados."},{"consecutivo":2,"texto":"Realizar seguimiento y consultar a los clientes después de la venta para resolver problemas, asegurar la satisfacción y proporcionar soporte técnico de los productos."},{"consecutivo":3,"texto":"Captar las órdenes de pedido de minoristas, establecimientos industriales, comerciantes mayoristas y otros clientes."},{"consecutivo":4,"texto":"Obtener y actualizar información sobre las condiciones del mercado, de los bienes y servicios de los empleadores y de los competidores."},{"consecutivo":5,"texto":"Vender bienes, equipos, suministros y servicios técnicos a establecimientos industriales, comerciales o particulares, instituciones, empresas, entre otros."},{"consecutivo":6,"texto":"Suministrar información general y especializada sobre características, ventajas, precios y funcionamiento de equipos, mercancías, productos, servicios y demostrar su utilización."},{"consecutivo":7,"texto":"Informar a proveedores y fabricantes las reacciones de los clientes y sus exigencias."},{"consecutivo":8,"texto":"Elaborar cotizaciones, condiciones de venta, garantías, fechas y orden de entrega."},{"consecutivo":9,"texto":"Implementar estrategias de mercado de acuerdo con la situación de la organización y los procesos administrativos."},{"consecutivo":10,"texto":"Promover las ventas con los clientes."},{"consecutivo":11,"texto":"Identificar y contactar clientes potenciales."},{"consecutivo":12,"texto":"Gestionar el cobro de cartera de sus clientes para garantizar el cumplimiento de los compromisos adquiridos en el proceso comercial de la venta."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33220.001","nombre":"Agente comercial de ventas"},{"codigo":"33220.002","nombre":"Agente de ventas de industria manufacturera"},{"codigo":"33220.003","nombre":"Agente de ventas de negocios"},{"codigo":"33220.004","nombre":"Agente de ventas"},{"codigo":"33220.005","nombre":"Asesor comercial / Asesora comercial"},{"codigo":"33220.006","nombre":"Asesor comercial de cesantías / Asesora comercial de cesantías"},{"codigo":"33220.007","nombre":"Asesor comercial de entidades financieras / Asesora comercial de entidades financieras"},{"codigo":"33220.008","nombre":"Asesor comercial de fondos de pensiones y cesantías / Asesora comercial de fondos de pensiones y cesantías"},{"codigo":"33220.009","nombre":"Asesor comercial de fondos / Asesora comercial de fondos"},{"codigo":"33220.010","nombre":"Asesor comercial en ventas no técnicas / Asesora comercial en ventas no técnicas"},{"codigo":"33220.011","nombre":"Asesor de servicio de postventa / Asesora de servicio de postventa"},{"codigo":"33220.012","nombre":"Asesor de ventas / Asesora de ventas"},{"codigo":"33220.013","nombre":"Consejero de servicios postventa / Consejera de servicios postventa"},{"codigo":"33220.014","nombre":"Consultor de ventas de ma