  ('rol_cuoc', 'Agentes de compras', '33230', 'Comercio, mercadeo y publicidad', 3, false, '{"codigo":"33230","nombre":"Agentes de compras","descripcion":"Adquieren bienes y servicios para uso o reventa por cuenta de establecimientos industriales; negocian mercancías para ser revendidas por establecimientos mayoristas y al detal; realizan contratos y pactan condiciones de pago. Se pueden desempeñar en sector público o privado, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"332","nombre":"Agentes comerciales y corredores"},"grupo_primario":{"codigo":"3323","nombre":"Agentes de compras"}},"funciones":[{"consecutivo":1,"texto":"Determinar y adjudicar contratos a los proveedores o recomendar la adjudicación de contratos para la compra de equipos, materias primas y servicios y mercancías para la reventa."},{"consecutivo":2,"texto":"Revisar requerimientos y las existencias y definir especificaciones de calidad y cantidad de los bienes y servicios para compra, los costos, fechas de entrega y demás condiciones contractuales."},{"consecutivo":3,"texto":"Comprar materiales, mercancías, servicios, equipos generales y especializados, ya sea para su uso, para futuro procesamiento o para reventa por establecimientos de venta mayoristas o minoristas."},{"consecutivo":4,"texto":"Seleccionar la mercancía o los productos que mejor se adapten a las necesidades del establecimiento."},{"consecutivo":5,"texto":"Convocar a licitación, consultando con los proveedores y examinar las ofertas."},{"consecutivo":6,"texto":"Estudiar los informes de mercado, publicaciones comerciales y materiales de promoción de ventas."},{"consecutivo":7,"texto":"Visitar ferias comerciales, salas de exposiciones, fábricas y eventos sobre diseño del producto."},{"consecutivo":8,"texto":"Establecer plazos de entrega, seguir de cerca el proceso y mantener contacto con los clientes y proveedores para resolver problemas."},{"consecutivo":9,"texto":"Entrevistar a los proveedores, solicitar cotizaciones y negociar los precios, descuentos, condiciones de crédito, convenios y modalidades de transporte, con el fin de evaluar y seleccionar el que más se ajusta a las necesidades y requisitos establecidos."},{"consecutivo":10,"texto":"Crear órdenes de compras, procesar compras y monitorear trazabilidad de pedidos según procedimientos."},{"consecutivo":11,"texto":"Establecer y mantener contacto, en calidad de intermediarios, entre compradores y vendedores de productos básicos y otros bienes."},{"consecutivo":12,"texto":"Supervisar la distribución de mercancías a los puntos de venta y mantener los niveles de existencias adecuados."},{"consecutivo":13,"texto":"Atender oferta y solicitudes de los clientes según procedimiento técnico y normativa de negocio."},{"consecutivo":14,"texto":"Firmar acuerdos o contratos en representación de clientes y velar por su cumplimiento."},{"consecutivo":15,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33230.001","nombre":"Agente de adquisiciones"},{"codigo":"33230.002","nombre":"Agente de compras"},{"codigo":"33230.003","nombre":"Agente de suministros"},{"codigo":"33230.004","nombre":"Agente intermediario de compras"},{"codigo":"33230.005","nombre":"Analista de compras"},{"codigo":"33230.006","nombre":"Analista de compras e importaciones"},{"codigo":"33230.007","nombre":"Analista de compras y suministros"},{"codigo":"33230.008","nombre":"Asistente de adquisiciones / Asistenta de adquisiciones"},{"codigo":"33230.009","nombre":"Asistente de compras / Asistenta de compras"},{"codigo":"33230.010","nombre":"Asistente de compras de materiales / Asistenta de compras de materiales"},{"codigo":"33230.011","nombre":"Asistente de compras y adquisiciones / Asistenta de compras y adquisiciones"},{"codigo":"33230.012","no