  ('rol_cuoc', 'Asistentes de comercio exterior / Asistentas de comercio exterior', '33311', 'Logística y transporte', 3, false, '{"codigo":"33311","nombre":"Asistentes de comercio exterior / Asistentas de comercio exterior","descripcion":"Preparan, tramitan y controlan documentos y autorizaciones de actividades de ingreso, salida, tránsito y depósito de mercancías según normativa de comercio exterior y acuerdos comerciales. Se pueden desempeñar en el sector público y privado, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"333","nombre":"Agentes de servicios empresariales"},"grupo_primario":{"codigo":"3331","nombre":"Declarantes o gestores de aduana"}},"funciones":[{"consecutivo":1,"texto":"Llevar a cabo los procedimientos de despacho de aduanas relativos a las exportaciones o importaciones."},{"consecutivo":2,"texto":"Verificar la documentación de importación y exportación para verificar el contenido de la carga."},{"consecutivo":3,"texto":"Atender clientes según requerimientos y protocolos de servicio."},{"consecutivo":4,"texto":"Apoyar en la expedición de documentos de importación y exportación según procesos y políticas de la organización."},{"consecutivo":5,"texto":"Desarrollar y controlar la operación de importación y exportación de mercancías según normativa de comercio exterior."},{"consecutivo":6,"texto":"Liquidar impuestos y derechos aduaneros de mercancías según normativa de comercio exterior."},{"consecutivo":7,"texto":"Asesorar a clientes sobre restricciones de importación y exportación, sistemas tarifarios, cartas de crédito, requisitos para el seguro y otros asuntos aduaneros."},{"consecutivo":8,"texto":"Asistir en el trámite de nacionalización de bienes y mercancías."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33311.001","nombre":"Agente de exportación"},{"codigo":"33311.002","nombre":"Agente de importación"},{"codigo":"33311.003","nombre":"Agente de liquidación de comercio exterior"},{"codigo":"33311.004","nombre":"Agente de transacciones en comercio exterior"},{"codigo":"33311.005","nombre":"Asistente de comercio exterior / Asistenta de comercio exterior"},{"codigo":"33311.006","nombre":"Asistente de exportaciones / Asistenta de exportaciones"},{"codigo":"33311.007","nombre":"Asistente de importaciones / Asistenta de importaciones"},{"codigo":"33311.008","nombre":"Coordinador de aduanas / Coordinadora de aduanas"},{"codigo":"33311.009","nombre":"Coordinador de exportaciones / Coordinadora de exportaciones"},{"codigo":"33311.010","nombre":"Coordinador de importaciones / Coordinadora de importaciones"},{"codigo":"33311.011","nombre":"Coordinador de operaciones aduaneros / Coordinadora de operaciones aduaneros"},{"codigo":"33311.012","nombre":"Coordinador de servicio al cliente de servicios aduaneros / Coordinadora de servicio al cliente de servicios aduaneros"}],"conocimientos":[{"id":"33","nombre":"Gestión financiera, administración bancaria y seguros"},{"id":"23","nombre":"Idioma extranjero"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"27","nombre":"Seguridad pública"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"10","nombre":"Relaciones interpersonales"}],"ocupaciones_afines":[{"codigo":"11120","nombre":"Directores del gobierno / Directoras del gobierno"},{"codigo":"11200","nombre":"Directores y gerentes generales / Directoras y gerentas generales"},{"codigo":"12212","nombre":"Directores y gerentes de comercio exterior / Directoras y gerentas de comercio exterior"},{"codigo":"33312","nombre":"Gestores y agentes de servicios de aduana / Gestoras y agentes