  ('rol_cuoc', 'Gestores y agentes de servicios de aduana / Gestoras y agentes de servicios de aduana', '33312', 'Logística y transporte', 3, false, '{"codigo":"33312","nombre":"Gestores y agentes de servicios de aduana / Gestoras y agentes de servicios de aduana","descripcion":"Tramitan a nombre de clientes importadores y exportadores documentos y autorizaciones aduaneras; intervienen en la compra y venta de espacios de carga a nombre de sus clientes; incluye agentes que no han sido clasificados quienes realizan transacciones comerciales u otros servicios entre las partes a nombre del cliente. Se pueden desempeñar en empresas aduaneras y de corretaje marítimo o pueden trabajar en forma independiente, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"333","nombre":"Agentes de servicios empresariales"},"grupo_primario":{"codigo":"3331","nombre":"Declarantes o gestores de aduana"}},"funciones":[{"consecutivo":1,"texto":"Tramitar documentos de importación, exportación y otros formatos, de acuerdo con las leyes y regulaciones aduaneras a nombre de los clientes."},{"consecutivo":2,"texto":"Asesorar a clientes sobre restricciones de importación y exportación, sistemas tarifarios, cartas de crédito, requisitos para el seguro y otros asuntos aduaneros."},{"consecutivo":3,"texto":"Cotizar y liquidar pagos de impuestos, derechos aduaneros, bodegaje y transporte de mercancía importada y exportada y fianzas para cubrir derechos de aduana."},{"consecutivo":4,"texto":"Clasificar las mercancías en diferentes niveles de aranceles o grupos arancelarios utilizando el sistema de codificación arancelaria."},{"consecutivo":5,"texto":"Apoyar la expedición de documentos de importación, exportación a nombre de los clientes por medio de un poder."},{"consecutivo":6,"texto":"Intervenir en la compra y la venta de espacios de carga en barcos a nombre de personas, empresas y gobiernos."},{"consecutivo":7,"texto":"Consultar publicaciones comerciales con el fin de informar a los clientes sobre el destino, las tasas, el despacho y el tiempo de desembarque."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33312.001","nombre":"Agente de carga y aduana"},{"codigo":"33312.002","nombre":"Agente de carga"},{"codigo":"33312.003","nombre":"Agente de embarque"},{"codigo":"33312.004","nombre":"Agente de envío"},{"codigo":"33312.005","nombre":"Agente marítimo / Agente marítima"},{"codigo":"33312.006","nombre":"Agente portuario / Agente portuaria"},{"codigo":"33312.007","nombre":"Corredor de aduana / Corredora de aduana"},{"codigo":"33312.008","nombre":"Gestor de aduana / Gestora de aduana"},{"codigo":"33312.009","nombre":"Representante aduanero / Representante aduanera"},{"codigo":"33312.010","nombre":"Tramitador de documentos de aduana / Tramitadora de documentos de aduana"}],"conocimientos":[{"id":"23","nombre":"Idioma extranjero"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"27","nombre":"Seguridad pública"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"},{"id":"31","nombre":"Servicios de transporte"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"15","nombre":"Orientación al servicio"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"10","nombre":"Relaciones interpersonales"}],"ocupaciones_afines":[{"codigo":"11120","nombre":"Directores del gobierno / Directoras del gobierno"},{"codigo":"12112","nombre":"Directores y gerentes de seguros, bienes raíces y corretaje financiero / Directoras y gerentas de seguros, bienes raíces y corretaje financiero"},{"cod