  ('rol_cuoc', 'Coordinadores y productores de conferencias, eventos y espectáculos / Coordinadoras y productoras de conferencias, eventos y espectáculos', '33320', 'Turismo, hotelería y gastronomía', 3, false, '{"codigo":"33320","nombre":"Coordinadores y productores de conferencias, eventos y espectáculos / Coordinadoras y productoras de conferencias, eventos y espectáculos","descripcion":"Planean, coordinan y gestionan la realización de conferencias, eventos, convenciones, reuniones, seminarios, exhibiciones, muestras comerciales, festivales y espectáculos, supervisan la arquitectura, estructura de montajes, electricidad, iluminación, sonido, video y plan de emergencias. Se pueden desempeñar en asociaciones comerciales y profesionales de turismo, centro de convenciones, empresas de organización de eventos, festivales de música, teatro, artes circenses y demás espectáculos, así como por otras empresas del sector público y privado, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"333","nombre":"Agentes de servicios empresariales"},"grupo_primario":{"codigo":"3332","nombre":"Coordinadores y productores de conferencias, eventos y espectáculos"}},"funciones":[{"consecutivo":1,"texto":"Promover y concertar servicios de organización de conferencias, congresos, espectáculos, convenciones, muestras y ferias comerciales a los clientes."},{"consecutivo":2,"texto":"Reunir clientes para analizar sus necesidades y examinar las opciones de paquetes de prestaciones que puedan satisfacer tales necesidades."},{"consecutivo":3,"texto":"Organizar, planear y coordinar los recursos y ejecución de los servicios y las instalaciones de eventos y espectáculos, según criterios técnicos, normatividad y protocolos."},{"consecutivo":4,"texto":"Negociar el tipo y costos de los servicios que se presten, ajustándose al presupuesto."},{"consecutivo":5,"texto":"Responder a las consultas relativas a los servicios ofrecidos, costos de alojamiento y alquiler de equipos, catering y otros servicios relacionados."},{"consecutivo":6,"texto":"Realizar seguimiento a la ejecución presupuestal, procedimientos administrativos y progreso de los eventos de acuerdo con lo concertado con comités de organizadores y patrocinadores."},{"consecutivo":7,"texto":"Organizar registro de participantes, preparar programas, material promocional y publicidad."},{"consecutivo":8,"texto":"Supervisar y coordinar el trabajo del personal de apoyo requerido para los eventos."},{"consecutivo":9,"texto":"Planear la logística y vigilar el cumplimiento del protocolo diplomático en la visita oficial de funcionarios, políticos y dignatarios extranjeros en el país."},{"consecutivo":10,"texto":"Capacitar y entrenar al personal de apoyo requerido para los eventos."},{"consecutivo":11,"texto":"Operar eventos de acuerdo con especificaciones técnicas y normativas."},{"consecutivo":12,"texto":"Preparar informes y registros financieros del evento."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33320.001","nombre":"Administrador de conferencia / Administradora de conferencia"},{"codigo":"33320.002","nombre":"Administrador de cuenta organización de conferencias o eventos / Administradora de cuenta organización de conferencias o eventos"},{"codigo":"33320.003","nombre":"Administrador de eventos / Administradora de eventos"},{"codigo":"33320.004","nombre":"Agente de contratación de espectáculos"},{"codigo":"33320.005","nombre":"Consultor de gestión de eventos / Consultora de gestión de eventos"},{"codigo":"33320.006","nombre":"Coordinador del área de backstage / Coordinadora del área de backstage"},{"codigo":"33320.007","nombre":"Coordinador de convención / Coordinadora de convención"},{"codigo":"33320.008","nombre":"Coordinador de acomodación /