  ('rol_cuoc', 'Agentes de empleo y contratistas de mano de obra', '33330', 'Administración, finanzas y derecho', 3, false, '{"codigo":"33330","nombre":"Agentes de empleo y contratistas de mano de obra","descripcion":"Encuentran trabajadores en busca de empleo, cuyos perfiles profesionales correspondan con las ofertas de puestos vacantes, o escoger los trabajadores que requiere cualquier empleador, público o privado; encontrar trabajadores para los empleadores y mano de obra contratada para proyectos particulares a petición de las empresas y otras organizaciones, entre ellas el gobierno y otras instituciones; encontrar puestos de trabajo para los demandantes de empleo a cambio del pago de una comisión. Se pueden desempeñar en sector público o privado, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"333","nombre":"Agentes de servicios empresariales"},"grupo_primario":{"codigo":"3333","nombre":"Agentes de empleo y contratistas de mano de obra"}},"funciones":[{"consecutivo":1,"texto":"Encontrar trabajadores en busca de empleo con las competencias requeridas para cubrir los puestos vacantes y realizar los trámites necesarios de acuerdo con las regulaciones y los requisitos nacionales o internacionales en materia de contratación."},{"consecutivo":2,"texto":"Recopilar información del mercado laboral relacionada con vacantes, requisitos, funciones y otra información ocupacional."},{"consecutivo":3,"texto":"Examinar conjuntamente con los empleadores las competencias y otras características que se exigirán a los postulantes a un empleo o contrato."},{"consecutivo":4,"texto":"Entrevistar a los solicitantes para obtener la historia laboral, antecedentes educativos y aspiraciones laborales."},{"consecutivo":5,"texto":"Asesorar a empleadores sobre oferta laboral y aspectos relacionados con el mercado de trabajo."},{"consecutivo":6,"texto":"Administrar e interpretar pruebas diseñadas para determinar los intereses, las aptitudes y habilidades del solicitante de empleo."},{"consecutivo":7,"texto":"Identificar las dificultades para emplearse y ayudar al interesado a desarrollar habilidades, aptitudes y estrategias de búsqueda de trabajo."},{"consecutivo":8,"texto":"Verificar que los contratos de trabajo cumplan con los requisitos legales y que sean firmados."},{"consecutivo":9,"texto":"Brindar asesoría sobre programas de formación y capacitación."},{"consecutivo":10,"texto":"Establecer la necesidad de orientación, rehabilitación, entrenamiento o capacitación y remitir los interesados a los servicios correspondientes."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33330.001","nombre":"Agente de empleo"},{"codigo":"33330.002","nombre":"Agente de oficina colocación de empleo"},{"codigo":"33330.003","nombre":"Agente de selección"},{"codigo":"33330.004","nombre":"Asesor de servicio de empleo / Asesora de servicio de empleo"},{"codigo":"33330.005","nombre":"Contratista de mano de obra"},{"codigo":"33330.006","nombre":"Funcionario de servicio de empleo / Funcionaria de servicio de empleo"},{"codigo":"33330.007","nombre":"Intermediario contratista de mano de obra / Intermediaria contratista de mano de obra"},{"codigo":"33330.008","nombre":"Técnico de servicio de empleo / Técnica de servicio de empleo"}],"conocimientos":[{"id":"1","nombre":"Gerencia y administración"},{"id":"6","nombre":"Gestión del talento humano y de personal"},{"id":"23","nombre":"Idioma extranjero"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"24232","nombre":"Consejeros de servicios de empleo / Consejeras de servicios de empleo"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"3333","ciuo08_obs":"Denominaciones completas","cno_codigo":"4212*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Agentes inmobiliarios / Agentes inmobiliarias', '33340', 'Comercio, mercadeo y publicidad', 3, false, '{"codigo":"33340","nombre":"Agentes inmobiliarios / Agentes inmobiliarias","descripcion":"Actúan como agentes o intermediadores para la compra, la venta y el arriendo de bienes inmuebles tales como casas, apartamentos, edificios comerciales, tierras y otros inmuebles. Comercializan y gestionan el servicio de intermediación, comercialización de bienes inmuebles a su cargo; gestionan, preparan la elaboración y formalización de los contratos de arrendamiento y venta, organizan la firma de los acuerdos de los derechos de propiedad y arrendamiento. Recaudan el alquiler y depósitos de garantía a nombre de los propietarios e inspeccionar antes, durante y después de los arrendamientos. Se pueden desempeñar en compañías de propiedad y finca raíz, pueden trabajar por cuenta propia, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"333","nombre":"Agentes de servicios empresariales"},"grupo_primario":{"codigo":"3334","nombre":"Agentes inmobiliarios"}},"funciones":[{"consecutivo":1,"texto":"Documentar información relacionada con las propiedades ofrecidas para venta o arrendamiento, circunstancias de su propietario y necesidades de los posibles compradores o inquilinos."},{"consecutivo":2,"texto":"Mostrar las propiedades e informar las condiciones para ser vendidas o arrendadas a los posibles compradores o inquilinos."},{"consecutivo":3,"texto":"Facilitar las negociaciones entre inquilinos, compradores y propietarios de los inmuebles, en caso necesario."},{"consecutivo":4,"texto":"Organizar la firma de los acuerdos de los derechos de arrendamiento y los contratos de cesión de derechos de propiedad."},{"consecutivo":5,"texto":"Preparar los contratos de arrendamiento y venta y estimar los costos."},{"consecutivo":6,"texto":"Recaudar el alquiler o canon de arrendamiento, así como gestionar las garantías a nombre de los propietarios."},{"consecutivo":7,"texto":"Establecer acuerdos de compraventa para aprobación entre comprador y vendedor."},{"consecutivo":8,"texto":"Promocionar y comercializar los bienes inmuebles a su cargo, de acuerdo con el tipo de transacción o negocio inmobiliario como compraventa, permuta, arriendo, entre otras, anunciando mediante avisos en periódicos y otros medios de comunicación la oferta de bienes inmuebles."},{"consecutivo":9,"texto":"Asegurar la disponibilidad de los trabajadores para realizar el mantenimiento de las propiedades."},{"consecutivo":10,"texto":"Asesorar a los clientes, tales como propietarios, arrendatarios, compradores, vendedores, entre otros, en lo relacionado con el servicio y condiciones inmobiliarias, transacciones, precios, hipotecas, requisitos legales y asuntos relacionados con la compraventa, la permuta, el arriendo, entre otras."},{"consecutivo":11,"texto":"Captar los bienes inmuebles objeto de intermediación inmobiliaria y concertar acuerdos para llevar a cabo su servicio de intermediación."},{"consecutivo":12,"texto":"Gestionar el cierre del negocio inmobiliario."},{"consecutivo":13,"texto":"Gestionar la administración de los bienes inmuebles arrendados que están a su cargo."},{"consecutivo":14,"texto":"Inspeccionar el estado de los bienes inmuebles objeto de arrendamiento."},{"consecutivo":15,"texto":"Planear y controlar la gestión del cliente y la prestación de los servicios inmobiliarios."},{"consecutivo":16,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33340.001","nombre":"Agente de bienes raíces"},{"codigo":"33340.002","nombre":"Agente de finca raíz"},{"codigo":"33340.003","nombre":"Agente inmobiliario / Agente inmobiliaria"},{"codigo":"33340.004","nombre":"Asesor inmobiliario / Asesora inmobiliaria"},{"codigo":"33340.005