  ('rol_cuoc', 'Asistentes de mercadeo, publicidad y comunicaciones / Asistentas de mercadeo, publicidad y comunicaciones', '33392', 'Comercio, mercadeo y publicidad', 3, false, '{"codigo":"33392","nombre":"Asistentes de mercadeo, publicidad y comunicaciones / Asistentas de mercadeo, publicidad y comunicaciones","descripcion":"Desarrollan actividades de gestión comercial y de venta. Venden mercancías y servicios no técnicos para clientes mayoristas, al detal, comerciantes, industriales y profesionales. Se pueden desempeñar en empresas que producen, distribuyen o proveen bienes y servicios, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"333","nombre":"Agentes de servicios empresariales"},"grupo_primario":{"codigo":"3339","nombre":"Agentes de servicios comerciales no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Obtener información sobre los servicios que se venden y las necesidades de los posibles compradores."},{"consecutivo":2,"texto":"Seleccionar la mercancía que mejor se ajuste a los requisitos del establecimiento."},{"consecutivo":3,"texto":"Establecer y mantener contacto, en calidad de intermediarios, entre compradores y vendedores de productos básicos y otros bienes."},{"consecutivo":4,"texto":"Identificar y contactar clientes potenciales."},{"consecutivo":5,"texto":"Informar a los clientes sobre las ventajas y utilización de las mercancías y servicios."},{"consecutivo":6,"texto":"Consultar con los clientes después de la venta, para resolver problemas existentes y brindar asesoría."},{"consecutivo":7,"texto":"Revisar y actualizar la información en cuanto a innovaciones de productos, competidores y condiciones de mercadeo."},{"consecutivo":8,"texto":"Soportar la operación comercial de impulsadores, pro