  ('rol_cuoc', 'Auxiliares de promoción artística', '33393', 'Audiovisuales, Artes Escénicas y Música', 2, false, '{"codigo":"33393","nombre":"Auxiliares de promoción artística","descripcion":"Apoyan la labor de managers, bookers y promotores artísticos con el cumplimiento de actividades puntuales que permitan alcanzar los objetivos planteados para el desarrollo del proyecto de promoción y representación artística, acompaña y asiste las labores de las agencias de booking, management, y sellos disqueros. Se pueden desempeñar en agencias de promoción artística, productoras de música y artes, compañías discográficas, compañías discográficas, managers y bookers, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"333","nombre":"Agentes de servicios empresariales"},"grupo_primario":{"codigo":"3339","nombre":"Agentes de servicios comerciales no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Verificar que el servicio contratado se proporcione al comprador en conformidad con el plazo acordado."},{"consecutivo":2,"texto":"Apoyar en la organización de viajes colectivos para grupos en desplazamiento de eventos."},{"consecutivo":3,"texto":"Apoyar en la búsqueda y gestión de fechas para conciertos, eventos y espectáculos de acuerdo con la planeación y programación."},{"consecutivo":4,"texto":"Apoyar el seguimiento y gestión del desarrollo del material requerido para la gestión, promoción y difusión de proyectos."},{"consecutivo":5,"texto":"Realizar la búsqueda y construcción de bases de datos de posibles marcas, clientes, lugares donde se pueda vender el proyecto, y contactos de relacionamiento público del artista."},{"consecutivo":6,"texto":"Apoyar la creación de estrategias para la difusión, comunicación y gestión de artistas y eventos."},{"consecutivo":7,"texto":"Acompañar en la ejecución de las estrategias desarrolladas por el manager del artista."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33393.001","nombre":"Agregador de contenidos audiovisuales / Agregadora de contenidos audiovisuales"},{"codigo":"33393.002","nombre":"Auxiliar de gestión artística"},{"codigo":"33393.003","nombre":"Auxiliar de promoción artística"}],"conocimientos":[{"id":"23","nombre":"Idioma extranjero"},{"id":"48","nombre":"Instrumentos musicales"},{"id":"35","nombre":"Interpretación de planos"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"85","nombre":"Seguridad y salud en el trabajo"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"2","nombre":"Escucha activa"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"37","nombre":"Proactividad"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"34","nombre":"Trabajo bajo presión"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"34353","nombre":"Auxiliares de producción de eventos y espectáculos"}],"area_principal":{"sigla":"AVEM","nombre":"Audiovisuales, Artes Escénicas y Música"},"areas_complementarias":[{"sigla":"COMP","nombre":"Comercio, mercadeo y publicidad"}],"equivalencias":[{"ciuo08_codigo":"3339*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"6312*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Agentes de servicios comerciales no clasificados en otras ocupaciones', '33399', 'Comercio, mercadeo y publicidad', 3, false, '{"codigo":"33399","nombre":"Agentes de servicios comerciales no clasificados en otras ocupaciones","descripcion":"Esta ocupación abarca a los agentes de servicios comerciales no clasificados en otros Grupos Primarios del subgrupo 3339: Agentes de servicios comerciales no clasificados en otros Grupos Primarios. Por ejemplo, incluyen a aquellos que establecen contactos de negocios o venden servicios a las empresas como espacios publicitarios en los medios de comunicación; organizan contratos laborales con atletas, animadores y artistas escénicos, así como para la publicación de libros, o la producción de obras de teatro, grabaciones y espectáculos musicales y la venta de música, subasta de propiedades y otros bienes; diseñan y organizan paquetes turísticos y viajes de grupo. Se pueden desempeñar en empresas que producen, distribuyen o proveen bienes y servicios, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"333","nombre":"Agentes de servicios empresariales"},"grupo_primario":{"codigo":"3339","nombre":"Agentes de servicios comerciales no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Identificar posibles compradores, las necesidades e información de los servicios ofrecidos."},{"consecutivo":2,"texto":"Asesorar a clientes en lo relacionado con leyes y regulaciones de marcas y patentes, ayudando a preparar solicitudes o examinar las solicitudes presentadas para su registro."},{"consecutivo":3,"texto":"Buscar registros de marcas y patentes, y determinar o confirmar si estos ya han sido establecidos y preparar y presentar aplicaciones para registros de marcas y patentes."},{"consecutivo":4,"texto":"Negociar y firmar contratos en nombre del vendedor o del comprador y explicar al cliente las condiciones de venta y de pago."},{"consecutivo":5,"texto":"Promover las ventas con los clientes."},{"consecutivo":6,"texto":"Informar a los clientes sobre las ventajas y utilización de las mercancías y los servicios."},{"consecutivo":7,"texto":"Consultar con los clientes después de la venta, para resolver problemas existentes y brindar asesoría."},{"consecutivo":8,"texto":"Asesorar sobre destinos e itinerarios, opciones de transporte, alojamiento, costos, servicios conexos y condiciones específicas del viaje de acuerdo con requerimientos del cliente."},{"consecutivo":9,"texto":"Comercializar paquetes, tiquetes y otros servicios turísticos teniendo en cuenta los requerimientos del cliente y de acuerdo con las políticas de la organización."},{"consecutivo":10,"texto":"Tramitar requisitos de visado y otros servicios consulares de acuerdo con procedimientos técnicos."},{"consecutivo":11,"texto":"Preparar reportes e informes de acuerdo con procedimientos técnicos de la organización."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33399.001","nombre":"Agente de alquiler"},{"codigo":"33399.002","nombre":"Agente de derechos y propiedad intelectual"},{"codigo":"33399.003","nombre":"Agente de marcas"},{"codigo":"33399.004","nombre":"Agente de marcas y patentes"},{"codigo":"33399.005","nombre":"Agente de patente"},{"codigo":"33399.006","nombre":"Operador turístico / Operadora turística"},{"codigo":"33399.007","nombre":"Organizador de viajes / Organizadora de viajes"},{"codigo":"33399.008","nombre":"Representante de servicios a las empresas"},{"codigo":"33399.009","nombre":"Subastador / Subastadora"},{"codigo":"33399.010","nombre":"Gestor de derechos de autor / Gestora de derechos de autor"}],"conocimientos":[{"id":"1","nombre":"Gerencia y administración"},{"id":"23","nombre":"Idioma extranjero"},{"id":"4","nombre":"Me