  ('rol_cuoc', 'Secretarios jurídicos / Secretarias jurídicas', '33420', 'Administración, finanzas y derecho', 3, false, '{"codigo":"33420","nombre":"Secretarios jurídicos / Secretarias jurídicas","descripcion":"Realizan y coordinan funciones y procedimientos administrativos de apoyo en los tribunales, oficinas de abogados y otras instancias judiciales; programan audiencias y velan por el mantenimiento de archivos y expedientes. Prestan servicios relacionados con asuntos legales tales como contratos de seguros, transferencias de propiedad y concesión de préstamos y otras operaciones financieras. Se pueden desempeñar en juzgados, salas penales, fiscalía, tribunales, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"334","nombre":"Secretarios administrativos y especializados"},"grupo_primario":{"codigo":"3342","nombre":"Secretarios jurídicos"}},"funciones":[{"consecutivo":1,"texto":"Preparar y tramitar documentos jurídicos y demás documentos como escrituras, testamentos, declaraciones juradas, notas oficiales, informes judiciales, alegatos, apelaciones, contratos y otros que resuman las posiciones legales y establezcan las condiciones de la concesión de préstamos o la suscripción de seguros."},{"consecutivo":2,"texto":"Planear, programar y organizar juicios, entrevistas, reuniones y exposiciones para las audiencias."},{"consecutivo":3,"texto":"Examinar la documentación tales como hipotecas, gravámenes, juicios, servidumbres, contratos y mapas con el fin de verificar las descripciones jurídicas y la titularidad de los bienes raíces."},{"consecutivo":4,"texto":"Preparar los documentos relativos a la transferencia de bienes raíces, título y valores u otros asuntos que requieren registro oficial."},{"consecutivo":5,"texto":"Documentar procedimientos judiciales, procedimientos y sentencias."},{"consecutivo":6,"texto":"Revisar y corregir documentos y correspondencia para asegurar el cumplimiento con los procedimientos legales."},{"consecutivo":7,"texto":"Expedir y gestionar la entrega de correspondencia legal como comparendos, citaciones, órdenes judiciales, entre otros, a los clientes, testigos y funcionarios judiciales."},{"consecutivo":8,"texto":"Organizar y mantener los archivos, documentos, expedientes y las bibliotecas de literatura jurídica."},{"consecutivo":9,"texto":"Asesorar a clientes en asuntos jurídicos, derechos y obligaciones."},{"consecutivo":10,"texto":"Prestar asistencia en la preparación de presupuestos y seguimiento de los gastos."},{"consecutivo":11,"texto":"Realizar requisiciones y contratos de adquisición de materiales para uso administrativo."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33420.001","nombre":"Administrador de práctica legal / Administradora de práctica legal"},{"codigo":"33420.002","nombre":"Asistente administrativo legal / Asistenta administrativa legal"},{"codigo":"33420.003","nombre":"Asistente ejecutivo legal / Asistenta ejecutiva legal"},{"codigo":"33420.004","nombre":"Citador / Citadora"},{"codigo":"33420.005","nombre":"Citador sustanciador / Citadora sustanciadora"},{"codigo":"33420.006","nombre":"Coordinador de la práctica jurídica / Coordinadora de la práctica jurídica"},{"codigo":"33420.007","nombre":"Estenógrafo judicial / Estenógrafa judicial"},{"codigo":"33420.008","nombre":"Secretario de litigios / Secretaria de litigios"},{"codigo":"33420.009","nombre":"Secretario de traspaso / Secretaria de traspaso"},{"codigo":"33420.010","nombre":"Secretario jurídico / Secretaria jurídica"},{"codigo":"33420.011","nombre":"Secretario legal / Secretaria legal"},{"codigo":"33420.012","nombre":"Supervisor de administración legal / Supervisora de administración legal"},{"codigo":"33420.013","nombre":"Taquígrafo judicial / Taquígrafa j