  ('rol_cuoc', 'Asistentes administrativos / Asistentas administrativas', '33431', 'Administración, finanzas y derecho', 3, true, '{"codigo":"33431","nombre":"Asistentes administrativos / Asistentas administrativas","descripcion":"Gestionan e implementan procesos, procedimientos y actividades administrativas de acuerdo con lineamientos organizacionales para el cumplimiento de los objetivos de las dependencias. Realizan tareas de enlace, coordinación y organización en apoyo de los directivos y profesionales, preparan correspondencia, informes y registros de los procedimientos y otros documentos especializados. Realizan funciones de secretariado a empleados, profesionales y directivos. Se pueden desempeñar en el sector público o privado, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"334","nombre":"Secretarios administrativos y especializados"},"grupo_primario":{"codigo":"3343","nombre":"Secretarios y asistentes administrativos y ejecutivos"}},"funciones":[{"consecutivo":1,"texto":"Coordinar con otros miembros del personal asuntos relacionados con las operaciones de la organización."},{"consecutivo":2,"texto":"Elaborar documentos, correspondencia, actos administrativos, cartas comerciales y dar respuestas a las mismas de acuerdo con lineamientos de la organización, guía y procedimientos técnicos."},{"consecutivo":3,"texto":"Asistir la gestión de proyectos de acuerdo con metodologías y normativa vigente."},{"consecutivo":4,"texto":"Gestionar solicitudes para concertar entrevistas, citas, reuniones, actividades y viajes de acuerdo con procedimientos técnicos y organizacionales."},{"consecutivo":5,"texto":"Atender clientes de acuerdo con protocolos de servicio."},{"consecutivo":6,"texto":"Recepcionar, clasificar y distribuir las comunicaciones de acuerdo con el procedimiento de la organización."},{"consecutivo":7,"texto":"Organizar archivos de gestión y documentos de la unidad administrativa de acuerdo con la legislación vigente, los procesos administrativos, lineamientos y procedimientos técnicos."},{"consecutivo":8,"texto":"Controlar inventarios y tramitar pedidos de la unidad administrativas de acuerdo con procesos administrativos, lineamientos y procedimientos técnicos."},{"consecutivo":9,"texto":"Registrar palabra a palabra y digitar información confiable de las intervenciones en tribunales, congresos, comités, asambleas legislativas, utilizando medios tecnológicos existentes."},{"consecutivo":10,"texto":"Transcribir intervenciones grabadas garantizando la exactitud de estas de acuerdo con formatos establecidos."},{"consecutivo":11,"texto":"Aplicar los procedimientos técnicos establecidos de acuerdo con las políticas de la organización."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33431.001","nombre":"Asistente administrativo / Asistenta administrativa"},{"codigo":"33431.002","nombre":"Asistente bilingüe / Asistenta bilingüe"},{"codigo":"33431.003","nombre":"Asistente de correspondencia / Asistenta de correspondencia"},{"codigo":"33431.004","nombre":"Asistente de gerencia / Asistenta de gerencia"},{"codigo":"33431.005","nombre":"Asistente de gerencia administrativa / Asistenta de gerencia administrativa"},{"codigo":"33431.006","nombre":"Asistente de planeación administrativa / Asistenta de planeación administrativa"},{"codigo":"33431.007","nombre":"Asistente de proyecto / Asistenta de proyecto"},{"codigo":"33431.008","nombre":"Asistente ejecutivo / Asistenta ejecutiva"},{"codigo":"33431.009","nombre":"Asistente ejecutivo administrativo / Asistenta ejecutiva administrativa"},{"codigo":"33431.010","nombre":"Gestor administrativo / Gestora administrativa"},{"codigo":"33431.011","nombre":"Relator administrativo de actas / Relatora administrativa de actas"},{"cod