  ('rol_cuoc', 'Asistentes de talento humano / Asistentas de talento humano', '33432', 'Administración, finanzas y derecho', 3, false, '{"codigo":"33432","nombre":"Asistentes de talento humano / Asistentas de talento humano","descripcion":"Realizan tareas de enlace y asisten la coordinación y la organización en apoyo de los directivos y profesionales en la vinculación, la capacitación, el desarrollo y el bienestar en la gestión del talento humano. Se pueden desempeñar en el sector público, privado, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"334","nombre":"Secretarios administrativos y especializados"},"grupo_primario":{"codigo":"3343","nombre":"Secretarios y asistentes administrativos y ejecutivos"}},"funciones":[{"consecutivo":1,"texto":"Colaborar en la preparación de presupuestos, control de gastos, elaboración de contratos y preparación de órdenes de compra o adquisición."},{"consecutivo":2,"texto":"Supervisar el trabajo del personal de apoyo administrativo."},{"consecutivo":3,"texto":"Apoyar acciones de capacitación, programas de inducción, reinducción y bienestar social laboral según políticas y procedimientos organizacionales."},{"consecutivo":4,"texto":"Publicar convocatorias laborales, apoyar el proceso de reclutamiento, selección y vinculación del talento humano según políticas y procedimientos organizacionales."},{"consecutivo":5,"texto":"Apoyar en la elaboración de informes correspondientes a la gestión del talento humano."},{"consecutivo":6,"texto":"Apoyar la generación de nómina según normativa y políticas organizacionales."},{"consecutivo":7,"texto":"Brindar información relacionada con los procesos de gestión humana de acuerdo con procedimientos organizacionales."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"