  ('rol_cuoc', 'Técnicos en archivística / Técnicas en archivística', '33433', 'Administración, finanzas y derecho', 3, false, '{"codigo":"33433","nombre":"Técnicos en archivística / Técnicas en archivística","descripcion":"Implementan el programa de gestión documental y el desarrollo de los procesos archivísticos en las organizaciones, procesan la información con base en la producción, el trámite y el control. Realizan tareas de enlace, coordinación y organización en apoyo de los directivos y profesionales y/o preparan correspondencia, informes y registros de los procedimientos y otros documentos especializados. Aplicación de tabla de retención documental y tabla de valoración documental, clasificación, ordenación y descripción de los documentos de archivo aplicando la normatividad vigente. Se pueden desempeñar en el sector público, privado, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"334","nombre":"Secretarios administrativos y especializados"},"grupo_primario":{"codigo":"3343","nombre":"Secretarios y asistentes administrativos y ejecutivos"}},"funciones":[{"consecutivo":1,"texto":"Coordinar actividades de archivo de acuerdo con estrategias de gestión y proceso administrativo."},{"consecutivo":2,"texto":"Ejecutar los procesos de gestión documental en las organizaciones, de acuerdo con los requerimientos de la entidad y la normatividad vigente."},{"consecutivo":3,"texto":"Apoyar los procedimientos establecidos en la organización para las transferencias documentales."},{"consecutivo":4,"texto":"Orientar y facilitar el acceso a la información que se encuentra registrada en los documentos de archivo."},{"consecutivo":5,"texto":"Recepcionar, registrar y distribuir los documentos de archivo de acuerdo con la normatividad y políticas institucionales."},{"consecutivo":6,"texto":"Organizar archivo central, fondos documentales acumulados y documentos de archivo mediante la aplicación de la metodología archivística y procesos técnicos, tecnologías y principios archivísticos de acuerdo con políticas empresariales y normativa."},{"consecutivo":7,"texto":"Aplicar las técnicas archivísticas de control de documentos de archivo de acuerdo con la normatividad vigente y con las necesidades institucionales."},{"consecutivo":8,"texto":"Administrar transferencia documental de acuerdo con procedimientos técnicos y normativa."},{"consecutivo":9,"texto":"Prestar servicios de información orientada a la consulta e investigación de documentos de archivo a usuarios internos y externos, de acuerdo con las necesidades presentes en cada una de las fases de archivo."},{"consecutivo":10,"texto":"Operar herramientas tecnológicas de la información y las comunicaciones disponibles de acuerdo con políticas institucionales, protocolos y manuales técnicos."},{"consecutivo":11,"texto":"Apoyar en la elaboración de documentos relacionados con archivo de acuerdo con pautas y políticas institucionales."},{"consecutivo":12,"texto":"Preservar y conservar documentos de archivo utilizando las herramientas tecnológicas existentes, de acuerdo con procedimientos técnicos, tipos de soporte, protocolos establecidos, políticas institucionales y normatividad vigente."},{"consecutivo":13,"texto":"Realizar las actividades propias de la disposición final de documentos de archivo de acuerdo con las políticas institucionales y la normatividad vigente."},{"consecutivo":14,"texto":"Asistir en acciones de conservación y conservación preventiva a los archivistas, conservadores y restauradores de patrimonio cultural mueble."},{"consecutivo":15,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33433.003","nombre":"Técnico en administración documental / Técnica en administración documental"},{"codigo":"33433.004","nombre":"Técnico en archivística / Técnica en archivística"},{"codigo":"33433.005","nombre":"Técnico en archivos / Técnica en archivos"},{"codigo":"33433.006","nombre":"Técnico en gestión documental / Técnica en gestión documental"},{"codigo":"33433.007","nombre":"Técnico en organización de archivos / Técnica en organización de archivos"},{"codigo":"33433.008","nombre":"Tecnólogo en administración documental / Tecnóloga en administración documental"},{"codigo":"33433.009","nombre":"Tecnólogo en archivística / Tecnóloga en archivística"},{"codigo":"33433.010","nombre":"Tecnólogo en gestión documental / Tecnóloga en gestión documental"}],"conocimientos":[{"id":"56","nombre":"Bibliotecología, información y archivología"},{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"43","nombre":"Patrimonio cultural"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"16","nombre":"Resolución de problemas complejos"},{"id":"38","nombre":"Seguir instrucciones"}],"ocupaciones_afines":[{"codigo":"26211","nombre":"Archivistas"},{"codigo":"41101","nombre":"Oficinistas generales"},{"codigo":"41200","nombre":"Secretarios generales / Secretarias generales"},{"codigo":"42251","nombre":"Auxiliares de información y servicio al cliente"},{"codigo":"43121","nombre":"Auxiliares de servicios estadísticos y financieros"},{"codigo":"44150","nombre":"Empleados auxiliares de archivos / Empleadas auxiliares de archivos"},{"codigo":"44161","nombre":"Auxiliares de talento humano"},{"codigo":"44199","nombre":"Otro personal de apoyo administrativo no clasificados en otras ocupaciones / Otra personal de apoyo administrativo no clasificados en otras ocupaciones"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derec