  ('rol_cuoc', 'Secretarios médicos / Secretarias médicas', '33440', 'Administración, finanzas y derecho', 3, false, '{"codigo":"33440","nombre":"Secretarios médicos / Secretarias médicas","descripcion":"Realizan funciones de secretariado a empleados, profesionales y directivos, utilizando los conocimientos especializados de la terminología médica y los procedimientos de atención de la salud para ayudar a los profesionales de esta área y otros trabajadores mediante la realización de una variedad de funciones de comunicación, documentación, administración y de coordinación interna; apoyan a los centros médicos y otras organizaciones. Se pueden desempeñar en empresas del sector público, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"334","nombre":"Secretarios administrativos y especializados"},"grupo_primario":{"codigo":"3344","nombre":"Secretarios médicos"}},"funciones":[{"consecutivo":1,"texto":"Programar y confirmar citas médicas y actividades de la unidad administrativa de acuerdo con procedimiento técnico."},{"consecutivo":2,"texto":"Comunicar mensajes al personal médico y a los pacientes."},{"consecutivo":3,"texto":"Compilar, registrar y organizar las historias clínicas, correspondencia y demás documentos de la unidad administrativa teniendo en cuenta la legislación vigente y procesos administrativos."},{"consecutivo":4,"texto":"Registrar y mantener archivos, registros médicos e historias clínicas de acuerdo con normativa y procedimientos técnicos."},{"consecutivo":5,"texto":"Recepcionar, clasificar y distribuir las comunicaciones de acuerdo con el procedimiento de la organización."},{"consecutivo":6,"texto":"Diligenciar y completar formularios, documentos e historias técnicas, seguros, entre otros, de acuerdo con procedimientos de servicios y normativa."},{"consecutivo":7,"texto":"Aplicar los procedimientos establecidos de acuerdo con las políticas de la organización."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33440.001","nombre":"Asistente administrativo de cirugía / Asistenta administrativa de cirugía"},{"codigo":"33440.002","nombre":"Asistente administrativo de consultorio médico / Asistenta administrativa de consultorio médico"},{"codigo":"33440.003","nombre":"Coordinador de práctica médica / Coordinadora de práctica médica"},{"codigo":"33440.004","nombre":"Encargado administrativo de pabellón de hospital / Encargada administrativa de pabellón de hospital"},{"codigo":"33440.005","nombre":"Encargado de facturación del seguro médico / Encargada de facturación del seguro médico"},{"codigo":"33440.006","nombre":"Secretario auxiliar de cirugía / Secretaria auxiliar de cirugía"},{"codigo":"33440.007","nombre":"Secretario auxiliar médico / Secretaria auxiliar médica"},{"codigo":"33440.008","nombre":"Secretario de admisiones / Secretaria de admisiones"},{"codigo":"33440.009","nombre":"Secretario de atención al paciente / Secretaria de atención al paciente"},{"codigo":"33440.010","nombre":"Secretario de facturación de seguro médico / Secretaria de facturación de seguro médico"},{"codigo":"33440.011","nombre":"Secretario de laboratorio médico / Secretaria de laboratorio médico"},{"codigo":"33440.012","nombre":"Secretario de consultorio médico / Secretaria de consultorio médico"},{"codigo":"33440.013","nombre":"Secretario de patología / Secretaria de patología"},{"codigo":"33440.014","nombre":"Secretario de sala de hospitalización / Secretaria de sala de hospitalización"},{"codigo":"33440.015","nombre":"Secretario dental / Secretaria dental"},{"codigo":"33440.016","nombre":"Taquígrafo médico / Taquígrafa médica"},{"codigo":"33440.017","nombre":"Transcriptor médico / Transcriptora médica"}],"conocimientos":[{"id":"56","nombre":"Bibliotecología, información y a