  ('rol_cuoc', 'Inspectores de aduana, fronteras y migración / Inspectoras de aduana, fronteras y migración', '33510', 'Administración, finanzas y derecho', 3, false, '{"codigo":"33510","nombre":"Inspectores de aduana, fronteras y migración / Inspectoras de aduana, fronteras y migración","descripcion":"Facilitan las operaciones de comercio exterior y controlan el cumplimiento de las obligaciones tributarias, aduaneras y cambiarias; controlan el ingreso y la salida de viajeros, carga, mercancías, divisas y vehículos, asegurando el cumplimiento de los regímenes aduaneros establecidos. Administran y hacen cumplir las leyes, las regulaciones y las disposiciones relacionadas con migración, verificación de extranjeros y extranjería; desempeñan las funciones de control y vigilancia como autoridad migratoria. Se pueden desempeñar en aeropuertos, puertos, fronteras y en el territorio nacional, entidades del gobierno, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"335","nombre":"Agentes de gobierno y profesionales del nivel medio para la aplicación de regulaciones"},"grupo_primario":{"codigo":"3351","nombre":"Inspectores de aduana, fronteras y migración"}},"funciones":[{"consecutivo":1,"texto":"Ejercer la facultad de Policía Judicial de conformidad con la ley y los lineamientos establecidos por la dirección de migración, con el direccionamiento y la coordinación de las demás autoridades competentes, utilizando los bienes y las armas de fuego que se le sean asignadas."},{"consecutivo":2,"texto":"Determinar la admisión y controlar los documentos de viaje de personas, transporte, mercancías en tránsito de importación y exportación, y carga de vehículos que cruzan fronteras nacionales para garantizar que tengan las autorizaciones, los certificados y demás documentos de conformidad con las normas, los protocolos, los lineamientos y las regulaciones gubernamentales."},{"consecutivo":3,"texto":"Inspeccionar los equipajes de las personas que cruzan las fronteras nacionales para detectar e incautar mercancías prohibidas, no declaradas o contrabando, garantizando que se ajusta a las normas y las regulaciones gubernamentales relativas a la importación o la exportación de bienes y divisas."},{"consecutivo":4,"texto":"Orientar e informar a usuarios aduaneros e interesados sobre las leyes, las regulaciones de aduana y la aplicación de las normas."},{"consecutivo":5,"texto":"Verificar que lo informado por el usuario aduanero corresponda con la normatividad en liquidación y pago de impuestos."},{"consecutivo":6,"texto":"Realizar las funciones administrativas necesarias para registrar los hallazgos, las transacciones, las infracciones y las resoluciones."},{"consecutivo":7,"texto":"Coordinar acciones, realizar seguimiento y cooperar con otros órganos involucrados de orden nacional e internacional, y aquellas que ejerzan competencias policiales en temas migratorios y procesamiento de infractores."},{"consecutivo":8,"texto":"Ejecutar el proceso de traslado de deportados y expulsados."},{"consecutivo":9,"texto":"Verificar la expedición de documentos de importación y exportación, según los procedimientos y las políticas de la organización."},{"consecutivo":10,"texto":"Buscar, registrar, verificar, analizar y difundir la información, y actualizar las bases de datos relacionadas con la actividad migratoria."},{"consecutivo":11,"texto":"Desarrollar, orientar y participar en las actividades relacionadas con los procesos de control y la vigilancia como autoridad migratoria."},{"consecutivo":12,"texto":"Proyectar, emitir y presentar conceptos e informes de carácter técnico, pericial y estadístico para brindar respuesta a requerimientos y la toma de decisiones en procesos misionales de migración y los protocolos de reserva de la información."},{"consecutivo":13,"texto":"Definir de manera oportuna la situación del viajero, verificando de manera física y tecnológica, los documentos y la información que reposa en las bases de datos."},{"consecutivo":14,"texto":"Participar en la expedición de documentos y el registro de extranjeros."},{"consecutivo":15,"texto":"Declarar ante los tribunales de justicia sobre las circunstancias y los resultados de las investigaciones realizadas."},{"consecutivo":16,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33510.001","nombre":"Aduanero / Aduanera"},{"codigo":"33510.005","nombre":"Agente de control de pasaportes"},{"codigo":"33510.006","nombre":"Agente de inmigración"},{"codigo":"33510.007","nombre":"Funcionario de inmigración / Funcionaria de inmigración"},{"codigo":"33510.008","nombre":"Guardia de frontera"},{"codigo":"33510.009","nombre":"Inspector de operación aduanera / Inspectora de operación aduanera"},{"codigo":"33510.010","nombre":"Inspector de fronteras / Inspectora de fronteras"},{"codigo":"33510.011","nombre":"Inspector de inmigración / Inspectora de inmigración"},{"codigo":"33510.012","nombre":"Inspector de pasaportes / Inspectora de pasaportes"},{"codigo":"33510.013","nombre":"Inspector de policía de fronteras / Inspectora de policía de fronteras"},{"codigo":"33510.014","nombre":"Oficial de comprobación de pasaporte"},{"codigo":"33510.015","nombre":"Oficial de inmigración"},{"codigo":"33510.016","nombre":"Agente de migración"},{"codigo":"33510.017","nombre":"Oficial de migración"},{"codigo":"33510.018","nombre":"Oficial de aduana"}],"conocimientos":[{"id":"28","nombre":"Leyes y gobierno"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"102","nombre":"Metodología e investigación"},{"id":"101","nombre":"Principios éticos"},{"id":"27","nombre":"Seguridad pública"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"3","nombre":"Redacción de textos"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"24111","nombre":"Contadores / Contadoras"},{"codigo":"24112","nombre":"Auditores financieros y contables / Auditoras financieras y contables"},{"codigo":"24120","nombre":"Asesores financieros y de inversiones / Asesoras financieras y de inversiones"},{"codigo":"24130","nombre":"Analistas financieros / Analistas financieras"},{"codigo":"33311","nombre":"Asistentes de comercio exterior / Asistentas de comercio exterior"},{"codigo":"33520","nombre":"Agentes de administración tributaria"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[{"sigla":"SEGU","nombre":"Seguridad"}],"equivalencias":[{"ciuo08_codigo":"3351","ciuo08_obs":"Denominaciones completas","cno_codigo":"1226*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"1227*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"1234*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Agentes de administración tributaria', '33520', 'Administración, finanzas y derecho', 3, false, '{"codigo":"33520","nombre":"Agentes de administración tributaria","descripcion":"Administran y hacen cumplir las leyes y regulaciones relacionadas con inmigración, aduana, impuestos y beneficios de la seguridad social. Examinan declaraciones tributarias, facturas de venta y otros documentos para determinar el tipo y monto de impuestos, tasas y otros tipos de gravámenes que deben pagar los particulares o las empresas, remitiendo los casos excepcionales o importantes a los contadores, gerentes o personal directivo de la administración pública. Se pueden desempeñar en el gobierno, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"335","nombre":"Agentes de gobierno y profesionales del nivel medio para la aplicación de regulaciones"},"grupo_primario":{"codigo":"3352","nombre":"Agentes de administración tributaria"}},"funciones":[{"consecutivo":1,"texto":"Asesorar e informar a personas interesadas, empresas y organizaciones sobre las leyes, las regulaciones, los reglamentos y las disposiciones gubernamentales relativas al pago de impuestos, tasas, gravámenes fiscales, programas de seguridad social, derechos y obligaciones de los ciudadanos."},{"consecutivo":2,"texto":"Auditar declaraciones tributarias, facturas de venta, registros contables y otros documentos para determinar ingresos, exenciones, el tipo y cuantía de los impuestos, tasas y otros tipos de gravámenes que se deben pagar, cumpliendo con regulaciones y normas existentes."},{"consecutivo":3,"texto":"Investigar declaraciones de impuestos presentadas y registros, sistemas y controles contables internos de las organizaciones para asegurar el cumplimiento de las leyes y la reglamentación tributaria."},{"consecutivo":4,"texto":"Examinar sistemas contables y controles internos."},{"consecutivo":5,"texto":"Sustentar los resultados de las investigaciones, manteniendo los registros e informar sobre las medidas adoptadas en ciertos casos."},{"consecutivo":6,"texto":"Examinar y evaluar la documentación, solicitudes y otros documentos de beneficiarios calificados para determinar la legitimidad de las personas que aplican a un seguro de desempleo u otros beneficios, asegurando que cumplen con los requisitos."},{"consecutivo":7,"texto":"Determinar el tipo y cuantía de las prestaciones que los individuos tienen derecho a recibir."},{"consecutivo":8,"texto":"Mantener los registros de los usuarios y preparar informes sobre las decisiones tomadas en cuanto a la elegibilidad, las referencias, la finalización de beneficios, abuso o fraude relacionados con impuestos."},{"consecutivo":9,"texto":"Abordar a transportadores que llegan del exterior para determinar la naturaleza del cargamento y garantizar el cumplimiento de las normas tributarias."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33520.001","nombre":"Agente fiscal de aranceles"},{"codigo":"33520.002","nombre":"Examinador de impuestos / Examinadora de impuestos"},{"codigo":"33520.003","nombre":"Funcionario de administración tributaria / Funcionaria de administración tributaria"},{"codigo":"33520.004","nombre":"Funcionario de recaudo impuestos / Funcionaria de recaudo impuestos"},{"codigo":"33520.005","nombre":"Funcionario del fisco / Funcionaria del fisco"},{"codigo":"33520.006","nombre":"Inspector de hacienda / Inspectora de hacienda"},{"codigo":"33520.007","nombre":"Inspector de impuestos / Inspectora de impuestos"},{"codigo":"33520.008","nombre":"Inspector fiscal / Inspectora fiscal"},{"codigo":"33520.009","nombre":"Inspector tributario / Inspectora tributaria"},{"codigo":"33520.010","nombre":"Liquidador y revisor de impuestos / Liquidadora y revisora de impuestos"},{"codigo":"33520.011","nombre":"Oficial de impuestos"},{"codigo":"33520.012","nombre":"Oficial de impuestos especiales"},{"codigo":"33520.013","nombre":"Recaudador de impuestos / Recaudadora de impuestos"},{"codigo":"33520.014","nombre":"Recaudador de impuestos nacionales / Recaudadora de impuestos nacionales"}],"conocimientos":[{"id":"23","nombre":"Idioma extranjero"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"14","nombre":"Matemáticas"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"3","nombre":"Redacción de textos"}],"ocupaciones_afines":[{"codigo":"11120","nombre":"Directores del gobierno / Directoras del gobierno"},{"codigo":"12212","nombre":"Directores y gerentes de comercio exterior / Directoras y gerentas de comercio exterior"},{"codigo":"24111","nombre":"Contadores / Contadoras"},{"codigo":"24112","nombre":"Auditores financieros y contables / Auditoras financieras y contables"},{"codigo":"24130","nombre":"Analistas financieros / Analistas financieras"},{"codigo":"24220","nombre":"Profesionales en políticas sociales y de administración"},{"codigo":"26320","nombre":"Sociólogos, antropólogos y afines / Sociólogas, antropólogas y afines"},{"codigo":"26351","nombre":"Profesionales del trabajo social y consejeros"},{"codigo":"33131","nombre":"Asistentes contables / Asistentas contables"},{"codigo":"43110","nombre":"Auxiliares de contabilidad, costos y tesorería"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"3352","ciuo08_obs":"Denominaciones completas","cno_codigo":"1226*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Funcionarios e inspectores de servicios de seguridad social / Funcionarias e inspectoras de servicios de seguridad social', '33530', 'Administración, finanzas y derecho', 3, false, '{"codigo":"33530","nombre":"Funcionarios e inspectores de servicios de seguridad social / Funcionarias e inspectoras de servicios de seguridad social","descripcion":"Examinan las solicitudes de prestaciones de programas públicos, de ayudas financieras y de servicios para determinar si las personas solicitantes tienen derecho a prestaciones, y en su caso precisar la cuantía de las prestaciones monetarias o el tipo de servicio apropiado; administran y hacen cumplir las leyes, regulaciones relacionadas con los beneficios de seguridad social. remiten los casos excepcionales o importantes para los agentes gubernamentales de alto rango o gerentes. Se pueden desempeñar en el Gobierno, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"335","nombre":"Agentes de gobierno y profesionales del nivel medio para la aplicación de regulaciones"},"grupo_primario":{"codigo":"3353","nombre":"Funcionarios e inspectores de servicios de seguridad social"}},"funciones":[{"consecutivo":1,"texto":"Brindar asesoramiento a individuos y organizaciones sobre las leyes y disposiciones reglamentarias relativas a los programas de seguridad social, la determinación y el desembolso de los pagos, la remisión a los servicios pertinentes, derechos y obligaciones de los ciudadanos."},{"consecutivo":2,"texto":"Evaluar las solicitudes, documentación y entrevistar a los beneficiarios calificados para determinar la legitimidad, el tipo y la cuantía de las prestaciones, seguros o beneficios que los individuos tienen derecho a recibir, asegurando que cumplen con los requisitos para recibir las prestaciones o servicios."},{"consecutivo":3,"texto":"Mantener los registros de los usuarios y preparar informes sobre las decisiones tomadas en cuanto a la elegibilidad, referencias, finalización de beneficios y abuso o fraude."},{"consecutivo":4,"texto":"Orientar a empleados y empleadores sobre la interpretación de leyes y reglamentos de contratación."},{"consecutivo":5,"texto":"Revisar y conceptuar en materia de prestaciones sociales y salariales."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33530.001","nombre":"Funcionario de beneficios sociales / Funcionaria de beneficios sociales"},{"codigo":"33530.002","nombre":"Funcionario de derecho a prestaciones sociales / Funcionaria de derecho a prestaciones sociales"},{"codigo":"33530.003","nombre":"Funcionario de pensiones / Funcionaria de pensiones"},{"codigo":"33530.004","nombre":"Funcionario de prestaciones de desempleo / Funcionaria de prestaciones de desempleo"},{"codigo":"33530.005","nombre":"Funcionario de prestaciones sociales / Funcionaria de prestaciones sociales"},{"codigo":"33530.006","nombre":"Funcionario de seguridad social y reclamaciones / Funcionaria de seguridad social y reclamaciones"},{"codigo":"33530.007","nombre":"Funcionario de tramitación de solicitudes a la seguridad social / Funcionaria de tramitación de solicitudes a la seguridad social"},{"codigo":"33530.008","nombre":"Inspector de higiene y seguridad / Inspectora de higiene y seguridad"},{"codigo":"33530.009","nombre":"Inspector de pensiones / Inspectora de pensiones"},{"codigo":"33530.011","nombre":"Inspector de seguridad social / Inspectora de seguridad social"},{"codigo":"33530.012","nombre":"Inspector de trabajo / Inspectora de trabajo"}],"conocimientos":[{"id":"23","nombre":"Idioma extranjero"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"14","nombre":"Matemáticas"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"3","nombre":"Redacción de textos"}],"ocupaciones_afines":[{"codigo":"13420","nombre":"Directores y gerentes de servicios de salud / Directoras y gerentas de servicios de salud"},{"codigo":"13440","nombre":"Directores y gerentes de servicios de bienestar social, comunitario y correccional / Directoras y gerentas de servicios de bienestar social, comunitario y correccional"},{"codigo":"24220","nombre":"Profesionales en políticas sociales y de administración"},{"codigo":"26351","nombre":"Profesionales del trabajo social y consejeros"},{"codigo":"34120","nombre":"Trabajadores y asistentes sociales y comunitarios / Trabajadoras y asistentes sociales y comunitarias"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[{"sigla":"SABI","nombre":"Salud y bienestar"}],"equivalencias":[{"ciuo08_codigo":"3353","ciuo08_obs":"Denominaciones completas","cno_codigo":"1226*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Funcionarios e inspectores gubernamentales de expedición de licencias / Funcionarias e inspectoras gubernamentales de expedición de licencias', '33540', 'Administración, finanzas y derecho', 3, false, '{"codigo":"33540","nombre":"Funcionarios e inspectores gubernamentales de expedición de licencias / Funcionarias e inspectoras gubernamentales de expedición de licencias","descripcion":"Examinan las solicitudes de licencias para exportar o importar mercancías, crear empresas, construir viviendas y otras estructuras y obtener pasaportes; determinan la elegibilidad de las solicitudes de expedición de licencias o pasaportes; identifican las condiciones o restricciones específicas que deben adjuntarse a los certificados expedidos; remiten los casos excepcionales o importantes para los agentes gubernamentales de alto rango o gerentes. Desarrollan planes y recomiendan políticas para direccionar la utilización de la tierra, instalaciones físicas y servicios asociados a las áreas urbanas y rurales. Se pueden desempeñar en el gobierno, empresas de consultoría e ingeniería, como consultores privados, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"335","nombre":"Agentes de gobierno y profesionales del nivel medio para la aplicación de regulaciones"},"grupo_primario":{"codigo":"3354","nombre":"Funcionarios e inspectores gubernamentales de expedición de licencias"}},"funciones":[{"consecutivo":1,"texto":"Asesorar a las personas sobre las leyes y disposiciones relacionadas con el tipo de licencias, permisos exigidos, condiciones que los rigen, derechos y obligaciones de los ciudadanos."},{"consecutivo":2,"texto":"Estudiar y evaluar las solicitudes y los documentos pertinentes para determinar si pueden ser concedidas las licencias, pasaportes, resoluciones, permisos y las condiciones que deban imponerse."},{"consecutivo":3,"texto":"Administrar y calificar a los solicitantes las pruebas exigidas para la licencia."},{"consecutivo":4,"texto":"Aprobar y gestionar la expedición de pasaportes, licencias y permisos."},{"consecutivo":5,"texto":"Preparar la correspondencia para informar a los solicitantes sobre las decisiones que se adopten con respecto a las licencias o permisos solicitados."},{"consecutivo":6,"texto":"Planear dirigir y supervisar reconocimientos y mediciones para establecer límites legales de propiedades, parcelas o terrenos, subdivisión de fincas para el desarrollo urbano de vías, carreteras y autopistas."},{"consecutivo":7,"texto":"Coordinar con las autoridades gubernamentales, líderes cívicos, abogados y grupos de interés especial en la formulación y el desarrollo de planes urbanísticos de la comunidad."},{"consecutivo":8,"texto":"Preparar, recomendar conceptos y formular políticas y planes de desarrollo para el ordenamiento y zonificación de terrenos destinados a vías, aeropuertos, instalaciones públicas y comunitarias, parques y otros usos de la tierra."},{"consecutivo":9,"texto":"Preparar planes y políticas para la protección del medio ambiente, como preservación de la fauna, los parques naturales y la protección de cuencas hidrográficas."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33540.001","nombre":"Asistente de licencias / Asistenta de licencias"},{"codigo":"33540.002","nombre":"Curador urbanístico / Curadora urbanística"},{"codigo":"33540.003","nombre":"Funcionario de expedición de licencias de apertura de empresas / Funcionaria de expedición de licencias de apertura de empresas"},{"codigo":"33540.004","nombre":"Funcionario de expedición de licencias de importación / Funcionaria de expedición de licencias de importación"},{"codigo":"33540.005","nombre":"Funcionario de expedición de pasaportes / Funcionaria de expedición de pasaportes"},{"codigo":"33540.006","nombre":"Funcionario de expedición licencias de exportación / Funcionaria de expedición licencias de exportación"},{"codigo":"33540.007","nombre":"Funcionario de licencias / Funcionaria de licencias"},{"codigo":"33540.008","nombre":"Funcionario de licencias de construcción / Funcionaria de licencias de construcción"},{"codigo":"33540.009","nombre":"Funcionario de licencias o permisos / Funcionaria de licencias o permisos"},{"codigo":"33540.010","nombre":"Funcionario de permiso de licencia comercial / Funcionaria de permiso de licencia comercial"},{"codigo":"33540.011","nombre":"Funcionario de permisos de construcción / Funcionaria de permisos de construcción"},{"codigo":"33540.012","nombre":"Inspector de licencias / Inspectora de licencias"}],"conocimientos":[{"id":"20","nombre":"Geografía y territorio"},{"id":"1","nombre":"Gerencia y administración"},{"id":"23","nombre":"Idioma extranjero"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"14","nombre":"Matemáticas"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"2","nombre":"Escucha activa"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"3","nombre":"Redacción de textos"}],"ocupaciones_afines":[{"codigo":"13230","nombre":"Directores y gerentes de empresas de construcción / Directoras y gerentas de empresas de construcción"},{"codigo":"21420","nombre":"Ingenieros civiles / Ingenieras civiles"},{"codigo":"21610","nombre":"Arquitectos / Arquitectas"},{"codigo":"21650","nombre":"Cartógrafos e ingenieros topográficos y catastrales / Cartógrafas e ingenieras topográficas y catastrales"},{"codigo":"24220","nombre":"Profesionales en políticas sociales y de administración"},{"codigo":"31122","nombre":"Técnicos en topografía / Técnicas en topografía"},{"codigo":"31123","nombre":"Técnicos en cartografía / Técnicas en cartografía"},{"codigo":"31342","nombre":"Inspectores de oleoductos y gasoductos / Inspectoras de oleoductos y gasoductos"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"3354","ciuo08_obs":"Denominaciones completas","cno_codigo":"1226*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"2152*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Inspectores y detectives de policía / Inspectoras y detectives de policía', '33551', 'Seguridad', 3, false, '{"codigo":"33551","nombre":"Inspectores y detectives de policía / Inspectoras y detectives de policía","descripcion":"Hacen cumplir órdenes de la justicia, estatutos y códigos con soporte en decretos judiciales; hacen citaciones y embargos de propiedad. Investigan los hechos y circunstancias relativas a delitos cometidos. Se pueden desempeñar en el gobierno, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"335","nombre":"Agentes de gobierno y profesionales del nivel medio para la aplicación de regulaciones"},"grupo_primario":{"codigo":"3355","nombre":"Inspectores de policía, detectives e investigadores criminalísticos"}},"funciones":[{"consecutivo":1,"texto":"Velar porque las normas de convivencia ciudadana se cumplan."},{"consecutivo":2,"texto":"Atender y recepcionar comisorios, querellas y denuncias por extravío de documentos, perdida de bienes de valor, entre otros."},{"consecutivo":3,"texto":"Examinar los lugares donde se han cometido delitos o donde han ocurrido accidentes para obtener pruebas, buscar pistas e indicios físicos."},{"consecutivo":4,"texto":"Establecer contactos y conseguir fuentes de información sobre los delitos, planeados o cometidos, con el fin de impedirlos, identificar a los presuntos delincuentes, conocer aspectos ignorados o presuntos en relación con el lugar de los hechos o a las circunstancias."},{"consecutivo":5,"texto":"Entrevistar e interrogar a testigos y sospechosos, analizando documentos y archivos informáticos."},{"consecutivo":6,"texto":"Practicar detenciones."},{"consecutivo":7,"texto":"Sancionar personas que infrinjan las normas de convivencia ciudadana."},{"consecutivo":8,"texto":"Atender citaciones y declarar ante los tribunales de justicia y otras órdenes judiciales, e informar a sus superiores sobre las circunstancias y los resultados de las investigaciones."},{"consecutivo":9,"texto":"Hacer cumplir órdenes de desalojo o sellamiento de propiedades."},{"consecutivo":10,"texto":"Ejecutar ordenes expedidas por juzgados."},{"consecutivo":11,"texto":"Localizar y entregar bienes inmuebles para efectuar embargos y secuestros con base en mandatos judiciales."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33551.001","nombre":"Agente de investigación de policía"},{"codigo":"33551.002","nombre":"Agente detective"},{"codigo":"33551.003","nombre":"Comisario inspector de policía / Comisaria inspectora de policía"},{"codigo":"33551.004","nombre":"Detective policial"},{"codigo":"33551.005","nombre":"Inspector de policía / Inspectora de policía"},{"codigo":"33551.006","nombre":"Inspector de policía zona rural / Inspectora de policía zona rural"},{"codigo":"33551.007","nombre":"Inspector de policía zona urbana / Inspectora de policía zona urbana"},{"codigo":"33551.008","nombre":"Inspector detective / Inspectora detective"},{"codigo":"33551.009","nombre":"Investigador de policía / Investigadora de policía"},{"codigo":"33551.010","nombre":"Oficial de policía detective"},{"codigo":"33551.011","nombre":"Oficial de policía inspector"},{"codigo":"33551.012","nombre":"Policía investigador / Policía investigadora"},{"codigo":"33551.013","nombre":"Sargento detective"}],"conocimientos":[{"id":"23","nombre":"Idioma extranjero"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"27","nombre":"Seguridad pública"},{"id":"5","nombre":"Servicio al cliente"},{"id":"18","nombre":"Sicología / psicología"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"6","nombre":"Pensamiento crítico"}],"ocupaciones_afines":[{"codigo":"01100","nombre":"Oficiales de las Fuerzas Militares"},{"codigo":"33420","nombre":"Secretarios jurídicos / Secretarias jurídicas"},{"codigo":"54123","nombre":"Patrulleros y agentes de policía / Patrulleras y agentes de policía"}],"area_principal":{"sigla":"SEGU","nombre":"Seguridad"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"3355*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"6361","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Técnicos investigadores criminalísticos y judiciales / Técnicas investigadoras criminalísticas y judiciales', '33552', 'Seguridad', 2, false, '{"codigo":"33552","nombre":"Técnicos investigadores criminalísticos y judiciales / Técnicas investigadoras criminalísticas y judiciales","descripcion":"Apoyan y asisten técnica, científica y operativamente el desarrollo de actividades investigativas del área judicial, criminalística y criminal. Se ocupan en el sector justicia, de bienes y servicios de carácter privado y público e investigación privada, en materia penal, disciplinaria, administrativa, comercial, industrial, civil, laboral y en prevención de actividades delictivas, entre otros. Se pueden desempeñar en el gobierno, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"335","nombre":"Agentes de gobierno y profesionales del nivel medio para la aplicación de regulaciones"},"grupo_primario":{"codigo":"3355","nombre":"Inspectores de policía, detectives e investigadores criminalísticos"}},"funciones":[{"consecutivo":1,"texto":"Apoyar la investigación y el examen de hechos, lugares, circunstancias y el comportamiento de las personas, donde se han cometido delitos o donde han ocurrido accidentes para reunir pruebas, pistas e indicios físicos."},{"consecutivo":2,"texto":"Reunir elementos materiales probatorios (EMP) y/o evidencia física (EF) e información útil para el esclarecimiento de estos, de acuerdo con normatividad de manejo de cadena de custodia."},{"consecutivo":3,"texto":"Establecer contactos y conseguir fuentes de información sobre los delitos, planeados o cometidos, que permitan conocer aspectos ignorados o presuntos en relación con el lugar de los hechos o a las circunstancias y el comportamiento de algunas personas."},{"consecutivo":4,"texto":"Entrevistar e interrogar a testigos y sospechosos, analizando documentos y archivos informáticos."},{"consecutivo":5,"texto":"Obtener información para ser usada en litigios de las diferentes ramas del derecho o para otros propósitos ético-legales."},{"consecutivo":6,"texto":"Preparar, ejecutar y presentar informes de las actividades desarrolladas de acuerdo con los protocolos estandarizados."},{"consecutivo":7,"texto":"Atestiguar ante autoridades judiciales y/o administrativas y comunicar a sus superiores o clientes sobre el resultado de las investigaciones."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33552.001","nombre":"Perito judicial / Perita judicial"},{"codigo":"33552.002","nombre":"Técnico investigador criminalístico / Técnica investigadora criminalística"},{"codigo":"33552.003","nombre":"Técnico investigador criminalístico y judicial / Técnica investigadora criminalística y judicial"},{"codigo":"33552.004","nombre":"Técnico investigador judicial / Técnica investigadora judicial"},{"codigo":"33552.005","nombre":"Técnico investigador privado / Técnica investigadora privada"}],"conocimientos":[{"id":"23","nombre":"Idioma extranjero"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"27","nombre":"Seguridad pública"},{"id":"5","nombre":"Servicio al cliente"},{"id":"18","nombre":"Sicología / psicología"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"6","nombre":"Pensamiento crítico"}],"ocupaciones_afines":[{"codigo":"01100","nombre":"Oficiales de las Fuerzas Militares"},{"codigo":"31213","nombre":"Supervisores y analistas de producción de hidrocarburos / Supervisoras y analistas de producción de hidrocarburos"},{"codigo":"33399","nombre":"Agentes de servicios comerciales no clasificados en otras ocupaciones"},{"codigo":"33553","nombre":"Investigadores criminalísticos y judiciales / Investigadoras criminalísticas y judiciales"},{"codigo":"54123","nombre":"Patrulleros y agentes de policía / Patrulleras y agentes de policía"},{"codigo":"54141","nombre":"Supervisor de personal de vigilancia / Supervisora de personal de vigilancia"}],"area_principal":{"sigla":"SEGU","nombre":"Seguridad"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"3355*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"6368","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Investigadores criminalísticos y judiciales / Investigadoras criminalísticas y judiciales', '33553', 'Administración, finanzas y derecho', 3, false, '{"codigo":"33553","nombre":"Investigadores criminalísticos y judiciales / Investigadoras criminalísticas y judiciales","descripcion":"Apoyan científica, técnica y operativamente en el desarrollo de procesos e investigaciones que se adelantan en el área judicial y criminalística. Realizan funciones de apoyo en los tribunales o en las oficinas de abogados; prestan servicios relacionados con asuntos legales tales como contratos de seguros, transferencias de propiedad y concesión de préstamos y otras operaciones financieras; realizan investigaciones para los clientes. Se pueden desempeñar en juzgados, salas penales, fiscalías, tribunales, instituciones de seguridad pública y privada, por cuenta propia, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"335","nombre":"Agentes de gobierno y profesionales del nivel medio para la aplicación de regulaciones"},"grupo_primario":{"codigo":"3355","nombre":"Inspectores de policía, detectives e investigadores criminalísticos"}},"funciones":[{"consecutivo":1,"texto":"Investigar y examinar los hechos, los lugares, las circunstancias y el comportamiento de las personas, donde se han cometido delitos o donde han ocurrido accidentes para reunir pruebas, pistas e indicios físicos."},{"consecutivo":2,"texto":"Establecer contactos y conseguir fuentes de información sobre los delitos, planeados o cometidos, que permitan conocer aspectos ignorados o presuntos en relación con el lugar de los hechos o a las circunstancias y el comportamiento de algunas personas."},{"consecutivo":3,"texto":"Entrevistar e interrogar a testigos y sospechosos."},{"consecutivo":4,"texto":"Realizar actividades de investigación criminalística, como: dactiloscopia, lofoscopia, balística, grafología, y otras técnicas de análisis probatorio."},{"consecutivo":5,"texto":"Analizar y preparar documentos y archivos informáticos como pruebas de delitos, hechos ilícitos, transferencia de bienes raíces, título y valores u otros asuntos que requieren registro oficial, entre otros."},{"consecutivo":6,"texto":"Buscar y documentar la evidencia derivada de su actividad, procedimientos judiciales, sentencias, disposiciones legales, decisiones jurisprudenciales y demás documentos legales para preparar los casos e informar los resultados a funcionarios judiciales."},{"consecutivo":7,"texto":"Realizar análisis y estudios especializados a los elementos materia de prueba que le sean solicitados."},{"consecutivo":8,"texto":"Preparar, ejecutar y presentar informes analíticos de situaciones legales concretas, de acuerdo con estudios realizados."},{"consecutivo":9,"texto":"Entregar escritos de demanda, citaciones, órdenes y otras órdenes judiciales."},{"consecutivo":10,"texto":"Declarar ante los tribunales de justicia o informar a sus superiores sobre las circunstancias y los resultados de las investigaciones."},{"consecutivo":11,"texto":"Realizar las ampliaciones, aclaraciones, adiciones, contradicciones y objeciones a los dictámenes o informes derivados de su función."},{"consecutivo":12,"texto":"Asesorar a clientes en asuntos jurídicos."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33553.001","nombre":"Dactiloscopista"},{"codigo":"33553.002","nombre":"Investigador de criminalística / Investigadora de criminalística"},{"codigo":"33553.003","nombre":"Investigador judicial / Investigadora judicial"},{"codigo":"33553.004","nombre":"Técnico en balística forense / Técnica en balística forense"},{"codigo":"33553.005","nombre":"Técnico de criminalística / Técnica de criminalística"},{"codigo":"33553.006","nombre":"Tecnólogo en investigación criminal y judicial / Tecnóloga en investigación criminal y judicial"}],"conocimientos":[{"id":"23","nombre":"Idioma extranjero"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"27","nombre":"Seguridad pública"},{"id":"5","nombre":"Servicio al cliente"},{"id":"18","nombre":"Sicología / psicología"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"6","nombre":"Pensamiento crítico"}],"ocupaciones_afines":[{"codigo":"01100","nombre":"Oficiales de las Fuerzas Militares"},{"codigo":"26110","nombre":"Abogados / Abogadas"},{"codigo":"26199","nombre":"Profesionales en derecho no clasificados en otras ocupaciones"},{"codigo":"33420","nombre":"Secretarios jurídicos / Secretarias jurídicas"},{"codigo":"33552","nombre":"Técnicos investigadores criminalísticos y judiciales / Técnicas investigadoras criminalísticas y judiciales"},{"codigo":"34111","nombre":"Asistentes de juzgados, tribunales y afines / Asistentas de juzgados, tribunales y afines"},{"codigo":"34113","nombre":"Asistentes legales y afines / Asistentas legales y afines"},{"codigo":"54123","nombre":"Patrulleros y agentes de policía / Patrulleras y agentes de policía"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[{"sigla":"SEGU","nombre":"Seguridad"}],"equivalencias":[{"ciuo08_codigo":"3355*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"4221*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"3411*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"","cno_obs":""}]}'::jsonb),
  ('rol_cuoc', 'Agentes de gobierno y profesionales del nivel medio para la aplicación de regulaciones no clasificados en otras ocupaciones', '33590', 'Administración, finanzas y derecho', 3, false, '{"codigo":"33590","nombre":"Agentes de gobierno y profesionales del nivel medio para la aplicación de regulaciones no clasificados en otras ocupaciones","descripcion":"Esta ocupación abarca a los agentes de gobierno y profesionales del nivel medio para la aplicación de regulaciones no clasificados en otras ocupaciones del subgrupo 335: Agentes de Gobierno y profesionales del nivel medio para la aplicación de regulaciones. Por ejemplo, incluyen a aquellos que inspeccionan los precios, los salarios, los pesos y las medidas; realizan funciones concernientes a la administración y el funcionamiento de las instituciones de gobierno, congresos, ministerios y actividades exclusivas de administración pública como relaciones exteriores, asuntos territoriales y procesos electorales. Se pueden desempeñar en instituciones de gobierno, congresos, ministerios y actividades exclusivas de administración pública como relaciones exteriores, asuntos territoriales y procesos electorales, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"33","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO EN LAS FINANZAS Y LA ADMINISTRACION"},"subgrupo":{"codigo":"335","nombre":"Agentes de gobierno y profesionales del nivel medio para la aplicación de regulaciones"},"grupo_primario":{"codigo":"3359","nombre":"Agentes de gobierno y profesionales del nivel medio para la aplicación de regulaciones no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Controlar los mecanismos de regulación salarial para asegurar la aplicación de los niveles de remuneración adecuados con respecto al trabajo realizado evaluando el cumplimiento de las normas de la legislación laboral."},{"consecutivo":2,"texto":"Controlar los mecanismos de regulación de los precios y verificar el cumplimiento de normas sobre precios, evaluando la idoneidad del nivel de costos de bienes y servicios para proteger los intereses de los consumidores."},{"consecutivo":3,"texto":"Inspeccionar los establecimientos y los espacios comerciales para asegurar el uso correcto de pesos y medidas en el comercio."},{"consecutivo":4,"texto":"Examinar sistemas contables y controles internos."},{"consecutivo":5,"texto":"Registrar y documentar los hallazgos, los problemas de incumplimiento y las prácticas comerciales inadecuadas."},{"consecutivo":6,"texto":"Orientar a contribuyentes sobre la interpretación adecuada de normas, fijación y pago de impuestos."},{"consecutivo":7,"texto":"Verificar el cumplimiento de la reglamentación vigente en rifas, concursos, sorteos y similares."},{"consecutivo":8,"texto":"Planear la logística y vigilar el cumplimiento del protocolo diplomático en la visita oficial de funcionarios, políticos y dignatarios extranjeros en el país."},{"consecutivo":9,"texto":"Verificar la existencia de licencias, permisos y autorizaciones de funcionamiento determinados por la ley."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"33590.001","nombre":"Agente de servicios consulares"},{"codigo":"33590.002","nombre":"Asesor electoral / Asesora electoral"},{"codigo":"33590.003","nombre":"Asesor de servicio de extranjería / Asesora de servicio de extranjería"},{"codigo":"33590.004","nombre":"Auditor gubernamental de calidad / Auditora gubernamental de calidad"},{"codigo":"33590.005","nombre":"Delegado electoral / Delegada electoral"},{"codigo":"33590.006","nombre":"Funcionario consular / Funcionaria consular"},{"codigo":"33590.007","nombre":"Funcionario de defensa civil / Funcionaria de defensa civil"},{"codigo":"33590.008","nombre":"Funcionario de programas exclusivos de la administración pública / Funcionaria de programas exclusivos de la 