  ('rol_cuoc', 'Asistentes de juzgados, tribunales y afines / Asistentas de juzgados, tribunales y afines', '34111', 'Administración, finanzas y derecho', 3, false, '{"codigo":"34111","nombre":"Asistentes de juzgados, tribunales y afines / Asistentas de juzgados, tribunales y afines","descripcion":"Realizan funciones de apoyo en los tribunales; coordinan funciones y procedimientos administrativos, de tribunales y otras instancias judiciales; programan audiencias, atienden juramentos; expiden comparendos, citaciones, órdenes judiciales y ejercen otras funciones relacionadas. Se pueden desempeñar en juzgados, salas penales, fiscalías y tribunales, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"34","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO DE SERVICIOS JURIDICOS, SOCIALES, CULTURALES Y AFINES"},"subgrupo":{"codigo":"341","nombre":"Técnicos y profesionales del nivel medio de servicios jurídicos, sociales y religiosos"},"grupo_primario":{"codigo":"3411","nombre":"Técnicos y profesionales del nivel medio del derecho, de servicios legales y afines"}},"funciones":[{"consecutivo":1,"texto":"Coordinar servicios administrativos y establecer prioridades de trabajo del personal de juzgados o tribunales."},{"consecutivo":2,"texto":"Coordinar audiencias."},{"consecutivo":3,"texto":"Registrar y documentar procedimientos judiciales y sentencias."},{"consecutivo":4,"texto":"Preparar actas, documentos jurídicos, informes judiciales, alegatos, apelaciones, testamentos, contratos, documentos de resumen de las posiciones legales, las condiciones de concesiones, suscripciones, entre otros."},{"consecutivo":5,"texto":"Expedir comparendos, citaciones y órdenes judiciales."},{"consecutivo":6,"texto":"Redactar correspondencia y actos administrativos."},{"consecutivo":7,"texto":"Mantener el orden en las salas de audiencia y tribunales."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"34111.001","nombre":"Asistente de juzgado / Asistenta de juzgado"},{"codigo":"34111.002","nombre":"Asistente de tribunal / Asistenta de tribunal"},{"codigo":"34111.003","nombre":"Notificador / Notificadora"},{"codigo":"34111.004","nombre":"Oficial mayor de juzgado"},{"codigo":"34111.005","nombre":"Relator de tribunales / Relatora de tribunales"},{"codigo":"34111.006","nombre":"Reportero de la corte / Reportera de la corte"},{"codigo":"34111.007","nombre":"Secretario de juzgado / Secretaria de juzgado"},{"codigo":"34111.008","nombre":"Secretario de la corte / Secretaria de la corte"},{"codigo":"34111.009","nombre":"Secretario de tribunal / Secretaria de tribunal"},{"codigo":"34111.010","nombre":"Secuestre"},{"codigo":"34111.011","nombre":"Sustanciador / Sustanciadora"}],"conocimientos":[{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"22","nombre":"Educación y capacitación"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"},{"id":"18","nombre":"Sicología / psicología"},{"id":"19","nombre":"Sociología, antropología y estudios culturales"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"3","nombre":"Redacción de textos"},{"id":"10","nombre":"Relaciones interpersonales"}],"ocupaciones_afines":[{"codigo":"13499","nombre":"Directores y gerentes de servicios profesionales no clasificados en otras ocupaciones / Directoras y gerentes de servicios profesionales no clasificados en otras ocupaciones"},{"codigo":"26110","nombre":"Abogados / Abogadas"},{"codigo":"26120","nombre":"Jueces / Juezas"},{"codigo":"26199","nombre":"Profesionales en derecho no clasificados en otras ocupaciones"},{"codigo":"33431","nombre":"Asistentes administrativos / Asistentas administrativas"},{"co