  ('rol_cuoc', 'Auxiliares de tribunales', '34112', 'Administración, finanzas y derecho', 2, false, '{"codigo":"34112","nombre":"Auxiliares de tribunales","descripcion":"Realizan funciones de apoyo en tribunales y cortes judiciales, como preparar y mantener el sumario y las pruebas. Se pueden desempeñar en el poder judicial, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"34","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO DE SERVICIOS JURIDICOS, SOCIALES, CULTURALES Y AFINES"},"subgrupo":{"codigo":"341","nombre":"Técnicos y profesionales del nivel medio de servicios jurídicos, sociales y religiosos"},"grupo_primario":{"codigo":"3411","nombre":"Técnicos y profesionales del nivel medio del derecho, de servicios legales y afines"}},"funciones":[{"consecutivo":1,"texto":"Actualizar archivos de acciones tomadas por tribunales."},{"consecutivo":2,"texto":"Recolectar, asegurar, registrar y documentar la evidencia derivada de su actividad e informar los resultados a funcionarios judiciales."},{"consecutivo":3,"texto":"Preparar expedientes, actas y otros documentos."},{"consecutivo":4,"texto":"Registrar desembolsos, multas y embargos."},{"consecutivo":5,"texto":"Radicar escritos de demanda, citaciones, órdenes judiciales, reparto y fallos de primera instancia."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"34112.001","nombre":"Auxiliar judicial"},{"codigo":"34112.002","nombre":"Auxiliar de juzgado"},{"codigo":"34112.003","nombre":"Auxiliar de tribunal"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"27","nombre":"Seguridad pública"},{"id":"5","nombre":"Servicio al cliente"},{"id":"18","nombre":"Sicología / psicología"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"15","nombre":"Orientación al servicio"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"10","nombre":"Relaciones interpersonales"}],"ocupaciones_afines":[{"codigo":"13499","nombre":"Directores y gerentes de servicios profesionales no clasificados en otras ocupaciones / Directoras y gerentes de servicios profesionales no clasificados en otras ocupaciones"},{"codigo":"26110","nombre":"Abogados / Abogadas"},{"codigo":"26120","nombre":"Jueces / Juezas"},{"codigo":"26199","nombre":"Profesionales en derecho no clasificados en otras ocupaciones"},{"codigo":"33399","nombre":"Agentes de servicios comerciales no clasificados en otras ocupaciones"},{"codigo":"33420","nombre":"Secretarios jurídicos / Secretarias jurídicas"},{"codigo":"33431","nombre":"Asistentes administrativos / Asistentas administrativas"},{"codigo":"33552","nombre":"Técnicos investigadores criminalísticos y judiciales / Técnicas investigadoras criminalísticas y judiciales"},{"codigo":"34111","nombre":"Asistentes de juzgados, tribunales y afines / Asistentas de juzgados, tribunales y afines"},{"codigo":"34113","nombre":"Asistentes legales y afines / Asistentas legales y afines"},{"codigo":"34222","nombre":"Árbitros / Árbitras"},{"codigo":"44140","nombre":"Escribientes públicos y afines / Escribientes públicas y afines"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"3411*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"1343*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"4221*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Asistentes legales y afines / Asistentas legales y afines', '34113', 'Administración, finanzas y derecho', 3, false, '{"codigo":"34113","nombre":"Asistentes legales y afines / Asistentas legales y afines","descripcion":"Apoyan en la preparación de documentos legales, trámite y control de procesos ante las instancias judiciales. Esta ocupación incluye a los tinterillos quienes tienen conocimiento y experiencia en principios y procedimientos legales. Se pueden desempeñar en firmas de abogados, departamentos jurídicos en las empresas públicas o privadas, notarias, o trabajan en forma independiente, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"34","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO DE SERVICIOS JURIDICOS, SOCIALES, CULTURALES Y AFINES"},"subgrupo":{"codigo":"341","nombre":"Técnicos y profesionales del nivel medio de servicios jurídicos, sociales y religiosos"},"grupo_primario":{"codigo":"3411","nombre":"Técnicos y profesionales del nivel medio del derecho, de servicios legales y afines"}},"funciones":[{"consecutivo":1,"texto":"Investigar posibles hechos delincuenciales y casos de comportamiento ilícito, reuniendo pruebas."},{"consecutivo":2,"texto":"Revisar expedientes, registros y otros documentos como hipotecas, gravámenes, juicios, servidumbres, contratos, mapas, entre otros, con el fin de verificar las descripciones jurídicas, la titularidad de los bienes raíces, etc."},{"consecutivo":3,"texto":"Recolectar, asegurar, registrar y documentar la evidencia derivada de su actividad e informar los resultados a funcionarios judiciales."},{"consecutivo":4,"texto":"Comprobar la validez de documentos y transmitir documentos al registro de accionistas de una compañía."},{"consecutivo":5,"texto":"Realizar análisis y estudios especializados a los elementos materia de prueba que le sean solicitados."},{"consecutivo":6,"texto":"Buscar disposiciones legales, decisiones jurisprudenciales y demás documentos legales para preparar los casos."},{"consecutivo":7,"texto":"Preparar documentos legales, respuestas a citaciones judiciales, notificaciones, informes jurídicos, alegatos, apelaciones, testamentos, contratos, resúmenes de posiciones legales, condiciones de concesión de préstamos y suscripciones de seguros, transferencia de bienes raíces, títulos y valores u otros asuntos que requieren registro oficial."},{"consecutivo":8,"texto":"Realizar las ampliaciones, aclaraciones, adiciones, contradicciones y objeciones a los dictámenes o informes derivados de su función."},{"consecutivo":9,"texto":"Preparar, ejecutar y presentar informes analíticos de situaciones legales concretas, de acuerdo con los análisis o estudios realizados."},{"consecutivo":10,"texto":"Registrar documentos sobre transferencias de propiedades, títulos y valores u otros asuntos que requieren registro oficial."},{"consecutivo":11,"texto":"Llevar registros de control de procesos legales y judiciales."},{"consecutivo":12,"texto":"Asesorar a clientes en asuntos jurídicos y legales, en la redacción y el diligenciamiento de formatos y documentos."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"34113.001","nombre":"Agente de investigación privada"},{"codigo":"34113.002","nombre":"Agente judicial"},{"codigo":"34113.003","nombre":"Alguacil"},{"codigo":"34113.004","nombre":"Asistente de abogado / Asistenta de abogado"},{"codigo":"34113.005","nombre":"Asistente de bufete abogados / Asistenta de bufete abogados"},{"codigo":"34113.006","nombre":"Asistente de notaría / Asistenta de notaría"},{"codigo":"34113.007","nombre":"Asistente de seguros de pago de siniestros / Asistenta de seguros de pago de siniestros"},{"codigo":"34113.008","nombre":"Asistente de seguros y pólizas / Asistenta de seguros y pólizas"},{"codigo":"34113.009","nombre":"Asistente de traspaso / Asistenta de traspaso"},{"codigo":"34113.010