"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"15","nombre":"Orientación al servicio"},{"id":"10","nombre":"Relaciones interpersonales"}],"ocupaciones_afines":[{"codigo":"23591","nombre":"Orientadores educativos / Orientadoras educativas"},{"codigo":"24232","nombre":"Consejeros de servicios de empleo / Consejeras de servicios de empleo"},{"codigo":"26320","nombre":"Sociólogos, antropólogos y afines / Sociólogas, antropólogas y afines"},{"codigo":"26351","nombre":"Profesionales del trabajo social y consejeros"},{"codigo":"33432","nombre":"Asistentes de talento humano / Asistentas de talento humano"},{"codigo":"53220","nombre":"Trabajadores de los cuidados personales a domicilio / Trabajadoras de los cuidados personales a domicilio"}],"area_principal":{"sigla":"CISH","nombre":"Ciencias sociales y humanidades"},"areas_complementarias":[{"sigla":"SABI","nombre":"Salud y bienestar"},{"sigla":"SEPC","nombre":"Servicios Personales y a la Comunidad"}],"equivalencias":[{"ciuo08_codigo":"3253*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"1121*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"3412","ciuo08_obs":"Denominaciones completas","cno_codigo":"4152*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"4211*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"4211*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"6237*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Auxiliares laicos de las religiones / Auxiliares laicas de las religiones', '34130', 'Servicios Personales y a la Comunidad', 3, false, '{"codigo":"34130","nombre":"Auxiliares laicos de las religiones / Auxiliares laicas de las religiones","descripcion":"Ofrecen apoyo a los ministros de culto o comunidades religiosas; realizan actividades religiosas; predican y propagan las enseñanzas de una religión específica y tratan de mejorar el bienestar humano a través del poder de la fe y el asesoramiento espiritual. Se pueden desempeñar en iglesias, sinagogas, templos y otros lugares de culto o en colegios, hospitales o prisiones, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"34","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO DE SERVICIOS JURIDICOS, SOCIALES, CULTURALES Y AFINES"},"subgrupo":{"codigo":"341","nombre":"Técnicos y profesionales del nivel medio de servicios jurídicos, sociales y religiosos"},"grupo_primario":{"codigo":"3413","nombre":"Auxiliares laicos de las religiones"}},"funciones":[{"consecutivo":1,"texto":"Ayudar en los servicios de culto y ritos religiosos."},{"consecutivo":2,"texto":"Predicar y propagar las enseñanzas de una religión o tradición espiritual particular."},{"consecutivo":3,"texto":"Realizar actividades religiosas."},{"consecutivo":4,"texto":"Administrar y participar en programas para proporcionar alimentos, vestuario, asilo y refugio a los necesitados."},{"consecutivo":5,"texto":"Suministrar educación religiosa, guía espiritual y apoyo moral a miembros de una comunidad religiosa."},{"consecutivo":6,"texto":"Aconsejar a las comunidades y las personas sobre la importancia de la fe y del comportamiento sano para preservar o mejorar el bienestar humano."},{"consecutivo":7,"texto":"Apoyar el desarrollo de programas de acción social humanitaria."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"34130.001","nombre":"Acólito / Acólita"},{"codigo":"34130.002","nombre":"Ayudante de culto"},{"codigo":"34130.003","nombre":"Catequista o evangelizador / Catequista o evangelizadora"},{"codigo":"34130.004","nombre":"Curandero de sugestión / Curandera de sugestión"},{"codigo":"34130.005","nombre":"Curandero religioso / Curandera religiosa"},{"codigo":"34130.006","nombre":"Evangelizador / Evangelizadora"},{"codigo":"34130.007","nombre":"Fraile"},{"codigo":"34130.008","nombre":"Hermano religioso / Hermana religiosa"},{"codigo":"34130.010","nombre":"Monje / Monja"},{"codigo":"34130.011","nombre":"Novicio / Novicia"},{"codigo":"34130.012","nombre":"Predicador laico / Predicadora laica"},{"codigo":"34130.013","nombre":"Predicador seglar / Predicadora seglar"},{"codigo":"34130.014","nombre":"Religioso / Religiosa"},{"codigo":"34130.015","nombre":"Salvacionista"},{"codigo":"34130.016","nombre":"Sanador de fe / Sanadora de fe"},{"codigo":"34130.017","nombre":"Seminarista"},{"codigo":"34130.019","nombre":"Trabajador laico / Trabajadora laica"},{"codigo":"34130.020","nombre":"Trabajador religioso / Trabajadora religiosa"}],"conocimientos":[{"id":"26","nombre":"Filosofía y ética"},{"id":"99","nombre":"Religión y teología"},{"id":"5","nombre":"Servicio al cliente"},{"id":"18","nombre":"Sicología / psicología"},{"id":"93","nombre":"Trabajo social"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"33","nombre":"Liderazgo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"34","nombre":"Trabajo bajo presión"}],"ocupaciones_afines":[{"codigo":"26360","nombre":"Profesionales religiosos y ministros de culto / Profesionales religiosas y ministras de culto"},{"codigo":"32301","nombre":"Técnicos y profesionales del nivel medio en medicina alternativa / Técnicas y profesionales del nivel medio en medicina alternativa"}],"area_p