  ('rol_cuoc', 'Atletas y deportistas', '34210', 'Actividades físicas, deportivas y recreativas', 3, false, '{"codigo":"34210","nombre":"Atletas y deportistas","descripcion":"Participan en eventos deportivos, entrenan y compiten, ya sea individualmente o como miembro de un equipo. Se pueden desempeñar en equipos profesionales en empresas estatales o privadas, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"34","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO DE SERVICIOS JURIDICOS, SOCIALES, CULTURALES Y AFINES"},"subgrupo":{"codigo":"342","nombre":"Entrenadores de deportes y aptitud física"},"grupo_primario":{"codigo":"3421","nombre":"Atletas y deportistas"}},"funciones":[{"consecutivo":1,"texto":"Realizar prácticas deportivas regulares y en sesiones de entrenamiento grupal e individual, bajo la dirección de un entrenador para mantener el estado físico y desarrollar el nivel de habilidad requerido para competir."},{"consecutivo":2,"texto":"Participar en eventos y competencias deportivas, de liga, locales, regionales, nacionales o internacionales."},{"consecutivo":3,"texto":"Determinar las estrategias, en consulta con los entrenadores."},{"consecutivo":4,"texto":"Evaluar el desempeño propio y de los demás competidores, así como las condiciones desarrolladas en las pruebas, después de la competencia deportiva para identificar fortalezas y debilidades."},{"consecutivo":5,"texto":"Brindar espectáculo deportivo en el marco de eventos deportivos y demás escenarios públicos y/o privados."},{"consecutivo":6,"texto":"Realizar actividades de promoción deportiva y participar en entrevistas con los medios de comunicación."},{"consecutivo":7,"texto":"Cumplir con las normas y reglamentos relacionados con un deporte específico."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"34210.001","nombre":"Ajedrecista"},{"codigo":"34210.