  ('rol_cuoc', 'Entrenadores y preparadores físicos / Entrenadoras y preparadoras físicas', '34221', 'Actividades físicas, deportivas y recreativas', 3, false, '{"codigo":"34221","nombre":"Entrenadores y preparadores físicos / Entrenadoras y preparadoras físicas","descripcion":"Trabajan con deportistas profesionales y aficionados para mejorar su rendimiento y fomentar una mayor participación en el deporte. Preparan y entrenan deportistas individualmente o en equipos para participar en eventos competitivos; instruyen y dirigen personas o grupos en sesiones de acondicionamiento físico, prácticas deportivas o recreativas, y en estrategias de promoción de salud y bienestar. Se pueden desempeñar en organizaciones deportivas, equipos profesionales y aficionados, clubes, gimnasios y establecimientos similares, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"34","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO DE SERVICIOS JURIDICOS, SOCIALES, CULTURALES Y AFINES"},"subgrupo":{"codigo":"342","nombre":"Entrenadores de deportes y aptitud física"},"grupo_primario":{"codigo":"3422","nombre":"Entrenadores, instructores y árbitros de actividades deportivas"}},"funciones":[{"consecutivo":1,"texto":"Identificar y reclutar deportistas promisorios para equipos deportivos profesionales."},{"consecutivo":2,"texto":"Identificar las fortalezas y debilidades de los atletas, jugadores o equipos."},{"consecutivo":3,"texto":"Analizar y evaluar el rendimiento y la actuación físico-atlética, estableciendo el perfil cardiovascular, osteomuscular y factores de riesgo de los deportistas para modificar los programas de entrenamiento."},{"consecutivo":4,"texto":"Planear y desarrollar programas, sesiones de práctica y entrenamiento deportivos, recreacionales, atléticos o de acondicionamiento físico de acuerdo con necesidades individuales o de grupo."},{"consecutivo":5,"texto":"Desarrollar, planificar y coordinar programas y calendarios de competencias y pruebas."},{"consecutivo":6,"texto":"Motivar y preparar a los deportistas, atletas y equipos para competir en eventos o juegos."},{"consecutivo":7,"texto":"Formular estrategias de competencia, desarrollar planes de juego, dirigir a los deportistas, atletas y jugadores durante los partidos o eventos deportivos."},{"consecutivo":8,"texto":"Fomentar y propiciar el desarrollo de las habilidades y destrezas físico-atléticas."},{"consecutivo":9,"texto":"Supervisar y analizar la técnica y el rendimiento, determinar las mejoras para el futuro."},{"consecutivo":10,"texto":"Proveer información sobre hábitos convenientes para llevar un estilo de vida saludable."},{"consecutivo":11,"texto":"Conducir actividades terapéuticas, recreacionales o atléticas."},{"consecutivo":12,"texto":"Monitorear actividades recreacionales o deportivas para garantizar seguridad o atender las emergencias en caso necesario."},{"consecutivo":13,"texto":"Reportar valoraciones de reconocimiento y hacer recomendaciones."},{"consecutivo":14,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"34221.001","nombre":"Entrenador de baloncesto / Entrenadora de baloncesto"},{"codigo":"34221.002","nombre":"Entrenador de actividad física / Entrenadora de actividad física"},{"codigo":"34221.003","nombre":"Entrenador de artes marciales / Entrenadora de artes marciales"},{"codigo":"34221.004","nombre":"Entrenador de atletismo / Entrenadora de atletismo"},{"codigo":"34221.005","nombre":"Entrenador de básquetbol / Entrenadora de básquetbol"},{"codigo":"34221.006","nombre":"Entrenador de béisbol / Entrenadora de béisbol"},{"codigo":"34221.007","nombre":"Entrenador de boxeo / Entrenadora de boxeo"},{"codigo":"34221.008","nombre":"Entrenador de buceo / Entrenadora de buceo"},{"codigo":"34221.009","nombre":"Entrenador de fútbol / Entrenadora de fútbol"},{"codigo":"34221.010","nombre":"Entrenador de fútbol aficionado en clubes de liga / Ent