  ('rol_cuoc', 'Recreadores / Recreadoras', '34232', 'Actividades físicas, deportivas y recreativas', 2, false, '{"codigo":"34232","nombre":"Recreadores / Recreadoras","descripcion":"Organizan y dirigen excursiones, actividades recreativas y de integración. Se pueden desempeñar en clubes deportivos, centros vacacionales y empresas que proveen servicios de recreación y entretenimiento, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"34","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO DE SERVICIOS JURIDICOS, SOCIALES, CULTURALES Y AFINES"},"subgrupo":{"codigo":"342","nombre":"Entrenadores de deportes y aptitud física"},"grupo_primario":{"codigo":"3423","nombre":"Instructores de educación física y actividades recreativas"}},"funciones":[{"consecutivo":1,"texto":"Supervisar las actividades recreativas para garantizar la seguridad de los participantes y suministrar primeros auxilios en situaciones de emergencia."},{"consecutivo":2,"texto":"Planear y coordinar actividades, itinerarios, medios de transporte y alojamiento de integración y recreativas."},{"consecutivo":3,"texto":"Demostrar e instruir sobre las actividades a realizar."},{"consecutivo":4,"texto":"Reunir el equipo y víveres necesarios como alimentos, herramientas, carpas y otros elementos de campamento."},{"consecutivo":5,"texto":"Explicar y hacer cumplir los procedimientos y las normas de seguridad."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"34232.001","nombre":"Animador de grupo / Animadora de grupo"},{"codigo":"34232.002","nombre":"Animador de recreación y deporte / Animadora de recreación y deporte"},{"codigo":"34232.003","nombre":"Guía de actividades al aire libre"},{"codigo":"34232.004","nombre":"Líder de programas de recreación / Lideresa de programas de recreación"},{"codigo":"34232.005","nombre":"Recreacionista"},{"codigo":"34232.006","nombre"