  ('rol_cuoc', 'Fotógrafos / Fotógrafas', '34310', 'Audiovisuales, Artes Escénicas y Música', 3, false, '{"codigo":"34310","nombre":"Fotógrafos / Fotógrafas","descripcion":"Manejan cámaras fotográficas para registrar imágenes con propósitos científicos, industriales, publicitarios, comerciales, artísticos, culturales, cinematográficos o corporativos con técnicas, tecnologías, narrativas y de lenguaje, entre otros. Se pueden desempeñar en estudios fotográficos, periódicos, revistas, agencias de publicidad y de comunicación digital, producciones audiovisuales, de forma independiente, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"34","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO DE SERVICIOS JURIDICOS, SOCIALES, CULTURALES Y AFINES"},"subgrupo":{"codigo":"343","nombre":"Técnicos y profesionales del nivel medio en actividades culturales, artísticas y culinarias"},"grupo_primario":{"codigo":"3431","nombre":"Fotógrafos"}},"funciones":[{"consecutivo":1,"texto":"Decidir sobre el tipo de cámara, película, iluminación y accesorios de fondo a ser utilizados."},{"consecutivo":2,"texto":"Realizar los ajustes técnicos al equipo y registrar imágenes de acuerdo con especificaciones del proyecto audiovisual."},{"consecutivo":3,"texto":"Tomar fotografías de grupos y personas, con fines publicitarios, comerciales, industriales o científicos y para ilustrar crónicas y artículos en periódicos, revistas y otras publicaciones."},{"consecutivo":4,"texto":"Hacer reparaciones de emergencia en el equipo."},{"consecutivo":5,"texto":"Adaptar y editar imágenes fotográficas existentes para crear nuevas imágenes digitalizadas para ser incluidas en productos multimedia, utilizando las herramientas necesarias."},{"consecutivo":6,"texto":"Realizar el revelado y retoque digital de la imagen en la etapa de postproducción."},{"consecutivo":7,"texto":"Operar los equipos audiovisuales, de reprografía, de transferencia de imágenes fotográficas a los archivos digitales, de creación de efectos visuales deseados."},{"consecutivo":8,"texto":"Entregar el producto final de acuerdo con el flujo de trabajo del tiempo y gestionar propuestas y proyectos fotográficos."},{"consecutivo":9,"texto":"Ayudar en la disposición de equipos de iluminación y exhibición."},{"consecutivo":10,"texto":"Montar y preparar exposiciones de fotografía."},{"consecutivo":11,"texto":"Aportar creativamente al lenguaje visual y corregir la imagen e iluminación de espacios escenográficos y en la producción, según técnicas y requerimientos del proyecto creativo."},{"consecutivo":12,"texto":"Apoyar el diseño de escenarios de acuerdo con técnicas y normativa."},{"consecutivo":13,"texto":"Capturar imágenes fijas durante el proceso de rodaje para efectos de promoción en medios digitales e impresos."},{"consecutivo":14,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"34310.001","nombre":"Fotógrafo / Fotógrafa"},{"codigo":"34310.002","nombre":"Fotógrafo aéreo / Fotógrafa aérea"},{"codigo":"34310.003","nombre":"Fotógrafo artístico / Fotógrafa artística"},{"codigo":"34310.004","nombre":"Fotógrafo científico / Fotógrafa científica"},{"codigo":"34310.005","nombre":"Fotógrafo comercial / Fotógrafa comercial"},{"codigo":"34310.006","nombre":"Fotógrafo de arquitectura / Fotógrafa de arquitectura"},{"codigo":"34310.007","nombre":"Fotógrafo de foto fija / Fotógrafa de foto fija"},{"codigo":"34310.008","nombre":"Fotógrafo de ilustración comercial / Fotógrafa de ilustración comercial"},{"codigo":"34310.009","nombre":"Fotógrafo de microfotografía / Fotógrafa de microfotografía"},{"codigo":"34310.010","nombre":"Fotógrafo de modas / Fotógrafa de modas"},{"codigo":"34310.011","nombre":"Fotógrafo de noticias / Fotógrafa de noticias"},{"codigo":"34310.012","nombre":"Fotógrafo de patrimonio cultural mueble / Fotógrafa de patrimonio cultural mueble"},{"codigo":"34310.013","nombre":"Fotógraf