  ('rol_cuoc', 'Decoradores de interiores / Decoradoras de interiores', '34320', 'Comercio, mercadeo y publicidad', 3, false, '{"codigo":"34320","nombre":"Decoradores de interiores / Decoradoras de interiores","descripcion":"Decoran interiores de edificios comerciales, industriales, públicos, de comercio al por menor y residenciales para mejorar los ambientes y ajustarlos a un propósito, teniendo en cuenta diversos factores. Se pueden desempeñar en firmas de diseño interior, de escenarios y espectáculos, servicios comerciales, establecimientos de venta al por menor, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"34","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO DE SERVICIOS JURIDICOS, SOCIALES, CULTURALES Y AFINES"},"subgrupo":{"codigo":"343","nombre":"Técnicos y profesionales del nivel medio en actividades culturales, artísticas y culinarias"},"grupo_primario":{"codigo":"3432","nombre":"Decoradores de interiores"}},"funciones":[{"consecutivo":1,"texto":"Consultar con grupos de interés con el fin de determinar necesidades, preferencias y propósitos para negociar la propuesta de decoración o exhibición, objetivos y limitaciones del espacio del proyecto."},{"consecutivo":2,"texto":"Investigar, seleccionar, especificar y recomendar los requerimientos espaciales, los materiales, los acabados, el mobiliario y los productos funcionales, eficientes, de seguridad y estéticos para el espacio."},{"consecutivo":3,"texto":"Preparar bocetos, diagramas, ilustraciones y planos en formato de animación y modelado para comunicar los conceptos de decoración y exhibición."},{"consecutivo":4,"texto":"Planear y desarrollar exhibiciones en almacenes, vitrinas y espacios menores."},{"consecutivo":5,"texto":"Apoyar el desarrollo de proyectos de adecuaciones de interiores, salas de exhibición y escenarios teniendo en cuenta la selección de estilos, colores, cubiertas de pisos y paredes, disposición de muros, muebles, divisiones, exhibidores, iluminación y otros detalles y accesorios para espectáculos, servicios y para promover productos."},{"consecutivo":6,"texto":"Detallar y documentar la propuesta de decoración seleccionada para la construcción."},{"consecutivo":7,"texto":"Estimar costos y materiales requeridos."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"34320.001","nombre":"Analista de exhibición"},{"codigo":"34320.002","nombre":"Decorador de espacios publicitarios / Decoradora de espacios publicitarios"},{"codigo":"34320.003","nombre":"Decorador de eventos / Decoradora de eventos"},{"codigo":"34320.004","nombre":"Decorador de exposiciones / Decoradora de exposiciones"},{"codigo":"34320.005","nombre":"Decorador de interiores / Decoradora de interiores"},{"codigo":"34320.006","nombre":"Decorador de mostrador / Decoradora de mostrador"},{"codigo":"34320.007","nombre":"Decorador de set de filmación / Decoradora de set de filmación"},{"codigo":"34320.008","nombre":"Decorador de vitrinas / Decoradora de vitrinas"},{"codigo":"34320.009","nombre":"Escaparatista"},{"codigo":"34320.010","nombre":"Escaparatista decorador / Escaparatista decoradora"},{"codigo":"34320.011","nombre":"Técnico decorador de escenarios de teatro / Técnica decoradora de escenarios de teatro"},{"codigo":"34320.012","nombre":"Técnico decorador de interiores / Técnica decoradora de interiores"},{"codigo":"34320.013","nombre":"Técnico decorador de stands / Técnica decoradora de stands"},{"codigo":"34320.014","nombre":"Técnico en decoración / Técnica en decoración"},{"codigo":"34320.015","nombre":"Técnico en decoración de exhibición / Técnica en decoración de exhibición"},{"codigo":"34320.016","nombre":"Técnico en decoración de interiores / Técnica en decoración de interiores"},{"codigo":"34320.017","nombre":"Técnico en decoración de teatro / Técnica en decoración de teatro"},{"codigo":"34320.018","nombre":"Técnico en decoraci