  ('rol_cuoc', 'Ocupaciones técnicas relacionadas con museos y galerías', '34331', 'Artes visuales, plásticas y del patrimonio cultural', 3, false, '{"codigo":"34331","nombre":"Ocupaciones técnicas relacionadas con museos y galerías","descripcion":"Asisten a los curadores, museólogos, museógrafos y conservadores-restauradores en la clasificación y catalogación de las piezas en museos y galerías, la organización y el montaje de exposiciones, el mantenimiento y el apoyo en acciones de conservación preventiva en colecciones de museos y galerías. Se pueden desempeñar en museos y galerías. Los taxidermistas se pueden desempeñar en comercios al por menor, o trabajar en forma independiente, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"34","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO DE SERVICIOS JURIDICOS, SOCIALES, CULTURALES Y AFINES"},"subgrupo":{"codigo":"343","nombre":"Técnicos y profesionales del nivel medio en actividades culturales, artísticas y culinarias"},"grupo_primario":{"codigo":"3433","nombre":"Técnicos en galerías de arte, museos y bibliotecas"}},"funciones":[{"consecutivo":1,"texto":"Planear y preparar exhibiciones, dioramas y piezas de valor artístico para exhibición, eventos, preservación y embarque."},{"consecutivo":2,"texto":"Montar y preparar objetos para exposiciones."},{"consecutivo":3,"texto":"Recibir, enviar, embalar y desembalar exposiciones."},{"consecutivo":4,"texto":"Apoyar en la conservación de piezas bajo la dirección de un funcionario encargado de la conservación."},{"consecutivo":5,"texto":"Preparar y disecar animales con propósitos científicos, de conservación o exhibición."},{"consecutivo":6,"texto":"Clasificar y asignar códigos de registro a las piezas, supervisar el control de inventario y catalogar obras impresas y grabadas."},{"consecutivo":7,"texto":"Apoyar en la búsqueda, el manejo y el almacenamiento de piezas."},{"consecutivo":8,"texto":"Ingresar datos en bases informáticas y editar los registros."},{"consecutivo":9,"texto":"Realizar acciones de mediación e interpretación del patrimonio cultural dirigidos a diversos tipos de públicos, en entidades museales y afines."},{"consecutivo":10,"texto":"Apoyar la programación académica y cultural, su información y divulgación, así como la atención a visitantes y el desarrollo de charlas introductorias, visitas, talleres y actividades paralelas en entidades museales y afines."},{"consecutivo":11,"texto":"Aportar desde la mediación educativa y cultural, para que la experiencia del ciudadano con las estrategias de la institución sea coherente con la misión del museo y sea significativa para quien la vive."},{"consecutivo":12,"texto":"Brindar asistencia pedagógica en el desarrollo de proyectos museográficos, el diseño de contenidos y material didáctico y pedagógico."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"34331.001","nombre":"Asistente curatorial / Asistenta curatorial"},{"codigo":"34331.002","nombre":"Auxiliar de restauración y conservación"},{"codigo":"34331.003","nombre":"Mediador de museo / Mediadora de museo"},{"codigo":"34331.005","nombre":"Montajista de museo"},{"codigo":"34331.006","nombre":"Tallerista de museo"},{"codigo":"34331.007","nombre":"Taxidermista"},{"codigo":"34331.008","nombre":"Técnico curatorial / Técnica curatorial"},{"codigo":"34331.009","nombre":"Técnico de galería / Técnica de galería"},{"codigo":"34331.010","nombre":"Técnico de galería de arte / Técnica de galería de arte"},{"codigo":"34331.011","nombre":"Técnico de museos / Técnica de museos"},{"codigo":"34331.012","nombre":"Técnico en proyección y manipulación de equipos para museos, galerías y planetarios / Técnica en proyección y manipulación de equipos para museos, galerías y planetarios"}],"conocimientos":[{"id":"24","nombre":"Bellas artes"},{"id":"22","nombre":"Educación y capacitación"},{"id":"25","nombre":"Historia y arqueología"},{"id":"38","nombre":"Mantenimiento"},{"id":"43","nombre":"Patrimonio cultural"},{"id":"44","nombre":"Patrimonio natural"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"15","nombre":"Orientación al servicio"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"3","nombre":"Redacción de textos"},{"id":"38","nombre":"Seguir instrucciones"}],"ocupaciones_afines":[{"codigo":"26215","nombre":"Restauradores y conservadores de patrimonio cultural mueble / Restauradoras y conservadoras de patrimonio cultural mueble"},{"codigo":"26216","nombre":"Restauradores y conservadores de patrimonio cultural construido / Restauradoras y conservadoras de patrimonio cultural construido"}],"area_principal":{"sigla":"AVPP","nombre":"Artes visuales, plásticas y del patrimonio cultural"},"areas_complementarias":[{"sigla":"AVPP","nombre":"Artes visuales, plásticas y del patrimonio cultural"},{"sigla":"AVEM","nombre":"Audiovisuales, Artes Escénicas y Música"}],"equivalencias":[{"ciuo08_codigo":"3433*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"5211*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Técnicos en biblioteca / Técnicas en biblioteca', '34332', 'Artes visuales, plásticas y del patrimonio cultural', 3, false, '{"codigo":"34332","nombre":"Técnicos en biblioteca / Técnicas en biblioteca","descripcion":"Asisten y orientan a los usuarios en el acceso a los recursos de la biblioteca y las unidades de información de acuerdo con sus necesidades, apoyan a los bibliotecólogos en la catalogación de nuevas adquisiciones y búsqueda de referencias; ayudan a los bibliotecarios a organizar, operar y poner en práctica sistemas de gestión de materiales y archivos grabados. Se pueden desempeñar en bibliotecas, unidades de información, centros de documentación y otros establecimientos con servicios bibliotecarios, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"34","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO DE SERVICIOS JURIDICOS, SOCIALES, CULTURALES Y AFINES"},"subgrupo":{"codigo":"343","nombre":"Técnicos y profesionales del nivel medio en actividades culturales, artísticas y culinarias"},"grupo_primario":{"codigo":"3433","nombre":"Técnicos en galerías de arte, museos y bibliotecas"}},"funciones":[{"consecutivo":1,"texto":"Solicitar pedidos de nuevas obras y catalogar nuevos libros o materiales de biblioteca, bajo la dirección de bibliotecólogos."},{"consecutivo":2,"texto":"Ingresar y editar registros en bases de datos informáticas."},{"consecutivo":3,"texto":"Apoyar y orientar a los usuarios de bibliotecas en la búsqueda y el acceso a libros, películas, fotografías, mapas, documentos y otros materiales de biblioteca."},{"consecutivo":4,"texto":"Realizar búsquedas de referencia manual o en línea hacer préstamos interbibliotecarios para los usuarios."},{"consecutivo":5,"texto":"Apoyar a los archivistas en el registro y los documentos históricos para su almacenamiento seguro."},{"consecutivo":6,"texto":"Apoyar la ejecución de los programas y eventos culturales de formación a usuarios y a la lectura."},{"consecutivo":7,"texto":"Operar los equipos audiovisuales y de reprografía."},{"consecutivo":8,"texto":"Poner en circulación, recibir libros y otros materiales."},{"consecutivo":9,"texto":"Asistir en acciones de conservación y conservación preventiva a bibliotecarios y conservadores-restauradores de patrimonio cultural mueble."},{"consecutivo":10,"texto":"Promover la cultura digital en el acceso a información."},{"consecutivo":11,"texto":"Implementar los procesos de innovación en la prestación de los servicios bibliotecarios y acceso a la información."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"34332.001","nombre":"Asistente de referencia de biblioteca / Asistenta de referencia de biblioteca"},{"codigo":"34332.003","nombre":"Bibliotecario / Bibliotecaria"},{"codigo":"34332.004","nombre":"Bibliotecario en música / Bibliotecaria en música"},{"codigo":"34332.005","nombre":"Gestor bibliotecario / Gestora bibliotecaria"},{"codigo":"34332.006","nombre":"Técnico de biblioteca / Técnica de biblioteca"},{"codigo":"34332.007","nombre":"Mediador social y cultural / Mediadora social y cultural"},{"codigo":"34332.008","nombre":"Mediador de cultura informacional / Mediadora de cultura informacional"},{"codigo":"34332.009","nombre":"Mediador de promoción de lectura / Mediadora de promoción de lectura"},{"codigo":"34332.010","nombre":"Técnico en conservación del patrimonio documental / Técnica en conservación del patrimonio documental"}],"conocimientos":[{"id":"56","nombre":"Bibliotecología, información y archivología"},{"id":"22","nombre":"Educación y capacitación"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"43","nombre":"Patrimonio cultural"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"15","nombre":"Orientación al servicio"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"38","nombre":"Seguir instrucciones"}],"ocupaciones_afines":[{"codigo":"13491","nombre":"Directores y gerentes de archivo, biblioteca, museo y galería de arte / Directoras y gerentas de archivo, biblioteca, museo y galería de arte"},{"codigo":"26220","nombre":"Bibliotecólogos, documentalistas y afines / Bibliotecólogas, documentalistas y afines"},{"codigo":"44110","nombre":"Empleados auxiliares de bibliotecas / Empleadas auxiliares de bibliotecas"}],"area_principal":{"sigla":"AVPP","nombre":"Artes visuales, plásticas y del patrimonio cultural"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"3433*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"4211*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"4411*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"5212*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Técnicos en promoción y animación a la lectura y la escritura / Técnicas en promoción y animación a la lectura y la escritura', '34333', 'Artes visuales, plásticas y del patrimonio cultural', 3, false, '{"codigo":"34333","nombre":"Técnicos en promoción y animación a la lectura y la escritura / Técnicas en promoción y animación a la lectura y la escritura","descripcion":"Desarrollan y asesoran actividades de promoción y animación a la lectura y la escritura, tanto de manera individual como grupal. Desarrollan estrategias pedagógicas innovadoras, apoyadas por las tecnologías de la información y la comunicación, y tienen dominio de la lectura en voz alta. Se pueden desempeñar en bibliotecas, centros educativos, librerías, espacios culturales, organizaciones sin fines de lucro, cajas de compensación, y proyectos comunitarios, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"34","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO DE SERVICIOS JURIDICOS, SOCIALES, CULTURALES Y AFINES"},"subgrupo":{"codigo":"343","nombre":"Técnicos y profesionales del nivel medio en actividades culturales, artísticas y culinarias"},"grupo_primario":{"codigo":"3433","nombre":"Técnicos en galerías de arte, museos y bibliotecas"}},"funciones":[{"consecutivo":1,"texto":"Planear y ejecutar actividades de promoción de lectura y escritura en cooperación con diversas instituciones."},{"consecutivo":2,"texto":"Seleccionar, preparar o adaptar materiales didácticos apropiados a la promoción y la motivación de lectura y escritura."},{"consecutivo":3,"texto":"Ejecutar y apoyar los procesos relacionados con la promoción y la animación a la lectura y la escritura, de acuerdo con los planes y los programas establecidos."},{"consecutivo":4,"texto":"Identificar las necesidades del lector para asesorar, recomendar y orientar la propuesta editorial."},{"consecutivo":5,"texto":"Elaborar, ejecutar y apoyar planes, programas, proyectos, eventos y campañas para promover y motivar la lectura y la escritura."},{"consecutivo":6,"texto":"Alimentar bases de datos para la creación, la actualización, la consulta y la recuperación de información."},{"consecutivo":7,"texto":"Manejar y aplicar teorías y modelos pedagógicos."},{"consecutivo":8,"texto":"Manejar las fuentes bibliográficas electrónicas y documentales."},{"consecutivo":9,"texto":"Realizar el alistamiento y la disposición de los recursos de información, los materiales didácticos, el mobiliario y los insumos necesarios para el desarrollo de las actividades de promoción y animación a la lectura y la escritura."},{"consecutivo":10,"texto":"Promover la cultura digital en el acceso a información para la lectura y la escritura."},{"consecutivo":11,"texto":"Generar y promover redes culturales alrededor de la lectura."},{"consecutivo":12,"texto":"Realizar revisiones periódicas de editoriales para mantener su propuesta editorial actualizada."},{"consecutivo":13,"texto":"Mantener relaciones activas y permanentes con proveedores y distribuidores con los agentes editoriales."},{"consecutivo":14,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"34333.001","nombre":"Animador a la lectura / Animadora a la lectura"},{"codigo":"34333.002","nombre":"Gestor cultural de fomento a la lectura / Gestora cultural de fomento a la lectura"},{"codigo":"34333.003","nombre":"Mediador de lectura / Mediadora de lectura"},{"codigo":"34333.004","nombre":"Promotor de escritura / Promotora de escritura"},{"codigo":"34333.005","nombre":"Promotor de lectura / Promotora de lectura"},{"codigo":"34333.006","nombre":"Promotor de oralidad / Promotora de oralidad"},{"codigo":"34333.007","nombre":"Promotor y animador a la lectura y la escritura / Promotora y animadora a la lectura y la escritura"},{"codigo":"34333.008","nombre":"Mediador de fomento a la escritura / Mediadora de fomento a la escritura"},{"codigo":"34333.009","nombre":"Mediador de fomento a la lectura / Mediadora de fomento a la lectura"},{"codigo":"34333.010","nombre":"Librero / Librera"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"3","nombre":"Redacción de textos"}],"ocupaciones_afines":[{"codigo":"26220","nombre":"Bibliotecólogos, documentalistas y afines / Bibliotecólogas, documentalistas y afines"},{"codigo":"34331","nombre":"Ocupaciones técnicas relacionadas con museos y galerías"},{"codigo":"34332","nombre":"Técnicos en biblioteca / Técnicas en biblioteca"},{"codigo":"44110","nombre":"Empleados auxiliares de bibliotecas / Empleadas auxiliares de bibliotecas"}],"area_principal":{"sigla":"AVPP","nombre":"Artes visuales, plásticas y del patrimonio cultural"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"3433*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"5213","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Chefs', '34340', 'Turismo, hotelería y gastronomía', 3, false, '{"codigo":"34340","nombre":"Chefs","descripcion":"Diseñan menús, crean platos, supervisan dirigen y coordinan la planificación, organización, preparación y la cocción de las comidas en los hoteles, restaurantes y otros establecimientos que expenden comidas, así como a bordo de buques, trenes de pasajeros y en hogares. Se pueden desempeñar en restaurantes, hospitales, hoteles, clubes, centros educativos, comunidades religiosas, empresas proveedoras de servicio de alimentos, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"34","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO DE SERVICIOS JURIDICOS, SOCIALES, CULTURALES Y AFINES"},"subgrupo":{"codigo":"343","nombre":"Técnicos y profesionales del nivel medio en actividades culturales, artísticas y culinarias"},"grupo_primario":{"codigo":"3434","nombre":"Chefs"}},"funciones":[{"consecutivo":1,"texto":"Planificar y elaborar recetas y menús, estimar los costos de los alimentos y la mano de obra y tramitar los pedidos de suministros de alimentos."},{"consecutivo":2,"texto":"Supervisar y coordinar las actividades de los cocineros para la preparación y la cocción de alimentos en restaurantes, hoteles, hospitales, clubes u otros establecimientos con servicio de alimentos."},{"consecutivo":3,"texto":"Preparar, condimentar y cocinar alimentos especiales y platos complejos."},{"consecutivo":4,"texto":"Supervisar el cumplimiento de estándares de calidad para alimentos, preparación, platos y servicio."},{"consecutivo":5,"texto":"Evaluar, conjuntamente con los directivos de sus entidades, los dietistas y el personal de cocina y de servicio, las cuestiones relativas a la preparación de los alimentos."},{"consecutivo":6,"texto":"Escoger la modalidad de presentación del plato, crear formas o estructuras decorativas."},{"consecutivo":7,"texto":"Instruir a los cocineros y otros trabajadores en la preparación, la guarnición, la cocción, el aderezo y la presentación de los alimentos."},{"consecutivo":8,"texto":"Inspeccionar los suministros, los equipos y las áreas de trabajo para asegurar que se cumpla con las normas establecidas."},{"consecutivo":9,"texto":"Explicar y hacer cumplir las normas de higiene y seguridad alimentaria."},{"consecutivo":10,"texto":"Participar en la contratación del personal de cocina y supervisar su desempeño."},{"consecutivo":11,"texto":"Planear menús y requisiciones de alimentos e implementos de cocina."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"34340.001","nombre":"Chef"},{"codigo":"34340.002","nombre":"Chef de alta cocina"},{"codigo":"34340.003","nombre":"Chef de cocina"},{"codigo":"34340.004","nombre":"Chef ejecutivo / Chef ejecutiva"},{"codigo":"34340.005","nombre":"Chef jefe / Chef jefa"},{"codigo":"34340.006","nombre":"Chef pastelero / Chef pastelera"},{"codigo":"34340.007","nombre":"Chef salsero / Chef salsera"},{"codigo":"34340.008","nombre":"Coordinador de autoservicio de alimentos y bebidas / Coordinadora de autoservicio de alimentos y bebidas"},{"codigo":"34340.009","nombre":"Coordinador de banquetes / Coordinadora de banquetes"},{"codigo":"34340.010","nombre":"Jefe de cocina / Jefa de cocina"},{"codigo":"34340.011","nombre":"Supervisor de servicio de alimentos y bebidas / Supervisora de servicio de alimentos y bebidas"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"1","nombre":"Gerencia y administración"},{"id":"6","nombre":"Gestión del talento humano y de personal"},{"id":"73","nombre":"Hotelería, restaurantes y servicios de banquetes"},{"id":"23","nombre":"Idioma extranjero"},{"id":"8","nombre":"Procesamiento de alimentos"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"9","nombre":"E