  ('rol_cuoc', 'Otros técnicos de actividades artísticas / Otras técnicas de actividades artísticas', '34351', 'Audiovisuales, Artes Escénicas y Música', 3, false, '{"codigo":"34351","nombre":"Otros técnicos de actividades artísticas / Otras técnicas de actividades artísticas","descripcion":"Asisten a trabajadores técnicos y realizan otras tareas de apoyo relacionadas con la coordinación, producción de cine y las artes escénicas. Se pueden desempeñar en estaciones de radio y televisión, estudios de grabación, compañías de producción de cine y teatro, centros de convenciones, festivales de música, teatro, artes circenses y demás espectáculos, así como por otras empresas del sector público y privado, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"34","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO DE SERVICIOS JURIDICOS, SOCIALES, CULTURALES Y AFINES"},"subgrupo":{"codigo":"343","nombre":"Técnicos y profesionales del nivel medio en actividades culturales, artísticas y culinarias"},"grupo_primario":{"codigo":"3435","nombre":"Otros técnicos y profesionales del nivel medio en actividades culturales y artísticas"}},"funciones":[{"consecutivo":1,"texto":"Apoyar a los operadores de cámara, apuntadores, actores y locutores durante la emisión de noticias y transmisión de programas de televisión."},{"consecutivo":2,"texto":"Emplazar y operar plataformas de cámara móvil, micrófonos y equipo de iluminación."},{"consecutivo":3,"texto":"Distribuir guiones a los actores, llevar registros detallados de todas las acciones, las posiciones y los ángulos de la cámara y las secuencias."},{"consecutivo":4,"texto":"Realizar actuaciones como extra."},{"consecutivo":5,"texto":"Apoyar el proceso de selección del elenco teniendo en cuenta requerimientos técnicos del proyecto."},{"consecutivo":6,"texto":"Programar la música para cada acto de acuerdo con procedimientos técnicos."}