  ('rol_cuoc', 'Artistas corporales', '34352', 'Artes visuales, plásticas y del patrimonio cultural', 3, false, '{"codigo":"34352","nombre":"Artistas corporales","descripcion":"Plasman representaciones artísticas sobre la piel de manera temporal o permanente siguiendo las indicaciones de los clientes en términos de diseño, técnica y la superficie del cuerpo, aplican condiciones higiénico-sanitarias y de bioseguridad. Igualmente, asesoran sobre la elaboración del arte, técnicas de diseño y complementos artísticos, pueden dar recomendaciones y métodos para cuidar el trabajo realizado y evitar complicaciones después de actuar sobre la piel. Se pueden desempeñar en estudios de tatuajes o en establecimientos convencionales y no convencionales, especializados y autorizados para este fin, eventos públicos, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"34","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO DE SERVICIOS JURIDICOS, SOCIALES, CULTURALES Y AFINES"},"subgrupo":{"codigo":"343","nombre":"Técnicos y profesionales del nivel medio en actividades culturales, artísticas y culinarias"},"grupo_primario":{"codigo":"3435","nombre":"Otros técnicos y profesionales del nivel medio en actividades culturales y artísticas"}},"funciones":[{"consecutivo":1,"texto":"Diseñar representaciones artísticas para tatuar la piel de acuerdo con los requerimientos del usuario y en condiciones higiénico-sanitarias y de bioseguridad."},{"consecutivo":2,"texto":"Plasmar diseños y representaciones artísticas de manera temporal o permanente sobre el cuerpo con diferentes técnicas de arte según lo acordado con el cliente en condiciones higiénico-sanitarias y de bioseguridad."},{"consecutivo":3,"texto":"Analizar, definir y realizar los diseños de acuerdo con las técnicas artísticas, requerimiento del cliente, morfología o zona del cuerpo para plasmar sobre la piel."},{"consecutivo":4,"texto":"Asesorar a los clientes sobre el arte a plasmar, técnicas y zona corporal del diseño de acuerdo con parámetros técnicos, estéticos y artísticos."},{"consecutivo":5,"texto":"Orientar e informar al usuario antes, durante y después de la realización del procedimiento sobre el cuidado de la piel, indicaciones y contraindicaciones, métodos para evitar complicaciones y sensibilización del arte y cuerpo."},{"consecutivo":6,"texto":"Mantener la zona de trabajo y el equipamiento en condiciones higiénico-sanitarias y de bioseguridad según la normativa legal vigente."},{"consecutivo":7,"texto":"Presentar y asesorar para la adquisición de productos y servicios asociados al tatuaje y body paint de acuerdo con principios éticos y normativa legal vigente."},{"consecutivo":8,"texto":"Asesorar sobre técnicas artísticas en diferentes eventos o convenciones para demostrar el arte."},{"consecutivo":9,"texto":"Manipular y aplicar en el arte productos e insumos adecuados, certificados y autorizados para la piel de acuerdo con indicaciones, contraindicaciones y la normatividad vigente."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"34352.001","nombre":"Artista de body paint"},{"codigo":"34352.002","nombre":"Artista corporal"},{"codigo":"34352.003","nombre":"Artista de tatuajes"},{"codigo":"34352.004","nombre":"Tatuador / Tatuadora"}],"conocimientos":[{"id":"24","nombre":"Bellas artes"},{"id":"11","nombre":"Diseño"},{"id":"4","nombre":"Mercadotecnia y publicidad"},{"id":"41","nombre":"Primeros auxilios"},{"id":"101","nombre":"Principios éticos"},{"id":"85","nombre":"Seguridad y salud en el trabajo"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"7","nombre":"Aprendizaje aplicado"},{"id":"39","nombre":"Creatividad"},{"id":"2","nombre":"Escucha activa"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"16","nombre":"Resolución de problemas complejos"}],"ocupaciones_afines":[{"codigo":"26511","nombre":"Artistas plásticos y visuales / Artistas plásticas y visuales"},{"codigo":"51422","nombre":"Cosmetólogos esteticistas / Cosmetólogas esteticistas"},{"codigo":"51429","nombre":"Otras ocupaciones elementales de los servicios no clasificados en otras ocupaciones / Otras ocupaciones elementales de los servicios no clasificadas en otras ocupaciones"}],"area_principal":{"sigla":"AVPP","nombre":"Artes visuales, plásticas y del patrimonio cultural"},"areas_complementarias":[{"sigla":"SABI","nombre":"Salud y bienestar"}],"equivalencias":[{"ciuo08_codigo":"3435*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"","cno_obs":""}]}'::jsonb),
  ('rol_cuoc', 'Auxiliares de producción de eventos y espectáculos', '34353', 'Audiovisuales, Artes Escénicas y Música', 2, false, '{"codigo":"34353","nombre":"Auxiliares de producción de eventos y espectáculos","descripcion":"Asisten a la coordinación y producción de eventos y espectáculos dentro y fuera del escenario y la logística de los diferentes equipos que se pueden usar instrumentos, parlantes, micrófonos, consolas, luces, parrillas y accesorios, verificando las condiciones óptimas para la presentación y el cumplimiento de los requisitos especiales que puedan tener. Se pueden desempeñar en estudios de grabación, compañías de producción de cine y teatro, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"34","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO DE SERVICIOS JURIDICOS, SOCIALES, CULTURALES Y AFINES"},"subgrupo":{"codigo":"343","nombre":"Técnicos y profesionales del nivel medio en actividades culturales, artísticas y culinarias"},"grupo_primario":{"codigo":"3435","nombre":"Otros técnicos y profesionales del nivel medio en actividades culturales y artísticas"}},"funciones":[{"consecutivo":1,"texto":"Instalar, operar y efectuar reparaciones de luces y otro equipo eléctrico en estudios y escenarios."},{"consecutivo":2,"texto":"Controlar acceso, chequear la seguridad y comodidad del escenario, así como el cumplimiento de los diferentes requisitos que piden los artistas para el escenario de acuerdo con las especificaciones brindadas por el coordinador."},{"consecutivo":3,"texto":"Asistir en la rotación, entrega y recibimiento de los camerinos y su uso en festivales o eventos de larga duración."},{"consecutivo":4,"texto":"Montar, desmontar y embalar equipos, instrumentos, elementos de iluminación y escenotécnia en general según técnicas y requerimientos del proyecto creativo."},{"consecutivo":5,"texto":"Limpiar, mantener, transportar, almacenar y asistir a los artistas en el vestuario de acuerdo con requerimiento y parámetros técnicos."},{"consecutivo":6,"texto":"Asistir en el arreglo y solución de problemas técnicos que puedan ocurrir durante el evento o espectáculo."},{"consecutivo":7,"texto":"Ubicar, movilizar y desmontar escenografías, telones de fondo y otro equipo de escenario."},{"consecutivo":8,"texto":"Apoyar en la coordinación de efectos especiales como fuegos, explosiones y colisiones."},{"consecutivo":9,"texto":"Ambientar obra de acuerdo con diseño y técnicas escénicas."},{"consecutivo":10,"texto":"Coordinar o hacer el montaje de carpas circenses de acuerdo con parámetros técnicos y normativa de seguridad."},{"consecutivo":11,"texto":"Operar equipamiento de tramoya de acuerdo con parámetros técnicos y artísticos."},{"consecutivo":12,"texto":"Supervisar el trabajo en alturas de acuerdo con normativa de seguridad y salud en el trabajo incluida su actividad."},{"consecutivo":13,"texto":"Supervisar y apoyar el armado de andamios, según especificaciones técnicas y normativa de trabajo en altura."},{"consecutivo":14,"texto":"Vigilar o hacer la instalación de los sistemas de sonido de acuerdo con parámetros técnicos y normativa de seguridad."},{"consecutivo":15,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"34353.001","nombre":"Ambientador / Ambientadora"},{"codigo":"34353.002","nombre":"Asistente de ambientación / Asistenta de ambientación"},{"codigo":"34353.003","nombre":"Asistente de construcción de set / Asistenta de construcción de set"},{"codigo":"34353.004","nombre":"Asistente de grip"},{"codigo":"34353.005","nombre":"Asistente de luces / Asistenta de luces"},{"codigo":"34353.006","nombre":"Asistente de montaje / Asistenta de montaje"},{"codigo":"34353.007","nombre":"Asistente de utilería / Asistenta de utilería"},{"codigo":"34353.008","nombre":"Asistente de vehículos en escena / Asistenta de vehículos en escena"},{"codigo":"34353.009","nombre":"Atrilero / Atrilera"},{"co