  ('rol_cuoc', 'Asistentes de dirección y producción en las artes escénicas y audiovisuales / Asistentas de dirección y producción en las artes escénicas y audiovisuales', '34354', 'Audiovisuales, Artes Escénicas y Música', 3, false, '{"codigo":"34354","nombre":"Asistentes de dirección y producción en las artes escénicas y audiovisuales / Asistentas de dirección y producción en las artes escénicas y audiovisuales","descripcion":"Asisten y acompañan el desarrollo de proyectos audiovisuales y de las artes escénicas, implementando planes de trabajo y especificaciones técnicas y artísticas de la dirección y la producción. Se pueden desempeñar en estudios de grabación, compañías de producción de cine y teatro, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"34","nombre":"TECNICOS Y PROFESIONALES DEL NIVEL MEDIO DE SERVICIOS JURIDICOS, SOCIALES, CULTURALES Y AFINES"},"subgrupo":{"codigo":"343","nombre":"Técnicos y profesionales del nivel medio en actividades culturales, artísticas y culinarias"},"grupo_primario":{"codigo":"3435","nombre":"Otros técnicos y profesionales del nivel medio en actividades culturales y artísticas"}},"funciones":[{"consecutivo":1,"texto":"Revisar y articular con el equipo de dirección y producción las necesidades específicas del plan de trabajo del proyecto audiovisual o de las artes escénicas."},{"consecutivo":2,"texto":"Apoyar el manejo de los datos de las imágenes, decidiendo el orden de los planos y secuencias dando sentido y coherencia al material audiovisual."},{"consecutivo":3,"texto":"Realizar actividades de acompañamiento a la preparación, la filmación y el control de tiempos de cada secuencia grabada, permitiendo la continuidad del material audiovisual según el guion del proyecto y las indicaciones de la dirección."},{"consecutivo":4,"texto":"Generar reportes y mantener registros de las operaciones, problemas y los ajustes efectuados al equipo de dirección y producción de acuerdo con las actividades asignadas."},{"consecutivo":5,"texto":"Asistir los procesos de organización, previsión y coordinación de la producción de contenidos audiovisuales y multiplataforma."},{"consecutivo":6,"texto":"Efectuar labores de seguimiento y enlace entre los directores y los diferentes equipos del proyecto audiovisual o de las artes escénicas."},{"consecutivo":7,"texto":"Elaborar y publicar los cronogramas de trabajo según requisitos técnicos y artísticos del proyecto."},{"consecutivo":8,"texto":"Apoyar la búsqueda de localizaciones y coordinación de traslados y transporte a dichas locaciones."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"34354.001","nombre":"Asistente de arte de escenografía / Asistenta de arte de escenografía"},{"codigo":"34354.002","nombre":"Asistente de coordinación de producción / Asistenta de coordinación de producción"},{"codigo":"34354.003","nombre":"Asistente de decoración / Asistenta de decoración"},{"codigo":"34354.004","nombre":"Asistente de dirección de arte / Asistenta de dirección de arte"},{"codigo":"34354.005","nombre":"Asistente de dirección de teatro / Asistenta de dirección de teatro"},{"codigo":"34354.006","nombre":"Asistente de efectos visuales / Asistenta de efectos visuales"},{"codigo":"34354.007","nombre":"Asistente de escenografía / Asistenta de escenografía"},{"codigo":"34354.008","nombre":"Asistente de producción audiovisual / Asistenta de producción audiovisual"},{"codigo":"34354.009","nombre":"Asistente de producción de arte / Asistenta de producción de arte"},{"codigo":"34354.010","nombre":"Asistente de producción de oficina / Asistenta de producción de oficina"},{"codigo":"34354.011","nombre":"Continuista"},{"codigo":"34354.014","nombre":"Ingestador / Ingestadora"},{"codigo":"34354.015","nombre":"Jefe de ambientación y montaje / Jefa de ambientación y montaje"},{"codigo":"34354.016","nombre":"Jefe de construcción e