  ('rol_cuoc', 'Técnicos en operaciones de tecnología de la información y las comunicaciones / Técnicas en operaciones de tecnología de la información y las comunicaciones', '35110', 'Tecnologías de la información y las comunicaciones', 3, false, '{"codigo":"35110","nombre":"Técnicos en operaciones de tecnología de la información y las comunicaciones / Técnicas en operaciones de tecnología de la información y las comunicaciones","descripcion":"Implementan la infraestructura tecnológica, redes de datos, tecnologías de voz sobre protocolos de internet, software de soporte de servicios de conectividad, aplicaciones de tecnologías de la información y las comunicaciones, utiliza herramientas de diagnóstico de seguridad de la información en las organizaciones. Se pueden desempeñar en organizaciones de tecnologías de la información y las comunicaciones, firmas consultoras y departamentos de tecnología en empresas, de forma independiente, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"35","nombre":"TÉCNICOS EN TECNOLOGÍA DE LA INFORMACIÓN Y LAS COMUNICACIONES"},"subgrupo":{"codigo":"351","nombre":"Técnicos en operaciones de tecnología de la información, las comunicaciones y asistencia al usuario"},"grupo_primario":{"codigo":"3511","nombre":"Técnicos en operaciones de tecnología de la información y las comunicaciones"}},"funciones":[{"consecutivo":1,"texto":"Manejar y controlar los equipos periféricos de ordenador y los materiales necesarios para su funcionamiento operativo."},{"consecutivo":2,"texto":"Vigilar los sistemas de seguimiento a fin de detectar fallas o errores en el funcionamiento del equipo."},{"consecutivo":3,"texto":"Responder a los mensajes de error de los programas buscando y corrigiendo los problemas."},{"consecutivo":4,"texto":"Incorporar la introducción de comandos, usando terminales de computador y la activación de los controles de computadores y equipos periféricos para para garantizar su funcionamiento."},{"consecutivo":5,"texto":"Notificar a los supervisores o técnicos de mantenimiento el mal funcionamiento del equipo."},{"consecutivo":6,"texto":"Documentar y registrar información de soluciones tecnológicas de acuerdo con normativa, procedimientos técnicos y metodologías."},{"consecutivo":7,"texto":"Implementar la red física de datos o inalámbrica según especificaciones del diseño y estándares técnicos."},{"consecutivo":8,"texto":"Instalar y reparar equipos de cómputo según procedimientos, protocolos y manuales técnicos."},{"consecutivo":9,"texto":"Operar herramientas informáticas y digitales de acuerdo con protocolos y manuales técnicos."},{"consecutivo":10,"texto":"Realizar mantenimiento a hardware y software de tecnología y equipos de telecomunicaciones según procedimiento técnico."},{"consecutivo":11,"texto":"Soportar tecnologías de la información de acuerdo con protocolos técnicos y herramientas computacionales."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"35110.001","nombre":"Asistente de computadores en operaciones / Asistenta de computadores en operaciones"},{"codigo":"35110.002","nombre":"Asistente de TI (Tecnologías de la Información) / Asistenta de TI (Tecnologías de la Información)"},{"codigo":"35110.003","nombre":"Operador de centro de cómputo / Operadora de centro de cómputo"},{"codigo":"35110.004","nombre":"Operador de computadores / Operadora de computadores"},{"codigo":"35110.005","nombre":"Operador de equipos informáticos periféricos / Operadora de equipos informáticos periféricos"},{"codigo":"35110.006","nombre":"Operador de impresora / Operadora de impresora"},{"codigo":"35110.007","nombre":"Operador de impresora de alta velocidad / Operadora de impresora de alta velocidad"},{"codigo":"35110.008","nombre":"Técnico de ingeniería de sistemas de computadores / Técnica de ingeniería de sistemas de computadores"}],"conocimientos":[{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"63","nombre":"Desarrollo y análisis de software y aplicaciones"},{"id":"65","nombre":"Diseño y administración de redes y bases de datos"},{"id":"10","nombre":"Ingeniería y tecnología"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"5","nombre":"Servicio al cliente"},{"id":"29","nombre":"Telecomunicación"}],"destrezas":[{"id":"7","nombre":"Aprendizaje aplicado"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"24","nombre":"Mantenimiento de equipos"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"11200","nombre":"Directores y gerentes generales / Directoras y gerentas generales"},{"codigo":"24340","nombre":"Profesionales de ventas de tecnología de la información y las comunicaciones"},{"codigo":"25110","nombre":"Analistas de sistemas"},{"codigo":"35130","nombre":"Técnicos en redes y tecnologías de la información / Técnicas en redes y tecnologías de la información"},{"codigo":"74222","nombre":"Auxiliares técnicos de instalación, mantenimiento y reparación de sistemas de telecomunicaciones / Auxiliares técnicas de instalación, mantenimiento y reparación de sistemas de telecomunicaciones"}],"area_principal":{"sigla":"TICO","nombre":"Tecnologías de la información y las comunicaciones"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"3511","ciuo08_obs":"Denominaciones completas","cno_codigo":"","cno_obs":""}]}'::jsonb),
  ('rol_cuoc', 'Técnicos en asistencia y soporte de tecnologías de la información / Técnicas en asistencia y soporte de tecnologías de la información', '35121', 'Tecnologías de la información y las comunicaciones', 2, false, '{"codigo":"35121","nombre":"Técnicos en asistencia y soporte de tecnologías de la información / Técnicas en asistencia y soporte de tecnologías de la información","descripcion":"Proporcionan asistencia técnica a los usuarios, ya sea directamente o por teléfono, correo electrónico u otros medios, incluyendo el diagnóstico y la solución de dificultades y problemas con el software, hardware, equipos periféricos, redes, bases de datos e internet, la disponibilidad, orientación y apoyo en el despliegue, instalación y mantenimiento de sistemas. Se pueden desempeñar en organizaciones de tecnologías de la información y las comunicaciones, firmas consultoras y departamentos de tecnología en empresas del sector público y privado, de manera independiente, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"35","nombre":"TÉCNICOS EN TECNOLOGÍA DE LA INFORMACIÓN Y LAS COMUNICACIONES"},"subgrupo":{"codigo":"351","nombre":"Técnicos en operaciones de tecnología de la información, las comunicaciones y asistencia al usuario"},"grupo_primario":{"codigo":"3512","nombre":"Técnicos en asistencia y soporte al usuario de tecnología de la información y las comunicaciones"}},"funciones":[{"consecutivo":1,"texto":"Atender requerimientos de los usuarios sobre el funcionamiento del software o el funcionamiento de hardware con el fin de resolver problemas."},{"consecutivo":2,"texto":"Instalar y realizar reparaciones menores a hardware y software o equipos periféricos, siguiendo el diseño o las especificaciones de instalación."},{"consecutivo":3,"texto":"Configurar los equipos para su uso por miembros del personal y realizar o asegurar que se lleve a cabo la correcta instalación de cables, sistemas operativos software, de acuerdo con necesidades de usuario."},{"consecutivo":4,"texto":"Incorporar instrucciones de programación y observar el funcionamiento de los sistemas a fin de verificar las operaciones correctas y detectar errores."},{"consecutivo":5,"texto":"Supervisar el funcionamiento diario de las comunicaciones y los sistemas informáticos."},{"consecutivo":6,"texto":"Ayudar a los programadores de aplicaciones, desarrolladores de sistemas y otros profesionales de las TIC en la concepción, la elaboración y la puesta a prueba de los productos y servicios de TIC."},{"consecutivo":7,"texto":"Realizar pruebas y análisis de máquinas, componentes y materiales para determinar su funcionamiento, resistencia y otras características."},{"consecutivo":8,"texto":"Instruir en el uso de herramientas informáticas de acuerdo con las necesidades de manejo de información."},{"consecutivo":9,"texto":"Realizar mantenimiento a registros de las operaciones, los problemas y los correctivos efectuados, así como de las actividades de instalación según procedimientos y protocolo de servicio."},{"consecutivo":10,"texto":"Instalar equipos de cómputo según protocolos y manual técnicos."},{"consecutivo":11,"texto":"Manejar incidencias informáticas según especificaciones técnicas y protocolos de servicio ."},{"consecutivo":12,"texto":"Realizar mantenimiento a equipos de cómputo según procedimiento técnico."},{"consecutivo":13,"texto":"Operar herramientas informáticas y digitales de acuerdo con protocolos y manuales técnicos ."},{"consecutivo":14,"texto":"Reparar equipos de cómputo según procedimiento técnico."},{"consecutivo":15,"texto":"Soportar tecnologías de la información de acuerdo con protocolos técnicos y herramientas computacionales."},{"consecutivo":16,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"35121.001","nombre":"Analista de apoyo del PC"},{"codigo":"35121.002","nombre":"Analista de apoyo software"},{"codigo":"35121.0