  ('rol_cuoc', 'Representantes de servicios especializados BPO (business process outsourcing)', '35122', 'Administración, finanzas y derecho', 3, false, '{"codigo":"35122","nombre":"Representantes de servicios especializados BPO (business process outsourcing)","descripcion":"Interactúan con los clientes internos y externos proporcionando información, realizan actividades de servicios especializados de los clientes y usuarios en el contexto de procesos de negocio; cumple indicadores de eficiencia, calidad, directrices y políticas. Las funciones y responsabilidades varían según el tipo de servicio especializado. Se pueden desempeñar en empresas públicas o privadas, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"35","nombre":"TÉCNICOS EN TECNOLOGÍA DE LA INFORMACIÓN Y LAS COMUNICACIONES"},"subgrupo":{"codigo":"351","nombre":"Técnicos en operaciones de tecnología de la información, las comunicaciones y asistencia al usuario"},"grupo_primario":{"codigo":"3512","nombre":"Técnicos en asistencia y soporte al usuario de tecnología de la información y las comunicaciones"}},"funciones":[{"consecutivo":1,"texto":"Atender requerimientos de los clientes de acuerdo con procedimientos técnicos y normativa de procesos de negocio."},{"consecutivo":2,"texto":"Interactuar con clientes de acuerdo con sus necesidades y con las políticas y la estrategia de servicio de la organización."},{"consecutivo":3,"texto":"Suministrar servicios especializados según el modelo de gestión."},{"consecutivo":4,"texto":"Supervisar el funcionamiento diario de las comunicaciones y los sistemas informáticos."},{"consecutivo":5,"texto":"Apoyar en la implementación de las normas de seguridad industrial, salud ocupacional y el medio ambiente que regulan su actividad en el puesto de trabajo."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"35122.001","nombre":"Agente corporativo BPO / Agente corporativa BPO (business process outsourcing)"},{"codigo":"35122.002","nombre":"Agente de contact center especializado BPO / Agente de contact center especializada BPO (business process outsourcing)"},{"codigo":"35122.003","nombre":"Agente de servicio especializado BPO (business process outsourcing)"},{"codigo":"35122.004","nombre":"Asesor de servicio especializado BPO / Asesora de servicio especializado BPO (business process outsourcing)"},{"codigo":"35122.005","nombre":"Ejecutivo de servicio especializado BPO / Ejecutiva de servicio especializado BPO (business process outsourcing)"},{"codigo":"35122.006","nombre":"Líder de servicio BPO (business process outsourcing)"},{"codigo":"35122.007","nombre":"Operador de servicio especializado BPO / Operadora de servicio especializado BPO (business process outsourcing)"},{"codigo":"35122.008","nombre":"Representante de servicio especializado BPO (business process outsourcing)"},{"codigo":"35122.009","nombre":"Representante de soporte de apoyo a internet"},{"codigo":"35122.010","nombre":"Representante técnico de soporte informático / Representante técnica de soporte informático"}],"conocimientos":[{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"23","nombre":"Idioma extranjero"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"},{"id":"29","nombre":"Telecomunicación"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"3","nombre":"Redacción de textos"}],"ocupaciones_afines":[{"codigo":"42220","nombre":"Empleados de centros de llamadas / Empleadas de centros de llamadas"},{"codigo":"42251","nombre":"Auxiliares de información y servicio al cliente"},{"codigo":"44199","nombre":"Otro personal de apoyo administrativo no clasificados en otras ocupaciones / Otra personal de apoyo administra