  ('rol_cuoc', 'Técnicos en redes y tecnologías de la información / Técnicas en redes y tecnologías de la información', '35130', 'Tecnologías de la información y las comunicaciones', 3, true, '{"codigo":"35130","nombre":"Técnicos en redes y tecnologías de la información / Técnicas en redes y tecnologías de la información","descripcion":"Implementan, operan y mantienen la infraestructura tecnológica, redes de datos, tecnologías de voz sobre protocolos de internet, software de soporte de servicios de conectividad, aplicaciones de tecnologías de la información y las comunicaciones, utiliza herramientas de diagnóstico de seguridad de la información en las organizaciones. Se pueden desempeñar de forma independiente para organizaciones de tecnologías de la información y las comunicaciones, firmas consultoras y departamentos de tecnología en empresas del sector público y privado, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"35","nombre":"TÉCNICOS EN TECNOLOGÍA DE LA INFORMACIÓN Y LAS COMUNICACIONES"},"subgrupo":{"codigo":"351","nombre":"Técnicos en operaciones de tecnología de la información, las comunicaciones y asistencia al usuario"},"grupo_primario":{"codigo":"3513","nombre":"Técnicos en redes y tecnologías de la información"}},"funciones":[{"consecutivo":1,"texto":"Implementar, operar, administrar y solucionar los problemas del sistemas de red de datos según estándares técnicos."},{"consecutivo":2,"texto":"Operar y mantener los sistemas de comunicación de datos distintos de las redes."},{"consecutivo":3,"texto":"Identificar los ámbitos en que sea necesario actualizar software y equipos, probar la solución del software con parámetros técnicos y modelos de referencia."},{"consecutivo":4,"texto":"Instalar y configurar equipos informáticos, software de red, de sistemas operativos y de aplicaciones."},{"consecutivo":5,"texto":"Llevar a cabo la puesta en marcha y la parada de los equipos, así como la realización de copias de seguridad y las operaciones de recuperación en caso de desastres en las redes informáticas."},{"consecutivo":6,"texto":"Atender requerimientos de los usuarios de acuerdo con procedimientos técnicos y normativa vigente."},{"consecutivo":7,"texto":"Configurar dispositivos activos de interconexión según especificaciones del diseño y protocolos técnicos."},{"consecutivo":8,"texto":"Aplicar herramientas de diagnóstico de seguridad de la información de acuerdo con protocolos técnicos."},{"consecutivo":9,"texto":"Monitorear el centro de datos de acuerdo con procedimientos técnicos y estándares."},{"consecutivo":10,"texto":"Realizar mantenimiento a la infraestructura tecnológica de red según modelos de referencia y procedimientos técnicos."},{"consecutivo":11,"texto":"Documentar la solución tecnológica de acuerdo con procedimientos técnicos y metodologías."},{"consecutivo":12,"texto":"Registrar información de acuerdo con normativa y procedimiento técnico."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"35130.001","nombre":"Asistente de comunicaciones de las TIC (tecnologías de la información y las comunicaciones) / Asistenta de comunicaciones de las TIC (tecnologías de la información y las comunicaciones)"},{"codigo":"35130.002","nombre":"Asistente de equipo de comunicaciones / Asistenta de equipo de comunicaciones"},{"codigo":"35130.003","nombre":"Asistente de equipo de red / Asistenta de equipo de red"},{"codigo":"35130.004","nombre":"Asistente informático en diseño de sistemas / Asistenta informática en diseño de sistemas"},{"codigo":"35130.005","nombre":"Codificador de aplicaciones informáticas / Codificadora de aplicaciones informáticas"},{"codigo":"35130.006","nombre":"Documentador de soluciones de TI (Tecnologías de la Información) / Documentadora de soluciones de TI (Tecnologías de la Información)"},{"codigo":"35130.007","nombre":"Técnico administrador de cen