  ('rol_cuoc', 'Técnicos de la web / Técnicas de la web', '35140', 'Tecnologías de la información y las comunicaciones', 3, false, '{"codigo":"35140","nombre":"Técnicos de la web / Técnicas de la web","descripcion":"Mantienen, supervisan y apoyan el óptimo funcionamiento de internet, intranet, sitios web y el hardware y software del servidor web. Garantizan el funcionamiento y la operación de servicios de tecnologías web. Se pueden desempeñar de forma independiente para organizaciones de tecnologías de la información y las comunicaciones, firmas consultoras y departamentos de tecnología en empresas del sector público y privado, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"35","nombre":"TÉCNICOS EN TECNOLOGÍA DE LA INFORMACIÓN Y LAS COMUNICACIONES"},"subgrupo":{"codigo":"351","nombre":"Técnicos en operaciones de tecnología de la información, las comunicaciones y asistencia al usuario"},"grupo_primario":{"codigo":"3514","nombre":"Técnicos de la web"}},"funciones":[{"consecutivo":1,"texto":"Crear, modificar y publicar sitios web en internet, redes internas de intranet o equipos y software en los servidores web, supervisar su funcionamiento y prestar apoyo técnico para asegurar su fiabilidad y la facilidad de uso."},{"consecutivo":2,"texto":"Registrar los procedimientos de operación e incidencias de los sistemas, manteniendo la documentación, de acuerdo con políticas e instrucciones."},{"consecutivo":3,"texto":"Ejecutar el sistema de seguridad de la información de acuerdo con estándares y marcos de referencia."},{"consecutivo":4,"texto":"Analizar riesgos de soluciones de tecnologías de la información y formular recomendaciones para mejorar el rendimiento, incluyendo la actualización y adquisición de nuevos sistemas."},{"consecutivo":5,"texto":"Establecer y mantener contactos con clientes y usuarios para brindarles orientación."},{"consecutivo":6,"texto":"Realizar las copias de seguridad del servidor web y llevar a cabo operaciones de recuperación en los mismos."},{"consecutivo":7,"texto":"Controlar el centro de datos de acuerdo con procedimiento técnico y estándares."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"35140.001","nombre":"Administrador de sitio web / Administradora de sitio web"},{"codigo":"35140.002","nombre":"Administrador de página web / Administradora de página web"},{"codigo":"35140.003","nombre":"Coordinador de gestión de sitio web / Coordinadora de gestión de sitio web"},{"codigo":"35140.004","nombre":"Coordinador de la página web / Coordinadora de la página web"},{"codigo":"35140.005","nombre":"Operador web / Operadora web"},{"codigo":"35140.006","nombre":"Técnico de diseño de página web / Técnica de diseño de página web"},{"codigo":"35140.007","nombre":"Técnico de sitio web / Técnica de sitio web"},{"codigo":"35140.008","nombre":"Webmaster"}],"conocimientos":[{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"65","nombre":"Diseño y administración de redes y bases de datos"},{"id":"23","nombre":"Idioma extranjero"},{"id":"10","nombre":"Ingeniería y tecnología"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"5","nombre":"Servicio al cliente"},{"id":"29","nombre":"Telecomunicación"}],"destrezas":[{"id":"17","nombre":"Análisis de necesidades"},{"id":"1","nombre":"Comprensión de lectura"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"16","nombre":"Resolución de problemas complejos"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"21499","nombre":"Ingenieros no clasificados en otras ocupaciones / Ingenieras no clasificadas en otras ocupaciones"},{"codigo":"21531","nombre":"Ingenieros de telecomunicaciones / Ingenieras de telecomunicaciones"},{"codigo":"24312","nombre":"Administradores de com