  ('rol_cuoc', 'Operadores de cámara de cine y televisión / Operadoras de cámara de cine y televisión', '35211', 'Audiovisuales, Artes Escénicas y Música', 3, false, '{"codigo":"35211","nombre":"Operadores de cámara de cine y televisión / Operadoras de cámara de cine y televisión","descripcion":"Operan cámaras de cine, televisión y equipo relacionado para la grabación de noticias, eventos, películas, videos y programas de televisión. Controlan el funcionamiento técnico de los equipos para grabar, editar y transmitir imágenes y sonidos de programas de radio y televisión, así como otro tipo de señales. Se pueden desempeñar en programadoras de televisión, compañías cinematográficas, productoras de video, trabajar en forma independiente, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"35","nombre":"TÉCNICOS EN TECNOLOGÍA DE LA INFORMACIÓN Y LAS COMUNICACIONES"},"subgrupo":{"codigo":"352","nombre":"Técnicos en telecomunicaciones y radiodifusión"},"grupo_primario":{"codigo":"3521","nombre":"Técnicos de radiodifusión y grabación audio visual"}},"funciones":[{"consecutivo":1,"texto":"Seleccionar e instalar el equipo a utilizar e implementar lentes, filtros, películas y otros accesorios para las cámaras."},{"consecutivo":2,"texto":"Ajustar enfoques, exposición, iluminación y otras adaptaciones de las cámaras."},{"consecutivo":3,"texto":"Operar cámaras de video, cine o televisión para grabar noticias, eventos, películas, programas de televisión y videos."},{"consecutivo":4,"texto":"Probar y dar mantenimiento al equipo."},{"consecutivo":5,"texto":"Emplazar y operar plataformas de cámara móvil, micrófonos y equipo de iluminación."},{"consecutivo":6,"texto":"Montar películas en los proyectores de cine, ajustar foco, niveles de sonido, decorados de teatro y hacer mantenimiento de rutina al equipo."},{"consecutivo":7,"texto":"Apoyar al director y a otros miembros del equipo en las secuencias y planos de filmación, movimientos de cámara y composición de las películas."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"35211.001","nombre":"Auxiliar de audiovisuales"},{"codigo":"35211.002","nombre":"Auxiliar de cámara de cine y de televisión"},{"codigo":"35211.003","nombre":"Ayudante de cámara"},{"codigo":"35211.004","nombre":"Camarógrafo / Camarógrafa"},{"codigo":"35211.005","nombre":"Camarógrafo de cine / Camarógrafa de cine"},{"codigo":"35211.006","nombre":"Camarógrafo de estudio / Camarógrafa de estudio"},{"codigo":"35211.007","nombre":"Camarógrafo de estudio-móvil / Camarógrafa de estudio-móvil"},{"codigo":"35211.008","nombre":"Camarógrafo de televisión / Camarógrafa de televisión"},{"codigo":"35211.009","nombre":"Camarógrafo de terreno / Camarógrafa de terreno"},{"codigo":"35211.010","nombre":"Camarógrafo operador de grúa / Camarógrafa operadora de grúa"},{"codigo":"35211.011","nombre":"Dolly grip"},{"codigo":"35211.012","nombre":"Operador asistente de cámara / Operadora asistenta de cámara"},{"codigo":"35211.013","nombre":"Operador de cámara inmersiva / Operadora de cámara inmersiva"},{"codigo":"35211.014","nombre":"Operador de audiovisuales / Operadora de audiovisuales"},{"codigo":"35211.015","nombre":"Operador de cámara / Operadora de cámara"},{"codigo":"35211.016","nombre":"Operador de cámara 360 / Operadora de cámara 360"},{"codigo":"35211.017","nombre":"Operador de cámara aérea / Operadora de cámara aérea"},{"codigo":"35211.018","nombre":"Operador de cámara de cine / Operadora de cámara de cine"},{"codigo":"35211.019","nombre":"Operador de cámara de cine y televisión / Operadora de cámara de cine y televisión"},{"codigo":"35211.020","nombre":"Operador de cámara de estudio / Operadora de cámara de estudio"},{"codigo":"35211.021","nombre":"Operador de cámara de televisión / Operadora de cámara de televisión"},{"codigo":"35211.022","nombre":"Operador de cámara de video / Operadora de cám