  ('rol_cuoc', 'Técnicos en transmisión audiovisual / Técnicas en transmisión audiovisual', '35212', 'Audiovisuales, Artes Escénicas y Música', 3, false, '{"codigo":"35212","nombre":"Técnicos en transmisión audiovisual / Técnicas en transmisión audiovisual","descripcion":"Operan consolas de control y otro equipo de radiodifusión para canalizar y monitorear transmisiones de radio y televisión a través de emisoras y cadenas. Asisten a trabajadores técnicos y realizan otras tareas de apoyo relacionadas con la producción de cine y las artes escénicas. Se pueden desempeñar en estaciones de radio y televisión, estudios de grabación, compañías de producción de cine y teatro, cadenas y estaciones de difusión de radio y televisión, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"35","nombre":"TÉCNICOS EN TECNOLOGÍA DE LA INFORMACIÓN Y LAS COMUNICACIONES"},"subgrupo":{"codigo":"352","nombre":"Técnicos en telecomunicaciones y radiodifusión"},"grupo_primario":{"codigo":"3521","nombre":"Técnicos de radiodifusión y grabación audio visual"}},"funciones":[{"consecutivo":1,"texto":"Monitorear la calidad de la emisión directa o grabada de programas de radio y televisión."},{"consecutivo":2,"texto":"Operar, dirigir y controlar los sistemas de transmisión y difusión mayoritarios y los programas de radio y televisión por satélites."},{"consecutivo":3,"texto":"Hacer reparaciones de emergencia al equipo y reemplazar los programas en caso de fallas en la señal."},{"consecutivo":4,"texto":"Instalar y operar consolas para captar o emitir ondas desde diferentes localizaciones y llevar al aire programas de radio, televisión y comerciales."},{"consecutivo":5,"texto":"Distribuir guiones a los actores, llevar registros detallados de todas las acciones, las posiciones y los ángulos de la cámara y secuencias."},{"consecutivo":6,"texto":"Ubicar, movilizar y desmontar escenografías, telones de fondo y otro equipo de escenario."},{"consecutivo":7,"texto":"Registrar imágenes, insertar y grabar textos, letreros o caracteres en las películas o proyecto audiovisual."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"35212.001","nombre":"Controlador técnico en cabina / Controladora técnica en cabina"},{"codigo":"35212.002","nombre":"Coordinador de transmisión de programas de radio / Coordinadora de transmisión de programas de radio"},{"codigo":"35212.003","nombre":"Editor de efectos de sonido / Editora de efectos de sonido"},{"codigo":"35212.004","nombre":"Emisorista"},{"codigo":"35212.005","nombre":"Generador de master de tv y video / Generadora de master de tv y video"},{"codigo":"35212.006","nombre":"Operador de cabina de proyección cinematografía / Operadora de cabina de proyección cinematografía"},{"codigo":"35212.007","nombre":"Operador de control master / Operadora de control master"},{"codigo":"35212.008","nombre":"Operador de equipo de transmisión / Operadora de equipo de transmisión"},{"codigo":"35212.009","nombre":"Operador de equipo de transmisión de radio / Operadora de equipo de transmisión de radio"},{"codigo":"35212.010","nombre":"Operador de equipo de transmisión de televisión / Operadora de equipo de transmisión de televisión"},{"codigo":"35212.011","nombre":"Operador de equipo transmisión móvil / Operadora de equipo transmisión móvil"},{"codigo":"35212.012","nombre":"Operador de equipos de proyección audiovisual y cinematográfico / Operadora de equipos de proyección audiovisual y cinematográfico"},{"codigo":"35212.013","nombre":"Operador de estación de emisora de radio / Operadora de estación de emisora de radio"},{"codigo":"35212.014","nombre":"Operador de máster / Operadora de máster"},{"codigo":"35212.015","nombre":"Operador de máster en vivo / Operadora de máster en vivo"},{"codigo":"35212.016","nombre":"Operador de panel de control de radio / Operadora de panel de control de radio"},{"codigo":"3