  ('rol_cuoc', 'Técnicos de producción de audio y sonido / Técnicas de producción de audio y sonido', '35214', 'Audiovisuales, Artes Escénicas y Música', 3, false, '{"codigo":"35214","nombre":"Técnicos de producción de audio y sonido / Técnicas de producción de audio y sonido","descripcion":"Operan equipo de grabación, edición, mezcla y masterización de sonido, análogo y digital; para grabar, editar y mezclar diálogos, ambientes, efectos, foley y música; para películas, videos, programas de radio, televisión, grabaciones y sonido en vivo. Se pueden desempeñar en compañías de producción de cine y vídeo, periodismo, grabación de sonido, estaciones de radio y televisión, empresas de renta de equipos de audio, teatros, auditorios, eventos, establecimientos de recreación y ocio, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"35","nombre":"TÉCNICOS EN TECNOLOGÍA DE LA INFORMACIÓN Y LAS COMUNICACIONES"},"subgrupo":{"codigo":"352","nombre":"Técnicos en telecomunicaciones y radiodifusión"},"grupo_primario":{"codigo":"3521","nombre":"Técnicos de radiodifusión y grabación audio visual"}},"funciones":[{"consecutivo":1,"texto":"Instalar, situar y operar implementos de grabación de audio de acuerdo con los procedimientos establecidos."},{"consecutivo":2,"texto":"Probar, dar mantenimiento, hacer reparaciones de emergencia al equipo y reemplazar los programas en caso de fallas en la señal."},{"consecutivo":3,"texto":"Emplazar y operar micrófonos."},{"consecutivo":4,"texto":"Movilizar y verificar el mantenimiento de equipos de sonido y asistir a los artistas en el escenario."},{"consecutivo":5,"texto":"Operar equipo de audio análogo y digital para grabar y capturar sonido, música, diálogos y crear efectos para películas, vídeos, programas de radio, televisión y grabaciones."},{"consecutivo":6,"texto":"Operar equipo de edición análogo y digital para editar piezas sonoras como música, mezclar estructuras, diálogos y efectos de sonido para películas, videos, programas de radio, televisión y grabaciones."},{"consecutivo":7,"texto":"Grabar audio y crear ambientes sonoros para el doblaje en la reproducción de diálogos, música y pistas y efectos de sonido desde diferentes fuentes en sincronización con películas cinematográficas."},{"consecutivo":8,"texto":"Operar consolas de audio para mezclar música y sonido en conciertos, eventos en vivo y producciones audiovisuales."},{"consecutivo":9,"texto":"Operar equipos de masterización análogos y digitales para masterizar música para películas, videos, programas de radio, televisión y grabaciones."},{"consecutivo":10,"texto":"Estructurar y escribir guiones sonoros para películas, videos, programas de radio, televisión y grabaciones."},{"consecutivo":11,"texto":"Coordinar con los grupos musicales o presentadores las pruebas de sonido en las presentaciones en vivo y diferidas."},{"consecutivo":12,"texto":"Supervisar y apoyar la construcción, montaje y desmontaje de las tecnologías de sonido ubicadas en el set."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"35214.001","nombre":"Artista de foley"},{"codigo":"35214.003","nombre":"Disc jockey mezclador / Disc jockey mezcladora"},{"codigo":"35214.004","nombre":"DJ productor de mezcla / DJ productora de mezcla"},{"codigo":"35214.005","nombre":"Grabador de foley / Grabadora de foley"},{"codigo":"35214.006","nombre":"Grabador de sonido de doblajes / Grabadora de sonido de doblajes"},{"codigo":"35214.007","nombre":"Mezclador de audio / Mezcladora de audio"},{"codigo":"35214.008","nombre":"Mezclador de sonido / Mezcladora de sonido"},{"codigo":"35214.009","nombre":"Microfonista"},{"codigo":"35214.010","nombre":"Montajista de sonido"},{"codigo":"35214.011","nombre":"Operador de audio / Operadora de audio"},{"codigo":"35214.012","nombre":"Operador de audio y sonido / Operadora de audio y sonido"},{"codigo":"35214.013"