  ('rol_cuoc', 'Asistentes de producción de audio y sonido / Asistentas de producción de audio y sonido', '35215', 'Audiovisuales, Artes Escénicas y Música', 2, false, '{"codigo":"35215","nombre":"Asistentes de producción de audio y sonido / Asistentas de producción de audio y sonido","descripcion":"Realizan labores operacionales relacionadas con el audio, realizan procesos técnicos y de operación de equipos basados en la decisión y los lineamientos del ingeniero de sonido o del productor musical, apoyan asistiendo la producción y edición de proyectos de grabación de audio. Se pueden desempeñar en estudios de grabación, festivales de música, disqueras, productoras de televisión, teatros, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"35","nombre":"TÉCNICOS EN TECNOLOGÍA DE LA INFORMACIÓN Y LAS COMUNICACIONES"},"subgrupo":{"codigo":"352","nombre":"Técnicos en telecomunicaciones y radiodifusión"},"grupo_primario":{"codigo":"3521","nombre":"Técnicos de radiodifusión y grabación audio visual"}},"funciones":[{"consecutivo":1,"texto":"Identificar y resolver los problemas de telecomunicaciones que surjan en la producción de audio y sonido."},{"consecutivo":2,"texto":"Asistir en el registro y mezcla del material sonoro de acuerdo con lineamientos brindados por el ingeniero de sonido o el productor musical."},{"consecutivo":3,"texto":"Operar y apoyar en la masterización, edición y producción musical de acuerdo con indicaciones."},{"consecutivo":4,"texto":"Organizar, editar y rotular el material sonoro registrado."},{"consecutivo":5,"texto":"Instalar, desmontar y embalar equipos de grabación y amplificación."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"35215.001","nombre":"Asistente de grabación / Asistenta de grabación"},{"codigo":"35215.002","nombre":"Asistente de ingeniería de edición / Asistenta de ingeniería de edic