  ('rol_cuoc', 'Supervisores de telecomunicaciones / Supervisoras de telecomunicaciones', '35222', 'Tecnologías de la información y las comunicaciones', 3, false, '{"codigo":"35222","nombre":"Supervisores de telecomunicaciones / Supervisoras de telecomunicaciones","descripcion":"Coordinan y supervisan las actividades de los trabajadores que ejecutan tareas técnicas relacionadas con la investigación en ingeniería de telecomunicaciones, así como en el diseño, la fabricación, el montaje, la construcción, la operación, el mantenimiento y la reparación de sistemas de telecomunicaciones. Se pueden desempeñar de forma independiente, empresas del sector público o privado, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"35","nombre":"TÉCNICOS EN TECNOLOGÍA DE LA INFORMACIÓN Y LAS COMUNICACIONES"},"subgrupo":{"codigo":"352","nombre":"Técnicos en telecomunicaciones y radiodifusión"},"grupo_primario":{"codigo":"3522","nombre":"Técnicos y operadores de ingeniería de las telecomunicaciones"}},"funciones":[{"consecutivo":1,"texto":"Supervisar, coordinar y programar las actividades de fabricación, utilización, instalación, reparación y mantenimiento de sistemas de telecomunicaciones, aparatos de control, sistemas eléctricos, sistemas electrónicos y sistemas de cablevisión, de acuerdo con especificaciones y reglamentos."},{"consecutivo":2,"texto":"Determinar el método de trabajo que se ha de adoptar, estudiando materiales técnicos como planos, croquis, entre otros."},{"consecutivo":3,"texto":"Establecer programas de trabajo y coordinar las actividades con otros subcontratistas o departamentos."},{"consecutivo":4,"texto":"Preparar estimaciones de cantidades, costos de materiales y mano de obra necesarios para la fabricación e instalación de equipos de telecomunicaciones y hacer las requisiciones de materiales e insumos, de acuerdo con las especificaciones establecidas."},{"consecutivo":5,"texto":"Efectuar el control técnico de la instalación, la utilización, el mantenimiento y la reparación de equipos electrónicos y garantizar su funcionamiento."},{"consecutivo":6,"texto":"Instalar y operar equipo normal y especializado para el diagnóstico, la prueba y el análisis del funcionamiento de componentes, ensambles y sistemas electrónicos."},{"consecutivo":7,"texto":"Realizar o disponer el entrenamiento de los trabajadores."},{"consecutivo":8,"texto":"Velar por el cumplimiento de las normas de seguridad."},{"consecutivo":9,"texto":"Identificar y resolver los problemas laborales que surjan en el curso de su trabajo y recomendar medidas que mejoren la productividad."},{"consecutivo":10,"texto":"Hacer recomendaciones sobre contratación y ascensos de personal."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"35222.001","nombre":"Coordinador de telecomunicaciones / Coordinadora de telecomunicaciones"},{"codigo":"35222.002","nombre":"Supervisor de electricidad y telecomunicaciones / Supervisora de electricidad y telecomunicaciones"},{"codigo":"35222.003","nombre":"Supervisor de personal de instalación y reparación de telecomunicaciones / Supervisora de personal de instalación y reparación de telecomunicaciones"},{"codigo":"35222.004","nombre":"Supervisor de personal técnico de servicio y mantenimiento de televisión por cable / Supervisora de personal técnico de servicio y mantenimiento de televisión por cable"},{"codigo":"35222.005","nombre":"Supervisor de telecomunicaciones / Supervisora de telecomunicaciones"},{"codigo":"35222.006","nombre":"Supervisor de instalación y reparación de telecomunicaciones / Supervisora de instalación y reparación de telecomunicaciones"}],"conocimientos":[{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"11","nombre":"Diseño"},{"id":"23","nombre":"Idioma extranjero"},{"id":"10","nombre":"Ingeniería y tecnología"},{"id":"85","nombre":"Seguridad y salud en