  ('rol_cuoc', 'Operadores de radio / Operadoras de radio', '35223', 'Tecnologías de la información y las comunicaciones', 2, false, '{"codigo":"35223","nombre":"Operadores de radio / Operadoras de radio","descripcion":"Reciben, transmiten y graban señales y mensajes usando radios y otro equipo de comunicaciones. Se pueden desempeñar en compañías de transporte, explotaciones forestales, explotaciones mineras y otros establecimientos industriales, asociaciones privadas y por las fuerzas armadas, la policía, bomberos, salud y otros servicios de emergencia, compañías de taxi, servicios de entrega, establecimientos comerciales e industriales, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"3","nombre":"TÉCNICOS Y PROFESIONALES DEL NIVEL MEDIO"},"subgrupo_principal":{"codigo":"35","nombre":"TÉCNICOS EN TECNOLOGÍA DE LA INFORMACIÓN Y LAS COMUNICACIONES"},"subgrupo":{"codigo":"352","nombre":"Técnicos en telecomunicaciones y radiodifusión"},"grupo_primario":{"codigo":"3522","nombre":"Técnicos y operadores de ingeniería de las telecomunicaciones"}},"funciones":[{"consecutivo":1,"texto":"Identificar y resolver los problemas de telecomunicaciones que surjan en la radio operación."},{"consecutivo":2,"texto":"Operar equipo de radio para comunicarse con embarcaciones, aeronaves, cuadrillas de minería, equipos de trabajo en campamentos petroleros y otras operaciones remotas."},{"consecutivo":3,"texto":"Operar y asistir en el mantenimiento del equipo de comunicación fijo, aéreotransportable, móvil y naval en las Fuerzas Armadas."},{"consecutivo":4,"texto":"Recibir solicitudes de servicio de emergencia y contactar ambulancias, grupos de personas especializadas, departamentos de bomberos, policía y servicio de grúa."},{"consecutivo":5,"texto":"Procesar y transmitir información e instrucciones para coordinar las actividades de los conductores, las tripulaciones y el equipo auxiliar, utilizando diferentes medios de comunicación y despacho."},{"consecutivo":6,"texto":"Despachar el personal de acuerdo con las programaciones escritas y órdenes de trabajo o según las situaciones de emergencia que se presenten."},{"consecutivo":7,"texto":"Informar a los operadores de vehículos sobre problemas de tráfico como: accidentes, congestión, condiciones climáticas y otras situaciones."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"35223.001","nombre":"Operador de código morse / Operadora de código morse"},{"codigo":"35223.002","nombre":"Operador de equipo de radio con base en mar / Operadora de equipo de radio con base en mar"},{"codigo":"35223.003","nombre":"Operador de equipo de radio con base en tierra / Operadora de equipo de radio con base en tierra"},{"codigo":"35223.004","nombre":"Operador de equipo de radio de vuelo / Operadora de equipo de radio de vuelo"},{"codigo":"35223.005","nombre":"Operador de radio / Operadora de radio"},{"codigo":"35223.006","nombre":"Operador de radio navegación aérea / Operadora de radio navegación aérea"},{"codigo":"35223.007","nombre":"Operador de radio navegación marítima / Operadora de radio navegación marítima"},{"codigo":"35223.008","nombre":"Radio operador / Radio operadora"},{"codigo":"35223.009","nombre":"Radionavegante"},{"codigo":"35223.010","nombre":"Radiotelefonista de estaciones terrestres"},{"codigo":"35223.011","nombre":"Operador de radiocomunicaciones / Operadora de radiocomunicaciones"}],"conocimientos":[{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"14","nombre":"Matemáticas"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"},{"id":"29","nombre":"Telecomunicación"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"15","nombre":"Orientación al servicio"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"16","nombre":"Resolución de problemas complejos"}],"ocupaciones_afines":[{"codigo":"21521","nombre":"Ingenieros electrónicos / Ingenieras electrónicas"},{"codigo":"54199","nombre":"Personal de los servicios de protección no clasificadas en otras ocupaciones"},{"codigo":"74221","nombre":"Técnicos instaladores de redes y líneas de telecomunicaciones / Técnicas instaladoras de redes y líneas de telecomunicaciones"}],"area_principal":{"sigla":"TICO","nombre":"Tecnologías de la información y las comunicaciones"},"areas_complementarias":[{"sigla":"AVEM","nombre":"Audiovisuales, Artes Escénicas y Música"}],"equivalencias":[{"ciuo08_codigo":"3522*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"1373*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Oficinistas generales', '41101', 'Administración, finanzas y derecho', 2, true, '{"codigo":"41101","nombre":"Oficinistas generales","descripcion":"Realizan diversas funciones de apoyo administrativo y de oficina según procedimientos establecidos como guías, manuales, procesos técnicos y normas; preparación del material de archivo para los procesos de gestión documental de la entidad. Se pueden desempeñar en oficinas administrativas de cualquier sector económico, en empresas del sector público y privado, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"41","nombre":"OFICINISTAS"},"subgrupo":{"codigo":"411","nombre":"Oficinistas generales"},"grupo_primario":{"codigo":"4110","nombre":"Oficinistas generales"}},"funciones":[{"consecutivo":1,"texto":"Registrar, preparar, ordenar, clasificar, codificar y archivar información y correspondencia, de acuerdo con los índices de sistemas de clasificación y gestión documental."},{"consecutivo":2,"texto":"Clasificar, abrir y enviar correos, hacer seguimiento y control a la correspondencia, incluyendo la radicación de acuerdo con horarios de entrada y salida y prepararlos para su disponibilidad."},{"consecutivo":3,"texto":"Brindar atención y orientación a clientes internos y externos, sobre la organización o los aspectos relacionados con su dependencia."},{"consecutivo":4,"texto":"Elaborar y apoyar al personal de la dependencia en la transcripción, la presentación de informes y documentos de la unidad administrativa de acuerdo con lineamientos de la organización, guía y procedimientos técnicos."},{"consecutivo":5,"texto":"Digitar y transcribir información en ordenadores, revisar y corregir textos de acuerdo con estándares y procedimientos técnicos."},{"consecutivo":6,"texto":"Registrar equipos asignados al personal."},{"consecutivo":7,"texto":"Informar al personal y público en general sobre reglas y procedimientos de la empresa."},{"consecutivo":8,"texto":"Clasificar documentos para microfilmación, operar sistemas de captura de información y facilitar documentos requeridos."},{"consecutivo":9,"texto":"Fotocopiar documentos para distribución, correo y archivo."},{"consecutivo":10,"texto":"Recepcionar llamadas telefónicas operando los medios técnicos disponibles y entregar los mensajes respectivos."},{"consecutivo":11,"texto":"Apoyar al personal de la dependencia en la elaboración y el seguimiento de los proyectos, trámites administrativos de la unidad que se requiera para el cumplimiento de su finalidad de acuerdo al procedimientos técnicos."},{"consecutivo":12,"texto":"Mantener listas de acceso de registros clasificados."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"41101.001","nombre":"Auxiliar administrativo / Auxiliar administrativa"},{"codigo":"41101.002","nombre":"Auxiliar de admisiones"},{"codigo":"41101.003","nombre":"Auxiliar de documentación"},{"codigo":"41101.004","nombre":"Auxiliar de fotocopiado en oficina"},{"codigo":"41101.006","nombre":"Auxiliar de oficina"},{"codigo":"41101.007","nombre":"Auxiliar de radicación"},{"codigo":"41101.008","nombre":"Oficinista"},{"codigo":"41101.009","nombre":"Oficinista general"},{"codigo":"41101.010","nombre":"Radicador de documentos / Radicadora de documentos"}],"conocimientos":[{"id":"56","nombre":"Bibliotecología, información y archivología"},{"id":"6","nombre":"Gestión del talento humano y de personal"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"50","nombre":"Servicio a la persona y humanización"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"15","nombre":"Orientación al servicio"},{"id":"3","nombre":"Redacción de textos"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"34","nombre":"Trabajo bajo presión"},{"i