  ('rol_cuoc', 'Auxiliares de aduana', '41102', 'Logística y transporte', 2, false, '{"codigo":"41102","nombre":"Auxiliares de aduana","descripcion":"Realizan diversas funciones administrativas y de apoyo en procesamiento de documentación y formularios aduaneros como su recopilación, verificación, registro y trámites para solicitudes, licencias, permisos, declaración e inscripciones de acuerdo con pautas, programación y procedimientos establecidos. Se pueden desempeñar en empresas de logística de carga y transporte, agencias aduaneras, puertos, departamentos de comercio exterior, sector público y privado, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"41","nombre":"OFICINISTAS"},"subgrupo":{"codigo":"411","nombre":"Oficinistas generales"},"grupo_primario":{"codigo":"4110","nombre":"Oficinistas generales"}},"funciones":[{"consecutivo":1,"texto":"Registrar, preparar, ordenar, clasificar y archivar información de importación y exportación según normatividad vigente y procedimientos establecidos."},{"consecutivo":2,"texto":"Brindar apoyo en el proceso de formalización de documentos según normativa aduanera."},{"consecutivo":3,"texto":"Apoyar los trámites de documentos según normativa aduanera. Participar y apoyar en la preinspección de mercancías según normativa vigente."},{"consecutivo":4,"texto":"Apoyar los trámites, procesos y requerimientos administrativos del área de comercio exterior o dependencia."},{"consecutivo":5,"texto":"Apoyar los procesos vinculados a pagos de impuestos, fianzas para cubrir derechos de aduana, bodegaje y transporte de mercancía importada y exportada."},{"consecutivo":6,"texto":"Clasificar, abrir y enviar correos."},{"consecutivo":7,"texto":"Brindar atención y orientación a los funcionarios sobre aspectos relacionados con su dependencia."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"41102.001","