  ('rol_cuoc', 'Secretarios generales / Secretarias generales', '41200', 'Administración, finanzas y derecho', 2, false, '{"codigo":"41200","nombre":"Secretarios generales / Secretarias generales","descripcion":"Realizan funciones de secretariado a empleados, profesionales, directivos y gerentes, utilizan herramientas ofimáticas, computadoras y otros equipos de procesamiento de texto para transcribir correspondencia y otros documentos; verifican y dan formato a documentos preparados por otros funcionarios; revisan correo entrante y saliente, manejan agendas, concretan citas para reuniones y realizan funciones de apoyo administrativo. Se pueden desempeñar en departamentos de empresas del sector privado o público, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"41","nombre":"OFICINISTAS"},"subgrupo":{"codigo":"412","nombre":"Secretarios generales"},"grupo_primario":{"codigo":"4120","nombre":"Secretarios generales"}},"funciones":[{"consecutivo":1,"texto":"Verificar formatos, ortografía, gramática, puntuación y transcribiendo correspondencia, actas e informes a partir de dictados, documentos electrónicos o borradores, utilizando máquinas de escribir, computadores personales u otros equipos de tratamiento de textos."},{"consecutivo":2,"texto":"Atender clientes de acuerdo con procedimiento de servicios y normativa."},{"consecutivo":3,"texto":"Registrar información en sistemas en de la unidad administrativa y contable, uso de diversos paquetes de software para proporcionar apoyo administrativo de acuerdo con lineamientos, normativa y procedimientos técnicos."},{"consecutivo":4,"texto":"Procesar el correo electrónico, correspondencia entrante y saliente, reciben, clasificando y distribuyendo las comunicaciones y otros documentos de acuerdo con el procedimiento de la organización por iniciativa propia."},{"consecutivo":5,"texto":"Elaborar documentos de la unidad administrativa de acuerdo con lineamientos, guía y procedimientos técnicos."},{"consecutivo":6,"texto":"Aplicar los procedimientos establecidos de acuerdo con las políticas de la organización."},{"consecutivo":7,"texto":"Programar y confirmar actividades y reuniones administrativas de la unidad administrativa de acuerdo con procedimientos técnicos y organizacionales."},{"consecutivo":8,"texto":"Organizar, programar y confirmar la agenda, actividades y reuniones administrativas de la unidad administrativa de acuerdo con procedimientos técnicos y organizacionales."},{"consecutivo":9,"texto":"Controlar y tramitar pedidos de la unidad administrativa de acuerdo con procesos administrativos."},{"consecutivo":10,"texto":"Efectuar el seguimiento y registro de las vacaciones y de otros derechos del personal."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"41200.001","nombre":"Datain en petróleo y gas"},{"codigo":"41200.003","nombre":"Secretario / Secretaria"},{"codigo":"41200.004","nombre":"Secretario auxiliar contable / Secretaria auxiliar contable"},{"codigo":"41200.005","nombre":"Secretario de procesamiento de textos / Secretaria de procesamiento de textos"},{"codigo":"41200.006","nombre":"Secretario general / Secretaria general"},{"codigo":"41200.007","nombre":"Secretario mecanógrafo / Secretaria mecanógrafa"},{"codigo":"41200.008","nombre":"Secretario recepcionista / Secretaria recepcionista"},{"codigo":"41200.009","nombre":"Secretario taquígrafo / Secretaria taquígrafa"},{"codigo":"41200.010","nombre":"Secretario / Secretaria"}],"conocimientos":[{"id":"28","nombre":"Leyes y gobierno"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"50","nombre":"Servicio a la persona y humanización"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"15","nombre":"Orientación al servicio"},{"id":"3","n