  ('rol_cuoc', 'Grabadores de datos / Grabadoras de datos', '41321', 'Administración, finanzas y derecho', 2, false, '{"codigo":"41321","nombre":"Grabadores de datos / Grabadoras de datos","descripcion":"Procesan y almacenan información e imágenes a partir de material fuente, introducen datos codificados de índole estadística, financiera y de otro tipo en equipos electrónicos, bases de datos electrónicas, hojas de cálculo u otros repositorios de datos utilizando tecnologías de almacenamiento y software de reconocimiento de voz, teclado, ratón o escáner y reconocimiento óptico, incluyendo otras herramientas que permiten registrar este tipo de información. Los datos se introducen en dispositivos mecánicos y electrónicos con el fin de realizar cálculos matemáticos. Se pueden desempeñar en centros de cómputo o por empresas del sector público y privado, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"41","nombre":"OFICINISTAS"},"subgrupo":{"codigo":"413","nombre":"Operadores de máquinas de oficina"},"grupo_primario":{"codigo":"4132","nombre":"Grabadores de datos y digitadores"}},"funciones":[{"consecutivo":1,"texto":"Recibir y alistar los documentos como facturas, formularios, registros y otros documentos con fines de captura de datos y equipos requeridos para la digitalización teniendo en cuenta las características técnicas del proceso."},{"consecutivo":2,"texto":"Realizar el proceso de digitalización de documentos utilizando los medios tecnológicos actualizados, transcribiendo datos numéricos, códigos y textos contenidos en materiales originales e introducirlos en dispositivos de almacenamiento y procesamiento compatibles con sistemas informáticos."},{"consecutivo":3,"texto":"Verificar la exactitud y exhaustividad de los datos y la calidad de imágenes y, de ser necesario, corregirlos ya introducidos."},{"consecutivo":4,"texto":"Almacenar archivos generados del proceso de digitalización, en soportes recomendados para su preservación."},{"consecutivo":5,"texto":"Importar y exportar datos entre distintos sistemas y software de bases de datos."},{"consecutivo":6,"texto":"Indexar imágenes en el sistema de información."},{"consecutivo":7,"texto":"Manejar máquinas de cálculo aritmético y máquinas de contabilidad."},{"consecutivo":8,"texto":"Registrar datos codificados, estadísticos y financieros en las bases de datos o los sistemas establecidos."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"41321.001","nombre":"Auxiliar de entrada de datos"},{"codigo":"41321.002","nombre":"Digitalizador / Digitalizadora"},{"codigo":"41321.003","nombre":"Empleado de máquina sumadora / Empleada de máquina sumadora"},{"codigo":"41321.004","nombre":"Operador de calculadora / Operadora de calculadora"},{"codigo":"41321.005","nombre":"Operador de contómetro / Operadora de contómetro"},{"codigo":"41321.006","nombre":"Operador de entrada de datos / Operadora de entrada de datos"},{"codigo":"41321.007","nombre":"Operador de facturadora / Operadora de facturadora"},{"codigo":"41321.008","nombre":"Operador de máquina contable / Operadora de máquina contable"},{"codigo":"41321.009","nombre":"Operador de máquina verificadora / Operadora de máquina verificadora"},{"codigo":"41321.010","nombre":"Operador de máquinas de llevar libros / Operadora de máquinas de llevar libros"},{"codigo":"41321.011","nombre":"Procesador de datos / Procesadora de datos"},{"codigo":"41321.012","nombre":"Registrador de datos / Registradora de datos"},{"codigo":"41321.013","nombre":"Tabulador de datos / Tabuladora de datos"},{"codigo":"41321.014","nombre":"Técnico de introducción de datos / Técnica de introducción de datos"},{"codigo":"41321.015","nombre":"Técnico de entrada y procesamiento de datos / Técnica de entrada y procesamiento de datos"}],"conocimientos":[{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"36","nombre