  ('rol_cuoc', 'Receptores de apuestas y afines / Receptoras de apuestas y afines', '42120', 'Actividades físicas, deportivas y recreativas', 2, false, '{"codigo":"42120","nombre":"Receptores de apuestas y afines / Receptoras de apuestas y afines","descripcion":"Calculan probabilidades, reciben y pagan apuestas sobre resultados de eventos deportivos o de otra índole y gestionan, operan juegos de azar, mecánicos y de salón en establecimientos dedicados a tal actividad. Se pueden desempeñar en casinos, casas o medios virtuales de apuestas, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"42","nombre":"EMPLEADOS DE TRATO DIRECTO CON EL PÚBLICO"},"subgrupo":{"codigo":"421","nombre":"Pagadores y cobradores de ventanilla y afines"},"grupo_primario":{"codigo":"4212","nombre":"Receptores de apuestas y afines"}},"funciones":[{"consecutivo":1,"texto":"Determinar cuáles son los riesgos para definir las probabilidades de apuestas, cubrir o rechazar apuestas y garantizar que se cumplan las reglas del juego."},{"consecutivo":2,"texto":"Preparar y publicar listas de probabilidades aproximadas para las apuestas."},{"consecutivo":3,"texto":"Operar mesas de juegos como ruleta, blackjack, keno y distribuir juegos de naipes, tirar dados o girar ruletas."},{"consecutivo":4,"texto":"Operar juegos mecánicos, juegos autorizados y otras atracciones y diversiones de apuestas y azar."},{"consecutivo":5,"texto":"Anunciar números ganadores, determinar, calcular y pagar a los acertantes y cobrar los pagos de perdedores."},{"consecutivo":6,"texto":"Explicar e interpretar las normas de funcionamiento de un establecimiento de juego de azar."},{"consecutivo":7,"texto":"Inspeccionar los juegos para su mantenimiento y actividades de mejora para y garantizar la seguridad de los usuarios."},{"consecutivo":8,"texto":"Instruir a los auxiliares de juegos de azar y apuestas."},{"consecutivo":9,"texto":"Vender tiquetes, fichas y registrar apuestas y juegos de azar."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"42120.001","nombre":"Auxiliar de apuestas"},{"codigo":"42120.002","nombre":"Banquero de sala de juego / Banquera de sala de juego"},{"codigo":"42120.003","nombre":"Corredor de apuestas / Corredora de apuestas"},{"codigo":"42120.004","nombre":"Crupier"},{"codigo":"42120.005","nombre":"Diller"},{"codigo":"42120.006","nombre":"Distribuidor de juegos / Distribuidora de juegos"},{"codigo":"42120.007","nombre":"Escrutador de chance / Escrutadora de chance"},{"codigo":"42120.008","nombre":"Garitero / Garitera"},{"codigo":"42120.009","nombre":"Operador de bingo / Operadora de bingo"},{"codigo":"42120.010","nombre":"Receptor de apuestas / Receptora de apuestas"},{"codigo":"42120.011","nombre":"Recibidor de apuestas / Recibidora de apuestas"},{"codigo":"42120.012","nombre":"Tallador de juego / Talladora de juego"},{"codigo":"42120.013","nombre":"Tallador de mesa de juegos de azar / Talladora de mesa de juegos de azar"}],"conocimientos":[{"id":"28","nombre":"Leyes y gobierno"},{"id":"14","nombre":"Matemáticas"},{"id":"4","nombre":"Mercadotecnia y publicidad"},{"id":"5","nombre":"Servicio al cliente"},{"id":"95","nombre":"Ventas al por mayor y al por menor"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"5","nombre":"Lógica matemática"},{"id":"15","nombre":"Orientación al servicio"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"12","nombre":"Persuasión"},{"id":"10","nombre":"Relaciones interpersonales"}],"ocupaciones_afines":[{"codigo":"42140","nombre":"Cobradores, auxiliares de cartera y afines / Cobradoras, auxiliares de cartera y afines"},{"codigo":"52110","nombre":"Vendedores en quioscos y puestos de mercado / Vendedoras en quioscos y puestos de mercado"},{"codigo":"52300","nombre":"Cajeros de comercio, taquilleros y expendedores de boletas / Cajer