  ('rol_cuoc', 'Prestamistas', '42130', 'Administración, finanzas y derecho', 2, false, '{"codigo":"42130","nombre":"Prestamistas","descripcion":"Presupuestan y prestan dinero a cambio del depósito de prendas de garantía constituidas por bienes y otros valores. Se pueden desempeñar en establecimientos financieros, de crédito, cooperativas, casas de cambio, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"42","nombre":"EMPLEADOS DE TRATO DIRECTO CON EL PÚBLICO"},"subgrupo":{"codigo":"421","nombre":"Pagadores y cobradores de ventanilla y afines"},"grupo_primario":{"codigo":"4213","nombre":"Prestamistas"}},"funciones":[{"consecutivo":1,"texto":"Evaluar artículos ofrecidos en prenda, calcular los intereses y prestar dinero a cambio del depósito de las prendas."},{"consecutivo":2,"texto":"Prestar dinero en forma de créditos personales cuyas garantías se constituyen sobre el producto de cosechas futuras y de otras empresas similares."},{"consecutivo":3,"texto":"Recuperar los créditos concedidos ejecutando las garantías constituidas sobre el producto generado por cosechas y otras empresas similares."},{"consecutivo":4,"texto":"Devolver artículos en prenda cuando se reembolsen los préstamos o, en caso de falta de pago, vender dichos artículos."},{"consecutivo":5,"texto":"Llevar un registro de los préstamos y artículos recibidos, calcular los intereses y cobrar el importe cuando sea retirada la prenda."},{"consecutivo":6,"texto":"Proyectar presupuestos y autorizar préstamos."},{"consecutivo":7,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"42130.001","nombre":"Ayudante de casa de empeño"},{"codigo":"42130.002","nombre":"Prestamista"},{"codigo":"42130.003","nombre":"Prestamista de dinero"},{"codigo":"42130.004","nombre":"Prestamista prendario / Prestamista prendaria"}],"conocimientos":[{"id":"32","nombre":"Contabilidad e impuestos"},{"id":"3","nombre"