  ('rol_cuoc', 'Cobradores, auxiliares de cartera y afines / Cobradoras, auxiliares de cartera y afines', '42140', 'Administración, finanzas y derecho', 2, false, '{"codigo":"42140","nombre":"Cobradores, auxiliares de cartera y afines / Cobradoras, auxiliares de cartera y afines","descripcion":"Tramitan las operaciones activas de crédito y el cobro de pagos correspondientes a cuentas vencidas, cheques sin fondos y recaudan contribuciones; evalúan el riesgo crediticio de las diferentes solicitudes, realizan procesos de análisis de información para ubicar a deudores y convenir formas de pagos. Se pueden desempeñar en compañías de cobranzas, empresas de servicios públicos, departamentos de cartera, entidades financieras, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"42","nombre":"EMPLEADOS DE TRATO DIRECTO CON EL PÚBLICO"},"subgrupo":{"codigo":"421","nombre":"Pagadores y cobradores de ventanilla y afines"},"grupo_primario":{"codigo":"4214","nombre":"Cobradores, auxiliares de cartera y afines"}},"funciones":[{"consecutivo":1,"texto":"Llamar, escribir y notificar a deudores por diferentes canales como dispositivos telefónicos, personalmente o por correo, sobre pagos y cuentas vencidas, cobrar el dinero adeudado, concertar pagos ulteriores y continuar el proceso de notificación si la respuesta no ha sido obtenida."},{"consecutivo":2,"texto":"Visitar a deudores para recoger la deuda o llegar a acuerdos de pago."},{"consecutivo":3,"texto":"Buscar y localizar a deudores."},{"consecutivo":4,"texto":"Llevar registro de direcciones y datos de contacto de los clientes."},{"consecutivo":5,"texto":"Recuperar cartera contactando a los morosos a través de medios telefónicos o electrónicos, de acuerdo con normativa financiera."},{"consecutivo":6,"texto":"Recomendar el inicio de acciones y trámites legales o la suspensión de la prestación de servicios en casos de no pago o cartera castigada y cuando se hayan agotado las maneras de obtener el reembolso."},{"consecutivo":7,"texto":"Solicitar y recaudar contribuciones destinadas a obras de caridad."},{"consecutivo":8,"texto":"Negociar acuerdos de pago según normativa financiera y guía técnica."},{"consecutivo":9,"texto":"Contestar la correspondencia, preparar informes y mantener los registros y los archivos relacionados."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"42140.001","nombre":"Auxiliar de cartera y cobranzas"},{"codigo":"42140.002","nombre":"Auxiliar de cobranza y facturación"},{"codigo":"42140.003","nombre":"Auxiliar de crédito y cobranzas"},{"codigo":"42140.004","nombre":"Auxiliar de cartera"},{"codigo":"42140.005","nombre":"Auxiliar de cobranza"},{"codigo":"42140.006","nombre":"Auxiliar de crédito de cartera"},{"codigo":"42140.007","nombre":"Auxiliar de recaudos"},{"codigo":"42140.008","nombre":"Cobrador / Cobradora"},{"codigo":"42140.009","nombre":"Cobrador de alquileres / Cobradora de alquileres"},{"codigo":"42140.010","nombre":"Cobrador de deudas / Cobradora de deudas"},{"codigo":"42140.011","nombre":"Cobrador de donativos de obras de caridad / Cobradora de donativos de obras de caridad"},{"codigo":"42140.012","nombre":"Cobrador de facturas / Cobradora de facturas"},{"codigo":"42140.013","nombre":"Cobrador externo / Cobradora externa"},{"codigo":"42140.014","nombre":"Cobrador recaudador / Cobradora recaudadora"},{"codigo":"42140.015","nombre":"Gestor de cobro / Gestora de cobro"},{"codigo":"42140.016","nombre":"Recaudador / Recaudadora"},{"codigo":"42140.017","nombre":"Visitador de cobranzas / Visitadora de cobranzas"}],"conocimientos":[{"id":"32","nombre":"Contabilidad e impuestos"},{"id":"33","nombre":"Gestión financiera, administración bancaria y seguros"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"14","nombre":"Matemáticas"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}