  ('rol_cuoc', 'Empleados de ventas y servicios de viajes / Empleadas de ventas y servicios de viajes', '42210', 'Turismo, hotelería y gastronomía', 2, false, '{"codigo":"42210","nombre":"Empleados de ventas y servicios de viajes / Empleadas de ventas y servicios de viajes","descripcion":"Preparan y comercializan viajes y paquetes turísticos o corporativos, tramitan reservas de alojamiento y traslados, emiten tiquetes, orientan acerca de los destinos, organizan itinerarios y diferentes opciones de viaje; registran los datos de los pasajeros y asesoran en las puertas de embarque en los servicios de transporte de líneas áreas, marítimas y terrestres. Se pueden desempeñar en agencias de viajes y empresas aliadas de turismo y transporte, aerolíneas, cruceros, empresas de transporte terrestre, cadenas de hoteles, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"42","nombre":"EMPLEADOS DE TRATO DIRECTO CON EL PÚBLICO"},"subgrupo":{"codigo":"422","nombre":"Empleados de servicios de información al cliente"},"grupo_primario":{"codigo":"4221","nombre":"Empleados de ventas y servicios de viajes"}},"funciones":[{"consecutivo":1,"texto":"Obtener información sobre las necesidades de los clientes y la disponibilidad, los costos y las ventajas de los diferentes tipos de transporte y alojamiento."},{"consecutivo":2,"texto":"Proporcionar información y suministrar mapas y folletos sobre las atracciones locales, regionales, excursiones, restaurantes, centros de arte y entretenimiento."},{"consecutivo":3,"texto":"Planear, coordinar y preparar itinerarios, paquetes turísticos o corporativos teniendo en cuenta los requerimientos del cliente."},{"consecutivo":4,"texto":"Preparar reservaciones y expedir tiquetes, asignar sillas, generar pasabordos, revisar equipajes, registrar pasajeros, atender las entradas de abordaje y ayudar a los viajeros en el preabordo."},{"consecutivo":5,"texto":"Ayudar a los clientes a tramitar los requisitos de visado, servicios consulares y demás documentos de viaje necesarios de acuerdo con procedimientos técnicos."},{"consecutivo":6,"texto":"Asesorar y brindar servicios orientados a dar comodidad a los pasajeros en cabina y asistencia en tierra de acuerdo con las políticas de servicio al cliente establecido por la organización."},{"consecutivo":7,"texto":"Realizar y confirmar reservaciones de viajes, excursiones, transporte, alojamiento y demás servicios de acuerdo con lo contratado por el cliente y procedimientos técnicos."},{"consecutivo":8,"texto":"Asesorar sobre destinos e itinerarios, planes de viaje, opciones de transporte, alojamiento, costos, servicios conexos, requisitos, documentación y condiciones específicas del viaje de acuerdo con requerimientos del cliente."},{"consecutivo":9,"texto":"Apoyar en el diligenciamiento y verificación de registro de pasajeros, equipaje, facturación, embarque y documentos relacionados al servicio de transporte de acuerdo con procedimientos establecidos."},{"consecutivo":10,"texto":"Emitir tiquetes y baucher de servicios hoteleros."},{"consecutivo":11,"texto":"Preparar facturas y recibir pagos."},{"consecutivo":12,"texto":"Comercializar paquetes de viajes o corporativos, tiquetes y otros servicios turísticos teniendo en cuenta los requerimientos del cliente y de acuerdo con las políticas de la organización."},{"consecutivo":13,"texto":"Realizar actividades de postventa del servicio adquirido por el viajero de acuerdo con los procedimientos establecidos por la organización."},{"consecutivo":14,"texto":"Ejecutar las actividades de los servicios que hayan sido pactados en convenios y alianzas empresariales según políticas de la organización."},{"consecutivo":15,"texto":"Preparar reportes e informes de acuerdo con procedimientos técnicos de la organización."},{"consecutivo":16,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"42210.001","nombre":"Agente de carga d