  ('rol_cuoc', 'Empleados de centros de llamadas / Empleadas de centros de llamadas', '42220', 'Administración, finanzas y derecho', 2, false, '{"codigo":"42220","nombre":"Empleados de centros de llamadas / Empleadas de centros de llamadas","descripcion":"Brindan asesoría e información a los clientes, responden preguntas sobre los bienes, productos, servicios, procesos o políticas de una empresa o de una organización con el fin de resolver las inquietudes regulares o canalizar los requerimientos al área correspondiente, procesan transacciones financieras y recaudan cartera mediante el teléfono o medios electrónicos de comunicación. Los centros de llamadas pueden estar ubicados a gran distancia de la ubicación de los clientes o de otras organizaciones o empresas representadas. Se pueden desempeñar en establecimientos de comercio, compañías de seguros, empresas de servicio público, consorcios turísticos, contact center, establecimientos del sector público y privado, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"42","nombre":"EMPLEADOS DE TRATO DIRECTO CON EL PÚBLICO"},"subgrupo":{"codigo":"422","nombre":"Empleados de servicios de información al cliente"},"grupo_primario":{"codigo":"4222","nombre":"Empleados de centros de llamadas"}},"funciones":[{"consecutivo":1,"texto":"Atender llamadas, mensajes y preguntas de los clientes, ya sea para responder consultas, gestionar sus demandas de servicios específicos o para resolver quejas en relación con servicios prestados, procedimientos y productos."},{"consecutivo":2,"texto":"Operar sistemas de enlistados de directorio informático o convencional indicando requisitos e introduciendo en el sistema datos sobre eventos, productos, servicios entre otros, para brindar información a clientes."},{"consecutivo":3,"texto":"Registrar y procesar la información objeto de consulta, para optimizar la prestación del servicio."},{"consecutivo":4,"texto":"Operar sistemas de conmutador para realizar, recibir y distribuir llamadas telefónicas, tomar mensajes y suministrar la información básica requerida."},{"consecutivo":5,"texto":"Brindar información telefónica a clientes y público sobre artículos, servicios, horarios, tarifas y reglamentaciones."},{"consecutivo":6,"texto":"Operar medios de comunicación telefónica y electrónica para servicio al cliente."},{"consecutivo":7,"texto":"Remitir tareas a otras unidades cuando sea pertinente."},{"consecutivo":8,"texto":"Enviar cartas, hojas informativas y otros documentos a los clientes."},{"consecutivo":9,"texto":"Contactar a morosos a través de teléfonos o medios electrónicos para cobrar, concertar pagos y recuperar cartera."},{"consecutivo":10,"texto":"Emitir facturas o tramitar pagos cuando sea pertinente."},{"consecutivo":11,"texto":"Cumplir con indicadores de eficiencia, calidad, directrices y políticas de la empresa."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"42220.001","nombre":"Agente de contact center de cobranzas"},{"codigo":"42220.002","nombre":"Agente de call center cobranzas"},{"codigo":"42220.003","nombre":"Agente de contact center"},{"codigo":"42220.004","nombre":"Asesor de call center / Asesora de call center"},{"codigo":"42220.005","nombre":"Asesor de contact center / Asesora de contact center"},{"codigo":"42220.006","nombre":"Auxiliar de centro de llamadas"},{"codigo":"42220.007","nombre":"Auxiliar de información al cliente centro de llamadas"},{"codigo":"42220.008","nombre":"Consultor de call center / Consultora de call center"},{"codigo":"42220.009","nombre":"Entrenador de centro de contacto / Entrenadora de centro de contacto"},{"codigo":"42220.010","nombre":"Entrenador telefónico / Entrenadora telefónica"},{"codigo":"42220.011","nombre":"Operador de centro de llamadas / Operadora de centro de llamadas"},{"codigo":"42220.012","nombre":"Operador de conmutador / Operadora de conmutador"},{"c