  ('rol_cuoc', 'Telefonistas', '42230', 'Administración, finanzas y derecho', 2, false, '{"codigo":"42230","nombre":"Telefonistas","descripcion":"Operan centrales y sistemas de comunicación telefónica y consolas para establecer conexiones por esta vía, asisten a los usuarios para resolver problemas de comunicación, establecer llamadas locales o de larga distancia, grabar mensajes y, remitir mensajes a otros miembros del personal o a clientes. Se pueden desempeñar en compañías de teléfono, empresas de transporte, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"42","nombre":"EMPLEADOS DE TRATO DIRECTO CON EL PÚBLICO"},"subgrupo":{"codigo":"422","nombre":"Empleados de servicios de información al cliente"},"grupo_primario":{"codigo":"4223","nombre":"Telefonistas"}},"funciones":[{"consecutivo":1,"texto":"Manejar centrales telefónicas para conectar, mantener, transferir o colgar llamadas telefónicas"},{"consecutivo":2,"texto":"Realizar las conexiones para llamadas salientes."},{"consecutivo":3,"texto":"Atender pedidos de información telefónica, responder preguntas, registrar y grabar mensajes."},{"consecutivo":4,"texto":"Operar sistemas de teléfonos para establecer la comunicación entre el solicitante y la persona a quien va dirigida la llamada, bien sea local, de larga distancia, radio teléfono móvil, entre otros."},{"consecutivo":5,"texto":"Transferir llamadas a miembros del personal o a clientes."},{"consecutivo":6,"texto":"Investigar problemas del sistema operativo e informar a los servicios de reparación."},{"consecutivo":7,"texto":"Registrar la cuantía de las conferencias."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"42230.001","nombre":"Ayudante de cabina telefónica"},{"codigo":"42230.002","nombre":"Operador de central telefónica / Operadora de central telefónica"},{"codigo":"42230.003","nombre":"Operador de larga dist