  ('rol_cuoc', 'Informadores turísticos / Informadoras turísticas', '42252', 'Turismo, hotelería y gastronomía', 2, false, '{"codigo":"42252","nombre":"Informadores turísticos / Informadoras turísticas","descripcion":"Suministran y responden preguntas sobre información turística, teniendo en cuenta las necesidades o expectativas tanto de los turistas como del territorio donde ejerce su actividad. Se pueden desempeñar en entidades gubernamentales, establecimientos de turismo y comercio, clubes, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"42","nombre":"EMPLEADOS DE TRATO DIRECTO CON EL PÚBLICO"},"subgrupo":{"codigo":"422","nombre":"Empleados de servicios de información al cliente"},"grupo_primario":{"codigo":"4225","nombre":"Empleados de ventanillas de información"}},"funciones":[{"consecutivo":1,"texto":"Informar sobre los atractivos turísticos del destino o la región según las necesidades y expectativas del visitante y protocolos de servicio."},{"consecutivo":2,"texto":"Suministrar información de servicios conexos del destino turístico de acuerdo con las necesidades y expectativas del visitante y protocolos de servicio."},{"consecutivo":3,"texto":"Recolectar y procesar datos de indicadores turísticos según procedimientos técnicos."},{"consecutivo":4,"texto":"Resolver inquietudes sobre los procedimientos de beneficios y reclamos de los visitantes sobre los servicios turísticos."},{"consecutivo":5,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"42252.001","nombre":"Auxiliar de información turística"},{"codigo":"42252.002","nombre":"Informador turístico / Informadora turística"},{"codigo":"42252.003","nombre":"Informador turístico local / Informadora turística local"}],"conocimientos":[{"id":"73","nombre":"Hotelería, restaurantes y servicios de banquetes"},{"id":"23","nombre":"Idioma extranjero"},{"id":"36","nombre":"Manejo de las TIC"},{"i