  ('rol_cuoc', 'Recepcionistas generales', '42260', 'Administración, finanzas y derecho', 2, false, '{"codigo":"42260","nombre":"Recepcionistas generales","descripcion":"Reciben y dan la bienvenida a los visitantes, clientes, pacientes y personal que llegan a las oficinas, hospitales y otros establecimientos, orientan hacia la persona o servicio apropiado, responden a preguntas y solicitudes, inclusive con respecto a la concertación de citas, operan sistemas telefónicos, contestan y toman mensajes y realizan otras funciones de oficina. Se pueden desempeñar en hospitales, consultorios médicos y dentales, oficinas de atención permanente al público en el sector público y privado, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"42","nombre":"EMPLEADOS DE TRATO DIRECTO CON EL PÚBLICO"},"subgrupo":{"codigo":"422","nombre":"Empleados de servicios de información al cliente"},"grupo_primario":{"codigo":"4226","nombre":"Recepcionistas generales"}},"funciones":[{"consecutivo":1,"texto":"Recibir, dar bienvenida y brindar información básica al personal, visitantes, pacientes o clientes que llegan a las oficinas, hospitales y otros establecimientos."},{"consecutivo":2,"texto":"Atender y orientar al cliente."},{"consecutivo":3,"texto":"Operar sistemas, conmutador, contestar, atender solicitudes y distribuir llamadas telefónicas, tomar mensajes, suministrar la información básica requerida y concertar citas si es necesario."},{"consecutivo":4,"texto":"Recibir documentación y tramitar cualquier solicitud de servicio del cliente, bien sea de forma presente, por teléfono o correo electrónico y remitir al interesado."},{"consecutivo":5,"texto":"Orientar a los clientes en la localización de personas o lugares."},{"consecutivo":6,"texto":"Recibir y entrevistar pacientes para obtener la información requerida para la provisión de servicios."},{"consecutivo":7,"texto":"Entregar a los clientes formularios, folletos y carpetas de información."},{"consecutivo":8,"texto":"Proporcionar todo tipo de información y asistencia."},{"consecutivo":9,"texto":"Operar sistemas de listado de directorio computarizado o convencional para brindar información a clientes."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"42260.001","nombre":"Auxiliar de consultas"},{"codigo":"42260.002","nombre":"Auxiliar de recepción"},{"codigo":"42260.003","nombre":"Empleado de recepción / Empleada de recepción"},{"codigo":"42260.004","nombre":"Recepcionista"},{"codigo":"42260.005","nombre":"Recepcionista de consultorio médico"},{"codigo":"42260.006","nombre":"Recepcionista de consultorio odontológico"},{"codigo":"42260.007","nombre":"Recepcionista operador de conmutador / Recepcionista operadora de conmutador"},{"codigo":"42260.008","nombre":"Recepcionista teleoperadora"},{"codigo":"42260.009","nombre":"Tele recepcionista"}],"conocimientos":[{"id":"23","nombre":"Idioma extranjero"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"15","nombre":"Orientación al servicio"},{"id":"37","nombre":"Proactividad"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"34","nombre":"Trabajo bajo presión"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"33440","nombre":"Secretarios médicos / Secretarias médicas"},{"codigo":"42220","nombre":"Empleados de centros de llamadas / Empleadas de centros de llamadas"},{"codigo":"42240","nombre":"Recepcionistas de hoteles"},{"codigo":"42251","nombre":"Auxiliares de información y servicio al cliente"},{"codigo":"42299","nombre":"Otros empleados de servicios de información al cliente no clasificados en otras ocupaciones / Otras empleadas de servici