  ('rol_cuoc', 'Entrevistadores de encuestas y de investigaciones de mercados / Entrevistadoras de encuestas y de investigaciones de mercados', '42270', 'Comercio, mercadeo y publicidad', 2, false, '{"codigo":"42270","nombre":"Entrevistadores de encuestas y de investigaciones de mercados / Entrevistadoras de encuestas y de investigaciones de mercados","descripcion":"Contactan, entrevistan y observan personas o fenómenos para recoger información sobre diversos temas como el tráfico, investigación de mercados, opinión pública, elección, censos, encuestas y demás investigaciones; registran y tabulan las respuestas y la información obtenida. Se pueden desempeñar en firmas de consultoría, empresas de marketing, y organizaciones que realicen estudios de mercado, agencias o departamentos gubernamentales, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"42","nombre":"EMPLEADOS DE TRATO DIRECTO CON EL PÚBLICO"},"subgrupo":{"codigo":"422","nombre":"Empleados de servicios de información al cliente"},"grupo_primario":{"codigo":"4227","nombre":"Entrevistadores de encuestas y de investigaciones de mercados"}},"funciones":[{"consecutivo":1,"texto":"Contactar las personas por teléfono o en persona y explicarles el propósito de la entrevista o encuesta."},{"consecutivo":2,"texto":"Plantear o hacer preguntas siguiendo las indicaciones de los cuestionarios y encuestas."},{"consecutivo":3,"texto":"Registrar o tabular las respuestas o información obtenida en papel o incluirlas directamente en una base de datos informática."},{"consecutivo":4,"texto":"Observar y registrar información sobre el flujo del tráfico vehicular, peatonal y similar."},{"consecutivo":5,"texto":"Monitorear, evaluar y apoyar la supervisión técnica de la elaboración de las encuestas y entrevistas, así como del mantenimiento, uso de registros y planillas de muestreo para censos y encuestas."},{"consecutivo":6,"texto":"Revisar la información recogida para saber si está completa y exacta e identificar y resolver inconsistencias."},{"consecutivo":7,"texto":"Entregar a los patrocinadores de las encuestas información sobre problemas observados en cuanto a la obtención de datos válidos."},{"consecutivo":8,"texto":"Apoyar la elaboración técnica, el mantenimiento y la utilización de registros, planillas de muestreo para censos y encuestas."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"42270.001","nombre":"Auxiliar encuestador / Auxiliar encuestadora"},{"codigo":"42270.002","nombre":"Auxiliar encuestador de estadística / Auxiliar encuestadora de estadística"},{"codigo":"42270.003","nombre":"Encuestador / Encuestadora"},{"codigo":"42270.004","nombre":"Encuestador comercial / Encuestadora comercial"},{"codigo":"42270.005","nombre":"Encuestador de opinión pública / Encuestadora de opinión pública"},{"codigo":"42270.006","nombre":"Encuestador telefónico / Encuestadora telefónica"},{"codigo":"42270.007","nombre":"Entrevistador de estudios de mercado / Entrevistadora de estudios de mercado"},{"codigo":"42270.008","nombre":"Entrevistador de investigaciones de mercado / Entrevistadora de investigaciones de mercado"},{"codigo":"42270.009","nombre":"Operador de estudios de mercado / Operadora de estudios de mercado"},{"codigo":"42270.010","nombre":"Supervisor de encuesta de estudios de mercado / Supervisora de encuesta de estudios de mercado"},{"codigo":"42270.011","nombre":"Recolector de información para encuestas / Recolectora de información para encuestas"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"4","nombre":"Mercadotecnia y publicidad"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"27","nombre":"Análisis de procesos"},{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"38","nombre":"Seguir instrucciones"}],"ocupaciones_afines":[{"codigo":"33220","nombre":"Representantes comerciales"},{"codigo":"42220","nombre":"Empleados de centros de llamadas / Empleadas de centros de llamadas"},{"codigo":"42251","nombre":"Auxiliares de información y servicio al cliente"},{"codigo":"42299","nombre":"Otros empleados de servicios de información al cliente no clasificados en otras ocupaciones / Otras empleadas de servicios de información al cliente no clasificados en otras ocupaciones"},{"codigo":"44130","nombre":"Codificadores de datos, correctores de pruebas de imprenta y afines / Codificadoras de datos, correctores de pruebas de imprenta y afines"},{"codigo":"52440","nombre":"Vendedores a través de medios tecnológicos / Vendedoras a través de medios tecnológicos"}],"area_principal":{"sigla":"COMP","nombre":"Comercio, mercadeo y publicidad"},"areas_complementarias":[{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"}],"equivalencias":[{"ciuo08_codigo":"4227","ciuo08_obs":"Denominaciones completas","cno_codigo":"1354*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Auxiliares administrativos en salud / Auxiliares administrativas en salud', '42291', 'Salud y bienestar', 2, false, '{"codigo":"42291","nombre":"Auxiliares administrativos en salud / Auxiliares administrativas en salud","descripcion":"Informan, recepcionan y verifican la solicitud de admisión de los usuarios en la prestación de servicios a la salud. Brindan apoyo administrativo a profesionales y al equipo de salud. Tramitan formularios de afiliación y apertura de historias clínicas. Revisan y generan facturas de ingreso y egreso derivadas de la atención y apoyan el agendamiento de citas y atenciones en salud. Se pueden desempeñar en aseguradoras o quien haga sus veces, instituciones prestadores de salud hospitales, públicos y privados, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"42","nombre":"EMPLEADOS DE TRATO DIRECTO CON EL PÚBLICO"},"subgrupo":{"codigo":"422","nombre":"Empleados de servicios de información al cliente"},"grupo_primario":{"codigo":"4229","nombre":"Otros empleados de servicios de información al cliente no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Recepcionar, orientar e indagar a la persona sujeto de atención con relación a sus necesidades para obtener y procesar la información necesaria requerida para la prestación de servicios de salud en el marco de la normatividad vigente."},{"consecutivo":2,"texto":"Definir la admisión de las personas que solicitan atención en las instituciones prestadoras de servicios de salud, según la normatividad vigente, utilizando los mecanismos de comunicación disponibles en el lugar de trabajo."},{"consecutivo":3,"texto":"Gestionar el traslado de los sujetos de atención a otras instituciones prestadoras de servicios de salud, según el nivel de complejidad que se requiera para la atención y el tipo de afiliación del sistema de salud."},{"consecutivo":4,"texto":"Brindar apoyo como primer responsable ante situaciones de emergencia en el entorno de trabajo, de acuerdo con las normas técnicas legales."},{"consecutivo":5,"texto":"Liquidar y facturar los servicios de salud prestados a las personas sujetos de atención, según la normatividad vigente y el tipo de contratación."},{"consecutivo":6,"texto":"Tramitar la afiliación de la población al sistema general de seguridad social en salud o al que haga sus veces, según la normatividad vigente."},{"consecutivo":7,"texto":"Clasificar, archivar y custodiar las historias clínicas durante el proceso de prestación de servicios, según la normatividad vigente."},{"consecutivo":8,"texto":"Fomentar prácticas seguras y saludables en los ambientes de trabajo en el marco de los principios de autocuidado y la normatividad vigente."},{"consecutivo":9,"texto":"Agendar, modificar o cancelar citas, exámenes y demás procedimientos requeridos por las personas sujeto de atención en salud."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"42291.001","nombre":"Asistente administrativo de piso en salud / Asistenta administrativa de piso en salud"},{"codigo":"42291.002","nombre":"Auxiliar administrativo en salud / Auxiliar administrativa en salud"},{"codigo":"42291.003","nombre":"Auxiliar de admisión y facturación al usuario en salud"},{"codigo":"42291.004","nombre":"Auxiliar de cuentas médicas"},{"codigo":"42291.005","nombre":"Auxiliar de admisiones hospitalarias"},{"codigo":"42291.006","nombre":"Auxiliar de apoyo administrativo en salud"},{"codigo":"42291.007","nombre":"Auxiliar de ingresos hospitalarios"},{"codigo":"42291.008","nombre":"Auxiliar de registro y admisiones en salud"},{"codigo":"42291.009","nombre":"Auxiliar en atención al usuario en salud"},{"codigo":"42291.010","nombre":"Auxiliar facturación aseguradora"},{"codigo":"42291.013","nombre":"Recepcionista auxiliar de facturación en salud"}],"conocimientos":[{"id":"32","nombre":"Contabilidad e impuestos"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"41","nombre":"Primeros auxilios"},{"id":"50","nombre":"Servicio a la persona y humanización"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"5","nombre":"Lógica matemática"},{"id":"15","nombre":"Orientación al servicio"},{"id":"37","nombre":"Proactividad"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"33411","nombre":"Supervisores administrativos / Supervisoras administrativas"},{"codigo":"33440","nombre":"Secretarios médicos / Secretarias médicas"},{"codigo":"41101","nombre":"Oficinistas generales"},{"codigo":"42260","nombre":"Recepcionistas generales"}],"area_principal":{"sigla":"SABI","nombre":"Salud y bienestar"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"4110*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"1331*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"4229*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"1345","cno_obs":"Denominaciones completas"},{"ciuo08_codigo":"4416*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"","cno_obs":""}]}'::jsonb),
  ('rol_cuoc', 'Otros empleados de servicios de información al cliente no clasificados en otras ocupaciones / Otras empleadas de servicios de información al cliente no clasificados en otras ocupaciones', '42299', 'Administración, finanzas y derecho', 2, false, '{"codigo":"42299","nombre":"Otros empleados de servicios de información al cliente no clasificados en otras ocupaciones / Otras empleadas de servicios de información al cliente no clasificados en otras ocupaciones","descripcion":"Esta ocupación abarca a otros empleados de servicios de información al cliente no clasificados en otras ocupaciones del Grupo Primario 4229: Otros empleados de servicios de información al cliente no clasificados en otros grupos primarios. Por ejemplo, incluye aquellos que entrevistan y, documentan la elegibilidad y brindan acompañamiento a los usuarios objeto deal recibir ayuda de diferentes programas o servicios ya sean de carácter privado o público como el acceso a recursos del organismo, tales como el bienestar, prestaciones por desempleo, seguridad social, y vivienda, entre otros. Se pueden desempeñar en entidades estatales, fundaciones, organismos de derechos humanos, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"42","nombre":"EMPLEADOS DE TRATO DIRECTO CON EL PÚBLICO"},"subgrupo":{"codigo":"422","nombre":"Empleados de servicios de información al cliente"},"grupo_primario":{"codigo":"4229","nombre":"Otros empleados de servicios de información al cliente no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Entrevistar a usuarios de servicios a propósito de sus derechos."},{"consecutivo":2,"texto":"Obtener y procesar información relativa a los usuarios para determinar si tienen o no derecho a determinadas prestaciones."},{"consecutivo":3,"texto":"Entrevistar a los solicitantes de asistencia pública para reunir información pertinente a su solicitud."},{"consecutivo":4,"texto":"Verificar la exactitud de la información proporcionada."},{"consecutivo":5,"texto":"Iniciar procedimientos para otorgar, modificar, negar o terminar la asistencia."},{"consecutivo":6,"texto":"Proporcionar información, rutas de atención institucional y contestar preguntas sobre los procedimientos de beneficios y reclamos."},{"consecutivo":7,"texto":"Brindar asistencia a las personas y sus sistemas familiares, desde su ingreso, permanecía, cambio y retiro de la prestación de servicios."},{"consecutivo":8,"texto":"Diligenciar o digitalizar los formatos, los formularios y otros documentos que en ejercicio de sus funciones desarrolle de acuerdo con los instructivos, los protocolos y la normativa."},{"consecutivo":9,"texto":"Apoyar operativa y logísticamente a los profesionales y los administrativos en la realización de talleres, programas y diferentes actividades del modelo psicosocial y otros servicios sociales que se programen y ejecuten."},{"consecutivo":10,"texto":"Actuar y reportar según lineamientos institucionales en casos de crisis, emergencias, conflictos comunitarios, en servicios a refugiados o damnificados, entre otros."},{"consecutivo":11,"texto":"Mantener el stock e informar al área responsable de los elementos e insumos necesarios para el funcionamiento de los servicios prestados bajo su responsabilidad."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"42299.001","nombre":"Consultor de elegibilidad / Consultora de elegibilidad"},{"codigo":"42299.002","nombre":"Entrevistador de elegibilidad / Entrevistadora de elegibilidad"},{"codigo":"42299.003","nombre":"Auxiliar de servicio social y comunitario"},{"codigo":"42299.004","nombre":"Auxiliar social en comunidad terapéutica"},{"codigo":"42299.005","nombre":"Auxiliar social de protección a la familia"},{"codigo":"42299.006","nombre":"Auxiliar social de protección de la infancia y la adolescencia"},{"codigo":"42299.007","nombre":"Auxiliar social de servicios de rehabilitación resocialización"}],"conocimientos":[{"id":"36","nombre":"Manejo de las TIC"},{"id":"50","nombre":"Servicio a la persona y humanización"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"},{"id":"42","nombre":"Atención, protección y servicios a la infancia, adolescencia y juventud"},{"id":"55","nombre":"Atención a adultos, adultos mayores con o sin discapacidad"}],"destrezas":[{"id":"17","nombre":"Análisis de necesidades"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"13","nombre":"Conciliación"},{"id":"15","nombre":"Orientación al servicio"},{"id":"16","nombre":"Resolución de problemas complejos"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"33411","nombre":"Supervisores administrativos / Supervisoras administrativas"},{"codigo":"33530","nombre":"Funcionarios e inspectores de servicios de seguridad social / Funcionarias e inspectoras de servicios de seguridad social"},{"codigo":"34120","nombre":"Trabajadores y asistentes sociales y comunitarios / Trabajadoras y asistentes sociales y comunitarias"},{"codigo":"41101","nombre":"Oficinistas generales"},{"codigo":"42260","nombre":"Recepcionistas generales"},{"codigo":"53293","nombre":"Auxiliares en salud pública"},{"codigo":"53120","nombre":"Auxiliares de maestros y primera infancia"},{"codigo":"53210","nombre":"Trabajadores de los cuidados personales en instituciones / Trabajadoras de los cuidados personales en instituciones"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"4229*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"","cno_obs":""}]}'::jsonb),
  ('rol_cuoc', 'Auxiliares de contabilidad, costos y tesorería', '43110', 'Administración, finanzas y derecho', 2, true, '{"codigo":"43110","nombre":"Auxiliares de contabilidad, costos y tesorería","descripcion":"Apoyan los procesos de cálculo, clasificación y registro de las transacciones contables, financieras, de tesorería y operaciones de flujo monetario, destinados al mantenimiento de los estados o registros financieros completos; realizan diversas funciones de cálculo rutinarias, liquidación de impuestos, cuantificación de costos y verificación de inventarios; llevan libros de contabilidad, verifican obligaciones, depuran y apoyan la elaboración de informes, comprobantes y documentos contables. Se pueden desempeñar en los departamentos del sector público y privado en el área de contabilidad, tesorería, cartera, financiero, empresas de consultoría contable, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"43","nombre":"AUXILIARES CONTABLES Y ENCARGADOS DEL REGISTRO DE MATERIALES"},"subgrupo":{"codigo":"431","nombre":"Auxiliares contables y financieros"},"grupo_primario":{"codigo":"4311","nombre":"Auxiliares de contabilidad, costos y tesorería"}},"funciones":[{"consecutivo":1,"texto":"Comprobar cifras, asientos contables y documentos a fin de confirmar su correcta anotación, su precisión matemática y la utilización apropiada de los códigos pertinentes."},{"consecutivo":2,"texto":"Colaborar y asistir en la preparación de balances de prueba, registros financieros, cuentas por pagar y cuentas por cobrar con la medición y reconocimiento de recursos financieros de acuerdo con la normativa vigente."},{"consecutivo":3,"texto":"Registrar, almacenar y analizar información utilizando programas informáticos contables."},{"consecutivo":4,"texto":"Clasificar, registrar y resumir datos numéricos de procesos contables y financieros con el fin de ingresar, compilar y mantener registros y al día el sistema contable, utilizando libros diarios o mayores, sistemas manuales y/o electrónicos de acuerdo con políticas organizacionales u institucionales vigentes."},{"consecutivo":5,"texto":"Calcular, preparar y emitir relaciones de gastos, facturas, estados de cuentas y otros documentos financieros con arreglo a los procedimientos establecidos."},{"consecutivo":6,"texto":"Apoyar en la implementación del sistema de costos, identificando costos operacionales de acuerdo con métodos vigentes de la entidad u organización."},{"consecutivo":7,"texto":"Organizar, archivar y compilar documentos e informes del área de contabilidad y finanzas como cuadros estadísticos, de auditoría, ingresos en efectivo, gastos, cuentas por pagar y por cobrar, beneficios y pérdidas, entre otros."},{"consecutivo":8,"texto":"Llevar registros de liquidaciones de compra y planillas de transferencia para pago a proveedores."},{"consecutivo":9,"texto":"Elaborar y seleccionar información de los procesos de liquidación tributaría según procedimientos y normativa fiscal vigente."},{"consecutivo":10,"texto":"Elaborar informes y reportes del área de acuerdo con procedimientos y políticas organizacionales u institucionales vigentes."},{"consecutivo":11,"texto":"Manejar la caja menor y llevar registros de los pagos y cobranzas relacionados con la conducción de los negocios."},{"consecutivo":12,"texto":"Atender clientes del área de acuerdo con normas técnicas y políticas institucionales vigentes."},{"consecutivo":13,"texto":"Realizar las conciliaciones de las diferentes operaciones de acuerdo con los procesos internos de la entidad."},{"consecutivo":14,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"43110.001","nombre":"Auxiliar de contabilidad cooperativa"},{"codigo":"43110.002","nombre":"Auxiliar de contabilidad hotelera"},{"codigo":"43110.003","nombre":"Auxiliar contable"},{"codigo":"43110.004","nombre":"Auxiliar contable y administrativo / Auxiliar contable y administrativa"},{"codigo":"43110.005","nombre":"Auxiliar contable y financiero / Auxiliar contable y financiera"},{"codigo":"43110.007","nombre":"Auxiliar de calculo de costos"},{"codigo":"43110.008","nombre":"Auxiliar de cálculo de presupuestos"},{"codigo":"43110.009","nombre":"Auxiliar de contabilidad"},{"codigo":"43110.010","nombre":"Auxiliar de contabilidad de costos"},{"codigo":"43110.011","nombre":"Auxiliar de costos"},{"codigo":"43110.012","nombre":"Auxiliar de cuentas"},{"codigo":"43110.013","nombre":"Auxiliar de cuentas por cobrar"},{"codigo":"43110.014","nombre":"Auxiliar de cuentas por pagar"},{"codigo":"43110.015","nombre":"Auxiliar de facturación"},{"codigo":"43110.016","nombre":"Auxiliar de presupuesto"},{"codigo":"43110.017","nombre":"Auxiliar de teneduría de libros"},{"codigo":"43110.018","nombre":"Auxiliar de tesorería"},{"codigo":"43110.019","nombre":"Auxiliar de trámite de cuentas"},{"codigo":"43110.020","nombre":"Facturador / Facturadora"}],"conocimientos":[{"id":"32","nombre":"Contabilidad e impuestos"},{"id":"33","nombre":"Gestión financiera, administración bancaria y seguros"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"14","nombre":"Matemáticas"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"27","nombre":"Análisis de procesos"},{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"5","nombre":"Lógica matemática"},{"id":"15","nombre":"Orientación al servicio"},{"id":"34","nombre":"Trabajo bajo presión"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"33120","nombre":"Analistas y asistentes financieros en préstamos y créditos / Analistas y asistentes financieras en préstamos y créditos"},{"codigo":"33131","nombre":"Asistentes contables / Asistentas contables"},{"codigo":"33132","nombre":"Asistentes financieros / Asistentas financieras"},{"codigo":"33133","n