  ('rol_cuoc', 'Auxiliares de servicios estadísticos y financieros', '43121', 'Administración, finanzas y derecho', 2, true, '{"codigo":"43121","nombre":"Auxiliares de servicios estadísticos y financieros","descripcion":"Obtienen, compilan, registran y calculan datos estadísticos o actuariales, información financiera y llevan a cabo funciones de oficina relacionadas con las operaciones de entidades de seguros, bancos y otros establecimientos financieros. Se pueden desempeñar en bancos, empresas de crédito, agencias de seguros, firmas de inversión, fondos de pensiones y otras entidades financieras en el sector público y privado, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"43","nombre":"AUXILIARES CONTABLES Y ENCARGADOS DEL REGISTRO DE MATERIALES"},"subgrupo":{"codigo":"431","nombre":"Auxiliares contables y financieros"},"grupo_primario":{"codigo":"4312","nombre":"Auxiliares de servicios estadísticos, financieros y de seguros"}},"funciones":[{"consecutivo":1,"texto":"Procesar contrataciones de seguros, anulaciones, trámites relativos a declaraciones de siniestros, modificaciones y acuerdos de pólizas y pagos de acuerdo con normativa financiera, guía técnica y tipo de negocio."},{"consecutivo":2,"texto":"Tramitar, calcular, revisar aplicaciones y pagos de seguros, primas, cobertura, pensiones y cesantías, beneficios, rendimientos y otra información relacionada."},{"consecutivo":3,"texto":"Tramitar solicitudes y pagos de hipotecas, apertura y cierre de productos y servicios de captación y colocación, depósitos, letras de cambio, compra y venta de acciones y moneda extranjera, cheques viajeros, giros postales y alquiler de cajas de seguridad."},{"consecutivo":4,"texto":"Mantener y llevar registros de obligaciones, títulos, acciones y otros valores comprados o vendidos por cuenta de clientes o del empleador."},{"consecutivo":5,"texto":"Asesorar, responder a requerimientos y dar información financiera, de seguros, pólizas y servicios al cliente de acuerdo con normativa y guía técnica."},{"consecutivo":6,"texto":"Verificar y hacer el balance de transacciones de cajero automático y preparar estados de cuenta calculando tarifas de servicios y pagos de intereses."},{"consecutivo":7,"texto":"Preparar correspondencia y notificaciones de interés general y financiero para el cliente y cuando existan diferencias con la cuenta o la captura de tarjetas."},{"consecutivo":8,"texto":"Recopilar registros de depósitos y retiros, pagos por préstamo e hipoteca, cheques, compra y venta de seguros."},{"consecutivo":9,"texto":"Calcular totales, promedios, porcentajes y otros detalles y presentarlos en forma tabular."},{"consecutivo":10,"texto":"Revisar la información recogida para saber si está completa y exacta."},{"consecutivo":11,"texto":"Obtener, recopilar y compilar datos estadísticos o actuariales a partir de fuentes de información ordinarias o fuentes especiales de acuerdo con fórmulas estadísticas y uso en estudios."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"43121.001","nombre":"Asesor rápido de servicios financieros / Asesora rápida de servicios financieros"},{"codigo":"43121.002","nombre":"Asistente de registro de pensiones y cesantías / Asistenta de registro de pensiones y cesantías"},{"codigo":"43121.003","nombre":"Auxiliar actuarial"},{"codigo":"43121.004","nombre":"Auxiliar administrativo de reclamos de seguros / Auxiliar administrativa de reclamos de seguros"},{"codigo":"43121.005","nombre":"Auxiliar bancario / Auxiliar bancaria"},{"codigo":"43121.006","nombre":"Auxiliar de ahorros"},{"codigo":"43121.007","nombre":"Auxiliar de auditoria"},{"codigo":"43121.009","nombre":"Auxiliar de bonos pensionales"},{"codigo":"43121.010","nombre":"Auxiliar de corretaje"},{"codigo":"43121.011","nombre":"Auxiliar de crédito"},{"codigo":"43121.012","nombre":"Auxiliar de crédito de banca"},{"codigo":"4312