  ('rol_cuoc', 'Auxiliares de avalúos', '43122', 'Administración, finanzas y derecho', 2, false, '{"codigo":"43122","nombre":"Auxiliares de avalúos","descripcion":"Apoyan los procesos de determinación del valor de un bien de conformidad con los métodos, técnicas, actuaciones, criterios y herramientas que se consideren necesarios y pertinentes para el dictamen valuatorio. Se pueden desempeñar en bancos, agencias de seguros, firmas de inversión, fondos de pensiones, otras entidades financieras en el sector público y privado, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"43","nombre":"AUXILIARES CONTABLES Y ENCARGADOS DEL REGISTRO DE MATERIALES"},"subgrupo":{"codigo":"431","nombre":"Auxiliares contables y financieros"},"grupo_primario":{"codigo":"4312","nombre":"Auxiliares de servicios estadísticos, financieros y de seguros"}},"funciones":[{"consecutivo":1,"texto":"Procesar contrataciones y asistir procesos de valuación de bienes tangibles, especiales e intangibles siguiendo procedimientos, metodologías y normatividad vigente."},{"consecutivo":2,"texto":"Mantener registros de títulos de propiedad, e informes de inventarios, con cantidad, tipo y valor de materiales y equipos; usando sistemas manuales o computarizados; cuando aplique."},{"consecutivo":3,"texto":"Asistir en la preparación, organización y presentación de documentación con fines velatorios."},{"consecutivo":4,"texto":"Llevar y ajustar el informe de avalúo con su respectiva memoria de cálculo y de cargo."},{"consecutivo":5,"texto":"Calcular totales, promedios, porcentajes y otros detalles y presentarlos en forma tabular."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"43122.001","nombre":"Auxiliar de avalúos y liquidación"},{"codigo":"43122.002","nombre":"Auxiliar de avalúo"}],"conocimientos":[{"id":"32","nombre":"Contabilidad e impuestos"},{"id":"33","nombre":"G