  ('rol_cuoc', 'Auxiliares de nómina y prestaciones', '43130', 'Administración, finanzas y derecho', 2, false, '{"codigo":"43130","nombre":"Auxiliares de nómina y prestaciones","descripcion":"Recogen, verifican, procesan y elaboran expedientes del personal e información relativa a los registros contables de las nóminas, apoyan la gestión de pagos y derechos a prestaciones sociales para los trabajadores de un departamento, una empresa o un establecimiento de acuerdo con normativa. Se pueden desempeñar en departamentos de gestión humana en el sector público y privado, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"43","nombre":"AUXILIARES CONTABLES Y ENCARGADOS DEL REGISTRO DE MATERIALES"},"subgrupo":{"codigo":"431","nombre":"Auxiliares contables y financieros"},"grupo_primario":{"codigo":"4313","nombre":"Auxiliares de nómina y prestaciones"}},"funciones":[{"consecutivo":1,"texto":"Verificar y mantener la información en la base de datos, sistema de nómina manual o informático introduciendo, modificando y excluyendo las novedades asociadas al personal como el ingreso o retiro, la asistencia, las horas extras y trabajadas, los permisos, rectificando informes de trabajo, tarjetas de entradas y salidas, licencias, entre otros."},{"consecutivo":2,"texto":"Preparar y verificar las declaraciones de ingresos establecidos para los empleados indicando los sueldos brutos y netos y las deducciones tales como impuestos, cuotas sindicales, embargos judiciales y planes de seguros y pensiones."},{"consecutivo":3,"texto":"Preparar los pagos de beneficios de los empleados mediante cheque o transferencia electrónica."},{"consecutivo":4,"texto":"Apoyar la elaboración, radicación y seguimiento de órdenes de pago, seguridad social y realizar el pago por las plataformas correspondientes."},{"consecutivo":5,"texto":"Verificar que estén completos los contratos colectivos de trabajo para determinar los factores de nóminas y tasas de pago; ajustes de remuneración y anotar los datos pertinentes en los registros previstos para tal propósito."},{"consecutivo":6,"texto":"Calcular nómina manual o sistematizada, teniendo en cuenta novedades de personal, salario, prestaciones sociales, beneficios y deducciones correspondientes para el pago de derechos a prestaciones de acuerdo con políticas organizacionales."},{"consecutivo":7,"texto":"Introducir, modificar y excluir información en la base de datos para nómina de personal."},{"consecutivo":8,"texto":"Brindar información relacionada con el proceso de nómina de acuerdo con procedimientos organizacionales."},{"consecutivo":9,"texto":"Apoyar la elaboración de informes del proceso de nómina y pagos a terceros de acuerdo con procedimientos organizacionales."},{"consecutivo":10,"texto":"Apoyar la recolección, el análisis y la entrega de información necesarias para dar respuesta a requerimientos de entidades encargadas de auditar procesos de nómina y pagos de seguridad social."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"43130.001","nombre":"Asistente de nómina / Asistenta de nómina"},{"codigo":"43130.002","nombre":"Auxiliar de cálculo de salarios"},{"codigo":"43130.003","nombre":"Auxiliar de nómina"},{"codigo":"43130.004","nombre":"Auxiliar de nómina y prestaciones"},{"codigo":"43130.005","nombre":"Auxiliar de pago de nómina"},{"codigo":"43130.006","nombre":"Ayudante de nómina"},{"codigo":"43130.007","nombre":"Liquidador de nómina / Liquidadora de nómina"}],"conocimientos":[{"id":"32","nombre":"Contabilidad e impuestos"},{"id":"6","nombre":"Gestión del talento humano y de personal"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"14","nombre":"Matemáticas"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"15","nombre":"Orientación al servicio"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"34","nombre":"Trabajo bajo presión"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"33131","nombre":"Asistentes contables / Asistentas contables"},{"codigo":"33134","nombre":"Técnicos de contabilidad y afines / Técnicas de contabilidad y afines"},{"codigo":"33431","nombre":"Asistentes administrativos / Asistentas administrativas"},{"codigo":"33432","nombre":"Asistentes de talento humano / Asistentas de talento humano"},{"codigo":"43110","nombre":"Auxiliares de contabilidad, costos y tesorería"},{"codigo":"43121","nombre":"Auxiliares de servicios estadísticos y financieros"},{"codigo":"44161","nombre":"Auxiliares de talento humano"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"4313","ciuo08_obs":"Denominaciones completas","cno_codigo":"1335","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Auxiliares de almacén y pesaje', '43211', 'Logística y transporte', 2, false, '{"codigo":"43211","nombre":"Auxiliares de almacén y pesaje","descripcion":"Reciben, clasifican, registran, pesan, almacenan, despachan, alistan pedidos y materiales, empacan, embalan, rotulan, unitarizan los suministros, los materiales de producción recibidos y equipos en centros de distribución y expedición, almacenes y plataformas para mantener un control continuo según normativa y el tipo de producto. Se pueden desempeñar en empresas, comercializadoras de venta al detal y al por mayor, transportadoras, puertos, empresas públicas y privadas, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"43","nombre":"AUXILIARES CONTABLES Y ENCARGADOS DEL REGISTRO DE MATERIALES"},"subgrupo":{"codigo":"432","nombre":"Empleados encargados del registro de materiales y de transportes"},"grupo_primario":{"codigo":"4321","nombre":"Empleados control de abastecimientos e inventario y de almacén"}},"funciones":[{"consecutivo":1,"texto":"Programar, dirigir y controlar las actividades de recepción, expedición, despacho, registro y control de las mercancías según la naturaleza, procesos, sistemas de almacenaje, métodos y normatividad."},{"consecutivo":2,"texto":"Verificar la distribución de los bienes y materiales, evaluar las necesidades y hacer solicitudes de reposición de las existencias."},{"consecutivo":3,"texto":"Inspeccionar, formalizar y desconsolidar la llegada de insumos y mercancías contra facturas y otros documentos."},{"consecutivo":4,"texto":"Organizar, ubicar, inventariar y mantener registros de existencias, materiales, insumos, suministros según métodos y normativa."},{"consecutivo":5,"texto":"Recibir, almacenar y expedir herramientas, piezas de repuesto y equipos diversos."},{"consecutivo":6,"texto":"Manipular materiales, carga o mercancías clasificando, empacando, desempacando, embalando, marcando, rotulando, unitarizarizando y consolidando según requerimientos de los clientes, métodos, normativa y tipo de producto."},{"consecutivo":7,"texto":"Pesar y mantener los registros pertinentes de los bienes recibidos, producidos, destinados a ser distribuidos y expedidos."},{"consecutivo":8,"texto":"Cargar y descargar la mercancía según normativa de higiene y seguridad."},{"consecutivo":9,"texto":"Operar equipos y herramientas de manipulación de la mercancía según manual del fabricante y normativa de seguridad."},{"consecutivo":10,"texto":"Apilar la mercancía en las bodegas de acuerdo con instrucciones."},{"consecutivo":11,"texto":"Revisar los materiales, mercancía o carga de los contenedores y guacales, diligenciando las órdenes de bodegaje."},{"consecutivo":12,"texto":"Realizar el pesaje bruto y tara de todos los vehículos que ingresan con productos para el centro de acopio y los vehículos despachados a puerto."},{"consecutivo":13,"texto":"Preparar los tiquetes de bascula e informar a los carperos si el peso del vehículo es el correcto para en caso de no serlo retirar material."},{"consecutivo":14,"texto":"Mantener el área de bodegaje en buenas condiciones."},{"consecutivo":15,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"43211.001","nombre":"Almacenador producto procesado / Almacenadora de producto procesado"},{"codigo":"43211.002","nombre":"Almacenador producto terminado / Almacenadora de producto terminado"},{"codigo":"43211.003","nombre":"Almacenista"},{"codigo":"43211.004","nombre":"Almacenista de insumos"},{"codigo":"43211.005","nombre":"Almacenista de obra"},{"codigo":"43211.006","nombre":"Almacenista de producción"},{"codigo":"43211.007","nombre":"Almacenista de suministros"},{"codigo":"43211.008","nombre":"Almacenista de taller de repuestos"},{"codigo":"43211.009","nombre":"Auxiliar de bodega"},{"codigo":"43211.010","nombre":"Auxiliar de bodega en petróleo y gas"},{"codigo":"43211.011","nombre":"Auxiliar de abas