  ('rol_cuoc', 'Auxiliares de compras e inventarios', '43212', 'Logística y transporte', 2, false, '{"codigo":"43212","nombre":"Auxiliares de compras e inventarios","descripcion":"Tramitan y registran órdenes de compra, codifican productos, mantienen inventario y su distribución a tiempo en los puntos a disposición del cliente final, de materiales, equipos y existencias. Se pueden desempeñar en establecimientos comerciales, fábricas y establecimientos del sector público y privado, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"43","nombre":"AUXILIARES CONTABLES Y ENCARGADOS DEL REGISTRO DE MATERIALES"},"subgrupo":{"codigo":"432","nombre":"Empleados encargados del registro de materiales y de transportes"},"grupo_primario":{"codigo":"4321","nombre":"Empleados control de abastecimientos e inventario y de almacén"}},"funciones":[{"consecutivo":1,"texto":"Mantener registros de existencias, verificar la distribución de los bienes y materiales para apoyar la elaboración de órdenes con el fin de reponer materiales, suministros y mercancías de acuerdo con los procedimientos de la organización."},{"consecutivo":2,"texto":"Verificar y controlar la recepción, la compra, la expedición y el mantenimiento de registros pertinentes para determinar la exactitud de materiales, equipos y mercancías, verificar que estén de acuerdo con el inventario y la programación de compras."},{"consecutivo":3,"texto":"Obtener cotizaciones, catálogos y lista de proveedores y preparar órdenes de compra."},{"consecutivo":4,"texto":"Apoyar el cálculo de inventario y costo de orden de compra y cargar a la cuenta apropiada de forma manual o computarizada de acuerdo con los procedimientos de la organización."},{"consecutivo":5,"texto":"Apoyar el contacto con proveedores para resolver problemas en la entrega de materiales, equipos, mercancías y tramitar devoluciones."},{"consecutivo":6,"texto":"Mantener actualizadas las bases de datos y archivos de proveedores, compras, informes y listas de precios de acuerdo con los procedimientos de la organización, tirillas de descargo, remisiones, entre otros."},{"consecutivo":7,"texto":"Controlar niveles y rotación de inventario de materiales, equipos y existencias para ser distribuidos dentro de la empresa o para venta al público, así como disponer la cuenta de obsoletos de acuerdo con los procedimientos de la organización."},{"consecutivo":8,"texto":"Consolidar informes de inventario, registrar la cantidad, el tipo y el valor de materiales y equipos usando sistemas de inventario manual o computarizado."},{"consecutivo":9,"texto":"Codificar productos nuevos."},{"consecutivo":10,"texto":"Ajustar los precios y las cantidades del inventario de acuerdo con estrategias de mercadeo y requerimientos."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"43212.001","nombre":"Auxiliar de almacén e inventarios"},{"codigo":"43212.002","nombre":"Auxiliar de compras"},{"codigo":"43212.003","nombre":"Auxiliar de compras e inventarios"},{"codigo":"43212.004","nombre":"Auxiliar de control de inventarios"},{"codigo":"43212.005","nombre":"Auxiliar de existencias de inventario"},{"codigo":"43212.006","nombre":"Auxiliar de inventarios"},{"codigo":"43212.007","nombre":"Encargado de inventario / Encargada de inventario"}],"conocimientos":[{"id":"32","nombre":"Contabilidad e impuestos"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"7","nombre":"Producción y procesamiento"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"5","nombre":"Lógica matemática"},{"id":"12","nombre":"Persuasión"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"33230","nombre":"Agentes de compras"},{"codigo":"33431","nombre":"Asistentes administrativos / Asistentas administrativas"},{"codigo":"43211","nombre":"Auxiliares de almacén y pesaje"}],"area_principal":{"sigla":"LOTR","nombre":"Logística y transporte"},"areas_complementarias":[{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},{"sigla":"COMP","nombre":"Comercio, mercadeo y publicidad"}],"equivalencias":[{"ciuo08_codigo":"4321*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"1372","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Empleados de servicios de apoyo a la producción / Empleadas de servicios de apoyo a la producción', '43220', 'Fabricación, transformación de materiales, instalación, mantenimiento y reparación', 2, false, '{"codigo":"43220","nombre":"Empleados de servicios de apoyo a la producción / Empleadas de servicios de apoyo a la producción","descripcion":"Calculan, estiman y hacen requerimientos de las cantidades de los diversos materiales necesarios en fechas específicas para llevar a cabo los programas de fabricación, construcción y producción u otros programas de producción afines; apoyan en la preparación y verificación de los calendarios de operación y producción; registran flujos de trabajo y monitorean máquinas. Se pueden desempeñar en empresas que fabrican productos como calzado y marroquinería, muebles, productos eléctricos, de plástico, de caucho textiles, confecciones, empresas de impresión y empaque, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"43","nombre":"AUXILIARES CONTABLES Y ENCARGADOS DEL REGISTRO DE MATERIALES"},"subgrupo":{"codigo":"432","nombre":"Empleados encargados del registro de materiales y de transportes"},"grupo_primario":{"codigo":"4322","nombre":"Empleados de servicios de apoyo a la producción"}},"funciones":[{"consecutivo":1,"texto":"Calcular, estimar y hacer requerimientos sobre la cantidad, la calidad y los tipos de materiales necesarios para llevar a cabo los programas de producción."},{"consecutivo":2,"texto":"Elaborar y mantener listas y registros de las materias primas y materiales requeridos en los procesos, garantizando que estén disponibles cuando sea necesario."},{"consecutivo":3,"texto":"Apoyar en la preparación de los calendarios de operación y la producción sobre la base de pedidos de los clientes y la capacidad de producción y rendimiento."},{"consecutivo":4,"texto":"Verificar las existencias, la organización de las entregas de los materiales pedidos e investigar la causa de los retrasos que se produzcan."},{"consecutivo":5,"texto":"Registrar el flujo de trabajo y los materiales entre departamentos."},{"consecutivo":6,"texto":"Monitorear máquinas para observar fallas por atascamientos de materiales en proceso."},{"consecutivo":7,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"43220.001","nombre":"Auxiliar de planificación de la producción"},{"codigo":"43220.002","nombre":"Auxiliar de planificación de materiales"},{"codigo":"43220.003","nombre":"Auxiliar de producción"},{"codigo":"43220.004","nombre":"Auxiliar de programación de materiales"}],"conocimientos":[{"id":"36","nombre":"Manejo de las TIC"},{"id":"38","nombre":"Mantenimiento"},{"id":"77","nombre":"Materiales (vidrio, papel, plástico y madera)"},{"id":"7","nombre":"Producción y procesamiento"},{"id":"85","nombre":"Seguridad y salud en el trabajo"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"17","nombre":"Análisis de necesidades"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"15","nombre":"Orientación al servicio"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"31229","nombre":"Supervisores de industrias manufactureras no clasificadas en otras ocupaciones / Supervisoras de industrias manufactureras no clasificadas en otras ocupaciones"},{"codigo":"33230","nombre":"Agentes de compras"}],"area_principal":{"sigla":"FAMA","nombre":"Fabricación, transformación de materiales, instalación, mantenimiento y reparación"},"areas_complementarias":[{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"}],"equivalencias":[{"ciuo08_codigo":"4322","ciuo08_obs":"Denominaciones completas","cno_codigo":"9616*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Empleados y operarios de servicios de transporte / Empleadas y operarias de servicios de transporte', '43231', 'Logística y transporte', 2, true, '{"codigo":"43231","nombre":"Empleados y operarios de servicios de transporte / Empleadas y operarias de servicios de transporte","descripcion":"Preparan programaciones y llevan registros de operaciones y de personal de transporte de pasajeros, equipaje y mercancías. Despachan todo tipo de vehículos y coordinar conjuntamente actividades de conductores y otro personal. Se pueden desempeñar en empresas de transporte de pasajeros, de servicio de entregas y correos, ferrocarril, camiones, aerolíneas, servicios de emergencia y otros establecimientos de transporte del sector público y privado, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"43","nombre":"AUXILIARES CONTABLES Y ENCARGADOS DEL REGISTRO DE MATERIALES"},"subgrupo":{"codigo":"432","nombre":"Empleados encargados del registro de materiales y de transportes"},"grupo_primario":{"codigo":"4323","nombre":"Empleados de servicios de transporte"}},"funciones":[{"consecutivo":1,"texto":"Llevar registros de los aspectos operativos del sector del transporte y coordinar los calendarios y horarios del transporte de pasajeros y de carga de acuerdo con los procedimientos establecidos y la normatividad."},{"consecutivo":2,"texto":"Apoyar en el diseño e incorporar en los planes de ruta e itinerarios, factores como períodos de transporte pico, vacaciones, eventos especiales con énfasis en el tiempo y modificaciones contemplando costo-beneficio utilizando métodos computacionales y de otro tipo."},{"consecutivo":3,"texto":"Procesar y transmitir información e instrucciones para coordinar el despacho y las actividades de conductores, tripulaciones y equipo auxiliar de acuerdo con las programaciones escritas, órdenes de trabajo o según las situaciones de emergencia que se presenten utilizando diferentes medios de comunicación."},{"consecutivo":4,"texto":"Informar a los operadores de vehículos y modificar programación de acuerdo con problemas de tráfico como accidentes, congestión, condiciones climáticas y estimando el número de pasajeros, tiempos, distancias, disponibilidad de personal y otras situaciones."},{"consecutivo":5,"texto":"Verificar el personal asignado para el equipo y rutas y programar turnos de trabajo."},{"consecutivo":6,"texto":"Recopilar registros de personal y equipo, incluyendo horas de servicio, distancias, número de viajes, mantenimiento, reparaciones requeridas y otra información para producir informes operativos."},{"consecutivo":7,"texto":"Diligenciar y verificar de documentos relacionados al servicio de transporte del pasajero de acuerdo con procedimientos establecidos."},{"consecutivo":8,"texto":"Rastrear e informar sobre el equipaje de acuerdo con las políticas y los protocolos de seguridad establecidas."},{"consecutivo":9,"texto":"Preparar informes relacionados con equipaje, despacho y programación de transporte destinados a sus directivos."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"43231.001","nombre":"Agente de equipajes"},{"codigo":"43231.002","nombre":"Agente de equipajes y servicio al cliente"},{"codigo":"43231.003","nombre":"Asistente de enrutamiento / Asistenta de enrutamiento"},{"codigo":"43231.004","nombre":"Asistente de envío de cargas / Asistenta de envío de cargas"},{"codigo":"43231.005","nombre":"Asistente de envío de transporte aéreo / Asistenta de envío de transporte aéreo"},{"codigo":"43231.006","nombre":"Asistente de movimiento de carga / Asistenta de movimiento de carga"},{"codigo":"43231.007","nombre":"Asistente de operaciones de vuelo / Asistenta de operaciones de vuelo"},{"codigo":"43231.008","nombre":"Asistente de recibo de carga / Asistenta de recibo de carga"},{"codigo":"43231.009","nombre":"Asistente de transporte marítimo de muelle /