  ('rol_cuoc', 'Inspectores y controladores de transporte / Inspectoras y controladoras de transporte', '43232', 'Logística y transporte', 3, true, '{"codigo":"43232","nombre":"Inspectores y controladores de transporte / Inspectoras y controladoras de transporte","descripcion":"Coordinan y dirigen el tráfico y las actividades previas al viaje de pasajeros y carga, ferroviaria, marítima, aérea y terrestre, dentro de las áreas asignadas. Informan a la tripulación sobre condiciones para despegar y operar, realizan el seguimiento de los vehículos y naves mediante permanente contacto con la tripulación informando sobre novedades en clima, rutas, torres, terminales y centros de control, entre otros. Mantienen registros de los aspectos operativos de este sector de actividad y coordinan los calendarios y horarios. Se pueden desempeñar en puertos, aeropuertos y estaciones ferroviarias y flotas de vehículos, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"43","nombre":"AUXILIARES CONTABLES Y ENCARGADOS DEL REGISTRO DE MATERIALES"},"subgrupo":{"codigo":"432","nombre":"Empleados encargados del registro de materiales y de transportes"},"grupo_primario":{"codigo":"4323","nombre":"Empleados de servicios de transporte"}},"funciones":[{"consecutivo":1,"texto":"Programar, controlar la salida, movimiento y despacho operacional de vehículos, aeronaves y trenes, en el transporte de pasajeros, mercancías y cargas de acuerdo con parámetros de seguridad, normas, procedimientos, regulaciones nacionales e internacionales vigentes."},{"consecutivo":2,"texto":"Asistir en el control, dirección de movimiento y regulación del tráfico aéreo, marítimo, terrestre y férreo de transporte de carga y pasajeros."},{"consecutivo":3,"texto":"Coordinar y llevar registros de actividades operacionales transporte por carretera, aéreo de pasajeros y de carga, tales como listas de pasajeros, manifiestos de carga, asignación y programación de vehículos y conductores, la organización de sus calendarios y horarios de trabajo, la carga y descarga de dichos vehículos."},{"consecutivo":4,"texto":"Alertar a los servicios de emergencia y reportar a las autoridades sobre accidentes, señales equivocadas, peligros de tráfico aéreo, marítimo y/o terrestre, y otras emergencias cuando los vehículos, embarcaciones o aeronaves se encuentren en dificultades o reportar su pérdida."},{"consecutivo":5,"texto":"Efectuar seguimientos de vuelos reportando novedades, cancelando o postergando vuelos de acuerdo con condiciones de aeronavegabilidad apropiadas."},{"consecutivo":6,"texto":"Llevar registros de los aspectos operativos del sector del transporte y coordinar los calendarios y horarios del transporte de pasajeros y de carga."},{"consecutivo":7,"texto":"Supervisar, coordinar y programar las actividades operacionales de vehículos de transporte, turnos de trabajo e inspeccionar las rutas para garantizar el cumplimiento de programación y resolver problemas de operación."},{"consecutivo":8,"texto":"Dar instrucciones de despegue y aterrizaje a los pilotos."},{"consecutivo":9,"texto":"Mantener contacto por radio y teléfono con torres cercanas, terminales, sectores y centros de control."},{"consecutivo":10,"texto":"Suministrar información previa al vuelo, concerniente con el estado del tiempo, frecuencias de radio, terreno, aeropuerto para apoyar a los pilotos en la preparación de planes de vuelo."},{"consecutivo":11,"texto":"Suministrar radio-ayudas, información de despegue, arribo y reporte de posiciones, utilizando radares, monitores de circuito cerrado, sistemas de radio a control remoto y otros equipos de comunicación."},{"consecutivo":12,"texto":"Inspeccionar el cumplimiento de las normas reguladoras de tránsito y transporte."},{"consecutivo":13,"texto":"Dirigir y controlar la ruta de tren y la manipulación de carga dentro de una estación, un tramo o una zona de red ferroviaria y mantener los registros pertinentes."},{"consecutivo":14,"texto":"Programar y ordenar tanqueos siguiendo políticas de combustible."},{"consecutivo":15,"texto":"Monitorear y operar tableros de control de señales y cruces del metro."},{"consecutivo":16,"texto":"Verificar el funcionamiento de los vehículos y velar porque se cumpla con su mantenimiento."},{"consecutivo":17,"texto":"Recibir, registrar e impartir órdenes al personal por radio o teléfono."},{"consecutivo":18,"texto":"Delegar en los supervisores de rampa la correcta distribución y amarre de carga."},{"consecutivo":19,"texto":"Elaborar manifiestos relacionados con: peso, balance y planes de vuelo."},{"consecutivo":20,"texto":"Preparar informes relacionados con la inspección y operación de transporte destinados a sus directivos."},{"consecutivo":21,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"43232.001","nombre":"Coordinador de transporte / Coordinadora de transporte"},{"codigo":"43232.002","nombre":"Coordinador de transporte de gas y petróleo / Coordinadora de transporte de gas y petróleo"},{"codigo":"43232.003","nombre":"Coordinador de flota flush by (field services) en la industria petrolera / Coordinadora de flota flush by (field services) en la industria petrolera"},{"codigo":"43232.004","nombre":"Despachador de aerolíneas / Despachadora de aerolíneas"},{"codigo":"43232.005","nombre":"Despachador de aeronaves / Despachadora de aeronaves"},{"codigo":"43232.006","nombre":"Despachador de trenes / Despachadora de trenes"},{"codigo":"43232.007","nombre":"Despachador de vuelos / Despachadora de vuelos"},{"codigo":"43232.008","nombre":"Inspector de operaciones de aeronave / Inspectora de operaciones de aeronave"},{"codigo":"43232.009","nombre":"Inspector ferroviario / Inspectora ferroviaria"},{"codigo":"43232.010","nombre":"Personal de operaciones de vuelo"},{"codigo":"43232.011","nombre":"Planeador de carga / Planeadora de carga"},{"codigo":"43232.012","nombre":"Programador de carga / Programadora de carga"},{"codigo":"43232.013","nombre":"Programador de rutas de transporte terrestre / Programadora de rutas de transporte terrestre"},{"codigo":"43232.014","nombre":"Supervisor de transporte petróleo y gas / Supervisora de transporte petróleo y gas"}],"conocimientos":[{"id":"1","nombre":"Gerencia y administración"},{"id":"6","nombre":"Gestión del talento humano y de personal"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"27","nombre":"Seguridad pública"},{"id":"5","nombre":"Servicio al cliente"},{"id":"31","nombre":"Servicios de transporte"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"11","nombre":"Trabajo en equipo"},{"id":"23","nombre":"Vigilancia de las operaciones"}],"ocupaciones_afines":[{"codigo":"13243","nombre":"Directores y gerentes de transporte, distribución y logística / Directoras y gerentas de transporte, distribución y logística"},{"codigo":"31530","nombre":"Pilotos, ingenieros e instructores de vuelo"},{"codigo":"31540","nombre":"Controladores de tráfico aéreo, marítimo y ferroviario / Controladoras de tráfico aéreo, marítimo y ferroviario"},{"codigo":"33416","nombre":"Supervisores de operación de transporte ferroviario / Supervisoras de operación de transporte ferroviario"},{"codigo":"33417","nombre":"Supervisores de operación de transporte terrestre (no ferroviario) / Supervisoras de operación de transporte terrestre (no ferroviario)"},{"codigo":"43231","nombre":"Empleados y operarios de servicios de transporte / Empleadas y operarias de servicios de transporte"}],"area_principal":{"sigla":"LOTR","nombre":"Logística y transporte"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"4323*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"0812*","cno_obs":"Denominaciones parci