  ('rol_cuoc', 'Empleados auxiliares de bibliotecas / Empleadas auxiliares de bibliotecas', '44110', 'Artes visuales, plásticas y del patrimonio cultural', 2, false, '{"codigo":"44110","nombre":"Empleados auxiliares de bibliotecas / Empleadas auxiliares de bibliotecas","descripcion":"Atienden, orientan y proveen información general a usuarios en el acceso a recursos y servicios de información de la biblioteca; apoyan los procesos de adquisición y catalogación de recursos de información; entregan y reciben material de biblioteca, clasifican, archivan y organizan libros, documentos, grabaciones de sonido y de imagen, publicaciones periódicas, diarios y revistas, entre otros; seleccionan y hacen inventario del material de la biblioteca. Se pueden desempeñar en bibliotecas, archivos u otro tipo de unidades de información, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"44","nombre":"OTRO PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo":{"codigo":"441","nombre":"Otro personal de apoyo administrativo"},"grupo_primario":{"codigo":"4411","nombre":"Empleados de bibliotecas"}},"funciones":[{"consecutivo":1,"texto":"Prestar, entregar y recibir libros y otros recursos de información de la biblioteca."},{"consecutivo":2,"texto":"Ordenar y ubicar los libros y demás recursos de información en los estantes de la biblioteca."},{"consecutivo":3,"texto":"Efectuar búsqueda de referencias en forma manual o computarizada y hacer préstamos ínter bibliotecarios para usuarios."},{"consecutivo":4,"texto":"Realizar actividades administrativas y labores de oficina de las bibliotecas, como archivo, registros manuales o electrónicos de las obras y otros materiales, procesamiento de textos y ocasionalmente trabajos de mecanografía."},{"consecutivo":5,"texto":"Atender y orientar a usuarios de bibliotecas en el acceso, disposición y uso adecuado de libros, textos, revistas, películas, fotografías, mapas, documentos y otros recursos de información de la biblioteca."},{"consecutivo":6,"texto":"Mantener y llevar registros sobre adquisición, préstamo y devolución de libros, y otros recursos de información de la biblioteca."},{"consecutivo":7,"texto":"Apoyar el mantenimiento, la restauración y las labores de conservación del material bibliográfico."},{"consecutivo":8,"texto":"Apoyar los procesos de catalogación de nuevos libros y recursos de información bajo la dirección de bibliotecarios o archivistas."},{"consecutivo":9,"texto":"Apoyar diferentes actividades relacionadas con eventos, comunicaciones y programas de la biblioteca."},{"consecutivo":10,"texto":"Apoyar la elaboración de informes sobre el funcionamiento de la biblioteca."},{"consecutivo":11,"texto":"Realizar el inventario del material bibliográfico."},{"consecutivo":12,"texto":"Apoyar la promoción de la cultura digital en el acceso a información."},{"consecutivo":13,"texto":"Asistir al personal en procesos de implementación de innovación en la prestación de los servicios bibliotecarios y el acceso a la información."},{"consecutivo":14,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"44110.001","nombre":"Archivador de biblioteca / Archivadora de biblioteca"},{"codigo":"44110.002","nombre":"Archivador de biblioteca audiovisual / Archivadora de biblioteca audiovisual"},{"codigo":"44110.003","nombre":"Auxiliar de adquisiciones de biblioteca"},{"codigo":"44110.004","nombre":"Auxiliar de biblioteca"},{"codigo":"44110.005","nombre":"Auxiliar de biblioteca de música"},{"codigo":"44110.006","nombre":"Auxiliar de clasificación de biblioteca"},{"codigo":"44110.007","nombre":"Auxiliar de índices"},{"codigo":"44110.008","nombre":"Auxiliar de préstamo de libros"},{"codigo":"44110.009","nombre":"Auxiliar de referencia de biblioteca"},{"codigo":"44110.010","nombre":"Auxiliar de servicios bibliotecarios"},{"codigo":"44110.011","nombre":"Ayudante de biblioteca"},{"codigo":"44110.012","nombre":"Referencista de biblioteca"},{"codigo":"44110.013","nombre":"Auxiliar en conservación del patrimonio cultural documental bibliográfico"}],"conocimientos":[{"id":"56","nombre":"Bibliotecología, información y archivología"},{"id":"22","nombre":"Educación y capacitación"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"15","nombre":"Orientación al servicio"},{"id":"10","nombre":"Relaciones interpersonales"}],"ocupaciones_afines":[{"codigo":"26220","nombre":"Bibliotecólogos, documentalistas y afines / Bibliotecólogas, documentalistas y afines"},{"codigo":"34332","nombre":"Técnicos en biblioteca / Técnicas en biblioteca"},{"codigo":"34333","nombre":"Técnicos en promoción y animación a la lectura y la escritura / Técnicas en promoción y animación a la lectura y la escritura"},{"codigo":"41101","nombre":"Oficinistas generales"}],"area_principal":{"sigla":"AVPP","nombre":"Artes visuales, plásticas y del patrimonio cultural"},"areas_complementarias":[{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"}],"equivalencias":[{"ciuo08_codigo":"4411*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"1351","cno_obs":"Denominaciones completas"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"5212*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Empleados de servicios de correos / Empleadas de servicios de correos', '44120', 'Logística y transporte', 2, false, '{"codigo":"44120","nombre":"Empleados de servicios de correos / Empleadas de servicios de correos","descripcion":"Clasifican, relacionan y distribuyen correspondencia, paquetes y encomiendas en oficinas de correo y en conexión con los servicios postales u organizaciones relacionadas, así como desde o dentro de un establecimiento; atienden clientes y registran transacciones de correspondencia. Se pueden desempeñar en empresas privadas y estatales que tramitan correo y envíos postales, empresas de servicios públicos, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"44","nombre":"OTRO PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo":{"codigo":"441","nombre":"Otro personal de apoyo administrativo"},"grupo_primario":{"codigo":"4412","nombre":"Empleados de servicios de correos"}},"funciones":[{"consecutivo":1,"texto":"Tramitar y despachar correspondencia en oficinas públicas de correo o en entidades privadas de acuerdo con procesos técnicos y normativa."},{"consecutivo":2,"texto":"Clasificar, aforar, marcar, embalar y distribuir el correo, paquetes y encomiendas que entran y salen de acuerdo con su destino a domicilios privados, públicos y empresas."},{"consecutivo":3,"texto":"Calcular y registrar información, porte postal en cartas, paquetes, correo certificado, recibir pagos y vender estampillas de acuerdo con normativa y procedimiento técnico."},{"consecutivo":4,"texto":"Clasificar y mantener registros sencillos de la correspondencia de entrada y de salida, y expedir la correspondencia saliente en distintos tipos de establecimientos."},{"consecutivo":5,"texto":"Proporcionar los registros de confirmación de entrega cuando el cliente lo solicite."},{"consecutivo":6,"texto":"Firmar o hacer firmar las entregas especiales y el correo certificado."},{"consecutivo":7,"texto":"Llenar formularios para atender reclamos de cambio de dirección, robo o pérdida de correo; realizar informe diario de transacciones."},{"consecutivo":8,"texto":"Organizar el correo, el archivo de gestión y las rutas por direcciones para la entrega de este de acuerdo con normativa."},{"consecutivo":9,"texto":"Atender clientes de acuerdo con procedimiento de servicios y normativa."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"44120.001","nombre":"Auxiliar de correos"},{"codigo":"44120.002","nombre":"Auxiliar de correos y servicio postal"},{"codigo":"44120.003","nombre":"Auxiliar de correspondencia"},{"codigo":"44120.004","nombre":"Auxiliar de oficina de correos"},{"codigo":"44120.005","nombre":"Auxiliar de remesas"},{"codigo":"44120.006","nombre":"Auxiliar de ventanilla de correo"},{"codigo":"44120.007","nombre":"Auxiliar de ventanilla postal"},{"codigo":"44120.008","nombre":"Auxiliar de servicios de correo"},{"codigo":"44120.009","nombre":"Ayudante clasificador de correo / Ayudante clasificadora de correo"},{"codigo":"44120.010","nombre":"Ayudante de servicios de correos"},{"codigo":"44120.011","nombre":"Cartero / Cartera"},{"codigo":"44120.012","nombre":"Cartero mensajero / Cartera mensajera"},{"codigo":"44120.013","nombre":"Clasificador de correo / Clasificadora de correo"},{"codigo":"44120.014","nombre":"Clasificador de correspondencia / Clasificadora de correspondencia"},{"codigo":"44120.015","nombre":"Controlador administrativo de servicio de postal / Controladora administrativa de servicio de postal"},{"codigo":"44120.016","nombre":"Distribuidor de correo / Distribuidora de correo"},{"codigo":"44120.017","nombre":"Empleado de correspondencia / Empleada de correspondencia"},{"codigo":"44120.018","nombre":"Empleado de ventanilla de correo / Empleada de ventanilla de correo"},{"codigo":"44120.019","nombre":"Empleado de ventanilla postal / Empleada de ventanilla postal"}],"conocimientos":[{