  ('rol_cuoc', 'Codificadores de datos, correctores de pruebas de imprenta y afines / Codificadoras de datos, correctores de pruebas de imprenta y afines', '44130', 'Administración, finanzas y derecho', 2, false, '{"codigo":"44130","nombre":"Codificadores de datos, correctores de pruebas de imprenta y afines / Codificadoras de datos, correctores de pruebas de imprenta y afines","descripcion":"Transcriben, codifican y tabulan información; verifican y corrigen pruebas de imprenta, leyéndolas y cotejándolas con el texto original, señalando y corrigiendo los errores en el material para publicación; desempeñan otras labores administrativas relacionadas con la edición y publicación. Se pueden desempeñar en periódicos, revistas, departamentos de publicaciones del sector público y privado, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"44","nombre":"OTRO PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo":{"codigo":"441","nombre":"Otro personal de apoyo administrativo"},"grupo_primario":{"codigo":"4413","nombre":"Codificadores de datos, correctores de pruebas de imprenta y afines"}},"funciones":[{"consecutivo":1,"texto":"Transcribir, codificar y clasificar información por códigos de acuerdo con manuales de cifrado establecidos e ingresarla al computador para el procesamiento de datos."},{"consecutivo":2,"texto":"Comparar las pruebas de texto y el material relacionado preparado para impresión con el material original."},{"consecutivo":3,"texto":"Clasificar formularios y marcarlos con números de identificación."},{"consecutivo":4,"texto":"Clasificar, digitar y tabular datos de la información recogida según los códigos aplicables a una nomenclatura preestablecida."},{"consecutivo":5,"texto":"Verificar la información obtenida para asegurarse que es exacta y completa."},{"consecutivo":6,"texto":"Calcular tarifas y facturar el servicio de avisos clasificados, catálogos, directorios, circulares, sobres y otro material para publicación."},{"consecutivo":7,"texto":"Apoyar en la preparación, redacción, edición y corrección de material y verificación de información de anuncios en periódicos, avisos, catálogos, directorios, circulares, sobres y otro material para publicación."},{"consecutivo":8,"texto":"Leer, verificar y hacer correcciones gramaticales, tipográficas y de composición del trabajo terminado antes de entregar a los empleados encargados para su procesamiento y publicación."},{"consecutivo":9,"texto":"Revisar, identificar y señalar los errores por medio de signos convencionales."},{"consecutivo":10,"texto":"Tramitar la devolución de las pruebas corregidas al taller de composición."},{"consecutivo":11,"texto":"Responder circulares y sobres a mano."},{"consecutivo":12,"texto":"Leer revistas, periódicos, artículos de prensa y otras publicaciones para localizar y sugerir artículos de interés para clientes internos y externos."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"44130.001","nombre":"Auxiliar de clasificación de procesamiento de datos"},{"codigo":"44130.002","nombre":"Auxiliar de codificación"},{"codigo":"44130.003","nombre":"Auxiliar de codificación de procesamiento de datos"},{"codigo":"44130.004","nombre":"Auxiliar de codificación estadística"},{"codigo":"44130.005","nombre":"Auxiliar de edición"},{"codigo":"44130.006","nombre":"Auxiliar de pruebas de lectura"},{"codigo":"44130.007","nombre":"Codificador / Codificadora"},{"codigo":"44130.008","nombre":"Codificador administrativo / Codificadora administrativa"},{"codigo":"44130.009","nombre":"Codificador de censo comercial / Codificadora de censo comercial"},{"codigo":"44130.010","nombre":"Codificador de censo / Codificadora de censo"},{"codigo":"44130.011","nombre":"Codificador de estadísticas / Codificadora de estadísticas"},{"codigo":"44130.012","nombre":"Codificador de guiones / Codificadora de guiones"},{"codigo":"44130.013","nombre"