  ('rol_cuoc', 'Escribientes públicos y afines / Escribientes públicas y afines', '44140', 'Administración, finanzas y derecho', 2, false, '{"codigo":"44140","nombre":"Escribientes públicos y afines / Escribientes públicas y afines","descripcion":"Graban y transcriben literalmente las intervenciones en tribunales, congresos, concejos, asambleas y comités; escriben cartas y diligencian formularios en nombre de personas que no saben leer ni escribir; realizan funciones de apoyo en tribunales, cortes judiciales preparan reportes y correspondencia que requiere del conocimiento de terminología legal. Se pueden desempeñar en tribunales, juzgados, asambleas, congresos y cuerpos legislativos, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"44","nombre":"OTRO PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo":{"codigo":"441","nombre":"Otro personal de apoyo administrativo"},"grupo_primario":{"codigo":"4414","nombre":"Escribientes públicos y afines"}},"funciones":[{"consecutivo":1,"texto":"Leer cartas y otros documentos o escritos a personas que no saben leer ni escribir, ayudarles a interpretar y comprender lo leído y aportarles información pertinente."},{"consecutivo":2,"texto":"Copiar escritos, pasarlos en limpio o escribir dictados."},{"consecutivo":3,"texto":"Escribir cartas y diligenciar formularios en nombre de otras personas."},{"consecutivo":4,"texto":"Transcribir intervenciones grabadas de acuerdo con formatos establecidos garantizando su exactitud."},{"consecutivo":5,"texto":"Registrar palabra a palabra las intervenciones en tribunales, congresos, comités, asambleas legislativas, utilizando máquina estenográfica o equipo computarizado de grabación."},{"consecutivo":6,"texto":"Digitar información confiable utilizando medios tecnológicos existentes."},{"consecutivo":7,"texto":"Ofrecer asesoramiento a las personas y ayudarles a interpretar, comprender o a diligenciar formularios de las autoridades estatales y otros documentos oficiales."},{"consecutivo":8,"texto":"Buscar textos jurídicos necesarios para preparar los datos referentes al caso que está siendo considerado."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"44140.001","nombre":"Amanuense"},{"codigo":"44140.002","nombre":"Auxiliar de escribanía"},{"codigo":"44140.003","nombre":"Escribiente"},{"codigo":"44140.004","nombre":"Escribiente de notarios"},{"codigo":"44140.005","nombre":"Escribiente público / Escribiente pública"},{"codigo":"44140.006","nombre":"Relator / Relatora"},{"codigo":"44140.007","nombre":"Tramitador en general por cuenta propia / Tramitadora en general por cuenta propia"},{"codigo":"44140.008","nombre":"Transcriptor / Transcriptora"},{"codigo":"44140.009","nombre":"Transcriptor y relator / Transcriptora y relatora"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"3","nombre":"Redacción de textos"},{"id":"38","nombre":"Seguir instrucciones"}],"ocupaciones_afines":[{"codigo":"33420","nombre":"Secretarios jurídicos / Secretarias jurídicas"},{"codigo":"33431","nombre":"Asistentes administrativos / Asistentas administrativas"},{"codigo":"34111","nombre":"Asistentes de juzgados, tribunales y afines / Asistentas de juzgados, tribunales y afines"},{"codigo":"41200","nombre":"Secretarios generales / Secretarias generales"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"4414","ciuo08_obs":"Denominacio