  ('rol_cuoc', 'Empleados auxiliares de archivos / Empleadas auxiliares de archivos', '44150', 'Administración, finanzas y derecho', 2, false, '{"codigo":"44150","nombre":"Empleados auxiliares de archivos / Empleadas auxiliares de archivos","descripcion":"Archivan correspondencia, tarjetas, facturas, recibos y otros materiales en orden alfabético o numérico de acuerdo con el sistema de archivo utilizado; localizan y eliminan el material de archivo conforme se les solicite; preparan material de archivo para los procesos de gestión documental de la organización; fotocopian, escanean documentos y los envían por correo electrónico y otras herramientas. Se pueden desempeñar en oficinas de archivo, correspondencia, empresas del sector público y privado, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"44","nombre":"OTRO PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo":{"codigo":"441","nombre":"Otro personal de apoyo administrativo"},"grupo_primario":{"codigo":"4415","nombre":"Empleados de archivos"}},"funciones":[{"consecutivo":1,"texto":"Ordenar, clasificar, codificar, registrar información y archivar los materiales de acuerdo con las directrices relacionadas con el contenido, propósito, los criterios del usuario, orden cronológico, alfabético o numérico, normativa y procedimiento técnico."},{"consecutivo":2,"texto":"Organizar y archivar técnicamente documentos y material en los cajones, armarios y cajas de almacenamiento."},{"consecutivo":3,"texto":"Localizar y recuperar documentos de archivo requeridos por el usuario y eliminar los materiales de los archivos cuando se le solicite."},{"consecutivo":4,"texto":"Operar sistemas de captura de información y facilitar documentos requeridos."},{"consecutivo":5,"texto":"Llevar registros clasificados, base de datos, listas de acceso de los materiales presentados y eliminados de acuerdo con procedimientos técnicos."},{"consecutivo":6,"texto":"Proporcionar información del material archivado de acuerdo con procedimientos técnicos y normativa."},{"consecutivo":7,"texto":"Revisar archivos periódicamente para garantizar que estén completos y clasificados correctamente."},{"consecutivo":8,"texto":"Preparar y mantener índices y rótulos de identificación del contenido de las carpetas para sistemas de clasificación."},{"consecutivo":9,"texto":"Apoyar en la organización y elaboración de los instrumentos de descripción de la documentación custodiada en el archivo, catálogos, inventarios, índices u otros y realizar aquellos que requieran una descripción documental más especializada."},{"consecutivo":10,"texto":"Clasificar documentos para microfilmación."},{"consecutivo":11,"texto":"Apoyar técnicamente el proceso de trámite de documentos de archivo."},{"consecutivo":12,"texto":"Disponer físicamente los documentos de archivo en las unidades de conservación e instalación de acuerdo con las normas archivísticas."},{"consecutivo":13,"texto":"Apoyar los procesos básicos de preservación de documentos."},{"consecutivo":14,"texto":"Apoyar técnicamente el proceso de transferencias documentales."},{"consecutivo":15,"texto":"Fotocopiar, escanear y enviar documentos por correo electrónico y demás herramientas."},{"consecutivo":16,"texto":"Atender clientes de acuerdo con procedimiento de servicios y normativa."},{"consecutivo":17,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"44150.001","nombre":"Asistente de archivística / Asistenta de archivística"},{"codigo":"44150.002","nombre":"Auxiliar de admisiones en archivo"},{"codigo":"44150.003","nombre":"Auxiliar de archivo"},{"codigo":"44150.004","nombre":"Auxiliar de archivo y registro"},{"codigo":"44150.005","nombre":"Auxiliar de duplicación de documentos"},{"codigo":"44150.006","nombre":"Auxiliar de reproducción de documentos"},{"codigo":"44150.007","nombre":"Auxiliar de microfilmación"},{"codigo":"44150.008","nombre":"Auxiliar de radicación en 