  ('rol_cuoc', 'Auxiliares de talento humano', '44161', 'Administración, finanzas y derecho', 2, false, '{"codigo":"44161","nombre":"Auxiliares de talento humano","descripcion":"Recopilan, mantienen, actualizan y tramitan información de los procesos de gestión humana y registros de personal sobre transferencias y promociones, evaluaciones de desempeño, permisos disfrutados y acumulados, salarios, calificaciones y formación. Se pueden desempeñar en departamentos de personal en el sector público y privado, organizaciones de intermediación laboral, empresas de selección temporal, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"44","nombre":"OTRO PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo":{"codigo":"441","nombre":"Otro personal de apoyo administrativo"},"grupo_primario":{"codigo":"4416","nombre":"Empleados del servicio de personal"}},"funciones":[{"consecutivo":1,"texto":"Actualizar la información sobre el historial de empleo, sueldos, evaluaciones de desempeño, calificaciones y formación, permisos disfrutados y acumulados."},{"consecutivo":2,"texto":"Tramitar, verificar y registrar información relacionada con el personal, como selección, ingreso, entrenamiento, evaluación del desempeño y control del ausentismo."},{"consecutivo":3,"texto":"Crear registros de los trabajadores recién nombrados y verificar que la información incorporada esté completa."},{"consecutivo":4,"texto":"Tramitar solicitudes de empleo y promoción y comunicar a los solicitantes de los resultados."},{"consecutivo":5,"texto":"Apoyar el proceso de reclutamiento, contratación, nómina y afiliación de trabajadores a seguridad social, según políticas y procedimientos organizacionales."},{"consecutivo":6,"texto":"Brindar información general de los procesos de gestión del recurso humano de acuerdo con procedimientos organizacionales."},{"consecutivo":7,"texto":"Mantener y actualizar sistemas de archivo y registros manuales o computarizados de hojas de vida y demás documentos de recursos humanos de acuerdo con procedimientos organizacionales."},{"consecutivo":8,"texto":"Apoyar la compilación, elaboración de informes y documentos relacionados con las actividades del personal de acuerdo con procedimientos organizacionales."},{"consecutivo":9,"texto":"Almacenar y recuperar archivos y registros de personal."},{"consecutivo":10,"texto":"Recibir consultas sobre condiciones de empleo y de promoción y comunicar los resultados a los solicitantes."},{"consecutivo":11,"texto":"Apoyar las actividades programadas por el área de talento humano tales como selección, ingreso, bienestar y otras."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"44161.001","nombre":"Auxiliar de asuntos de personal"},{"codigo":"44161.002","nombre":"Auxiliar de bienestar de personal"},{"codigo":"44161.003","nombre":"Auxiliar de compilación de documentos"},{"codigo":"44161.004","nombre":"Auxiliar de contratación"},{"codigo":"44161.005","nombre":"Auxiliar de control de asistencia"},{"codigo":"44161.006","nombre":"Auxiliar de personal"},{"codigo":"44161.007","nombre":"Auxiliar de recursos humanos"},{"codigo":"44161.008","nombre":"Auxiliar de registro de personal"},{"codigo":"44161.009","nombre":"Auxiliar de relaciones laborales"},{"codigo":"44161.010","nombre":"Auxiliar de selección de personal"},{"codigo":"44161.011","nombre":"Auxiliar en talento humano"},{"codigo":"44161.012","nombre":"Auxiliar de gestión humana"},{"codigo":"44161.013","nombre":"Programador de plantilla / Programadora de plantilla"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"6","nombre":"Gestión del talento humano y de personal"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"32","nombre":"Gestión del Talento Humano y de Personal"},{"id":"15","nombre":"Orientación al servicio"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"33432","nombre":"Asistentes de talento humano / Asistentas de talento humano"},{"codigo":"41101","nombre":"Oficinistas generales"},{"codigo":"43130","nombre":"Auxiliares de nómina y prestaciones"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"4416*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"1342","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Auxiliares de seguridad en el trabajo', '44162', 'Salud y bienestar', 2, false, '{"codigo":"44162","nombre":"Auxiliares de seguridad en el trabajo","descripcion":"Apoyan la inspección, las capacitaciones, el manejo de indicadores de gestión y condiciones de los lugares de trabajo; tramitan las incapacidades ante las administradoras de riesgo, procesan información y participan en las actividades de los sistemas de seguridad ambiental, industrial y en el trabajo. Se pueden desempeñar en administradoras de riesgo laboral, aseguradoras, departamentos de recursos humanos de empresas públicas y privadas, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"44","nombre":"OTRO PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo":{"codigo":"441","nombre":"Otro personal de apoyo administrativo"},"grupo_primario":{"codigo":"4416","nombre":"Empleados del servicio de personal"}},"funciones":[{"consecutivo":1,"texto":"Apoyar prácticas seguras y saludables en los ambientes de trabajo con el apoyo en la investigación y desarrollo de la planeación de actividades que promuevan un ambiente apropiado a los trabajadores."},{"consecutivo":2,"texto":"Realizar actividades de articulación con la gestión ambiental en el manejo integral de residuos, así como identificación, fuentes, clasificación y aprovechamiento de estos."},{"consecutivo":3,"texto":"Actualizar la información sobre el historial de accidentes laborales, manejo de residuos, elementos de seguridad e higiene, entre otros."},{"consecutivo":4,"texto":"Monitorear y reportar el cumplimiento de la normatividad relacionada con las condiciones seguras y saludables en el trabajo."},{"consecutivo":5,"texto":"Identificar, inspeccionar y registrar riesgos en el desarrollo de las actividades en el trabajo."},{"consecutivo":6,"texto":"Tramitar solicitudes de requerimientos de elementos de seguridad para los puestos de trabajo y la atención de empleados ante las administradoras de riesgos laborales."},{"consecutivo":7,"texto":"Apoyar la implementación, el registro y el seguimiento del sistema y programas de gestión de seguridad ocupacional, ambiental, industrial e higiene laboral."},{"consecutivo":8,"texto":"Apoyar en la compilación y elaboración de informes y documentos relativos a las actividades de seguridad en el trabajo."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"44162.001","nombre":"Auxiliar de prevención en el trabajo"},{"codigo":"44162.002","nombre":"Auxiliar en seguridad industrial"},{"codigo":"44162.003","nombre":"Auxiliar en seguridad laboral"},{"codigo":"44162.004","nombre":"Auxiliar en seguridad ocupacional"},{"codigo":"44162.005","nombre":"Auxiliar HSEQ (salud, seguridad, medio ambiente y calidad)"},{"codigo":"44162.006","nombre":"Técnico auxiliar de seguridad en el trabajo / Técnica auxiliar de seguridad en el trabajo"},{"codigo":"44162.007","nombre":"Técnico auxiliar de seguridad ocupacional / Técnica auxiliar de seguridad ocupacional"},{"codigo":"44162.008","nombre":"Técnico auxiliar en seguridad ocupacional y laboral / Técnica auxiliar en seguridad ocupacional y laboral"}],"conocimientos":[{"id":"45","nombre":"Gestión del riesgo de desastres"},{"id":"6","nombre":"Gestión del talento humano y de personal"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"41","nombre":"Primeros auxilios"},{"id":"27","nombre":"Seguridad pública"},{"id":"85","nombre":"Seguridad y salud en el trabajo"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"15","nombre":"Orientación al servicio"},{"id":"16","nombre":"Resolución de problemas complejos"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"11","nombre":"Trabajo en equipo"},{"id":"14","nombre":"Transmisión de conocimiento"}],"ocupaciones_afines":[{"codigo":"22630","nombre":"Profesionales de la salud y la higiene laboral y ambiental"},{"codigo":"32571","nombre":"Inspectores de sanidad, seguridad y salud en el trabajo / Inspectoras de sanidad, seguridad y salud en el trabajo"},{"codigo":"32573","nombre":"Técnicos en prevención, gestión y control ambiental / Técnicas en prevención, gestión y control ambiental"},{"codigo":"32574","nombre":"Asistentes en saneamiento ambiental / Asistentas en saneamiento ambiental"},{"codigo":"43130","nombre":"Auxiliares de nómina y prestaciones"}],"area_principal":{"sigla":"SABI","nombre":"Salud y bienestar"},"areas_complementarias":[{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"}],"equivalencias":[{"ciuo08_codigo":"4416*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"2233*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"2313","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Auxiliares de publicación y afines', '44191', 'Literatura y artes gráficas', 2, false, '{"codigo":"44191","nombre":"Auxiliares de publicación y afines","descripcion":"Apoyan en la elaboración de resúmenes de prensa, creación de contenidos para su utilización tanto en línea como en las versiones impresas, corrigen material para publicación, prestan apoyo en todas las operaciones efectuadas en gestión y solución de las actividades administrativas relacionadas con la edición y publicación. Se comunican con el personal del departamento de publicidad y con clientes externos. Se pueden desempeñar en periódicos, revistas, departamentos de publicaciones, agencias de publicidad del sector público y privado, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"44","nombre":"OTRO PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo":{"codigo":"441","nombre":"Otro personal de apoyo administrativo"},"grupo_primario":{"codigo":"4419","nombre":"Otro personal de apoyo administrativo no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Recibir pedidos de los clientes sobre la inserción de textos para avisos clasificados, redactar y editar anuncios publicitarios, calcular tarifas de publicidad y facturar al cliente."},{"consecutivo":2,"texto":"Redactar correspondencia de rutina a nombre de otra persona, empresas o entidades públicas como, por ejemplo, respuestas a solicitudes de información y asistencia, reclamaciones de indemnizaciones por daños, perjuicios y servicios, formularios u otros servicios complementarios ."},{"consecutivo":3,"texto":"Ayudar y apoyar en la preparación, corrección, verificación de la información y elaboración de publicaciones periódicas, anuncios, catálogos y directorios, entre otros."},{"consecutivo":4,"texto":"Leer periódicos, revistas, comunicados de prensa, y demás publicaciones con el fin de localizar archivos y artículos de interés para el personal y los clientes."},{"consecutivo":5,"texto":"Leer el material antes de su publicación para hacer correcciones gramaticales y tipográficas o errores de composición."},{"consecutivo":6,"texto":"Operar herramientas tecnológicas de la información y las comunicaciones disponibles de acuerdo con políticas institucionales, protocolos y manuales."},{"consecutivo":7,"texto":"Cotejar la veracidad de la información de acuerdo con procedimientos y normatividad vigente"},{"consecutivo":8,"texto":"Atender y direccionar a usuarios para la atención de sus requerimientos."},{"consecutivo":9,"texto":"Tramitar información relacionada con la unidad administrativa de acuerdo con procedimientos administrativos y normatividad vigente relacionada."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"44191.001","nombre":"Asistente editorial / Asistenta editorial"},{"codigo":"44191.002","nombre":"Auxiliar de avisos clasificados"},{"codigo":"44191.003","nombre":"Auxiliar de publicación"},{"codigo":"44191.004","nombre":"Auxiliar de resúmenes de prensa"},{"codigo":"44191.006","nombre":"Empleado de publicación / Empleada de publicación"}],"conocimientos":[{"id":"26","nombre":"Filosofía y ética"},{"id":"23","nombre":"Idioma extranjero"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"4","nombre":"Mercadotecnia y publicidad"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"},{"id":"95","nombre":"Ventas al por mayor y al por menor"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"15","nombre":"Orientación al servicio"},{"id":"3","nombre":"Redacción de textos"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"34","nombre":"Trabajo bajo presión"}],"ocupaciones_afines":[{"codigo":"24311","nombre":"Profesionales en mercadeo y publicidad"},{"codigo":"24312","nombre":"Administradores de comunidades virtuales / Administradoras de comunidades virtuales"},{"codigo":"24320","nombre":"Profesionales de relaciones públicas y comunicaciones"},{"codigo":"26421","nombre":"Periodistas"},{"codigo":"33413","nombre":"Supervisores y coordinadores de procesos de negocio, empleados de información y servicio al cliente / Supervisoras y coordinadoras de procesos de negocio, empleadas de información y servicio al cliente"}],"area_principal":{"sigla":"LIAG","nombre":"Literatura y artes gráficas"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"4110*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"1352*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"4419*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"","cno_obs":""}]}'::jsonb),
  ('rol_cuoc', 'Otro personal de apoyo administrativo no clasificados en otras ocupaciones / Otra personal de apoyo administrativo no clasificados en otras ocupaciones', '44199', 'Administración, finanzas y derecho', 2, false, '{"codigo":"44199","nombre":"Otro personal de apoyo administrativo no clasificados en otras ocupaciones / Otra personal de apoyo administrativo no clasificados en otras ocupaciones","descripcion":"Esta ocupación abarca a otro personal de apoyo administrativo no clasificados en otras ocupaciones del Grupo Primario 4419: Otro personal de apoyo administrativo no clasificados en otros grupos primarios. Por ejemplo, incluye aquellos que registran, suministran y actualizan información; y asesoran sobre suscripciones, directorios, productos y servicios asociados con el fin de resolver las inquietudes regulares, canalizan los requerimientos al área correspondiente, orientan a los clientes en el procesamiento y los estados de cuenta. Se pueden desempeñar en el gobierno, las entidades públicas y las empresas que ofrecen servicios de entretenimiento, editoriales, periódicos, revistas, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"4","nombre":"PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo_principal":{"codigo":"44","nombre":"OTRO PERSONAL DE APOYO ADMINISTRATIVO"},"subgrupo":{"codigo":"441","nombre":"Otro personal de apoyo administrativo"},"grupo_primario":{"codigo":"4419","nombre":"Otro personal de apoyo administrativo no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Apoyar en la elaboración de catálogos, directorios, listas de correo y otros documentos o bases de información."},{"consecutivo":2,"texto":"Brindar información telefónica o personal a clientes y público sobre suscripciones, servicios, horarios, tarifas y reglamentaciones."},{"consecutivo":3,"texto":"Responder a requerimientos de clientes e investigar sobre quejas presentadas en relación con servicios de suscripción, procedimientos y productos; hacer devoluciones y cambios de estos."},{"consecutivo":4,"texto":"Operar medios de comunicación telefónica y electrónica para servicio al cliente."},{"consecutivo":5,"texto":"Preparar estados de cuenta de las suscripciones de los clientes y enviarse por correspondencia."},{"consecutivo":6,"texto":"Registrar y procesar la información de suscripciones o directorios."},{"consecutivo":7,"texto":"Identificar las expectativas, deseos y exigencias de los clientes en función de los productos y servicios a obtener, obteniendo y procesando la información requerida para optimizar la prestación del servicio."},{"consecutivo":8,"texto":"Actualizar datos y documentación de acuerdo con estándares de seguimiento, registro y normas de gestión documental para que estos sigan siendo legibles y que no se utilicen documentos obsoletos."},{"consecutivo":9,"texto":"Compilar información necesaria para realizar suscripciones, directorios, listas de correo y demás procesos operacionales de la oficina."},{"consecutivo":10,"texto":"Preparar y recibir pagos de servicios de suscripciones y asociados."},{"consecutivo":11,"texto":"Aplicar reglas ortográficas, gramaticales y garantizar la coherencia en los textos."},{"consecutivo":12,"texto":"Operar herramientas tecnológicas de la información y las comunicaciones disponibles de acuerdo con políticas institucionales, protocolos y manuales."},{"consecutivo":13,"texto":"Cotejar la veracidad de la información de acuerdo con procedimientos y normatividad vigente"},{"consecutivo":14,"texto":"Atender y direccionar a usuarios para la atención de sus requerimientos."},{"consecutivo":15,"texto":"Tramitar información relacionada con la unidad administrativa de acuerdo con procedimientos administrativos y normatividad vigente relacionada."},{"consecutivo":16,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"44199.001","nombre":"Asistente de directorios / Asistenta de directorios"},{"codigo":"44199.002","nombre":"Auxiliar compilador de lista de direcciones / Auxiliar compiladora de lista de direcciones"},{"codigo":"44199.003","nombre":"Auxiliar de lista de correos"},{"codigo":"44199.004","nombre":"Auxiliar de registro de guías y repertorios"},{"codigo":"44199.005","nombre":"Auxiliar de suscripciones"},{"codigo":"44199.006","nombre":"Ayudante de compilación de directorios"},{"codigo":"44199.007","nombre":"Empleado de compilación de directorios / Empleada de compilación de directorios"},{"codigo":"44199.008","nombre":"Auxiliar de reconocimiento predial"}],"conocimientos":[{"id":"23","nombre":"Idioma extranjero"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"4","nombre":"Mercadotecnia y publicidad"},{"id":"50","nombre":"Servicio a la persona y humanización"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"},{"id":"95","nombre":"Ventas al por mayor y al por menor"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"15","nombre":"Orientación al servicio"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"38","nombre":"Seguir instrucciones"}],"ocupaciones_afines":[{"codigo":"42210","nombre":"Empleados de ventas y servicios de viajes / Empleadas de ventas y servicios de viajes"},{"codigo":"42220","nombre":"Empleados de centros de llamadas / Empleadas de centros de llamadas"},{"codigo":"42260","nombre":"Recepcionistas generales"},{"codigo":"44191","nombre":"Auxiliares de publicación y afines"}],"area_principal":{"sigla":"AFDE","nombre":"Administración, finanzas y derecho"},"areas_complementarias":[{"sigla":"COMP","nombre":"Comercio, mercadeo y publicidad"}],"equivalencias":[{"ciuo08_codigo":"4419*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"1333*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"1353*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Personal de servicio a pasajeros', '51110', 'Logística y transporte', 3, false, '{"codigo":"51110","nombre":"Personal de servicio a pasajeros","descripcion":"Garantizan la seguridad y comodidad de los pasajeros durante vuelos, a bordo de barcos y otros medios de transporte como los terrestres; dirigen y operan procedimientos y equipos de emergencia. Se pueden desempeñar en aerolíneas, empresas de transporte terrestre, de turismo y cruceros, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"51","nombre":"TRABAJADORES DE LOS SERVICIOS PERSONALES"},"subgrupo":{"codigo":"511","nombre":"Personal al servicio directo de los pasajeros"},"grupo_primario":{"codigo":"5111","nombre":"Personal de servicio a pasajeros"}},"funciones":[{"consecutivo":1,"texto":"Saludar a pasajeros y comprobar billetes o tarjetas de embarque teniendo en cuenta protocolos de servicio."},{"consecutivo":2,"texto":"Recibir y acomodar a los pasajeros y su equipaje teniendo en cuenta su asiento y necesidades de acuerdo con protocolos y técnicas de servicio."},{"consecutivo":3,"texto":"Informar y demostrar a los pasajeros las medidas y procedimientos de seguridad y de emergencia, tales como: el uso de las máscaras de oxígeno, los cinturones de seguridad, chalecos salvavidas, entre otros."},{"consecutivo":4,"texto":"Servir comidas preparadas y bebidas durante el viaje de acuerdo con protocolos y técnicas de servicio."},{"consecutivo":5,"texto":"Velar por el cumplimiento por parte de los pasajeros, de las normas de seguridad durante el despegue, aterrizaje, desembarco y en caso de emergencias."},{"consecutivo":6,"texto":"Distribuir material de lectura, auriculares, mantas y artículos similares y responder las preguntas formuladas por los pasajeros."},{"consecutivo":7,"texto":"Vender productos libres de impuestos a pasajeros durante el servicio."},{"consecutivo":8,"texto":"Asistir a los pasajeros siguiendo los procedimientos establecidos en el caso de una emergencia o accidente."},{"consecutivo":9,"texto":"Prestar primeros auxilios a pasajeros en caso de necesidad."},{"consecutivo":10,"texto":"Atender a las necesidades generales y la comodidad de los pasajeros, responder a las solicitudes y mantener las cabinas limpias y ordenadas."},{"consecutivo":11,"texto":"Asistir a reuniones de información previa al vuelo sobre: el clima, la altitud, las rutas, los procedimientos de emergencia, la coordinación de la tripulación, las longitudes de los vuelos, el servicio de alimentos y bebidas que ofrece y el número de pasajeros."},{"consecutivo":12,"texto":"Verificar equipos de emergencia para la seguridad de los pasajeros y elaborar los reportes necesarios."},{"consecutivo":13,"texto":"Asistir a los pasajeros en el diligenciamiento de formularios de inmigración o desembarque, de acuerdo con técnicas de servicio."},{"consecutivo":14,"texto":"Determinar y atender las necesidades especiales de asistencia de pasajeros como: niños pequeños, adultos mayores o personas en condición de discapacidad en el sitio de viaje, embarque o desembarque."},{"consecutivo":15,"texto":"Coordinar las actividades de otros auxiliares y elaborar los reportes necesarios."},{"consecutivo":16,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"51110.001","nombre":"Aeromozo / Aeromoza"},{"codigo":"51110.002","nombre":"Auxiliar de servicio a pasajeros"},{"codigo":"51110.003","nombre":"Auxiliar de vuelo"},{"codigo":"51110.004","nombre":"Auxiliar de vuelo en cabina"},{"codigo":"51110.005","nombre":"Auxiliar de servicios a viajeros"},{"codigo":"51110.006","nombre":"Auxiliar de vuelo y sobrecargo"},{"codigo":"51110.007","nombre":"Azafato / Azafata"},{"codigo":"51110.008","nombre":"Azafato de aerolínea / Azafata de aerolínea"},{"codigo":"51110.009","nombre":"Azafato de barco / Azafata de barco"},{"codigo":"51110.010","nombre":"Azafato jefe de barco