  ('rol_cuoc', 'Guías de turismo', '51131', 'Turismo, hotelería y gastronomía', 3, false, '{"codigo":"51131","nombre":"Guías de turismo","descripcion":"Planean, orientan, conducen, instruyen, asisten y controlan los servicios de guionaje turístico durante el servicio contratado o según su especialidad. Interpretan y velan por el bienestar del patrimonio natural y cultural de turistas, viajeros o pasajeros de acuerdo con los requerimientos técnicos, los protocolos y la normativa. Se pueden desempeñar en agencias de viaje, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"51","nombre":"TRABAJADORES DE LOS SERVICIOS PERSONALES"},"subgrupo":{"codigo":"511","nombre":"Personal al servicio directo de los pasajeros"},"grupo_primario":{"codigo":"5113","nombre":"Guías de turismo y anfitriones turísticos locales"}},"funciones":[{"consecutivo":1,"texto":"Planear y controlar el servicio de guionaje turístico de acuerdo con el servicio contratado los requerimientos técnicos y normativos."},{"consecutivo":2,"texto":"Diseñar recorridos turísticos según requerimientos técnicos y normativos."},{"consecutivo":3,"texto":"Conducir usuarios de acuerdo con técnicas y tipo de recorrido turístico y normativa."},{"consecutivo":4,"texto":"Diseñar guiones interpretativos de acuerdo con tipo de patrimonio y técnicas de redacción."},{"consecutivo":5,"texto":"Velar y fomentar la protección y el bienestar del patrimonio cultural y natural, turistas, viajeros o pasajeros según requerimientos técnicos y normativos."},{"consecutivo":6,"texto":"Apoyar la gestión y el desarrollo de destinos turísticos teniendo en cuenta la normativa del sector."},{"consecutivo":7,"texto":"Traducir información en idioma extranjero o lenguas nativas de acuerdo con requerimientos técnicos."},{"consecutivo":8,"texto":"Saludar y registrar visitantes, turistas, viajeros o pasajeros y emitir cualquier identificación, placas o dispositivos de seguridad que se requiera según requerimientos técnicos y normativos."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"51131.001","nombre":"Guía de cabalgata"},{"codigo":"51131.002","nombre":"Guía de descubrimientos"},{"codigo":"51131.003","nombre":"Guía de establecimientos industriales"},{"codigo":"51131.004","nombre":"Guía de excursiones"},{"codigo":"51131.005","nombre":"Guía de galería de arte"},{"codigo":"51131.006","nombre":"Guía de gira"},{"codigo":"51131.007","nombre":"Guía de montañismo"},{"codigo":"51131.008","nombre":"Guía de museo"},{"codigo":"51131.009","nombre":"Guía de parque temático"},{"codigo":"51131.010","nombre":"Guía de parques naturales"},{"codigo":"51131.011","nombre":"Guía de turismo"},{"codigo":"51131.012","nombre":"Guía de turismo cultural"},{"codigo":"51131.013","nombre":"Guía de turismo de aventura"},{"codigo":"51131.014","nombre":"Guía de turismo especializado"},{"codigo":"51131.015","nombre":"Guía de viaje"}],"conocimientos":[{"id":"25","nombre":"Historia y arqueología"},{"id":"23","nombre":"Idioma extranjero"},{"id":"43","nombre":"Patrimonio cultural"},{"id":"44","nombre":"Patrimonio natural"},{"id":"41","nombre":"Primeros auxilios"},{"id":"5","nombre":"Servicio al cliente"},{"id":"19","nombre":"Sociología, antropología y estudios culturales"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"15","nombre":"Orientación al servicio"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"3","nombre":"Redacción de textos"},{"id":"10","nombre":"Relaciones interpersonales"}],"ocupaciones_afines":[{"codigo":"34331","nombre":"Ocupaciones técnicas relacionadas con museos y galerías"}],"area_principal":{"sigla":"TUHG","nombre":"Turismo, hotelería y gastronomía"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"5113*","ciuo08_obs":"Denominaciones parcial