  ('rol_cuoc', 'Anfitriones turísticos locales / Anfitrionas turísticas locales', '51132', 'Turismo, hotelería y gastronomía', 2, false, '{"codigo":"51132","nombre":"Anfitriones turísticos locales / Anfitrionas turísticas locales","descripcion":"Transmiten su conocimiento sobre el patrimonio natural y cultural de su territorio a visitantes. Brindan acompañamiento a los visitantes en su ámbito geográfico local. Brindan información manteniendo su autenticidad sociocultural enriqueciendo la experiencia turística. Promueven la conservación y protegen el territorio. Se pueden desempeñar en agencias de viaje, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"51","nombre":"TRABAJADORES DE LOS SERVICIOS PERSONALES"},"subgrupo":{"codigo":"511","nombre":"Personal al servicio directo de los pasajeros"},"grupo_primario":{"codigo":"5113","nombre":"Guías de turismo y anfitriones turísticos locales"}},"funciones":[{"consecutivo":1,"texto":"Transmitir sus conocimientos sobre el patrimonio natural y cultural de su territorio según protocolos de servicio y técnicas de comunicación."},{"consecutivo":2,"texto":"Informar sobre el patrimonio local de acuerdo con las características geográficas, culturales, requerimientos técnicos, normativos y protocolo de la comunidad local."},{"consecutivo":3,"texto":"Narrar historias y experiencias de la comunidad a visitantes de acuerdo con los principios de protección del patrimonio natural y cultural."},{"consecutivo":4,"texto":"Mediar sobre los intereses y el alcance de intervención entre el visitante y la comunidad."},{"consecutivo":5,"texto":"Intervenir entre los prestadores de servicios turísticos locales del territorio facilitando la operación turística."},{"consecutivo":6,"texto":"Promover la conservación y protección del patrimonio natural y cultural entre los visitantes y la comunidad, según protocolos y técnicas de comunicación."},{"consecutivo":7,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"51132.001","nombre":"Anfitrión turístico local / Anfitriona turística local"},{"codigo":"51132.002","nombre":"Baquiano / Baquiana"},{"codigo":"51132.003","nombre":"Intérprete ambiental local"},{"codigo":"51132.004","nombre":"Intérprete histórico local"},{"codigo":"51132.005","nombre":"Interprete turístico local"}],"conocimientos":[{"id":"52","nombre":"Adquisición del lenguaje"},{"id":"20","nombre":"Geografía y territorio"},{"id":"43","nombre":"Patrimonio cultural"},{"id":"44","nombre":"Patrimonio natural"},{"id":"41","nombre":"Primeros auxilios"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"33","nombre":"Liderazgo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"42252","nombre":"Informadores turísticos / Informadoras turísticas"}],"area_principal":{"sigla":"TUHG","nombre":"Turismo, hotelería y gastronomía"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"5113*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"6647","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Cocineros / Cocineras', '51201', 'Turismo, hotelería y gastronomía', 2, false, '{"codigo":"51201","nombre":"Cocineros / Cocineras","descripcion":"Planean, organizan, preparan y cocinan alimentos, comidas y menús según recetas o bajo supervisión. Se pueden desempeñar en restaurantes, casinos, hoteles, hospitales, instituciones educativas, centros carcelarios, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"51","nombre":"TRABAJADORES DE LOS SERVICIOS PERSONALES"},"subgrupo":{"codigo":"512","nombre":"Cocineros"},"grupo_primario":{"codigo":"5120","nombre":"Cocineros"}},"funciones":[{"consecutivo":1,"texto":"Planear, preparar y cocinar menús completos, platos individuales, especiales, postres y entre otros, según instrucciones, técnicas, tipos y estilos de comida."},{"consecutivo":2,"texto":"Preparar y cocinar menús especiales en hospitales o clínicas para pacientes, según instrucciones del nutricionista o del chef."},{"consecutivo":3,"texto":"Planear menús, determinar tamaño de porciones de alimentos, estimar ingredientes y costos de los alimentos y solicitar suministros."},{"consecutivo":4,"texto":"Operar equipos y herramientas de cocina para la preparación de alimentos."},{"consecutivo":5,"texto":"Inspeccionar y limpiar equipos, herramientas, áreas de servicio y cocina de acuerdo con buenas prácticas sanitarias."},{"consecutivo":6,"texto":"Supervisar a los ayudantes y auxiliares de cocina en la preparación, el manejo y la calidad de los alimentos."},{"consecutivo":7,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"51201.001","nombre":"Cocinero / Cocinera"},{"codigo":"51201.002","nombre":"Cocinero de campamentos de trabajo / Cocinera de campamentos de trabajo"},{"codigo":"51201.003","nombre":"Cocinero de cocina fría / Cocinera de cocina fría"},{"codigo":"51201.004","nombre":"Cocinero de barco / C