  ('rol_cuoc', 'Sabedores de la cocina tradicional / Sabedoras de la cocina tradicional', '51202', 'Artes visuales, plásticas y del patrimonio cultural', 2, false, '{"codigo":"51202","nombre":"Sabedores de la cocina tradicional / Sabedoras de la cocina tradicional","descripcion":"Preparan alimentos y bebidas de las regiones culinarias colombianas haciendo uso de los ingredientes, las materias primas, los utensilios y las técnicas propias de la cocina tradicional, salvaguardando el patrimonio cultural asociado a las cocinas tradicionales. Realizan las preparaciones bajo parámetros de buenas prácticas y tradiciones propias de la cultura culinaria, teniendo en cuenta las manifestaciones sociales y culturales asociadas a la alimentación tradicional, herramientas de gestión y fomento del patrimonio cultural. Se pueden desempeñar en restaurantes, hoteles, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"51","nombre":"TRABAJADORES DE LOS SERVICIOS PERSONALES"},"subgrupo":{"codigo":"512","nombre":"Cocineros"},"grupo_primario":{"codigo":"5120","nombre":"Cocineros"}},"funciones":[{"consecutivo":1,"texto":"Participar en actividades de salvaguardia de las tradiciones culinarias y sus prácticas de acuerdo con la identidad cultural de las regiones y las técnicas tradicionales."},{"consecutivo":2,"texto":"Aprovisionar las materias primas y recursos físicos del menú de acuerdo con las tradiciones culinarias y alimenticias."},{"consecutivo":3,"texto":"Administrar y gestionar cocinas tradicionales regionales colombianas, según estándares de calidad e inocuidad de los alimentos y satisfacción de los consumidores."},{"consecutivo":4,"texto":"Producir preparaciones de las cocinas regionales, según su contexto social, cultural y las técnicas tradicionales."},{"consecutivo":5,"texto":"Aplicar técnicas tradicionales como ahumado, madurado, macerado y moquiado."},{"consecutivo":6,"texto":"Determinar las características del menú de acuerdo con las tradiciones culinarias y alimenticias de la región."},{"consecutivo":7,"texto":"Realizar acciones de transmisión se saberes asociados a las cocinas regionales tales: enseñanzas de las técnicas tradicionales, se los tipos de preparación, identificación de productos alimenticios para la preparación de menús de acuerdo con las tradiciones culinarias."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"51202.001","nombre":"Aprendiz de la cocina tradicional / Aprendiza de la cocina tradicional"},{"codigo":"51202.002","nombre":"Artesano de la cocina / Artesana de la cocina"},{"codigo":"51202.003","nombre":"Cocinera tradicional / Cocinero tradicional"},{"codigo":"51202.004","nombre":"Cocinero colombiano / Cocinera colombiana"},{"codigo":"51202.005","nombre":"Portador de la cocina tradicional / Portadora de la cocina tradicional"},{"codigo":"51202.006","nombre":"Sabedor de la cocina tradicional / Sabedora de la cocina tradicional"},{"codigo":"51202.007","nombre":"Transformador de bebidas tradicionales / Transformadora de bebidas tradicionales"}],"conocimientos":[{"id":"37","nombre":"Manipulación de alimentos"},{"id":"43","nombre":"Patrimonio cultural"},{"id":"8","nombre":"Procesamiento de alimentos"},{"id":"7","nombre":"Producción y procesamiento"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"51201","nombre":"Cocineros / Cocineras"},{"codigo":"52120","nombre":"Vendedores ambulantes de alimentos preparados para consumo inmediato / Vendedoras ambulantes de alimentos preparados para consumo inmediato"},{"codigo":"75121","no