  ('rol_cuoc', 'Bartenders', '51321', 'Turismo, hotelería y gastronomía', 2, false, '{"codigo":"51321","nombre":"Bartenders","descripcion":"Preparan, mezclan y sirven bebidas alcohólicas y no alcohólicas directamente a los clientes sobre una barra o mostrador, o a través de meseros, manipulan alimentos, controlan las materias primas y los insumos a su cargo. Se pueden desempeñar en restaurantes, hoteles, bares, tabernas, clubes, casas de banquetes, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"51","nombre":"TRABAJADORES DE LOS SERVICIOS PERSONALES"},"subgrupo":{"codigo":"513","nombre":"Meseros y bármanes"},"grupo_primario":{"codigo":"5132","nombre":"Bármanes y baristas"}},"funciones":[{"consecutivo":1,"texto":"Efectuar operaciones de alistamiento para el servicio de bebidas de acuerdo con procedimientos técnicos y estándares del establecimiento."},{"consecutivo":2,"texto":"Tomar pedidos de bebidas del personal de servicio o directamente de los clientes de acuerdo con los protocolos del establecimiento."},{"consecutivo":3,"texto":"Preparar y servir alcohólicas y no alcohólicas según procedimientos técnicos y estándares del establecimiento."},{"consecutivo":4,"texto":"Mezclar bebidas alcohólicas, no alcohólicas y otros ingredientes para preparar cócteles y otras bebidas, según procedimientos técnicos y estándares del establecimiento."},{"consecutivo":5,"texto":"Higienizar elementos, maquinarias y áreas del servicio del bar de acuerdo con protocolos y estándares del establecimiento."},{"consecutivo":6,"texto":"Mantener el inventario, controlar existencias, organizar las botellas y la cristalería del bar, según procedimientos técnicos y estándares del establecimiento."},{"consecutivo":7,"texto":"Comprobar la identificación de los clientes y verificar los requisitos de edad para la compra de alcohol."},{"consecutivo":8,"texto":"Tomar medidas para limitar los problemas relacionados con el consumo excesivo de alcohol, tales como persuadir a los clientes a dejar de beber, disminuyendo los servicios adicionales y pedir transporte."},{"consecutivo":9,"texto":"Manipular los barriles y conectar los conductos de salida tiendo en cuenta las indicaciones del proveedor."},{"consecutivo":10,"texto":"Supervisar, coordinar y programar las actividades del personal que prepara y porciona."},{"consecutivo":11,"texto":"Recibir y registrar los pagos en la caja registradora, según políticas del establecimiento."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"51321.001","nombre":"Auxiliar de bar"},{"codigo":"51321.002","nombre":"Ayudante de bar"},{"codigo":"51321.003","nombre":"Barman"},{"codigo":"51321.004","nombre":"Bartender"},{"codigo":"51321.005","nombre":"Cantinero / Cantinera"},{"codigo":"51321.006","nombre":"Coctelero / Coctelera"},{"codigo":"51321.007","nombre":"Jefe de bar / Jefa de bar"},{"codigo":"51321.008","nombre":"Preparador de bebidas / Preparadora de bebidas"},{"codigo":"51321.009","nombre":"Tabernero / Tabernera"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"6","nombre":"Gestión del talento humano y de personal"},{"id":"23","nombre":"Idioma extranjero"},{"id":"37","nombre":"Manipulación de alimentos"},{"id":"14","nombre":"Matemáticas"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"14120","nombre":"Gerentes y administradores de servicios de alimentos y restaurantes / Gerentas y administradoras de servicios de alimentos y restaurantes"},{"codigo":"51310","nombre":"Meseros 