  ('rol_cuoc', 'Baristas', '51322', 'Turismo, hotelería y gastronomía', 2, false, '{"codigo":"51322","nombre":"Baristas","descripcion":"Operan los diferentes métodos de preparación del café, mezclan y sirven bebidas calientes y frías basadas en café directamente a los clientes sobre una barra o mostrador, o a través de meseros siguiendo normas y protocolos de atención, buenas prácticas de manufactura, salud y seguridad industrial. Identifican los diversos tipos de proceso, variedades y orígenes de café, distinguen tipos de tueste y molienda de este. Se pueden desempeñar en restaurantes, hoteles, bares, tabernas, clubes, casas de banquetes, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"51","nombre":"TRABAJADORES DE LOS SERVICIOS PERSONALES"},"subgrupo":{"codigo":"513","nombre":"Meseros y bármanes"},"grupo_primario":{"codigo":"5132","nombre":"Bármanes y baristas"}},"funciones":[{"consecutivo":1,"texto":"Tomar pedidos de bebidas a base de café al personal de servicio o directamente a los clientes."},{"consecutivo":2,"texto":"Preparar y servir bebidas calientes y frías basadas en las diferentes presentaciones o tipos de café de acuerdo con principios técnicos, normativos y gastronómicos."},{"consecutivo":3,"texto":"Preparar bebidas a base de café para los meseros o servir directamente a los clientes."},{"consecutivo":4,"texto":"Hacer mantenimiento en el lugar de trabajo a equipos y maquinaria utilizada para la preparación del café."},{"consecutivo":5,"texto":"Realizar inventario y controlar existencias de la tienda o establecimiento."},{"consecutivo":6,"texto":"Aplicar la normativa de las Buenas Prácticas de Manufactura (BPM), Salud y Seguridad Industrial en el manejo de las materias primas y la elaboración de los productos."},{"consecutivo":7,"texto":"Desarrollar habilidades sociales y comerciales que faciliten la interacción con el cliente durante la prestación del servicio."},{"consecutivo":8,"texto":"Orientar a los clientes sobre la cultura institucional del consumo del café y su historia."},{"consecutivo":9,"texto":"Recibir y registrar los pagos en la caja registradora según políticas del establecimiento."},{"consecutivo":10,"texto":"Identificar los diferentes tipos de proceso, variedades y orígenes de café, distinguir diversos tipos de tueste y molienda del café e identificar la calidad del agua, operar métodos de preparación resaltando las características en taza."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"51322.001","nombre":"Barista"},{"codigo":"51322.002","nombre":"Preparador de café por filtrado / Preparadora de café por filtrado"},{"codigo":"51322.003","nombre":"Preparador de cafés expreso / Preparadora de cafés expreso"},{"codigo":"51322.004","nombre":"Técnico en preparación de café / Técnica en preparación de café"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"6","nombre":"Gestión del talento humano y de personal"},{"id":"23","nombre":"Idioma extranjero"},{"id":"37","nombre":"Manipulación de alimentos"},{"id":"14","nombre":"Matemáticas"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"14120","nombre":"Gerentes y administradores de servicios de alimentos y restaurantes / Gerentas y administradoras de servicios de alimentos y restaurantes"},{"codigo":"51310","nombre":"Meseros y capitanes de servicio a la mesa / Meseras y capitanes de servicio a la mesa"},{"codigo":"51321","nombre":"Bartenders"}],"area_principal":{"sigla":"TUHG","nombre":"Turismo, hotele