  ('rol_cuoc', 'Supervisores de mantenimiento y limpieza en oficinas, hoteles y otros establecimientos / Supervisoras de mantenimiento y limpieza en oficinas, hoteles y otros establecimientos', '51510', 'Servicios Personales y a la Comunidad', 3, false, '{"codigo":"51510","nombre":"Supervisores de mantenimiento y limpieza en oficinas, hoteles y otros establecimientos / Supervisoras de mantenimiento y limpieza en oficinas, hoteles y otros establecimientos","descripcion":"Planean, supervisan, coordinan y controlan los servicios y las operaciones de mantenimiento y limpieza en oficinas, hoteles y otros establecimientos bajo la conducción general de otros directores. Realizan capacitación de las funciones laboras al personal a su cargo. Coordinan actividades de mantenimiento y limpieza con otros grupos, áreas o departamentos de la empresa donde trabajan; están en capacidad de ejercer las tareas inherentes al grupo del cual son responsables. Se pueden desempeñar en hospitales, teatros, lavandería, colegios, establecimientos comerciales, empresas de servicios de limpieza, empresas de servicio doméstico, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"51","nombre":"TRABAJADORES DE LOS SERVICIOS PERSONALES"},"subgrupo":{"codigo":"515","nombre":"Supervisores de mantenimiento y limpieza de edificios"},"grupo_primario":{"codigo":"5151","nombre":"Supervisores de mantenimiento y limpieza en oficinas, hoteles y otros establecimientos"}},"funciones":[{"consecutivo":1,"texto":"Inspeccionar y comunicar el estado de los lugares de trabajo y las instalaciones para garantizar el cumplimiento de normas de higiene y seguridad industrial."},{"consecutivo":2,"texto":"Definir y dirigir procedimientos operacionales para el desarrollo de las actividades relacionadas con mantenimiento y limpieza en oficinas, hoteles y otros establecimientos."},{"consecutivo":3,"texto":"Determinar, supervisar y controlar el suministro, el almacenamiento y el inventario de materiales y equipos requeridos para el mantenimiento y la limpieza en oficinas, hoteles y otros establecimientos."},{"consecutivo":4,"texto":"Preparar y presentar informes de gestión administrativos y financieros del establecimiento o lugar de trabajo."},{"consecutivo":5,"texto":"Planear, entrenar y supervisar al personal a su cargo en el desarrollo de sus funciones, utilización de recursos, horarios, normas de seguridad y reglamentos internos de trabajo."},{"consecutivo":6,"texto":"Establecer y coordinar actividades de mantenimiento y limpieza con otros grupos o departamentos de la empresa."},{"consecutivo":7,"texto":"Generar e implementar planes de acción y mejoramiento a los servicios de mantenimiento y limpieza en oficinas, hoteles y otros establecimientos."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"51510.001","nombre":"Amo de llaves hotel / Ama de llaves hotel"},{"codigo":"51510.002","nombre":"Coordinador de aseo externo / Coordinadora de aseo externo"},{"codigo":"51510.003","nombre":"Coordinador de aseo interno / Coordinadora de aseo interno"},{"codigo":"51510.004","nombre":"Coordinador de servicios generales / Coordinadora de servicios generales"},{"codigo":"51510.005","nombre":"Jefe de alojamiento / Jefa de alojamiento"},{"codigo":"51510.006","nombre":"Jefe de aseo / Jefa de aseo"},{"codigo":"51510.007","nombre":"Jefe de camareras de hotel / Jefa de camareras de hotel"},{"codigo":"51510.008","nombre":"Jefe de habitaciones / Jefa de habitaciones"},{"codigo":"51510.009","nombre":"Jefe de lavandería / Jefa de lavandería"},{"codigo":"51510.010","nombre":"Jefe de lavandería hotel / Jefa de lavandería hotel"},{"codigo":"51510.011","nombre":"Jefe de piso de hospedaje / Jefa de piso de hospedaje"},{"codigo":"51510.012","nombre":"Jefe de servicios generales / Jefa de servicios generales"},{"codigo":"51510.013","nombre":"Ma