  ('rol_cuoc', 'Conserjes y afines', '51530', 'Servicios Personales y a la Comunidad', 2, false, '{"codigo":"51530","nombre":"Conserjes y afines","descripcion":"Realizan el mantenimiento de edificios de apartamentos, conjuntos, hoteles, oficinas, iglesias y otros, junto con los terrenos asociados, y los conserva limpios y ordenados; ayudan con reparaciones menores, y sirven como persona de contacto para los residentes; dependiendo del tamaño y la naturaleza del edificio, pueden supervisar a otros trabajadores y contratistas de mantenimiento. Se pueden desempeñar en hospitales, centros educativos, comunidades religiosas, establecimientos comerciales, empresas de servicios de limpieza, domésticos, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"51","nombre":"TRABAJADORES DE LOS SERVICIOS PERSONALES"},"subgrupo":{"codigo":"515","nombre":"Supervisores de mantenimiento y limpieza de edificios"},"grupo_primario":{"codigo":"5153","nombre":"Conserjes y afines"}},"funciones":[{"consecutivo":1,"texto":"Supervisar al personal y los contratistas en las labores de mantenimiento y de limpieza, según el servicio contratado."},{"consecutivo":2,"texto":"Prestar servicios de recepción, limpieza, mantenimiento y reparaciones simples al interior de edificios, conjuntos e instalaciones."},{"consecutivo":3,"texto":"Informar al administrador y residentes sobre las necesidades de reparación y mantenimiento."},{"consecutivo":4,"texto":"Operar y vigilar el funcionamiento de sistemas de calefacción, ventilación y suministro de agua caliente, entre otros."},{"consecutivo":5,"texto":"Informar sobre el incumplimiento de las normas de convivencia al interior del edificio o conjunto y las zonas comunes por parte de los residentes y los visitantes."},{"consecutivo":6,"texto":"Realizar el mantenimiento y notificar la disponibilidad de los lugares donde se van a realizar actos o celebraciones, de acuerdo con el protocolo del edificio o conjunto."},{"consecutivo":7,"texto":"Procurar el cumplimiento del protocolo establecido al interior del edificio o conjunto frente a la disponibilidad de zonas comunes, la entrega de correspondencia, entre otros."},{"consecutivo":8,"texto":"Recibir, ordenar y entregar en nombre de propietarios o inquilinos ausentes paquetes y/o correspondencia conforme a protocolos establecidos."},{"consecutivo":9,"texto":"Brindar información u orientación solicitada a los residentes, huéspedes o inquilinos de acuerdo con protocolos establecidos."},{"consecutivo":10,"texto":"Diligenciar el registro de visitantes y proporcionar copias de manuales y/o reglamentos."},{"consecutivo":11,"texto":"Preparar, ordenar los equipos y prestar apoyo en la realización de ritos religiosos."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"51530.001","nombre":"Conserje"},{"codigo":"51530.002","nombre":"Conserje de edificio"},{"codigo":"51530.003","nombre":"Sacristán / Sacristana"}],"conocimientos":[{"id":"38","nombre":"Mantenimiento"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"15","nombre":"Orientación al servicio"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"26","nombre":"Reparación"}],"ocupaciones_afines":[{"codigo":"51520","nombre":"Ecónomos y mayordomos domésticos / Ecónomas y mayordomas domésticas"},{"codigo":"51510","nombre":"Supervisores de mantenimiento y limpieza en oficinas, hoteles y otros establecimientos / Supervisoras de mantenimiento y limpieza en oficinas, hoteles y otros establecimientos"},{"codigo":"42240","nombre":"Recepcionistas de hoteles"}],"area_principal":{"sigla":"SEPC","nombre":"Servicios Personales y a la Comunidad"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"5153","ciuo08_obs":"Denominaciones completas","cno_codigo":"6641*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Astrólogos, adivinos y afines / Astrólogas, adivinas y afines', '51610', 'Servicios Personales y a la Comunidad', 2, false, '{"codigo":"51610","nombre":"Astrólogos, adivinos y afines / Astrólogas, adivinas y afines","descripcion":"Indagan el pasado y predicen los acontecimientos futuros en la vida de los usuarios mediante la práctica de la astrología, consultoría mental, cartomancia, lectura de las líneas de las manos y de los naipes echados al azar; aconsejan o advierten acerca de eventuales comportamientos o sucesos y utilizan otras técnicas similares. Se pueden desempeñar en centros esotéricos, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"51","nombre":"TRABAJADORES DE LOS SERVICIOS PERSONALES"},"subgrupo":{"codigo":"516","nombre":"Otros trabajadores de servicios personales"},"grupo_primario":{"codigo":"5161","nombre":"Astrólogos, adivinos y afines"}},"funciones":[{"consecutivo":1,"texto":"Estudiar e interpretar posiciones planetarias y estelares sobre el horóscopo del usuario para rastrear el pasado, predecir el futuro y eventuales comportamientos o sucesos para un cliente o público en general."},{"consecutivo":2,"texto":"Vaticinar el porvenir aplicando métodos astrológicos, la influencia de los astros y de otros fenómenos en la vida del usuario sobre posibles acciones a tomar."},{"consecutivo":3,"texto":"Interpretar las características de las líneas de las palmas de las manos, las cartas, el azar, restos de café o chocolate en una taza, entre otros para predecir el futuro."},{"consecutivo":4,"texto":"Elaborar cartas astrales de acuerdo con la fecha, la hora y el lugar de nacimiento del cliente."},{"consecutivo":5,"texto":"Determinar y aconsejar el momento más propicio para emprender determinadas actividades o actos tales como inauguraciones, matrimonios, viajes, negocios, ceremonias, entre otros."},{"consec