  ('rol_cuoc', 'Acompañantes', '51620', 'Servicios Personales y a la Comunidad', 2, false, '{"codigo":"51620","nombre":"Acompañantes","descripcion":"Acompañan de sus empleadores y usuarios, atienden diversos requerimientos y necesidades personales de estos. Se pueden desempeñar en agencias de servicios, particulares, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"51","nombre":"TRABAJADORES DE LOS SERVICIOS PERSONALES"},"subgrupo":{"codigo":"516","nombre":"Otros trabajadores de servicios personales"},"grupo_primario":{"codigo":"5162","nombre":"Acompañantes"}},"funciones":[{"consecutivo":1,"texto":"Acompañar a sus empleadores a eventos sociales, visitas, viajes, entre otros de acuerdo con el servicio contratado."},{"consecutivo":2,"texto":"Participar con los empleadores en diversas actividades deportivas, lecturas, conversaciones, en otras de acuerdo con el servicio contratado."},{"consecutivo":3,"texto":"Recibir y entretener a los visitantes que acudan a la casa del empleador de acuerdo con el servicio contratado."},{"consecutivo":4,"texto":"Mantener en orden y buen estado los elementos personales del empleador de acuerdo con el servicio contratado."},{"consecutivo":5,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"51620.001","nombre":"Acompañante"},{"codigo":"51620.002","nombre":"Acompañante domiciliario / Acompañante domiciliaria"},{"codigo":"51620.003","nombre":"Caballero de compañía / Dama de compañía"},{"codigo":"51620.004","nombre":"Criada personal / Criado personal"},{"codigo":"51620.006","nombre":"Señor de compañía / Señora de compañía"}],"conocimientos":[{"id":"1","nombre":"Gerencia y administración"},{"id":"23","nombre":"Idioma extranjero"},{"id":"14","nombre":"Matemáticas"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"39","nombre":"Crea