  ('rol_cuoc', 'Personal de servicios funerarios', '51633', 'Servicios Personales y a la Comunidad', 2, false, '{"codigo":"51633","nombre":"Personal de servicios funerarios","descripcion":"Realizan la disposición del lugar de velación y supervisan la ejecución del servicio funerario de acuerdo con lo pactado con el cliente, los deudos y los procedimientos de la organización. Acompañan a los deudos durante el servicio funerario. Se pueden desempeñar en organizaciones que prestan servicios funerarios, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"51","nombre":"TRABAJADORES DE LOS SERVICIOS PERSONALES"},"subgrupo":{"codigo":"516","nombre":"Otros trabajadores de servicios personales"},"grupo_primario":{"codigo":"5163","nombre":"Personal de servicios funerarios y embalsamadores"}},"funciones":[{"consecutivo":1,"texto":"Disponer el lugar de velación con adornos florales y demás elementos necesarios para llevar a cabo funerales, cremaciones y sepelios de acuerdo con lo pactado con los deudos y procedimientos de la organización."},{"consecutivo":2,"texto":"Acompañar y orientar a los dolientes durante el servicio funerario de acuerdo con los protocolos de servicio de la organización."},{"consecutivo":3,"texto":"Atender a los clientes de acuerdo con procedimientos de servicio."},{"consecutivo":4,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"51633.001","nombre":"Auxiliar de funeraria"},{"codigo":"51633.002","nombre":"Auxiliar de morgue"},{"codigo":"51633.003","nombre":"Auxiliar de servicios de velación"},{"codigo":"51633.004","nombre":"Auxiliar en servicios funerarios"},{"codigo":"51633.005","nombre":"Ayudante de funeraria"},{"codigo":"51633.006","nombre":"Ayudante de pompas fúnebres"}],"conocimientos":[{"id":"36","nombre":"Manejo de las TIC"},{"id":"4","nombre":"Mercadotecnia y publicidad"},{"id":"5","nombre":"Ser