  ('rol_cuoc', 'Instructores de conducción / Instructoras de conducción', '51650', 'Educación y formación', 3, false, '{"codigo":"51650","nombre":"Instructores de conducción / Instructoras de conducción","descripcion":"Instruyen a particulares sobre técnicas, destrezas y condiciones de conducción; enseñan normas, reglamento de tráfico y seguridad vial de acuerdo con lineamentos técnicos; explican y demuestran el funcionamiento mecánico y general de vehículos; se pueden desempeñar en escuelas, instituciones de formación para el trabajo, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"51","nombre":"TRABAJADORES DE LOS SERVICIOS PERSONALES"},"subgrupo":{"codigo":"516","nombre":"Otros trabajadores de servicios personales"},"grupo_primario":{"codigo":"5165","nombre":"Instructores de conducción"}},"funciones":[{"consecutivo":1,"texto":"Instruir a particulares sobre técnicas, destrezas y condiciones de conducción, explicando y demostrando el funcionamiento de los frenos, el embrague, la selección de cambios, la transmisión automática, las señales y las luces, y supervisar durante la práctica de conducción."},{"consecutivo":2,"texto":"Instruir a particulares sobre normas, reglamento de tráfico y seguridad vial de acuerdo con lineamientos técnicos."},{"consecutivo":3,"texto":"Asesorar a particulares en técnicas de conducción básicas, avanzadas y de situaciones de emergencia para examen."},{"consecutivo":4,"texto":"Ilustrar y explicar el funcionamiento mecánico, el manejo de vehículos de motor y las técnicas usando recursos didácticos de enseñanza como diagramas en pizarra, audiovisuales, entre otros."},{"consecutivo":5,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"51650.001","nombre":"Ensayador de conducción / Ensayadora de conducción"},{"codigo":"51650.002","nombre":"Examinador de conducción / Examinadora de conducción"},{"codigo":"51650.003","nombre":"Instructor de academia de conducción / Instructora de academia de conducción"},{"codigo":"51650.004","nombre":"Instructor de centro integral de atención vial / Instructora de centro integral de atención vial"},{"codigo":"51650.005","nombre":"Instructor de conducción / Instructora de conducción"},{"codigo":"51650.006","nombre":"Instructor de conducción de motos / Instructora de conducción de motos"},{"codigo":"51650.007","nombre":"Instructor en movilidad y seguridad vial / Instructora en movilidad y seguridad vial"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"14","nombre":"Transmisión de conocimiento"}],"ocupaciones_afines":[{"codigo":"23200","nombre":"Profesores de formación profesional / Profesoras de formación profesional"},{"codigo":"31530","nombre":"Pilotos, ingenieros e instructores de vuelo"}],"area_principal":{"sigla":"EDFO","nombre":"Educación y formación"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"5165","ciuo08_obs":"Denominaciones completas","cno_codigo":"4214*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Otros trabajadores de servicios personales no clasificados en otras ocupaciones / Otras trabajadoras de servicios personales no clasificados en otras ocupaciones', '51690', 'Servicios Personales y a la Comunidad', 2, false, '{"codigo":"51690","nombre":"Otros trabajadores de servicios personales no clasificados en otras ocupaciones / Otras trabajadoras de servicios personales no clasificados en otras ocupaciones","descripcion":"Esta Ocupación abarca a Otros trabajadores de servicios personales no clasificados en otras ocupaciones en el Subgrupo Principal 51: Trabajadores de servicios personales. Por ejemplo, incluye aquellos que prestan servicios y compañía como pareja de baile, acompañantes sociales en restaurantes, clubes, bares y otros establecimientos de baile o diversión; las azafatas, los anfitriones de club nocturno, así como las personas que ofrecen servicios como trabajadores sexuales se clasifican aquí. Se pueden desempeñar en establecimientos de diversión, discotecas, clubes, whiskerías, sitio web, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"51","nombre":"TRABAJADORES DE LOS SERVICIOS PERSONALES"},"subgrupo":{"codigo":"516","nombre":"Otros trabajadores de servicios personales"},"grupo_primario":{"codigo":"5169","nombre":"Otros trabajadores de servicios personales no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Acompañar a clientes a restaurantes, bares y otros lugares públicos de acuerdo con el servicio contratado."},{"consecutivo":2,"texto":"Oficiar de pareja en reuniones y/o eventos sociales de acuerdo con servicio contratado."},{"consecutivo":3,"texto":"Recibir clientes en diversos establecimientos públicos de baile o diversión y velar por su entretenimiento."},{"consecutivo":4,"texto":"Prestar servicios como trabajadores sexuales."},{"consecutivo":5,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"51690.001","nombre":"Acompañante de baile"},{"codigo":"51690.002","nombre":"Acompañante de club nocturno"},{"codigo":"51690.003","nombre":"Acompañante en actos sociales"},{"codigo":"51690.004","nombre":"Acompañante social"},{"codigo":"51690.005","nombre":"Animador de club nocturno / Animadora de club nocturno"},{"codigo":"51690.006","nombre":"Azafato de club nocturno / Azafata de club nocturno"},{"codigo":"51690.007","nombre":"Gigoló"},{"codigo":"51690.008","nombre":"Pareja de baile"},{"codigo":"51690.009","nombre":"Prestador de servicios sexuales / Prestadora de servicios sexuales"},{"codigo":"51690.010","nombre":"Prostituto / Prostituta"},{"codigo":"51690.011","nombre":"Trabajador sexual a través de teléfono o internet / Trabajadora sexual a través de teléfono o internet"},{"codigo":"51690.012","nombre":"Trabajador sexual / Trabajadora sexual"},{"codigo":"51690.013","nombre":"Modelo webcam"}],"conocimientos":[{"id":"36","nombre":"Manejo de las TIC"},{"id":"4","nombre":"Mercadotecnia y publicidad"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"39","nombre":"Creatividad"},{"id":"2","nombre":"Escucha activa"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"}],"ocupaciones_afines":[{"codigo":"51620","nombre":"Acompañantes"}],"area_principal":{"sigla":"SEPC","nombre":"Servicios Personales y a la Comunidad"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"5169","ciuo08_obs":"Denominaciones completas","cno_codigo":"","cno_obs":""}]}'::jsonb),
  ('rol_cuoc', 'Vendedores en quioscos y puestos de mercado / Vendedoras en quioscos y puestos de mercado', '52110', 'Comercio, mercadeo y publicidad', 2, true, '{"codigo":"52110","nombre":"Vendedores en quioscos y puestos de mercado / Vendedoras en quioscos y puestos de mercado","descripcion":"Venden diversos productos como artesanías, diarios, revistas, tarjetas postales, cigarrillos, golosinas, helados, frutas, verduras y otros artículos alimenticios, principalmente perecederos, en quioscos y puestos fijos de mercado situados en emplazamientos callejeros o al aire libre, los cuales cuentan con el debido permiso de las autoridades locales competentes. Se pueden desempeñar en plazas de mercado, espacios públicos, ferias, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"52","nombre":"VENDEDORES"},"subgrupo":{"codigo":"521","nombre":"Vendedores callejeros y de puestos de mercado"},"grupo_primario":{"codigo":"5211","nombre":"Vendedores en quioscos y puestos de mercado"}},"funciones":[{"consecutivo":1,"texto":"Atender clientes y determinar el tipo, calidad y cantidad de mercancía solicitada para comprar."},{"consecutivo":2,"texto":"Conseguir de las autoridades locales competentes el permiso necesario para establecer un quiosco o puesto de venta al público en un lugar determinado en las calles, mercados u otros espacios abiertos."},{"consecutivo":3,"texto":"Exhibir, surtir y vender mercancía como: muebles, artesanías, diarios, revistas, dulces y otros productos para la venta al público en aceras, eventos públicos, quioscos y puestos de mercado de manera limpia y ordena."},{"consecutivo":4,"texto":"Determinar la mezcla de productos, inventario y niveles de precios de los bienes a ser vendidos."},{"consecutivo":5,"texto":"Mantener los registros de compras, ventas e inventarios para control del establecimiento."},{"consecutivo":6,"texto":"Empacar las compras de los clientes y artículos para despacho o entrega a domicilio."},{"consecutivo":7,"texto":"Comprar suministros de productos para la venta a los proveedores al por mayor o directamente a los productores."},{"consecutivo":8,"texto":"Montar y desmontar puestos y stands para venta de productos en lugares públicos."},{"consecutivo":9,"texto":"Mercadear, vender y aceptar el pago de mercancía o productos adquiridos por el cliente."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"52110.001","nombre":"Auxiliar de ventas en plaza"},{"codigo":"52110.002","nombre":"Auxiliar de ventas en puesto callejero"},{"codigo":"52110.003","nombre":"Auxiliar de ventas en puesto de mercado"},{"codigo":"52110.004","nombre":"Proveedor de mercado / Proveedora de mercado"},{"codigo":"52110.005","nombre":"Puestero de mercado / Puestera de mercado"},{"codigo":"52110.006","nombre":"Vendedor de periódicos en quiosco / Vendedora de periódicos en quiosco"},{"codigo":"52110.007","nombre":"Vendedor en puesto de mercado / Vendedora en puesto de mercado"},{"codigo":"52110.008","nombre":"Vendedor en puesto fijo callejero / Vendedora en puesto fijo callejero"},{"codigo":"52110.009","nombre":"Vendedor en quiosco / Vendedora en quiosco"},{"codigo":"52110.010","nombre":"Desgranador de arverja / Desgranadora de arverja"},{"codigo":"52110.011","nombre":"Desgranador de granos / Desgranadora de granos"}],"conocimientos":[{"id":"1","nombre":"Gerencia y administración"},{"id":"14","nombre":"Matemáticas"},{"id":"4","nombre":"Mercadotecnia y publicidad"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"15","nombre":"Orientación al servicio"},{"id":"12","nombre":"Persuasión"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"52120","nombre":"Vendedores ambulantes de alimentos preparados p