  ('rol_cuoc', 'Supervisores de tiendas y almacenes / Supervisoras de tiendas y almacenes', '52220', 'Comercio, mercadeo y publicidad', 3, false, '{"codigo":"52220","nombre":"Supervisores de tiendas y almacenes / Supervisoras de tiendas y almacenes","descripcion":"Supervisan y coordinan las actividades de comercialización de bienes y servicios realizados por el personal de ventas. Se pueden desempeñar en tiendas al por menor y al por mayor, supermercados, grandes superficies, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"52","nombre":"VENDEDORES"},"subgrupo":{"codigo":"522","nombre":"Comerciantes y vendedores de tiendas, almacenes y afines"},"grupo_primario":{"codigo":"5222","nombre":"Supervisores de tiendas y almacenes"}},"funciones":[{"consecutivo":1,"texto":"Supervisar, coordinar y programar las actividades de los vendedores y otro personal de apoyo en ventas de acuerdo con proceso administrativo y estrategia de servicio."},{"consecutivo":2,"texto":"Seleccionar y entrenar personal de venta en establecimientos comerciales según proceso administrativo y estrategia de servicio."},{"consecutivo":3,"texto":"Participar y asesorar a los administradores de establecimientos comerciales en entrevistas, contratación, formación, evaluación y promoción del personal de ventas."},{"consecutivo":4,"texto":"Vender mercancía a los clientes y atender peticiones, quejas, reclamos y sugerencias en establecimientos comerciales de acuerdo con proceso administrativo y estrategia de servicio."},{"consecutivo":5,"texto":"Realizar análisis del estado de mercancía en el establecimiento comercial de acuerdo con proceso administrativo y estrategia de servicio."},{"consecutivo":6,"texto":"Controlar inventario en el establecimiento comercial para determinar, mantener y ordenar mercancía de acuerdo con proceso administrativo y estrategia de servicio."},{"consecutivo":7,"texto":"Preparar informes del volumen de ventas, mercancías y asuntos relacionados con el personal del establecimiento comercial de acuerdo con procedimientos administrativo."},{"consecutivo":8,"texto":"Garantizar que los bienes y servicios del establecimiento comercial se exhiban de acuerdo con el plan promocional y los protocolos de campaña."},{"consecutivo":9,"texto":"Garantizar que los procedimientos de seguridad en el establecimiento se cumplan."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"52220.003","nombre":"Coordinador de mercadeo / Coordinadora de mercadeo"},{"codigo":"52220.004","nombre":"Coordinador de personal de ventas puerta a puerta / Coordinadora de personal de ventas puerta a puerta"},{"codigo":"52220.005","nombre":"Inspector de caja comercio al por menor / Inspectora de caja comercio al por menor"},{"codigo":"52220.006","nombre":"Jefe de abarrotes / Jefa de abarrotes"},{"codigo":"52220.007","nombre":"Jefe de personal de caja en comercio / Jefa de personal de caja en comercio"},{"codigo":"52220.008","nombre":"Supervisor de almacén / Supervisora de almacén"},{"codigo":"52220.009","nombre":"Supervisor de almacén de abarrotes / Supervisora de almacén de abarrotes"},{"codigo":"52220.010","nombre":"Supervisor de almacén por departamentos / Supervisora de almacén por departamentos"},{"codigo":"52220.011","nombre":"Supervisor de auxiliares de ventas / Supervisora de auxiliares de ventas"},{"codigo":"52220.012","nombre":"Supervisor de personal de caja en comercio / Supervisora de personal de caja en comercio"},{"codigo":"52220.013","nombre":"Supervisor de pedido / Supervisora de pedido"},{"codigo":"52220.014","nombre":"Supervisor de personal promotor de ventas / Supervisora de personal promotor de ventas"},{"codigo":"52220.015","nombre":"Supervisor de puntos de venta / Supervisora de puntos de venta"},{"codigo":"52220.016","nombre":"Supervisor de servicio al cliente comercio al por menor / Superviso