  ('rol_cuoc', 'Cajeros de comercio, taquilleros y expendedores de boletas / Cajeras de comercio, taquilleros y expendedores de boletas', '52300', 'Comercio, mercadeo y publicidad', 2, false, '{"codigo":"52300","nombre":"Cajeros de comercio, taquilleros y expendedores de boletas / Cajeras de comercio, taquilleros y expendedores de boletas","descripcion":"Registran y reciben pagos de clientes o usuarios, verifican y emiten billetes y tiquetes. Se pueden desempeñar en restaurantes, almacenes, teatros, oficinas de negocios, empresas de servicios y transporte público, establecimientos de comercio mayoristas, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"52","nombre":"VENDEDORES"},"subgrupo":{"codigo":"523","nombre":"Cajeros de comercio, taquilleros y expendedores de boletas"},"grupo_primario":{"codigo":"5230","nombre":"Cajeros de comercio, taquilleros y expendedores de boletas"}},"funciones":[{"consecutivo":1,"texto":"Realizar las operaciones de caja en establecimientos de comercio de acuerdo con requerimientos técnicos y protocolos de servicios."},{"consecutivo":2,"texto":"Establecer o identificar el precio de mercancías o servicios mediante el registro en calculadora, caja registradora o sensores ópticos."},{"consecutivo":3,"texto":"Expedir y emitir boletos, pases, billetes o recibos para eventos, peajes, loterías y juegos de azar, entre otros de acuerdo con requerimientos técnicos y protocolos de servicios."},{"consecutivo":4,"texto":"Verificar y comprobar validez de boletos, pases, billetes o recibos emitidos en cajas de comercio, garitas, taquillas, entre otros de acuerdo con requerimientos técnicos y protocolos de servicios."},{"consecutivo":5,"texto":"Realizar depósito de dinero de las ventas del establecimiento en el banco de acuerdo con protocolos."},{"consecutivo":6,"texto":"Realizar proceso de cierre de caja de acuerdo con métodos contables y lineamientos del establecimiento."},{"consecutivo":7,"texto":"Empacar y colocar en bolsas la mercancía vendida de acuerdo protocolos del establecimiento."},{"consecutivo":8,"texto":"Proporcionar información a los clientes en la venta de productos, mercancías, eventos, juegos de azar, loterías, peajes, entre otros, de acuerdo con protocolos de servicio."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"52300.001","nombre":"Auxiliar de cabina de peajes"},{"codigo":"52300.002","nombre":"Auxiliar de consola de estación de servicio"},{"codigo":"52300.003","nombre":"Cajero de apuestas / Cajera de apuestas"},{"codigo":"52300.004","nombre":"Cajero de cafetería / Cajera de cafetería"},{"codigo":"52300.005","nombre":"Cajero de almacén / Cajera de almacén"},{"codigo":"52300.006","nombre":"Cajero de autoservicio / Cajera de autoservicio"},{"codigo":"52300.007","nombre":"Cajero de comercio / Cajera de comercio"},{"codigo":"52300.008","nombre":"Cajero de estación de servicio / Cajera de estación de servicio"},{"codigo":"52300.009","nombre":"Cajero de gasolinera / Cajera de gasolinera"},{"codigo":"52300.010","nombre":"Cajero de mostrador / Cajera de mostrador"},{"codigo":"52300.011","nombre":"Cajero de oficina / Cajera de oficina"},{"codigo":"52300.012","nombre":"Cajero de oficina de reservas / Cajera de oficina de reservas"},{"codigo":"52300.013","nombre":"Cajero de recepción de efectivo / Cajera de recepción de efectivo"},{"codigo":"52300.014","nombre":"Cajero de restaurante / Cajera de restaurante"},{"codigo":"52300.015","nombre":"Cajero de supermercado / Cajera de supermercado"},{"codigo":"52300.016","nombre":"Cajero de tienda / Cajera de tienda"},{"codigo":"52300.017","nombre":"Cajero de tienda de autoservicio / Cajera de tienda de autoservicio"},{"codigo":"52300.018","nombre":"Cajero de hotel / Cajera de hotel"},{"codigo":"52300.019","nombre":"Cajero vendedor / Cajera vendedora"},{"codigo":"52300.020","nombre":"Co