  ('rol_cuoc', 'Modelos de moda, arte y publicidad', '52410', 'Comercio, mercadeo y publicidad', 2, false, '{"codigo":"52410","nombre":"Modelos de moda, arte y publicidad","descripcion":"Desfilan prendas de vestir, objetos, accesorios y otros artículos destinados a la venta, modelan para creaciones publicitarias, sesiones de fotografía, cine, vídeo, posan para fotografía artística y otras creaciones de pintores y escultores. Se pueden desempeñar en agencias de modelaje, firmas publicitarias, empresas de protocolo, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"52","nombre":"VENDEDORES"},"subgrupo":{"codigo":"524","nombre":"Otros vendedores"},"grupo_primario":{"codigo":"5241","nombre":"Modelos de moda, arte y publicidad"}},"funciones":[{"consecutivo":1,"texto":"Desfilar prendas, accesorios y otras mercancías de diseñadores en pasarelas de top shows, ferias de moda, centros de eventos, centros comerciales y otros sitios ante posibles compradores."},{"consecutivo":2,"texto":"Servir de modelo para escultores, fotógrafos, pintores, artistas, vídeos, cine, y otras producciones de acuerdo con contrato."},{"consecutivo":3,"texto":"Presentar pruebas y casting para comerciales, pasarelas y otras producciones de acuerdo con requerimientos."},{"consecutivo":4,"texto":"Prestar su imagen para representar marcas exclusivas, de acuerdo con contrato."},{"consecutivo":5,"texto":"Participar en desfiles de carácter social y beneficencia."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"52410.001","nombre":"Maniquí modelo"},{"codigo":"52410.002","nombre":"Modelo"},{"codigo":"52410.003","nombre":"Modelo artístico / Modelo artística"},{"codigo":"52410.004","nombre":"Modelo de eventos"},{"codigo":"52410.005","nombre":"Modelo de fotografía"},{"codigo":"52410.006","nombre":"Modelo de maniquí"},{"codigo":"52410.007"