  ('rol_cuoc', 'Otros vendedores no clasificados en otras ocupaciones / Otras vendedoras no clasificadas en otras ocupaciones', '52490', 'Comercio, mercadeo y publicidad', 2, true, '{"codigo":"52490","nombre":"Otros vendedores no clasificados en otras ocupaciones / Otras vendedoras no clasificadas en otras ocupaciones","descripcion":"Esta Ocupación abarca a Otros vendedores no clasificados en otras ocupaciones en el Subgrupo Principal 52: Vendedores. Por ejemplo, incluye aquellos que prestan servicio de venta o alquiler de bienes como vehículos, entre otros, pueden registrar y aceptar el pago de productos adquiridos por clientes. Se pueden desempeñar en establecimientos de renta de vehículos, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"52","nombre":"VENDEDORES"},"subgrupo":{"codigo":"524","nombre":"Otros vendedores"},"grupo_primario":{"codigo":"5249","nombre":"Otros vendedores no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Efectuar operaciones de alistamientos de mercancía utilizando aparatos manuales y eléctricos, de acuerdo con protocolos y estándares del establecimiento."},{"consecutivo":2,"texto":"Recibir y registrar los pagos en la caja registradora o sistema de venta de bienes y servicios adquiridos por clientes, según políticas del establecimiento."},{"consecutivo":3,"texto":"Contactar personalmente, telefónicamente o por medios electrónicos personas y negocios para impulsar y vender bienes y servicios, según estándares."},{"consecutivo":4,"texto":"Dar a conocer las características, beneficios y precios de bienes y servicios para promover el interés y la compra del cliente."},{"consecutivo":5,"texto":"Elaborar y presentar informes periódicos de las actividades de mercadeo, administración, operaciones de ventas, contacto de clientes y sus resultados."},{"consecutivo":6,"texto":"Realizar seguimiento de la gestión de ventas y contacto de clientes, y actualizar las bases de datos, según estándares y protocolos de servicio."},{"consecutivo":7,"texto":"Compilar listas de clientes nuevos y antiguos para distribuir cartas, folletos informativos, publicidad o entrega de muestras para obtener nuevas ventas."},{"consecutivo":8,"texto":"Registrar pedidos, transacciones y remitir al proveedor para su despacho, de acuerdo con protocolos de ventas."},{"consecutivo":9,"texto":"Elaborar inventarios, hacer pedidos e informes de ventas diarias en el punto de venta."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"52490.001","nombre":"Asesor de ventas de alquiler de vehículos / Asesora de ventas de alquiler de vehículos"},{"codigo":"52490.002","nombre":"Asesor de ventas de rentas / Asesora de ventas de rentas"},{"codigo":"52490.003","nombre":"Auxiliar de ventas de alquiler"},{"codigo":"52490.004","nombre":"Auxiliar de ventas de alquiler de vehículos"},{"codigo":"52490.005","nombre":"Vendedor de alquiler / Vendedora de alquiler"},{"codigo":"52490.006","nombre":"Vendedor de alquiler de vehículos / Vendedora de alquiler de vehículos"},{"codigo":"52490.007","nombre":"Vendedor de alquiler de videos / Vendedora de alquiler de videos"},{"codigo":"52490.008","nombre":"Auxiliar de alquiler de vehículos eléctricos recreativos"}],"conocimientos":[{"id":"14","nombre":"Matemáticas"},{"id":"4","nombre":"Mercadotecnia y publicidad"},{"id":"5","nombre":"Servicio al cliente"},{"id":"95","nombre":"Ventas al por mayor y al por menor"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"15","nombre":"Orientación al servicio"},{"id":"12","nombre":"Persuasión"},{"id":"10","nombre":"Relaciones interpersonales"}],"ocupaciones_afines":[{"codigo":"52110","nombre":"Vendedores en quioscos y puestos de mercado / Vendedoras en quioscos y puestos de mercado"},{"codigo":"52210","nombre":"Comerciantes de t