  ('rol_cuoc', 'Cuidadores de niños / Cuidadoras de niños', '53110', 'Servicios Personales y a la Comunidad', 2, false, '{"codigo":"53110","nombre":"Cuidadores de niños / Cuidadoras de niños","descripcion":"Prestan servicio de cuidado y supervisión a niños durante sus actividades cotidianas, extracurriculares y de vacaciones en hogares residenciales, guarderías, espacios comunitarios, transporte estudiantil, entre otros. Instruyen a los niños en actividades que estimulen y desarrollen su crecimiento y hábitos sociales, alimenticios, de vestuario e higiene. Se pueden desempeñar en jardines, guarderías, hogares comunitarios o particulares, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"53","nombre":"TRABAJADORES DE LOS CUIDADOS PERSONALES"},"subgrupo":{"codigo":"531","nombre":"Cuidadores de niños y auxiliares de maestros"},"grupo_primario":{"codigo":"5311","nombre":"Cuidadores de niños"}},"funciones":[{"consecutivo":1,"texto":"Guiar y ayudar a los niños a desarrollar hábitos sociales, alimenticios, de vestuario e higiene de acuerdo con protocolos y políticas de primera infancia."},{"consecutivo":2,"texto":"Cuidar y observar a los niños durante actividades de juego, recreo, almuerzo y otras actividades en residencias, jardines o guarderías."},{"consecutivo":3,"texto":"Acompañar, vigilar y cuidar a los niños durante recorrido a la escuela o el jardín, paseos, excursión, recorrido en la ruta escolar y actividades similares."},{"consecutivo":4,"texto":"Acompañar y organizar juegos y actividades de entretenimiento a los niños, según su edad, espacio y condiciones."},{"consecutivo":5,"texto":"Preparar materiales y equipos para la educación y las actividades recreativas de los niños."},{"consecutivo":6,"texto":"Controlar, disciplinar y recomendar medidas para el control del comportamiento de los niños en el desarrollo de hábitos en diversos espacios."},{"consecutivo":7,"texto":"Llevar registro de los niños cuidados incluyendo observaciones diarias e información sobre actividades, comidas y medicamentos administrados."},{"consecutivo":8,"texto":"Preparar y servir loncheras a los niños de acuerdo con lineamientos e higiene."},{"consecutivo":9,"texto":"Apoyar a los padres en actividades como supervisión y administración del hogar, asistencia a reuniones de profesores para escuchar el progreso y las dificultades de los niños, entre otras."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"53110.001","nombre":"Auxiliar de cuidado de niños"},{"codigo":"53110.002","nombre":"Auxiliar de guardería infantil"},{"codigo":"53110.003","nombre":"Ayo / Aya"},{"codigo":"53110.004","nombre":"Ayo de casa / Aya de casa"},{"codigo":"53110.005","nombre":"Ayo de guardería infantil / Aya de guardería infantil"},{"codigo":"53110.006","nombre":"Cuidador de niños / Cuidadora de niños"},{"codigo":"53110.007","nombre":"Cuidador de niños durante el día / Cuidadora de niños durante el día"},{"codigo":"53110.008","nombre":"Cuidador de niños en espacios comunitarios / Cuidadora de niños en espacios comunitarios"},{"codigo":"53110.009","nombre":"Cuidador de niños fuera del horario escolar / Cuidadora de niños fuera del horario escolar"},{"codigo":"53110.010","nombre":"Institutriz"},{"codigo":"53110.011","nombre":"Institutriz de niños"},{"codigo":"53110.012","nombre":"Jardinero de cuidado de niños / Jardinera de cuidado de niños"},{"codigo":"53110.014","nombre":"Monitor de transporte escolar / Monitora transporte escolar"},{"codigo":"53110.015","nombre":"Nana"},{"codigo":"53110.016","nombre":"Niñero / Niñera"},{"codigo":"53110.017","nombre":"Niñero por horas / Niñera por horas"},{"codigo":"53110.018","nombre":"Padre comunitario"},{"codigo":"53110.019","nombre":"Trabajador en cuidado de niños / Trabajadora en cuidado de niños"},{"codigo":"53110.020","nombre":"Trabajador en cuidado de niños fuera