  ('rol_cuoc', 'Auxiliares de maestros y primera infancia', '53120', 'Educación y formación', 2, false, '{"codigo":"53120","nombre":"Auxiliares de maestros y primera infancia","descripcion":"Prestan servicio de apoyo en actividades educativas bajo la supervisión de un educador infantil, orientadas a promover el desarrollo integral de las niñas y los niños. Se pueden desempeñar en modalidades de educación inicial, centros de desarrollo infantil, jardines infantiles, preescolares, guarderías, centros de estimulación, sala cunas, sala materna, hogares comunitarios, museos, bibliotecas, ludotecas, parques, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"53","nombre":"TRABAJADORES DE LOS CUIDADOS PERSONALES"},"subgrupo":{"codigo":"531","nombre":"Cuidadores de niños y auxiliares de maestros"},"grupo_primario":{"codigo":"5312","nombre":"Auxiliares de maestros y primera infancia"}},"funciones":[{"consecutivo":1,"texto":"Supervisar y participar en actividades que mejoran el desarrollo físico, social, emocional e intelectual de los niños en las escuelas y guarderías."},{"consecutivo":2,"texto":"Preparar áreas interiores y exteriores para actividades recreativas y de aprendizaje de los niños en las escuelas y guarderías."},{"consecutivo":3,"texto":"Asistir la educación en la primera infancia de acuerdo con las orientaciones del maestro, profesor o cuidador y el plan de trabajo definido."},{"consecutivo":4,"texto":"Apoyar niños en situación de discapacidad, problemas de conducta, entre otros en el desarrollo de destrezas de adaptación a la vida cotidiana y los hábitos sociales, alimenticios y de higiene."},{"consecutivo":5,"texto":"Participar en las actividades educativas con las familias y la comunidad para promover el desarrollo de los niños y las niñas de acuerdo con las orientaciones y el plan definido."},{"consecutivo":6,"texto":"Asistir actividades de la vida cotidiana de niños y apoyar el desarrollo de hábitos sociales, alimenticios, de vestuario e higiene de acuerdo con protocolos y políticas de primera infancia."},{"consecutivo":7,"texto":"Apoyar acciones de salud en niños de acuerdo con protocolos y políticas de primera infancia."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"53120.001","nombre":"Asistente de enseñanza especial / Asistenta de enseñanza especial"},{"codigo":"53120.002","nombre":"Asistente de preescolar / Asistenta de preescolar"},{"codigo":"53120.003","nombre":"Asistente de primera infancia / Asistenta de primera infancia"},{"codigo":"53120.004","nombre":"Auxiliar de educación para la primera infancia"},{"codigo":"53120.005","nombre":"Auxiliar de enseñanza correctiva"},{"codigo":"53120.006","nombre":"Auxiliar de jardín infantil"},{"codigo":"53120.007","nombre":"Auxiliar en educación inicial"},{"codigo":"53120.008","nombre":"Auxiliar de maestros"},{"codigo":"53120.009","nombre":"Auxiliar de preescolar"},{"codigo":"53120.010","nombre":"Auxiliar del educador infantil"},{"codigo":"53120.011","nombre":"Auxiliar en primera infancia"},{"codigo":"53120.012","nombre":"Colaborador de preescolar / Colaboradora de preescolar"},{"codigo":"53120.013","nombre":"Colaborador de docentes / Colaboradora de docentes"},{"codigo":"53120.014","nombre":"Supervisor en exámenes / Supervisora en exámenes"},{"codigo":"53120.015","nombre":"Auxiliar pedagógico de primera infancia / Auxiliar pedagógica de primera infancia"}],"conocimientos":[{"id":"42","nombre":"Atención, protección y servicios a la infancia, adolescencia y juventud"},{"id":"22","nombre":"Educación y capacitación"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"36","nombre":"Manejo de las TIC"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"39","nombre":"Creatividad"},{"id":"8","nombre":"Estrategias para el aprendizaje"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"15","nombre":"Orientación al servicio"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"23410","nombre":"Profesores de educación básica primaria / Profesoras de educación básica primaria"},{"codigo":"23420","nombre":"Profesores de primera infancia y preescolar / Profesoras de primera infancia y preescolar"},{"codigo":"23521","nombre":"Profesores e instructores de educación especial e inclusiva / Profesoras e instructoras de educación especial e inclusiva"},{"codigo":"53110","nombre":"Cuidadores de niños / Cuidadoras de niños"}],"area_principal":{"sigla":"EDFO","nombre":"Educación y formación"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"4311*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"4213*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"5312*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"4311*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Trabajadores de los cuidados personales en instituciones / Trabajadoras de los cuidados personales en instituciones', '53210', 'Salud y bienestar', 2, false, '{"codigo":"53210","nombre":"Trabajadores de los cuidados personales en instituciones / Trabajadoras de los cuidados personales en instituciones","descripcion":"Prestan servicios de atención personal en lo relacionado con el autocuidado de la salud física, y desarrollo de habilidades sociales y ocupacionales, así como las necesidades de comunicación y ayuda directa con las actividades de la vida diaria a los pacientes. Generalmente trabajan en la implementación de planes de atención y prácticas establecidas bajo la supervisión directa de médicos, u otros profesionales de nivel medio de la salud. Colaboran en la atención a pacientes enfermos, heridos, con discapacidades, entre otros. Se pueden desempeñar en clínicas, hospitales, clínicas, centros de salud, centros geriátricos, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"53","nombre":"TRABAJADORES DE LOS CUIDADOS PERSONALES"},"subgrupo":{"codigo":"532","nombre":"Trabajadores de los cuidados personales en servicios de salud"},"grupo_primario":{"codigo":"5321","nombre":"Trabajadores de los cuidados personales en instituciones"}},"funciones":[{"consecutivo":1,"texto":"Proporcionar atención, apoyo y tratamiento a pacientes y residentes de centros de atención médica, o de rehabilitación según planes de tratamiento establecidos por los profesionales."},{"consecutivo":2,"texto":"Apoyar al personal médico y de enfermería en procedimientos tales como terapia respiratoria, aplicación de compresas, remoción de suturas, entre otros, según protocolo y normativa de salud."},{"consecutivo":3,"texto":"Tomar presión sanguínea, temperatura y pulso, tomar muestras, distribuir medicamentos a los pacientes y realizar otros procedimientos prescritos por el personal de salud."},{"consecutivo":4,"texto":"Trasladar a donde se requiera equipo médico- quirúrgico y de asistencia como: balas de oxígeno, electrocardiógrafos y demás, según protocolos."},{"consecutivo":5,"texto":"Atender las necesidades de cuidado personal y terapéutico de los pacientes sobre aspectos como: higiene personal, alimentación, vestuario, movilidad, ejercicios físicos, comunicación, ingestión de medicamentos por vía oral, cambio de vendajes y remoción de suturas."},{"consecutivo":6,"texto":"Mantener en buenas condiciones la higiene ambiental de los pacientes en habitaciones y salas de operaciones, velando por la limpieza, esterilización, cambio de la ropa de cama, mantener el inventario y los suministros de las habitaciones, atender los llamados de los pacientes, según protocolo y normativa de salud."},{"consecutivo":7,"texto":"Proporcionar masajes y otros medios no farmacológicos para aliviar el dolor, como en el embarazo y el parto, así como servicios que puedan contribuir a su comodidad y bienestar físico, recreativo y ocupacional."},{"consecutivo":8,"texto":"Acompañar a la persona a consultas médicas, terapias, actividades recreativas y de otra índole, de acuerdo con el servicio contratado."},{"consecutivo":9,"texto":"Programar citas y observar el estado de los pacientes, su progreso y sus cambios de comportamiento e informar a los profesionales de la salud como médicos, enfermeros jefes y otros miembros del equipo de salud."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"53210.001","nombre":"Auxiliar de cuidados a pacientes"},{"codigo":"53210.002","nombre":"Auxiliar de hogar geriátrico"},{"codigo":"53210.003","nombre":"Auxiliar de nacimientos en clínica u hospital"},{"codigo":"53210.004","nombre":"Auxiliar de obstetricia en clínica u hospital"},{"codigo":"53210.005","nombre":"Auxiliar de psiquiatría"},{"codigo":"53210.008","nombre":"Camillero / Camillera"},{"codigo":"53210.009","nombre":"Inyectólogo / Inyectóloga"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"41","nombre":"Primeros auxilios"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"32550","nombre":"Técnicos y asistentes terapeutas / Técnicas y asistentes terapeutas"},{"codigo":"32580","nombre":"Técnicos en atención prehospitalaria / Técnicas en atención prehospitalaria"},{"codigo":"53220","nombre":"Trabajadores de los cuidados personales a domicilio / Trabajadoras de los cuidados personales a domicilio"}],"area_principal":{"sigla":"SABI","nombre":"Salud y bienestar"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"5321","ciuo08_obs":"Denominaciones completas","cno_codigo":"3316*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"6371*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Trabajadores de los cuidados personales a domicilio / Trabajadoras de los cuidados personales a domicilio', '53220', 'Servicios Personales y a la Comunidad', 2, false, '{"codigo":"53220","nombre":"Trabajadores de los cuidados personales a domicilio / Trabajadoras de los cuidados personales a domicilio","descripcion":"Prestan servicios de cuidado personal enfocados en actividades de la vida diaria (básicas, instrumentales y avanzadas), fomentando el autocuidado físico y mental, el apoyo socioemocional y espiritual, el desarrollo de habilidades sociales y ocupacionales y la asistencia en la comunicación. Atienden las necesidades de las personas con discapacidad, personas mayores, personas con alguna enfermedad u otras condiciones físicas o mentales con dependencia de cuidado y promueven la autonomía bajo un enfoque biopsicosocial y de derechos. Se desempeñan en entornos comunitarios y domicilios.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"53","nombre":"TRABAJADORES DE LOS CUIDADOS PERSONALES"},"subgrupo":{"codigo":"532","nombre":"Trabajadores de los cuidados personales en servicios de salud"},"grupo_primario":{"codigo":"5322","nombre":"Trabajadores de los cuidados personales a domicilio"}},"funciones":[{"consecutivo":1,"texto":"Brindar cuidados personales y asistencia en actividades básicas, instrumentales y avanzadas de la vida diaria, respetando la voluntad y la autonomía de la persona sujeta de cuidado o apoyo."},{"consecutivo":2,"texto":"Mantener registros o notas para realizar el seguimiento a los cambios en el estado físico o biopsicosocial para activar rutas de atención de salud y servicios sociales."},{"consecutivo":3,"texto":"Apoyar la movilidad y el desplazamiento, según las necesidades y las preferencias de la persona, utilizando medios de transporte o de apoyo."},{"consecutivo":4,"texto":"Adquirir, preparar y administrar alimentos teniendo en cuenta requerimientos nutricionales y preferencias, según orientación del profesional de la salud."},{"consecutivo":5,"texto":"Realizar actividades de higiene y organización en los espacios de permanencia de la persona sujeta de cuidado o apoyo, según sus necesidades y preferencias."},{"consecutivo":6,"texto":"Programar y acompañar a citas médicas, terapias, hospitalizaciones, actividades educativas, recreativas u otras diligencias, según el ciclo de vida de la persona."},{"consecutivo":7,"texto":"Proporcionar apoyo en necesidades socioemocionales y espirituales, fortalecer la resiliencia y fomentar habilidades cognitivas, creativas y ocupacionales."},{"consecutivo":8,"texto":"Gestionar trámites y coordinar el acceso a servicios de salud, educativos o sociales, activando rutas de atención y facilitando la comunicación con las instituciones."},{"consecutivo":9,"texto":"Asistir en la comunicación y el uso de tecnologías de apoyo para facilitar la interacción y el acceso a información relevante."},{"consecutivo":10,"texto":"Fortalecer conocimientos en actividades de la vida diaria, integrando a la familia en la redistribución del cuidado y fomentando la autonomía de la persona."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"53220.001","nombre":"Acompañante de ancianos"},{"codigo":"53220.002","nombre":"Auxiliar de atención domiciliaria"},{"codigo":"53220.003","nombre":"Auxiliar de atención residencial para edad avanzada o con discapacidad"},{"codigo":"53220.004","nombre":"Auxiliar de centro diurno para edad avanzada o con discapacidad"},{"codigo":"53220.005","nombre":"Auxiliar de cuidado de reposo"},{"codigo":"53220.006","nombre":"Auxiliar de cuidados en el hogar"},{"codigo":"53220.007","nombre":"Auxiliar de cuidados en el hogar para edad avanzada o personas con discapacidad"},{"codigo":"53220.009","nombre":"Cuidador de parto en casa / Cuidadora de parto en casa"},{"codigo":"53220.010","nombre":"Ayudante de cuidados personales"},{"codigo":"53220.012","nombre":"Ayudante de obstetricia de partos en casa"},{"codigo":"53220.014","nombre":"Cuidador de personas con discapacidad / Cuidadora de personas con discapacidad"},{"codigo":"53220.015","nombre":"Cuidador de personas mayores / Cuidadora de personas mayores"},{"codigo":"53220.016","nombre":"Asistente personal de personas con discapacidad / Asistenta personal de personas con discapacidad"},{"codigo":"53220.017","nombre":"Auxiliar de cuidados domiciliarios"}],"conocimientos":[{"id":"42","nombre":"Atención, protección y servicios a la infancia, adolescencia y juventud"},{"id":"55","nombre":"Atención a adultos, adultos mayores con o sin discapacidad"},{"id":"37","nombre":"Manipulación de alimentos"},{"id":"41","nombre":"Primeros auxilios"},{"id":"50","nombre":"Servicio a la persona y humanización"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"38","nombre":"Seguir instrucciones"}],"ocupaciones_afines":[{"codigo":"53210","nombre":"Trabajadores de los cuidados personales en instituciones / Trabajadoras de los cuidados personales en instituciones"}],"area_principal":{"sigla":"SEPC","nombre":"Servicios Personales y a la Comunidad"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"5322","ciuo08_obs":"Denominaciones completas","cno_codigo":"","cno_obs":""}]}'::jsonb),
  ('rol_cuoc', 'Auxiliares en enfermería', '53291', 'Salud y bienestar', 2, false, '{"codigo":"53291","nombre":"Auxiliares en enfermería","descripcion":"Realizan apoyo a las actividades de cuidado básico de enfermería orientadas al bienestar y confort a las personas, familias y comunidades en los diferentes entornos y curso de vida en su proceso de salud-enfermedad, vida-muerte; apoya acciones de promoción de la salud, prevención de la enfermedad, tratamiento, rehabilitación y paliación bajo la delegación, la supervisión y el control del profesional de enfermería en el marco de las políticas y la normatividad vigente, teniendo en cuenta las características socio-demográficas, culturales, ancestral y territorial. Se pueden desempeñar en hospitales, clínicas, consultorios, otras instituciones del cuidado de salud, en el ámbito comunitario, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"53","nombre":"TRABAJADORES DE LOS CUIDADOS PERSONALES"},"subgrupo":{"codigo":"532","nombre":"Trabajadores de los cuidados personales en servicios de salud"},"grupo_primario":{"codigo":"5329","nombre":"Trabajadores de los cuidados personales en servicios de salud no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Recolectar, comunicar y registrar información sobre la condición física y emocional del paciente y su evolución, según protocolos de salud y reportar al profesional de enfermería."},{"consecutivo":2,"texto":"Apoyar en la preparación del individuo para la toma y remisión de muestras de exámenes de diagnóstico terapéutico, según delegación, protocolos y tecnologías en salud."},{"consecutivo":3,"texto":"Participar y asistir en la promoción, el mantenimiento y la recuperación de la salud de los sujetos de cuidado, según curso de vida, contexto sociocultural y protocolos."},{"consecutivo":4,"texto":"Apoyar el desarrollo de acciones de promoción de salud y prevención de la enfermedad fomentando los estilos de vida saludables e identificación de factores de riesgo, de acuerdo con el plan instaurado bajo la supervisión o la delegación del profesional de enfermería"},{"consecutivo":5,"texto":"Apoyar acciones de tratamiento médico-quirúrgico, rehabilitación y paliación bajo las indicaciones del profesional de enfermería."},{"consecutivo":6,"texto":"Asistir en las actividades de cuidado básico de enfermería que aporten al bienestar y el confort de la persona, según protocolos, principios de humanización e indicaciones del profesional de enfermería."},{"consecutivo":7,"texto":"Aplica los lineamientos y las normas técnicas y legales de seguridad y salud en el trabajo."},{"consecutivo":8,"texto":"Apoyar en la admisión de las personas a los servicios de salud, según la normatividad vigente."},{"consecutivo":9,"texto":"Asistir a la persona sujeto de cuidado, según el curso de vida, contexto sociocultural y guías de manejo de la salud."},{"consecutivo":10,"texto":"Aplicar protocolos de bioseguridad, según normatividad en salud vigente aplicable a las actividades realizadas y al servicio en que se desempeña."},{"consecutivo":11,"texto":"Orientar a las personas, las familias y la comunidad frente a los mecanismos de acceso a la atención en salud, según normatividad, necesidades, expectativas y contexto sociocultural."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"53291.001","nombre":"Auxiliar en enfermería"},{"codigo":"53291.002","nombre":"Técnico auxiliar en enfermería / Técnica auxiliar en enfermería"}],"conocimientos":[{"id":"36","nombre":"Manejo de las TIC"},{"id":"50","nombre":"Servicio a la persona y humanización"},{"id":"41","nombre":"Primeros auxilios"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"15","nombre":"Orientación al servicio"},{"id":"34","nombre":"Trabajo bajo presión"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"42291","nombre":"Auxiliares administrativos en salud / Auxiliares administrativas en salud"},{"codigo":"53293","nombre":"Auxiliares en salud pública"},{"codigo":"53295","nombre":"Auxiliares en servicios farmacéuticos"},{"codigo":"53292","nombre":"Auxiliares en salud oral"}],"area_principal":{"sigla":"SABI","nombre":"Salud y bienestar"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"5329*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"3311","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Auxiliares en salud oral', '53292', 'Salud y bienestar', 2, false, '{"codigo":"53292","nombre":"Auxiliares en salud oral","descripcion":"Asisten a los odontólogos durante los procedimientos clínicos que estos realizan, desarrollando funciones operativas y asistenciales como: brindar información a los pacientes, aplicar protocolos o lineamientos de desinfección, bioseguridad y esterilización; organizan las instalaciones, los equipos biomédicos, los dispositivos médicos y los insumos acordes con los procedimientos habilitados en el servicio odontológico. También realizan funciones administrativas como: apoyar el manejo de historias clínicas y realizar acciones de educación e información para la promoción de la salud bucal y la prevención de las enfermedades bucales en personas, familias y comunidades, que incluyen la realización de procedimientos de higiene bucodental, bajo la supervisión del odontólogo. Se pueden desempeñar en consultorios odontológicos públicos o privados, y en distintos entornos colectivos en el marco de programas y proyectos de promoción de la salud y la prevención de la enfermedad de acuerdo con la normatividad vigente, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"53","nombre":"TRABAJADORES DE LOS CUIDADOS PERSONALES"},"subgrupo":{"codigo":"532","nombre":"Trabajadores de los cuidados personales en servicios de salud"},"grupo_primario":{"codigo":"5329","nombre":"Trabajadores de los cuidados personales en servicios de salud no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Preparar el ambiente del consultorio odontológico, según el protocolo y la normativa de salud."},{"consecutivo":2,"texto":"Preparar pacientes para examen odontológico y asistir a los odontólogos durante el mismo."},{"consecutivo":3,"texto":"Realizar el alistamiento de los dispositivos médicos, los equipos biomédicos y las áreas de trabajo, según los procesos de bioseguridad, los protocolos y la normativa de salud."},{"consecutivo":4,"texto":"Alistar y preparar los materiales de uso odontológico de acuerdo con el requerimiento clínico, quirúrgico o procedimiento técnico definido para el tratamiento."},{"consecutivo":5,"texto":"Apoyar el control del abastecimiento, el uso de insumos odontológicos y brindar alertas de caducación, según el protocolo y la normativa de salud."},{"consecutivo":6,"texto":"Apoyar el registro de la información y el desarrollo del tratamiento a los pacientes, según indicaciones del odontólogo."},{"consecutivo":7,"texto":"Asistir al odontólogo en la toma de impresiones y el vaciado, según protocolo."},{"consecutivo":8,"texto":"Apoyar el diseño y la preparación del material educativo y de información para las acciones de promoción de la salud en personas y comunidades."},{"consecutivo":9,"texto":"Implementar acciones de información, educación y comunicación para el cuidado de la salud bucal, así como su impacto en la salud de las personas y las comunidades."},{"consecutivo":10,"texto":"Ejecutar acciones de control de biopelicula, raspado supragingival, profilaxis, sellantes, colocación de barniz de flúor en un paciente de acuerdo con sus necesidades individuales, bajo indicaciones y supervisión por parte del profesional."},{"consecutivo":11,"texto":"Apoyar las actividades administrativas requeridas por los entes reguladores y la normatividad en salud (formatos, protocolos)."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"53292.002","nombre":"Auxiliar de consultorio odontológico"},{"codigo":"53292.003","nombre":"Auxiliar de odontología"},{"codigo":"53292.004","nombre":"Auxiliar de odontología e higiene oral"},{"codigo":"53292.005","nombre":"Auxiliar en salud oral"},{"codigo":"53292.006","nombre":"Auxiliar de higiene oral"},{"codigo":"53292.008","nombre":"Asistente de salud oral / Asistenta de salud oral"},{"codigo":"53292.009","nombre":"Higienista oral"}],"conocimientos":[{"id":"40","nombre":"Anatomía"},{"id":"49","nombre":"Atención integral en salud"},{"id":"22","nombre":"Educación y capacitación"},{"id":"41","nombre":"Primeros auxilios"},{"id":"50","nombre":"Servicio a la persona y humanización"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"15","nombre":"Orientación al servicio"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"34","nombre":"Trabajo bajo presión"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"32141","nombre":"Técnicos en mecánica dental / Técnicas en mecánica dental"}],"area_principal":{"sigla":"SABI","nombre":"Salud y bienestar"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"5329*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"3222*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"3312*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Auxiliares en salud pública', '53293', 'Salud y bienestar', 2, false, '{"codigo":"53293","nombre":"Auxiliares en salud pública","descripcion":"Realizan actividades de apoyo y complementación en salud pública, mediante acciones individuales y colectivas de educación, información, promoción y mantenimiento de la salud, la prevención y la mitigación de riesgos, la identificación de eventos de interés en salud pública, el cuidado del medio ambiente y de determinantes sociales en salud, la inclusión social y la participación social en salud bajo la delegación, la supervisión y el seguimiento de profesionales de salud en el marco de las políticas y las normas del sector, teniendo en cuenta las características poblacionales, culturales y territoriales. Se pueden desempeñar en instituciones de salud y gobierno, en entidades territoriales, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"53","nombre":"TRABAJADORES DE LOS CUIDADOS PERSONALES"},"subgrupo":{"codigo":"532","nombre":"Trabajadores de los cuidados personales en servicios de salud"},"grupo_primario":{"codigo":"5329","nombre":"Trabajadores de los cuidados personales en servicios de salud no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Orientar a las personas, las familias y las comunidades sobre sus derechos y deberes, según normativa de salud."},{"consecutivo":2,"texto":"Participar en la caracterización de la situación de salud individual y colectiva en relación con los determinantes sociales de la salud."},{"consecutivo":3,"texto":"Apoyar la implementación de las medidas de prevención y atención para el control y la eliminación de enfermedades transmisibles y factores de riesgo presentes en el ambiente."},{"consecutivo":4,"texto":"Ejecutar prácticas de trabajo seguro en el desarrollo de su rol conforme a las normas técnicas y legales establecidas."},{"consecutivo":5,"texto":"Participar en los procesos de educación para la salud, la información y la comunicación con la comunidad y el equipo de salud, fundamentado en el diálogo de saberes, de los usos y las costumbres de las personas, las familias y las comunidades presentes en el territorio, para el cuidado de la vida y la salud, según técnicas y normas legales."},{"consecutivo":6,"texto":"Apoyar la conformación y el funcionamiento de los comités de salud y de otras formas de organización social y comunitaria orientadas a salud."},{"consecutivo":7,"texto":"Administrar inmunobiológicos, según la delegación del profesional y la normativa vigente."},{"consecutivo":8,"texto":"Asistir personas de acuerdo con las guías de atención y los protocolos de primer respondiente, según la normativa vigente."},{"consecutivo":9,"texto":"Apoyar a los equipos de salud en actividades de vigilancia en eventos de interés en salud pública y comunitaria."},{"consecutivo":10,"texto":"Apoyar la identificación, la captación y el monitoreo del acceso efectivo a servicios de salud, según la normativa vigente."},{"consecutivo":11,"texto":"Apoyar el proceso de entrega de suministros médicos y de seguimiento al cumplimiento del tratamiento, según lo establecido en los programas de control, eliminación y erradicación en salud pública."},{"consecutivo":12,"texto":"Registrar los datos en los sistemas de información disponibles en los diferentes programas de salud pública."},{"consecutivo":13,"texto":"Apoyar la identificación las dinámicas socioculturales de los territorios, el reconocimiento de los modos, las formas y los estilos de vida, así como las necesidades y las prioridades de las poblaciones para facilitar la gestión de la salud pública y las condiciones sociosanitarias."},{"consecutivo":14,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"53293.001","nombre":"Auxiliar de salud familiar y comunitaria"},{"codigo":"53293.002","nombre":"Auxiliar en cuidado comunitario"},{"codigo":"53293.003","nombre":"Auxiliar promotor de salud / Auxiliar promotora de salud"},{"codigo":"53293.004","nombre":"Auxiliar en salud pública"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"41","nombre":"Primeros auxilios"},{"id":"86","nombre":"Saneamiento de la comunidad"},{"id":"50","nombre":"Servicio a la persona y humanización"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"15","nombre":"Orientación al servicio"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"32530","nombre":"Trabajadores comunitarios de la salud / Trabajadoras comunitarias de la salud"},{"codigo":"53291","nombre":"Auxiliares en enfermería"}],"area_principal":{"sigla":"SABI","nombre":"Salud y bienestar"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"5329*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"3313*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Auxiliares de laboratorio clínico', '53294', 'Salud y bienestar', 2, false, '{"codigo":"53294","nombre":"Auxiliares de laboratorio clínico","descripcion":"Reciben y toman muestras de laboratorio, llevan registros y velan por el mantenimiento de los equipos de laboratorio. Se pueden desempeñar en laboratorios, hospitales, clínicas, centros de salud, instituciones de investigación, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"53","nombre":"TRABAJADORES DE LOS CUIDADOS PERSONALES"},"subgrupo":{"codigo":"532","nombre":"Trabajadores de los cuidados personales en servicios de salud"},"grupo_primario":{"codigo":"5329","nombre":"Trabajadores de los cuidados personales en servicios de salud no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Recibir y tomar muestras de sangre, tejidos u otras de acuerdo con los exámenes solicitados y las normas establecidas."},{"consecutivo":2,"texto":"Preparar el material necesario y montar las pruebas requeridas, de acuerdo con los exámenes solicitados y la normativa en salud."},{"consecutivo":3,"texto":"Instruir al usuario sobre la forma de recolectar las muestras y las condiciones con que se debe presentar al examen."},{"consecutivo":4,"texto":"Preparar muestras para cultivo de acuerdo con los exámenes solicitados y la normativa en salud."},{"consecutivo":5,"texto":"Llevar registros y archivos administrativos y estadísticas mensuales de las actividades en el laboratorio clínico."},{"consecutivo":6,"texto":"Verificar la correcta rotulación y el transporte de las muestras en la remisión interna y externa."},{"consecutivo":7,"texto":"Velar por el cuidado, el mantenimiento y la asepsia de los aparatos, elementos y equipos del laboratorio."},{"consecutivo":8,"texto":"Hacer las requisiciones de materiales e insumos para el laboratorio."},{"consecutivo":9,"texto":"Registrar y hacer seguimiento de la información relacionada con donantes."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"53294.001","nombre":"Auxiliar de laboratorio clínico"},{"codigo":"53294.002","nombre":"Auxiliar de servicios asistenciales de laboratorio"},{"codigo":"53294.003","nombre":"Ayudante de laboratorio clínico"},{"codigo":"53294.004","nombre":"Flebotomista"}],"conocimientos":[{"id":"17","nombre":"Biología"},{"id":"41","nombre":"Primeros auxilios"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"7","nombre":"Aprendizaje aplicado"},{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"6","nombre":"Pensamiento crítico"}],"ocupaciones_afines":[{"codigo":"32120","nombre":"Técnicos de laboratorios médicos / Técnicas de laboratorios médicos"},{"codigo":"32560","nombre":"Asistentes médicos / Asistentas médicas"},{"codigo":"53291","nombre":"Auxiliares en enfermería"},{"codigo":"53293","nombre":"Auxiliares en salud pública"}],"area_principal":{"sigla":"SABI","nombre":"Salud y bienestar"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"5329*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"3314*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Auxiliares en servicios farmacéuticos', '53295', 'Salud y bienestar', 2, false, '{"codigo":"53295","nombre":"Auxiliares en servicios farmacéuticos","descripcion":"Apoyan la prestación del servicio farmacéutico en los procesos de recepción, almacenamiento y dispensación de medicamentos, dispositivos médicos y otros productos farmacéuticos. Brindan información sobre el uso adecuado de medicamentos. Brindan apoyo en las actividades de distribución de medicamentos y dispositivos médicos así como las actividades del sistema de distribución de medicamentos en dosis unitaria, todo lo anterior bajo la delegación y la supervisión de profesionales del servicio farmacéutico. Se pueden desempeñar en los servicios farmacéuticos independientes (establecimientos farmacéuticos mayoristas y minoristas) y dependientes (prestadores de servicios de salud), tiendas naturistas, farmacias veterinarias, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"53","nombre":"TRABAJADORES DE LOS CUIDADOS PERSONALES"},"subgrupo":{"codigo":"532","nombre":"Trabajadores de los cuidados personales en servicios de salud"},"grupo_primario":{"codigo":"5329","nombre":"Trabajadores de los cuidados personales en servicios de salud no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Apoyar en la recepción y el despacho de medicamentos y dispositivos médicos en los servicios farmacéuticos, según la normativa de salud."},{"consecutivo":2,"texto":"Clasificar y almacenar medicamentos y dispositivos médicos, de acuerdo con las especificaciones técnicas y la normativa de salud."},{"consecutivo":3,"texto":"Dispensar medicamentos y dispositivos médicos, según la delegación y la normativa de salud."},{"consecutivo":4,"texto":"Mantener el inventario de medicamentos, dispositivos médicos y medicamentos de control especial actualizado, de acuerdo con las existencias físicas frente a los registros de los movimientos de entrada y salida."},{"consecutivo":5,"texto":"Surtir medicamentos, dispositivos médicos y productos farmacéuticos, según el plan y las técnicas de mercadeo."},{"consecutivo":6,"texto":"Elaborar y tramitar documentos relacionados con la distribución de medicamentos, dispositivos médicos y productos farmacéuticos."},{"consecutivo":7,"texto":"Administrar medicamentos vía intramuscular de acuerdo con la prescripción médica en establecimientos farmacéuticos minoristas autorizados de conformidad con la normativa en salud."},{"consecutivo":8,"texto":"Implementar medidas de asepsia para todas las actividades del servicio farmacéutico, según el manual de bioseguridad y la normativa de salud."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"53295.002","nombre":"Auxiliar de droguería"},{"codigo":"53295.004","nombre":"Auxiliar de farmacia"},{"codigo":"53295.005","nombre":"Auxiliar farmacéutico / Auxiliar farmacéutica"},{"codigo":"53295.006","nombre":"Auxiliar en servicios farmacéuticos"}],"conocimientos":[{"id":"70","nombre":"Farmacia"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"14","nombre":"Matemáticas"},{"id":"41","nombre":"Primeros auxilios"},{"id":"7","nombre":"Producción y procesamiento"},{"id":"50","nombre":"Servicio a la persona y humanización"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"15","nombre":"Orientación al servicio"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"10","nombre":"Relaciones interpersonales"}],"ocupaciones_afines":[{"codigo":"32130","nombre":"Técnicos y asistentes farmacéuticos / Técnicas y asistentes farmacéuticas"}],"area_principal":{"sigla":"SABI","nombre":"Salud y bienestar"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"3213*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"3315*","cno_obs"