  ('rol_cuoc', 'Trabajadores de los cuidados personales en servicios de salud no clasificados en otras ocupaciones / Trabajadoras de los cuidados personales en servicios de salud no clasificados en otras ocupaciones', '53299', 'Salud y bienestar', 2, false, '{"codigo":"53299","nombre":"Trabajadores de los cuidados personales en servicios de salud no clasificados en otras ocupaciones / Trabajadoras de los cuidados personales en servicios de salud no clasificados en otras ocupaciones","descripcion":"Esta Ocupación abarca a Trabajadores de los cuidados personales en servicios de salud no clasificados en otras ocupaciones en el Grupo Primario 5329: Trabajadores de los cuidados personales en servicios de salud no clasificados en otros Grupos Primarios. Por ejemplo, incluye aquellos que limpian, desinfectan y esterilizan pisos, paredes, y otros divisorios de áreas críticas de centro de salud y consultorios médicos. Preparan a los pacientes para su examen o tratamiento según indicaciones, protocolos y normativa en salud. Se pueden desempeñar en laboratorios, hospitales, clínicas, centros de salud, instituciones de investigación, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"53","nombre":"TRABAJADORES DE LOS CUIDADOS PERSONALES"},"subgrupo":{"codigo":"532","nombre":"Trabajadores de los cuidados personales en servicios de salud"},"grupo_primario":{"codigo":"5329","nombre":"Trabajadores de los cuidados personales en servicios de salud no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Limpiar, desinfectar y esterilizar pisos, paredes, y otros divisorios de áreas críticas de centro de salud y consultorios médicos."},{"consecutivo":2,"texto":"Preparar a los pacientes para su examen o tratamiento según indicaciones, protocolos y normativa en salud."},{"consecutivo":3,"texto":"Organizar las bandejas de instrumentos, preparación de materiales e insumos en procedimientos médicos, toma de exámenes e imágenes diagnosticas según indicaciones, protocolos y normativa en salud."},{"consecutivo":4,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"53299.001","nombre":"Auxiliar de esterilización"},{"codigo":"53299.002","nombre":"Auxiliar de imagen médica"},{"codigo":"53299.003","nombre":"Auxiliar de sala de esterilización"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"41","nombre":"Primeros auxilios"},{"id":"27","nombre":"Seguridad pública"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"6","nombre":"Pensamiento crítico"}],"ocupaciones_afines":[{"codigo":"91120","nombre":"Aseadores de oficinas, hoteles y otros establecimientos / Aseadoras de oficinas, hoteles y otros establecimientos"}],"area_principal":{"sigla":"SABI","nombre":"Salud y bienestar"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"5329*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"6632*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Oficiales de bomberos', '54111', 'Seguridad', 4, false, '{"codigo":"54111","nombre":"Oficiales de bomberos","descripcion":"Gestionan y administran el recurso humano, económico, físico y tecnológico de las áreas asignadas en el cuerpo de bomberos para garantizar la gestión integral del riesgo contra incendios, el rescate en todas sus modalidades, la atención de incidentes con materiales peligrosos y otras emergencias. Se pueden desempeñar en el gobierno, entidades no gubernamentales y particulares que presten los servicios bomberiles relacionadas con la gestión integral del riesgo, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"54","nombre":"PERSONAL DE LOS SERVICIOS DE PROTECCIÓN"},"subgrupo":{"codigo":"541","nombre":"Personal de los servicios de protección"},"grupo_primario":{"codigo":"5411","nombre":"Bomberos"}},"funciones":[{"consecutivo":1,"texto":"Planear y desarrollar planes, programas y proyectos para la gestión integral del riesgo contra incendios, rescates en todas sus modalidades, atención de incidentes con materiales peligrosos u otras emergencias."},{"consecutivo":2,"texto":"Evaluar y formular objetivos, estrategias y tácticas de intervención, de acuerdo con procedimientos, protocolos y normativa vigente."},{"consecutivo":3,"texto":"Planear, dirigir y coordinar las acciones encaminadas a la gestión integral de riesgos contra incendios, rescates en todas sus modalidades, atención de incidentes con materiales peligrosos u otras emergencias de acuerdo con protocolos y procedimientos."},{"consecutivo":4,"texto":"Planear y coordinar los programas de capacitación y entrenamiento misional de los cuerpos de bomberos de acuerdo con normativa vigente."},{"consecutivo":5,"texto":"Planear y coordinar los programas de la gestión del riesgo dirigido a la comunidad de acuerdo con normativa vigente y en coordinación con la oficina de gestión del riesgo de desastres de su jurisdicción."},{"consecutivo":6,"texto":"Cooperar con las autoridades competentes en la gestión integral del riesgo de desastres en los territorios, a fin de garantizar la protección a la vida, los bienes y el medio ambiente."},{"consecutivo":7,"texto":"Formular planes, programas y proyectos para el mejoramiento de la prestación del servicio del cuerpo de bomberos según normativa vigente."},{"consecutivo":8,"texto":"Vigilar y hacer cumplir la aplicación de las normas sobre la prestación del servicio de conformidad con normativa vigente."},{"consecutivo":9,"texto":"Evaluar incidentes, según procedimientos y protocolos."},{"consecutivo":10,"texto":"Realizar cierre administrativo y operativo de incidentes, de acuerdo con procedimientos y protocolos."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"54111.001","nombre":"Capitán de bomberos"},{"codigo":"54111.002","nombre":"Oficial comandante de bomberos"},{"codigo":"54111.003","nombre":"Oficial de bomberos"},{"codigo":"54111.004","nombre":"Oficial subcomandante de bomberos"},{"codigo":"54111.005","nombre":"Subteniente de bomberos"},{"codigo":"54111.006","nombre":"Teniente de bomberos"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"1","nombre":"Gerencia y administración"},{"id":"45","nombre":"Gestión del riesgo de desastres"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"41","nombre":"Primeros auxilios"},{"id":"27","nombre":"Seguridad pública"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"32","nombre":"Gestión del Talento Humano y de Personal"},{"id":"33","nombre":"Liderazgo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"37","nombre":"Proactividad"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"54112","nombre":"Suboficiales de bombero