  ('rol_cuoc', 'Suboficiales de bomberos', '54112', 'Seguridad', 3, false, '{"codigo":"54112","nombre":"Suboficiales de bomberos","descripcion":"Dirigen y coordinan las acciones relacionadas con la gestión integral del riesgo contra incendios, los preparativos y el rescate en todas sus modalidades, la atención de incidentes con materiales peligrosos y lideran las actuaciones en otras emergencias. Se pueden desempeñar en el gobierno, las entidades no gubernamentales y los particulares que presten los servicios bomberiles relacionadas con la gestión integral del riesgo, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"54","nombre":"PERSONAL DE LOS SERVICIOS DE PROTECCIÓN"},"subgrupo":{"codigo":"541","nombre":"Personal de los servicios de protección"},"grupo_primario":{"codigo":"5411","nombre":"Bomberos"}},"funciones":[{"consecutivo":1,"texto":"Coordinar y dirigir la respuesta a incendio, rescate, materiales peligrosos y otros incidentes de acuerdo con procedimientos de emergencia, protocolos y normativa."},{"consecutivo":2,"texto":"Realizar la evaluación de incidente y diseñar los objetivos, las estrategias y las tácticas de intervención, de acuerdo con procedimientos, protocolos y normativa."},{"consecutivo":3,"texto":"Verificar las condiciones de seguridad del entorno y del personal asignado a la operación de acuerdo con procedimientos, protocolos y normativa."},{"consecutivo":4,"texto":"Determinar la necesidad de recursos y solicitarlos, de acuerdo con los procedimientos y protocolos."},{"consecutivo":5,"texto":"Realizar el cierre operativo y administrativo de incidentes, según protocolos y procedimientos."},{"consecutivo":6,"texto":"Realizar la evaluación posincidente con el fin de determinar acciones de mejoras, según procedimientos y normativa."},{"consecutivo":7,"texto":"Verificar la operación, el uso, el cuidado y el mantenimiento del parque automotor, equipos, herramientas, accesorios y elementos de protección personal para la atención de incidentes de acuerdo con manuales, procedimientos y protocolos."},{"consecutivo":8,"texto":"Iniciar el trámite de requerimientos para la revisión, el mantenimiento y el reemplazo del parque automotor, equipos, herramientas, accesorios y elementos de protección de acuerdo con procedimientos."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"54112.001","nombre":"Cabo bomberos"},{"codigo":"54112.002","nombre":"Sargento de bomberos"},{"codigo":"54112.003","nombre":"Suboficial comandante de bomberos"},{"codigo":"54112.004","nombre":"Suboficial de bomberos"},{"codigo":"54112.005","nombre":"Suboficial subcomandante de bomberos"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"45","nombre":"Gestión del riesgo de desastres"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"41","nombre":"Primeros auxilios"},{"id":"27","nombre":"Seguridad pública"},{"id":"5","nombre":"Servicio al cliente"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"33","nombre":"Liderazgo"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"54111","nombre":"Oficiales de bomberos"},{"codigo":"54113","nombre":"Bomberos / Bomberas"}],"area_principal":{"sigla":"SEGU","nombre":"Seguridad"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"5411*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"6225","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Bomberos / Bomberas', '54113', 'Seguridad', 2, false, '{"codigo":"54113","nombre":"Bomberos / Bomberas","descripcion":"Ejecutan las acciones relacionadas con la gestión integral del riesgo contra incendios, los preparativos y el rescate en todas sus modalidades, la atención de incidentes con materiales peligrosos y actúan en otras emergencias. Se pueden desempeñar en el gobierno, las entidades no gubernamentales y particulares que presten los servicios bomberiles relacionadas con la gestión integral del riesgo, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"54","nombre":"PERSONAL DE LOS SERVICIOS DE PROTECCIÓN"},"subgrupo":{"codigo":"541","nombre":"Personal de los servicios de protección"},"grupo_primario":{"codigo":"5411","nombre":"Bomberos"}},"funciones":[{"consecutivo":1,"texto":"Responder al llamado de emergencias por incendio, rescate, materiales peligrosos y otros incidentes, de acuerdo con procedimientos de emergencia, protocolos y/o normativa vigente."},{"consecutivo":2,"texto":"Controlar, extinguir y liquidar el fuego utilizando equipos, herramientas, accesorios, elementos de protección personal adecuados y maquinaria, de acuerdo con los protocolos, procedimientos de emergencia y/o la normativa vigente."},{"consecutivo":3,"texto":"Desarrollar operaciones de búsqueda, localización, acceso, estabilización y extracción de víctimas en incidentes según procedimientos, protocolos establecidos y normativa vigente."},{"consecutivo":4,"texto":"Brindar soporte básico de vida a pacientes humanos, de acuerdo con protocolos y procedimientos establecidos."},{"consecutivo":5,"texto":"Desarrollar operaciones de control de incidentes con materiales peligrosos, según protocolos, procedimientos y/o normativa vigente."},{"consecutivo":6,"texto":"Realizar la evaluación del incidente y diseñar objetivos, estrategias y tácticas de intervención, de acuerdo con procedimientos, protocolos y normativa vigente."},{"consecutivo":7,"texto":"Operar, usar, cuidar y mantener el parque automotor, equipos, herramientas, accesorios y elementos de protección personal para la respuesta a incendios y rescate en todas sus modalidades, y la atención de incidentes con materiales peligrosos, de acuerdo con las guías, los manuales, procedimientos y protocolos."},{"consecutivo":8,"texto":"Realizar actividades de gestión integral del riego dirigidas a la comunidad, de acuerdo con la normativa vigente."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"54113.001","nombre":"Bombero / Bombera"},{"codigo":"54113.002","nombre":"Bombero aeronáutico / Bombera aeronáutica"},{"codigo":"54113.003","nombre":"Bombero aeroportuario / Bombera aeroportuaria"},{"codigo":"54113.004","nombre":"Bombero comandante / Bombera comandante"},{"codigo":"54113.005","nombre":"Bombero de la industria petrolera / Bombera de la industria petrolera"},{"codigo":"54113.006","nombre":"Bombero subcomandante / Bombera subcomandante"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"1","nombre":"Gerencia y administración"},{"id":"45","nombre":"Gestión del riesgo de desastres"},{"id":"41","nombre":"Primeros auxilios"},{"id":"16","nombre":"Química"},{"id":"27","nombre":"Seguridad pública"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"34","nombre":"Trabajo bajo presión"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"54112","nombre":"Suboficiales de bomberos"}],"area_principal":{"sigla":"SEGU","nombre":"Seguridad"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"5411*","ciuo08_obs":"Denominaciones parciales","cno_co