  ('rol_cuoc', 'Auxiliares de policía', '54124', 'Seguridad', 2, false, '{"codigo":"54124","nombre":"Auxiliares de policía","descripcion":"Controlan, apoyan y velan por el mantenimiento de la ley, el orden público y la protección ciudadana, hacen respetar leyes y reglamentos. Se pueden desempeñar en sector público, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"54","nombre":"PERSONAL DE LOS SERVICIOS DE PROTECCIÓN"},"subgrupo":{"codigo":"541","nombre":"Personal de los servicios de protección"},"grupo_primario":{"codigo":"5412","nombre":"Policías"}},"funciones":[{"consecutivo":1,"texto":"Patrullar las áreas urbanas o rurales asignadas para mantener la seguridad y el orden público, para hacer cumplir las leyes y regulaciones."},{"consecutivo":2,"texto":"Implementar registro de acuerdo con procedimiento técnico de policía y marco legal."},{"consecutivo":3,"texto":"Controlar accesos a áreas de acuerdo con las características del servicio y la normatividad."},{"consecutivo":4,"texto":"Organizar actividades recreodeportivas, según parámetros técnicos."},{"consecutivo":5,"texto":"Preservar la autenticidad del elemento material probatorio y evidencia física (emp/ef) conforme a la normatividad vigente."},{"consecutivo":6,"texto":"Participar en actividades y programas de prevención, información y seguridad pública disuasivas y reactivas orientadas a la difusión de normas de comportamiento ciudadano, mantenimiento de la ley y el orden."},{"consecutivo":7,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"54124.001","nombre":"Auxiliar de bachiller de la policía"},{"codigo":"54124.002","nombre":"Auxiliar de policía"},{"codigo":"54124.003","nombre":"Auxiliar no bachiller de la policía"},{"codigo":"54124.004","nombre":"Auxiliar social y comunitario / Auxiliar social y comunitaria"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"27","nombre":"Seguridad pública"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"34","nombre":"Trabajo bajo presión"}],"ocupaciones_afines":[{"codigo":"54122","nombre":"Suboficiales y nivel ejecutivo de la policía"},{"codigo":"54123","nombre":"Patrulleros y agentes de policía / Patrulleras y agentes de policía"}],"area_principal":{"sigla":"SEGU","nombre":"Seguridad"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"5412*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"6363","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Oficiales del cuerpo de custodia y vigilancia', '54131', 'Seguridad', 4, false, '{"codigo":"54131","nombre":"Oficiales del cuerpo de custodia y vigilancia","descripcion":"Planean, implementan y gestionan planes, programas y proyectos de seguridad penitenciaria y carcelaria para la ejecución de la pena privativa de la libertad, atención básica y el tratamiento penitenciario, administrando los recursos físicos y de talento humano del cuerpo de custodia y vigilancia penitenciaria y carcelaria nacional, conforme al marco jurídico, procedimientos y reglamentos internos. Se pueden desempeñar en sector público, entre otros.","nivel_competencia":4,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"54","nombre":"PERSONAL DE LOS SERVICIOS DE PROTECCIÓN"},"subgrupo":{"codigo":"541","nombre":"Personal de los servicios de protección"},"grupo_primario":{"codigo":"5413","nombre":"Cuerpo de custodia y guardianes de prisión"}},"funciones":[{"consecutivo":1,"texto":"Dirigir los servicios de orden, seguridad y disciplina en los establecimientos penitenciarios, carcelarios y las dependencias administrativos, de acuerdo con reglamentos, procedimientos y normativa."},{"consecutivo":2,"texto":"Administrar el talento humano a su cargo de acuerdo con reglamentos, procedimientos y normativa."},{"consecutivo":3,"texto":"Planear programas y proyectos administrativos para la ejecución de la pena privativa de la libertad, la atención básica y el tratamiento penitenciario, de acuerdo con reglamentos, procedimientos y normativa."},{"consecutivo":4,"texto":"Controlar la ejecución de las políticas, los planes y los programas de tratamiento penitenciario, atención básica, administración y planeación de los servicios asistenciales a la población privada de la libertad a cargo, de acuerdo con procedimientos y normativa."},{"consecutivo":5,"texto":"Orientar las órdenes y los requerimientos de las autoridades judiciales, administrativas y de los organismos de control de acuerdo con protocolos, lineamientos y normativa vigente."},{"consecutivo":6,"texto":"Administrar los recursos financieros, físicos y tecnológicos del establecimiento penitenciario, carcelario y dependencias administrativas, de acuerdo con reglamentos, procedimientos y normativa."},{"consecutivo":7,"texto":"Diseñar y proponer esquemas de seguridad y defensa, contingencia y emergencia conforme con procedimientos y normativa."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"54131.001","nombre":"Capitán de prisiones"},{"codigo":"54131.002","nombre":"Comandante superior de prisiones"},{"codigo":"54131.003","nombre":"Mayor de prisiones"},{"codigo":"54131.004","nombre":"Oficial de tratamiento penitenciario"},{"codigo":"54131.005","nombre":"Oficial del cuerpo de custodia y vigilancia"},{"codigo":"54131.006","nombre":"Oficial logístico de prisiones"},{"codigo":"54131.007","nombre":"Teniente de prisiones"}],"conocimientos":[{"id":"1","nombre":"Gerencia y administración"},{"id":"6","nombre":"Gestión del talento humano y de personal"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"14","nombre":"Matemáticas"},{"id":"27","nombre":"Seguridad pública"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"2","nombre":"Escucha activa"},{"id":"33","nombre":"Liderazgo"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"16","nombre":"Resolución de problemas complejos"},{"id":"34","nombre":"Trabajo bajo presión"}],"ocupaciones_afines":[{"codigo":"01100","nombre":"Oficiales de las Fuerzas Militares"},{"codigo":"11120","nombre":"Directores del gobierno / Directoras del gobierno"},{"codigo":"54121","nombre":"Oficiales de policía"}],"area_principal":{"sigla":"SEGU","nombre":"Seguridad"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"5413*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"0644","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Suboficiales del cuerpo de custodia y vigilancia', '54132', 'Seguridad', 3, false, '{"codigo":"54132","nombre":"Suboficiales del cuerpo de custodia y vigilancia","descripcion":"Coordinan, ejecutan y controlan las acciones de seguridad, administrativas y de tratamiento penitenciario de conformidad con el marco jurídico, los procedimientos y los reglamentos internos.  Se pueden desempeñar en sector público, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"54","nombre":"PERSONAL DE LOS SERVICIOS DE PROTECCIÓN"},"subgrupo":{"codigo":"541","nombre":"Personal de los servicios de protección"},"grupo_primario":{"codigo":"5413","nombre":"Cuerpo de custodia y guardianes de prisión"}},"funciones":[{"consecutivo":1,"texto":"Ejecutar las órdenes de servicio en los aspectos de orden, seguridad, disciplina, atención básica, tratamiento penitenciario y administración de acuerdo con procedimientos y normativa."},{"consecutivo":2,"texto":"Administrar el talento humano a su cargo de acuerdo con reglamentos, procedimientos y normativa."},{"consecutivo":3,"texto":"Supervisar las actividades de seguridad y tratamiento penitenciario en cada uno de los servicios y puestos de trabajo, de acuerdo con los reglamentos y procedimientos."},{"consecutivo":4,"texto":"Adoptar medidas de prevención y corrección en los eventos de afectación de la seguridad, orden, disciplina y procesos de atención básica y tratamiento penitenciario de acuerdo con el marco jurídico y procedimientos."},{"consecutivo":5,"texto":"Verificar el cumplimiento de esquemas de seguridad y defensa, contingencia y emergencia, de acuerdo con órdenes administrativas y judiciales, marco jurídico y procedimientos."},{"consecutivo":6,"texto":"Controlar la presencia física y ubicación de las personas privadas de la libertad de acuerdo con el marco jurídico y procedimientos."},{"consecutivo":7,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"54132.001","nombre":"Inspector jefe penitenciario / Inspectora jefa penitenciaria"},{"codigo":"54132.002","nombre":"Inspector penitenciario / Inspectora penitenciaria"},{"codigo":"54132.003","nombre":"Subinspector penitenciario / Subinspectora penitenciaria"},{"codigo":"54132.004","nombre":"Suboficial del cuerpo de custodia y vigilancia"}],"conocimientos":[{"id":"6","nombre":"Gestión del talento humano y de personal"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"14","nombre":"Matemáticas"},{"id":"27","nombre":"Seguridad pública"},{"id":"2","nombre":"Servicios de oficina y administrativos"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"32","nombre":"Gestión del Talento Humano y de Personal"},{"id":"33","nombre":"Liderazgo"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"16","nombre":"Resolución de problemas complejos"}],"ocupaciones_afines":[{"codigo":"02100","nombre":"Suboficiales de las Fuerzas Militares"},{"codigo":"54122","nombre":"Suboficiales y nivel ejecutivo de la policía"}],"area_principal":{"sigla":"SEGU","nombre":"Seguridad"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"5413*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"6224","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Guardianes de prisión / Guardianas de prisión', '54133', 'Seguridad', 2, false, '{"codigo":"54133","nombre":"Guardianes de prisión / Guardianas de prisión","descripcion":"Custodian reclusos y detenidos y mantienen el orden en las instituciones correccionales y otros lugares de detención. Se pueden desempeñar en sector público, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"54","nombre":"PERSONAL DE LOS SERVICIOS DE PROTECCIÓN"},"subgrupo":{"codigo":"541","nombre":"Personal de los servicios de protección"},"grupo_primario":{"codigo":"5413","nombre":"Cuerpo de custodia y guardianes de prisión"}},"funciones":[{"consecutivo":1,"texto":"Registrar a los nuevos reclusos en el momento de su ingreso, poner sus valores en custodia, escoltarlos hasta sus celdas, de acuerdo con protocolo de operación del establecimiento penitenciario y normativa."},{"consecutivo":2,"texto":"Inspeccionar periódicamente las diferentes áreas del establecimiento penitenciario para mantener la seguridad de los internos, personal de custodia y visitantes."},{"consecutivo":3,"texto":"Supervisar a los internos durante las jornadas de trabajo, comidas y períodos de recreación, de acuerdo con procedimientos y normativa."},{"consecutivo":4,"texto":"Observar la conducta y comportamiento de reclusos para prevenir disturbios y fugas, de acuerdo con protocolo de operación del establecimiento penitenciario y normativa."},{"consecutivo":5,"texto":"Patrullar áreas asignadas del establecimiento penitenciario para mantener la seguridad de los internos, el personal de custodia y los visitantes, reportar novedades al superior, de acuerdo con procedimientos y normativa."},{"consecutivo":6,"texto":"Ayudar a aplicar programas de rehabilitación a internos de acuerdo con protocolo de operación del establecimiento penitenciario y normativa."},{"consecutivo":7,"texto":"Escoltar internos en sus desplazamientos a audiencias judiciales, permisos temporales, entre otros, de acuerdo con protocolo de operación del establecimiento penitenciario y normativa."},{"consecutivo":8,"texto":"Practicar requisas a los internos y visitantes del establecimiento penitenciario para garantizar la seguridad en el penal, de acuerdo con protocolo de operación y normativa."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"54133.001","nombre":"Cabo prisión"},{"codigo":"54133.002","nombre":"Dragoneante del cuerpo de custodia y vigilancia"},{"codigo":"54133.003","nombre":"Guardián de cárcel / Guardiana de cárcel"},{"codigo":"54133.004","nombre":"Guardián de correccional / Guardiana de correccional"},{"codigo":"54133.005","nombre":"Guardián de prisión / Guardiana de prisión"},{"codigo":"54133.006","nombre":"Guardián penitenciario / Guardiana penitenciaria"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"27","nombre":"Seguridad pública"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"38","nombre":"Seguir instrucciones"}],"ocupaciones_afines":[{"codigo":"54142","nombre":"Vigilantes, guardas y personal operativo de seguridad privada"}],"area_principal":{"sigla":"SEGU","nombre":"Seguridad"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"5413*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"6365","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Supervisor de personal de vigilancia / Supervisora de personal de vigilancia', '54141', 'Seguridad', 3, false, '{"codigo":"54141","nombre":"Supervisor de personal de vigilancia / Supervisora de personal de vigilancia","descripcion":"Coordinan, supervisan y dirigen las actividades del personal de seguridad privada en los lugares en los que se esté prestando el servicio; verifican el cumplimiento de funciones, protocolos y normas de vigilancia y seguridad privada; apoyan a la empresa y al personal de seguridad en caso de eventualidades presentados en el puesto. Se pueden desempeñar en departamentos de seguridad, cooperativas y empresas de vigilancia y seguridad privada, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"54","nombre":"PERSONAL DE LOS SERVICIOS DE PROTECCIÓN"},"subgrupo":{"codigo":"541","nombre":"Personal de los servicios de protección"},"grupo_primario":{"codigo":"5414","nombre":"Vigilantes y guardias de seguridad"}},"funciones":[{"consecutivo":1,"texto":"Supervisar, coordinar y programar las actividades del personal de vigilancia según normativa y requerimientos de seguridad privada."},{"consecutivo":2,"texto":"Coordinar actividades con otras áreas o departamentos de la empresa teniendo en cuenta la normatividad de la vigilancia y seguridad privada."},{"consecutivo":3,"texto":"Recomendar sistemas de seguridad y la utilización de medios y modalidades, de acuerdo con el perfil de riesgo del cliente."},{"consecutivo":4,"texto":"Efectuar rondas periódicas a los sitios vigilados por el personal a su cargo para garantizar y verificar la prestación del servicio de vigilancia y seguridad privada."},{"consecutivo":5,"texto":"Verificar el cumplimiento de las normas del sector de vigilancia y seguridad privada."},{"consecutivo":6,"texto":"Instruir al personal acerca de las funciones y las políticas de la empresa, los esquemas de seguridad privada, los riesgos y las metodologías de la prestación del servicio."},{"consecutivo":7,"texto":"Reportar y gestionar novedades laborales de acuerdo con políticas y lineamientos del servicio de vigilancia y seguridad privada."},{"consecutivo":8,"texto":"Elaborar informes operativos de actividades del personal a su cargo, incidentes y gestión del servicio de seguridad privada."},{"consecutivo":9,"texto":"Verificar el cumplimiento del reentrenamiento anual del personal operativo, la práctica del exámen psicofísico para el porte y la tenencia de armas de fuego y la acreditación ante el ente regulatorio, el contenido y la puesta en marcha del decálogo de seguridad de armas de fuego."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"54141.001","nombre":"Especialista en seguridad y vigilancia"},{"codigo":"54141.002","nombre":"Supervisor de puesto fijo de seguridad y vigilancia / Supervisora de puesto fijo de seguridad y vigilancia"},{"codigo":"54141.003","nombre":"Supervisor de rondas de seguridad y vigilancia / Supervisora de rondas de seguridad y vigilancia"},{"codigo":"54141.004","nombre":"Supervisor de seguridad y vigilancia / Supervisora de seguridad y vigilancia"},{"codigo":"54141.005","nombre":"Supervisor de vigilancia / Supervisora de vigilancia"},{"codigo":"54141.006","nombre":"Coordinador de vigilancia y seguridad privada / Coordinadora de vigilancia y seguridad privada"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"45","nombre":"Gestión del riesgo de desastres"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"41","nombre":"Primeros auxilios"},{"id":"5","nombre":"Servicio al cliente"},{"id":"29","nombre":"Telecomunicación"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"33","nombre":"Liderazgo"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"54132","nombre":"Suboficiales del cuerpo de custodia y vigilancia"},{"codigo":"54142","nombre":"Vigilantes, guardas y personal operativo de seguridad privada"}],"area_principal":{"sigla":"SEGU","nombre":"Seguridad"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"5414*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"6223*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Vigilantes, guardas y personal operativo de seguridad privada', '54142', 'Seguridad', 2, false, '{"codigo":"54142","nombre":"Vigilantes, guardas y personal operativo de seguridad privada","descripcion":"Custodian y monitorean personas, bienes muebles, inmuebles y valores; inspeccionan y controlan el acceso y la salida de personas, vehículos y mercancías; mantienen el orden y hacen cumplir las funciones del puesto de vigilancia de acuerdo con la normativa legal, las normas de seguridad y los protocolos establecidos a través de diferentes medios y modalidades de la vigilancia y seguridad privada. Se pueden desempeñar en empresas, sector residencial, comercial, hospitalarios, mineros, bancarios, industriales, aeroportuarios y entidades gubernamentales, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"54","nombre":"PERSONAL DE LOS SERVICIOS DE PROTECCIÓN"},"subgrupo":{"codigo":"541","nombre":"Personal de los servicios de protección"},"grupo_primario":{"codigo":"5414","nombre":"Vigilantes y guardias de seguridad"}},"funciones":[{"consecutivo":1,"texto":"Realizar rondas en áreas asignadas para prevenir robos, saqueos, vandalismo e incendios de acuerdo con protocolos de seguridad privada."},{"consecutivo":2,"texto":"Controlar y dirigir el acceso a los establecimientos de empleados y demás visitantes, verificar la identidad de las personas según protocolo del servicio de seguridad privada."},{"consecutivo":3,"texto":"Custodiar bienes muebles e inmuebles, verificando la entrada y la salida de visitantes y asistir a las personas que ingresan y salen de los mismos, según protocolo de seguridad privada."},{"consecutivo":4,"texto":"Realizar controles de seguridad a personas, inspeccionar vehículos bienes muebles e inmuebles, de acuerdo con protocolos de seguridad y normativa."},{"consecutivo":5,"texto":"Responder a las alarmas, verificar situaciones que alteran el orden y contactar con los superiores, la policía o los bomberos, según proceda."},{"consecutivo":6,"texto":"Conducir, maniobrar y vigilar camiones blindados y distribuir dinero y valores a bancos y otros establecimientos, de acuerdo con protocolos de seguridad y normativa."},{"consecutivo":7,"texto":"Hacer cumplir las normas de un establecimiento para mantener el orden y la seguridad privada."},{"consecutivo":8,"texto":"Registrar la entrada y la salida de vehículos en parqueaderos y zonas de parqueo, de acuerdo con protocolos de seguridad privada."},{"consecutivo":9,"texto":"Proteger y defender personas evitando que sean objeto de actos delictivos."},{"consecutivo":10,"texto":"Custodiar y proteger vehículos, mercancías o cualquier otro objeto durante su desplazamiento o almacenamiento y evitar que sean objeto de actos delictivos."},{"consecutivo":11,"texto":"Aplicar el decálogo de seguridad de armas de fuego con ocasión de la manipulación de estas en el puesto de trabajo."},{"consecutivo":12,"texto":"Reportar novedades operativas presentadas en el puesto de vigilancia, tales como la existencia de armas, de munición defectuosa o en mal estado y demás que se presenten de acuerdo con los protocolos de seguridad."},{"consecutivo":13,"texto":"Evaluar factores de inseguridad, estudios de seguridad y los posibles de riesgos en la ruta."},{"consecutivo":14,"texto":"Monitorear y analizar información registrada en los monitores de videos, imágenes, señales, patrones y rutinas para salvaguardar la seguridad de la persona o bien custodiado."},{"consecutivo":15,"texto":"Identificar, disminuir, prevenir riegos, amenazas y vulnerabilidades que afecten o puedan afectar la vida, la integridad personal y los bienes de las personas."},{"consecutivo":16,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"54142.003","nombre":"Celador / Celadora"},{"codigo":"54142.004","nombre":"Escolta"},{"codigo":"54142.005","nombre":"Guardaespaldas"},{"codigo":"54142.007","nombre":"Guarda de seguridad"},{"codigo":"54142.011","nombre":"Guardia de valores"},{"codigo":"54142.015","nombre":"Portero / Portera"},{"codigo":"54142.019","nombre":"Tripulante de carro de valores"},{"codigo":"54142.020","nombre":"Vigilante"},{"codigo":"54142.021","nombre":"Vigilante de carro de valores"},{"codigo":"54142.025","nombre":"Vigilante guardia de seguridad"},{"codigo":"54142.026","nombre":"Escolta de valores"},{"codigo":"54142.027","nombre":"Guarda de valores"},{"codigo":"54142.028","nombre":"Manejador canino de vigilancia y seguridad privada / Manejadora canina de vigilancia y seguridad privada"},{"codigo":"54142.029","nombre":"Operador de medios tecnológicos de vigilancia y seguridad privada / Operadora de medios tecnológicos de vigilancia y seguridad privada"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"41","nombre":"Primeros auxilios"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"54141","nombre":"Supervisor de personal de vigilancia / Supervisora de personal de vigilancia"}],"area_principal":{"sigla":"SEGU","nombre":"Seguridad"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"5312*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"6367","cno_obs":"Denominaciones completas"},{"ciuo08_codigo":"5414*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"6644*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Guardavidas y salvavidas', '54191', 'Seguridad', 3, false, '{"codigo":"54191","nombre":"Guardavidas y salvavidas","descripcion":"Previenen, vigilan y supervisan situaciones de riesgo en los diferentes cuerpos de agua. Brindan soporte básico de vida a las personas bajo protocolos internacionales. Se pueden desempeñar en centros deportivos, conjuntos residenciales, complejos acuáticos, empresas públicas y privadas, los sistemas de respuesta a emergencias, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"54","nombre":"PERSONAL DE LOS SERVICIOS DE PROTECCIÓN"},"subgrupo":{"codigo":"541","nombre":"Personal de los servicios de protección"},"grupo_primario":{"codigo":"5419","nombre":"Personal de los servicios de protección no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Patrullar y monitorear las actividades realizadas por los usuarios en las áreas designadas y estar alerta ante posibles riesgos de seguridad e infracciones."},{"consecutivo":2,"texto":"Brindar primera respuesta ante la emergencia que se presenta en el cuerpo de agua utilizando técnicas y equipos de rescate."},{"consecutivo":3,"texto":"Examinar a las personas lesionadas y administrar primeros auxilios o reanimación cardiopulmonar, si es necesario, utilizando equipos y suministros médicos."},{"consecutivo":4,"texto":"Inspeccionar el área asignada y los equipos de rescate y de recreación, tales como cuerdas, flotadores, trampolines, entre otros, para garantizar su funcionamiento optimo."},{"consecutivo":5,"texto":"Enseñar el reglamento, los procedimientos y las normas de seguridad a los usuarios."},{"consecutivo":6,"texto":"Elaborar informes sobre las condiciones del cuerpo de agua, reportando cualquier información pertinente o cualquier incidente, tales como las emergencias presentadas."},{"consecutivo":7,"texto":"Garantizar el cumplimiento del plan de seguridad y manejo de las operaciones diarias de funcionamiento."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"54191.001","nombre":"Guardavidas"},{"codigo":"54191.002","nombre":"Guardavidas de complejos acuáticos"},{"codigo":"54191.003","nombre":"Guardavidas de piscinas"},{"codigo":"54191.004","nombre":"Guardavidas de playas y mares"},{"codigo":"54191.005","nombre":"Salvavidas"},{"codigo":"54191.006","nombre":"Salvavidas de surf"}],"conocimientos":[{"id":"40","nombre":"Anatomía"},{"id":"15","nombre":"Física"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"41","nombre":"Primeros auxilios"},{"id":"16","nombre":"Química"},{"id":"85","nombre":"Seguridad y salud en el trabajo"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"16","nombre":"Resolución de problemas complejos"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"54114","nombre":"Rescatistas"},{"codigo":"54199","nombre":"Personal de los servicios de protección no clasificadas en otras ocupaciones"}],"area_principal":{"sigla":"SEGU","nombre":"Seguridad"},"areas_complementarias":[{"sigla":"CPSA","nombre":"Conservación, protección y saneamiento ambiental"}],"equivalencias":[{"ciuo08_codigo":"5419*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"3235","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Agentes de tránsito', '54192', 'Seguridad', 2, false, '{"codigo":"54192","nombre":"Agentes de tránsito","descripcion":"Regulan la circulación vehicular y de los actores viales; vigilan, controlan e intervienen en el cumplimiento de las normas de tránsito y transporte a partir de la asistencia en los incidentes y accidentes viales y la promoción y prevención de la seguridad vial. Se pueden desempeñar en organismos de tránsito, organismos de apoyo al tránsito, secretarías de tránsito o de movilidad e inspecciones de tránsito, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"54","nombre":"PERSONAL DE LOS SERVICIOS DE PROTECCIÓN"},"subgrupo":{"codigo":"541","nombre":"Personal de los servicios de protección"},"grupo_primario":{"codigo":"5419","nombre":"Personal de los servicios de protección no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Diligenciar y entregar al presunto infractor la orden de comparendo y autorizar la inmovilización de vehículos automotores o no automotores cuando haya lugar."},{"consecutivo":2,"texto":"Ejercer regulación de la movilidad vial, el control y la vigilancia en el cumplimiento de las normas de tránsito, transporte, ambiental y calidad del aire, por parte de los actores viales."},{"consecutivo":3,"texto":"Orientar a los actores viales en hábitos, conductas y comportamientos seguros en la vía."},{"consecutivo":4,"texto":"Realizar los procedimientos de policía judicial en accidentes de tránsito que puedan incurrir infracción penal."},{"consecutivo":5,"texto":"Redactar y remitir informes de accidentes de tránsito y demás que le sean solicitados y que competan a su labor de servicio."},{"consecutivo":6,"texto":"Autorizar la inmovilización de vehículos automotores o no automotores."},{"consecutivo":7,"texto":"Promover la conciliación entre los actores viales conforme a la gravedad (sólo daños)."},{"consecutivo":8,"texto":"Vigilar el cumplimiento del código de ética y las disposiciones existentes en materia disciplinaria, sobre derechos, deberes, prohibiciones, inhabilidades, incompatibilidades y conflicto de intereses."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"54192.001","nombre":"Agente de tránsito"},{"codigo":"54192.002","nombre":"Guarda de tránsito"},{"codigo":"54192.003","nombre":"Guardián de tráfico / Guardiana de tráfico"},{"codigo":"54192.004","nombre":"Patrullero de tránsito / Patrullera de tránsito"}],"conocimientos":[{"id":"12","nombre":"Construcción e ingeniería civil"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"38","nombre":"Mantenimiento"},{"id":"41","nombre":"Primeros auxilios"},{"id":"27","nombre":"Seguridad pública"},{"id":"31","nombre":"Servicios de transporte"},{"id":"92","nombre":"Tecnologías de protección y gestión del medio ambiente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"13","nombre":"Conciliación"},{"id":"33","nombre":"Liderazgo"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"3","nombre":"Redacción de textos"},{"id":"10","nombre":"Relaciones interpersonales"}],"ocupaciones_afines":[{"codigo":"33551","nombre":"Inspectores y detectives de policía / Inspectoras y detectives de policía"},{"codigo":"54193","nombre":"Técnicos operativos de tránsito / Técnicas operativas de tránsito"}],"area_principal":{"sigla":"SEGU","nombre":"Seguridad"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"3359*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"6381*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"5419*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"","cno_obs":""}]}'::jsonb),
  ('rol_cuoc', 'Técnicos operativos de tránsito / Técnicas operativas de tránsito', '54193', 'Seguridad', 2, false, '{"codigo":"54193","nombre":"Técnicos operativos de tránsito / Técnicas operativas de tránsito","descripcion":"Coordinan las políticas y estrategias diseñadas por el organismo de tránsito, para mejorar la movilidad, el control, la prevención, el seguimiento de personal operativo, la educación, la atención de hechos de accidentalidad y seguridad vial en el tránsito de la jurisdicción. Se pueden desempeñar en los organismos de tránsito, organismos de apoyo al tránsito, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"54","nombre":"PERSONAL DE LOS SERVICIOS DE PROTECCIÓN"},"subgrupo":{"codigo":"541","nombre":"Personal de los servicios de protección"},"grupo_primario":{"codigo":"5419","nombre":"Personal de los servicios de protección no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Coordinar acciones de cumplimiento de planes y programas misionales trazados por el organismo de tránsito."},{"consecutivo":2,"texto":"Coordinar la atención inmediata de accidentes de tránsito, emergencias y eventos que obstaculicen la libre circulación vial."},{"consecutivo":3,"texto":"Verificar cumplimiento de programación de actividades y de servicios asignados al personal operativo."},{"consecutivo":4,"texto":"Verificar el estado de funcionamiento de los equipos de trabajo."},{"consecutivo":5,"texto":"Vigilar el cumplimiento de las normas de tránsito y del transporte por parte de los actores viales."},{"consecutivo":6,"texto":"Establecer, coordinar e implementar con diferentes actores de otras entidades las jornadas de prevención y educación, los operativos de control de tránsito, de uso de las vías y del espacio público."},{"consecutivo":7,"texto":"Prestar asistencia técnica y emitir conceptos en los asuntos relacionados con el área y solicitados por los usuarios."},{"consecutivo":8,"texto":"Realizar los procedimientos de policía judicial en accidentes de tránsito que puedan incurrir infracción penal."},{"consecutivo":9,"texto":"Gestionar los informes policiales de accidentes de tránsito, comparendos e informes al transporte."},{"consecutivo":10,"texto":"Tramitar y responder comunicados, derechos de petición, oficios y reclamos de su área."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"54193.001","nombre":"Supervisor de tránsito / Supervisora de tránsito"},{"codigo":"54193.002","nombre":"Técnico de tránsito / Técnica de tránsito"},{"codigo":"54193.003","nombre":"Técnico operativo de tránsito / Técnica operativa de tránsito"}],"conocimientos":[{"id":"12","nombre":"Construcción e ingeniería civil"},{"id":"28","nombre":"Leyes y gobierno"},{"id":"38","nombre":"Mantenimiento"},{"id":"41","nombre":"Primeros auxilios"},{"id":"27","nombre":"Seguridad pública"},{"id":"31","nombre":"Servicios de transporte"},{"id":"92","nombre":"Tecnologías de protección y gestión del medio ambiente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"13","nombre":"Conciliación"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"33","nombre":"Liderazgo"},{"id":"25","nombre":"Manejo de imprevistos"}],"ocupaciones_afines":[{"codigo":"33551","nombre":"Inspectores y detectives de policía / Inspectoras y detectives de policía"},{"codigo":"54192","nombre":"Agentes de tránsito"}],"area_principal":{"sigla":"SEGU","nombre":"Seguridad"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"5419*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"6382","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Personal de los servicios de protección no clasificadas en otras ocupaciones', '54199', 'Seguridad', 2, false, '{"codigo":"54199","nombre":"Personal de los servicios de protección no clasificadas en otras ocupaciones","descripcion":"Esta ocupación abarca al personal de los servicios de protección no clasificadas en otras ocupaciones en el Grupo Primario 5419: Personal de los servicios de protección no clasificados en otros grupos primarios. Por ejemplo, incluye aquellos que prestan servicios de protección como patrullar y realizar acciones para la prevención de accidentes, riesgos y agentes de control de animales, así como tareas de monitoreo no técnico, prevención, respuesta y rehabilitación en articulación con entidades del Sistema Nacional de Gestión del Riesgo. Se pueden desempeñar en reservas naturales, bosques, parques, jardines públicos, playas, entidades públicas, privadas y organizaciones comunitarias, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"5","nombre":"TRABAJADORES DE LOS SERVICIOS Y VENDEDORES DE COMERCIOS Y MERCADOS"},"subgrupo_principal":{"codigo":"54","nombre":"PERSONAL DE LOS SERVICIOS DE PROTECCIÓN"},"subgrupo":{"codigo":"541","nombre":"Personal de los servicios de protección"},"grupo_primario":{"codigo":"5419","nombre":"Personal de los servicios de protección no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Patrullar reservas naturales, bosques, parques y jardines públicos velando por su protección y la seguridad de los visitantes."},{"consecutivo":2,"texto":"Patrullar las playas y piscinas para prevenir accidentes y rescatar a bañistas en riesgo de ahogo."},{"consecutivo":3,"texto":"Responder a las quejas del ciudadano con respecto a los animales domésticos, ganado y vida silvestre en la vía pública, emitir advertencias y citaciones a propietarios y confiscar animales."},{"consecutivo":4,"texto":"Reportar a las autoridades sobre accidentes, señales equivocadas, peligros de navegación y otras emergencias."},{"consecutivo":5,"texto":"Monitorear actividades recreacionales o deportivas para garantizar seguridad o atender las emergencias en caso necesario."},{"consecutivo":6,"texto":"Apoyar la caracterización de escenarios de riesgo de desastres mediante el diligenciamiento de herramientas técnicas y la recolección de información en campo."},{"consecutivo":7,"texto":"Participar en actividades de sensibilización, educación y preparación comunitaria frente a riesgos de desastres, incluyendo la logística de jornadas informativas y simulacros."},{"consecutivo":8,"texto":"Apoyar el diseño, implementación y seguimiento de planes y estrategias de gestión del riesgo de desastres, acción social y gestión ambiental en los territorios."},{"consecutivo":9,"texto":"Apoyar actividades administrativas y operativas de los consejos municipales y departamentales de gestión del riesgo de desastres, en articulación con las entidades del sistema."},{"consecutivo":10,"texto":"Colaborar en la ejecución de la respuesta a incidentes, emergencias y desastres, particularmente en tareas relacionadas con servicios básicos, seguridad humana y restauración temprana."},{"consecutivo":11,"texto":"Apoyar la formulación y puesta en marcha de planes de recuperación, rehabilitación, restauración o reconstrucción en contextos afectados por emergencias o desastres."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"54199.001","nombre":"Auxiliar de servicios contra incendios"},{"codigo":"54199.002","nombre":"Bombero de protección civil / Bombera de protección civil"},{"codigo":"54199.003","nombre":"Brigadista"},{"codigo":"54199.004","nombre":"Especialista en salvamento de incendios"},{"codigo":"54199.005","nombre":"Guarda de caza y pesca"},{"codigo":"54199.006","nombre":"Guarda forestal de vida silvestre"},{"codigo":"54199.007","nombre":"Guardabosque de parque para protección del medio ambiente"},{"codigo":"54199.008","nombre":"Guardabosques"},{"codigo":"54199.009","nombre":"Guardacostas"},{"codigo":"54199.010","nombre":"Guardia de cruce"},{"codigo":"54199.011","nombre":"Guardia de playa"},{"codigo":"54199.012","nombre":"Guardián de juego / Guardiana de juego"},{"codigo":"54199.013","nombre":"Guardián de parques y jardines públicos / Guardiana de parques y jardines públicos"},{"codigo":"54199.014","nombre":"Guardián de reserva natural / Guardiana de reserva natural"},{"codigo":"54199.015","nombre":"Guardián de santuario de aves / Guardiana de santuario de aves"},{"codigo":"54199.016","nombre":"Patrullero de playa / Patrullera de playa"},{"codigo":"54199.017","nombre":"Auxiliar de gestión de riesgo de desastres"},{"codigo":"54199.018","nombre":"Auxiliar de gestión del riesgo de emergencias y desastres"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"20","nombre":"Geografía y territorio"},{"id":"45","nombre":"Gestión del riesgo de desastres"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"78","nombre":"Medio ambiente natural y vida silvestre"},{"id":"41","nombre":"Primeros auxilios"},{"id":"27","nombre":"Seguridad pública"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"15","nombre":"Orientación al servicio"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"34","nombre":"Trabajo bajo presión"},{"id":"11","nombre":"Trabajo en equipo"},{"id":"23","nombre":"Vigilancia de las operaciones"}],"ocupaciones_afines":[{"codigo":"21331","nombre":"Profesionales ambientales y ecologistas"},{"codigo":"32573","nombre":"Técnicos en prevención, gestión y control ambiental / Técnicas en prevención, gestión y control ambiental"},{"codigo":"54112","nombre":"Suboficiales de bomberos"},{"codigo":"54142","nombre":"Vigilantes, guardas y personal operativo de seguridad privada"},{"codigo":"54191","nombre":"Guardavidas y salvavidas"}],"area_principal":{"sigla":"SEGU","nombre":"Seguridad"},"areas_complementarias":[{"sigla":"CPS