  ('rol_cuoc', 'Agricultores de cultivos extensivos / Agricultoras de cultivos extensivos', '61111', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 3, false, '{"codigo":"61111","nombre":"Agricultores de cultivos extensivos / Agricultoras de cultivos extensivos","descripcion":"Llevan a cabo actividades necesarias para el cultivo extensivo y la cosecha de diversos productos agrícolas, como cereales, hortalizas, tubérculos, frutales, verduras y otros productos agrícolas como tabaco, caña de azúcar, para la venta en mercados o la entrega a compradores u organismos de comercialización. Se pueden desempeñar en fincas, parcelas, granjas, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"6","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS AGROPECUARIOS, FORESTALES Y PESQUEROS"},"subgrupo_principal":{"codigo":"61","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS DE EXPLOTACIONES AGROPECUARIAS CON DESTINO AL MERCADO"},"subgrupo":{"codigo":"611","nombre":"Agricultores y trabajadores calificados de jardines y de cultivos para el mercado"},"grupo_primario":{"codigo":"6111","nombre":"Agricultores y trabajadores calificados de cultivos extensivos"}},"funciones":[{"consecutivo":1,"texto":"Realizar seguimiento de las actividades y condiciones del mercado, planificar, determinar, coordinar y dirigir las faenas, según variedades y cantidades de cultivo a producir."},{"consecutivo":2,"texto":"Contratar, despedir, capacitar y supervisar trabajadores en mantenimiento y producción agrícola."},{"consecutivo":3,"texto":"Adquirir máquinas y suministros para granja, semillas, otras provisiones y mantener inventarios."},{"consecutivo":4,"texto":"Promover, mercadear, comercializar y llevar registros de transacciones, actividades agrícolas y organizar el transporte de productos y suministros."},{"consecutivo":5,"texto":"Llevar registros de producción y aprovechamiento en faenas agrícolas, fincas, granjas, entre otros."},{"consecutivo":6,"texto":"Establec