  ('rol_cuoc', 'Trabajadores agrícolas calificados de cultivos extensivos / Trabajadoras agrícolas calificadas de cultivos extensivos', '61112', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 2, false, '{"codigo":"61112","nombre":"Trabajadores agrícolas calificados de cultivos extensivos / Trabajadoras agrícolas calificadas de cultivos extensivos","descripcion":"Llevan a cabo actividades operativas necesarias para el cultivo extensivo; preparan terrenos, plantan, cultivan y recogen cosechas; del mismo modo, apoyan otras labores relacionadas con la producción como operar y mantener herramientas y equipos agrícolas. Se pueden desempeñar en empresas de aprovechamiento agrícola, plantaciones, haciendas, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"6","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS AGROPECUARIOS, FORESTALES Y PESQUEROS"},"subgrupo_principal":{"codigo":"61","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS DE EXPLOTACIONES AGROPECUARIAS CON DESTINO AL MERCADO"},"subgrupo":{"codigo":"611","nombre":"Agricultores y trabajadores calificados de jardines y de cultivos para el mercado"},"grupo_primario":{"codigo":"6111","nombre":"Agricultores y trabajadores calificados de cultivos extensivos"}},"funciones":[{"consecutivo":1,"texto":"Preparar suelos y fertilizar aplicando métodos foliares, radiculares, en corona u otros de acuerdo con requerimientos específicos del cultivo y recoger cosechas de forma manual o con máquina."},{"consecutivo":2,"texto":"Detectar y controlar plagas, enfermedades en cultivos y erradicarlas bajo el control de expertos con la aplicación de herbicidas y pesticidas."},{"consecutivo":3,"texto":"Mantener cultivos mediante actividades de labranza, trasplante, poda, raleo o aclarado de plantas de aprovechamiento agrícola."},{"consecutivo":4,"texto":"Realizar labores postcosecha como inspeccionar, clasificar, seleccionar, manipular, realizar cierto grado de elaboración primaria, almacenar y empacar productos agrícolas para la venta o entrega a mercado."},{"consecutivo":5,"texto":"Cumplir y mantener normas de salud y seguridad ocupacional que se han de adoptar en medios de aprovechamiento agrícola."},{"consecutivo":6,"texto":"Llevar registros de control, aspectos fitosanitarios y prácticas culturales en medios de aprovechamiento agrícola."},{"consecutivo":7,"texto":"Operar y mantener equipos en el aprovechamiento agrícola."},{"consecutivo":8,"texto":"Operar y mantener equipo de fumigación y velar por el mantenimiento fitosanitario del cultivo."},{"consecutivo":9,"texto":"Mantener equipos, herramientas e instalaciones como bodegas, graneros, secadores, sistemas de abastecimiento de agua, entre otros."},{"consecutivo":10,"texto":"Seleccionar, sembrar semillas, plántulas y plantones para aprovechamiento agrícolas de acuerdo con especificaciones técnicas."},{"consecutivo":11,"texto":"Almacenar productos y proceder a cierto grado de procesamiento y elaboración primaria de los mismos."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"61112.001","nombre":"Censador de enfermedades / Censadora de enfermedades"},{"codigo":"61112.002","nombre":"Censador de plagas / Censadora de plagas"},{"codigo":"61112.003","nombre":"Censador de plagas y enfermedades / Censadora de plagas y enfermedades"},{"codigo":"61112.004","nombre":"Evaluador de fruto / Evaluadora de fruto"},{"codigo":"61112.005","nombre":"Evaluador de plagas / Evaluadora de plagas"},{"codigo":"61112.006","nombre":"Evaluador de plagas y enfermedades / Evaluadora de plagas y enfermedades"},{"codigo":"61112.007","nombre":"Operario agrícola de cultivos extensivos / Operaria agrícola de cultivos extensivos"},{"codigo":"61112.008","nombre":"Operario agrícola de cultivos intensivos / Operaria agrícola de cultivos intensivos"},{"codigo":"61112.009","nombre":"Operario especializado en agropecuaria orgánica / Operaria especializada en agropecuaria orgánica"},{"codigo":"61112.010","nomb