  ('rol_cuoc', 'Agricultores de plantaciones de árboles y arbustos / Agricultoras de plantaciones de árboles y arbustos', '61121', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 3, false, '{"codigo":"61121","nombre":"Agricultores de plantaciones de árboles y arbustos / Agricultoras de plantaciones de árboles y arbustos","descripcion":"Planean, organizan, dirigen y controlan actividades para plantar y cosechar árboles y arbustos tales como: árboles frutales y nogales, plantas de té y arbustos de café, palma africana, viñedos, arbustos de bayas, árboles de cacao y caucho (de los que pueden recolectar la savia), con la finalidad de venderlos en mercados o entregarlos a compradores u organismos de comercialización. Se pueden desempeñar en empresas forestales, fincas o de forma independiente, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"6","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS AGROPECUARIOS, FORESTALES Y PESQUEROS"},"subgrupo_principal":{"codigo":"61","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS DE EXPLOTACIONES AGROPECUARIAS CON DESTINO AL MERCADO"},"subgrupo":{"codigo":"611","nombre":"Agricultores y trabajadores calificados de jardines y de cultivos para el mercado"},"grupo_primario":{"codigo":"6112","nombre":"Agricultores y trabajadores calificados de plantaciones de árboles y arbustos"}},"funciones":[{"consecutivo":1,"texto":"Dirigir actividades, llevar registros de aprovechamiento, planificar, determinar y coordinar las variedades y cantidades de cultivos que se han de producir de acuerdo con condiciones del mercado."},{"consecutivo":2,"texto":"Promover, comercializar y organizar la compra, la venta y el transporte de productos de plantaciones de árboles y arbustos, y evaluar registros de las diversas actividades y las transacciones de árboles y arbustos."},{"consecutivo":3,"texto":"Contratar, despedir, capacitar y coordinar trabajadores y colaboradores externos de la producción de plantaciones de árboles y arbustos, relacionados con funciones, mantenimiento y precauciones que se han de adoptar en materia de salud y seguridad."},{"consecutivo":4,"texto":"Adquirir máquinas, comprar suministros, insumos, materiales, semillas, plántulas, plantones y mantener inventarios para plantaciones de árboles y arbustos."},{"consecutivo":5,"texto":"Determinar las condiciones ambientales y demás factores requeridos para el cultivo de árboles, arbustos y plantas."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"61121.001","nombre":"Agricultor de arboles y arbustos / Agricultora de arboles y arbustos"},{"codigo":"61121.002","nombre":"Agricultor de cultivo de aguacate / Agricultora de cultivo de aguacate"},{"codigo":"61121.003","nombre":"Agricultor de cultivo de banano / Agricultora de cultivo de banano"},{"codigo":"61121.004","nombre":"Agricultor de cultivo de cacao / Agricultora de cultivo de cacao"},{"codigo":"61121.005","nombre":"Agricultor de cultivo de café / Agricultora de cultivo de café"},{"codigo":"61121.006","nombre":"Agricultor de cultivo de caucho / Agricultora de cultivo de caucho"},{"codigo":"61121.007","nombre":"Agricultor de cultivo de coco / Agricultora de cultivo de coco"},{"codigo":"61121.008","nombre":"Agricultor de cultivo de durazno / Agricultora de cultivo de durazno"},{"codigo":"61121.009","nombre":"Agricultor de cultivo de frutales / Agricultora de cultivo de frutales"},{"codigo":"61121.010","nombre":"Agricultor de cultivo de limón / Agricultora de cultivo de limón"},{"codigo":"61121.011","nombre":"Agricultor de cultivo de mandarina / Agricultora de cultivo de mandarina"},{"codigo":"61121.012","nombre":"Agricultor de cultivo de mango / Agricultora de cultivo de mango"},{"codigo":"61121.013","nombre":"Agricultor de cultivo de naranja / Agricultora de cultivo de naranja"},{"codigo":"61121.014","nombre":"Agricultor de cultivo de palma africana / Agricultora de cultivo de palma africana"},{"codigo":"61121.015","nombre":"Ag