  ('rol_cuoc', 'Agricultores de huertas, invernaderos, viveros y jardines / Agricultoras de huertas, invernaderos, viveros y jardines', '61131', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 3, false, '{"codigo":"61131","nombre":"Agricultores de huertas, invernaderos, viveros y jardines / Agricultoras de huertas, invernaderos, viveros y jardines","descripcion":"Planean, organizan, dirigen y controlan actividades de trabajadores y producción en huertas, invernaderos, viveros y jardines, con la finalidad de vender en mercados o entregar los productos a organismos de comercialización. Se pueden desempeñar en huertas, invernaderos, viveros, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"6","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS AGROPECUARIOS, FORESTALES Y PESQUEROS"},"subgrupo_principal":{"codigo":"61","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS DE EXPLOTACIONES AGROPECUARIAS CON DESTINO AL MERCADO"},"subgrupo":{"codigo":"611","nombre":"Agricultores y trabajadores calificados de jardines y de cultivos para el mercado"},"grupo_primario":{"codigo":"6113","nombre":"Agricultores y trabajadores calificados de huertas, invernaderos, viveros y jardines"}},"funciones":[{"consecutivo":1,"texto":"Planear, organizar, dirigir y controlar todas las operaciones de plantación, mantenimiento y construcción en huertas, invernaderos, viveros y jardines interiores o exteriores."},{"consecutivo":2,"texto":"Efectuar el seguimiento de actividades y condiciones del mercado para determinar las variedades y cantidades de productos de huertas, invernaderos, viveros y jardines deben ser producidos."},{"consecutivo":3,"texto":"Contratar, despedir, capacitar y supervisar a trabajadores y personal externo en programas de trabajo, actividades de producción, mantenimiento y recomendaciones de salud y seguridad en huertas, invernaderos, viveros y jardines."},{"consecutivo":4,"texto":"Promover y comercializar productos, organizar la compra, la venta y el transporte de la producción de huertas, invernaderos, viveros y jardines."},{"consecutivo":5,"texto":"Determinar las condiciones ambientales requeridas para definir la cantidad y las clases de cultivo a producir en huertas, invernaderos, viveros y jardines."},{"consecutivo":6,"texto":"Adquirir máquinas, comprar suministros y mantener inventarios en huertas, invernaderos, viveros y jardines."},{"consecutivo":7,"texto":"Llevar registros de actividades y transacciones de producción en huertas, invernaderos, viveros y jardines."},{"consecutivo":8,"texto":"Elaborar propuestas de contratación para el mantenimiento de prados y jardines."},{"consecutivo":9,"texto":"Suministrar información a clientes sobre el cuidado de flores, plantas y prados cultivados en huertas, invernaderos, viveros y jardines."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"61131.001","nombre":"Agricultor de cultivo de césped, grama o pasto / Agricultora de cultivo de césped, grama o pasto"},{"codigo":"61131.002","nombre":"Agricultor de cultivo de flor de corte / Agricultora de cultivo de flor de corte"},{"codigo":"61131.003","nombre":"Agricultor de cultivo de flores / Agricultora de cultivo de flores"},{"codigo":"61131.004","nombre":"Agricultor de cultivo de hongos / Agricultora de cultivo de hongos"},{"codigo":"61131.005","nombre":"Agricultor de cultivo de plantas medicinales y especias / Agricultora de cultivo de plantas medicinales y especias"},{"codigo":"61131.006","nombre":"Agricultor de cultivo hidropónicos / Agricultora de cultivo hidropónicos"},{"codigo":"61131.007","nombre":"Agricultor de viveros ornamentales / Agricultora de viveros ornamentales"},{"codigo":"61131.008","nombre":"Cultivador de flores / Cultivadora de flores"},{"codigo":"61131.009","nombre":"Cultivador de hongos / Cultivadora de hongos"},{"codigo":"61131.010","nombre":"Cultivador de hortalizas de invernadero / Cultivadora de hortalizas de invernadero"},{"codigo":"61131.011","nombre":"Cultivador de pastos / Cultivadora de pastos"},{"codigo":"61131.012","nombre":"Cultivador de semillas / Cultivadora de semillas"},{"codigo":"61131.013","nombre":"Cultivador de setas y champiñones / Cultivadora de setas y champiñones"},{"codigo":"61131.014","nombre":"Cultivador de viveros / Cultivadora de viveros"},{"codigo":"61131.015","nombre":"Floricultor / Floricultora"},{"codigo":"61131.016","nombre":"Hortelano / Hortelana"},{"codigo":"61131.017","nombre":"Horticultor / Horticultora"},{"codigo":"61131.018","nombre":"Horticultor de vivero / Horticultora de vivero"},{"codigo":"61131.019","nombre":"Promotor de mantenimiento prados y jardines / Promotora de mantenimiento prados y jardines"},{"codigo":"61131.020","nombre":"Viverista"},{"codigo":"61131.021","nombre":"Viverista forestal"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"6","nombre":"Gestión del talento humano y de personal"},{"id":"72","nombre":"Horticultura (técnicas de huertas, invernaderos, viveros y jardines)"},{"id":"85","nombre":"Seguridad y salud en el trabajo"},{"id":"5","nombre":"Servicio al cliente"},{"id":"92","nombre":"Tecnologías de protección y gestión del medio ambiente"}],"destrezas":[{"id":"17","nombre":"Análisis de necesidades"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"31421","nombre":"Técnicos agropecuarios / Técnicas agropecuarias"},{"codigo":"31424","nombre":"Supervisores de producción agrícola / Supervisoras de producción agrícola"},{"codigo":"61111","nombre":"Agricultores de cultivos extensivos / Agricultoras de cultivos extensivos"},{"codigo":"61121","nombre":"Agricultores de plantaciones de árboles y arbustos / Agricultoras de plantaciones de árboles y arbustos"},{"codigo":"61132","nom