  ('rol_cuoc', 'Trabajadores agrícolas calificados de huertas, invernaderos, viveros y jardines / Trabajadoras agrícolas calificadas de huertas, invernaderos, viveros y jardines', '61132', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 2, false, '{"codigo":"61132","nombre":"Trabajadores agrícolas calificados de huertas, invernaderos, viveros y jardines / Trabajadoras agrícolas calificadas de huertas, invernaderos, viveros y jardines","descripcion":"Preparan terrenos, plantan, cultivan cosechan, operan, mantienen equipos, herramientas e instalaciones y realizan una variedad de labores manuales a flores y plantas ornamentales en parques, invernaderos, viveros y jardines. Se pueden desempeñar en parques, invernaderos, viveros, huertas, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"6","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS AGROPECUARIOS, FORESTALES Y PESQUEROS"},"subgrupo_principal":{"codigo":"61","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS DE EXPLOTACIONES AGROPECUARIAS CON DESTINO AL MERCADO"},"subgrupo":{"codigo":"611","nombre":"Agricultores y trabajadores calificados de jardines y de cultivos para el mercado"},"grupo_primario":{"codigo":"6113","nombre":"Agricultores y trabajadores calificados de huertas, invernaderos, viveros y jardines"}},"funciones":[{"consecutivo":1,"texto":"Preparar suelos, nivelar terrenos, acondicionar y operar equipos, herramientas y sistemas en huertas, invernaderos, viveros y jardines."},{"consecutivo":2,"texto":"Plantar y sembrar prados, flores, plantas de jardín, árboles y arbustos en huertas, invernaderos, viveros y jardines."},{"consecutivo":3,"texto":"Operar equipo de fumigación y velar por el mantenimiento fitosanitario en el control de enfermedades y plagas bajo el control de expertos en huertas, invernaderos, viveros y jardines."},{"consecutivo":4,"texto":"Operar equipos y herramientas para cortar césped y podar plantas, árboles, arbustos y setos en huertas, invernaderos, viveros y jardines."},{"consecutivo":5,"texto":"Realizar labores de mantenimiento como retirar malezas, aporcar, deschuponar, entresacar, castrar, escarificar, segar, airear, bordear el césped e instalar soportes y protecciones a plantas, prados, árboles, arbustos y flores en huertas, invernaderos, viveros y jardines."},{"consecutivo":6,"texto":"Producir plántulas, plantones, esquejes, bulbos, semillas, retoños, injertos y capullos aplicando diferentes métodos de propagación."},{"consecutivo":7,"texto":"Construir y mantener estructuras, instalaciones, equipamientos, sistemas de abastecimiento, áreas pavimentadas, senderos, muros, cobertizos, cercas y vallas en huertas, invernaderos, viveros y jardines."},{"consecutivo":8,"texto":"Realizar labores postcosecha como limpiar, clasificar, seleccionar, manipular, envasar, y empacar productos de huertas, invernaderos, viveros y jardines para la venta o entrega al mercado."},{"consecutivo":9,"texto":"Almacenar productos de huertas, invernaderos, viveros y jardines y realizar algún tipo de procesamiento o elaboración primaria de los mismos."},{"consecutivo":10,"texto":"Operar, mantener y cuidar semilleros, equipos y herramientas en huertas, invernaderos, viveros y jardines."},{"consecutivo":11,"texto":"Operar sistemas de riego, estanques, drenajes y fuentes de agua para irrigar cultivos en huertas, invernaderos, viveros y jardines."},{"consecutivo":12,"texto":"Controlar la salud de cultivos y fertilizar aplicando métodos foliares, radiculares, en corona u otros de acuerdo con requerimientos específicos en huertas, invernaderos, viveros y jardines."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"61132.001","nombre":"Injertador / Injertadora"},{"codigo":"61132.002","nombre":"Jardinero / Jardinera"},{"codigo":"61132.003","nombre":"Jardinero de campos atléticos / Jardinera de campos atléticos"},{"codigo":"61132.004","nombre":"Jardinero de campos de golf / Jardinera de campos de golf"},{"