  ('rol_cuoc', 'Agricultores y trabajadores calificados de cultivos mixtos / Agricultoras y trabajadoras calificadas de cultivos mixtos', '61140', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 3, false, '{"codigo":"61140","nombre":"Agricultores y trabajadores calificados de cultivos mixtos / Agricultoras y trabajadoras calificadas de cultivos mixtos","descripcion":"Planifican, organizan y llevan a cabo actividades de operación y mantenimiento de herramientas y equipos agrícolas, igualmente, preparan terrenos, plantan, cultivan y recogen cosechas de cultivos mixtos para la venta en mercados o entrega a compradores u organismos de comercialización. Se pueden desempeñar en empresas de explotación agrícola como plantaciones, haciendas, invernaderos, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"6","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS AGROPECUARIOS, FORESTALES Y PESQUEROS"},"subgrupo_principal":{"codigo":"61","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS DE EXPLOTACIONES AGROPECUARIAS CON DESTINO AL MERCADO"},"subgrupo":{"codigo":"611","nombre":"Agricultores y trabajadores calificados de jardines y de cultivos para el mercado"},"grupo_primario":{"codigo":"6114","nombre":"Agricultores y trabajadores calificados de cultivos mixtos"}},"funciones":[{"consecutivo":1,"texto":"Preparar suelos, sembrar semillas y plantar plántulas, plantones, bulbos, flores y hortalizas en cultivos mixtos aplicando diferentes técnicas manuales o con máquinas."},{"consecutivo":2,"texto":"Operar y mantener equipos, herramientas, edificaciones, estructuras, equipamientos y sistemas de abastecimiento de cultivos mixtos."},{"consecutivo":3,"texto":"Mantener cultivos mixtos mediante el retiro de malezas, aporcamiento, actividades de labranza, trasplante, poda o aclarado."},{"consecutivo":4,"texto":"Realizar labores de postcosecha como almacenar, inspeccionar, limpiar, clasificar, envasar, cargar y llevar a cabo algún tipo de procesamiento de productos cosechados para la venta o entrega al mercado."},{"consecutivo":5,"texto":"Detectar y erradicar plagas y enfermedades de forma manual u operando equipos de fumigación para velar por el mantenimiento fitosanitario de los cultivos mixtos bajo el control de expertos."},{"consecutivo":6,"texto":"Realizar y evaluar registros de actividades, transacciones, variedades y cantidades de cultivos mixtos según condiciones del mercado, producción, aspectos fitosanitarios y prácticas culturales."},{"consecutivo":7,"texto":"Operar e instalar sistemas de riego para irrigar cultivos mixtos de acuerdo con condiciones técnicas y prácticas culturales del cultivo."},{"consecutivo":8,"texto":"Fertilizar aplicando métodos foliares, radiculares, en corona, abonos u otros de acuerdo con requerimientos específicos y prácticas culturales de los cultivos mixtos."},{"consecutivo":9,"texto":"Promover y comercializar productos, organizar la compra, la venta y el transporte de artículos y suministros para cultivos mixtos."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"61140.001","nombre":"Agricultor de cultivos mixtos para el mercado / Agricultora de cultivos mixtos para el mercado"},{"codigo":"61140.002","nombre":"Implementador de producción agro-ecológica / Implementadora de producción agro-ecológica"},{"codigo":"61140.003","nombre":"Monitor MIPE (manejo integrado de plagas y enfermedades) / Monitora MIPE (manejo integrado de plagas y enfermedades)"},{"codigo":"61140.004","nombre":"Trabajador agrícola de cultivos mixtos / Trabajadora agrícola de cultivos mixtos"},{"codigo":"61140.005","nombre":"Trabajador agrícola de policultivos / Trabajadora agrícola de policultivos"},{"codigo":"61140.006","nombre":"Implementador de procesos agroecológicos / Implementadora de procesos agroecológicos"}],"conocimientos":[{"id":"72","nombre":"Horticultura (técnicas de huertas, invernaderos, viveros y jardines)"},{"id":"98","nombre":"Producción agrícola y pecuaria"},{"id":"5","nombre":"Servicio al cliente"},{"id":"92","nombre":"Tecnologías de protección y gestión del medio ambiente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"61111","nombre":"Agricultores de cultivos extensivos / Agricultoras de cultivos extensivos"},{"codigo":"61112","nombre":"Trabajadores agrícolas calificados de cultivos extensivos / Trabajadoras agrícolas calificadas de cultivos extensivos"},{"codigo":"61113","nombre":"Trabajadores calificados de riego agrícola / Trabajadoras calificadas de riego agrícola"},{"codigo":"61121","nombre":"Agricultores de plantaciones de árboles y arbustos / Agricultoras de plantaciones de árboles y arbustos"},{"codigo":"61122","nombre":"Trabajadores agrícolas calificados de plantaciones de árboles y arbustos / Trabajadoras agrícolas calificadas de plantaciones de árboles y arbustos"},{"codigo":"61131","nombre":"Agricultores de huertas, invernaderos, viveros y jardines / Agricultoras de huertas, invernaderos, viveros y jardines"},{"codigo":"61132","nombre":"Trabajadores agrícolas calificados de huertas, invernaderos, viveros y jardines / Trabajadoras agrícolas calificadas de huertas, invernaderos, viveros y jardines"},{"codigo":"92110","nombre":"Obreros y peones de explotaciones agrícolas / Obreras y peonas de explotaciones agrícolas"},{"codigo":"92130","nombre":"Obreros y peones de explotaciones agropecuarias / Obreras y peonas de explotaciones agropecuarias"},{"codigo":"92150","nombre":"Obreros y peones forestales y de silvicultura / Obreras y peonas forestales y de silvicultura"}],"area_principal":{"sigla":"AGVE","nombre":"Agropecuario, silvicultura, pesca, acuicultura y veterinaria"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"6114*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"7221*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"7331*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Criadores de animales (excepto aves de corral) / Criadoras de animales (excepto aves de corral)', '61211', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 3, false, '{"codigo":"61211","nombre":"Criadores de animales (excepto aves de corral) / Criadoras de animales (excepto aves de corral)","descripcion":"Planifican, organizan y administran operaciones y faenas en hatos ganaderos, pesebreras y granjas de cría, levante, engorde y reproducción de animales (con excepción de aves de corral), como ganado vacuno, ovino, porcino, caprino y equino, con el fin de obtener carne, leche, productos lácteos, pieles y lana para venderlos en mercados o entregarlos a compradores u organismos de comercialización. Se pueden desempeñar en hatos ganaderos, pesebreras, fincas, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"6","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS AGROPECUARIOS, FORESTALES Y PESQUEROS"},"subgrupo_principal":{"codigo":"61","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS DE EXPLOTACIONES AGROPECUARIAS CON DESTINO AL MERCADO"},"subgrupo":{"codigo":"612","nombre":"Criadores y trabajadores pecuarios calificados de la cría de animales orientados al mercado"},"grupo_primario":{"codigo":"6121","nombre":"Criadores de ganado y trabajadores de la cría de animales domésticos (excepto aves de corral)"}},"funciones":[{"consecutivo":1,"texto":"Llevar registros y efectuar seguimiento de actividades, variedades y cantidades de animales a criar, levantar o producir de acuerdo con condiciones del mercado."},{"consecutivo":2,"texto":"Dirigir y efectuar seguimiento de animales para detectar enfermedades, lesiones o dolencias y observar indicadores de su condición física y nutricional."},{"consecutivo":3,"texto":"Promover y organizar la compra, venta, transporte y evaluar registros de transacciones de la cría y levante de animales."},{"consecutivo":4,"texto":"Comprar o adquirir máquinas, suministros y mantener inventarios para hatos, pesebreras, granjas y demás criaderos de animales."},{"consecutivo":5,"texto":"Contratar, despedir, capacitar, supervisar a trabajadores y colaboradores con respecto a procedimientos de cuidado de animales, tareas de mantenimiento y precauciones que se han de adoptar en materia de salud y seguridad en hatos, pesebreras, granjas y demás criaderos de animales."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"61211.001","nombre":"Criador de animales domésticos / Criadora de animales domésticos"},{"codigo":"61211.002","nombre":"Criador de caballos / Criadora de caballos"},{"codigo":"61211.003","nombre":"Criador de cabras / Criadora de cabras"},{"codigo":"61211.004","nombre":"Criador de ganado / Criadora de ganado"},{"codigo":"61211.005","nombre":"Criador de ganado bovino / Criadora de ganado bovino"},{"codigo":"61211.006","nombre":"Criador de ganado caballar / Criadora de ganado caballar"},{"codigo":"61211.007","nombre":"Criador de ganado caprino / Criadora de ganado caprino"},{"codigo":"61211.008","nombre":"Criador de ganado lechero / Criadora de ganado lechero"},{"codigo":"61211.009","nombre":"Criador de ganado ovino / Criadora de ganado ovino"},{"codigo":"61211.010","nombre":"Criador de ganado porcino / Criadora de ganado porcino"},{"codigo":"61211.011","nombre":"Criador de ganado vacuno / Criadora de ganado vacuno"},{"codigo":"61211.012","nombre":"Criador de ovejas / Criadora de ovejas"},{"codigo":"61211.013","nombre":"Criador de perros / Criadora de perros"},{"codigo":"61211.014","nombre":"Criador de especies mayores / Criadora de especies mayores"},{"codigo":"61211.015","nombre":"Criador de especies menores / Criadora de especies menores"},{"codigo":"61211.016","nombre":"Encargado de hato ganadero / Encargada de hato ganadero"},{"codigo":"61211.017","nombre":"Ganadero / Ganadera"},{"codigo":"61211.018","nombre":"Ganadero criador / Ganadera criadora"},{"codigo":"61211.019","nombre":"Mayordomo de hato ganadero / May