  ('rol_cuoc', 'Avicultores / Avicultoras', '61221', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 3, false, '{"codigo":"61221","nombre":"Avicultores / Avicultoras","descripcion":"Planifican, manejan y administran actividades de levante, engorde, reproducción y cría de pollos, gallinas, pavos, gansos, patos y otras aves de corral con el fin de obtener carne, huevos y polluelos para la venta en mercados o entrega a compradores y organismos de comercialización. Se pueden desempeñar en fincas, granjas, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"6","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS AGROPECUARIOS, FORESTALES Y PESQUEROS"},"subgrupo_principal":{"codigo":"61","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS DE EXPLOTACIONES AGROPECUARIAS CON DESTINO AL MERCADO"},"subgrupo":{"codigo":"612","nombre":"Criadores y trabajadores pecuarios calificados de la cría de animales orientados al mercado"},"grupo_primario":{"codigo":"6122","nombre":"Avicultores y trabajadores calificados de la avicultura"}},"funciones":[{"consecutivo":1,"texto":"Planear, coordinar, dirigir y determinar cantidades, clases de aves a criar o levantar, efectuar seguimiento, mantener y evaluar registros de actividades de explotación y condiciones del mercado."},{"consecutivo":2,"texto":"Comprar y adquirir, máquinas, suministros, equipamientos, edificaciones y estructuras para la explotación avícola, mantener inventarios y asegurar su mantenimiento."},{"consecutivo":3,"texto":"Organizar la venta y transporte de existencias de productos como cría de aves, huevos, carne, plumas, entre otros, en explotaciones avícolas."},{"consecutivo":4,"texto":"Coordinar, supervisar, capacitar, contratar y despedir a trabajadores y colaboradores, respecto a actividades de mantenimiento, precauciones que se han de adoptar en materia de salud y seguridad y procedimientos de producción avícola."},{"consecutivo":5,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"61221.001","nombre":"Avicultor / Avicultora"},{"codigo":"61221.002","nombre":"Criador de aves de corral / Criadora de aves de corral"},{"codigo":"61221.003","nombre":"Criador de gallos de pelea / Criadora de gallos de pelea"},{"codigo":"61221.004","nombre":"Granjero de aprovechamiento avícola / Granjera de aprovechamiento avícola"},{"codigo":"61221.005","nombre":"Granjero de aves de corral / Granjera de aves de corral"},{"codigo":"61221.006","nombre":"Granjero de avicultura / Granjera de avicultura"},{"codigo":"61221.007","nombre":"Granjero avícola / Granjera avícola"},{"codigo":"61221.008","nombre":"Granjero de producción avícola / Granjera de producción avícola"},{"codigo":"61221.009","nombre":"Productor de aves / Productora de aves"}],"conocimientos":[{"id":"1","nombre":"Gerencia y administración"},{"id":"4","nombre":"Mercadotecnia y publicidad"},{"id":"98","nombre":"Producción agrícola y pecuaria"},{"id":"7","nombre":"Producción y procesamiento"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"17","nombre":"Análisis de necesidades"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"13110","nombre":"Directores y gerentes de producción agropecuaria y silvicultura / Directoras y gerentas de producción agropecuaria y silvicultura"},{"codigo":"31425","nombre":"Supervisores de producción pecuaria / Supervisoras de producción pecuaria"}],"area_principal":{"sigla":"AGVE","nombre":"Agropecuario, silvicultura, pesca, acuicultura y veterinaria"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"6122*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"7231*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Trabajadores calificados de la avicultura / Trabajadoras calificadas de la avicultura', '61222', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 2, false, '{"codigo":"61222","nombre":"Trabajadores calificados de la avicultura / Trabajadoras calificadas de la avicultura","descripcion":"Realizan actividades requeridas para controlar y monitorear equipos, instrumentos y ambientes con condiciones especiales usados en la reproducción, la cría, el levante y el engorde de pollos, gallinas, pavos, gansos, patos y otras aves de corral con el fin de obtener carne, huevos y polluelos para la venta en mercados o entrega a compradores u organismos de comercialización. Se pueden desempeñar en plantas de incubación artificial, granjas, empresas avícolas, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"6","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS AGROPECUARIOS, FORESTALES Y PESQUEROS"},"subgrupo_principal":{"codigo":"61","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS DE EXPLOTACIONES AGROPECUARIAS CON DESTINO AL MERCADO"},"subgrupo":{"codigo":"612","nombre":"Criadores y trabajadores pecuarios calificados de la cría de animales orientados al mercado"},"grupo_primario":{"codigo":"6122","nombre":"Avicultores y trabajadores calificados de la avicultura"}},"funciones":[{"consecutivo":1,"texto":"Cultivar, mezclar y suministrar piensos, aditivos, suministros alimenticios y verter en comederos y bebederos para que las aves de corral tengan dietas de nutrición balanceada y se mantengan en buenas condiciones."},{"consecutivo":2,"texto":"Examinar y realizar seguimiento de las aves de corral para detectar lesiones o dolencias compatibles con enfermedades, de acuerdo con métodos y especificaciones técnicas, y suministrar tratamiento bajo el control de técnicos o profesionales, aplicando normas de bioseguridad avícola."},{"consecutivo":3,"texto":"Retirar de la bandada las aves débiles, enfermas o muertas bajo control de técnicos o profesionales aplicando normas de bioseguridad avícola."},{"consecutivo":4,"texto":"Vacunar a las aves de corral en su primer día de nacidas y durante su vida, siguiendo las recomendaciones técnicas sobre la aplicación de vacunas, las vías de administración y el plan sanitario establecido para la prevención y el control de enfermedades aviares."},{"consecutivo":5,"texto":"Recoger y almacenar productos como huevo, carne, entre otros y empacarlos para la venta o entrega al mercado."},{"consecutivo":6,"texto":"Seleccionar, sexar y empacar aves de un día para despachar a granjas, según procedimiento técnico."},{"consecutivo":7,"texto":"Llevar y mantener registros relacionados con los procesos de natalidad, mortalidad y producción en la explotación avícola, según procedimiento técnico."},{"consecutivo":8,"texto":"Realizar actividades de limpieza y desinfección de máquinas, equipos, instalaciones, galpones, jaulas, gallineros, entre otros, utilizados en el sector avícola, y aplicar normas de bioseguridad."},{"consecutivo":9,"texto":"Alistar y monitorear máquinas nacedoras, según procedimiento técnico, controlando variables como temperatura, luz y humedad."},{"consecutivo":10,"texto":"Recepcionar, inventariar y transferir la producción de huevos fértiles a máquinas incubadoras."},{"consecutivo":11,"texto":"Manipular cortinas, techos y paredes móviles de galpones para controlar temperatura, luz y humedad."},{"consecutivo":12,"texto":"Iniciar y controlar el proceso del desarrollo embrionario, nacimiento y sus variables, según procedimiento técnico."},{"consecutivo":13,"texto":"Sacrificar aves de corral y acondicionarlas para la venta o entrega al mercado de acuerdo con procedimientos técnicos."},{"consecutivo":14,"texto":"Aplicar productos para el tratamiento del agua de bebida de las aves y el control de roedores y plagas, según criterios técnicos establecidos."},{"consecutivo":15,"texto":"Operar los sistemas para el control de condiciones ambientales del galpón (temperatura, ventilación, humedad y luz)."},{"consecutivo":16,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"61222.001","nombre":"Clasificador de aves en pie / Clasificadora de aves en pie"},{"codigo":"61222.002","nombre":"Galponero avícola / Galponera avícola"},{"codigo":"61222.003","nombre":"Operador de planta de incubación / Operadora de planta de incubación"},{"codigo":"61222.004","nombre":"Operario de planta de incubación / Operaria de planta de incubación"},{"codigo":"61222.005","nombre":"Sexador de aves / Sexadora de aves"},{"codigo":"61222.006","nombre":"Trabajador avícola / Trabajadora avícola"},{"codigo":"61222.007","nombre":"Trabajador de granja avícola / Trabajadora de granja avícola"},{"codigo":"61222.008","nombre":"Trabajador de plantas de incubación artificial / Trabajadora de plantas de incubación artificial"},{"codigo":"61222.009","nombre":"Operario de selección de aves en pie / Operaria de selección de aves en pie"},{"codigo":"61222.010","nombre":"Operario de sexaje de aves / Operaria de sexaje de aves"},{"codigo":"61222.011","nombre":"Operario de vacunación de aves / Operaria de vacunación de aves"}],"conocimientos":[{"id":"17","nombre":"Biología"},{"id":"98","nombre":"Producción agrícola y pecuaria"},{"id":"7","nombre":"Producción y procesamiento"},{"id":"96","nombre":"Veterinaria"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"31425","nombre":"Supervisores de producción pecuaria / Supervisoras de producción pecuaria"},{"codigo":"32400","nombre":"Técnicos y asistentes veterinarios / Técnicas y asistentes veterinarias"},{"codigo":"61221","nombre":"Avicultores / Avicultoras"},{"codigo":"61290","nombre":"Criadores y trabaja