cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Trabajadores calificados de explotación forestal / Trabajadoras calificadas de explotación forestal', '62101', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 2, false, '{"codigo":"62101","nombre":"Trabajadores calificados de explotación forestal / Trabajadoras calificadas de explotación forestal","descripcion":"Organizan y llevan a cabo actividades necesarias para talar, derribar y trozar árboles, al igual que la operación de equipos de arrastre, bandas transportadoras y deslizadores para mover o apilar árboles talados desde los sitios de explotación al área de procesamiento y transporte. Se pueden desempeñar en aserraderos, compañías explotadoras de madera, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"6","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS AGROPECUARIOS, FORESTALES Y PESQUEROS"},"subgrupo_principal":{"codigo":"62","nombre":"TRABAJADORES FORESTALES CALIFICADOS, PESCADORES Y CAZADORES EN ACTIVIDADES ORIENTADAS AL MERCADO"},"subgrupo":{"codigo":"621","nombre":"Trabajadores forestales calificados y afines"},"grupo_primario":{"codigo":"6210","nombre":"Trabajadores forestales calificados y afines"}},"funciones":[{"consecutivo":1,"texto":"Determinar e identificar árboles para talar o mover según el lugar, el terreno, las condiciones climáticas y el volumen de madera negociable."},{"consecutivo":2,"texto":"Operar sierra de cadena para talar, desbastar derribar y trozar árboles en el sitio de corte y área de cargue."},{"consecutivo":3,"texto":"Operar equipo de arrastre para mover, apilar o trozar troncos desde el sitio de corte hasta el área de procesamiento y transporte de madera."},{"consecutivo":4,"texto":"Apilar troncos y colocarlos en arrastraderos, deslizaderos, rampas o lanzarlos para hacerlos flotar río abajo."},{"consecutivo":5,"texto":"Capacitar a otros trabajadores en procedimientos forestales, incluidos los trabajadores forestales y operarios de maquinaria."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"62101.001","nombre":"Aserrador de explotación forestal / Aserradora de explotación forestal"},{"codigo":"62101.002","nombre":"Aserrador de monte / Aserradora de monte"},{"codigo":"62101.003","nombre":"Aserrador en explotación maderera / Aserradora en explotación maderera"},{"codigo":"62101.004","nombre":"Aserrador talador / Aserradora taladora"},{"codigo":"62101.005","nombre":"Balsero de transporte de troncos / Balsera de transporte de troncos"},{"codigo":"62101.006","nombre":"Carbonero / Carbonera"},{"codigo":"62101.007","nombre":"Carbonero en carbón vegetal / Carbonera en carbón vegetal"},{"codigo":"62101.008","nombre":"Clasificador de troncos / Clasificadora de troncos"},{"codigo":"62101.009","nombre":"Destilador de madera / Destiladora de madera"},{"codigo":"62101.010","nombre":"Escuadrador de troncos / Escuadradora de troncos"},{"codigo":"62101.011","nombre":"Ganchero / Ganchera"},{"codigo":"62101.012","nombre":"Ganchero de explotación forestal / Ganchera de explotación forestal"},{"codigo":"62101.013","nombre":"Maderero / Maderera"},{"codigo":"62101.014","nombre":"Operador de sierra de cadena para explotación forestal / Operadora de sierra de cadena para explotación forestal"},{"codigo":"62101.015","nombre":"Talador / Taladora"},{"codigo":"62101.016","nombre":"Talador de arboles / Taladora de arboles"},{"codigo":"62101.017","nombre":"Talador de árboles con hacha o motosierra / Taladora de árboles con hacha o motosierra"},{"codigo":"62101.018","nombre":"Trabajador de explotación forestal / Trabajadora de explotación forestal"},{"codigo":"62101.019","nombre":"Trabajador forestal en explotación / Trabajadora forestal en explotación"},{"codigo":"62101.020","nombre":"Trozador de árboles / Trozadora de árboles"},{"codigo":"62101.021","nombre":"Trozador de explotación forestal / Trozadora de explotación forestal"},{"codigo":"62101.022","nombre":"Operario forestal / Operaria forestal"}],"conocimientos":[{"id":"