  ('rol_cuoc', 'Trabajadores de silvicultura y forestación / Trabajadoras de silvicultura y forestación', '62102', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 2, false, '{"codigo":"62102","nombre":"Trabajadores de silvicultura y forestación / Trabajadoras de silvicultura y forestación","descripcion":"Planifican, organizan y llevan a cabo funciones relacionadas con la reforestación, el manejo, el mejoramiento y la conservación de bosques y reservas naturales. Se pueden desempeñar en compañías explotadoras de madera, gobierno, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"6","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS AGROPECUARIOS, FORESTALES Y PESQUEROS"},"subgrupo_principal":{"codigo":"62","nombre":"TRABAJADORES FORESTALES CALIFICADOS, PESCADORES Y CAZADORES EN ACTIVIDADES ORIENTADAS AL MERCADO"},"subgrupo":{"codigo":"621","nombre":"Trabajadores forestales calificados y afines"},"grupo_primario":{"codigo":"6210","nombre":"Trabajadores forestales calificados y afines"}},"funciones":[{"consecutivo":1,"texto":"Evaluar y determinar sitios aptos de reforestación para plantar árboles, plántulas, plantones y seleccionar semilleros utilizando herramientas manuales de acuerdo con procedimientos técnicos."},{"consecutivo":2,"texto":"Recolectar semillas, podar árboles, realizar muestreos de plantaciones y marcar árboles para talas posteriores."},{"consecutivo":3,"texto":"Manejar motosierras y otros elementos mecánicos para aclarar, ralear, espaciar, descabezar, derribar árboles y aserrar troncos en áreas de reforestación."},{"consecutivo":4,"texto":"Controlar malas hierbas y malezas en áreas de reforestación utilizando herramientas manuales y productos químicos."},{"consecutivo":5,"texto":"Realizar actividades de vigilancia, prevención, contribución y participación en maniobras de extinción de incendios forestales."},{"consecutivo":6,"texto":"Operar, manejar y mantener palas mecánicas, excavadoras, arrastradores, buldócer u otras máquinas para remolcar diversos equipos de escarificación de suelos y preparación del terreno en zonas de regeneración forestal."},{"consecutivo":7,"texto":"Proporcionar información al público en general y participar en programas educativos sobre conservación y protección de recursos naturales."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"62102.001","nombre":"Almadiero / Almadiera"},{"codigo":"62102.002","nombre":"Cubicador forestal / Cubicadora forestal"},{"codigo":"62102.003","nombre":"Destajero de silvicultura / Destajera de silvicultura"},{"codigo":"62102.004","nombre":"Escalador podador de árboles / Escaladora podadora de árboles"},{"codigo":"62102.005","nombre":"Escalador podador en silvicultura / Escaladora podadora en silvicultura"},{"codigo":"62102.006","nombre":"Marcador de árboles / Marcadora de árboles"},{"codigo":"62102.007","nombre":"Operador de sierra desmontadora / Operadora de sierra desmontadora"},{"codigo":"62102.008","nombre":"Operador de sierra espaciadora / Operadora de sierra espaciadora"},{"codigo":"62102.009","nombre":"Trabajador de silvicultura / Trabajadora de silvicultura"},{"codigo":"62102.010","nombre":"Trabajador forestal / Trabajadora forestal"},{"codigo":"62102.011","nombre":"Trabajador forestal de reforestación / Trabajadora forestal de reforestación"},{"codigo":"62102.012","nombre":"Trabajador forestal en silvicultura / Trabajadora forestal en silvicultura"},{"codigo":"62102.013","nombre":"Trabajador forestal especializado / Trabajadora forestal especializada"},{"codigo":"62102.014","nombre":"Trabajador en silvicultura y forestación / Trabajadora en silvicultura y forestación"}],"conocimientos":[{"id":"72","nombre":"Horticultura (técnicas de huertas, invernaderos, viveros y jardines)"},{"id":"44","nombre":"Patrimonio natural"},{"id":"89","nombre":"Silvicultura y producción forestal"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"24","nombre":"Mantenimiento de equipos"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"21322","nombre":"Silvicultores y forestales / Silvicultoras y forestales"},{"codigo":"31431","nombre":"Técnicos forestales y de recursos naturales / Técnicas forestales y de recursos naturales"},{"codigo":"61132","nombre":"Trabajadores agrícolas calificados de huertas, invernaderos, viveros y jardines / Trabajadoras agrícolas calificadas de huertas, invernaderos, viveros y jardines"},{"codigo":"62101","nombre":"Trabajadores calificados de explotación forestal / Trabajadoras calificadas de explotación forestal"},{"codigo":"92150","nombre":"Obreros y peones forestales y de silvicultura / Obreras y peonas forestales y de silvicultura"}],"area_principal":{"sigla":"AGVE","nombre":"Agropecuario, silvicultura, pesca, acuicultura y veterinaria"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"6210*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"7322*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Productores de acuicultura / Productoras de acuicultura', '62211', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 3, false, '{"codigo":"62211","nombre":"Productores de acuicultura / Productoras de acuicultura","descripcion":"Programan y controlan actividades dedicadas a la reproducción, cría y lévate de peces, crustáceos, moluscos y otras especies de vida acuática, para la producción, comercialización o liberación. Se pueden desempeñar en plantas acuícolas, entre otros.","nivel_competencia":3,"jerarquia":{"gran_grupo":{"codigo":"6","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS AGROPECUARIOS, FORESTALES Y PESQUEROS"},"subgrupo_principal":{"codigo":"62","nombre":"TRABAJADORES FORESTALES CALIFICADOS, PESCADORES Y CAZADORES EN ACTIVIDADES ORIENTADAS AL MERCADO"},"subgrupo":{"codigo":"622","nombre":"Pescadores, cazadores y tramperos"},"grupo_primario":{"codigo":"6221","nombre":"Productores y trabajadores calificados de explotaciones de acuicultura"}},"funciones":[{"consecutivo":1,"texto":"Programar, controlar y hacer seguimiento a la cría, el levante, el cultivo y la cosecha de peces, mejillones, ostras, alevinos, nauplios, larvas y otras especies de vida acuática para la producción, comercialización o liberación en agua dulce o salada."},{"consecutivo":2,"texto":"Registrar información de parámetros sobre crecimiento, producción, proveedores e inventarios de insumos para la elaboración de informes."},{"consecutivo":3,"texto":"Coordinar, delegar funciones y supervisar trabajadores involucrados en los procesos productivos de la acuicultura."},{"consecutivo":4,"texto":"Comprar, alquilar y asegurar el mantenimiento de edificaciones, equipamientos, maquinarias, tanques, embarcaciones, otros equipos, al igual que suministros para los sistemas de cultivo acuícola."},{"consecutivo":5,"texto":"Coordinar, verificar y supervisar los planes sanitarios a fin de detectar enfermedades o parásitos en el cultivo o la producción acuícola."},{"consecutivo":6,"texto":"Programar, ajustar y efectuar seguimiento de la dieta alimenticia y nutricional de especies acuáticas para asegurar que se mantengan en condiciones óptimas en las diferentes etapas del proceso productivo."},{"consecutivo":7,"texto":"Supervisar y realizar procesos de captura, desove de peces, incubación de huevos, cría de pececillos y aplicar conocimientos de gestión, control de calidad y técnicas acuícolas."},{"consecutivo":8,"texto":"Implementar y realizar seguimiento a las Buenas Prácticas de Producción Acuícola (BPPA) y al cumplimiento de las normas que regulan la actividad."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"62211.001","nombre":"Acuicultor / Acuicultora"},{"codigo":"62211.002","nombre":"Criador de camarones / Criadora de camarones"},{"codigo":"62211.003","nombre":"Criador de especies acuáticas / Criadora de especies acuáticas"},{"codigo":"62211.004","nombre":"Criador de peces / Criadora de peces"},{"codigo":"62211.005","nombre":"Criador de peces estanque / Criadora de peces estanque"},{"codigo":"62211.006","nombre":"Criador de trucha / Criadora de trucha"},{"codigo":"62211.007","nombre":"Cultivador de algas / Cultivadora de algas"},{"codigo":"62211.008","nombre":"Cultivador de madreperlas / Cultivadora de madreperlas"},{"codigo":"62211.009","nombre":"Ostricultor / Ostricultora"},{"codigo":"62211.010","nombre":"Piscicultor / Piscicultora"},{"codigo":"62211.011","nombre":"Productor de mariscos / Productora de mariscos"},{"codigo":"62211.012","nombre":"Criador de especies acuícolas / Criadora de especies acuícolas"}],"conocimientos":[{"id":"83","nombre":"Acuicultura y pesca"},{"id":"17","nombre":"Biología"},{"id":"7","nombre":"Producción y procesamiento"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"17","nombre":"Análisis de necesidades"},{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"13120","nombre":"Directores y gerentes de producción acuícola, piscícola y de pesca / Directoras y gerentas de producción acuícola, piscícola y de pesca"},{"codigo":"62212","nombre":"Trabajadores acuícolas calificados / Trabajadoras acuícolas calificadas"},{"codigo":"92160","nombre":"Obreros y peones de pesca y acuicultura / Obreras y peonas de pesca y acuicultura"}],"area_principal":{"sigla":"AGVE","nombre":"Agropecuario, silvicultura, pesca, acuicultura y veterinaria"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"6221*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"7111*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Trabajadores acuícolas calificados / Trabajadoras acuícolas calificadas', '62212', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 2, false, '{"codigo":"62212","nombre":"Trabajadores acuícolas calificados / Trabajadoras acuícolas calificadas","descripcion":"Apoyan y realizan la siembra, la transferencia, la alimentación, el cuidado, el seguimiento, la cosecha y la producción de especies acuáticas, verificando el cumplimiento de normas y especificaciones técnicas establecidas para la venta en mercados o entrega a compradores u organismos de comercialización. Se pueden desempeñar en criaderos de peces comerciales, entidades de fomento, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"6","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS AGROPECUARIOS, FORESTALES Y PESQUEROS"},"subgrupo_principal":{"codigo":"62","nombre":"TRABAJADORES FORESTALES CALIFICADOS, PESCADORES Y CAZADORES EN ACTIVIDADES ORIENTADAS AL MERCADO"},"subgrupo":{"codigo":"622","nombre":"Pescadores, cazadores y tramperos"},"grupo_primario":{"codigo":"6221","nombre":"Productores y trabajadores calificados de explotaciones de acuicultura"}},"funciones":[{"consecutivo":1,"texto":"Ayudar en las etapas de producción de semilla, cría, levante y engorde de peces, mejillones, ostras y otras especies de vida acuática, de acuerdo con los programas de cultivo comercial o liberación."},{"consecutivo":2,"texto":"Realizar observación permanente, toma y registros de parámetros a la calidad del agua y producción, biometrías, mortalidad e inventario de acuerdo con condiciones físicas y sanitarias de las especies acuícolas."},{"consecutivo":3,"texto":"Operar y mantener instalaciones, tanques, maquinarias, embarcaciones y otros equipos en labores acuícolas."},{"consecutivo":4,"texto":"Revisar, limpiar, desinfectar, mantener y operar equipos e instalaciones relacionadas con las etapas productivas, garantizando condiciones óptimas de la vida acuática."},{"consecutivo":5,"texto":"Limpiar, congelar, colocar en hielo o salar las capturas, tanto en alta mar como en tierra y apoyar el proceso de transporte de productos cosechado hasta la planta de transformación o su despacho, garantizando la cadena de custodia."},{"consecutivo":6,"texto":"Preparar, reparar y alistar redes, aparejos y materiales de pesca para efectuar la captura, clasificación, transporte y traslado de animales de acuerdo con requerimientos técnicos y programas de manejo acuícola."},{"consecutivo":7,"texto":"Aplicar tratamientos profilácticos, tratamientos preventivos y de control de enfermedades, implementando buenas prácticas de producción acuícola y programas de bioseguridad en cada una de las etapas de producción."},{"consecutivo":8,"texto":"Preparar medios de cultivo, concentrado y nutrientes para suministrar alimento a especies acuícolas de acuerdo con las etapas de producción y requerimientos técnicos."},{"consecutivo":9,"texto":"Recoger, almacenar y disponer los residuos generados en la etapa de incubación, levante y engorde acuícola de acuerdo con programas establecidos."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"62212.001","nombre":"Auxiliar de cadena de custodia acuícola"},{"codigo":"62212.002","nombre":"Operario acuícola / Operaria acuícola"},{"codigo":"62212.003","nombre":"Operario en cosecha acuícola / Operaria en cosecha acuícola"},{"codigo":"62212.004","nombre":"Operario de cultivo acuícola / Operaria de cultivo acuícola"},{"codigo":"62212.005","nombre":"Operario de bombeo acuícola / Operaria de bombeo acuícola"},{"codigo":"62212.006","nombre":"Operario en producción de alimento vivo / Operaria en producción de alimento vivo"},{"codigo":"62212.007","nombre":"Trabajador acuícola de campo / Trabajadora acuícola de campo"},{"codigo":"62212.008","nombre":"Trabajador de piscifactoría / Trabajadora de piscifactoría"},{"codigo":"62212.009","nombre":"Trabajador de vivero de mariscos / Trabajadora de vivero de mar