  ('rol_cuoc', 'Trabajadores agropecuarios de subsistencia / Trabajadoras agropecuarias de subsistencia', '63300', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 2, false, '{"codigo":"63300","nombre":"Trabajadores agropecuarios de subsistencia / Trabajadoras agropecuarias de subsistencia","descripcion":"Realizan actividades de cultivo, cosecha, cría y cuidado de animales con el fin de obtener alimentos, vivienda y generar en algunos casos un nivel mínimo de ingresos en efectivo para ellos y sus familias. Se pueden desempeñar en granjas, fincas, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"6","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS AGROPECUARIOS, FORESTALES Y PESQUEROS"},"subgrupo_principal":{"codigo":"63","nombre":"TRABAJADORES AGROPECUARIOS, PESCADORES, CAZADORES Y RECOLECTORES DE SUBSISTENCIA"},"subgrupo":{"codigo":"633","nombre":"Trabajadores agropecuarios de subsistencia"},"grupo_primario":{"codigo":"6330","nombre":"Trabajadores agropecuarios de subsistencia"}},"funciones":[{"consecutivo":1,"texto":"Preparar la tierra, sembrar, cultivar, cosechar cultivos agrícolas, plantas de la huerta, hortalizas, árboles frutales, arbustos y realizar labores culturales a sembradíos para autoconsumo, trueque o venta en mercados locales."},{"consecutivo":2,"texto":"Criar, cuidar y alimentar animales incluyendo aves de corral con el fin de obtener carne, huevos, leche, pelo, piel u otros productos para autoconsumo, trueque o venta en mercados locales."},{"consecutivo":3,"texto":"Construir y mantener viviendas, corrales, establos, graneros, herramientas, indumentaria y utensilios para autoconsumo, trueque o venta en mercados locales."},{"consecutivo":4,"texto":"Mantener, operar y cuidar herramientas como guadañadoras, podadoras y otros equipos agrícolas simples."},{"consecutivo":5,"texto":"Recolectar frutos, plantas silvestres, madera para leña y agua para autoconsumo, trueque o venta en mercados locales."},{"consecutivo":6,"