  ('rol_cuoc', 'Pescadores, cazadores, tramperos y recolectores de subsistencia / Pescadoras, cazadoras, tramperas y recolectoras de subsistencia', '63400', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 2, false, '{"codigo":"63400","nombre":"Pescadores, cazadores, tramperos y recolectores de subsistencia / Pescadoras, cazadoras, tramperas y recolectoras de subsistencia","descripcion":"Recogen agua, leña, frutos y plantas silvestres tanto medicinales como de otra índole, cazan y atrapan animales o diversas especies acuáticas con el fin de obtener alimentos, vivienda y en algunos casos generar un nivel mínimo de ingresos en efectivo para ellos y sus familias. Se pueden desempeñar en granjas, bosques, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"6","nombre":"AGRICULTORES Y TRABAJADORES CALIFICADOS AGROPECUARIOS, FORESTALES Y PESQUEROS"},"subgrupo_principal":{"codigo":"63","nombre":"TRABAJADORES AGROPECUARIOS, PESCADORES, CAZADORES Y RECOLECTORES DE SUBSISTENCIA"},"subgrupo":{"codigo":"634","nombre":"Pescadores, cazadores, tramperos y recolectores de subsistencia"},"grupo_primario":{"codigo":"6340","nombre":"Pescadores, cazadores, tramperos y recolectores de subsistencia"}},"funciones":[{"consecutivo":1,"texto":"Recolectar agua, leña, frutos, raíces y plantas silvestres tanto medicinales como de otra índole, para autoconsumo, trueque o venta en mercados locales."},{"consecutivo":2,"texto":"Cazar o atrapar animales para obtener carne, leche, pelo, piel u otros productos destinados al autoconsumo, trueque o venta en mercados locales."},{"consecutivo":3,"texto":"Maniobrar embarcaciones pequeñas o equipos para la captura de peces u otras especies acuáticas en ríos, mares o costas, para autoconsumo, trueque o venta en mercados locales."},{"consecutivo":4,"texto":"Almacenar productos de origen animal o vegetal y llevar a cabo algún tipo de procesamiento y conservación de los mismo, para autoconsumo, trueque o venta en mercados locales."},{"consecutivo":5,"texto":"Construir y mantener edificaciones, herramientas, indumentaria y utensilios para autoconsumo, trueque o venta en mercados locales."},{"consecutivo":6,"texto":"Entregar, vender o realizar trueque de excedentes de productos de origen animal o vegetal en mercados locales."},{"consecutivo":7,"texto":"Preparar redes, sedales, anzuelos, trampas, cuerdas, armas, jaulas y otros aparejos para la captura de animales destinados al autoconsumo, trueque o venta en mercados locales."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"63400.001","nombre":"Buzo de subsistencia"},{"codigo":"63400.002","nombre":"Cazador de subsistencia / Cazadora de subsistencia"},{"codigo":"63400.003","nombre":"Pescador de subsistencia / Pescadora de subsistencia"},{"codigo":"63400.004","nombre":"Recolector de subsistencia / Recolectora de subsistencia"},{"codigo":"63400.005","nombre":"Trampero de subsistencia / Trampera de subsistencia"}],"conocimientos":[{"id":"38","nombre":"Mantenimiento"},{"id":"98","nombre":"Producción agrícola y pecuaria"}],"destrezas":[{"id":"17","nombre":"Análisis de necesidades"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"24","nombre":"Mantenimiento de equipos"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"63100","nombre":"Trabajadores agrícolas de subsistencia / Trabajadoras agrícolas de subsistencia"},{"codigo":"63200","nombre":"Trabajadores pecuarios de subsistencia / Trabajadoras pecuarias de subsistencia"},{"codigo":"92120","nombre":"Obreros y peones de explotaciones ganaderas / Obreras y peonas de explotaciones ganaderas"},{"codigo":"96240","nombre":"Acarreadores de agua y recolectores de leña / Acarreadoras de agua y recolectores de leña"}],"area_principal":{"sigla":"AGVE","nombre":"Agropecuario, silvicultura, pesca, acuicu