  ('rol_cuoc', 'Oficiales y operarios de la construcción de obra gruesa y afines no clasificados en otras ocupaciones', '71190', 'Construcción e infraestructura', 2, false, '{"codigo":"71190","nombre":"Oficiales y operarios de la construcción de obra gruesa y afines no clasificados en otras ocupaciones","descripcion":"Esta ocupación abarca a Oficiales y operarios de la construcción de obra gruesa y afines no clasificados en otras ocupaciones en el Subgrupo 712 Oficiales y operarios de la construcción de trabajos de acabado y afines. Por ejemplo, incluye aquellos que desempeñan diversas labores relacionadas con la construcción como: levantamiento y replanteo de andamios, apuntalamiento de las estructuras, demolición de edificaciones, mantenimiento en alturas y demás funciones. Se pueden desempeñar en compañías constructoras, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"71","nombre":"OFICIALES Y OPERARIOS DE LA CONSTRUCCIÓN (EXCLUYENDO ELECTRICISTAS)"},"subgrupo":{"codigo":"711","nombre":"Oficiales y operarios de la construcción de obra gruesa y afines"},"grupo_primario":{"codigo":"7119","nombre":"Oficiales y operarios de la construcción de obra gruesa y afines no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Montar y levantar andamiajes y otras armazones provisionales de madera o metal en los lugares de obras."},{"consecutivo":2,"texto":"Verificar las condiciones del área de armado y replanteo de andamios."},{"consecutivo":3,"texto":"Demoler edificios y otras estructuras de acuerdo con especificaciones técnicas."},{"consecutivo":4,"texto":"Apuntalar con estructura de tubos metálicos, vigas, cuñas de madera o de metal, los edificios donde se efectúan obras de transformación."},{"consecutivo":5,"texto":"Excavar pozos de agua y fosas profundas para asentar los cimientos de las construcciones."},{"consecutivo":6,"texto":"Levantar y alinear chimeneas residenciales e industriales empleando ladrillos especiales."},{"consecutivo":7,"texto":"Interpretar especificaciones de órdenes de trabajo para determinar la ubicación y el procedimiento de obra."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"71190.001","nombre":"Andamiero / Andamiera"},{"codigo":"71190.002","nombre":"Apuntalador de edificios / Apuntaladora de edificios"},{"codigo":"71190.003","nombre":"Auxiliar técnico de servicios generales de reparación e instalación / Auxiliar técnica de servicios generales de reparación e instalación"},{"codigo":"71190.004","nombre":"Ayudante o técnico de andamios"},{"codigo":"71190.005","nombre":"Enlucidor de suelos plásticos / Enlucidora de suelos plásticos"},{"codigo":"71190.006","nombre":"Montador de andamios / Montadora de andamios"},{"codigo":"71190.007","nombre":"Oficial de mantenimiento general residencial y comercial"},{"codigo":"71190.008","nombre":"Oficial de obra negra"},{"codigo":"71190.009","nombre":"Operario de apuntalamiento en edificación / Operaria de apuntalamiento en edificación"},{"codigo":"71190.010","nombre":"Operario de construcción para trabajos a gran altura / Operaria de construcción para trabajos a gran altura"},{"codigo":"71190.011","nombre":"Operario de derribo de edificios / Operaria de derribo de edificios"},{"codigo":"71190.012","nombre":"Operario de mantenimiento general edificios / Operaria de mantenimiento general edificios"},{"codigo":"71190.013","nombre":"Operario de montaje de edificaciones prefabricadas / Operaria de montaje de edificaciones prefabricadas"},{"codigo":"71190.014","nombre":"Operario de reparación de chimeneas / Operaria de reparación de chimeneas"},{"codigo":"71190.015","nombre":"Operario de reparación de edificios / Operaria de reparación de edificios"},{"codigo":"71190.016","nombre":"Operario especializado en demolición excepto por método de implosión / Operaria especializada en demolición excepto por método de implosión"},{"codigo":"71190.017","nombre":"Pocero / Pocera"},{"codigo":"71190.018","nombre":"Reparador de chimeneas / Reparadora de chimeneas"}],"conocimientos":[{"id":"12","nombre":"Construcción e ingeniería civil"},{"id":"11","nombre":"Diseño"}],"destrezas":[{"id":"2","nombre":"Escucha activa"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"71110","nombre":"Constructores de casas / Constructoras de casas"},{"codigo":"71120","nombre":"Albañiles y oficiales de construcción"},{"codigo":"71140","nombre":"Operarios en cemento armado, enfoscadores y afines / Operarias en cemento armado, enfoscadores y afines"}],"area_principal":{"sigla":"COIF","nombre":"Construcción e infraestructura"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"7119","ciuo08_obs":"Denominaciones completas","cno_codigo":"8343*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8361*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8411*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Techadores / Techadoras', '71210', 'Construcción e infraestructura', 2, false, '{"codigo":"71210","nombre":"Techadores / Techadoras","descripcion":"Instalan, mantienen y reparan azoteas y tejados de edificaciones empleando una o varias clases de materiales. Se pueden desempeñar en empresas constructoras, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"71","nombre":"OFICIALES Y OPERARIOS DE LA CONSTRUCCIÓN (EXCLUYENDO ELECTRICISTAS)"},"subgrupo":{"codigo":"712","nombre":"Oficiales y operarios de la construcción de trabajos de acabado y afines"},"grupo_primario":{"codigo":"7121","nombre":"Techadores"}},"funciones":[{"consecutivo":1,"texto":"Estudiar planos y especificaciones e inspeccionar el lugar de las obras para determinar los materiales necesarios."},{"consecutivo":2,"texto":"Aplicar sobre el interior y exterior de las edificaciones revestimientos de pizarra y tejas prefabricadas para cubrir tejados e impermeabilizar las superficies de concreto."},{"consecutivo":3,"texto":"Medir y cortar materiales de techumbre destinados a cubrir bordes, esquinas y protuberancias como las chimeneas, entre otros."},{"consecutivo":4,"texto":"Instalar y reparar cubiertas de teja metálica usando herramientas manuales o mecánicas."},{"consecutivo":5,"texto":"Instalar, reparar y reemplazar techos utilizando materiales sintéticos, asfalto, fieltros saturados, asfalto caliente y grava, tejas de arcilla o pizarra, madera, metal y otros materiales."},{"consecutivo":6,"texto":"Instalar estructuras temporales, como andamios y escaleras para garantizar la seguridad en el acceso a los tejados."},{"consecutivo":7,"texto":"Impermeabilizar la superficie del techo usando emulsiones, vinilos, sustancias epóxicas, telas asfálticas y otros materiales."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"71210.001","nombre":