  ('rol_cuoc', 'Enchapadores / Enchapadoras', '71221', 'Construcción e infraestructura', 2, false, '{"codigo":"71221","nombre":"Enchapadores / Enchapadoras","descripcion":"Instalan, mantienen y reparan suelos de baldosas, cerámica, porcelanato, azulejo, entre otros, para decoración u otros propósitos. Se pueden desempeñar en compañías constructoras, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"71","nombre":"OFICIALES Y OPERARIOS DE LA CONSTRUCCIÓN (EXCLUYENDO ELECTRICISTAS)"},"subgrupo":{"codigo":"712","nombre":"Oficiales y operarios de la construcción de trabajos de acabado y afines"},"grupo_primario":{"codigo":"7122","nombre":"Enchapadores, parqueteros y colocadores de suelos"}},"funciones":[{"consecutivo":1,"texto":"Ensamblar y colocar piezas y mosaicos para insonorización de espacios y/o diseños decorativos en paredes, muros o pisos de acuerdo con especificaciones."},{"consecutivo":2,"texto":"Instalar baldosas en posición y aplicar presión para fijarlas a la base de acuerdo con especificaciones."},{"consecutivo":3,"texto":"Colocar cemento blanco entre las uniones de las baldosas y retirar los sobrantes, de acuerdo con especificaciones."},{"consecutivo":4,"texto":"Mezclar, aplicar y esparcir mortero, cemento, macilla, pegante y otros adhesivos utilizando llana manual."},{"consecutivo":5,"texto":"Preparar, medir y señalar las superficies que van a ser cubiertas con baldosas, cerámica, porcelanato, azulejos u otros materiales de acuerdo con especificaciones."},{"consecutivo":6,"texto":"Cortar y fijar baldosas con contornos difíciles y pulir las superficies."},{"consecutivo":7,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"71221.001","nombre":"Azulejero / Azulejera"},{"codigo":"71221.002","nombre":"Colocador de baldosas / Colocadora de baldosas"},{"codigo":"71221.003","nombre":"Embaldosador de muros / Embaldosadora 