  ('rol_cuoc', 'Instaladores de pisos / Instaladoras de pisos', '71222', 'Construcción e infraestructura', 2, false, '{"codigo":"71222","nombre":"Instaladores de pisos / Instaladoras de pisos","descripcion":"Instalan, mantienen y reparan suelos de alfombra, pisos de madera, linóleo, vinilos, y otros materiales en edificaciones residenciales, industriales y comerciales, para decoración u otros propósitos. Se pueden desempeñar en compañías constructoras, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"71","nombre":"OFICIALES Y OPERARIOS DE LA CONSTRUCCIÓN (EXCLUYENDO ELECTRICISTAS)"},"subgrupo":{"codigo":"712","nombre":"Oficiales y operarios de la construcción de trabajos de acabado y afines"},"grupo_primario":{"codigo":"7122","nombre":"Enchapadores, parqueteros y colocadores de suelos"}},"funciones":[{"consecutivo":1,"texto":"Preparar medir y señalar las superficies que van a ser cubiertas con parqué, alfombra u otros materiales."},{"consecutivo":2,"texto":"Medir, cortar e instalar pisos de madera tales como parqué o listón, alfombras, pisos de vinilo u otro material, según el diseño o las especificaciones recibidas."},{"consecutivo":3,"texto":"Realizar mantenimiento y reparación de pisos de acuerdo con los distintos tipos de técnicas y especificaciones."},{"consecutivo":4,"texto":"Calcular el costo de los materiales y mano de obra para la instalación de pisos de acuerdo con especificaciones."},{"consecutivo":5,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"71222.001","nombre":"Embaldosador de suelos / Embaldosadora de suelos"},{"codigo":"71222.002","nombre":"Instalador de alfombras / Instaladora de alfombras"},{"codigo":"71222.003","nombre":"Instalador de pisos / Instaladora de pisos"},{"codigo":"71222.004","nombre":"Instalador de pisos de madera / Instaladora de pisos de madera"},{"codigo":"71222.005","nombre":"Instal