  ('rol_cuoc', 'Revocadores / Revocadoras', '71230', 'Construcción e infraestructura', 2, false, '{"codigo":"71230","nombre":"Revocadores / Revocadoras","descripcion":"Revisten y enlucen muros y techos de las edificaciones; aplican recubrimientos de yeso y materiales similares para los interiores, exteriores de las estructuras, paneles de yeso y otros materiales; decoran con adornos de estuco. Se pueden desempeñar en compañías de construcción, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"71","nombre":"OFICIALES Y OPERARIOS DE LA CONSTRUCCIÓN (EXCLUYENDO ELECTRICISTAS)"},"subgrupo":{"codigo":"712","nombre":"Oficiales y operarios de la construcción de trabajos de acabado y afines"},"grupo_primario":{"codigo":"7123","nombre":"Revocadores"}},"funciones":[{"consecutivo":1,"texto":"Limpiar y preparar las superficies, mezclar el yeso y demás ingredientes y determinar la consistencia."},{"consecutivo":2,"texto":"Preparar, aplicar, nivelar y suavizar las capas de cemento, yeso o material similar usando llana, espátulas, brochas y equipo esparcidor, para revestir superficies interiores y exteriores."},{"consecutivo":3,"texto":"Cortar e instalar esquineros metálicos de protección de acuerdo con especificaciones."},{"consecutivo":4,"texto":"Medir, marcar y colocar ángulos y entrepaños, crear diseños decorativos, adornos, paneles de yeso, cornisas de escayola, entre otros."},{"consecutivo":5,"texto":"Medir, marcar y cortar hormas, moldes y paneles de yeso, levantar las piezas cortadas y fijarlas en las paredes, techos o sobre listones."},{"consecutivo":6,"texto":"Cubrir uniones, bordes, pliegues y juntas con yeso húmedo y compuestos de sellado y pulir utilizando herramientas manuales y papel de lija."},{"consecutivo":7,"texto":"Aplicar y revestir muros y techos exteriores e interiores de las edificaciones para dar el acabado a las superficies con cemento, yeso y materiales similares de acuerdo con especificaciones."},{"consecutivo":8,"texto":"Preparar accesorios decorativos de yeso fibroso e instalar tabiques, mamparos y otras separaciones en paredes y techos usando herramientas manuales o mecánicas."},{"consecutivo":9,"texto":"Colocar y asegurar las hojas al metal o partes de madera, anclar piezas metálicas en los espárragos utilizando puntillas, ganchos o alambres."},{"consecutivo":10,"texto":"Instalar los guardacantos, mallas y demás accesorios alrededor de vigas en las cuales va a colocarse el yeso."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"71230.001","nombre":"Colocador de yeso fibroso / Colocadora de yeso fibroso"},{"codigo":"71230.002","nombre":"Decorador de yeso fibroso / Decoradora de yeso fibroso"},{"codigo":"71230.003","nombre":"Decorador escayolista / Decoradora escayolista"},{"codigo":"71230.005","nombre":"Enlistonador / Enlistonadora"},{"codigo":"71230.006","nombre":"Enlucidor de yeso / Enlucidora de yeso"},{"codigo":"71230.007","nombre":"Escayolista"},{"codigo":"71230.008","nombre":"Estucador / Estucadora"},{"codigo":"71230.009","nombre":"Estuquista decorador / Estuquista decoradora"},{"codigo":"71230.010","nombre":"Listonero / Listonera"},{"codigo":"71230.011","nombre":"Pañetador / Pañetadora"},{"codigo":"71230.012","nombre":"Revocador / Revocadora"},{"codigo":"71230.013","nombre":"Yesero / Yesera"},{"codigo":"71230.014","nombre":"Yesero de estuco / Yesera de estuco"},{"codigo":"71230.015","nombre":"Yesero de pared seca / Yesera de pared seca"},{"codigo":"71230.016","nombre":"Yesero ornamental / Yesera ornamental"},{"codigo":"71230.017","nombre":"Yesero sólido / Yesera sólida"}],"conocimientos":[{"id":"12","nombre":"Construcción e ingeniería civil"},{"id":"11","nombre":"Diseño"},{"id":"35","nombre":"Interpretación de planos"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escuc