  ('rol_cuoc', 'Instaladores de material aislante y de insonorización / Instaladoras de material aislante y de insonorización', '71240', 'Construcción e infraestructura', 2, false, '{"codigo":"71240","nombre":"Instaladores de material aislante y de insonorización / Instaladoras de material aislante y de insonorización","descripcion":"Instalan y reparan material aislante, térmico y de insonorización en calderas, tuberías, instalaciones de ventilación, refrigeración y calefacción en paredes, pisos y techos de edificaciones y otras estructuras para prevenir el paso del frío, calor, sonido o fuego. Se pueden desempeñar en compañías constructoras, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"71","nombre":"OFICIALES Y OPERARIOS DE LA CONSTRUCCIÓN (EXCLUYENDO ELECTRICISTAS)"},"subgrupo":{"codigo":"712","nombre":"Oficiales y operarios de la construcción de trabajos de acabado y afines"},"grupo_primario":{"codigo":"7124","nombre":"Instaladores de material aislante y de insonorización"}},"funciones":[{"consecutivo":1,"texto":"Medir y cortar los materiales aislantes a dimensiones requeridas utilizando herramientas manuales y eléctricas."},{"consecutivo":2,"texto":"Examinar e Interpretar planos, especificaciones y lugares de obras para determinar el tipo, la calidad y la cantidad de materiales aislantes requeridos."},{"consecutivo":3,"texto":"Aplicar e inyectar materiales aislantes o insonorizantes en las cavidades interiores de muros, pisos y techos de edificios, utilizando máquinas eléctricas."},{"consecutivo":4,"texto":"Revestir con materiales aislantes superficies externas de equipos como calderas, tuberías, depósitos, tanques, entre otros."},{"consecutivo":5,"texto":"Colocar el aislante alrededor de las obstrucciones y entre las uniones de superficies."},{"consecutivo":6,"texto":"Aislar térmicamente instalaciones y equipos de refrigeración, calefacción y climatización."},{"consecutivo":7,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"71240.001","nombre":"Aislador de calderas y tuberías / Aisladora de calderas y tuberías"},{"codigo":"71240.002","nombre":"Aislador de equipos de refrigeración y aire acondicionado / Aisladora de equipos de refrigeración y aire acondicionado"},{"codigo":"71240.003","nombre":"Aislador de sonidos / Aisladora de sonidos"},{"codigo":"71240.004","nombre":"Aislador de turbinas / Aisladora de turbinas"},{"codigo":"71240.005","nombre":"Instalador de aislación de calderas tuberías y turbinas / Instaladora de aislación de calderas tuberías y turbinas"},{"codigo":"71240.007","nombre":"Instalador de aislación térmica / Instaladora de aislación térmica"},{"codigo":"71240.008","nombre":"Instalador de material aislante / Instaladora de material aislante"},{"codigo":"71240.009","nombre":"Instalador de material aislante de edificios / Instaladora de material aislante de edificios"},{"codigo":"71240.010","nombre":"Instalador de material aislante en equipos de refrigeración y climatización / Instaladora de material aislante en equipos de refrigeración y climatización"},{"codigo":"71240.011","nombre":"Instalador de material aislante para calderas y tuberías / Instaladora de material aislante para calderas y tuberías"},{"codigo":"71240.012","nombre":"Instalador de material de insonorización / Instaladora de material de insonorización"},{"codigo":"71240.013","nombre":"Operario de instalación de material aislante / Operaria de instalación de material aislante"},{"codigo":"71240.014","nombre":"Operario de instalación de material aislante en calderas y tuberías / Operaria de instalación de material aislante en calderas y tuberías"},{"codigo":"71240.015","nombre":"Operario de instalación para aislamiento acústico / Operaria de instalación para aislamiento acústico"}],"conocimientos":[{"id":"12","nombre":"Construcción e ingeniería civil"},{"id":"35","nombre":"Interpretación de planos"},{"id":"14","nombre":"Matemáticas"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"31231","nombre":"Supervisores de la construcción, maestros generales de obra, instalación y reparación / Supervisoras de la construcción, maestros generales de obra, instalación y reparación"}],"area_principal":{"sigla":"COIF","nombre":"Construcción e infraestructura"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"7124","ciuo08_obs":"Denominaciones completas","cno_codigo":"8365","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Cristaleros y vidrieros / Cristaleras y vidrieras', '71250', 'Fabricación, transformación de materiales, instalación, mantenimiento y reparación', 2, false, '{"codigo":"71250","nombre":"Cristaleros y vidrieros / Cristaleras y vidrieras","descripcion":"Miden, cortan, montan e instalan vidrios, cristales y espejos en residencias, edificios comerciales e industriales y a otras estructuras; en vehículos, muebles y otros productos. Se pueden desempeñar en empresas constructoras, vidrierías, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"71","nombre":"OFICIALES Y OPERARIOS DE LA CONSTRUCCIÓN (EXCLUYENDO ELECTRICISTAS)"},"subgrupo":{"codigo":"712","nombre":"Oficiales y operarios de la construcción de trabajos de acabado y afines"},"grupo_primario":{"codigo":"7125","nombre":"Cristaleros y vidrieros"}},"funciones":[{"consecutivo":1,"texto":"Elegir el tipo de cristal que se ha de utilizar, cortarlo a medida según la forma especificada, dimensiones, espesor, marco y materiales requeridos para instalar en ventanas, puertas, duchas y tabiques de edificaciones."},{"consecutivo":2,"texto":"Medir, marcar y cortar vidrios, cristales y espejos utilizando herramientas manuales y equipos eléctricos."},{"consecutivo":3,"texto":"Instalar las hojas de vidrios, cristales y espejos asegurando con ganchos, masillas, empaques, tornillos, molduras, entre otros."},{"consecutivo":4,"texto":"Ensamblar e instalar espejos y vidrios planos o curvados en escaparates, elementos de separación, puertas giratorias, entre otros en paredes, techos o exteriores de edificaciones."},{"consecutivo":5,"texto":"Preparar e instalar claraboyas, cristales, espejos, vitrales y otros vidrios especiales en vitrinas, paredes interiores y techos."},{"consecutivo":6,"texto":"Instalar o reemplazar parabrisas en vehículos y otros productos en vidrio o cristal."},{"consecutivo":7,"texto":"Armar marcos de metal, madera, entre otros materiales para cortar e instalar vidrios y enmarcar objetos."},{"consecutivo":8,"texto":"Calcular costos de los trabajos de acuerdo con los requerimientos del cliente y especificaciones técnicas."},{"consecutivo":9,"texto":"Crear elementos decorativos de cristal, tales como vitrinas, escaleras, balaustradas y ventanas con cristales de colores."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"71250.001","nombre":"Colocador de cristales de automóviles / Colocadora de cristales de automóviles"},{"codigo":"71250.002","nombre":"Cristalero / Cristalera"},{"codigo":"71250.003","nombre":"Cristalero colocador de lunas de vidrio / Cristalera colocadora de lunas de vidrio"},{"codigo":"71250.004","nombre":"Cristalero de claraboyas / Cristalera de claraboyas"},{"codigo":"71250.005","nombre":"Cristalero de edificios / Cristalera de edificios"},{"codigo":"71250.006","nombre":"Cristalero de vehículos / Cristalera de vehículos"},{"codigo":"71250.007","nombre":"Instalador de cristales / Instaladora de cristales"},{"codigo":"71250.008","nombre":"Instalador de cristales de vehículos / Instaladora de cristales de vehículos"},{"codigo":"71250.009","nombre":"Instalador de vitrales / Instaladora de vitrales"},{"codigo":"71250.010","nombre":"Operario de instalación de vidrios / Operaria de instalación de vidrios"},{"codigo":"71250.011","nombre":"Operario de trabajos de vidriería / Operaria de trabajos de vidriería"},{"codigo":"71250.012","nombre":"Operario de vidriería / Operaria de vidriería"},{"codigo":"71250.013","nombre":"Vidriero / Vidriera"},{"codigo":"71250.014","nombre":"Vidriero de edificios / Vidriera de edificios"},{"codigo":"71250.015","nombre":"Vidriero de lunas de vidrio / Vidriera de lunas de vidrio"},{"codigo":"71250.016","nombre":"Vidriero de vehículos / Vidriera de vehículos"},{"codigo":"71250.017","nombre":"Vidriero de vidrieras artísticas / Vidriera de vidrieras artísticas"},{"cod