  ('rol_cuoc', 'Instaladores de redes y equipos a gas / Instaladoras de redes y equipos a gas', '71263', 'Construcción e infraestructura', 2, false, '{"codigo":"71263","nombre":"Instaladores de redes y equipos a gas / Instaladoras de redes y equipos a gas","descripcion":"Instalan, verifican, reparan, ajustan, mantienen y ponen en funcionamiento redes de suministro de gas, accesorios y artefactos de la red en residencias y establecimientos especiales, comerciales e industriales, realizan procesos de gasificación y puesta en servicio de sistemas de suministro de gas. Se pueden desempeñar en empresas distribuidoras de gases combustibles o medicinales e industriales, constructoras, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"71","nombre":"OFICIALES Y OPERARIOS DE LA CONSTRUCCIÓN (EXCLUYENDO ELECTRICISTAS)"},"subgrupo":{"codigo":"712","nombre":"Oficiales y operarios de la construcción de trabajos de acabado y afines"},"grupo_primario":{"codigo":"7126","nombre":"Fontaneros, instaladores y operarios de mantenimiento de tuberías"}},"funciones":[{"consecutivo":1,"texto":"Estudiar los diseños, especificaciones y planos para determinar materiales y localización de las instalaciones de redes y equipos a gas."},{"consecutivo":2,"texto":"Medir y marcar los sitios de referencia para la instalación de las redes y el equipo de gas de acuerdo con los diseños y las especificaciones."},{"consecutivo":3,"texto":"Instalar, habilitar, mantener y dar servicio a los sistemas, unidades, equipos, centros de medición de gas, entre otros, de acuerdo con procedimientos técnicos."},{"consecutivo":4,"texto":"Instalar aparatos y equipos gasodomésticos utilizando herramientas de uso manual y eléctrico."},{"consecutivo":5,"texto":"Instalar, reparar y dar mantenimiento a los medidores, reguladores, redes internas e instalaciones de gas y redes de gases medicinales de acuerdo con el diseño y las especificaciones técnicas."},{"consecutivo":6,"texto":"Examinar, probar y ajustar los sistemas, mecanismos de control, tuberías, redes de distribución y conexiones a gas para prevenir y localizar escapes utilizando medidores de presión, analizadores hidrostáticos, observación u otros métodos."},{"consecutivo":7,"texto":"Preparar reportes de trabajo realizado y condiciones de las instalaciones de redes y equipos a gas."},{"consecutivo":8,"texto":"Instruir a los usuarios sobre las normas de seguridad, manejo y mantenimiento de las unidades, sistemas, redes y equipos a gas."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"71263.001","nombre":"Gasfitero e instalador de tuberías / Gasfitera e instaladora de tuberías"},{"codigo":"71263.002","nombre":"Instalador de artefactos a gas / Instaladora de artefactos a gas"},{"codigo":"71263.003","nombre":"Instalador de calentadores de agua a gas / Instaladora de calentadores de agua a gas"},{"codigo":"71263.004","nombre":"Instalador de gases medicinales / Instaladora de gases medicinales"},{"codigo":"71263.005","nombre":"Instalador de gasodomésticos / Instaladora de gasodomésticos"},{"codigo":"71263.006","nombre":"Instalador de medidores de gas / Instaladora de medidores de gas"},{"codigo":"71263.007","nombre":"Instalador de redes de gas / Instaladora de redes de gas"},{"codigo":"71263.008","nombre":"Instalador de redes de gas combustible residenciales y comerciales / Instaladora de redes de gas combustible residenciales y comerciales"},{"codigo":"71263.009","nombre":"Instalador de redes de gas externas / Instaladora de redes de gas externas"},{"codigo":"71263.010","nombre":"Instalador de redes de gas internas / Instaladora de redes de gas internas"},{"codigo":"71263.011","nombre":"Instalador de redes industriales de gas combustible / Instaladora de redes industriales de gas combustible"},{"codigo":"71263.012","nombre":"Instalador de redes y equipos a gas / Instalador