  ('rol_cuoc', 'Operarios de mantenimiento de redes de abastecimiento de agua y gas / Operarias de mantenimiento de redes de abastecimiento de agua y gas', '71264', 'Construcción e infraestructura', 2, false, '{"codigo":"71264","nombre":"Operarios de mantenimiento de redes de abastecimiento de agua y gas / Operarias de mantenimiento de redes de abastecimiento de agua y gas","descripcion":"Realizan instalaciones, mantenimiento preventivo y correctivo de equipos, redes de abastecimiento y distribución de agua y gas en la parte exterior y subterránea de la tubería maestra. Se pueden desempeñar en plantas de tratamiento de agua y compañías distribuidores de gas, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"71","nombre":"OFICIALES Y OPERARIOS DE LA CONSTRUCCIÓN (EXCLUYENDO ELECTRICISTAS)"},"subgrupo":{"codigo":"712","nombre":"Oficiales y operarios de la construcción de trabajos de acabado y afines"},"grupo_primario":{"codigo":"7126","nombre":"Fontaneros, instaladores y operarios de mantenimiento de tuberías"}},"funciones":[{"consecutivo":1,"texto":"Revisar, limpiar y lubricar el equipo de bombeo, cloración, compresores, válvulas de tuberías en redes de abastecimiento de agua y gas."},{"consecutivo":2,"texto":"Localizar los escapes de agua y gas reportados para reparar las tomas, válvulas y salidas de acuerdo con especificaciones técnicas."},{"consecutivo":3,"texto":"Cavar terrenos y colocar tubos de diferentes materiales en zanjas para formar la red de alcantarillado, drenajes, redes de distribución de agua, gas y para otros propósitos de acuerdo con especificaciones técnicas."},{"consecutivo":4,"texto":"Reparar y dar mantenimiento a las tuberías y accesorios de sistemas de abastecimiento, tubería maestra y redes de distribución de agua y gas."},{"consecutivo":5,"texto":"Hacer inspección de rutina a la tubería maestra y redes de distribución de agua y gas para detectar posibles escapes, la ubicación y magnitud de este."},{"consecutivo":6,"texto":"Llevar los registros de los trabajos ejecutados y de la localización y condiciones de la tubería de agua o gas."},{"consecutivo":7,"texto":"Suministrar la información sobre la distribución y la instalación de las líneas de agua y las redes de distribución de agua y gas."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"71264.001","nombre":"Instalador de redes de acueducto y alcantarillado / Instaladora de redes de acueducto y alcantarillado"},{"codigo":"71264.002","nombre":"Localizador de escapes de gas redes externas (excepto plantas de gas) / Localizadora de escapes de gas redes externas (excepto plantas de gas)"},{"codigo":"71264.003","nombre":"Operario de mantenimiento de acueducto / Operaria de mantenimiento de acueducto"},{"codigo":"71264.004","nombre":"Operario de mantenimiento de instalaciones de abastecimiento de agua y gas / Operaria de mantenimiento de instalaciones de abastecimiento de agua y gas"},{"codigo":"71264.005","nombre":"Operario de mantenimiento de redes gas (excepto plantas de gas) / Operaria de mantenimiento de redes gas (excepto plantas de gas)"},{"codigo":"71264.006","nombre":"Operario de mantenimiento de tuberías de gas (excepto plantas de gas) / Operaria de mantenimiento de tuberías de gas (excepto plantas de gas)"},{"codigo":"71264.007","nombre":"Trabajador de mantenimiento de planta de abastecimiento de agua / Trabajadora de mantenimiento de planta de abastecimiento de agua"},{"codigo":"71264.008","nombre":"Trabajador de mantenimiento redes de gas (excepto plantas de gas) / Trabajadora de mantenimiento redes de gas (excepto plantas de gas)"}],"conocimientos":[{"id":"12","nombre":"Construcción e ingeniería civil"},{"id":"20","nombre":"Geografía y territorio"},{"id":"35","nombre":"Interpretación de planos"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"38","nombre":"Mantenimiento"},{"id":"14","