  ('rol_cuoc', 'Chapistas y caldereros / Chapistas y caldereras', '72131', 'Fabricación, transformación de materiales, instalación, mantenimiento y reparación', 2, false, '{"codigo":"72131","nombre":"Chapistas y caldereros / Chapistas y caldereras","descripcion":"Fabrican, ensamblan, instalan y reparan productos en metales como: acero, aluminio, cobre, estaño, latón, zinc, entre otros. Se pueden desempeñar en industrias o talleres de fabricación de productos en lámina de metal, calderas, compañías constructoras de barcos y establecimientos industriales, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"72","nombre":"OFICIALES Y OPERARIOS DE LA METALURGIA; MECÁNICOS Y REPARADORES DE MÁQUINAS Y AFINES"},"subgrupo":{"codigo":"721","nombre":"Moldeadores, soldadores, chapistas, caldereros, montadores de estructuras metálicas y afines"},"grupo_primario":{"codigo":"7213","nombre":"Chapistas y caldereros"}},"funciones":[{"consecutivo":1,"texto":"Construir y armar estructuras metálicas pequeñas como marcos de ventanas, puertas y otros productos similares."},{"consecutivo":2,"texto":"Alistar y operar máquinas y equipos para trabajar el metal, como: cizalla, prensas, punzones, taladros, oxicombustible de plasma y de air car para cortar, doblar, taladrar, perforar y enderezar lámina de metal."},{"consecutivo":3,"texto":"Fabricar y reparar utensilios de uso doméstico y otros objetos de estaño, cobre y aleaciones ligeras, o piezas y artículos y accesorios de decoración."},{"consecutivo":4,"texto":"Adaptar y empalmar partes metálicas utilizando equipo remachador y de soldadura o similar, para fabricar y reparar productos como: canales, bastidores, conductos para ventilación y calefacción, tejas, calderas, depósitos, tanques, tubería y otros productos de metal."},{"consecutivo":5,"texto":"Aplicar las normas de seguridad industrial, salud ocupacional y medio ambiente que regulan su actividad en el puesto de trabajo."},{"consecutivo":6,"texto":"Convertir los planos en dibujos de taller que han de seguirse para construir y montar productos de chapa metálica."},{"consecutivo":7,"texto":"Interpretar dibujos, diseños e instrucciones orales o escritas para determinar requisitos como: alcance, secuencia de montaje, método y materiales necesarios para el proyecto y trabajo a realizar."},{"consecutivo":8,"texto":"Inspeccionar la calidad de los productos e instalación para garantizar el cumplimiento de las especificaciones."},{"consecutivo":9,"texto":"Alistar componentes estructurales para la soldadura con el proceso GMAW, según procedimientos aplicados en la industria."},{"consecutivo":10,"texto":"Cuidar los equipos y herramientas que están bajo su responsabilidad y devolverlos en buen estado, reportando situaciones anómalas."},{"consecutivo":11,"texto":"Inspeccionar y verificar el registro de mantenimiento de los equipos y las herramientas utilizados en el mantenimiento de equipo estático, soportes y estructuras metálicas."},{"consecutivo":12,"texto":"Montar e instalar equipos estáticos y otros productos de metal pesado, según especificaciones y utilizando herramientas manuales o mecánicas."},{"consecutivo":13,"texto":"Preparar los materiales y realizar fabricación, instalación y mantenimiento para tubería, accesorios internos en equipos estáticos, soportes y estructuras metálicas."},{"consecutivo":14,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"72131.001","nombre":"Calderero / Calderera"},{"codigo":"72131.002","nombre":"Calderero de chapas de acero / Calderera de chapas de acero"},{"codigo":"72131.003","nombre":"Calderero en cobre / Calderera en cobre"},{"codigo":"72131.004","nombre":"Calderero industrial / Calderera industrial"},{"codigo":"72131.005","nombre":"Calderero marítimo / Calderera marítima"},{"codigo":"72131.006","nombre":"Chapista"},{"codigo":"72131.007","nombre":"Chapista calderero / Chapista calderera"},{"codigo":"72131.008","nombre":"Chapista de ornamentación"},{"codigo":"72131.009","nombre":"Hojalatero / Hojalatera"},{"codigo":"72131.010","nombre":"Operario de caldera / Operaria de caldera"},{"codigo":"72131.011","nombre":"Trabajador de metal de lámina / Trabajadora de metal de lámina"},{"codigo":"72131.012","nombre":"Trazador cortador de calderas y chapas / Trazadora cortadora de calderas y chapas"}],"conocimientos":[{"id":"11","nombre":"Diseño"},{"id":"10","nombre":"Ingeniería y tecnología"},{"id":"38","nombre":"Mantenimiento"},{"id":"13","nombre":"Mecánica y metalistería"},{"id":"7","nombre":"Producción y procesamiento"},{"id":"85","nombre":"Seguridad y salud en el trabajo"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"17","nombre":"Análisis de necesidades"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"26","nombre":"Reparación"}],"ocupaciones_afines":[{"codigo":"72120","nombre":"Soldadores y oxicortadores / Soldadoras y oxicortadoras"},{"codigo":"72140","nombre":"Montadores de estructuras metálicas / Montadoras de estructuras metálicas"},{"codigo":"81210","nombre":"Operadores de instalaciones de procesamiento de metales / Operadoras de instalaciones de procesamiento de metales"},{"codigo":"81220","nombre":"Operadores de máquinas pulidoras, galvanizadoras y recubridoras de metales / Operadoras de máquinas pulidoras, galvanizadoras y recubridoras de metales"}],"area_principal":{"sigla":"FAMA","nombre":"Fabricación, transformación de materiales, instalación, mantenimiento y reparación"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"7213*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"8341*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8431*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Latoneros / Latoneras', '72132', 'Fabricación, transformación de materiales, instalación, mantenimiento y reparación', 2, false, '{"codigo":"72132","nombre":"Latoneros / Latoneras","descripcion":"Reparan y restauran partes averiadas de la carrocería, partes estructurales e interiores del vehículo. Se pueden desempeñar en concesionarios, talleres de reparación de carrocerías de vehículos, ensambladoras, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"72","nombre":"OFICIALES Y OPERARIOS DE LA METALURGIA; MECÁNICOS Y REPARADORES DE MÁQUINAS Y AFINES"},"subgrupo":{"codigo":"721","nombre":"Moldeadores, soldadores, chapistas, caldereros, montadores de estructuras metálicas y afines"},"grupo_primario":{"codigo":"7213","nombre":"Chapistas y caldereros"}},"funciones":[{"consecutivo":1,"texto":"Enderezar las estructuras dobladas utilizando equipo requerido."},{"consecutivo":2,"texto":"Inspeccionar los vehículos latonados."},{"consecutivo":3,"texto":"Lijar y pulir superficies reparadas utilizando herramientas manuales o mecánicas."},{"consecutivo":4,"texto":"Martillar las abolladuras y otros defectos usando bloques, martillos u otras herramientas."},{"consecutivo":5,"texto":"Operar equipo de soldadura para latonar."},{"consecutivo":6,"texto":"Remover guardafango, paneles y parrillas dañadas utilizando llaves, soplete, cortador de pernos."},{"consecutivo":7,"texto":"Reparar o cambiar partes interiores como asientos, aisladores de piso y tapetes."},{"consecutivo":8,"texto":"Reparar o reemplazar componentes delanteros y traseros, puertas, armazón y componentes de la parte interior."},{"consecutivo":9,"texto":"Revisar, estimar e inspeccionar daños en los vehículos, reportar los costos de reparación y planear el trabajo que va a realizarse."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"72132.001","nombre":"Carrocero / Carrocera"},{"codigo":"72132.002","nombre":"Chapista de carrocerías"},{"codigo":"72132.003","nombre":"Latonero / Latonera"},{"codigo":"72132.004","nombre":"Latonero de vehículos / Latonera de vehículos"},{"codigo":"72132.005","nombre":"Mecánico de carrocerías de vehículos / Mecánica de carrocerías de vehículos"},{"codigo":"72132.006","nombre":"Reparador de carrocerías de vehículos / Reparadora de carrocerías de vehículos"},{"codigo":"72132.007","nombre":"Técnico en carrocería / Técnica en carrocería"}],"conocimientos":[{"id":"11","nombre":"Diseño"},{"id":"38","nombre":"Mantenimiento"},{"id":"13","nombre":"Mecánica y metalistería"},{"id":"7","nombre":"Producción y procesamiento"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"2","nombre":"Escucha activa"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"11","nombre":"Trabajo en equipo"},{"id":"23","nombre":"Vigilancia de las operaciones"}],"ocupaciones_afines":[{"codigo":"72120","nombre":"Soldadores y oxicortadores / Soldadoras y oxicortadoras"},{"codigo":"72131","nombre":"Chapistas y caldereros / Chapistas y caldereras"},{"codigo":"72140","nombre":"Montadores de estructuras metálicas / Montadoras de estructuras metálicas"},{"codigo":"82110","nombre":"Ensambladores de maquinaria mecánica / Ensambladoras de maquinaria mecánica"}],"area_principal":{"sigla":"FAMA","nombre":"Fabricación, transformación de materiales, instalación, mantenimiento y reparación"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"7213*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"8384","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Montadores de estructuras metálicas / Montadoras de estructuras metálicas', '72140', 'Construcción e infraestructura', 2, false, '{"codigo":"72140","nombre":"Montadores de estructuras metálicas / Montadoras de estructuras metálicas","descripcion":"Fabrican, ensamblan, montan y desmontan piezas, elementos y estructuras metálicas de edificios y otras estructuras. Se pueden desempeñar en empresas de fabricación de estructuras metálicas, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"72","nombre":"OFICIALES Y OPERARIOS DE LA METALURGIA; MECÁNICOS Y REPARADORES DE MÁQUINAS Y AFINES"},"subgrupo":{"codigo":"721","nombre":"Moldeadores, soldadores, chapistas, caldereros, montadores de estructuras metálicas y afines"},"grupo_primario":{"codigo":"7214","nombre":"Montadores de estructuras metálicas"}},"funciones":[{"consecutivo":1,"texto":"Trazar los puntos de referencia y modelos sobre las piezas de metal, como guía para cortar, taladrar y darle forma a estructuras y partes metálicas acuerdo con especificaciones técnicas."},{"consecutivo":2,"texto":"Perforar, cortar y dar forma a estructuras metálicas, empalmar y soldar o empernar partes en el sitio de trabajo."},{"consecutivo":3,"texto":"Montar componentes y estructuras metálicas para construcciones, edificios, puentes, tornos y otras estructuras de acuerdo con especificaciones técnicas."},{"consecutivo":4,"texto":"Ensamblar y montar las sesiones y elementos de las estructuras metálicas de edificios, puentes y otras construcciones, de acuerdo con métodos y especificaciones técnicas."},{"consecutivo":5,"texto":"Remachar elementos metálicos estructurales y otras piezas de acero a mano o remachador neumático, planchas, barras, prensa hidráulica u otra prensa de acuerdo con especificaciones técnicas."},{"consecutivo":6,"texto":"Ensamblar y montar estructuras, armazones, elementos y partes metálicas de acuerdo con especificaciones técnicas."},{"consecutivo":7,"texto":"Alistar material para armado y modificación de estructuras metálicas como andamios, entre otros de acuerdo con especificaciones técnicas."},{"consecutivo":8,"texto":"Montar e instalar andamiajes, aparatos de izar y aparejos verificando condiciones del área."},{"consecutivo":9,"texto":"Operar máquinas de trabajo de metal pesado como prensas, cizallas, cortadores de soplete, esmeriles, taladros y equipo de control numérico para doblar , cortar, moldear, taladrar o soldar componentes de metal pesado."},{"consecutivo":10,"texto":"Aplicar las normas de seguridad industrial, salud ocupacional y medio ambiente que regulan su actividad en el puesto de trabajo."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"72140.001","nombre":"Ajustador ensamblador de estructuras metálicas / Ajustadora ensambladora de estructuras metálicas"},{"codigo":"72140.002","nombre":"Armador de blindaje de buques / Armadora de blindaje de buques"},{"codigo":"72140.003","nombre":"Armador de estructuras de acero / Armadora de estructuras de acero"},{"codigo":"72140.004","nombre":"Armador de estructuras metálicas / Armadora de estructuras metálicas"},{"codigo":"72140.005","nombre":"Armador ensamblador de estructuras metálicas / Armadora ensambladora de estructuras metálicas"},{"codigo":"72140.006","nombre":"Armador instalador de divisiones de oficina / Armadora instaladora de divisiones de oficina"},{"codigo":"72140.007","nombre":"Ayudante o técnico armador de estructuras metálicas / Ayudante o técnica armadora de estructuras metálicas"},{"codigo":"72140.008","nombre":"Curvador de chapas de metal / Curvadora de chapas de metal"},{"codigo":"72140.009","nombre":"Instalador de juegos mecánicos / Instaladora de juegos mecánicos"},{"codigo":"72140.010","nombre":"Instalador ensamblador de estructuras metálicas / Instaladora ensambladora de estructuras metálicas"},{"codigo":"72140.011","nombre":"Montador de armazones metálicos / Montadora de armazones metálicos"},{"codigo":"72140.012","nombre":"Montador de armazones metálicas para buques / Montadora de armazones metálicas para buques"},{"codigo":"72140.013","nombre":"Montador de estructuras de acero / Montadora de estructuras de acero"},{"codigo":"72140.014","nombre":"Montador de estructuras metálicas / Montadora de estructuras metálicas"},{"codigo":"72140.015","nombre":"Montador y armador / Montadora y armadora"},{"codigo":"72140.016","nombre":"Operario de montaje de estructuras metálicas / Operaria de montaje de estructuras metálicas"},{"codigo":"72140.017","nombre":"Preparador de estructuras metálicas / Preparadora de estructuras metálicas"},{"codigo":"72140.018","nombre":"Remachador / Remachadora"},{"codigo":"72140.019","nombre":"Remachador de estructuras metálicas / Remachadora de estructuras metálicas"},{"codigo":"72140.020","nombre":"Remachador de martillo neumático / Remachadora de martillo neumático"},{"codigo":"72140.021","nombre":"Reparador de muebles de metal / Reparadora de muebles de metal"},{"codigo":"72140.022","nombre":"Replanteador de estructuras metálicas / Replanteadora de estructuras metálicas"},{"codigo":"72140.023","nombre":"Trazador de estructuras metálicas / Trazadora de estructuras metálicas"},{"codigo":"72140.024","nombre":"Operador de montaje escenico / Operadora de montaje escenico"}],"conocimientos":[{"id":"12","nombre":"Construcción e ingeniería civil"},{"id":"11","nombre":"Diseño"},{"id":"35","nombre":"Interpretación de planos"},{"id":"14","nombre":"Matemáticas"},{"id":"13","nombre":"Mecánica y metalistería"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"17","nombre":"Análisis de necesidades"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"16","nombre":"Resolución de problemas complejos"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"31226","nombre":"Supervisores de fabricación y tratamiento de productos mecánicos, metálicos y minerales / Supervisoras de fabricación y tratamiento de productos mecánicos, metálicos y minerales"},{"codigo":"72210","nombre":"Herreros y forjadores / Herreras y forjadoras"},{"codigo":"72220","nombre":"Herramentistas y afines"},{"codigo":"72230","nombre":"Ajustadores y operadores de máquinas herramientas / Ajustadoras y operadoras de máquinas herramientas"},{"codigo":"81210","nombre":"Operadores de instalaciones de procesamiento de metales / Operadoras de instalaciones de procesamiento de metales"}],"area_principal":{"sigla":"COIF","nombre":"Construcción e infraestructura"},"areas_complementarias":[{"sigla":"FAMA","nombre":"Fabricación, transformación de materiales, instalación, mantenimiento y reparación"},{"sigla":"TMFM","nombre":"Transformación de la madera y fabricación de muebles"}],"equivalencias":[{"ciuo08_codigo":"7214","ciuo08_obs":"Denominaciones completas","cno_codigo":"8214*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8343*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8344*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8411*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"9393*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Aparejadores / Aparejadoras', '72151', 'Fabricación, transformación de materiales, instalación, mantenimiento y reparación', 2, false, '{"codigo":"72151","nombre":"Aparejadores / Aparejadoras","descripcion":"Montan equipo para mover y posicionar equipos, componentes estructurales, carga y descarga de materiales; inspeccionan aparejos y demás elementos del izaje. Se pueden desempeñar en empresas públicas y privadas, constructoras, compañías transportadoras de carga, agencias y líneas marítimas, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"72","nombre":"OFICIALES Y OPERARIOS DE LA METALURGIA; MECÁNICOS Y REPARADORES DE MÁQUINAS Y AFINES"},"subgrupo":{"codigo":"721","nombre":"Moldeadores, soldadores, chapistas, caldereros, montadores de estructuras metálicas y afines"},"grupo_primario":{"codigo":"7215","nombre":"Aparejadores, instaladores y empalmadores de cables"}},"funciones":[{"consecutivo":1,"texto":"Seleccionar los elementos de izajes (aparejos) requeridos de acuerdo con condiciones y requerimientos técnicos según el tamaño, forma, peso y centro de gravedad de los objetos o carga a mover."},{"consecutivo":2,"texto":"Instalar y mantener jaulas, funiculares, teleféricos, cable vías, plataformas móviles, aparejos y otros aparatos para desplazar pasajeros, materiales, máquinas y objetos de gran peso de acuerdo con manuales técnicos y normativa."},{"consecutivo":3,"texto":"Participar en el montaje y reparación de torres de perforación de pozos de agua, gas y petróleo de acuerdo con procedimientos técnicos."},{"consecutivo":4,"texto":"Participar en el montaje, ajuste e instalación de cables metálicos para construir puentes colgantes y otras estructuras de acuerdo con procedimientos técnicos y normativa."},{"consecutivo":5,"texto":"Verificar la posición de los elementos de izaje, grúa y carga antes y después del levantamiento según manual de operaciones."},{"consecutivo":6,"texto":"Verificar el almacenamiento de los elementos de izaje de carga de acuerdo con procedimientos técnicos."},{"consecutivo":7,"texto":"Inspeccionar los aparejos de carga según los criterios de aceptación o rechazo de los mismos establecidos en las normas técnicas."},{"consecutivo":8,"texto":"Emplear señales de manos y mantener línea visual permanente con el operador de acuerdo con procedimientos técnicos internacionales y normativa vigente."},{"consecutivo":9,"texto":"Instalar, movilizar y desmontar telones, escenografías, equipos de iluminación, entre otros equipos en teatros y sets de filmación de acuerdo con especificaciones del proyecto y procedimientos técnicos."},{"consecutivo":10,"texto":"Aplicar las normas de seguridad industrial, salud ocupacional y medio ambiente que regulen su actividad y puesto de trabajo."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"72151.001","nombre":"Aparejador / Aparejadora"},{"codigo":"72151.002","nombre":"Aparejador de aparatos de elevación para construcción / Aparejadora de aparatos de elevación para construcción"},{"codigo":"72151.003","nombre":"Aparejador de barcos / Aparejadora de barcos"},{"codigo":"72151.004","nombre":"Aparejador de buques / Aparejadora de buques"},{"codigo":"72151.005","nombre":"Aparejador de cables / Aparejadora de cables"},{"codigo":"72151.006","nombre":"Aparejador de ensamblaje de aeronaves / Aparejadora de ensamblaje de aeronaves"},{"codigo":"72151.007","nombre":"Aparejador de máquinas de izar / Aparejadora de máquinas de izar"},{"codigo":"72151.008","nombre":"Aparejador de torre / Aparejadora de torre"},{"codigo":"72151.009","nombre":"Aparejador en industria petrolera / Aparejadora en industria petrolera"},{"codigo":"72151.010","nombre":"Aparejador operario de grúa / Aparejadora operaria de grúa"},{"codigo":"72151.011","nombre":"Montador de cables de puentes colgantes / Montadora de cables de puentes colgantes"},{"codigo":"72151.012","nombre":"Tramoyista"},{"codigo":"72151.013","nombre":"Rigger"}],"conocimientos":[{"id":"12","nombre":"Construcción e ingeniería civil"},{"id":"35","nombre":"Interpretación de planos"},{"id":"14","nombre":"Matemáticas"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"24","nombre":"Mantenimiento de equipos"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"81891","nombre":"Operadores portuarios / Operadoras portuarias"},{"codigo":"81899","nombre":"Otros operadores de máquinas y de instalaciones fijas no clasificados en otras ocupaciones / Otras operadoras de máquinas y de instalaciones fijas no clasificados en otras ocupaciones"},{"codigo":"83430","nombre":"Operadores de grúas, aparatos elevadores y afines / Operadoras de grúas, aparatos elevadores y afines"},{"codigo":"83440","nombre":"Operadores de montacargas / Operadoras de montacargas"},{"codigo":"93332","nombre":"Obreros y peones portuarios / Obreras y peonas portuarias"}],"area_principal":{"sigla":"FAMA","nombre":"Fabricación, transformación de materiales, instalación, mantenimiento y reparación"},"areas_complementarias":[{"sigla":"COIF","nombre":"Construcción e infraestructura"},{"sigla":"LOTR","nombre":"Logística y transporte"}],"equivalencias":[{"ciuo08_codigo":"7215*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"5227*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8343*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8493","cno_obs":"Denominaciones completas"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"9386*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Instaladores y empalmadores de cables / Instaladoras y empalmadoras de cables', '72152', 'Producción de energía y electricidad', 2, false, '{"codigo":"72152","nombre":"Instaladores y empalmadores de cables / Instaladoras y empalmadoras de cables","descripcion":"Instalan, empalman y mantienen los cables, cuerdas y alambres en sistemas de distribución y transmisión de energía eléctrica, aérea y subterránea que se utilizan en obras de construcción, edificios y otras estructuras. Se pueden desempeñar en compañías de generación, transmisión y distribución de energía, empresas de servicios públicos, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"72","nombre":"OFICIALES Y OPERARIOS DE LA METALURGIA; MECÁNICOS Y REPARADORES DE MÁQUINAS Y AFINES"},"subgrupo":{"codigo":"721","nombre":"Moldeadores, soldadores, chapistas, caldereros, montadores de estructuras metálicas y afines"},"grupo_primario":{"codigo":"7215","nombre":"Aparejadores, instaladores y empalmadores de cables"}},"funciones":[{"consecutivo":1,"texto":"Instalar, mantener y reparar cables, redes, líneas aéreas y subterráneas de distribución y transmisión eléctrica, aisladores, conductores, postes de iluminación, interruptores, transformadores y otro equipo asociado de acuerdo con especificaciones técnicas."},{"consecutivo":2,"texto":"Levantar y hacer mantenimiento a los postes de cables, accesorios entre otros de acuerdo con especificaciones técnicas."},{"consecutivo":3,"texto":"Empalmar, soldar y aislar los conductores y alambrado necesarios para conectar la red de distribución y transmisión eléctrica usando herramientas y equipo eléctrico relacionado."},{"consecutivo":4,"texto":"Inspeccionar y probar la línea y cableado de energía aéreo, subterráneo y equipo auxiliar utilizando el equipo eléctrico de prueba."},{"consecutivo":5,"texto":"Operar canastas hidráulicas y escaleras para efectuar trabajos en postes, torres o en túneles para instalar líneas de energía y equipo asociado."},{"consecutivo":6,"texto":"Coordinar con otros trabajadores la preparación y terminación del trabajo asignado en la instalación y empalme de cables."},{"consecutivo":7,"texto":"Ayudar en el empalme de cables de transmisión de energía eléctrica, aérea y subterránea de acuerdo con procedimientos técnicos."},{"consecutivo":8,"texto":"Aplicar las normas de seguridad industrial, salud ocupacional y medio ambiente que regulen su actividad y puesto de trabajo."},{"consecutivo":9,"texto":"Instalar y reparar cabos y cables en buques y aeronaves de acuerdo con especificaciones técnicas."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"72152.001","nombre":"Asistente de cables / Asistenta de cables"},{"codigo":"72152.002","nombre":"Ayudante empalmador de cables / Ayudante empalmadora de cables"},{"codigo":"72152.003","nombre":"Chequeador de línea de hidrocarburos / Chequeadora de línea de hidrocarburos"},{"codigo":"72152.004","nombre":"Empalmador de cables eléctricos de sistemas de energía / Empalmadora de cables eléctricos de sistemas de energía"},{"codigo":"72152.005","nombre":"Empalmador de cables y cuerdas / Empalmadora de cables y cuerdas"},{"codigo":"72152.006","nombre":"Empalmador de cables y sistemas de energía eléctrica / Empalmadora de cables y sistemas de energía eléctrica"},{"codigo":"72152.007","nombre":"Empalmador de redes eléctricas / Empalmadora de redes eléctricas"},{"codigo":"72152.008","nombre":"Instalador de cables de sistema energía eléctrica / Instaladora de cables de sistema energía eléctrica"},{"codigo":"72152.009","nombre":"Instalador de cables subterráneos de sistemas de energía eléctrica / Instaladora de cables subterráneos de sistemas de energía eléctrica"},{"codigo":"72152.010","nombre":"Instalador de cables subterráneos de transporte de corriente eléctrica / Instaladora de cables subterráneos de transporte de corriente eléctrica"},{"codigo":"72152.011","nombre":"Instalador de líneas de energía eléctrica de tendido aéreo / Instaladora de líneas de energía eléctrica de tendido aéreo"},{"codigo":"72152.012","nombre":"Instalador de líneas eléctricas de alta tensión / Instaladora de líneas eléctricas de alta tensión"},{"codigo":"72152.013","nombre":"Instalador de líneas eléctricas subterráneas / Instaladora de líneas eléctricas subterráneas"},{"codigo":"72152.014","nombre":"Instalador de redes de energía eléctrica / Instaladora de redes de energía eléctrica"},{"codigo":"72152.015","nombre":"Liniero de cables eléctricos / Liniera de cables eléctricos"},{"codigo":"72152.016","nombre":"Liniero de redes de energía / Liniera de redes de energía"},{"codigo":"72152.017","nombre":"Liniero eléctrico / Liniera eléctrica"}],"conocimientos":[{"id":"67","nombre":"Electricidad y energía"},{"id":"35","nombre":"Interpretación de planos"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"2","nombre":"Escucha activa"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"19","nombre":"Selección de equipo"}],"ocupaciones_afines":[{"codigo":"74221","nombre":"Técnicos instaladores de redes y líneas de telecomunicaciones / Técnicas instaladoras de redes y líneas de telecomunicaciones"}],"area_principal":{"sigla":"PEEL","nombre":"Producción de energía y electricidad"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"7215*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"2314*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8323*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8414*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Herreros y forjadores / Herreras y forjadoras', '72210', 'Fabricación, transformación de materiales, instalación, mantenimiento y reparación', 2, false, '{"codigo":"72210","nombre":"Herreros y forjadores / Herreras y forjadoras","descripcion":"Forjan y curvan barras, varillas, lingotes y chapas de hierro, acero u otro metal para fabricar herramientas, piezas de maquinaria, accesorios ornamentales, puertas, ventanas y otras estructuras; elaboran el diseño ornamental y unen las partes con diferentes medios. Se pueden desempeñar en fábricas de productos de metal, industrias de maquinarias, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"72","nombre":"OFICIALES Y OPERARIOS DE LA METALURGIA; MECÁNICOS Y REPARADORES DE MÁQUINAS Y AFINES"},"subgrupo":{"codigo":"722","nombre":"Herreros, herramentistas y afines"},"grupo_primario":{"codigo":"7221","nombre":"Herreros y forjadores"}},"funciones":[{"consecutivo":1,"texto":"Operar martillo, pilón o prensa mecánica provista de matrices o estampas para forjar piezas de metal."},{"consecutivo":2,"texto":"Interpretar dibujos y planos para determinar especificaciones y materiales de los pedidos de trabajo, tolerancias especificadas y secuencias de operación de herreros y forjadores."},{"consecutivo":3,"texto":"Calentar el metal en la fragua y hornos de fundición para fabricar o reparar objetos estirando, martillando, curvando, cortando, taladrando, soldando y dándoles temple o recocido al metal o a las piezas sobre un yunque."},{"consecutivo":4,"texto":"Utilizar elementos de protección personal y aplicar normas de medio ambiente, seguridad industrial y salud en el trabajo."},{"consecutivo":5,"texto":"Operar hornos y máquinas para fundir, moldear y vaciar el metal en fundición, en forma manual para producir piezas fundidas."},{"consecutivo":6,"texto":"Operar prensas mecánicas provistas de matrices u otras máquinas para ejecutar forjado en frío o caliente, por trefilado, estirado, curvado, moldeado, cortado, doblado, estampado y ejecutar otras operaciones para dar forma al metal."},{"consecutivo":7,"texto":"Instalar rejas, puertas y otras estructuras ornamentales e inspeccionar las piezas para asegurar que cumplen las especificaciones recibidas."},{"consecutivo":8,"texto":"Colocar piezas de metal frío o caliente en hornos utilizando tenazas manuales o grúa, retirarlas cuando el color del metal indique la temperatura de forjado y alimentar y descargar en el troquel de la prensa o en transportadores automáticos de maquinaria de forjado."},{"consecutivo":9,"texto":"Dar forma en la forja al metal caliente utilizando un martillo mecánico provisto de estampas, taladrando, cortando, curvando, soldando y realizando otras formas de trabajar el metal para lograr el tamaño y forma requeridos."},{"consecutivo":10,"texto":"Forjar herramientas especiales desde el metal o crear moldes especiales, muebles o accesorios de acuerdo con especificaciones técnicas."},{"consecutivo":11,"texto":"Operar hornos de gas o aceite para calentar metales a una temperatura apropiada antes del forjado."},{"consecutivo":12,"texto":"Colocar y ajustar troqueles sobre el yunque de la máquina de forjado utilizando grúa aérea o herramientas manuales."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"72210.001","nombre":"Apisonador de forja / Apisonadora de forja"},{"codigo":"72210.002","nombre":"Forjador / Forjadora"},{"codigo":"72210.003","nombre":"Forjador con herramientas / Forjadora con herramientas"},{"codigo":"72210.004","nombre":"Forjador con martillo / Forjadora con martillo"},{"codigo":"72210.005","nombre":"Forjador con prensa / Forjadora con prensa"},{"codigo":"72210.006","nombre":"Forjador de aperos agrícolas / Forjadora de aperos agrícolas"},{"codigo":"72210.009","nombre":"Forjador de martillo pilón / Forjadora de martillo pilón"},{"codigo":"72210.011","nombre":"Fundidor de piezas de moldeo / Fundidora de piezas de moldeo"},{"codigo":"72210.012","nombre":"Fundidor de metal / Fundidora de metal"},{"codigo":"72210.013","nombre":"Herrador / Herradora"},{"codigo":"72210.014","nombre":"Herrero / Herrera"},{"codigo":"72210.015","nombre":"Metalistero / Metalistera"},{"codigo":"72210.016","nombre":"Operario de forja / Operaria de forja"},{"codigo":"72210.017","nombre":"Operario de moldeo forja y montaje de estructuras metálicas / Operaria de moldeo forja y montaje de estructuras metálicas"},{"codigo":"72210.018","nombre":"Operario de ornamentación y forja / Operaria de ornamentación y forja"},{"codigo":"72210.019","nombre":"Ornamentador / Ornamentadora"},{"codigo":"72210.020","nombre":"Ornamentador armador / Ornamentadora armadora"},{"codigo":"72210.021","nombre":"Ornamentador de hierro / Ornamentadora de hierro"},{"codigo":"72210.022","nombre":"Ornamentista forjador / Ornamentista forjadora"}],"conocimientos":[{"id":"11","nombre":"Diseño"},{"id":"35","nombre":"Interpretación de planos"},{"id":"38","nombre":"Mantenimiento"},{"id":"13","nombre":"Mecánica y metalistería"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"17","nombre":"Análisis de necesidades"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"72120","nombre":"Soldadores y oxicortadores / Soldadoras y oxicortadoras"},{"codigo":"72140","nombre":"Montadores de estructuras metálicas / Montadoras de estructuras metálicas"},{"codigo":"72220","nombre":"Herramentistas y afines"},{"codigo":"72230","nombre":"Ajustadores y operadores de máquinas herramientas / Ajustadoras y operadoras de máquinas herramientas"},{"codigo":"81210","nombre":"Operadores de instalaciones de procesamiento de metales / Operadoras de instalaciones de procesamiento de metales"}],"area_principal":{"sigla":"FAMA","nombre":"Fabricación, transformación de materiales, instalación, mantenimiento y reparación"},"areas_complementarias":[{"sigla":"AVPP","nombre":"Artes visuales, plásticas y del patrimonio cultural"}],"equivalencias":[{"ciuo08_codigo":"7221*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"7332*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8214*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8341*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8344*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"9312*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Herramentistas y afines', '72220', 'Fabricación, transformación de materiales, instalación, mantenimiento y reparación', 2, false, '{"codigo":"72220","nombre":"Herramentistas y afines","descripcion":"Fabrican y reparan herramientas hechas a medida y herramientas especiales, así como armas de uso deportivo, cerraduras, modelos, matrices, troqueles, componentes de maquinarias y otras piezas de metal utilizando herramientas de uso manual y mecánicas con gran precisión. Se pueden desempeñar en industrias manufactureras, cerrajerías, talleres industriales, fabricantes de herramientas y troqueles, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"72","nombre":"OFICIALES Y OPERARIOS DE LA METALURGIA; MECÁNICOS Y REPARADORES DE MÁQUINAS Y AFINES"},"subgrupo":{"codigo":"722","nombre":"Herreros, herramentistas y afines"},"grupo_primario":{"codigo":"7222","nombre":"Herramentistas y afines"}},"funciones":[{"consecutivo":1,"texto":"Interpretar y analizar planchas, dibujos, diagramas, tablas y especificaciones de herramientas, matrices, prototipos o modelos para determinar las operaciones a realizar."},{"consecutivo":2,"texto":"Visualizar y calcular las dimensiones, tamaños, formas y tolerancias de los montajes y piezas a trabajar, basándose en especificaciones técnicas."},{"consecutivo":3,"texto":"Verificar las dimensiones del producto para establecer la precisión y el funcionamiento correcto de conformidad con especificaciones técnicas, utilizando instrumentos y medidores de precisión tales como micrómetros, nonios, calibradores, manómetros, comparadores ópticos y otros instrumentos de medición especializados."},{"consecutivo":4,"texto":"Utilizar elementos de protección personal y aplicar las normas de seguridad industrial y salud en el trabajo."},{"consecutivo":5,"texto":"Fabricar, ajustar, montar, reparar e instalar cerraduras y piezas de cerraduras, además de fabricar llaves, cambiar guardas y realizar cambios de combinaciones a cajas fuertes."},{"consecutivo":6,"texto":"Construir, adaptar y ensamblar piezas para reparar los patrones de metal fundido en la fabricación de núcleos, placas clisés y moldes."},{"consecutivo":7,"texto":"Reparar y modificar herramientas y piezas metálicas para medir, colocar y sujetar partes de metal o piezas fundidas y disponerlas en las máquinas herramientas."},{"consecutivo":8,"texto":"Situar, asegurar y medir el metal a trabajar para disponer el maquinado en la fabricación de piezas, repuestos y elementos para motores y máquinas."},{"consecutivo":9,"texto":"Instalar, manejar y mantener máquinas herramientas convencionales para realizar operaciones de maquinado con precisión como cortar, tornear, aplanar, taladrar, perforar, rectificar, mandrilar, pulir o dar forma por otros medios a las piezas de trabajo."},{"consecutivo":10,"texto":"Preparar plantillas, bosquejos y determinar los procesos de trabajo para trazar en la pieza de metal líneas y puntos de referencia para guía de otros trabajadores encargados de cortar, tornear, fresar, pulir y trabajar de otras formas el metal."},{"consecutivo":11,"texto":"Ajustar, fijar y ensamblar las diferentes piezas, partes y subensambles de metal en la fabricación y reparación de mandriles, accesorios y calibradores para uso de herramientas manuales o eléctricas."},{"consecutivo":12,"texto":"Mantener, reparar, calibrar y verificar partes maquinadas de conformidad con especificaciones utilizando instrumentos medidores de precisión."},{"consecutivo":13,"texto":"Instalar, reparar y mantener cerraduras y dispositivos de cajas fuertes y bóvedas acorazados en bancos u otros establecimientos."},{"consecutivo":14,"texto":"Ajustar y operar máquinas para fabricar piezas grandes y pequeñas utilizando moldes, modelos, cajas de moldeo y herramientas manuales sobre un banco, fosas o en el suelo de la fundición."},{"consecutivo":15,"texto":"Fabricar, mantener, reparar y probar herramientas, troqueles, matrices, mandriles, calibradores y soportes utilizando herramientas manuales y mecánicas que garanticen su operación."},{"consecutivo":16,"texto":"Disponer y ensamblar partes para fabricar moldes para el procesamiento del metal, plástico y otros procesos de producción."},{"consecutivo":17,"texto":"Ajustar y modificar herramientas, placas y piezas para reparar armas, de acuerdo con especificaciones técnicas."},{"consecutivo":18,"texto":"Fabricar y recubrir machos con materiales protectores para ser usados en moldes y cocinar en hornos proporcionando huecos o cavidades en las piezas a fundir."},{"consecutivo":19,"texto":"Operar una variedad de máquinas y herramientas para cortar, tornear, fresar, pulir, taladrar y afilar el metal de acuerdo con dimensiones y acabados establecidos."},{"consecutivo":20,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"72220.001","nombre":"Ajustador de calibradores / Ajustadora de calibradores"},{"codigo":"72220.002","nombre":"Ajustador de mandriles / Ajustadora de mandriles"},{"codigo":"72220.003","nombre":"Ajustador de mandriles y calibradores / Ajustadora de mandriles y calibradores"},{"codigo":"72220.004","nombre":"Ajustador de troqueles y matrices / Ajustadora de troqueles y matrices"},{"codigo":"72220.005","nombre":"Ajustador herramentista de matrices / Ajustadora herramentista de matrices"},{"codigo":"72220.006","nombre":"Ajustador modelista de fundición / Ajustadora modelista de fundición"},{"codigo":"72220.007","nombre":"Ajustador montador de armas / Ajustadora montadora de armas"},{"codigo":"72220.008","nombre":"Armero / Armera"},{"codigo":"72220.009","nombre":"Cerrajero / Cerrajera"},{"codigo":"72220.010","nombre":"Cerrajero de fabricación de puertas y ventanas / Cerrajera de fabricación de puertas y ventanas"},{"codigo":"72220.011","nombre":"Cerrajero de llaves y cerraduras / Cerrajera de llaves y cerraduras"},{"codigo":"72220.012","nombre":"Cortador trazador de lámina de metal / Cortadora trazadora de lámina de metal"},{"codigo":"72220.013","nombre":"Fabricante de brazos de grúas o mandriles"},{"codigo":"72220.014","nombre":"Fabricante de herramientas"},{"codigo":"72220.015","nombre":"Fabricante de troqueles"},{"codigo":"72220.016","nombre":"Fabricante de moldes de metal"},{"codigo":"72220.017","nombre":"Fabricante de moldes de procesamiento de plástico"},{"codigo":"72220.018","nombre":"Fabricante de plantillas"},{"codigo":"72220.019","nombre":"Fabricante de moldes de cerámica de fundición"},{"codigo":"72220.020","nombre":"Herramentista"},{"codigo":"72220.021","nombre":"Matricero / Matricera"},{"codigo":"72220.022","nombre":"Matricero ajustador / Matricera ajustadora"},{"codigo":"72220.023","nombre":"Matricero de procesamiento de plásticos / Matricera de procesamiento de plásticos"},{"codigo":"72220.024","nombre":"Mecánico ajustador de estampado / Mecánica ajustadora de estampado"},{"codigo":"72220.025","nombre":"Mecánico ajustador de herramientas con punta diamante / Mecánica ajustadora de herramientas con punta diamante"},{"codigo":"72220.026","nombre":"Mecánico de armamento / Mecánica de armamento"},{"codigo":"72220.027","nombre":"Mecánico matricero / Mecánica matricera"},{"codigo":"72220.028","nombre":"Modelista de metal"},{"codigo":"72220.029","nombre":"Modelista matricero / Modelista matricera"},{"codigo":"72220.030","nombre":"Operario ajustador de máquinas / Operaria ajustadora de máquinas"},{"codigo":"72220.031","nombre":"Operario de fabricación moldes y matrices / Operaria de fabricación moldes y matrices"},{"codigo":"72220.032","nombre":"Reparador de armas / Reparadora de armas"},{"codigo":"72220.033","nombre":"Reparador de bóvedas de seguridad / Reparadora de bóvedas de seguridad"},{"codigo":"72220.034","nombre":"Reparador de cajas fuertes y bóvedas de seguridad / Reparadora de cajas fuertes y bóvedas de seguridad"},{"codigo":"72220.035","nombre":"Trazador de metales / Trazadora de metales"}],"conocimientos":[{"id":"11","nombre":"Diseño"},{"id":"10","nombre":"Ingeniería y tecnología"},{"id":"35","nombre":"Interpretación de planos"},{"id":"38","nombre":"Mantenimiento"},{"id":"13","nombre":"Mecánica y metalistería"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"36","nombre":"Ensamble"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"26","nombre":"Reparación"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"31226","nombre":"Supervisores de fabricación y tratamiento de productos mecánicos, metálicos y minerales / Supervisoras de fabricación y tratamiento de productos mecánicos, metálicos y minerales"},{"codigo":"31350","nombre":"Controladores de procesos de producción y tratamiento de metales / Controladoras de procesos de producción y tratamiento de metales"},{"codigo":"72230","nombre":"Ajustadores y operadores de máquinas herramientas / Ajustadoras y operadoras de máquinas herramientas"},{"codigo":"72240","nombre":"Pulidores de metales y afiladores de herramientas / Pulidoras de metales y afiladores de herramientas"}],"area_principal":{"sigla":"FAMA","nombre":"Fabricación, transformación de materiales, instalación, mantenimiento y reparación"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"7222","ciuo08_obs":"Denominaciones completas","cno_codigo":"8211*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"7223*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"8311*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8312*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8344*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8372*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Ajustadores y operadores de máquinas herramientas / Ajustadoras y operadoras de máquinas herramientas', '72230', 'Fabricación, transformación de materiales, instalación, mantenimiento y reparación', 2, false, '{"codigo":"72230","nombre":"Ajustadores y operadores de máquinas herramientas / Ajustadoras y operadoras de máquinas herramientas","descripcion":"Regulan y operan una variedad de máquinas y herramientas convencionales semiautomáticas o automáticas que cortan y pulen partes o productos de metal o materiales similares con dimensiones precisas, cumpliendo la normativa de seguridad y medio ambiente. Inspeccionan las partes o piezas mecanizadas para mantener estándares de control de calidad. Se pueden desempeñar en empresas metalmecánicas, compañías fabricantes de maquinaria, equipos mecánicos, motores para vehículos, partes para carros, motocicletas y aeronaves, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"72","nombre":"OFICIALES Y OPERARIOS DE LA METALURGIA; MECÁNICOS Y REPARADORES DE MÁQUINAS Y AFINES"},"subgrupo":{"codigo":"722","nombre":"Herreros, herramentistas y afines"},"grupo_primario":{"codigo":"7223","nombre":"Ajustadores y operadores de máquinas herramientas"}},"funciones":[{"consecutivo":1,"texto":"Alistar materia prima para procesar, fijar y ensamblar los componentes de la maquina antes de iniciar la labor utilizando herramientas mecánicas o a mano."},{"consecutivo":2,"texto":"Alistar herramientas y máquinas para cortar y pulir partes o productos de metal o materiales similares con dimensiones precisas."},{"consecutivo":3,"texto":"Operar y monitorear máquinas y herramientas convencionales para trabajar metal en operaciones repetitivas como cortar, tornear, fresar, pulir, taladrar, afilar, entre otras de acuerdo con dimensiones y acabados establecidos."},{"consecutivo":4,"texto":"Operar y monitorear prensas u otras máquinas para ejecutar forjado en frío o caliente, por estirado, curvado, moldeado, cortado, doblado y estampado, y ejecutar otras operaciones para dar forma al metal."},{"consecutivo":5,"texto":"Operar y monitorear máquinas, herramientas y hornos para fundir, moldear y vaciar metal ferroso y no ferroso para producir piezas y productos."},{"consecutivo":6,"texto":"Operar y monitorear máquinas y herramientas para juntar y adaptar materiales en piezas de metal u otros materiales de acuerdo con requerimiento técnico."},{"consecutivo":7,"texto":"Lijar, recortar, pulir y limpiar productos en su forma final usando herramientas, maquinas o de forma manual."},{"consecutivo":8,"texto":"Mantener, reparar y calibrar instrumentos medidores de precisión de acuerdo con especificaciones técnicas."},{"consecutivo":9,"texto":"Realizar mantenimiento de primer nivel, que involucra: limpieza, lubricación, ajustes básicos y cambio de accesorios autorizados a máquinas y herramientas."},{"consecutivo":10,"texto":"Ajustar y regular diversas clases de máquinas y herramientas para ser usadas en la fabricación en serie de piezas de metal."},{"consecutivo":11,"texto":"Utilizar elementos de protección personal y aplicar normas de medio ambiente, seguridad industrial y salud en el trabajo."},{"consecutivo":12,"texto":"Inspeccionar las piezas de trabajo o dimensiones del producto para establecer la precisión y conformidad de acuerdo con las especificaciones técnicas utilizando instrumentos y medidores de precisión tales como micrómetros, nonios, calibradores, manómetros, comparadores ópticos y otros instrumentos de medición especializados."},{"consecutivo":13,"texto":"Observar el funcionamiento de las máquinas para descubrir defectos en las piezas de trabajo o en las propias máquinas o herramientas para reportar al supervisor sobre lo detectado."},{"consecutivo":14,"texto":"Revisar la calidad de los productos fabricados en forma visual o usando patrones e instrumentos para detectar conformidades e inconformidades de acuerdo con especificaciones técnicas."},{"consecutivo":15,"texto":"Interpretar las planchas, dibujos, diagramas y tablas o estudiar muestras para determinar las operaciones a realizar."},{"consecutivo":16,"texto":"Regular y operar una variedad de máquinas y herramientas para realizar operaciones de maquinado con precisión, incluyendo las de control numérico, como torno automático, fresadora, taladradora, cepilladora, mandriladora o rectificadora."},{"consecutivo":17,"texto":"Colocar piezas de metal en hornos utilizando tenazas manuales o grúa, y retirarlas cuando el color del metal indique la temperatura de forjado o alimentar y descargar el horno con transportadores automáticos."},{"consecutivo":18,"texto":"Colocar y ajustar troqueles sobre el yunque de la máquina de forjado utilizando grúa aérea o herramientas manuales."},{"consecutivo":19,"texto":"Operar y atender máquinas automáticas o multipropósito, incluyendo máquinas trefiladoras para producir partes o productos de metal, como alambre, mallas, cestas de metal, cremalleras, ganchos, tubería y otros productos de metal."},{"consecutivo":20,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"72230.001","nombre":"Ajustador de máquinas herramientas / Ajustadora de máquinas herramientas"},{"codigo":"72230.002","nombre":"Ajustador de máquinas herramientas de control numérico / Ajustadora de máquinas herramientas de control numérico"},{"codigo":"72230.003","nombre":"Ajustador o montador de máquinas y herramientas / Ajustadora o montadora de máquinas y herramientas"},{"codigo":"72230.004","nombre":"Ajustador o preparador de máquinas y herramientas / Ajustadora o preparadora de máquinas y herramientas"},{"codigo":"72230.005","nombre":"Ajustador operador de esmeriladora de metales / Ajustadora operadora de esmeriladora de metales"},{"codigo":"72230.006","nombre":"Ajustador operador de fresadora de metales / Ajustadora operadora de fresadora de metales"},{"codigo":"72230.008