  ('rol_cuoc', 'Mecánicos de equipo pesado / Mecánicas de equipo pesado', '72332', 'Fabricación, transformación de materiales, instalación, mantenimiento y reparación', 2, false, '{"codigo":"72332","nombre":"Mecánicos de equipo pesado / Mecánicas de equipo pesado","descripcion":"Instalan, ajustan, ensamblan, montan, mantienen y reparan equipo móvil de labor pesada, utilizado en construcción, agricultura, minería y actividades similares. Se pueden desempeñar en empresas que poseen y operan equipo pesado, distribuidores y establecimientos que alquilan y prestan servicios de equipo pesado, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"72","nombre":"OFICIALES Y OPERARIOS DE LA METALURGIA; MECÁNICOS Y REPARADORES DE MÁQUINAS Y AFINES"},"subgrupo":{"codigo":"723","nombre":"Mecánicos y reparadores de máquinas"},"grupo_primario":{"codigo":"7233","nombre":"Mecánicos y reparadores de máquinas agrícolas e industriales"}},"funciones":[{"consecutivo":1,"texto":"Revisar, probar y verificar el funcionamiento de equipos mecánicos y maquinarias como buldóceres, grúas, cargadores, niveladores y demás equipos pesados de construcción, agricultura y minería para detectar fallas y mal funcionamiento."},{"consecutivo":2,"texto":"Desmontar maquinaria y equipo pesado para examinar y diagnosticar fallas, defectos, fugas y desgaste para determinar reparación y mantenimiento requerido."},{"consecutivo":3,"texto":"Probar y manejar maquinaria y equipos reparados para verificar que las reparaciones han sido adecuadas y garantizar su funcionamiento."},{"consecutivo":4,"texto":"Limpiar, lubricar y hacer mantenimiento de rutina a equipos pesados, así como disponer los residuos generados por motores, máquinas y equipos mecánicos para aprovecharlos, reutilizarlos o eliminarlos de forma adecuada."},{"consecutivo":5,"texto":"Ajustar, instalar, revisar, mantener y reparar partes, componentes, sistemas y motores de equipos pesados utilizando herramientas manuales o mecánicas y llevar el registro de estos."},{"consecutivo":6,"texto":"Engrasar, aceitar motores, calibrar equipos pesados y maquinaria fija de acuerdo con especificaciones técnicas del fabricante."},{"consecutivo":7,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"72332.001","nombre":"Ajustador de maquinaria agrícola / Ajustadora de maquinaria agrícola"},{"codigo":"72332.002","nombre":"Ajustador de maquinaria pesada / Ajustadora de maquinaria pesada"},{"codigo":"72332.003","nombre":"Ajustador de máquinas agrícolas / Ajustadora de máquinas agrícolas"},{"codigo":"72332.004","nombre":"Ajustador de máquinas de minería / Ajustadora de máquinas de minería"},{"codigo":"72332.005","nombre":"Ajustador montador de maquinaria agrícola / Ajustadora montadora de maquinaria agrícola"},{"codigo":"72332.006","nombre":"Ajustador montador de maquinaria pesada / Ajustadora montadora de maquinaria pesada"},{"codigo":"72332.007","nombre":"Mecánico de draga / Mecánica de draga"},{"codigo":"72332.008","nombre":"Mecánico de equipo de construcción / Mecánica de equipo de construcción"},{"codigo":"72332.009","nombre":"Mecánico de equipo de excavación / Mecánica de equipo de excavación"},{"codigo":"72332.010","nombre":"Mecánico de equipo fijo agrícola / Mecánica de equipo fijo agrícola"},{"codigo":"72332.011","nombre":"Mecánico de equipo móvil pesado de minería / Mecánica de equipo móvil pesado de minería"},{"codigo":"72332.012","nombre":"Mecánico de equipo pesado / Mecánica de equipo pesado"},{"codigo":"72332.013","nombre":"Mecánico de equipo pesado con motor diésel / Mecánica de equipo pesado con motor diésel"},{"codigo":"72332.014","nombre":"Mecánico de equipo pesado de minería / Mecánica de equipo pesado de minería"},{"codigo":"72332.015","nombre":"Mecánico de equipo pesado de minería móvil / Mecánica de equipo pesado de minería móvil"},{"codigo":"72332.016","nombre":"Mecánico de m