  ('rol_cuoc', 'Mecánicos de maquinaria textil, confección, cuero, calzado y marroquinería / Mecánicas de maquinaria textil, confección, cuero, calzado y marroquinería', '72333', 'Fabricación, transformación de materiales, instalación, mantenimiento y reparación', 2, false, '{"codigo":"72333","nombre":"Mecánicos de maquinaria textil, confección, cuero, calzado y marroquinería / Mecánicas de maquinaria textil, confección, cuero, calzado y marroquinería","descripcion":"Asesoran el montaje en producción, brindan asistencia, ajustan, instalan y realizan mantenimientos preventivos y correctivos a los equipos y maquinaria de la industria textil, de confección, de cuero, de calzado y marroquinería. Se pueden desempeñar en empresas de fabricación textil, confección, cuero, calzado y marroquinería, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"72","nombre":"OFICIALES Y OPERARIOS DE LA METALURGIA; MECÁNICOS Y REPARADORES DE MÁQUINAS Y AFINES"},"subgrupo":{"codigo":"723","nombre":"Mecánicos y reparadores de máquinas"},"grupo_primario":{"codigo":"7233","nombre":"Mecánicos y reparadores de máquinas agrícolas e industriales"}},"funciones":[{"consecutivo":1,"texto":"Reparar, ajustar, instalar, reparar y mantener motores, equipos y maquinaria de la industria textil, confección, cuero, calzado y marroquinería."},{"consecutivo":2,"texto":"Desmontar, acondicionar, instalar y reparar maquinaria y equipos de la industria textil, confección, cuero, calzado y marroquinería."},{"consecutivo":3,"texto":"Revisar, manejar y probar maquinaria y equipos reparados para verificar el funcionamiento de las reparaciones efectuadas conforme a estándares y especificaciones."},{"consecutivo":4,"texto":"Examinar piezas, Identificar fallas, irregularidades y mal funcionamiento de maquinaria y equipos relacionados con fugas y desgaste excesivo."},{"consecutivo":5,"texto":"Brindar asistencia técnica de maquinaria y equipo en los procesos de la industria textil, confección, cuero, calzado y marroquinería y recomendar modificaciones y/o reemplazos de máquinas y equipos."},{"consecutivo":6,"texto":"Engrasar, aceitar y calibrar equipos, motores y maquinaria de la industria textil, confección, cuero, calzado y marroquinería de acuerdo con especificaciones técnicas."},{"consecutivo":7,"texto":"Ajustar y acondicionar maquinaria y equipos en líneas de producción y mantener registros de las reparaciones y el mantenimiento realizados."},{"consecutivo":8,"texto":"Disponer adecuadamente de los residuos generados por motores, máquinas y equipos mecánicos, con fines de aprovechamiento, reutilización o eliminación."},{"consecutivo":9,"texto":"Coordinar y hacer mantenimiento preventivo y correctivo de maquinaria y equipos de la industria textil, confección, cuero, calzado y marroquinería."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"72333.001","nombre":"Ajustador de maquinaria textil / Ajustadora de maquinaria textil"},{"codigo":"72333.002","nombre":"Ajustador de máquinas de tejido de punto / Ajustadora de máquinas de tejido de punto"},{"codigo":"72333.003","nombre":"Ajustador de telares / Ajustadora de telares"},{"codigo":"72333.004","nombre":"Ajustador montador de maquinaria textil / Ajustadora montadora de maquinaria textil"},{"codigo":"72333.005","nombre":"Lubricador de telares / Lubricadora de telares"},{"codigo":"72333.006","nombre":"Mecánico de cardas / Mecánica de cardas"},{"codigo":"72333.007","nombre":"Mecánico de continuas de hilar / Mecánica de continuas de hilar"},{"codigo":"72333.008","nombre":"Mecánico de hiladoras / Mecánica de hiladoras"},{"codigo":"72333.009","nombre":"Mecánico de mantenimiento de máquinas confección / Mecánica de mantenimiento de máquinas confección"},{"codigo":"72333.010","nombre":"Mecánico de mantenimiento de máquinas de estiraje / Mecánica de mantenimiento de máquinas de es