  ('rol_cuoc', 'Reparadores de bicicletas y afines / Reparadoras de bicicletas y afines', '72340', 'Fabricación, transformación de materiales, instalación, mantenimiento y reparación', 2, false, '{"codigo":"72340","nombre":"Reparadores de bicicletas y afines / Reparadoras de bicicletas y afines","descripcion":"Reparan, mantienen, calibran o fabrican equipos mecánicos y afines de bicicletas, triciclos, cochecitos de niño, sillas de ruedas y medios de transporte no mecanizados similares. Se pueden desempeñar en bicicleterías, talleres de reparación y mantenimiento especializado, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"72","nombre":"OFICIALES Y OPERARIOS DE LA METALURGIA; MECÁNICOS Y REPARADORES DE MÁQUINAS Y AFINES"},"subgrupo":{"codigo":"723","nombre":"Mecánicos y reparadores de máquinas"},"grupo_primario":{"codigo":"7234","nombre":"Reparadores de bicicletas y afines"}},"funciones":[{"consecutivo":1,"texto":"Revisar bicicletas y otros medios de transporte no motorizados para determinar la clase de reparación y acondicionamiento que requieren."},{"consecutivo":2,"texto":"Sustituir, reparar y reemplazar partes, piezas y componentes dañados o defectuosos en bicicletas y otros medios de transporte no motorizados."},{"consecutivo":3,"texto":"Ensamblar bicicletas, sillas de ruedas, equipos similares y otros medios de transporte no motorizados nuevos."},{"consecutivo":4,"texto":"Probar los productos, partes y componentes reparados para verificar su correcto funcionamiento en bicicletas y otros medios de transporte no motorizados."},{"consecutivo":5,"texto":"Realizar actividades de limpieza y mantenimiento preventivo y correctivo en accesorios y piezas de bicicletas y equipos similares no motorizados."},{"consecutivo":6,"texto":"Pintar accesorios y piezas de bicicletas y equipos similares no motorizados de acuerdo con requerimientos del cliente."},{"consecutivo":7,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"72340.001","nombre":"Mecánico de bicicletas / Mecánica de bicicletas"},{"codigo":"72340.002","nombre":"Reparador de bicicletas / Reparadora de bicicletas"},{"codigo":"72340.003","nombre":"Reparador de cochecitos de niño / Reparadora de cochecitos de niño"},{"codigo":"72340.004","nombre":"Reparador de silla de ruedas / Reparadora de silla de ruedas"}],"conocimientos":[{"id":"38","nombre":"Mantenimiento"},{"id":"13","nombre":"Mecánica y metalistería"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"17","nombre":"Análisis de necesidades"},{"id":"36","nombre":"Ensamble"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"26","nombre":"Reparación"},{"id":"19","nombre":"Selección de equipo"}],"ocupaciones_afines":[{"codigo":"72310","nombre":"Mecánicos y reparadores de vehículos de motor / Mecánicas y reparadoras de vehículos de motor"}],"area_principal":{"sigla":"FAMA","nombre":"Fabricación, transformación de materiales, instalación, mantenimiento y reparación"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"7234","ciuo08_obs":"Denominaciones completas","cno_codigo":"8416*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Mecánicos y reparadores de instrumentos de precisión / Mecánicas y reparadoras de instrumentos de precisión', '73110', 'Fabricación, transformación de materiales, instalación, mantenimiento y reparación', 2, false, '{"codigo":"73110","nombre":"Mecánicos y reparadores de instrumentos de precisión / Mecánicas y reparadoras de instrumentos de precisión","descripcion":"Fabrican, calibran, reparan, mantienen, ajustan e instalan relojes mecánicos de todo tipo; y otros instrumentos y aparatos de precisión que tengan aplicaciones náuticas, meteorológicas, ópticas y de otra índole, y los ajustan para su correcto funcionamiento. Se pueden desempeñar en empresas de ingeniería, servicios, consultoría, procesos industriales, industrias de manufactura, relojerías, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"73","nombre":"ARTESANOS Y OPERARIOS DE LAS ARTES GRÁFICAS Y AFINES"},"subgrupo":{"codigo":"731","nombre":"Artesanos de precisión, alfarería, cerámica y vidrio"},"grupo_primario":{"codigo":"7311","nombre":"Mecánicos y reparadores de instrumentos de precisión"}},"funciones":[{"consecutivo":1,"texto":"Examinar, reparar, limpiar, ajustar y sincronizar los mecanismos de instrumentos de medición del tiempo como relojes de todo tipo de acuerdo con técnicas de precisión."},{"consecutivo":2,"texto":"Ajustar los reguladores de tiempo utilizando herramientas e instrumentos como: calibres, cronómetros comparadores, pinzas, entre otros."},{"consecutivo":3,"texto":"Limpiar, lavar, secar, lubricar y brillar las piezas internas y otras partes de los relojes utilizando técnica manual, soluciones y máquinas ultrasónicas o mecánicas."},{"consecutivo":4,"texto":"Verificar la exactitud y el funcionamiento de los relojes e instrumentos de precisión utilizando medidores y otros instrumentos electrónicos."},{"consecutivo":5,"texto":"Determinar la exactitud de medidores, calibradores, indicadores y otros instrumentos de registro o control para localizar componentes defectuosos o verificar el cumplimiento de las especificaciones técnicas."},{"consecutivo":6,"texto":"Calibrar productos, instrumentos o escalas utilizando herramientas manuales, computadores o instrumentos electrónicos."},{"consecutivo":7,"texto":"Inspeccionar componentes, conexiones, mecanismos e instrumentos de precisión para detectar defectos y determinar la clase de reparación que requieren."},{"consecutivo":8,"texto":"Montar, probar, calibrar y ajustar instrumentos electrónicos, mercuriales, aneroides, mecánicos y otro tipo de instrumentos meteorológicos para verificar el cumplimiento de las especificaciones y diagramas esquemáticos, utilizando voltímetros, osciloscopios, medidores de tubo y otros instrumentos analíticos."},{"consecutivo":9,"texto":"Realizar mantenimiento preventivo y correctivo de instrumentos ópticos, de precisión, entre otros, de acuerdo con plan y requisitos técnicos."},{"consecutivo":10,"texto":"Inspeccionar los productos reparados para verificar su correcto funcionamiento de acuerdo con análisis de satisfacción."},{"consecutivo":11,"texto":"Verificar que los aparatos montados cumplan las especificaciones y asegurar su funcionamiento y sensibilidad con arreglo a las instrucciones pertinentes realizando pruebas normalizadas."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"73110.001","nombre":"Ajustador de balanzas / Ajustadora de balanzas"},{"codigo":"73110.002","nombre":"Ajustador de equipos de meteorología / Ajustadora de equipos de meteorología"},{"codigo":"73110.003","nombre":"Ajustador óptico de precisión / Ajustadora óptica de precisión"},{"codigo":"73110.004","nombre":"Calibrador de instrumentos de precisión / Calibradora de instrumentos de precisión"},{"codigo":"73110.005","nombre":"Mecánico de balanzas / Mecánica de balanzas"},{"codigo":"73110.006","nombre":"Mecánico de instrument