  ('rol_cuoc', 'Tipógrafos / Tipógrafas', '73212', 'Literatura y artes gráficas', 2, false, '{"codigo":"73212","nombre":"Tipógrafos / Tipógrafas","descripcion":"Preparan materiales necesarios para procesos de prensa, impresión y representación en medios visuales, teniendo en cuenta parámetros de control de calidad y órdenes de trabajo. Se pueden desempeñar en empresas de impresión comercial, periódicos, revistas, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"73","nombre":"ARTESANOS Y OPERARIOS DE LAS ARTES GRÁFICAS Y AFINES"},"subgrupo":{"codigo":"732","nombre":"Oficiales y operarios de las artes gráficas"},"grupo_primario":{"codigo":"7321","nombre":"Pre-impresores, tipógrafos y afines"}},"funciones":[{"consecutivo":1,"texto":"Manejar linotipias, monotipias y fundidoras de máquinas imprentas según especificaciones técnicas."},{"consecutivo":2,"texto":"Grabar a mano planchas, cilindros, matrices de acero o cobre y componer tipos de ilustraciones para imprimir copias en prensas sencillas."},{"consecutivo":3,"texto":"Llevar a cabo pruebas digitales y químicas a partir de sistemas digitales, así como positivos y negativos de película."},{"consecutivo":4,"texto":"Lubricar prensas, entintar rodillos y operar máquinas tipográficas de impresión."},{"consecutivo":5,"texto":"Preparar moldes de composiciones tipográficas con cartón, cera, madera o neolito para accionarlos en prensas y máquinas manuales de impresión tipográfica."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"73212.001","nombre":"Ajustador operador de máquina fundidora de tipos / Ajustadora operadora de máquina fundidora de tipos"},{"codigo":"73212.002","nombre":"Armador de páginas / Armadora de páginas"},{"codigo":"73212.003","nombre":"Armador de tipografía / Armadora de tipografía"},{"codigo":"73212.004","nombre":"Cajista"},{"codigo":"73212.0