  ('rol_cuoc', 'Impresores de artes gráficas / Impresoras de artes gráficas', '73220', 'Literatura y artes gráficas', 2, false, '{"codigo":"73220","nombre":"Impresores de artes gráficas / Impresoras de artes gráficas","descripcion":"Preparan y operan diversos tipos de máquinas litográficas, flexográficas, serigráficas, de impresión digital, entre otras, para imprimir piezas gráficas, publicomerciales, editoriales y empaques como periódicos, libros, impresiones de seguridad sobre diferentes materiales y textiles. Se pueden desempeñar en empresas de impresión comercial, periódicos, revistas, en empresas públicas y privadas que cuentan con departamentos de publicaciones entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"73","nombre":"ARTESANOS Y OPERARIOS DE LAS ARTES GRÁFICAS Y AFINES"},"subgrupo":{"codigo":"732","nombre":"Oficiales y operarios de las artes gráficas"},"grupo_primario":{"codigo":"7322","nombre":"Impresores de artes gráficas"}},"funciones":[{"consecutivo":1,"texto":"Verificar insumos, materiales, estado de las máquinas y equipos de impresión requeridas para el cumplimiento de la orden de trabajo determinando especificaciones, secuencias de color, cantidades requeridas y tiempo de producción."},{"consecutivo":2,"texto":"Preparar y montar formas impresoras en diferentes sistemas de impresión y realizar los ajustes necesarios para el alistamiento de la máquina."},{"consecutivo":3,"texto":"Instalar, ajustar, limpiar y vigilar mecanismos de alimentación, de salida, sistemas de entintado y otras funciones según sistemas de impresión."},{"consecutivo":4,"texto":"Mezclar tintas, disolventes, ajustar y controlar alimentación y color durante los procesos de impresión según especificaciones de funcionamiento del sistema de impresión."},{"consecutivo":5,"texto":"Operar, programar, controlar y hacer los ajustes requeridos a las máquinas y equipos de impresión durante el proceso de producción."},{"consecutivo":6,"texto":"Vigilar, evaluar, verificar y corregir la calidad del producto impreso durante el proceso de producción, teniendo como referencia la muestra patrón y los parámetros normativos de calidad."},{"consecutivo":7,"texto":"Realizar mantenimiento preventivo y limpieza de máquinas y equipos en los diferentes sistemas de impresión."},{"consecutivo":8,"texto":"Alistar finalización de archivos digitales mediante el uso de programas informáticos especializados para la impresión digital"},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"73220.001","nombre":"Operario de plancha para impresión / Operaria de plancha para impresión"},{"codigo":"73220.002","nombre":"Impresor de textiles / Impresora de textiles"},{"codigo":"73220.003","nombre":"Impresor digital / Impresora digital"},{"codigo":"73220.004","nombre":"Impresor digital de gran formato / Impresora digital de gran formato"},{"codigo":"73220.005","nombre":"Impresor en artes gráficas / Impresora en artes gráficas"},{"codigo":"73220.006","nombre":"Impresor en serigrafía / Impresora en serigrafía"},{"codigo":"73220.007","nombre":"Impresor flexográfico / Impresora flexográfica"},{"codigo":"73220.008","nombre":"Inspector de control de calidad de impresión / Inspectora de control de calidad de impresión"},{"codigo":"73220.009","nombre":"Litógrafo de multilith / Litógrafa de multilith"},{"codigo":"73220.010","nombre":"Operador de alimentación en impresión / Operadora de alimentación en impresión"},{"codigo":"73220.013","nombre":"Operador de impresora de serigrafía / Operadora de impresora de serigrafía"},{"codigo":"73220.014","nombre":"Operador de impresora flexográfica / Operadora de impresora flexográfica"},{"codigo":"73220.015","nombre":"Operador de impresora láser / Operadora de impresora láser"},{"codigo":"73220.016","nombre":"Operador de impresora multilith / Operadora de impresora multilith"},{"codigo":"73220.017