  ('rol_cuoc', 'Tejedores con agujas / Tejedoras con agujas', '73320', 'Artes visuales, plásticas y del patrimonio cultural', 2, false, '{"codigo":"73320","nombre":"Tejedores con agujas / Tejedoras con agujas","descripcion":"Elaboran objetos utilitarios y decorativos con fibras animales, vegetales o sintéticas de manera manual ayudados con diferentes tipos de agujas y técnicas de tejido dentro de las que se encuentran: el tejido de punto o tricot, el ganchillo o crochet y el tejido con aguja de ojo, que para el caso y de acuerdo con la etnia, se elaboran diferentes tipos de puntadas y diseños. Mediante el ejercicio de esta función se obtienen mochilas, bolsos, guantes, prendas de vestir, gorros, ruanas y chales, entre otros. Se pueden desempeñar en talleres, empresas u organizaciones artesanales, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"73","nombre":"ARTESANOS Y OPERARIOS DE LAS ARTES GRÁFICAS Y AFINES"},"subgrupo":{"codigo":"733","nombre":"Tejedores"},"grupo_primario":{"codigo":"7332","nombre":"Tejedores con agujas"}},"funciones":[{"consecutivo":1,"texto":"Planear producción artesanal según tipo de producto y métodos técnicos."},{"consecutivo":2,"texto":"Interpretar y manejar diagramas y patrones de tejido en aguja de acuerdo con fibra natural, diseño, orden de producción y contexto cultural."},{"consecutivo":3,"texto":"Dar acabado a los productos y las prendas tejidas con aguja según requerimiento técnico y tipo de material."},{"consecutivo":4,"texto":"Determinar el grosor de la aguja y las combinaciones de colores y puntadas de acuerdo con las características del material y tipo de puntada."},{"consecutivo":5,"texto":"Elaborar producto artesanal con dos agujas, aguja crochet, ganchillo o con aguja de ojo, bolillos, anudado, ensartado, según diseño requerimiento técnico y contexto cultural."},{"consecutivo":6,"texto":"Tinturar fibras con colorantes naturales o sintéticos, según ficha de tintorería, muestra de color y requerimiento técnico."},{"consecutivo":7,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"73320.001","nombre":"Anudador / Anudadora"},{"codigo":"73320.002","nombre":"Anudador de fibras textiles / Anudadora de fibras textiles"},{"codigo":"73320.003","nombre":"Artesano de alfombras de nudo / Artesana de alfombras de nudo"},{"codigo":"73320.004","nombre":"Artesano de hilados de textiles / Artesana de hilados de textiles"},{"codigo":"73320.005","nombre":"Artesano hilandero / Artesana hilandera"},{"codigo":"73320.006","nombre":"Ganchillero a mano / Ganchillera a mano"},{"codigo":"73320.007","nombre":"Hilandero / Hilandera"},{"codigo":"73320.008","nombre":"Mallero / Mallera"},{"codigo":"73320.009","nombre":"Operario de tejido de punto / Operaria de tejido de punto"},{"codigo":"73320.010","nombre":"Redero / Redera"},{"codigo":"73320.011","nombre":"Tejedor de agujas / Tejedora de agujas"},{"codigo":"73320.012","nombre":"Tejedor de anudado / Tejedora de anudado"},{"codigo":"73320.013","nombre":"Tejedor de punto / Tejedora de punto"},{"codigo":"73320.014","nombre":"Tejedor de redes de pesca manual / Tejedora de redes de pesca manual"}],"conocimientos":[{"id":"54","nombre":"Artesanías"},{"id":"11","nombre":"Diseño"},{"id":"22","nombre":"Educación y capacitación"},{"id":"4","nombre":"Mercadotecnia y publicidad"},{"id":"43","nombre":"Patrimonio cultural"},{"id":"7","nombre":"Producción y procesamiento"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"39","nombre":"Creatividad"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"73310","nombre":"Tejedores con telares / Tejedoras con telar