  ('rol_cuoc', 'Artesanos de papel / Artesanas de papel', '73910', 'Artes visuales, plásticas y del patrimonio cultural', 2, false, '{"codigo":"73910","nombre":"Artesanos de papel / Artesanas de papel","descripcion":"Elaboran máscaras, títeres, lámparas, objetos utilitarios de escritorio, agendas, hojas de papel, cartones, empaques y tarjetas, por medio de la implementación de técnicas tales como papel maché, cartapesta y conformación de papeles y cartones artesanales, a partir de materiales reciclados y de fibras vegetales. Se pueden desempeñar en talleres artesanales, empresas de elaboración artículos en papel, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"73","nombre":"ARTESANOS Y OPERARIOS DE LAS ARTES GRÁFICAS Y AFINES"},"subgrupo":{"codigo":"739","nombre":"Artesanos no clasificados en otros grupos primarios"},"grupo_primario":{"codigo":"7391","nombre":"Artesanos de papel"}},"funciones":[{"consecutivo":1,"texto":"Clasificar papeles y adicionar aglutinantes de acuerdo con las características del objeto artesanal a elaborar."},{"consecutivo":2,"texto":"Eliminar materiales contaminantes que afectan los resultados de la producción artesanal de artículos de papel."},{"consecutivo":3,"texto":"Procesar pulpa de papel a partir de acciones de rasgado, molido y macerado de la misma, de acuerdo con requerimientos técnicos y tipo de producto a elaborar."},{"consecutivo":4,"texto":"Modelar y moldear pulpa de papel y piezas artesanales elaboradas con papel según diseño y técnica de conformado."},{"consecutivo":5,"texto":"Elaborar estructuras soporte de las piezas en papel de acuerdo con las características del objeto artesanal, según diseños y técnicas de cartapesta, plegado y/o calado."},{"consecutivo":6,"texto":"Conformar y prensar hojas para elaborar artículos artesanales en papel de acuerdo con un diseño previo, utilizado herramientas manuales y mecánicas."},{"consecutivo":7,"texto":"Decorar las piezas artesanales en papel con técnicas pictóricas e incrustar materiales complementarios dentro de la pieza u hoja modelada, según características del diseño."},{"consecutivo":8,"texto":"Controlar la densidad de paredes y secado de las hojas de papel o piezas modeladas, para elaborar artículos artesanales en papel de acuerdo con requerimientos técnicos."},{"consecutivo":9,"texto":"Acabar las hojas conformadas u objetos modelados, teniendo presente el uso posterior de los productos artesanales en papel."},{"consecutivo":10,"texto":"Acondicionar material recuperado, según requerimiento técnico."},{"consecutivo":11,"texto":"Adornar producto, según técnicas pictóricas y tipo de material."},{"consecutivo":12,"texto":"Calar material, según técnicas artesanales y tipo de material."},{"consecutivo":13,"texto":"Configurar pieza artesanal, según técnica de modelado manual."},{"consecutivo":14,"texto":"Dibujar propuesta de acuerdo con técnicas de dibujo y requerimientos del diseño."},{"consecutivo":15,"texto":"Grabar material según técnicas artesanales."},{"consecutivo":16,"texto":"Planear producción artesanal de acuerdo con sistema productivo y métodos técnicos."},{"consecutivo":17,"texto":"Reproducir pieza según técnica de moldeo."},{"consecutivo":18,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"73910.001","nombre":"Artesano de artículos de papel y cartón / Artesana de artículos de papel y cartón"},{"codigo":"73910.002","nombre":"Artesano cartapesta / Artesana cartapesta"},{"codigo":"73910.003","nombre":"Artesano de papel maché / Artesana de papel maché"},{"codigo":"73910.004","nombre":"Artesano de trabajos en papel / Artesana de trabajos en papel"},{"codigo":"73910.005","nombre":"Batidor de pulpa de papel / Batidora de pulpa de papel"},{"codigo":"73910.006","nombre":"Operario de equipo batidor de pulpa de papel / Operaria de equipo batidor de pulpa de papel"},{"codigo":"73910.007","nombre":"Papelero / Papelera"},{"codigo":"73910.008","nombre":"Prensador de papel / Prensadora de papel"},{"codigo":"73910.009","nombre":"Trabajador artesanal de papel / Trabajadora artesanal de papel"}],"conocimientos":[{"id":"54","nombre":"Artesanías"},{"id":"11","nombre":"Diseño"},{"id":"77","nombre":"Materiales (vidrio, papel, plástico y madera)"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"17","nombre":"Análisis de necesidades"},{"id":"39","nombre":"Creatividad"},{"id":"2","nombre":"Escucha activa"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"19","nombre":"Selección de equipo"}],"ocupaciones_afines":[{"codigo":"73230","nombre":"Encuadernadores y afines / Encuadernadoras y afines"},{"codigo":"81712","nombre":"Operadores de máquinas para la producción de pulpa / Operadoras de máquinas para la producción de pulpa"}],"area_principal":{"sigla":"AVPP","nombre":"Artes visuales, plásticas y del patrimonio cultural"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"7391","ciuo08_obs":"Denominaciones completas","cno_codigo":"5269","cno_obs":"Denominaciones completas"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"9233*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Artesanos del hierro y otros metales / Artesanas del hierro y otros metales', '73920', 'Artes visuales, plásticas y del patrimonio cultural', 2, false, '{"codigo":"73920","nombre":"Artesanos del hierro y otros metales / Artesanas del hierro y otros metales","descripcion":"Diseñan, cortan, modelan, moldean, ensamblan y conforman piezas utilitarias, decorativas o artísticas a partir de la transformación del metal en barra o en láminas con el uso de técnicas de modelado en frío, caliente y soldadura. Se pueden desempeñar en talleres de artesanías en metal, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"73","nombre":"ARTESANOS Y OPERARIOS DE LAS ARTES GRÁFICAS Y AFINES"},"subgrupo":{"codigo":"739","nombre":"Artesanos no clasificados en otros grupos primarios"},"grupo_primario":{"codigo":"7392","nombre":"Artesanos del hierro y otros metales"}},"funciones":[{"consecutivo":1,"texto":"Calcular materiales, insumos y planear todas las unidades de producción artesanal según el tipo de productos y requerimientos técnicos."},{"consecutivo":2,"texto":"Alistar moldes para fundir hierro y otros metales en la elaboración artesanal de productos, según técnicas de metalistería."},{"consecutivo":3,"texto":"Acabar y decorar productos artesanales en hierro y otros metales aplicando pátinas e insumos según requerimientos de diseño, características del material y especificaciones técnicas."},{"consecutivo":4,"texto":"Alistar fragua, combustible, herramientas e insumos para el modelado del hierro y otros metales mediante técnicas de percusión en frío y caliente."},{"consecutivo":5,"texto":"Realizar uniones mediante técnicas de ensamble y soldadura, eliminando rebabas y sobrantes del hierro y otros metales, con la ayuda de herramientas manuales."},{"consecutivo":6,"texto":"Preparar metal para elaborar productos artesanales, según requerimientos de diseño, características y técnica de transformación de metalistería."},{"consecutivo":7,"texto":"Crear bosquejos, plantillas o dibujos para elaborar objetos artesanales en hierro y otros metales, según características de diseño y planos de producción."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"73920.001","nombre":"Artesano batidor de metal / Artesana batidora de metal"},{"codigo":"73920.002","nombre":"Artesano burilador / Artesana buriladora"},{"codigo":"73920.003","nombre":"Artesano cincelador / Artesana cinceladora"},{"codigo":"73920.004","nombre":"Artesano de juguetes de metal / Artesana de juguetes de metal"},{"codigo":"73920.005","nombre":"Artesano de la forja / Artesana de la forja"},{"codigo":"73920.006","nombre":"Artesano del bronce / Artesana del bronce"},{"codigo":"73920.007","nombre":"Artesano del cobre / Artesana del cobre"},{"codigo":"73920.008","nombre":"Artesano del hierro y otros metales / Artesana del hierro y otros metales"},{"codigo":"73920.009","nombre":"Artesano doblador de alambre / Artesana dobladora de alambre"},{"codigo":"73920.010","nombre":"Artesano esmaltador de metales / Artesana esmaltadora de metales"},{"codigo":"73920.011","nombre":"Artesano fundidor de campanas / Artesana fundidora de campanas"},{"codigo":"73920.012","nombre":"Artesano herrero / Artesana herrera"},{"codigo":"73920.013","nombre":"Artesano soldador / Artesana soldadora"},{"codigo":"73920.014","nombre":"Artesano de trabajos en metal / Artesana de trabajos en metal"},{"codigo":"73920.015","nombre":"Forjador de objetos artesanales / Forjadora de objetos artesanales"},{"codigo":"73920.016","nombre":"Fundidor de campanas / Fundidora de campanas"},{"codigo":"73920.017","nombre":"Herrero de objetos artesanales / Herrera de objetos artesanales"}],"conocimientos":[{"id":"54","nombre":"Artesanías"},{"id":"11","nombre":"Diseño"},{"id":"13","nombre":"Mecánica y metalistería"},{"id":"7","nombre":"Producción y procesamiento"}],"destrezas":