  ('rol_cuoc', 'Artesanos de las semillas y cortezas vegetales / Artesanas de las semillas y cortezas vegetales', '73930', 'Artes visuales, plásticas y del patrimonio cultural', 2, false, '{"codigo":"73930","nombre":"Artesanos de las semillas y cortezas vegetales / Artesanas de las semillas y cortezas vegetales","descripcion":"Elaboran objetos a partir del procesamiento de hilos de origen vegetal extraídos de hojas, tallos, cortezas y raíces, al igual que la identificación, recolección, selección y procesamiento de semillas y cortezas vegetales algunas veces mezcladas con madera u otros materiales para elaborar bandejas, centros de mesa, cucharas, pasaboqueros, individuales, muñequería, lámparas y accesorios tales como bolsos, collares, pulseras o anillos y demás. Se pueden desempeñar en talleres de tejido artesanal, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"73","nombre":"ARTESANOS Y OPERARIOS DE LAS ARTES GRÁFICAS Y AFINES"},"subgrupo":{"codigo":"739","nombre":"Artesanos no clasificados en otros grupos primarios"},"grupo_primario":{"codigo":"7393","nombre":"Artesanos de las semillas y cortezas vegetales"}},"funciones":[{"consecutivo":1,"texto":"Identificar, recolectar y almacenar semillas, plantas o partes de ellas para la obtención de insumos, de acuerdo con la abundancia en la región, los ciclos de cosecha y condiciones climáticas."},{"consecutivo":2,"texto":"Clasificar, limpiar, acondicionar e inmunizar semillas de acuerdo con el diseño de los productos a elaborar, basándose en técnicas tradicionales de bajo impacto ambiental."},{"consecutivo":3,"texto":"Ensamblar productos artesanales con semillas y dar acabado de acuerdo con el diseño y recomendaciones técnicas."},{"consecutivo":4,"texto":"Tinturar y dar acabado a cortezas vegetales, hilos o semillas según característica de diseño, tipo de material y requerimientos técnicos."},{"consecutivo":5,"texto":"Aplicar técnicas de limpieza, inmunizado, corte, cosido, entrencillado, calado, pulido y ensamble de cortezas vegetales duras y blandas."},{"consecutivo":6,"texto":"Seleccionar, recolectar y almacenar cortezas vegetales de acuerdo con el tipo de producto artesanal a elaborar."},{"consecutivo":7,"texto":"Aplicar técnicas de tejido, retorcido e hilado manual a partir de métodos de anudado o utilizando utensilios adaptados como agujas de hueso, metal o de otros telares."},{"consecutivo":8,"texto":"Preparar recursos y planear producción artesanal según tipo de producto y requerimientos técnicos."},{"consecutivo":9,"texto":"Elaborar bosquejos, dibujos y plantillas de productos artesanales hechos con semillas y cortezas vegetales, según diseño y requerimientos técnicos."},{"consecutivo":10,"texto":"Preparar, mantener y operar maquinarias, equipos y herramientas para trabajar semillas y cortezas vegetales según técnicas artesanales."},{"consecutivo":11,"texto":"Aprovisionar de hilos de origen sintético y materiales complementarios de acuerdo con el diseño del objeto artesanal."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"73930.001","nombre":"Artesano de las semillas / Artesana de las semillas"},{"codigo":"73930.002","nombre":"Artesano de las semillas y cortezas vegetales / Artesana de las semillas y cortezas vegetales"},{"codigo":"73930.003","nombre":"Artesano de los frutos secos / Artesana de los frutos secos"},{"codigo":"73930.004","nombre":"Artesano del coco y el totumo / Artesana del coco y el totumo"},{"codigo":"73930.005","nombre":"Artesano en tagua / Artesana en tagua"},{"codigo":"73930.006","nombre":"Trabajador de marfil vegetal / Trabajadora de marfil vegetal"}],"conocimientos":[{"id":"54","nombre":"Artesanías"},{"id":"11","nombre":"Diseño"},{"id":"44","nombre":"Patrimonio natural"},{"id":"7","nombre":"Producción y procesamiento"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"17","nombre":"Análisis de necesidades"},{"id":"39","nombre":"Creatividad"},{"id":"36","nombre":"Ensamble"},{"id":"2","nombre":"Escucha activa"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"}],"ocupaciones_afines":[{"codigo":"73320","nombre":"Tejedores con agujas / Tejedoras con agujas"},{"codigo":"73410","nombre":"Cesteros y mimbreros / Cesteras y mimbreras"},{"codigo":"73999","nombre":"Artesanos de otros materiales no clasificados en otras ocupaciones / Artesanas de otros materiales no clasificados en otras ocupaciones"}],"area_principal":{"sigla":"AVPP","nombre":"Artes visuales, plásticas y del patrimonio cultural"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"7393","ciuo08_obs":"Denominaciones completas","cno_codigo":"5263*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Artesanos de trabajos en materiales líticos / Artesanas de trabajos en materiales líticos', '73991', 'Artes visuales, plásticas y del patrimonio cultural', 2, false, '{"codigo":"73991","nombre":"Artesanos de trabajos en materiales líticos / Artesanas de trabajos en materiales líticos","descripcion":"Identifican, seleccionan, cortan y disponen bloques de piedra, carbón mineral o sal de roca, con la ayuda de herramientas manuales, electro manuales y neumáticas, para elaborar modelos a escala, piezas utilitarias, decorativas o artísticas, bajo la implementación de técnicas de tallaje, cincelado, pulimento, grabado y/o ensamble. Se pueden desempeñar en talleres líticos, empresas de manufacturas, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"73","nombre":"ARTESANOS Y OPERARIOS DE LAS ARTES GRÁFICAS Y AFINES"},"subgrupo":{"codigo":"739","nombre":"Artesanos no clasificados en otros grupos primarios"},"grupo_primario":{"codigo":"7399","nombre":"Artesanos de otros materiales no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Planear la producción artesanal de productos elaborados con materiales líticos, según el tipo de elaboración y requerimientos técnicos."},{"consecutivo":2,"texto":"Realizar, bosquejos, plantillas o dibujos según diseño y requerimientos técnicos de los materiales que se deben esculpir para la fabricación artesanal de productos con materiales líticos."},{"consecutivo":3,"texto":"Alistar, mantener y operar maquinarias, equipos y herramientas según técnicas artesanales de elaboración de productos con materiales líticos."},{"consecutivo":4,"texto":"Preparar bloques de piedra, carbón mineral o sal de roca y eliminar impurezas de la materia prima a emplear según requerimientos técnicos."},{"consecutivo":5,"texto":"Acabar productos artesanales hechos con materiales líticos, mediante lijas y felpas de brillo según requerimientos y características del diseño."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"73991.001","nombre":"Artesano escultor de piedra / Artesana escultora de piedra"},{"codigo":"73991.002","nombre":"Artesano tallador de carbón / Artesana talladora de carbón"},{"codigo":"73991.003","nombre":"Artesano tallador de materiales líticos / Artesana talladora de materiales líticos"},{"codigo":"73991.004","nombre":"Artesano tallador de piedra / Artesana talladora de piedra"},{"codigo":"73991.005","nombre":"Artesano tallador de sal de roca / Artesana talladora de sal de roca"},{"codigo":"73991.006","nombre":"Artesano de trabajo en materiales líticos / Artesana de trabajo en materiales líticos"},{"codigo":"73991.007","nombre":"Artesano pulidor de carbón / Artesana pulidora de carbón"}],"conocimientos":[{"id":"54","nombre":"Artesanías"},{"id":"11","nombre":"Diseño"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"17","nombre":"Análisis de necesidades"},{"id":"39","nombre":"Creatividad"},{"id":"2","nombre":"Escucha activa"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"19","nombre":"Selección de equipo"}],"ocupaciones_afines":[{"codigo":"73999","nombre":"Artesanos de otros materiales no clasificados en otras ocupaciones / Artesanas de otros materiales no clasificados en otras ocupaciones"}],"area_principal":{"sigla":"AVPP","nombre":"Artes visuales, plásticas y del patrimonio cultural"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"7399*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"5268","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Artesanos de otros materiales no clasificados en otras ocupaciones / Artesanas de otros materiales no clasificados en otras ocupaciones', '73999', 'Artes visuales, plásticas y del patrimonio cultural', 2, false, '{"codigo":"73999","nombre":"Artesanos de otros materiales no clasificados en otras ocupaciones / Artesanas de otros materiales no clasificados en otras ocupaciones","descripcion":"Esta ocupación abarca a Artesanos de otros materiales no clasificados en otras ocupaciones del Grupo Primario 7543 Artesanos de otros materiales no clasificados en otras ocupaciones. Por ejemplo, incluye aquellos que elaboran objetos utilitarios o decorativos en otros materiales de origen natural o sintético tales como cacho, pezuña, tela, parafina, jabón, porcelanicron, empleando técnicas de corte, afieltrado, modelado, moldeado, costura y ensamble. Se pueden desempeñar en talleres artesanales, empresa de manufactura, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"73","nombre":"ARTESANOS Y OPERARIOS DE LAS ARTES GRÁFICAS Y AFINES"},"subgrupo":{"codigo":"739","nombre":"Artesanos no clasificados en otros grupos primarios"},"grupo_primario":{"codigo":"7399","nombre":"Artesanos de otros materiales no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Planear la producción y seleccionar los materiales adecuados de origen vegetal y animal, de acuerdo con las características del producto artesanal y requerimientos técnicos."},{"consecutivo":2,"texto":"Emplear técnicas de acondicionamiento de materiales de origen natural o sintético como cuerno, pezuña, huesos, conchas, tela, cera, caucho, polímeros, materiales reciclados y/o reutilizados, entre otros, de acuerdo con las características del objeto artesanal a elaborar."},{"consecutivo":3,"texto":"Realizar moldes, dibujos, bosquejos o plantillas de los trabajos artesanales a realizar, según el diseño y requerimientos técnicos."},{"consecutivo":4,"texto":"Acabar productos artesanales o piezas elaboradas mediante lijas y felpas de brillo, de acuerdo con característica de diseño, tipo de material y requerimientos técnicos."},{"consecutivo":5,"texto":"Decorar productos artesanales elaborados con materiales maderables y no maderables según técnicas de incrustación, pirograbado, enchapes pinturas, bruñido y acabados naturales según diseño y contexto cultural."},{"consecutivo":6,"texto":"Descortezar, cortar puntas, laminar lajas de cuerno o pezuña y eliminar impurezas de la materia prima a emplear para la elaboración de artículos artesanales."},{"consecutivo":7,"texto":"Cortar telas y rellenar el cuerpo de las muñecas con distintos materiales, según la materia prima seleccionada y especificaciones técnicas del producto artesanal."},{"consecutivo":8,"texto":"Elaborar y disponer moldes para el vaciado de parafina, jabón o velas, desmoldar y eliminar las rebabas del producto."},{"consecutivo":9,"texto":"Seleccionar las flores que están en buen estado, emparejarlas y prepararlas para la venta ya sea a través de un arreglo floral, adicionando accesorios como frutas, dulces, chocolates, entre otros."},{"consecutivo":10,"texto":"Preparar, mantener y operar maquinarias, equipos y herramientas para la elaboración de productos artesanales de acuerdo con el diseño y especificaciones técnicas."},{"consecutivo":11,"texto":"Elaborar y modelar productos artesanales en materiales maderables y no maderables según técnicas artesanales y requerimientos diseño."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"73999.001","nombre":"Artesano de arreglos florales (silletero) / Artesana de arreglos florales (silletera)"},{"codigo":"73999.002","nombre":"Artesano cerero / Artesana cerera"},{"codigo":"73999.003","nombre":"Artesano de cuerno / Artesana de cuerno"},{"codigo":"73999.004","nombre":"Artesano de elaboración jabó