  ('rol_cuoc', 'Electricistas de obra, residenciales y afines', '74111', 'Producción de energía y electricidad', 2, false, '{"codigo":"74111","nombre":"Electricistas de obra, residenciales y afines","descripcion":"Instalan, prueban, regulan y reparan sistemas de cableado eléctrico, aparatos de control, accesorios afines y equipos relacionados en edificios, fábricas y otras instalaciones. Se pueden desempeñar en departamentos de mantenimiento, constructoras, compañías de generación, transmisión y distribución de energía eléctrica, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"74","nombre":"OFICIALES Y OPERARIOS DE ELECTRICIDAD Y ELECTRÓNICA"},"subgrupo":{"codigo":"741","nombre":"Instaladores y reparadores de equipos eléctricos"},"grupo_primario":{"codigo":"7411","nombre":"Electricistas de obra, residenciales y afines"}},"funciones":[{"consecutivo":1,"texto":"Interpretar planos, diagramas de cableado y especificaciones de código eléctrico para determinar secuencias, métodos de operación y ubicación del cableado de instalaciones nuevas o existentes."},{"consecutivo":2,"texto":"Instalar, mantener y reparar sistemas de cableado eléctrico, cajas de interruptores, conductos, alimentadores, accesorios de iluminación, equipos conexos y otros componentes eléctricos en diversos edificios, como escuelas, hospitales, establecimientos comerciales, viviendas y otras estructuras."},{"consecutivo":3,"texto":"Instalar y mantener transformadores, generadores, reguladores de voltaje, tableros de distribución, reactores y otros equipos de generación y distribución de energía."},{"consecutivo":4,"texto":"Probar equipos eléctricos y componentes de continuidad, corriente, voltaje y resistencia, utilizando equipos de prueba para garantizar la compatibilidad y la seguridad de los procesos de instalación, cambio o reparación."},{"consecutivo":5,"texto":"Planificar el diseño e instalación de cableado eléctrico, equipos y aparatos eléctricos basándose en especificaciones de trabajo y normas aplicables."},{"consecutivo":6,"texto":"Instalar, componer, mantener y reparar tableros de distribución eléctrica, sistemas y accesorios de control eléctrico."},{"consecutivo":7,"texto":"Inspeccionar, probar y chequear la operación de sistemas eléctricos utilizando medidores de voltaje y otros instrumentos y equipo de prueba eléctrica."},{"consecutivo":8,"texto":"Inspeccionar sistemas, equipos y componentes eléctricos para detectar fallas, peligros y deficiencias, de acuerdo con especificaciones técnicas."},{"consecutivo":9,"texto":"Medir instalaciones, colocar puntos de referencia y conectar alambres y cables en terminales y conectores."},{"consecutivo":10,"texto":"Conectar energía eléctrica a equipos de sonido, visual, comunicación, señalización o sistemas de calefacción de acuerdo con especificaciones técnicas."},{"consecutivo":11,"texto":"Llevar registros y velar por el cumplimiento de programas de mantenimiento preventivo y normas de seguridad de instalaciones y componentes eléctricos."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"74111.001","nombre":"Electricista"},{"codigo":"74111.002","nombre":"Electricista de construcción"},{"codigo":"74111.003","nombre":"Electricista de construcción residencial"},{"codigo":"74111.004","nombre":"Electricista de escenario y estudio"},{"codigo":"74111.005","nombre":"Electricista de escenario y plató"},{"codigo":"74111.006","nombre":"Electricista de estación eléctrica"},{"codigo":"74111.007","nombre":"Electricista de eventos y espectáculos"},{"codigo":"74111.008","nombre":"Electricista de generador eléctrico"},{"codigo":"74111.009","nombre":"Electricista de mantenimiento y construcción"},{"codigo":"74111.010","nombre":"Electricista de obra"},{"codigo":"74111.011","nombre":"Electricista de planta"},{"codigo":"74111.012","nombre":"Electricista de planta de energía eléctrica"},{"codigo":"74111.013","nombre":"Electricista de sistema de energía eléctrica"},{"codigo":"74111.014","nombre":"Electricista de subestación eléctrica"},{"codigo":"74111.015","nombre":"Electricista de teatro"},{"codigo":"74111.016","nombre":"Electricista reparador de edificios / Electricista reparadora de edificios"},{"codigo":"74111.017","nombre":"Electricista residencial"},{"codigo":"74111.019","nombre":"Operario de electricidad / Operaria de electricidad"},{"codigo":"74111.020","nombre":"Operario de generador eléctrico / Operaria de generador eléctrico"},{"codigo":"74111.021","nombre":"Reparador eléctrico de edificios / Reparadora eléctrica de edificios"}],"conocimientos":[{"id":"67","nombre":"Electricidad y energía"},{"id":"20","nombre":"Geografía y territorio"},{"id":"10","nombre":"Ingeniería y tecnología"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"17","nombre":"Análisis de necesidades"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"26","nombre":"Reparación"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"72152","nombre":"Instaladores y empalmadores de cables / Instaladoras y empalmadoras de cables"},{"codigo":"74121","nombre":"Electricistas industriales"},{"codigo":"74123","nombre":"Mecánicos electricistas / Mecánicas electricistas"},{"codigo":"74130","nombre":"Instaladores y reparadores de líneas eléctricas / Instaladoras y reparadoras de líneas eléctricas"}],"area_principal":{"sigla":"PEEL","nombre":"Producción de energía y electricidad"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"7411*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"8212*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8321*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8322","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Ayudantes electricistas', '74112', 'Producción de energía y electricidad', 2, false, '{"codigo":"74112","nombre":"Ayudantes electricistas","descripcion":"Ayudan a los trabajadores que realizan labores de instalación, mantenimiento y reparación de equipos, accesorios y estructuras eléctricas tales como: redes eléctricas, subestaciones, transformadores y tableros eléctricos. Se pueden desempeñar en empresas manufactureras, talleres de mantenimiento eléctrico, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"74","nombre":"OFICIALES Y OPERARIOS DE ELECTRICIDAD Y ELECTRÓNICA"},"subgrupo":{"codigo":"741","nombre":"Instaladores y reparadores de equipos eléctricos"},"grupo_primario":{"codigo":"7411","nombre":"Electricistas de obra, residenciales y afines"}},"funciones":[{"consecutivo":1,"texto":"Interpretar y manejar información básica sobre normas técnicas relacionadas con equipos eléctricos e instrumentos de medición."},{"consecutivo":2,"texto":"Realizar actividades básicas relacionadas con el alistamiento, montaje y mantenimiento de equipos, herramientas y estructuras eléctricas de acuerdo con procedimientos establecidos en el sitio de trabajo."},{"consecutivo":3,"texto":"Realizar cargue, descargue y alistamiento de herramientas, equipos e insumos y velar por la seguridad y cuidado de estos."},{"consecutivo":4,"texto":"Apoyar con actividades de metrología eléctrica básica bajo la supervisión del jefe inmediato."},{"consecutivo":5,"texto":"Realizar el adecuado almacenamiento de equipos, herramientas e insumos de acuerdo con normatividad relacionada con la energía eléctrica."},{"consecutivo":6,"texto":"Ayudar en el empalme de cables de transmisión de energía eléctrica aéreos y subterráneos, bajo la supervisión del jefe inmediato."},{"consecutivo":7,"texto":"Ayudar en la reparación y mantenimiento de aparatos eléctricos, motores pequeños, mecanismos similares, equipos de distribución y generación eléctrica."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"74112.001","nombre":"Auxiliar eléctrico / Auxiliar eléctrica"},{"codigo":"74112.002","nombre":"Auxiliar eléctrico de petróleo y gas / Auxiliar eléctrica de petróleo y gas"},{"codigo":"74112.003","nombre":"Auxiliar técnico de campo de electric line / Auxiliar técnica de campo de electric line"},{"codigo":"74112.004","nombre":"Ayudante de electricidad"},{"codigo":"74112.005","nombre":"Auxiliar en electricidad para construcción"},{"codigo":"74112.006","nombre":"Ayudante electricista"},{"codigo":"74112.007","nombre":"Ayudante electricista residencial"},{"codigo":"74112.008","nombre":"Ayudante técnico de electricidad / Ayudante técnica de electricidad"},{"codigo":"74112.009","nombre":"Ayudante técnico de electricidad de petróleo y gas / Ayudante técnica de electricidad de petróleo y gas"}],"conocimientos":[{"id":"67","nombre":"Electricidad y energía"},{"id":"20","nombre":"Geografía y territorio"},{"id":"10","nombre":"Ingeniería y tecnología"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"37","nombre":"Proactividad"},{"id":"26","nombre":"Reparación"}],"ocupaciones_afines":[{"codigo":"72152","nombre":"Instaladores y empalmadores de cables / Instaladoras y empalmadoras de cables"},{"codigo":"74111","nombre":"Electricistas de obra, residenciales y afines"},{"codigo":"74121","nombre":"Electricistas industriales"},{"codigo":"74123","nombre":"Mecánicos electricistas / Mecánicas electricistas"},{"codigo":"74130","nombre":"Instaladores y reparadores de líneas eléctricas / Instaladoras y reparadoras de líneas eléctricas"}],"area_principal":{"sigla":"PEEL","nombre":"Producción de energía y electricidad"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"7411*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"8414*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8415*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Electricistas industriales', '74121', 'Producción de energía y electricidad', 2, false, '{"codigo":"74121","nombre":"Electricistas industriales","descripcion":"Instalan, mantienen, prueban y reparan sistemas eléctricos de aeronavegación, componentes eléctricos de vehículos automotores, redes eléctricas, equipos de generación eléctrica, subestaciones, transformadores, sistemas de distribución y transmisión de energía, controles y tableros eléctricos. Se pueden desempeñar en establecimientos industriales, empresas de mantenimiento, aeronáutica, aerolíneas, fuerzas armadas, compañías de transmisión y distribución de energía eléctrica, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"74","nombre":"OFICIALES Y OPERARIOS DE ELECTRICIDAD Y ELECTRÓNICA"},"subgrupo":{"codigo":"741","nombre":"Instaladores y reparadores de equipos eléctricos"},"grupo_primario":{"codigo":"7412","nombre":"Mecánicos y ajustadores electricistas"}},"funciones":[{"consecutivo":1,"texto":"Inspeccionar, reparar, mantener e instalar instrumentos, sistemas y equipos eléctricos de aeronaves validando que se cumplan estándares de seguridad."},{"consecutivo":2,"texto":"Leer planos, diagnosticar fallas y efectuar mantenimiento de partes y componentes eléctricos de vehículos automotores."},{"consecutivo":3,"texto":"Operar simuladores eléctricos, equipos y herramientas de diagnóstico para efectuar lecturas digitales y analógicas relacionadas con el uso eléctrico automotriz."},{"consecutivo":4,"texto":"Instalar, probar, reparar y mantener motores eléctricos, generadores, baterías, sistemas de control de cableado, eléctrico, hidráulico y neumático."},{"consecutivo":5,"texto":"Instalar y mantener equipo eléctrico, aparatos de estaciones eléctricas, transformadores, generadores, reguladores de voltaje y otros equipos de distribución y generación de energía."},{"consecutivo":6,"texto":"Instalar, reparar y llevar registros relacionados con programas de mantenimiento preventivo de sistemas de alumbrado público."},{"consecutivo":7,"texto":"Inspeccionar, probar, sustituir y reparar piezas defectuosas de productos eléctricos fabricados."},{"consecutivo":8,"texto":"Instalar, mantener, reparar y probar redes, aisladores, conductores, postes de iluminación, interruptores, transformadores, equipos auxiliares, líneas de cableado aéreas y subterráneas de distribución y transmisión eléctrica, utilizando equipo eléctrico de prueba."},{"consecutivo":9,"texto":"Mantener, reparar, instalar y probar equipos eléctricos, interruptores, transformadores, tableros de distribución, reguladores, reactores, componentes de continuidad, corriente, voltaje y resistencia, entre otros."},{"consecutivo":10,"texto":"Interpretar planos, especificaciones y códigos eléctricos para determinar la ubicación de conexiones e instalaciones de equipos y sistemas eléctricos a las fuentes de alimentación."},{"consecutivo":11,"texto":"Mantener, reparar e inspeccionar sistemas y accesorios de control eléctrico para detectar fallas en equipos eléctricos instalados, utilizando medidores de voltaje, equipo de prueba eléctrica y otros instrumentos."},{"consecutivo":12,"texto":"Instalar, examinar, reemplazar y reparar cableado eléctrico, cajas de interruptores, conductos, alimentadores, ensambles de cable, accesorios de iluminación y otros componentes eléctricos."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"74121.001","nombre":"Auxiliar en electricidad automotriz"},{"codigo":"74121.002","nombre":"Ayudante técnico electricista en industria petrolera / Ayudante técnica electricista en industria petrolera"},{"codigo":"74121.003","nombre":"Electricista ajustador de centrales eléctricas de regulación e instalaciones similares / Electricista ajustadora de centrales eléctricas de regulación e instalaciones similares"},{"codigo":"74121.004","nombre"