  ('rol_cuoc', 'Reparadores de aparatos electrodomésticos / Reparadoras de aparatos electrodomésticos', '74122', 'Producción de energía y electricidad', 2, false, '{"codigo":"74122","nombre":"Reparadores de aparatos electrodomésticos / Reparadoras de aparatos electrodomésticos","descripcion":"Instalan, montan, ajustan, diagnostican y reparan electrodomésticos en edificios, residencias y establecimientos comerciales. Se pueden desempeñar en talleres de mantenimiento de línea blanca, empresas fabricantes, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"74","nombre":"OFICIALES Y OPERARIOS DE ELECTRICIDAD Y ELECTRÓNICA"},"subgrupo":{"codigo":"741","nombre":"Instaladores y reparadores de equipos eléctricos"},"grupo_primario":{"codigo":"7412","nombre":"Mecánicos y ajustadores electricistas"}},"funciones":[{"consecutivo":1,"texto":"Instalar, ajustar, reparar y mantener partes eléctricas, componentes y tarjetas electrónicas, de aparatos electrodomésticos como neveras, refrigeradores, lavadoras y otros equipos."},{"consecutivo":2,"texto":"Reemplazar, sustituir y reparar piezas defectuosas o partes dañadas utilizando herramientas manuales y equipo de soldadura."},{"consecutivo":3,"texto":"Diagnosticar y revisar fallas de aparatos domésticos en relación con controles, condensadores, ventiladores y otros componentes utilizando equipo eléctrico de prueba como medidores y calibradores para establecer resistencia, corriente, voltaje y presión."},{"consecutivo":4,"texto":"Consultar manuales, instrucciones o con los clientes sobre la naturaleza del mal funcionamiento de los aparatos electrodomésticos."},{"consecutivo":5,"texto":"Elaborar presupuestos de trabajos y cronogramas de mantenimientos rutinarios a los aparatos domésticos."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"74122.001","nombre":"Ayudante reparador 