  ('rol_cuoc', 'Mecánicos electricistas / Mecánicas electricistas', '74123', 'Producción de energía y electricidad', 2, false, '{"codigo":"74123","nombre":"Mecánicos electricistas / Mecánicas electricistas","descripcion":"Instalan, montan, ajustan y reparan maquinaria eléctrica, motores eléctricos, transformadores, interruptores, ascensores, escaleras automáticas y otros aparatos. Se pueden desempeñar en talleres de reparación eléctrica, plantas manufactureras, fabricantes de equipo y maquinaria industrial, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"74","nombre":"OFICIALES Y OPERARIOS DE ELECTRICIDAD Y ELECTRÓNICA"},"subgrupo":{"codigo":"741","nombre":"Instaladores y reparadores de equipos eléctricos"},"grupo_primario":{"codigo":"7412","nombre":"Mecánicos y ajustadores electricistas"}},"funciones":[{"consecutivo":1,"texto":"Montar, ajustar y reparar diversas clases de máquinas, motores eléctricos, transformadores, generadores, dispositivos de distribución y control, interruptores, instrumentos y partes eléctricos de máquinas industriales, ascensores y equipos relacionados."},{"consecutivo":2,"texto":"Reparar, probar y observar condiciones eléctricas y mecánicas de motores eléctricos, transformadores, alambrados, interruptores eléctricos, dispositivos de distribución y control, entre otros, utilizando instrumentos de medición y prueba."},{"consecutivo":3,"texto":"Instalar, mantener y reparar ascensores, escaleras mecánicas, aceras rodantes, montacargas eléctricos e hidráulicos y otros equipos de elevación de acuerdo con especificaciones técnicas."},{"consecutivo":4,"texto":"Reemplazar reparar y reacondicionar conexiones, piezas defectuosas y otros componentes de aparatos eléctricos."},{"consecutivo":5,"texto":"Asegurar las fuentes eléctricas de motores y transformadores eléctricos."},{"consecutivo":6,"texto":"Realizar balanceo dinámico o