  ('rol_cuoc', 'Instaladores y reparadores de líneas eléctricas / Instaladoras y reparadoras de líneas eléctricas', '74130', 'Producción de energía y electricidad', 2, false, '{"codigo":"74130","nombre":"Instaladores y reparadores de líneas eléctricas / Instaladoras y reparadoras de líneas eléctricas","descripcion":"Instalan, construyen y reparan líneas aéreas y subterráneas de sistemas de distribución, transmisión y suministro de energía eléctrica. Se pueden desempeñar en empresas de servicios públicos, compañías de generación, transmisión y distribución de energía, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"74","nombre":"OFICIALES Y OPERARIOS DE ELECTRICIDAD Y ELECTRÓNICA"},"subgrupo":{"codigo":"741","nombre":"Instaladores y reparadores de equipos eléctricos"},"grupo_primario":{"codigo":"7413","nombre":"Instaladores y reparadores de líneas eléctricas"}},"funciones":[{"consecutivo":1,"texto":"Instalar, mantener y reparar redes, líneas aéreas, subterráneas, de alimentación, distribución y transmisión eléctrica, de acuerdo con recomendaciones técnicas."},{"consecutivo":2,"texto":"Empalmar, soldar y aislar cables aéreos, subterráneos, conductores y alambrado necesarios para conectar la red de distribución y transmisión eléctrica usando herramientas y equipo eléctrico relacionado."},{"consecutivo":3,"texto":"Ascender y hacer mantenimiento a los equipos en postes de acero, madera, concreto, torres y cables utilizando canastas hidráulicas, escaleras y plataformas elevadoras montadas en un camión."},{"consecutivo":4,"texto":"Cumplir con prácticas y procedimientos de seguridad tales como comprobar regularmente equipos y levantar barreras alrededor de las zonas de trabajo."},{"consecutivo":5,"texto":"Inspeccionar, instalar y probar dispositivos, equipo auxiliar, cableado aéreo y subterráneo, eliminando riesgos eléctricos de las líneas averiadas o caídas utilizando equipo de prueba."},{"consecutivo":6,"texto":"Instalar y mantener sistemas de alumbrado público, líneas eléctricas aéreas y subterráneas de baja y media tensión."},{"consecutivo":7,"texto":"Detectar defectos en dispositivos de seccionamiento, disyuntores, fusibles, reguladores de tensión, transformadores, conmutadores, relés o cables, usando diagramas de cableado e instrumentos de medición y prueba eléctrica."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"74130.001","nombre":"Empalmador de cables eléctricos / Empalmadora de cables eléctricos"},{"codigo":"74130.002","nombre":"Instalador de cables de tracción de vehículos eléctricos / Instaladora de cables de tracción de vehículos eléctricos"},{"codigo":"74130.003","nombre":"Instalador de líneas de energía eléctrica / Instaladora de líneas de energía eléctrica"},{"codigo":"74130.004","nombre":"Instalador de líneas eléctricas de tracción / Instaladora de líneas eléctricas de tracción"},{"codigo":"74130.005","nombre":"Liniero de redes / Liniera de redes"},{"codigo":"74130.006","nombre":"Montador de líneas de energía eléctrica / Montadora de líneas de energía eléctrica"},{"codigo":"74130.007","nombre":"Reparador de cables eléctricos / Reparadora de cables eléctricos"},{"codigo":"74130.008","nombre":"Reparador de cable de sistema de energía eléctrica / Reparadora de cable de sistema de energía eléctrica"},{"codigo":"74130.009","nombre":"Reparador de líneas de energía eléctrica / Reparadora de líneas de energía eléctrica"}],"conocimientos":[{"id":"67","nombre":"Electricidad y energía"},{"id":"10","nombre":"Ingeniería y tecnología"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"17","nombre":"Análisis de necesidades"},{"id":"2","nombre":"Escucha activa"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"19","nombre":"Selección de equipo"},{"id":"11",