  ('rol_cuoc', 'Ajustadores, reparadores e instaladores en electrónica / Ajustadoras, reparadoras e instaladoras en electrónica', '74210', 'Electrónica y automatización', 2, false, '{"codigo":"74210","nombre":"Ajustadores, reparadores e instaladores en electrónica / Ajustadoras, reparadoras e instaladoras en electrónica","descripcion":"Instalan, mantienen, ajustan, diagnostican y reparan dispositivos electrónicos, tales como señales de tráfico, sistemas de aeronavegación, equipos audiovisuales, máquinas tragamonedas, expendedoras comerciales, y demás mecanismos electrónicos. Se pueden desempeñar en talleres de mantenimiento electrónico, compañías de aeronáutica, aerolíneas, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"74","nombre":"OFICIALES Y OPERARIOS DE ELECTRICIDAD Y ELECTRÓNICA"},"subgrupo":{"codigo":"742","nombre":"Instaladores y reparadores de equipos electrónicos y de telecomunicaciones"},"grupo_primario":{"codigo":"7421","nombre":"Ajustadores, reparadores e instaladores en electrónica"}},"funciones":[{"consecutivo":1,"texto":"Instalar, ajustar, reparar y mantener sistemas electrónicos, piezas, partes desgastadas o defectuosas de máquinas, equipos e instrumentos utilizando herramientas de uso manual, eléctricas o soldadores."},{"consecutivo":2,"texto":"Examinar, montar y probar máquinas, instrumentos, componentes, sistemas de control y otros equipos electrónicos para diagnosticar averías en el funcionamiento y realizar ajustes en los mismos."},{"consecutivo":3,"texto":"Interpretar datos obtenidos en pruebas, planos de circuitos, montajes electrónicos, entre otros, para realizar diagnóstico y registro de defectos y problemas de funcionamiento sistémicos."},{"consecutivo":4,"texto":"Reparar, conectar y modificar componentes y equipos electrónicos de aeronaves como sistemas de radio, magnetos, dispositivos de comunicación, equipos de navegación, inversores y sistemas de reabastecimiento en vuelo."},{"consecutivo":5,"texto":"Inspeccionar y probar la instalación de instrumentos electrónicos y sistemas de control de aeronaves cumpliendo con estándares de seguridad."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"74210.001","nombre":"Ajustador de señales de tráfico / Ajustadora de señales de tráfico"},{"codigo":"74210.002","nombre":"Auxiliar de mantenimiento técnico de soporte electrónico"},{"codigo":"74210.003","nombre":"Auxiliar técnico en electrónica / Auxiliar técnica en electrónica"},{"codigo":"74210.004","nombre":"Mecánico de cajeros automáticos / Mecánica de cajeros automáticos"},{"codigo":"74210.005","nombre":"Mecánico de equipos de oficina / Mecánica de equipos de oficina"},{"codigo":"74210.006","nombre":"Mecánico de mantenimiento de aeronaves especializado en aviónica / Mecánica de mantenimiento de aeronaves especializado en aviónica"},{"codigo":"74210.007","nombre":"Mecánico de mantenimiento electrónico / Mecánica de mantenimiento electrónico"},{"codigo":"74210.008","nombre":"Mecánico electrónico / Mecánica electrónica"},{"codigo":"74210.009","nombre":"Mecánico reparador de equipo electrónico / Mecánica reparadora de equipo electrónico"},{"codigo":"74210.010","nombre":"Operario de reparación de audio, video y televisión / Operaria de reparación de audio, video y televisión"},{"codigo":"74210.011","nombre":"Reparador de aparatos de grabación de transmisión de sonido e imagen / Reparadora de aparatos de grabación de transmisión de sonido e imagen"},{"codigo":"74210.012","nombre":"Reparador de aparatos electrónicos / Reparadora de aparatos electrónicos"},{"codigo":"74210.013","nombre":"Reparador de equipos electrónicos / Reparadora de equipos electrónicos"},{"codigo":"74210.014","nombre":"Reparador de máquinas tragamonedas / Reparadora de máquinas tragamonedas"},{"codigo":"74210.015","nombre":"Reparador de máquinas ventas automáticas / Reparadora de 