  ('rol_cuoc', 'Técnicos instaladores de redes y líneas de telecomunicaciones / Técnicas instaladoras de redes y líneas de telecomunicaciones', '74221', 'Tecnologías de la información y las comunicaciones', 2, false, '{"codigo":"74221","nombre":"Técnicos instaladores de redes y líneas de telecomunicaciones / Técnicas instaladoras de redes y líneas de telecomunicaciones","descripcion":"Instalan, reparan y mantienen líneas y redes de telecomunicaciones, transmisión de datos, cables, antenas y conductos. Se pueden desempeñar en compañías de telecomunicaciones, proveedores de infraestructura de telecomunicaciones, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"74","nombre":"OFICIALES Y OPERARIOS DE ELECTRICIDAD Y ELECTRÓNICA"},"subgrupo":{"codigo":"742","nombre":"Instaladores y reparadores de equipos electrónicos y de telecomunicaciones"},"grupo_primario":{"codigo":"7422","nombre":"Instaladores y reparadores en tecnología de la información y las comunicaciones"}},"funciones":[{"consecutivo":1,"texto":"Instalar, trasladar, mantener y reparar redes, líneas, antenas y demás medios de trasmisión utilizadas en servicios de telecomunicaciones."},{"consecutivo":2,"texto":"Inspeccionar, realizar pruebas y localizar fallas básicas en cables, líneas y medios de transmisión de telecomunicaciones."},{"consecutivo":3,"texto":"Empalmar, reparar y sellar envoltorios con cinta aislante a cables coaxiales, de fibra óptica, cobre y demás utilizados en las telecomunicaciones y trasmisión de datos."},{"consecutivo":4,"texto":"Medir y registrar los resultados de parámetros y pruebas básicas a líneas y/o medios de transmisión, según normativa vigente de telecomunicaciones."},{"consecutivo":5,"texto":"Brindar asesoramiento a clientes e información técnica relacionada con el funcionamiento de redes de telecomunicaciones y equipos complejos, de acuerdo con protocolos y niveles de servicio."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"74221.001","nombre":"Ajustador de instalación de redes de telecomunicaciones / Ajustadora de instalación de redes de telecomunicaciones"},{"codigo":"74221.002","nombre":"Ajustador de radar / Ajustadora de radar"},{"codigo":"74221.003","nombre":"Aparejador de telecomunicaciones / Aparejadora de telecomunicaciones"},{"codigo":"74221.004","nombre":"Auxiliar en asistencia y soporte equipos de tecnologías de la información"},{"codigo":"74221.005","nombre":"Electricista de equipo de telecomunicaciones"},{"codigo":"74221.006","nombre":"Empalmador de cable de telecomunicaciones / Empalmadora de cable de telecomunicaciones"},{"codigo":"74221.007","nombre":"Empalmador de cable de teléfonos / Empalmadora de cable de teléfonos"},{"codigo":"74221.008","nombre":"Instalador de antenas / Instaladora de antenas"},{"codigo":"74221.009","nombre":"Instalador de antenas de radio / Instaladora de antenas de radio"},{"codigo":"74221.010","nombre":"Instalador de antenas de televisión / Instaladora de antenas de televisión"},{"codigo":"74221.011","nombre":"Instalador de cable teléfonos / Instaladora de cable teléfonos"},{"codigo":"74221.012","nombre":"Instalador de cables de telecomunicaciones / Instaladora de cables de telecomunicaciones"},{"codigo":"74221.013","nombre":"Instalador de líneas de telecomunicaciones / Instaladora de líneas de telecomunicaciones"},{"codigo":"74221.014","nombre":"Instalador de líneas telefónicas / Instaladora de líneas telefónicas"},{"codigo":"74221.015","nombre":"Instalador de radio y radar de aeronavegación / Instaladora de radio y radar de aeronavegación"},{"codigo":"74221.016","nombre":"Instalador de redes de telecomunicaciones / Instaladora de redes de telecomunicaciones"},{"codigo":"74221.017","nombre":"Instalador de redes informáticas / Instaladora de redes informáticas"},{"codigo":"74221.018","nombre":"Instalador de sistemas de telecomunicación