  ('rol_cuoc', 'Operarios de mantenimiento y servicio de televisión por cable / Operarias de mantenimiento y servicio de televisión por cable', '74223', 'Tecnologías de la información y las comunicaciones', 2, false, '{"codigo":"74223","nombre":"Operarios de mantenimiento y servicio de televisión por cable / Operarias de mantenimiento y servicio de televisión por cable","descripcion":"Instalan, mantienen y reparan sistemas de transmisión, distribución y señal de televisión por cable y equipos asociados, en residencias e instalaciones comerciales. Se pueden desempeñar en empresas de servicio de TV por cable, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"74","nombre":"OFICIALES Y OPERARIOS DE ELECTRICIDAD Y ELECTRÓNICA"},"subgrupo":{"codigo":"742","nombre":"Instaladores y reparadores de equipos electrónicos y de telecomunicaciones"},"grupo_primario":{"codigo":"7422","nombre":"Instaladores y reparadores en tecnología de la información y las comunicaciones"}},"funciones":[{"consecutivo":1,"texto":"Conectar, desconectar, instalar y reubicar salidas de cable, divisores, convertidores, equipos y otros sistemas en la zona del suscriptor."},{"consecutivo":2,"texto":"Inspeccionar, probar y reparar señales y equipos asociados en la zona de suscriptores de servicios de televisión por cable."},{"consecutivo":3,"texto":"Instalar, mantener y reparar antenas, sistemas principales, líneas y demás dispositivos relacionados con interconexión, distribución y transmisión de TV por cable."},{"consecutivo":4,"texto":"Inspeccionar, probar y ajustar cables utilizados en sistemas de transmisión y distribución de televisión por cable."},{"consecutivo":5,"texto":"Reparar o reemplazar implementos defectuosos, amplificadores y otros equipos de transmisión o distribución utilizados en la televisión por cable."},{"consecutivo":6,"texto":"Trepar y trabajar en la altura sobre postes, escaleras u otras estructuras de apoyo para efectuar instalaciones y arreglos a conexiones de televisión por cable."},{"consecutivo":7,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"74223.001","nombre":"Ajustador de instalación de televisión por cable / Ajustadora de instalación de televisión por cable"},{"codigo":"74223.002","nombre":"Instalador de televisión por cable / Instaladora de televisión por cable"},{"codigo":"74223.003","nombre":"Operario de instalación de televisión por cable / Operaria de instalación de televisión por cable"},{"codigo":"74223.004","nombre":"Operario de mantenimiento de televisión por cable / Operaria de mantenimiento de televisión por cable"},{"codigo":"74223.005","nombre":"Operario de montaje de antenas de televisión por cable / Operaria de montaje de antenas de televisión por cable"},{"codigo":"74223.006","nombre":"Operario de servicio de televisión por cable / Operaria de servicio de televisión por cable"},{"codigo":"74223.007","nombre":"Reparador de televisión por cable / Reparadora de televisión por cable"},{"codigo":"74223.008","nombre":"Técnico de instalación de televisión por cable / Técnica de instalación de televisión por cable"},{"codigo":"74223.009","nombre":"Técnico de mantenimiento de televisión por cable / Técnica de mantenimiento de televisión por cable"},{"codigo":"74223.010","nombre":"Técnico de montaje de antenas de televisión por cable / Técnica de montaje de antenas de televisión por cable"},{"codigo":"74223.011","nombre":"Técnico de servicio de televisión por cable / Técnica de servicio de televisión por cable"}],"conocimientos":[{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"36","nombre":"Manejo de las TIC"},{"id":"38","nombre":"Mantenimiento"},{"id":"5","nombre":"Servicio al cliente"},{"id":"29","nombre":"Telecomunicación"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"2","nombre":"Escucha activa"},{"id":"25","nombre":"Manejo