  ('rol_cuoc', 'Carniceros, pescaderos y afines / Carniceras, pescaderas y afines', '75110', 'Elaboración y transformación de alimentos', 2, false, '{"codigo":"75110","nombre":"Carniceros, pescaderos y afines / Carniceras, pescaderas y afines","descripcion":"Sacrifican animales, limpian y preparan cortes, retiran huesos, conservan carne, pollo, pescado y otros productos cárnicos secándolos, salándolos o ahumándolos. Se pueden desempeñar en supermercados, carnicerías, pescaderías, establecimientos de sacrificio, preparación y empaque de carne y aves, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"75","nombre":"OFICIALES Y OPERARIOS DE PROCESAMIENTO DE ALIMENTOS, DE LA CONFECCIÓN, EBANISTAS Y AFINES"},"subgrupo":{"codigo":"751","nombre":"Oficiales y operarios de procesamiento de alimentos y afines"},"grupo_primario":{"codigo":"7511","nombre":"Carniceros, pescaderos y afines"}},"funciones":[{"consecutivo":1,"texto":"Operar máquinas, cuchillos y otros implementos para sacrificar ganado, aves y peces, remover las vísceras, plumas y otras partes no comestibles, lavar, chamuscar y conservar los productos cárnicos para permitir su manipulación, procesamiento y empaque."},{"consecutivo":2,"texto":"Moler, tajar y preparar cortes especiales de carne, aves, pescados y mariscos utilizando equipo manual o eléctrico para exhibición y venta según normatividad internacional."},{"consecutivo":3,"texto":"Realizar corte y arreglo para el procesamientos o empaque de carnes, aves, pescado y mariscos para uso institucional o comercial en supermercados o en negocios particulares, de acuerdo con órdenes del cliente y especificaciones técnicas."},{"consecutivo":4,"texto":"Desollar, remover y descuartizar la piel, excesos de grasa o magulladuras del animal sacrificado o las piezas de carne porcionada."},{"consecutivo":5,"texto":"Deshuesar y cortar carne, pollo y pescado para su procesamiento conteniendo el envasado, pesaje y etiquetado de productos cárnicos para la venta."},{"consecutivo":6,"texto":"Arreglar, trinchar, envolver, amarrar y preparar ingredientes para fabricar salchichas y productos similares utilizando máquinas de cortar, mezclar y embutir carnes."},{"consecutivo":7,"texto":"Operar, accionar y mantener utensilios, máquinas y equipos para, pelar, desvenar, cortar, eviscerar, lavar, despinar, deshuesar, retirar escamas, separar filetes y arreglar productos cárnicos manteniendo la cadena de frio."},{"consecutivo":8,"texto":"Curar carne, pescado, pollo y productos cárnicos frotándolos con sal o metiéndolos en salmuera, de acuerdo con instrucciones técnicas."},{"consecutivo":9,"texto":"Operar máquinas cámaras u hornos para ahumar, enlatar, embolsar, embalar y empacar productos de carne, pollo, pescado y mariscos."},{"consecutivo":10,"texto":"Desprender la carne de crustáceos o peces para el procesamiento y enlatado, de acuerdo con instrucciones técnicas."},{"consecutivo":11,"texto":"Garantizar la cadena de frío, conservación, envase al vacío y presentación del producto, de acuerdo con las normativas existentes."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"75110.001","nombre":"Acecinador de carnes / Acecinadora de carnes"},{"codigo":"75110.002","nombre":"Ahumador de carnes / Ahumadora de carnes"},{"codigo":"75110.003","nombre":"Arreglador de carnes / Arregladora de carnes"},{"codigo":"75110.004","nombre":"Auxiliar de corte de carne"},{"codigo":"75110.005","nombre":"Ayudante de planta de beneficio animal"},{"codigo":"75110.006","nombre":"Butifarrero / Butifarrera"},{"codigo":"75110.007","nombre":"Carnicero / Carnicera"},{"codigo":"75110.008","nombre":"Carnicero industrial / Carnicera industrial"},{"codigo":"75110.009","nombre":"Carnicero matarife / Carnicera matarife"},{"codigo":"75110.010","nombre":"Carnicero mayorista y al detal / Carnicera mayorista y al detal"},{"codigo":