  ('rol_cuoc', 'Panaderos, pasteleros y confiteros / Panaderas, pasteleras y confiteras', '75121', 'Elaboración y transformación de alimentos', 2, false, '{"codigo":"75121","nombre":"Panaderos, pasteleros y confiteros / Panaderas, pasteleras y confiteras","descripcion":"Elaboran diversas clases de pan, pasteles, galletas y otros productos a base de harina, al igual que chocolates, dulces elaborados a mano, para su comercialización y confites en general. Se pueden desempeñar en panaderías, supermercados, hoteles, restaurantes y fabricas entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"75","nombre":"OFICIALES Y OPERARIOS DE PROCESAMIENTO DE ALIMENTOS, DE LA CONFECCIÓN, EBANISTAS Y AFINES"},"subgrupo":{"codigo":"751","nombre":"Oficiales y operarios de procesamiento de alimentos y afines"},"grupo_primario":{"codigo":"7512","nombre":"Panaderos, pasteleros, confiteros y paneleros"}},"funciones":[{"consecutivo":1,"texto":"Medir ingredientes y combinarlos en los recipientes de máquinas de mezclado, amasado o cocción de acuerdo con recetas u órdenes especiales del cliente."},{"consecutivo":2,"texto":"Elaborar cremas, batido, entre otros ingredientes para la preparación de galletas y bizcochos de acuerdo con recetas u órdenes especiales del cliente."},{"consecutivo":3,"texto":"Hornear masas y pastas mezcladas de acuerdo con recetas u órdenes especiales del cliente."},{"consecutivo":4,"texto":"Elaborar pan, bizcochos, galletas, pasteles, tartas y otros productos hechos con harina de manera tradicional, artesanal y en empresas de manufactura."},{"consecutivo":5,"texto":"Aplicar baños, glaseados, escarcha y otras coberturas para decorar productos horneados usando espátulas, pinceles o de forma manual."},{"consecutivo":6,"texto":"Confeccionar a mano dulces y golosinas con ayuda de utensilios y algunas máquinas mezclando azúcar, chocolate y otros ingredientes de acuerdo con recetas u órdenes especiales del cliente."},{"consecutivo":7,"texto":"Preparar dulces tradicionales como cocadas, postres, dulces blandos, duros, panes, tortas, mecatos, galletas, entre otros."},{"consecutivo":8,"texto":"Comprobar la limpieza de los equipos y el estado del lugar de trabajo antes de realizar las tareas de producción, para asegurar que se cumplan las normas ambientales y de seguridad y salud en el trabajo."},{"consecutivo":9,"texto":"Vigilar medidores, imágenes de computador, monitores, hornos, maquinas, entre otros, para controlar condiciones del procesamiento como: temperatura, tiempos de cocción, adición de ingredientes y promedios de flujo."},{"consecutivo":10,"texto":"Coordinar y establecer preparación, carga, horneado, descarga, retirada, enfriamiento y horario de producción para determinar el tipo y cantidad de productos de los lotes de pan, panecillos, pasteles y productos de confitería."},{"consecutivo":11,"texto":"Preparar masas para pasteles, pan, pizzas, panecillos, dulces y batidos para galletas, tortas y escarchados de acuerdo con recetas u órdenes especiales del cliente."},{"consecutivo":12,"texto":"Inspeccionar los productos elaborados para detectar irregularidades a fin de garantizar su calidad y ajustar la máquina si fuese necesario."},{"consecutivo":13,"texto":"Comprobar la calidad de las materias primas para asegurar que se cumplan las normas y especificaciones."},{"consecutivo":14,"texto":"Registrar la información de producción como cantidad, peso, tamaño, fecha y tipo de productos empacados."},{"consecutivo":15,"texto":"Comprar provisiones e ingredientes de panadería, pastelería o confitería de acuerdo con orden de producción."},{"consecutivo":16,"texto":"Emplear y entrenar personal para realizar actividades de panadería, pastelería o confitería de acuerdo con lineamientos del establecimiento."},{"consecutivo":17,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"75121.001","nombre":"Amasador de panadería / Amasadora de panadería"},{"codigo":"75121.002","nombre":"Artesano de amasijos / Artesana de amasijos"},{"codigo":"75121.003","nombre":"Batidor de chocolate / Batidora de chocolate"},{"codigo":"75121.005","nombre":"Bizcochero / Bizcochera"},{"codigo":"75121.006","nombre":"Chocolatero / Chocolatera"},{"codigo":"75121.007","nombre":"Confitero / Confitera"},{"codigo":"75121.009","nombre":"Dulcero tradicional / Dulcera tradicional"},{"codigo":"75121.010","nombre":"Galletero / Galletera"},{"codigo":"75121.011","nombre":"Hornero de confitería / Hornera de confitería"},{"codigo":"75121.012","nombre":"Hornero de galletas / Hornera de galletas"},{"codigo":"75121.014","nombre":"Hornero de panadería / Hornera de panadería"},{"codigo":"75121.015","nombre":"Moldeador de elaboración de chocolate / Moldeadora de elaboración de chocolate"},{"codigo":"75121.016","nombre":"Molinero de cacao / Molinera de cacao"},{"codigo":"75121.017","nombre":"Operario de fabricación de chicle / Operaria de fabricación de chicle"},{"codigo":"75121.018","nombre":"Operario de fabricación de levadura / Operaria de fabricación de levadura"},{"codigo":"75121.019","nombre":"Operario de fabricación de pastas alimenticias / Operaria de fabricación de pastas alimenticias"},{"codigo":"75121.020","nombre":"Operario en fabricación de galletas / Operaria en fabricación de galletas"},{"codigo":"75121.021","nombre":"Panadero / Panadera"},{"codigo":"75121.023","nombre":"Panadero galletero / Panadera galletera"},{"codigo":"75121.024","nombre":"Panadero pastelero / Panadera pastelera"},{"codigo":"75121.026","nombre":"Pastelero / Pastelera"},{"codigo":"75121.027","nombre":"Pizzero / Pizzera"},{"codigo":"75121.028","nombre":"Preparador de amasijos y dulces tradicionales / Preparadora de amasijos y dulces tradicionales"},{"codigo":"75121.029","nombre":"Procesador de dulces artesanales / Procesadora de dulces artesanales"},{"codigo":"75121.030","nombre":"Procesador de pan / Procesadora de pan"},{"codigo":"75