  ('rol_cuoc', 'Preparadores y elaboradores de cigarros y productos del tabaco / Preparadoras y elaboradoras de cigarros y productos del tabaco', '75160', 'Elaboración y transformación de alimentos', 2, false, '{"codigo":"75160","nombre":"Preparadores y elaboradores de cigarros y productos del tabaco / Preparadoras y elaboradoras de cigarros y productos del tabaco","descripcion":"Clasifican, curan, secan y preparan hojas de tabaco para la fabricación manual de diversos productos como picaduras, cigarros y artículos relacionados. Se pueden desempeñar en empresas fabricantes de cigarrillos, tabacaleras, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"75","nombre":"OFICIALES Y OPERARIOS DE PROCESAMIENTO DE ALIMENTOS, DE LA CONFECCIÓN, EBANISTAS Y AFINES"},"subgrupo":{"codigo":"751","nombre":"Oficiales y operarios de procesamiento de alimentos y afines"},"grupo_primario":{"codigo":"7516","nombre":"Preparadores y elaboradores de cigarros y productos del tabaco"}},"funciones":[{"consecutivo":1,"texto":"Alimentar, descargar y operar máquinas manuales de procesamiento, curado y secado de tabaco."},{"consecutivo":2,"texto":"Limpiar máquinas manuales, áreas de trabajo y eliminar obstrucciones en instalaciones de humedecido, curado y secado de productos de tabaco."},{"consecutivo":3,"texto":"Seleccionar y juntar hojas de tabaco de diversas clases, calidades y lugares de procedencia para obtener mezclas de aroma particular aplicando determinadas fórmulas."},{"consecutivo":4,"texto":"Atender y vigilar el funcionamiento de instalaciones y maquinas manuales que mezclan, aromatizan, humedecen, despalillan, secan, o cortan hojas de tabaco para su procesamiento posterior."},{"consecutivo":5,"texto":"Arrancar nervaduras centrales, tallos de hojas, picar y preparar mezclas de tabaco aromatizado de forma manual o con maquinaria simple."},{"consecutivo":6,"texto":"Confeccionar cigarros, rapé y otros productos del tabaco de forma manual y examinar los productos una vez terminados para detectar irregularidades."},{"consecutivo":7,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"75160.001","nombre":"Acondicionador de tabaco / Acondicionadora de tabaco"},{"codigo":"75160.002","nombre":"Aromatizador de tabaco / Aromatizadora de tabaco"},{"codigo":"75160.003","nombre":"Cigarrero / Cigarrera"},{"codigo":"75160.004","nombre":"Clasificador de cigarros / Clasificadora de cigarros"},{"codigo":"75160.005","nombre":"Clasificador de hojas de tabaco / Clasificadora de hojas de tabaco"},{"codigo":"75160.006","nombre":"Clasificador de tabaco / Clasificadora de tabaco"},{"codigo":"75160.007","nombre":"Despalillador de tabaco / Despalilladora de tabaco"},{"codigo":"75160.008","nombre":"Desvenador de tabaco / Desvenadora de tabaco"},{"codigo":"75160.009","nombre":"Empacador de cigarros / Empacadora de cigarros"},{"codigo":"75160.010","nombre":"Enfriador de tabaco / Enfriadora de tabaco"},{"codigo":"75160.011","nombre":"Fabricador de cigarros / Fabricadora de cigarros"},{"codigo":"75160.012","nombre":"Humectador de tabaco / Humectadora de tabaco"},{"codigo":"75160.013","nombre":"Laminador de vena de tabaco / Laminadora de vena de tabaco"},{"codigo":"75160.014","nombre":"Ligador de tabaco / Ligadora de tabaco"},{"codigo":"75160.015","nombre":"Mezclador de tabaco / Mezcladora de tabaco"},{"codigo":"75160.016","nombre":"Operario de fabricación de cigarros / Operaria de fabricación de cigarros"},{"codigo":"75160.017","nombre":"Operario de picado de tabaco / Operaria de picado de tabaco"},{"codigo":"75160.018","nombre":"Operario de secado de tabaco / Operaria de secado de tabaco"},{"codigo":"75160.019","nombre":"Operario de limpieza y clasificación en procesamiento del tabaco / Operaria de limpieza y clasificación en procesamiento del tabaco"},{"codigo":"75160.020","nombre":"Oreador de tabaco / Oreadora de tabaco"},{"codigo":"75160.021","nombre":"Prensador de cigarros / Prensadora de cigarros"},{"codigo":"75160.022","nombre":"Preparador de picadura de tabaco de pipa / Preparadora de picadura de tabaco de pipa"},{"codigo":"75160.023","nombre":"Refrescador de tabaco / Refrescadora de tabaco"},{"codigo":"75160.024","nombre":"Secador de rapé / Secadora de rapé"},{"codigo":"75160.025","nombre":"Secador de tabaco / Secadora de tabaco"},{"codigo":"75160.026","nombre":"Tabaquero / Tabaquera"},{"codigo":"75160.027","nombre":"Torcedor de tabaco / Torcedora de tabaco"}],"conocimientos":[{"id":"38","nombre":"Mantenimiento"},{"id":"7","nombre":"Producción y procesamiento"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"17","nombre":"Análisis de necesidades"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"31221","nombre":"Supervisores de procesamiento de alimentos y bebidas / Supervisoras de procesamiento de alimentos y bebidas"},{"codigo":"81600","nombre":"Operadores de máquinas para elaborar alimentos y productos afines / Operadoras de máquinas para elaborar alimentos y productos afines"}],"area_principal":{"sigla":"ETAL","nombre":"Elaboración y transformación de alimentos"},"areas_complementarias":[{"sigla":"AGVE","nombre":"Agropecuario, silvicultura, pesca, acuicultura y veterinaria"}],"equivalencias":[{"ciuo08_codigo":"7516","ciuo08_obs":"Denominaciones completas","cno_codigo":"9363*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"9364*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Operarios del tratamiento de la madera / Operarias del tratamiento de la madera', '75210', 'Transformación de la madera y fabricación de muebles', 2, false, '{"codigo":"75210","nombre":"Operarios del tratamiento de la madera / Operarias del tratamiento de la madera","descripcion":"Operan, controlan y mantienen equipos y máquinas como aserradoras, cepilladoras, trozadoras, cortadoras, desbastadoras, secadoras, hornos y tanques para el tratamiento de madera en diferentes tamaños y grosores, igualmente, clasifican, preservan y separan la madera de acuerdo con estándares de calidad. Se pueden desempeñar en aserraderos, plantas de tratamiento y procesamiento de madera, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"75","nombre":"OFICIALES Y OPERARIOS DE PROCESAMIENTO DE ALIMENTOS, DE LA CONFECCIÓN, EBANISTAS Y AFINES"},"subgrupo":{"codigo":"752","nombre":"Oficiales y operarios del tratamiento de la madera, ebanistas y afines"},"grupo_primario":{"codigo":"7521","nombre":"Operarios del tratamiento de la madera"}},"funciones":[{"consecutivo":1,"texto":"Accionar, detener y ajustar hornos, equipos de secado y tanques de tratamiento para disponer e impregnar la madera con sustancias conservantes."},{"consecutivo":2,"texto":"Observar y vigilar el funcionamiento equipos, indicadores, paneles de control y otros instrumentos para garantizar que los procesos estén operando de acuerdo con las especificaciones o detectar desviaciones y mal funcionamiento."},{"consecutivo":3,"texto":"Transportar materiales, productos, e insumos por las diferentes áreas de trabajo de forma manual o utilizando sistemas transportadores, carros, carretillas, polipastos, entre otros."},{"consecutivo":4,"texto":"Limpiar, lubricar, operar y mantener equipos de tratamiento y procesamiento de madera, máquinas cortadoras, cepilladoras, tronzadoras, intercaladoras, secadoras, aserradoras, calibradoras, prensas y otras herramientas manuales cuando se requiera."},{"consecutivo":5,"texto":"Clasificar, marcar y seleccionar troncos de madera de acuerdo con el tamaño, la condición y los estándares de calidad utilizando compases, calibradores y metros para garantizar la densidad, longitud y extensión."},{"consecutivo":6,"texto":"Ensamblar, reparar y tratar secciones de madera laminada de forma manual, mecánica o con productos químicos para evitar que se pudra o la ataquen parásitos."},{"consecutivo":7,"texto":"Accionar válvulas para introducir soluciones de tratamiento en contenedores y mantener niveles de calor, vacío, presión hidráulica y solución establecidos en los ciclos de transformación de la madera."},{"consecutivo":8,"texto":"Activar bombas de vacío y de presión hidráulica para eliminar el aire y vapor de contenedores y forzar la entrada de solución en los poros de la madera a fin de acelerar el proceso de impregnación."},{"consecutivo":9,"texto":"Elaborar, complementar y conservar informes de producción, inspección y clasificación en relación con la transformación y tratamiento de la madera."},{"consecutivo":10,"texto":"Inspeccionar visualmente la madera para reconocer troncos, determinar el tamaño, condición, calidad, detectar nudos, huecos, hendiduras y otros defectos y clasificarlo para el respectivo tratamiento."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"75210.001","nombre":"Impregnador de madera / Impregnadora de madera"},{"codigo":"75210.002","nombre":"Inmunizador de madera / Inmunizadora de madera"},{"codigo":"75210.003","nombre":"Operador de contenedores para tratamiento de madera / Operadora de contenedores para tratamiento de madera"},{"codigo":"75210.004","nombre":"Operador de hornos de secado de madera / Operadora de hornos de secado de madera"},{"codigo":"75210.005","nombre":"Operador de máquina impregnadora de madera / Operadora de máquina impregnadora de madera"},{"codigo":"75210.006","nombre":"Operador de máquina secadora de madera / Operadora de máquina secadora de madera"},{"codigo":"75210.007","nombre":"Operador de secado de chapa de madera / Operadora de secado de chapa de madera"},{"codigo":"75210.008","nombre":"Operador de secadores de madera / Operadora de secadores de madera"},{"codigo":"75210.009","nombre":"Operario de tratamiento de la madera / Operaria de tratamiento de la madera"},{"codigo":"75210.010","nombre":"Operario de tratamiento de madera para incisiones / Operaria de tratamiento de madera para incisiones"},{"codigo":"75210.011","nombre":"Secador de madera / Secadora de madera"}],"conocimientos":[{"id":"77","nombre":"Materiales (vidrio, papel, plástico y madera)"},{"id":"7","nombre":"Producción y procesamiento"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"17","nombre":"Análisis de necesidades"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"26","nombre":"Reparación"},{"id":"19","nombre":"Selección de equipo"}],"ocupaciones_afines":[{"codigo":"31432","nombre":"Supervisores de explotación forestal y silvicultura / Supervisoras de explotación forestal y silvicultura"},{"codigo":"75220","nombre":"Ebanistas y carpinteros (excluye carpinteros de armar y de obra blanca) / Ebanistas y carpinteras (excluye carpinteras de armar y de obra blanca)"},{"codigo":"75230","nombre":"Ajustadores y operadores de máquinas para trabajar madera / Ajustadoras y operadoras de máquinas para trabajar madera"},{"codigo":"81720","nombre":"Operadores de instalaciones de procesamiento de la madera / Operadoras de instalaciones de procesamiento de la madera"},{"codigo":"93291","nombre":"Obreros y ayudantes en el procesamiento de la madera y producción de pulpa y papel / Obreras y ayudantas en el procesamiento de la madera y producción de pulpa y papel"}],"area_principal":{"sigla":"TMFM","nombre":"Transformación de la madera y fabricación de muebles"},"are