  ('rol_cuoc', 'Ebanistas y carpinteros (excluye carpinteros de armar y de obra blanca) / Ebanistas y carpinteras (excluye carpinteras de armar y de obra blanca)', '75220', 'Transformación de la madera y fabricación de muebles', 2, false, '{"codigo":"75220","nombre":"Ebanistas y carpinteros (excluye carpinteros de armar y de obra blanca) / Ebanistas y carpinteras (excluye carpinteras de armar y de obra blanca)","descripcion":"Fabrican, decoran y reparan muebles, gabinetes, elementos de vehículos, equipos, plantillas, maquetas, accesorios y otros productos de madera utilizando máquinas de cortar, moldear, ensamblar, labrar madera y herramientas manuales de uso especial. Se pueden desempeñar en talleres de madera, fábricas de muebles, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"75","nombre":"OFICIALES Y OPERARIOS DE PROCESAMIENTO DE ALIMENTOS, DE LA CONFECCIÓN, EBANISTAS Y AFINES"},"subgrupo":{"codigo":"752","nombre":"Oficiales y operarios del tratamiento de la madera, ebanistas y afines"},"grupo_primario":{"codigo":"7522","nombre":"Ebanistas y carpinteros (excluye carpinteros de armar y de obra blanca)"}},"funciones":[{"consecutivo":1,"texto":"Operar máquinas para cortar, moldear, ensamblar partes y labrar madera como sierras, ensambladoras, fresadoras, cepillos mecánicos, entre otros."},{"consecutivo":2,"texto":"Analizar planos, dibujos, especificaciones y verificar dimensiones, calidad y ajuste de las piezas y los artículos en madera que han de fabricarse, con el fin de asegurar que se cumplan las especificaciones recibidas."},{"consecutivo":3,"texto":"Señalar trazos o dimensiones sobre la madera para recortar, ajustar y formar unidades completas usando cola, abrazaderas, además de reforzar los ensambles con pegantes, grapas, bisagras, puntillas, cerrojos, clavos, tornillos y otros sujetadores."},{"consecutivo":4,"texto":"Construir y reparar muebles de madera, matrices, plantillas, accesorios y otros productos relacionados, utilizando herramientas manuales y mecánicas."},{"consecutivo":5,"texto":"Lijar las superficies de madera, aplicar enchapados y dar acabado final a los artículos o muebles de madera."},{"consecutivo":6,"texto":"Preparar, pulir y adoptar partes de muebles, piezas de madera en el interior y exterior de los edificios como puertas, ventanas, escaleras y revestimientos, utilizando herramientas manuales y mecánicas."},{"consecutivo":7,"texto":"Fabricar, remodelar y reparar diversos artículos de madera como huacales, estibas, carretas en madera, armarios, muebles, mesas de billar, cajas para pianos, estuches, cajas para relojes de péndulo, maquetas, toneles, pipas de fumar, esquís, zuecos, raquetas y bastones, puertas, ventanas y otras piezas o productos en madera."},{"consecutivo":8,"texto":"Adornar muebles y accesorios con tallados, grabados, enchapados o incrustaciones decorativas de madera, usando herramientas manuales y mecánicas."},{"consecutivo":9,"texto":"Aplicar tinte, pinturas u otros materiales, usando brocha o pistola con el fin de dar acabado a la madera con un color específico."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"75220.001","nombre":"Ayudante técnico de ebanistería / Ayudante técnica de ebanistería"},{"codigo":"75220.002","nombre":"Chapeador de muebles de madera / Chapeadora de muebles de madera"},{"codigo":"75220.003","nombre":"Ebanista"},{"codigo":"75220.004","nombre":"Ebanista armador de fabricación de muebles / Ebanista armadora de fabricación de muebles"},{"codigo":"75220.005","nombre":"Ebanista de ataúdes"},{"codigo":"75220.006","nombre":"Ebanista de marquetería"},{"codigo":"75220.007","nombre":"Ebanista marquetero / Ebanista marquetera"},{"codigo":"75220.008","nombre":"Ebanista tallista"},{"codigo":"75220.009","nombre":"Esqueletero de fabricación muebles / Esqueletera de fabricación muebles"},{"codigo":"75220.010","nombre":"Fabricante de muebles en madera"},{"codigo":"75220.011","nombre":"Mueblista"},{"codigo":"75220.012","nombre":"Operario de lijado de madera / Operaria de lijado de madera"},{"codigo":"75220.014","nombre":"Operario ensamblador de espigas de madera / Operaria ensambladora de espigas de madera"},{"codigo":"75220.015","nombre":"Operario en ensamble de espigas de madera / Operaria en ensamble de espigas de madera"},{"codigo":"75220.016","nombre":"Patronista de madera"},{"codigo":"75220.017","nombre":"Tallista de madera"},{"codigo":"75220.018","nombre":"Taraceador de trabajo de la madera / Taraceadora de trabajo de la madera"},{"codigo":"75220.019","nombre":"Tonelero / Tonelera"},{"codigo":"75220.020","nombre":"Trazador de ebanistería / Trazadora de ebanistería"}],"conocimientos":[{"id":"11","nombre":"Diseño"},{"id":"77","nombre":"Materiales (vidrio, papel, plástico y madera)"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"17","nombre":"Análisis de necesidades"},{"id":"39","nombre":"Creatividad"},{"id":"2","nombre":"Escucha activa"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"71320","nombre":"Barnizadores y afines / Barnizadoras y afines"},{"codigo":"75230","nombre":"Ajustadores y operadores de máquinas para trabajar madera / Ajustadoras y operadoras de máquinas para trabajar madera"}],"area_principal":{"sigla":"TMFM","nombre":"Transformación de la madera y fabricación de muebles"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"7522*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"8351*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8352","cno_obs":"Denominaciones completas"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8611*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs"