  ('rol_cuoc', 'Ajustadores y operadores de máquinas para trabajar madera / Ajustadoras y operadoras de máquinas para trabajar madera', '75230', 'Transformación de la madera y fabricación de muebles', 2, false, '{"codigo":"75230","nombre":"Ajustadores y operadores de máquinas para trabajar madera / Ajustadoras y operadoras de máquinas para trabajar madera","descripcion":"Preparan, programan, operan y atienden máquinas, equipos, herramientas y aparatos de precisión que se utilizan para aserrar, limar, cepillar, perforar, tornear y tallar con el fin de fabricar o reparar piezas de madera para muebles, accesorios y otros productos. Se pueden desempeñar en fábricas de muebles, empresas de fabricación productos de madera, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"75","nombre":"OFICIALES Y OPERARIOS DE PROCESAMIENTO DE ALIMENTOS, DE LA CONFECCIÓN, EBANISTAS Y AFINES"},"subgrupo":{"codigo":"752","nombre":"Oficiales y operarios del tratamiento de la madera, ebanistas y afines"},"grupo_primario":{"codigo":"7523","nombre":"Ajustadores y operadores de máquinas para trabajar madera"}},"funciones":[{"consecutivo":1,"texto":"Ajustar, programar, manejar y vigilar diversos tipos de máquinas utilizadas para serrar, limar, perforar, taladrar, cepillar, prensar, tornear, lijar o tallar madera con el fin de fabricar piezas para muebles, accesorios y otros productos de madera."},{"consecutivo":2,"texto":"Operar máquinas preajustadas para fabricar productos de madera como ganchos para ropa, percheros, mangos de traperos, palos de escoba, pinzas para la ropa, entre otros."},{"consecutivo":3,"texto":"Preparar, programar, ajustar e instalar hojas, cabezales de fresado, brocas, correas de lijado en máquinas manuales o computarizadas para trabajar madera como canteadoras, sierras, cepillos, taladros, pulidoras, entre otros."},{"consecutivo":4,"texto":"Operar máquinas para ensamblar productos y accesorios de madera como ventanas, puertas, bastidores, cajones, escaleras, componentes modulares y otras partes prefabricadas de madera, utilizando pegantes, tuercas, tornillos, pernos, herramientas manuales o mecánicas, entre otros."},{"consecutivo":5,"texto":"Operar, atender y seleccionar cuchillas, sierras, hojas, cabezales de fresado, avellanadores, brocas o correas en función de las especificaciones de los productos que se van a labrar y la maquinaria y equipo utilizado para procesar madera."},{"consecutivo":6,"texto":"Preparar y operar máquinas, herramientas y equipos para acabar, adoptar, terminar y pulir partes de muebles y productos de madera."},{"consecutivo":7,"texto":"Seleccionar y marcar partes o productos defectuosos de madera para hacerles ajustes y reparaciones."},{"consecutivo":8,"texto":"Limpiar y lubricar equipos, máquinas y herramientas para labrar madera utilizados por otros trabajadores, y reemplazar partes si es necesario."},{"consecutivo":9,"texto":"Leer e interpretar especificaciones o seguir instrucciones verbales para la operación o el ajuste de máquinas para trabajar madera."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"75230.001","nombre":"Acabador de muebles de madera / Acabadora de muebles de madera"},{"codigo":"75230.002","nombre":"Ajustador de máquina para trabajo de la madera / Ajustadora de máquina para trabajo de la madera"},{"codigo":"75230.003","nombre":"Ajustador operador de ranuradora de madera / Ajustadora operadora de ranuradora de madera"},{"codigo":"75230.004","nombre":"Ajustador operador de máquinas para trabajo de la madera / Ajustadora operadora de máquinas para trabajo de la madera"},{"codigo":"75230.005","nombre":"Ajustador operador de torno para madera / Ajustadora operadora de torno para madera"},{"codigo":"75230.006","nombre":"Marcador de madera / Marcadora de madera"},{"codigo":"75230.007","nombre":"Operador de cepilladora de madera / O