  ('rol_cuoc', 'Costureros, bordadores y afines / Costureras, bordadoras y afines', '75330', 'Textil, cuero, confección y diseño de modas', 2, false, '{"codigo":"75330","nombre":"Costureros, bordadores y afines / Costureras, bordadoras y afines","descripcion":"Cosen, reparan, renuevan y bordan prendas de vestir, guantes u otros productos de tela, cueros finos y otros materiales; confeccionan velas para barcos, carpas, toldos y otros artículos de lona impermeable. Su trabajo lo hacen principalmente a mano, con aguja e hilo, pero pueden realizar algunas tareas con máquina de coser. Se pueden desempeñar en talleres de modistería, sastrería, empresas de confección, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"75","nombre":"OFICIALES Y OPERARIOS DE PROCESAMIENTO DE ALIMENTOS, DE LA CONFECCIÓN, EBANISTAS Y AFINES"},"subgrupo":{"codigo":"753","nombre":"Oficiales y operarios de la confección y afines"},"grupo_primario":{"codigo":"7533","nombre":"Costureros, bordadores y afines"}},"funciones":[{"consecutivo":1,"texto":"Ajustar, modificar y reparar a mano, con aguja e hilo tejidos o prendas de vestir de acuerdo con los requerimientos del cliente."},{"consecutivo":2,"texto":"Soltar puntadas de prendas que han de modificarse, empleando cuchillas u otros utensilios."},{"consecutivo":3,"texto":"Seleccionar el hilo de acuerdo con las especificaciones recibidas o en función del color, para que entone con el color y el matiz de la tela que se remiende."},{"consecutivo":4,"texto":"Coser, cortar y adaptar a mano, con hilo y aguja accesorios, adornos, diseños decorativos en prendas de vestir, patrones estampados, impresos o estarcidos en tela."},{"consecutivo":5,"texto":"Invertir el abotonado de las prendas, añadiendo ganchos a mano, con hilo y aguja."},{"consecutivo":6,"texto":"Recortar y pulir bordes con tijera y otras herramientas de costura para que las partes arregladas queden uniformes con el dibujo o patrón del diseño."},{"consecutivo":7,"texto":"Bordar diseños decorativos a mano o a máquina no industrial, con aguja e hilo de color."},{"consecutivo":8,"texto":"Coser a mano las telas a la armadura de paraguas y sombrillas, haciendo coincidir los cordoncillos con las costuras, fijar los ángulos a los extremos de las varillas y unirlas de tal modo que queden sujetas al plegarse la sombrilla."},{"consecutivo":9,"texto":"Confeccionar y montar telas gruesas, lonas y materiales análogos en velas, toldos, tiendas y otros artículos de lona impermeable."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"75330.001","nombre":"Bordador a mano no artesanal / Bordadora a mano no artesanal"},{"codigo":"75330.002","nombre":"Cosedor a mano de prendas de vestir / Cosedora a mano de prendas de vestir"},{"codigo":"75330.003","nombre":"Costurero / Costurera"},{"codigo":"75330.004","nombre":"Costurero / Costurera"},{"codigo":"75330.005","nombre":"Operario de manualidades de prendas de vestir / Operaria de manualidades de prendas de vestir"},{"codigo":"75330.006","nombre":"Paragüero / Paragüera"},{"codigo":"75330.007","nombre":"Pasamanero / Pasamanera"},{"codigo":"75330.008","nombre":"Remendador de tejidos / Remendadora de tejidos"}],"conocimientos":[{"id":"11","nombre":"Diseño"},{"id":"22","nombre":"Educación y capacitación"},{"id":"84","nombre":"Productos textiles (ropa, calzado y artículos de cuero)"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"6","nombre":"Pensamiento crítico"}],"ocupaciones_afines":[{"codigo":"75310","nombre":"Sastres, modistos, peleteros y sombrereros / Sastresas, modistas, peleteras y sombrereras"},{"codigo":"75322","nombre"