  ('rol_cuoc', 'Tapiceros, colchoneros y afines / Tapiceras, colchoneras y afines', '75340', 'Textil, cuero, confección y diseño de modas', 2, false, '{"codigo":"75340","nombre":"Tapiceros, colchoneros y afines / Tapiceras, colchoneras y afines","descripcion":"Instalan, reparan y sustituyen tapicerías de muebles, accesorios, artículos de ortopedia, asientos, paneles, capotas y otros elementos de automóviles utilizando tela, cuero, cuero artificial u otros materiales de tapizado. También confeccionan y arreglan cojines, edredones y colchones. Se pueden desempeñar en fábricas de muebles, empresas de colchones, talleres de restauración de muebles, empresas de tapizado automotriz, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"75","nombre":"OFICIALES Y OPERARIOS DE PROCESAMIENTO DE ALIMENTOS, DE LA CONFECCIÓN, EBANISTAS Y AFINES"},"subgrupo":{"codigo":"753","nombre":"Oficiales y operarios de la confección y afines"},"grupo_primario":{"codigo":"7534","nombre":"Tapiceros, colchoneros y afines"}},"funciones":[{"consecutivo":1,"texto":"Trazar, medir y cortar materiales de tapicería siguiendo patrones, plantillas, diseños, bocetos o especificaciones del cliente."},{"consecutivo":2,"texto":"Coser, entrelazar y juntar partes descosidas y desgarros en la tapicería de colchones, cojines, almohadones, almohadas, entre otros, utilizando aguja e hilo de forma manual o con máquina."},{"consecutivo":3,"texto":"Confeccionar patrones de tapizado, edredones, almohadones y colchones a partir de bocetos, planos y especificaciones de los clientes."},{"consecutivo":4,"texto":"Reemplazar telas deterioradas, resortes y otras partes de colchones y muebles tapizados usando herramientas manuales o eléctricas."},{"consecutivo":5,"texto":"Incrustar, hilvanar, engomar, pegar o coser a la tapicería adornos, cintas, broches, galones, botones y otros accesorios a los artículos tapizados."},{"consecutivo":6,"texto":"Colocar, disponer y sujetar los muelles, el relleno y la tapicería de los muebles, de acuerdo con especificaciones técnicas."},{"consecutivo":7,"texto":"Trazar, cortar, confeccionar, e instalar tapicerías y otros revestimientos de interior en aviones, vehículos de motor, coches de ferrocarril, embarcaciones, buques, entre otros."},{"consecutivo":8,"texto":"Analizar y apoyar a clientes en la selección de materiales, colores, estilo y calcular los costos de mobiliario, alfombras y tapizado de interiores que se requieren."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"75340.001","nombre":"Auxiliar de tapicería"},{"codigo":"75340.002","nombre":"Ayudante técnico de tapicería / Ayudante técnica de tapicería"},{"codigo":"75340.003","nombre":"Colchonero / Colchonera"},{"codigo":"75340.004","nombre":"Confeccionador de edredones / Confeccionadora de edredones"},{"codigo":"75340.005","nombre":"Confeccionador de tapicería / Confeccionadora de tapicería"},{"codigo":"75340.006","nombre":"Restaurador de tapicería / Restauradora de tapicería"},{"codigo":"75340.007","nombre":"Tapicero / Tapicera"},{"codigo":"75340.008","nombre":"Tapicero de automóviles / Tapicera de automóviles"},{"codigo":"75340.009","nombre":"Tapicero de artículos de ortopedia / Tapicera de artículos de ortopedia"},{"codigo":"75340.010","nombre":"Tapicero de muebles / Tapicera de muebles"},{"codigo":"75340.011","nombre":"Tapicero de vehículos / Tapicera de vehículos"}],"conocimientos":[{"id":"11","nombre":"Diseño"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"17","nombre":"Análisis de necesidades"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"26","nombre":"Reparación"}],"ocupaciones_afines":[{"codigo":"75322","nombre"