  ('rol_cuoc', 'Zapateros y afines / Zapateras y afines', '75360', 'Textil, cuero, confección y diseño de modas', 2, false, '{"codigo":"75360","nombre":"Zapateros y afines / Zapateras y afines","descripcion":"Confeccionan, fabrican, modifican, reparan, refuerzan y dan acabado a calzado normal, especial, a medida, ortopédico y otros artículos como maletas, bolsos de mano, cinturones (exceptuando prendas de vestir, sombreros y guantes) de cuero natural o artificial, asimismo, participan en la fabricación y decoración de zapatos, maletas, bolsos de mano, cinturones y artículos similares. Se pueden desempeñar en establecimientos de fabricación de calzado, marroquinerías, zapaterías, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"75","nombre":"OFICIALES Y OPERARIOS DE PROCESAMIENTO DE ALIMENTOS, DE LA CONFECCIÓN, EBANISTAS Y AFINES"},"subgrupo":{"codigo":"753","nombre":"Oficiales y operarios de la confección y afines"},"grupo_primario":{"codigo":"7536","nombre":"Zapateros y afines"}},"funciones":[{"consecutivo":1,"texto":"Tomar medidas y preparar insertos, plantillas y alzas a partir de moldes de pies para confeccionar el tipo de calzado requerido de los clientes."},{"consecutivo":2,"texto":"Confeccionar, modificar y reparar calzado normal, terapéutico u ortopédico de acuerdo con prescripciones médicas, medidas y necesidades especiales de los clientes."},{"consecutivo":3,"texto":"Preparar de forma manual o con máquina capelladas para montar o ensuelar calzado, de acuerdo con especificaciones técnicas."},{"consecutivo":4,"texto":"Retirar, examinar zapatos y dar acabado al calzado, suelas, encajes, diseños y partes de zapato quitando imperfectos, suavizando y sacándole brillo para verificar que cumplen las especificaciones requeridas."},{"consecutivo":5,"texto":"Confeccionar, reparar y mantener artículos monturas, suelas, tacones, aperos, arneses para caballería y otros artículos de cuero utilizando máquinas cosedoras, pulidoras y otros materiales para asegurar que son adecuados para el fin concreto a que se destinan."},{"consecutivo":6,"texto":"Añadir accesorios, elementos y parches para adornar, proteger o reparar productos de cuero como bolsos, cinturones, zapatos, maletas, entre otros."},{"consecutivo":7,"texto":"Estudiar planos, pedidos, identificaciones y otras especificaciones para determinar cargas de trabajo, detalles de pedido y materiales que han de emplearse para confeccionar calzado de acuerdo con las necesidades de clientes."},{"consecutivo":8,"texto":"Seleccionar, cortar, moldear, acolchar y ensamblar hormas, plantillas y piezas con las que se han de confeccionar zapatos y artículos de cuero."},{"consecutivo":9,"texto":"Alistar y operar máquinas de costura para aplicar adhesivos, unir plantillas, suelas y demás partes del calzado y marroquinería de forma manual o con máquina."},{"consecutivo":10,"texto":"Reparar monturas, maletas, maletines, bolsos de mano, bolsos, cinturones, arneses para animales y artículos similares en cuero."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"75360.001","nombre":"Acabador de calzado / Acabadora de calzado"},{"codigo":"75360.002","nombre":"Armador de calzado / Armadora de calzado"},{"codigo":"75360.003","nombre":"Armador de productos de marroquinería / Armadora de productos de marroquinería"},{"codigo":"75360.004","nombre":"Auxiliar de armado de calzado"},{"codigo":"75360.005","nombre":"Auxiliar de corte de calzado"},{"codigo":"75360.006","nombre":"Auxiliar de ensuelado"},{"codigo":"75360.007","nombre":"Auxiliar de entintado de calzado"},{"codigo":"75360.008","nombre":"Auxiliar de estampado de calzado"},{"codigo":"75360.009","nombre":"Auxiliar de guarnición"},{"codigo":"75360.010","nombre":"Auxiliar de montaje de calzado"},{"codigo":"75360.011","nombre":"Auxiliar de zapatería"},{"codigo":"75360.012","nombre":"Clasifica