  ('rol_cuoc', 'Buzos / Buzas', '75410', 'Seguridad', 2, false, '{"codigo":"75410","nombre":"Buzos / Buzas","descripcion":"Realizan actividades bajo el agua con o sin la ayuda de aparatos de respiración en inmersión para inspeccionar, instalar, reparar y desmontar instalaciones y equipos, llevar a cabo pruebas o experimentos, colocar explosivos, fotografiar estructuras o formas de vida marina, recolectar diversas especies acuáticas con fines comerciales o de investigación, buscar y salvar a personas y recuperar cadáveres y objetos. Se pueden desempeñar en empresas comerciales de buceo y constructoras de barcos, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"75","nombre":"OFICIALES Y OPERARIOS DE PROCESAMIENTO DE ALIMENTOS, DE LA CONFECCIÓN, EBANISTAS Y AFINES"},"subgrupo":{"codigo":"754","nombre":"Otros oficiales, operarios y afines"},"grupo_primario":{"codigo":"7541","nombre":"Buzos"}},"funciones":[{"consecutivo":1,"texto":"Cumplir con las normas de seguridad, salud y medio ambiente para desarrollar una actividad profesional, militar, recreativa, deportiva o de investigación científica con o sin ayuda de equipos especiales de buceo."},{"consecutivo":2,"texto":"Comprobar y mantener el equipo de buceo como cascos, mascarillas, depósitos de aire, trajes de inmersión, arneses e indicadores de acuerdo con la normativa."},{"consecutivo":3,"texto":"Hacer inmersiones en cuerpos de agua con el apoyo de buceadores auxiliares con o sin ayuda de equipos o trajes especiales de buceo."},{"consecutivo":4,"texto":"Trabajar bajo el agua para colocar o reparar cimientos de puentes, muelles o malecones teniendo en cuenta especificaciones y normativa."},{"consecutivo":5,"texto":"Inspeccionar cascos de embarcaciones, tuberías, bocatomas y otras instalaciones bajo el agua para detectar posibles averías o deterioros para informar y efectuar reparaciones."},{"consecutivo":6,"texto":"Operar equipo de grabación submarina y otro equipo para propósitos científicos o exploratorios."},{"consecutivo":7,"texto":"Soldar e instalar tuberías, posicionar pilotes y otras estructuras y mantener estas estructuras utilizando herramientas y equipo neumático."},{"consecutivo":8,"texto":"Perforar agujeros para ubicar y denotar explosivos para llevar a cabo voladuras bajo el agua, remover obstáculos y destruir o sacar a flote objetos sumergidos."},{"consecutivo":9,"texto":"Participar en operaciones de rescate, salvamento y limpieza bajo el agua de acuerdo con requerimientos y normativa."},{"consecutivo":10,"texto":"Apartar obstáculos y recolectar mariscos, esponjas y otras formas de vida acuática que se encuentren bajo el agua."},{"consecutivo":11,"texto":"Obtener información sobre las tareas de buceo, las condiciones del entorno y comunicarse con los trabajadores de superficie durante la inmersión, empleando líneas de señales o teléfonos."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"75410.001","nombre":"Buzo"},{"codigo":"75410.002","nombre":"Buzo comercial"},{"codigo":"75410.003","nombre":"Buzo de rescate"},{"codigo":"75410.004","nombre":"Buzo de salvamento"},{"codigo":"75410.005","nombre":"Buzo militar de salvamento"},{"codigo":"75410.006","nombre":"Buzo montador de estructuras metálicas / Buzo montadora de estructuras metálicas"},{"codigo":"75410.007","nombre":"Buzo pescador de esponjas / Buzo pescadora de esponjas"},{"codigo":"75410.008","nombre":"Buzo pescador de ostras / Buzo pescadora de ostras"},{"codigo":"75410.009","nombre":"Hombre rana de salvamento / Mujer rana de salvamento"},{"codigo":"75410.010","nombre":"Soldador bajo el agua / Soldadora bajo el agua"},{"codigo":"75410.011","nombre":"Soldador submarino / Soldadora submarina"},{"codigo":"75410.012","nombre":"Trabajador bajo el agua / Trabajadora bajo el agua"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"20","nombre":"Geografía y territorio"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"23","nombre":"Vigilancia de las operaciones"}],"ocupaciones_afines":[{"codigo":"63400","nombre":"Pescadores, cazadores, tramperos y recolectores de subsistencia / Pescadoras, cazadoras, tramperas y recolectoras de subsistencia"},{"codigo":"72120","nombre":"Soldadores y oxicortadores / Soldadoras y oxicortadoras"}],"area_principal":{"sigla":"SEGU","nombre":"Seguridad"},"areas_complementarias":[{"sigla":"AGVE","nombre":"Agropecuario, silvicultura, pesca, acuicultura y veterinaria"},{"sigla":"COIF","nombre":"Construcción e infraestructura"},{"sigla":"FAMA","nombre":"Fabricación, transformación de materiales, instalación, mantenimiento y reparación"},{"sigla":"LOTR","nombre":"Logística y transporte"},{"sigla":"TUHG","nombre":"Turismo, hotelería y gastronomía"}],"equivalencias":[{"ciuo08_codigo":"7541","ciuo08_obs":"Denominaciones completas","cno_codigo":"8342*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8427","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Dinamiteros y pegadores / Dinamiteras y pegadoras', '75420', 'Exploración y extracción de minas, canteras, petróleo y gas', 2, false, '{"codigo":"75420","nombre":"Dinamiteros y pegadores / Dinamiteras y pegadoras","descripcion":"Colocan, montan y detonan explosivos en minas, canteras, obras civiles, construcción de túneles, pasadizos, pozos de ventilación y obras de demolición. Se pueden desempeñar en empresas de explotación minera, canteras, compañías constructoras, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"75","nombre":"OFICIALES Y OPERARIOS DE PROCESAMIENTO DE ALIMENTOS, DE LA CONFECCIÓN, EBANISTAS Y AFINES"},"subgrupo":{"codigo":"754","nombre":"Otros oficiales, operarios y afines"},"grupo_primario":{"codigo":"7542","nombre":"Dinamiteros y pegadores"}},"funciones":[{"consecutivo":1,"texto":"Planificar la disposición, la profundidad y el diámetro de perforaciones para barrenos, comprobar que han detonado los explosivos e informar sobre fallos y subsanarlos."},{"consecutivo":2,"texto":"Montar cargas de cebo usando detonadores, mechas, cuerdas de detonación, cartuchos explosivos y dirigir a otros trabajadores para que las monten y conecten los filamentos eléctricos, fusibles y cordones detonadores correspondientes."},{"consecutivo":3,"texto":"Instalar y operar taladros, máquinas y equipos de perforación para abrir barrenos y determinar la ubicación de cargas explosivas de acuerdo con profundidades específicas y posiciones demarcadas en minas, canteras y cimientos de edificaciones."},{"consecutivo":4,"texto":"Conectar fusibles, mechas, cordones detonadores en serie, filamentos y alambrados eléctricos a máquinas para realizar voladuras y hacer estallar las cargas en forma normal o por controles."},{"consecutivo":5,"texto":"Interpretar instrucciones y diagramas para determinar el tipo, lugar, cantidad y calidad de explosivos que se requieren para obtener la fragmentación deseada."},{"consecutivo":6,"texto":"Manejar, almacenar, transportar y asegurar que se cumplan procedimientos de manejo de explosivos y normas de seguridad en los lugares de trabajo de conformidad con leyes y reglamentos pertinentes."},{"consecutivo":7,"texto":"Colocar y comprobar la profundidad y limpieza de las perforaciones, cubrir las cargas explosivas, terminar de llenar los barrenos con polvo de roca, arena, entre otros materiales y apisonar el material para compactar las cargas."},{"consecutivo":8,"texto":"Cargar explosivos, confirmar y anunciar la seguridad de las zonas de voladura antes y después de las detonaciones."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"75420.001","nombre":"Artillero de canteras / Artillera de canteras"},{"codigo":"75420.002","nombre":"Auxiliar de voladura de minería subterránea"},{"codigo":"75420.003","nombre":"Barrenero / Barrenera"},{"codigo":"75420.004","nombre":"Barrenero de cantera / Barrenera de cantera"},{"codigo":"75420.005","nombre":"Barrenero de construcción / Barrenera de construcción"},{"codigo":"75420.006","nombre":"Barrenero de minería de superficie / Barrenera de minería de superficie"},{"codigo":"75420.007","nombre":"Cargapozo"},{"codigo":"75420.008","nombre":"Dinamitero / Dinamitera"},{"codigo":"75420.009","nombre":"Dinamitero de minas / Dinamitera de minas"},{"codigo":"75420.010","nombre":"Disparador de hidrocarburos / Disparadora de hidrocarburos"},{"codigo":"75420.011","nombre":"Grumete encargado de la pólvora / Grumete encargada de la pólvora"},{"codigo":"75420.012","nombre":"Operario de vehículo de transporte de explosivos de minería subterránea / Operaria de vehículo de transporte de explosivos de minería subterránea"},{"codigo":"75420.013","nombre":"Operario de voladura de construcción / Operaria de voladura de construcción"},{"codigo":"75420.014","nombre":"Operario de voladura de minería a cielo abierto / Operaria 