  ('rol_cuoc', 'Analistas de calidad de textiles', '75431', 'Textil, cuero, confección y diseño de modas', 2, false, '{"codigo":"75431","nombre":"Analistas de calidad de textiles","descripcion":"Preparan muestras, examinan y clasifican productos textiles para descubrir defectos, desgastes y desviaciones para asegurar que se cumplan los estándares de calidad y especificaciones. Se pueden desempeñar en empresas textilerías, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"75","nombre":"OFICIALES Y OPERARIOS DE PROCESAMIENTO DE ALIMENTOS, DE LA CONFECCIÓN, EBANISTAS Y AFINES"},"subgrupo":{"codigo":"754","nombre":"Otros oficiales, operarios y afines"},"grupo_primario":{"codigo":"7543","nombre":"Clasificadores y probadores de productos (excluyendo alimentos y bebidas)"}},"funciones":[{"consecutivo":1,"texto":"Inspeccionar y probar materiales textiles de conformidad a especificaciones, normas y estándares de calidad."},{"consecutivo":2,"texto":"Clasificar y organizar fibras textiles por calidad, estilos, colores, tamaño, grosor y otros criterios para su hilado y bobinado."},{"consecutivo":3,"texto":"Marcar defectos sobre los textiles indicando clase y grado de aceptación o rechazo de acuerdo con las especificaciones."},{"consecutivo":4,"texto":"Medir las dimensiones y pesar textiles empleando instrumentos como: reglas, calibres o micrómetros."},{"consecutivo":5,"texto":"Notificar a los supervisores y a otros miembros del personal de producción textil sobre el mal funcionamiento de las máquinas."},{"consecutivo":6,"texto":"Registrar información obtenida en las inspecciones y pruebas de los textiles como: peso, temperatura, grado, humedad, cantidad, entre otros."},{"consecutivo":7,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"75431.001","nombre":"Analista de calidad de textiles"},{"codigo":"75431.002","nombre":"Analista de calidad de telas"},{"codigo":"75431.003","nombre":"Analista de calidad fibras"},{"codigo":"75431.004","nombre":"Analista de calidad hilatura"},{"codigo":"75431.005","nombre":"Analista de calidad tejeduría"},{"codigo":"75431.006","nombre":"Analista de calidad tintorería y acabados"},{"codigo":"75431.007","nombre":"Analista de laboratorio de fibras textiles"},{"codigo":"75431.008","nombre":"Analista de telas"},{"codigo":"75431.009","nombre":"Auxiliar de revisión de textiles"},{"codigo":"75431.010","nombre":"Clasificador de lanas / Clasificadora de lanas"},{"codigo":"75431.011","nombre":"Clasificador de textiles / Clasificadora de textiles"},{"codigo":"75431.012","nombre":"Clasificador de fibras textiles / Clasificadora de fibras textiles"},{"codigo":"75431.013","nombre":"Clasificador de productos textiles / Clasificadora de productos textiles"},{"codigo":"75431.014","nombre":"Clasificador de telas / Clasificadora de telas"},{"codigo":"75431.015","nombre":"Examinador de telas / Examinadora de telas"},{"codigo":"75431.016","nombre":"Inspector de control de calidad de fibras textiles / Inspectora de control de calidad de fibras textiles"},{"codigo":"75431.017","nombre":"Inspector de control de calidad de hilados / Inspectora de control de calidad de hilados"},{"codigo":"75431.018","nombre":"Inspector de control de calidad de tejido de punto / Inspectora de control de calidad de tejido de punto"},{"codigo":"75431.019","nombre":"Inspector de control de calidad de tejidos / Inspectora de control de calidad de tejidos"},{"codigo":"75431.020","nombre":"Inspector de control de calidad de textiles / Inspectora de control de calidad de textiles"},{"codigo":"75431.021","nombre":"Inspector de telas / Inspectora de telas"},{"codigo":"75431.022","nombre":"Inspector de textiles / Inspectora de textiles"},{"codigo":"75431.023","nombre":"Revisor de tejidos / Revisora de tejidos"},{"codigo":"75431.024","nombre":"Revisor de telas / Revisora de telas"}],"conocimientos":[{"id":"22","nombre":"