  ('rol_cuoc', 'Inspectores de control de calidad, fabricación de productos de tela, piel y cuero / Inspectoras de control de calidad, fabricación de productos de tela, piel y cuero', '75432', 'Textil, cuero, confección y diseño de modas', 2, false, '{"codigo":"75432","nombre":"Inspectores de control de calidad, fabricación de productos de tela, piel y cuero / Inspectoras de control de calidad, fabricación de productos de tela, piel y cuero","descripcion":"Inspeccionan y clasifican pieles, cueros, prendas de vestir y otros productos manufacturados de tela, cuero o piel para asegurar que se cumplan los estándares de calidad y especificaciones. Se pueden desempeñar en curtiembres, empresas de confección, calzado y marroquinería, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"75","nombre":"OFICIALES Y OPERARIOS DE PROCESAMIENTO DE ALIMENTOS, DE LA CONFECCIÓN, EBANISTAS Y AFINES"},"subgrupo":{"codigo":"754","nombre":"Otros oficiales, operarios y afines"},"grupo_primario":{"codigo":"7543","nombre":"Clasificadores y probadores de productos (excluyendo alimentos y bebidas)"}},"funciones":[{"consecutivo":1,"texto":"Inspeccionar y clasificar telas, pieles y cueros, de acuerdo con tamaño, condición, peso y especificaciones técnicas."},{"consecutivo":2,"texto":"Inspeccionar y probar productos, piezas y materiales en la fabricación de tela, piel y cuero para asegurar el cumplimiento de especificaciones y normas."},{"consecutivo":3,"texto":"Verificar talla, tamaño y modelo de las prendas y calzados en tela, piel o cuero sobre figurines, plantillas, entre otros."},{"consecutivo":4,"texto":"Registrar los datos obtenidos en las inspecciones y pruebas en la fabricación de productos de tela, piel o cuero como: peso, temperatura, grado, humedad, cantidad clasificada, entre otros."},{"consecutivo":5,"texto":"Auditar la calidad durante el proceso de confección y manufactura de cuero, calzado y marroquinería."},{"consecutivo":6,"texto":"Analizar los datos de las pruebas de control de calidad en la fabricación de productos de tela, piel y cuero."},{"consecutivo":7,"texto":"Determinar los parámetros de calidad de los productos de confección, cuero, calzado y marroquinería."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"75432.001","nombre":"Auditor de calidad de calzado / Auditora de calidad de calzado"},{"codigo":"75432.002","nombre":"Auditor de calidad de confección / Auditora de calidad de confección"},{"codigo":"75432.003","nombre":"Auditor de calidad de marroquinería / Auditora de calidad de marroquinería"},{"codigo":"75432.004","nombre":"Examinador de ropa / Examinadora de ropa"},{"codigo":"75432.005","nombre":"Inspector de calidad en confección / Inspectora de calidad en confección"},{"codigo":"75432.006","nombre":"Inspector de control de calidad en marroquinería / Inspectora de control de calidad en marroquinería"},{"codigo":"75432.007","nombre":"Inspector de confección / Inspectora de confección"},{"codigo":"75432.008","nombre":"Inspector de control de calidad de calzado / Inspectora de control de calidad de calzado"},{"codigo":"75432.009","nombre":"Inspector de control de calidad de productos de piel / Inspectora de control de calidad de productos de piel"},{"codigo":"75432.010","nombre":"Inspector de lencería / Inspectora de lencería"},{"codigo":"75432.011","nombre":"Inspector de prendas de vestir / Inspectora de prendas de vestir"},{"codigo":"75432.012","nombre":"Inspector de productos de cuero / Inspectora de productos de cuero"},{"codigo":"75432.013","nombre":"Inspector para la manufacturación del cuero / Inspectora para la manufacturación del cuero"},{"codigo":"75432.014","nombre":"Jefe de calidad de calzado y marroquinería / Jefa de calidad de calzado y marroquinería"},{"codigo":"75432.015","nombre":"Jefe de calidad de confección / Jefa de calidad de confección"},{"codigo":"75432.016","nombre":"Muestreador de textiles / Muestreadora de textiles"},{"codigo":"75432.017","nombre":"Revisador de calidad / Revisadora de calidad"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"7","nombre":"Producción y procesamiento"},{"id":"84","nombre":"Productos textiles (ropa, calzado y artículos de cuero)"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"1","nombre":"Comprensión de lectura"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"10","nombre":"Relaciones interpersonales"}],"ocupaciones_afines":[{"codigo":"75431","nombre":"Analistas de calidad de textiles"},{"codigo":"75439","nombre":"Clasificadores y probadores de productos (excluyendo alimentos y bebidas) no clasificados en otras ocupaciones / Clasificadoras y probadoras de productos (excluyendo alimentos y bebidas) no clasificados en otras ocupaciones"}],"area_principal":{"sigla":"TCCD","nombre":"Textil, cuero, confección y diseño de modas"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"7543*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"9344*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"9355*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Inspectores de control de calidad, procesamiento de la madera / Inspectoras de control de calidad, procesamiento de la madera', '75433', 'Transformación de la madera y fabricación de muebles', 2, false, '{"codigo":"75433","nombre":"Inspectores de control de calidad, procesamiento de la madera / Inspectoras de control de calidad, procesamiento de la madera","descripcion":"Inspeccionan y miden madera aserrada, tablas, enchapes y productos similares de madera para identificar defectos, garantizar la conformidad con especificaciones y clasificar productos de acuerdo con estándares. Se pueden desempeñar en aserraderos y establecimientos donde se procesa la madera, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"75","nombre":"OFICIALES Y OPERARIOS DE PROCESAMIENTO DE ALIMENTOS, DE LA CONFECCIÓN, EBANISTAS Y AFINES"},"subgrupo":{"codigo":"754","nombre":"Otros oficiales, operarios y afines"},"grupo_primario":{"codigo":"7543","nombre":"Clasificadores y probadores de productos (excluyendo alimentos y bebidas)"}},"funciones":[{"consecutivo":1,"texto":"Inspeccionar tableros y piezas de madera aserrada, laminada, tríplex y otros productos similares de la madera para detectar nudos, huecos, rajaduras y otros defectos de acuerdo con especificaciones y normas."},{"consecutivo":2,"texto":"Examinar la madera aserrada para detectar nudos, huecos, rajaduras y otros defectos para descartar, rechazar y seleccionar para su tratamiento, de acuerdo con especificaciones."},{"consecutivo":3,"texto":"Interpretar tipos de madera y analizar datos para verificar y determinar especificaciones de grosor, longitud y anchura para definir procedimientos de inspección y prueba."},{"consecutivo":4,"texto":"Marcar los defectos de la madera y separarlos para reparación o reprocesamiento de acuerdo con especificaciones técnicas."},{"consecutivo":5,"texto":"Registrar los datos obtenidos en las inspecciones y pruebas en el procesamiento de la madera como: peso, temperatura, grado, humedad, y cantidades inspeccionadas o clasificadas."},{"consecutivo":6,"texto":"Medir productos de madera para garantizar el cumplimiento de las especificaciones, utilizando instrumentos como: reglas, calibres, micrómetros o de medidas estándar."},{"consecutivo":7,"texto":"Clasificar, marcar y separar productos de madera de acuerdo con estándares de calidad."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"75433.001","nombre":"Clasificador de madera / Clasificadora de madera"},{"codigo":"75433.002","nombre":"Clasificador de madera aserrada / Clasificadora de madera aserrada"},{"codigo":"75433.003","nombre":"Clasificador de madera chapada / Clasificadora de madera chapada"},{"codigo":"75433.004","nombre":"Clasificador de madera procesada / Clasificadora de madera procesada"},{"codigo":"75433.005","nombre":"Inspector de calidad de ensamble de muebles y accesorios / Inspectora de calidad de ensamble de muebles y accesorios"},{"codigo":"75433.006","nombre":"Inspector de madera aserrada / Inspectora de madera aserrada"},{"codigo":"75433.007","nombre":"Inspector de madera procesada / Inspectora de madera procesada"}],"conocimientos":[{"id":"22","nombre":"Educación y capacitación"},{"id":"7","nombre":"Producción y procesamiento"},{"id":"84","nombre":"Productos textiles (ropa, calzado y artículos de cuero)"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"9","nombre":"Evaluación y control de actividades"},{"id":"32","nombre":"Gestión del Talento Humano y de Personal"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"23","nombre":"Vigilancia de las operaciones"}],"ocupaciones_afines":[{"codigo":"31223","nombre":"Supervisores de procesamiento de la madera y producción de pulpa y papel / Supervisoras de procesamiento de la madera y producción de pulpa y papel"},{"codigo":"75439","nombre":"Clasificadores y probadores de productos (excluyendo alimentos y bebidas) no clasificados en otras ocupaciones / Clasificadoras y probadoras de productos (excluyendo alimentos y bebidas) no clasificados en otras ocupaciones"}],"area_principal":{"sigla":"TMFM","nombre":"Transformación de la madera y fabricación de muebles"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"7521*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"9335*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"7543*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"9392*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Clasificadores y probadores de productos (excluyendo alimentos y bebidas) no clasificados en otras ocupaciones / Clasificadoras y probadoras de productos (excluyendo alimentos y bebidas) no clasificados en otras ocupaciones', '75439', 'Fabricación, transformación de materiales, instalación, mantenimiento y reparación', 2, false, '{"codigo":"75439","nombre":"Clasificadores y probadores de productos (excluyendo alimentos y bebidas) no clasificados en otras ocupaciones / Clasificadoras y probadoras de productos (excluyendo alimentos y bebidas) no clasificados en otras ocupaciones","descripcion":"Esta ocupación abarca a Clasificadores y probadores de productos (excluyendo alimentos y bebidas) no clasificados en otras ocupaciones del Grupo Primario 7543 Clasificadores y probadores de productos (excluyendo alimentos y bebidas) no clasificados en otras ocupaciones. Por ejemplo, incluye aquellos que Inspeccionan, prueban, clasifican, muestrean y pesan materias primas, componentes fabricados y artículos no comestibles producidos o vendidos, para asegurar que se cumplan los estándares de calidad y descubrir defectos, desgastes y desviaciones con respecto a las especificaciones y ordenar y clasificar dichos productos de acuerdo con su calidad. Se pueden desempeñar en empresas manufactureras, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"7","nombre":"OFICIALES, OPERARIOS, ARTESANOS Y OFICIOS RELACIONADOS"},"subgrupo_principal":{"codigo":"75","nombre":"OFICIALES Y OPERARIOS DE PROCESAMIENTO DE ALIMENTOS, DE LA CONFECCIÓN, EBANISTAS Y AFINES"},"subgrupo":{"codigo":"754","nombre":"Otros oficiales, operarios y afines"},"grupo_primario":{"codigo":"7543","nombre":"Clasificadores y probadores de productos (excluyendo alimentos y bebidas)"}},"funciones":[{"consecutivo":1,"texto":"Inspeccionar y probar productos, piezas y materiales para asegurar que se cumplan las especificaciones y normas."},{"consecutivo":2,"texto":"Analizar e interpretar planos, datos, manuales y otros materiales para determinar las especificaciones y los procedimientos de inspección y prueba cumplimiento con las normas de seguridad."},{"consecutivo":3,"texto":"Notificar los problemas a los supervisores y a otros miembros del personal de producción teniendo en cuenta los lineamientos de la organización."},{"consecutivo":4,"texto":"Registrar los datos obtenidos en las inspecciones y pruebas como: peso, temperatura, grado, contenido de humedad cantidades inspeccionadas o clasificadas."},{"consecutivo":5,"texto":"Marcar los artículos indicando datos como: clase y grado de aceptación o rechazo de acuerdo con lineamientos técnicos."},{"consecutivo":6,"texto":"Analizar, organizar y presentar los resultados de las inspecciones y pruebas de los productos de acuerdo con requerimientos técnicos y normativa."},{"consecutivo":7,"texto":"Descartar o rechazar productos, materiales y equipos que no cumplan las especificaciones pertinentes."},{"consecutivo":8,"texto":"Conducir pruebas para garantizar la calidad o detectar discontinuidades o defectos utilizando equipos de prueba radiográfica, ultrasónica, líquido penetrante, partículas magnéticas, corriente eléctrica y otros métodos de ensayo no destructivo."},{"consecutivo":9,"texto":"Revisar el ensamble final de motores eléctricos, transformadores o equipo de control para garantizar estándares de control de calidad."},{"consecutivo":10,"texto":"Revisar durante y al final del proceso de producción en forma visual o mecánica, los defectos de los artículos o probar la operación del equipo para mantener la calidad de los productos."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"75439.001","nombre":"Auditor de calidad de ensamble de vehículos y motos / Auditora de calidad de ensamble de vehículos y motos"},{"codigo":"75439.002","nombre":"Clasificador de productos / Clasificadora de productos"},{"codigo":"75439.003","nombre":"Clasificador de productos de arcilla / Clasificadora de productos de arcilla"},{"codigo":"75439.004","nombre":"Controlador de calidad / Controladora de calidad"},{"codigo":"75439.005","nombre":"Ensayador de metales / Ensayadora de metales"},{"codigo":"75439.006","nombre":"Inspector de control de calidad de batería eléctrica seca / Inspectora de control de calidad de batería eléctrica seca"},{"codigo":"75439.007","nombre":"Inspector de control de calidad de bombillas eléctricas / Inspectora de control de calidad de bombillas eléctricas"},{"codigo":"75439.008","nombre":"Inspector de control de calidad de tratamiento de metales y minerales / Inspectora de control de calidad de tratamiento de metales y minerales"},{"codigo":"75439.009","nombre":"Inspector de control de calidad de vidrio / Inspectora de control de calidad de vidrio"},{"codigo":"75439.010","nombre":"Inspector de calidad / Inspectora de calidad"},{"codigo":"75439.011","nombre":"Inspector de calidad de materiales y productos metálicos / Inspectora de calidad de materiales y productos metálicos"},{"codigo":"75439.012","nombre":"Inspector de calidad de productos agrícolas (excluyendo alimentos y bebidas) / Inspectora de calidad de productos agrícolas (excluyendo alimentos y bebidas)"},{"codigo":"75439.013","nombre":"Inspector de calidad de productos eléctricos / Inspectora de calidad de productos eléctricos"},{"codigo":"75439.014","nombre":"Inspector de calidad de productos electrónicos / Inspectora de calidad de productos electrónicos"},{"codigo":"75439.015","nombre":"Inspector de calidad de productos mecánicos / Inspectora de calidad de productos mecánicos"},{"codigo":"75439.016","nombre":"Inspector de calidad en productos agropecuarios / Inspectora de calidad en productos agropecuarios"},{"codigo":"75439.017","nombre":"Inspector de control de calidad / Inspectora de control de calidad"},{"codigo":"75439.018","nombre":"Inspector de control de calidad de cigarrillos / Inspectora de control de calidad de cigarrillos"},{"codigo":"75439.019","nomb