  ('rol_cuoc', 'Operadores de instalaciones de procesamiento de minerales y rocas / Operadoras de instalaciones de procesamiento de minerales y rocas', '81120', 'Exploración y extracción de minas, canteras, petróleo y gas', 2, false, '{"codigo":"81120","nombre":"Operadores de instalaciones de procesamiento de minerales y rocas / Operadoras de instalaciones de procesamiento de minerales y rocas","descripcion":"Operan y supervisan máquinas y equipos que hacen parte de un proceso de producción en cadena de minerales, rocas, piedra y metales con el fin de obtener productos refinados para uso inmediato o para nuevos procesamientos ulteriores. Se pueden desempeñar en plantas procesadoras de metal y mineral como refinerías de cobre, plomo y zinc, acerías, plantas de aluminio, refinerías de metales preciosos, plantas procesadoras de cemento, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"81","nombre":"OPERADORES DE INSTALACIONES FIJAS Y MÁQUINAS"},"subgrupo":{"codigo":"811","nombre":"Operadores de instalaciones mineras y de extracción y procesamiento de minerales"},"grupo_primario":{"codigo":"8112","nombre":"Operadores de instalaciones de procesamiento de minerales y rocas"}},"funciones":[{"consecutivo":1,"texto":"Instalar y operar instalaciones y maquinaria que sirven para machacar, triturar, cortar, serrar separar, colar, fundir, tratar, mezclar y refinar u otra forma de procesar rocas y minerales de acuerdo con las especificaciones del trabajo."},{"consecutivo":2,"texto":"Disponer y ajustar la maquinaria utilizada en las operaciones de procesamiento de metales, minerales y cemento."},{"consecutivo":3,"texto":"Efectuar la lectura de los contadores, indicadores, tableros de control, medidores, calibradores o las imágenes del computador y monitores para garantizar el funcionamiento seguro y eficiente de los equipos, detectar posibles problemas de funcionamiento, ayudar al mantenimiento y reparación."},{"consecutivo":4,"texto":"Colocar en las máquinas bloques y losas de piedra para el serrado, corte y otros trabajos."},{"consecutivo":5,"texto":"Supervisar y mantener el flujo de rocas sin procesar, minerales y piedra desde las cintas transportadoras hacia las máquinas."},{"consecutivo":6,"texto":"Operar equipos de lavado, separación, lixiviación, precipitado, filtrado, extracción y combinación para eliminar el material de desecho y recuperar los minerales."},{"consecutivo":7,"texto":"Combinar minerales con disolventes para facilitar su posterior procesamiento."},{"consecutivo":8,"texto":"Separar concentrados de metales y minerales de los depósitos aluviales y de minerales por sedimentación, flotación, gravedad y filtrado o separación magnética y electrostática."},{"consecutivo":9,"texto":"Examinar los materiales procesados visualmente o con las manos para garantizar el cumplimiento de los estándares establecidos y las especificaciones del trabajo y la recolección de muestras para análisis en laboratorios."},{"consecutivo":10,"texto":"Realizar mantenimiento, ajuste y reparación a las instalaciones y maquinaria si es requerido."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"81120.001","nombre":"Apurador lavador de mineral / Apuradora lavadora de mineral"},{"codigo":"81120.002","nombre":"Colador de carbón / Coladora de carbón"},{"codigo":"81120.003","nombre":"Colador de minerales / Coladora de minerales"},{"codigo":"81120.004","nombre":"Cribador de carbón / Cribadora de carbón"},{"codigo":"81120.005","nombre":"Cribador de minerales / Cribadora de minerales"},{"codigo":"81120.006","nombre":"Escogedor de minerales / Escogedora de minerales"},{"codigo":"81120.007","nombre":"Estriador de minerales / Estriadora de minerales"},{"codigo":"81120.008","nombre":"Lavador de carbón / Lavadora de carbón"},{"codigo":"81120.009","nombre":"Lavador de minerales / Lavadora de minerales"},{