  ('rol_cuoc', 'Perforadores de pozos de gas y petróleo / Perforadoras de pozos de gas y petróleo', '81131', 'Exploración y extracción de minas, canteras, petróleo y gas', 2, false, '{"codigo":"81131","nombre":"Perforadores de pozos de gas y petróleo / Perforadoras de pozos de gas y petróleo","descripcion":"Operan, supervisan y controlan equipos de perforación mecánico o electrónico, instrumentos y equipo auxiliar utilizados en la perforación y mantenimiento de pozos. Se pueden desempeñar en compañías de explotación y producción de petróleo y gas, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"81","nombre":"OPERADORES DE INSTALACIONES FIJAS Y MÁQUINAS"},"subgrupo":{"codigo":"811","nombre":"Operadores de instalaciones mineras y de extracción y procesamiento de minerales"},"grupo_primario":{"codigo":"8113","nombre":"Perforadores y sondistas de pozos y afines"}},"funciones":[{"consecutivo":1,"texto":"Instalar y operar equipos de perforación, menores y auxiliares; coordinar al personal en el montaje de acuerdo con procedimiento técnico y condiciones operacionales."},{"consecutivo":2,"texto":"Operar controles de equipos de perforación, regular su presión, aparatos de elevación y equipo de acuerdo con procedimiento técnico y condiciones operacionales."},{"consecutivo":3,"texto":"Operar y mantener equipos de sondeo de acuerdo con procedimiento técnico."},{"consecutivo":4,"texto":"Supervisar y entrenar al personal de perforación de acuerdo con metodología y normativas técnica."},{"consecutivo":5,"texto":"Realizar mantenimiento o reparaciones menores a equipos y llevar registros de las operaciones de perforación."},{"consecutivo":6,"texto":"Ensamblar y operar equipos o elementos del taladro o cables para conducir las pruebas y ensayos requeridos de acuerdo con especificaciones técnicas."},{"consecutivo":7,"texto":"Preparar, mantener, tomar y analizar fluidos de perforación y comprobar el funcionamiento de las bombas para asegurar la circulación adecuada de los líquidos hacia el tubo de perforación y el pozo."},{"consecutivo":8,"texto":"Efectuar la lectura de los indicadores y demás instrumentos de medición y escuchar el sonido de los equipos para detectar averías, fallas de funcionamiento y condiciones inhabituales en los pozos y determinar si es necesario calibrar, modificar o sustituir los equipos de perforación."},{"consecutivo":9,"texto":"Operar y supervisar contadores o computadores en pruebas móviles aleatorias o unidades de registro para recolectar datos."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"81131.001","nombre":"Administrador de taladro industria petrolera / Administradora de taladro industria petrolera"},{"codigo":"81131.002","nombre":"Conductor de tren de sondeo por rotación de pozos de petróleo / Conductora de tren de sondeo por rotación de pozos de petróleo"},{"codigo":"81131.003","nombre":"Excavador de agujeros / Excavadora de agujeros"},{"codigo":"81131.006","nombre":"Manilero de perforación de petróleo y gas / Manilera de perforación de petróleo y gas"},{"codigo":"81131.007","nombre":"Operador de equipo de perforación / Operadora de equipo de perforación"},{"codigo":"81131.008","nombre":"Operador de perforadora de percusión de pozos de petróleo y gas / Operadora de perforadora de percusión de pozos de petróleo y gas"},{"codigo":"81131.009","nombre":"Operador de planta de perforación / Operadora de planta de perforación"},{"codigo":"81131.010","nombre":"Operador de prueba de pozo de perforación de petróleo y gas / Operadora de prueba de pozo de perforación de petróleo y gas"},{"codigo":"81131.011","nombre":"Operador de tren de sondeo de pozos de petróleo y gas / Operadora de tren de sondeo de pozos de petróleo y gas"},{"codigo":"81131.012","nombre":"Operador de perforadora de pozos de petróleo y gas / Operadora de perforadora de pozos de petróleo y gas"},{"codigo":"81131.013","nombre":"Perforador de pozos de gas / Perforadora de pozos de gas"},{"codigo":"81131.014","nombre":"Perforador de pozos de petróleo / Perforadora de pozos de petróleo"},{"codigo":"81131.015","nombre":"Perforador experto en perforación de desarrollo / Perforadora experta en perforación de desarrollo"},{"codigo":"81131.016","nombre":"Perforador experto en perforación de direccional / Perforadora experta en perforación de direccional"},{"codigo":"81131.018","nombre":"Perforador sondistas de pozos de gas y petróleo / Perforadora sondista de pozos de gas y petróleo"},{"codigo":"81131.019","nombre":"Sondista de perforación de pozos"},{"codigo":"81131.021","nombre":"Sondista de pozos de petróleo y gas"},{"codigo":"81131.022","nombre":"Taladrero de perforación de petróleo y gas / Taladrera de perforación de petróleo y gas"}],"conocimientos":[{"id":"38","nombre":"Mantenimiento"},{"id":"13","nombre":"Mecánica y metalistería"},{"id":"79","nombre":"Minería y extracción"},{"id":"85","nombre":"Seguridad y salud en el trabajo"},{"id":"92","nombre":"Tecnologías de protección y gestión del medio ambiente"}],"destrezas":[{"id":"36","nombre":"Ensamble"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"24","nombre":"Mantenimiento de equipos"},{"id":"26","nombre":"Reparación"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"81111","nombre":"Mineros y canteros / Mineras y canteras"},{"codigo":"81132","nombre":"Perforadores de pozos de agua / Perforadoras de pozos de agua"},{"codigo":"81133","nombre":"Operadores de servicios en perforación de petróleo y gas / Operadoras de servicios en perforación de petróleo y gas"}],"area_principal":{"sigla":"EMCP","nombre":"Exploración y extracción de minas, canteras, petróleo y gas"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"8113*","ciuo08_obs":"Denominaciones parciales","cno