  ('rol_cuoc', 'Perforadores de pozos de agua / Perforadoras de pozos de agua', '81132', 'Exploración y extracción de minas, canteras, petróleo y gas', 2, false, '{"codigo":"81132","nombre":"Perforadores de pozos de agua / Perforadoras de pozos de agua","descripcion":"Operan, supervisan y controlan equipos para la perforación de pozos de agua para fines diversos, realizan servicios de calibración o reparación a instrumentos y equipos. Se pueden desempeñar en empresas de perforación, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"81","nombre":"OPERADORES DE INSTALACIONES FIJAS Y MÁQUINAS"},"subgrupo":{"codigo":"811","nombre":"Operadores de instalaciones mineras y de extracción y procesamiento de minerales"},"grupo_primario":{"codigo":"8113","nombre":"Perforadores y sondistas de pozos y afines"}},"funciones":[{"consecutivo":1,"texto":"Operar y supervisar equipos para excavar, sondear y perforar pozos de agua, así como instalar protectores, revestimientos, tuberías, cubiertas y otros accesorios, cumpliendo con los procedimientos técnicos y las condiciones operativas."},{"consecutivo":2,"texto":"Realizar mantenimiento mecánico de rutina o reparaciones menores a equipos y llevar registros de las operaciones de perforación."},{"consecutivo":3,"texto":"Instalar, probar, mantener y reparar bombas, cubiertas, tuberías, cabezales de perforación y equipo, realizar pruebas de bombeo para evaluar el desempeño del pozo o sustituir los equipos que no funcionan adecuadamente."},{"consecutivo":4,"texto":"Proveer servicios de calibración o reparación a instrumentos y equipos para solucionar fallas de funcionamiento o desmonte de estructuras de pozos de agua existentes."},{"consecutivo":5,"texto":"Analizar y evaluar las localizaciones de los pozos de agua de acuerdo con los requerimientos de los clientes."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"81132.001","nombre":"Constructor de aljibes / Constructora de aljibes"},{"codigo":"81132.002","nombre":"Constructor de pozos de agua / Constructora de pozos de agua"},{"codigo":"81132.003","nombre":"Operador de perforadora de percusión de pozos de agua / Operadora de perforadora de percusión de pozos de agua"},{"codigo":"81132.004","nombre":"Operador de perforadora de pozos de agua potable / Operadora de perforadora de pozos de agua potable"},{"codigo":"81132.005","nombre":"Perforador de pozos de agua / Perforadora de pozos de agua"},{"codigo":"81132.006","nombre":"Sondista de pozos de agua"}],"conocimientos":[{"id":"38","nombre":"Mantenimiento"},{"id":"13","nombre":"Mecánica y metalistería"},{"id":"79","nombre":"Minería y extracción"}],"destrezas":[{"id":"36","nombre":"Ensamble"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"24","nombre":"Mantenimiento de equipos"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"26","nombre":"Reparación"}],"ocupaciones_afines":[{"codigo":"81111","nombre":"Mineros y canteros / Mineras y canteras"},{"codigo":"81113","nombre":"Operadores de equipo pesado de minería / Operadoras de equipo pesado de minería"},{"codigo":"81131","nombre":"Perforadores de pozos de gas y petróleo / Perforadoras de pozos de gas y petróleo"}],"area_principal":{"sigla":"EMCP","nombre":"Exploración y extracción de minas, canteras, petróleo y gas"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"8113*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"8443","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Operadores de servicios en perforación de petróleo y gas / Operadoras de servicios en perforación de petróleo y gas', '81133', 'Exploración y extracción de minas, canteras, petróleo y gas', 2, false, '{"codigo":"81133","nombre":"Operadores de servicios en perforación de petróleo y gas / Operadoras de servicios en perforación de petróleo y gas","descripcion":"Operan, supervisan y controlan máquinas y equipos de servicio a pozos; operan sistemas de bombeo especializado para aplicar cemento en los pozos o tratarlos con químicos, mezclas de arena y gases para la perforación. Se pueden desempeñar en compañías petroleras, explotadoras de gas y petróleo, empresas especializadas en perforación de pozos, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"81","nombre":"OPERADORES DE INSTALACIONES FIJAS Y MÁQUINAS"},"subgrupo":{"codigo":"811","nombre":"Operadores de instalaciones mineras y de extracción y procesamiento de minerales"},"grupo_primario":{"codigo":"8113","nombre":"Perforadores y sondistas de pozos y afines"}},"funciones":[{"consecutivo":1,"texto":"Ensamblar, ajustar y desmontar secciones de tubería, cubiertas desde las plataformas y sustituir los equipos que no funcionan adecuadamente."},{"consecutivo":2,"texto":"Operar, supervisar y mantener sistemas de bombeo hidráulico y de lodo para inyectar químicos, gases, arena, cemento, aditivos y otros materiales dentro del pozo de acuerdo con manual técnico."},{"consecutivo":3,"texto":"Apoyar en la instalación, desmonte y transporte de equipos de perforación y apoyo de acuerdo con manual de operación."},{"consecutivo":4,"texto":"Efectuar la lectura de los indicadores y demás instrumentos de medición y escuchar el sonido de los equipos para detectar averías, fallas de funcionamiento y condiciones inhabituales en el bombeo y determinar si necesario ajustar o sustituir los equipos."},{"consecutivo":5,"texto":"Calibrar válvulas y elementos de presión, realizar ajustes si es necesario de acuerdo con manual técnico."},{"consecutivo":6,"texto":"Realizar mantenimiento o reparaciones a motobombas, bombas de subsuelo u otros equipos y llevar registros de las operaciones de perforación."},{"consecutivo":7,"texto":"Operar y supervisar los equipos de wireline y de inyección de acuerdo con manual técnico."},{"consecutivo":8,"texto":"Limpiar y mantener en buen estado los pozos de petróleo y gas, reemplazar los vástagos de bombeo, el entubado y las tuberías de acuerdo con procedimiento técnico."},{"consecutivo":9,"texto":"Operar y supervisar máquinas y equipos para extraer de los pozos el polvo, los recortes y el material de los equipos de perforación que se haya desprendido o roto de acuerdo con procedimiento técnico."},{"consecutivo":10,"texto":"Cerrar y sellar los pozos que ya no estén en servicio de acuerdo con procedimiento técnico."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"81133.001","nombre":"Cadenero en la industria petrolera / Cadenera en la industria petrolera"},{"codigo":"81133.002","nombre":"Chequeapozo"},{"codigo":"81133.003","nombre":"Operador de apoyo y servicios en perforación de petróleo y gas / Operadora de apoyo y servicios en perforación de petróleo y gas"},{"codigo":"81133.004","nombre":"Operador de bombas industria petrolera / Operadora de bombas industria petrolera"},{"codigo":"81133.005","nombre":"Operador de bombeo electrosumergible industria petrolera / Operadora de bombeo electrosumergible industria petrolera"},{"codigo":"81133.006","nombre":"Operador de campo down hole industria petrolera / Operadora de campo down hole industria petrolera"},{"codigo":"81133.007","nombre":"Operador de llave de potencia / Operadora de llave de potencia"},{"codigo":"81133.008","nombre":"Operador de llaves hidráulicas servicios a pozo de petróleo / Operadora de llaves hidráulicas servicios a pozo de petról