  ('rol_cuoc', 'Operadores de producción de hidrocarburos / Operadoras de producción de hidrocarburos', '81134', 'Exploración y extracción de minas, canteras, petróleo y gas', 2, false, '{"codigo":"81134","nombre":"Operadores de producción de hidrocarburos / Operadoras de producción de hidrocarburos","descripcion":"Operan, supervisan y controlan equipos en la operación de los procesos de producción de hidrocarburos, well testing y mantenimiento de las instalaciones, la maquinaria y los equipos cumpliendo con los estándares técnicos. Se pueden desempeñar en plantas de producción de hidrocarburos, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"81","nombre":"OPERADORES DE INSTALACIONES FIJAS Y MÁQUINAS"},"subgrupo":{"codigo":"811","nombre":"Operadores de instalaciones mineras y de extracción y procesamiento de minerales"},"grupo_primario":{"codigo":"8113","nombre":"Perforadores y sondistas de pozos y afines"}},"funciones":[{"consecutivo":1,"texto":"Operar, supervisar y monitorear maquinarias y equipos para los procesos de la producción de hidrocarburos como recibo, separación, compresión, tratamiento, almacenamiento y transferencia de acuerdo procedimiento técnico."},{"consecutivo":2,"texto":"Efectuar lectura de los indicadores y demás instrumentos de medición de los procesos de separación de fluidos, tratamiento, almacenamiento y transporte de los productos y determinar si necesario ajustar o sustituir los equipos."},{"consecutivo":3,"texto":"Realizar informes de producción dentro de los tiempos estipulados y presentar los datos al supervisor."},{"consecutivo":4,"texto":"Supervisar el funcionamiento maquinaria, equipos y herramientas con el fin de prevenir paradas, accidentes o cualquier tipo de anormalidad en los procesos productivos o de prueba."},{"consecutivo":5,"texto":"Ejecutar la operación y el control de los procesos de recibo, medición, almacenamiento, despacho y transferencia de fluidos de producción y prueba de pozos de acuerdo normativa y procedimientos establecidos."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"81134.001","nombre":"Operador de máquina de extracción de pozos de petróleo y gas / Operadora de máquina de extracción de pozos de petróleo y gas"},{"codigo":"81134.002","nombre":"Operador de planta de proceso de hidrocarburos / Operadora de planta de proceso de hidrocarburos"},{"codigo":"81134.003","nombre":"Operador de producción de hidrocarburos / Operadora de producción de hidrocarburos"},{"codigo":"81134.004","nombre":"Operador de producción de petróleo y gas / Operadora de producción de petróleo y gas"},{"codigo":"81134.005","nombre":"Operador de well testing en facilidades de producción básico / Operadora de well testing en facilidades de producción (nivel básico)"}],"conocimientos":[{"id":"13","nombre":"Mecánica y metalistería"},{"id":"79","nombre":"Minería y extracción"},{"id":"85","nombre":"Seguridad y salud en el trabajo"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"24","nombre":"Mantenimiento de equipos"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"16","nombre":"Resolución de problemas complejos"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"81112","nombre":"Operadores de servicios e instalaciones mineras / Operadoras de servicios e instalaciones mineras"},{"codigo":"81132","nombre":"Perforadores de pozos de agua / Perforadoras de pozos de agua"},{"codigo":"81133","nombre":"Operadores de servicios en perforación de petróleo y gas / Operadoras de servicios en perforación de petróleo y gas"}],"area_principal":{"sigla":"EMCP","nombre":"Exploración y extracción de minas, canteras, petróleo y gas"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"8113*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"7314*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"7317","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Operadores de servicios a pozos de hidrocarburos / Operadoras de servicios a pozos de hidrocarburos', '81135', 'Exploración y extracción de minas, canteras, petróleo y gas', 2, false, '{"codigo":"81135","nombre":"Operadores de servicios a pozos de hidrocarburos / Operadoras de servicios a pozos de hidrocarburos","descripcion":"Operan, supervisan y controlan equipos de servicios a pozos de hidrocarburos como transporte de producto, well testing, haciendo recorrido a pozos, observando condiciones de superficie y mantenimiento de los equipos, realizan el manejo y operaciones a los sistemas de levantamiento artificial y de reacondicionamiento de pozos. Se pueden desempeñar en plantas de producción de hidrocarburos y perforación de pozos, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"81","nombre":"OPERADORES DE INSTALACIONES FIJAS Y MÁQUINAS"},"subgrupo":{"codigo":"811","nombre":"Operadores de instalaciones mineras y de extracción y procesamiento de minerales"},"grupo_primario":{"codigo":"8113","nombre":"Perforadores y sondistas de pozos y afines"}},"funciones":[{"consecutivo":1,"texto":"Operar, supervisar y monitorear equipos para los procesos de recibo, separación, compresión, transferencia de fluidos, tratamiento, almacenamiento y transporte de los productos de acuerdo con lo establecido en la planilla de toma de datos operacionales."},{"consecutivo":2,"texto":"Instalar y operar equipos de subsuelo en sistemas de bombeo por cavidades progresivas (PCP), bombeo electrosumergible (BES), bombeo neumático (Gas Lift -GL), de acuerdo con manual técnico."},{"consecutivo":3,"texto":"Realizar mantenimiento de equipo y alistar unidad de servicio, conexión de batería, manipulación de herramienta, entre otros de acuerdo requerimientos técnicos."},{"consecutivo":4,"texto":"Realizar acciones para asegurar una óptima operación, libre de riesgos para las personas; la integridad de los equipos y el cuidado del medio ambiente."},{"consecutivo":5,"texto":"Realizar informes de la operación e informar al supervisor cualquier variación que se detecte durante el proceso."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"81135.001","nombre":"Operador de cañolero / Operadora de cañolero"},{"codigo":"81135.002","nombre":"Operador de coiled tubing / Operadora de coiled tubing"},{"codigo":"81135.003","nombre":"Operador de equipo wireline para servicios de pozo de petróleo / Operadora de equipo wireline para servicios de pozo de petróleo"},{"codigo":"81135.004","nombre":"Operador de facilidades de producción de servicio a pozos de hidrocarburos / Operadora de facilidades de producción de servicio a pozos de hidrocarburos"},{"codigo":"81135.005","nombre":"Operador de mezcla de servicio a pozos de hidrocarburos / Operadora de mezcla de servicio a pozos de hidrocarburos"},{"codigo":"81135.006","nombre":"Operador de planta de servicio a pozos de hidrocarburos / Operadora de planta de servicio a pozos de hidrocarburos"},{"codigo":"81135.007","nombre":"Operador de producción de servicio a pozos de hidrocarburos / Operadora de producción de servicio a pozos de hidrocarburos"},{"codigo":"81135.008","nombre":"Operador de slick line / Operadora de slick line"},{"codigo":"81135.009","nombre":"Operador de DST (prueba de columna de perforación) / Operadora de DST (prueba de columna de perforación)"},{"codigo":"81135.010","nombre":"Operador de servicios a pozos de hidrocarburos / Operadora de servicios a pozos de hidrocarburos"}],"conocimientos":[{"id":"13","nombre":"Mecánica y metalistería"},{"id":"79","nombre":"Minería y extracción"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"24","nombre":"Mantenimiento de equipos"},{"id":"26","nombre":"Reparación"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"81131","nombre":"Perforadores de pozos de gas y petróleo / Perforadoras de pozos de gas y petróleo"},{"codigo":"81134","nombre":"Operadores de producción de hidrocarburos / Operadoras de producción de hidrocarburos"}],"area_principal":{"sigla":"EMCP","nombre":"Exploración y extracción de minas, canteras, petróleo y gas"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"8113*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"7318*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Operadores de torres de perforación de pozos hidrocarburos / Operadoras de torres de perforación de pozos hidrocarburos', '81136', 'Exploración y extracción de minas, canteras, petróleo y gas', 2, false, '{"codigo":"81136","nombre":"Operadores de torres de perforación de pozos hidrocarburos / Operadoras de torres de perforación de pozos hidrocarburos","descripcion":"Operan, supervisan y controlan equipos en torres de perforación de pozos hidrocarburos de acuerdo con los parámetros dispuestos por los responsables de la operación, identificando los sistemas que conforman el equipo de perforación, manipulando y operando la tubería y las herramientas, apoyando en el arme y desarme de la torre de perforación. Se pueden desempeñar plantas de producción de hidrocarburos y perforación de pozos, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"81","nombre":"OPERADORES DE INSTALACIONES FIJAS Y MÁQUINAS"},"subgrupo":{"codigo":"811","nombre":"Operadores de instalaciones mineras y de extracción y procesamiento de minerales"},"grupo_primario":{"codigo":"8113","nombre":"Perforadores y sondistas de pozos y afines"}},"funciones":[{"consecutivo":1,"texto":"Operar y supervisar equipos elevadores, seguro de cuñas, llaves de potencia y neumáticas de acuerdo con manual técnico."},{"consecutivo":2,"texto":"Operar equipos neumáticos e hidráulicos en la operación del top drive de acuerdo con procedimientos técnicos."},{"consecutivo":3,"texto":"Utilizar instrumentos para determinar las propiedades del peso, ph, filtrado y viscosidad."},{"consecutivo":4,"texto":"Realizar conexiones a la sarta de perforación de acuerdo con procedimientos técnicos."},{"consecutivo":5,"texto":"Llevar y mantener registros de las operaciones de perforación, mantenimiento y reparación de equipos e instalación."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"81136.001","nombre":"Cuñero / Cuñera (perforación o workover)"},{"codigo":"81136.002","nombre":"Cuñero de servicios a pozos de petróleo / Cuñera de servicios a pozos de petróleo"},{"codigo":"81136.003","nombre":"Encuellador de servicios de pozos de petróleo / Encuelladora de servicios de pozos de petróleo"},{"codigo":"81136.004","nombre":"Encuellador de perforación / Encuelladora de perforación"},{"codigo":"81136.005","nombre":"Encuellador workover / Encuelladora workover"},{"codigo":"81136.006","nombre":"Operador de torre de perforación de hidrocarburos / Operadora de torre de perforación de hidrocarburos"},{"codigo":"81136.007","nombre":"Operador de torre de perforación de petróleo y gas / Operadora de torre de perforación de petróleo y gas"},{"codigo":"81136.008","nombre":"Torrero / Torrera"}],"conocimientos":[{"id":"13","nombre":"Mecánica y metalistería"},{"id":"79","nombre":"Minería y extracción"},{"id":"85","nombre":"Seguridad y salud en el trabajo"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"24","nombre":"Mantenimiento de equipos"}],"ocupaciones_afines":[{"codigo":"81131","nombre":"Perforadores de pozos de gas y petróleo / Perforadoras de pozos de gas y petróleo"},{"codigo":"81132","nombre":"Perforadores de pozos de agua / Perforadoras de pozos de agua"},{"codigo":"81133","nombre":"Operadores de servicios en perforación de petróleo y gas / Operadoras de servicios en perforación de petróleo y gas"},{"codigo":"81134","nombre":"Operadores de producción de hidrocarburos / Operadoras de producción de hidrocarburos"},{"codigo":"81135","nombre":"Operadores de servicios a pozos de hidrocarburos / Operadoras de servicios a pozos de hidrocarburos"}],"area_principal":{"sigla":"EMCP","nombre":"Exploración y extracción de minas, canteras, petróleo y gas"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"8113*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"7312*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"9311*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"7314*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"7319","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Operadores de máquinas para fabricar cemento y otros productos minerales / Operadoras de máquinas para fabricar cemento y otros productos minerales', '81140', 'Fabricación, transformación de materiales, instalación, mantenimiento y reparación', 2, false, '{"codigo":"81140","nombre":"Operadores de máquinas para fabricar cemento y otros productos minerales / Operadoras de máquinas para fabricar cemento y otros productos minerales","descripcion":"Operan y supervisan máquinas para la fabricación de productos y acabado de hormigón prefabricado, betún y productos de piedra, y fabrican piedra artificial destinada a la construcción. Se pueden desempeñar en empresas fabricantes de productos de piedra, concreto, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"81","nombre":"OPERADORES DE INSTALACIONES FIJAS Y MÁQUINAS"},"subgrupo":{"codigo":"811","nombre":"Operadores de instalaciones mineras y de extracción y procesamiento de minerales"},"grupo_primario":{"codigo":"8114","nombre":"Operadores de máquinas para fabricar cemento y otros productos minerales"}},"funciones":[{"consecutivo":1,"texto":"Operar máquinas de extrudir, moldear, mezclar, bombear, compactar, triturar, pulir y cortar utilizadas en la fabricación y el acabado de productos prefabricados de hormigón o piedra de acuerdo con especificaciones."},{"consecutivo":2,"texto":"Operar y ajustar instalaciones y máquinas para pesar, triturar, cortar y mezclar arena, grava, cemento, agua y otros ingredientes sobre especificaciones de fabricación productos de hormigón."},{"consecutivo":3,"texto":"Operar instalaciones de producción de cemento, cal y clínker, incluida la carga y descarga de ingredientes y el manejo de equipos de alimentación continua, como bombas y cintas transportadoras."},{"consecutivo":4,"texto":"Operar y supervisar máquinas para cortar, triturar, perforar, chorrear con arena y pulir productos de hormigón y bloques, losas y otros productos de piedra, de acuerdo con las especificaciones recibidas para el trabajo."},{"consecutivo":5,"texto":"Comprobar los planos de producción y las especificaciones para determinar y seleccionar los materiales, ingredientes, procedimientos, componentes y ajustes para las máquinas de extrusión, moldeo, mezclado y compactación."},{"consecutivo":6,"texto":"Preparar y operar instalaciones y máquinas que montan y llenan moldes con mezclas de hormigón, piedra artificial; Retiran los vaciados de los moldes y dan el acabado a las superficies de los productos prefabricados."},{"consecutivo":7,"texto":"Supervisar el funcionamiento de los equipos y máquinas, leyendo instrumentos tales como los indicadores de temperatura y de presión; ajustar los mandos y notificar las averías y problemas de funcionamiento conforme sea necesario."},{"consecutivo":8,"texto":"Recoger y examinar muestras de mezclas y de productos acabados a fin de comprobar que se cumplen las especificaciones y efectuar en las máquinas los ajustes correspondientes."},{"consecutivo":9,"texto":"Fabricar y reparar formaletas, moldes de arcilla, madera y otros materiales para usar en el vaciado de productos de hormigón."},{"consecutivo":10,"texto":"Colocar varillas reforzadas o malla metálica en los moldes y llenar, asentar el concreto o apisonarlo usando vertedores en suspensión y/o vibradores eléctricos pisones."},{"consecutivo":11,"texto":"Organizar el mantenimiento, ajuste y reparación de las máquinas y equipos cuando sea necesario."},{"consecutivo":12,"texto":"Comprobar y registrar información de producción, en los que se indiquen las cantidades, llos tamaños y los tipos de materiales y bienes producidos."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"81140.001","nombre":"Extrusor de productos de concreto, arcilla y piedra / Extrusora de productos de concreto, arcilla y piedra"},{"codigo":"81140.002","no