  ('rol_cuoc', 'Operadores de máquinas de planta química / Operadoras de máquinas de planta química', '81311', 'Industria química', 2, false, '{"codigo":"81311","nombre":"Operadores de máquinas de planta química / Operadoras de máquinas de planta química","descripcion":"Operan y controlan maquinas, aparatos y unidades para combinar, mezclar, procesar y empacar un amplio rango de químicos especiales, productos farmacéuticos, de aseo y de tocador; Ajustan las unidades y equipo de procesamiento en estas plantas. Se pueden desempeñar en compañías procesadoras de petróleo, gas natural, oleoductos, petroquímicas, químicas, farmacéuticas, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"81","nombre":"OPERADORES DE INSTALACIONES FIJAS Y MÁQUINAS"},"subgrupo":{"codigo":"813","nombre":"Operadores de instalaciones y máquinas de productos químicos y fotográficos"},"grupo_primario":{"codigo":"8131","nombre":"Operadores de plantas y máquinas de productos químicos"}},"funciones":[{"consecutivo":1,"texto":"Instalar, operar, controlar, ajustar y detener posibles fallas en equipo, máquinas e instalaciones."},{"consecutivo":2,"texto":"Monitorear medidores y calibradores e instrumentación electrónica en una o más aparatos químicos o unidades de formulación química como mezcladoras, combinadoras, calentadoras, amasadoras, secadoras, prensadoras, tableteadoras, encapsuladoras, granuladoras y máquinas de revestimiento."},{"consecutivo":3,"texto":"Medir, pesar, cargar y agregar ingredientes químicos de acuerdo con la fórmula."},{"consecutivo":4,"texto":"Tomar muestras, realizar pruebas químicas y físicas de rutina a los productos y registrar datos de la producción."},{"consecutivo":5,"texto":"Calibrar y limpiar máquinas, equipo de procesamiento e instalaciones y realizar reparaciones menores en las mismas."},{"consecutivo":6,"texto":"Operar y ajustar maquinas como horno y digestores e instalaciones para transformar materia prima en productos según su requerimiento."},{"consecutivo":7,"texto":"Supervisar procesos de reacción y transferencias de productos, de conformidad con los procedimientos de seguridad establecidos."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"81311.001","nombre":"Blanqueador de productos químicos / Blanqueadora de productos químicos"},{"codigo":"81311.003","nombre":"Destilador de glicerina / Destiladora de glicerina"},{"codigo":"81311.004","nombre":"Destilador de perfumes y esencias / Destiladora de perfumes y esencias"},{"codigo":"81311.005","nombre":"Destilador en procesamiento químico / Destiladora en procesamiento químico"},{"codigo":"81311.006","nombre":"Ensamblador de juegos pirotécnicos artificiales / Ensambladora de juegos pirotécnicos artificiales"},{"codigo":"81311.007","nombre":"Fabricante de juegos pirotécnicos artificiales"},{"codigo":"81311.008","nombre":"Fabricante de municiones"},{"codigo":"81311.009","nombre":"Mezclador en procesamiento químico / Mezcladora en procesamiento químico"},{"codigo":"81311.010","nombre":"Operador de centrifugadora en procesamiento químico / Operadora de centrifugadora en procesamiento químico"},{"codigo":"81311.011","nombre":"Operador de alambique de perfumería / Operadora de alambique de perfumería"},{"codigo":"81311.012","nombre":"Operador de alambique para procesos químicos / Operadora de alambique para procesos químicos"},{"codigo":"81311.013","nombre":"Operador de alambique para trementina / Operadora de alambique para trementina"},{"codigo":"81311.014","nombre":"Operador de autoclave procesamiento químico / Operadora de autoclave procesamiento químico"},{"codigo":"81311.015","nombre":"Operador de calcinadora de tratamientos químicos / Operadora de calcinadora de tratamientos químicos"},{"codigo":"81311.016","nombre":"Operador de caldera de tratamientos químicos / Operadora de caldera de tratamientos químicos"},{"c