  ('rol_cuoc', 'Operadores de planta de gas / Operadoras de planta de gas', '81312', 'Industria química', 2, false, '{"codigo":"81312","nombre":"Operadores de planta de gas / Operadoras de planta de gas","descripcion":"Operan, controlan, monitorean y ajustan aparatos, unidades, sistemas, equipos y accesorios en plantas de gas; operan sistemas de compresión y descompresión de gas, realizan labores de sistemas de trasiego, envasan gas en contenedores y almacenan gas aplicando las normas de seguridad. Controlan arranque y cierre de proceso. Se pueden desempeñar en empresas de distribución de gas, plantas de almacenamiento, envasado de gas, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"81","nombre":"OPERADORES DE INSTALACIONES FIJAS Y MÁQUINAS"},"subgrupo":{"codigo":"813","nombre":"Operadores de instalaciones y máquinas de productos químicos y fotográficos"},"grupo_primario":{"codigo":"8131","nombre":"Operadores de plantas y máquinas de productos químicos"}},"funciones":[{"consecutivo":1,"texto":"Operar y ajustar sistemas de reparto de gas licuado del petróleo y sistemas de distribución de gas."},{"consecutivo":2,"texto":"Envasar gas y realizar labores de trasiego entre contenedores y sistemas, según protocolos."},{"consecutivo":3,"texto":"Operar y ajustar sistemas e instalaciones de compresión de gas."},{"consecutivo":4,"texto":"Operar panel de control computarizado o electrónico desde una sala de control central para monitorear y optimizar los procesos físicos y químicos de varias unidades de procesamiento de gas."},{"consecutivo":5,"texto":"Controlar y ajustar las variables y condiciones de operación y seguridad de redes y sistemas de distribución de gas, llevar registro información de condiciones del sistema de distribución."},{"consecutivo":6,"texto":"Supervisar procesos de reacción y transferencias de productos, de conformidad con los procedimientos de seguridad establecidos."},{"consecutivo":7,"texto":"Solicitar y generar requerimiento del mantenimiento de rutina y reparaciones menores a la red de gas y líneas de distribución."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"81312.001","nombre":"Operador de autotanques de gas / Operadora de autotanques de gas"},{"codigo":"81312.002","nombre":"Operador de centros de control de gas / Operadora de centros de control de gas"},{"codigo":"81312.003","nombre":"Operador de compresión y descompresión de gas / Operadora de compresión y descompresión de gas"},{"codigo":"81312.004","nombre":"Operador de envasado de gas / Operadora de envasado de gas"},{"codigo":"81312.005","nombre":"Operador de estación de gas / Operadora de estación de gas"},{"codigo":"81312.006","nombre":"Operador de llenado de gas / Operadora de llenado de gas"},{"codigo":"81312.007","nombre":"Operador de llenado de gases medicinales e industriales / Operadora de llenado de gases medicinales e industriales"},{"codigo":"81312.008","nombre":"Operador de máquina de licuefacción de gases / Operadora de máquina de licuefacción de gases"},{"codigo":"81312.009","nombre":"Operador de máquina de producción de gas cloro / Operadora de máquina de producción de gas cloro"},{"codigo":"81312.010","nombre":"Operador de máquina de producción de gas de hulla / Operadora de máquina de producción de gas de hulla"},{"codigo":"81312.011","nombre":"Operador de máquina de producción de gas halógeno / Operadora de máquina de producción de gas halógeno"},{"codigo":"81312.012","nombre":"Operador de máquina de producción de hidrógeno / Operadora de máquina de producción de hidrógeno"},{"codigo":"81312.013","nombre":"Operador de máquina llenadora de cilindros de gas / Operadora de máquina llenadora de cilindros de gas"},{"codigo":"81312.014","nombre":"Operador de planta de gas (excepto refinación y tratamiento) / Operadora de planta de gas (excepto refinación y tratamiento)"},{"codigo":"81312.015","nombre":"Operador de retorta de producción de gas de hulla / Operadora de retorta de producción de gas de hulla"},{"codigo":"81312.016","nombre":"Operador de sistemas de gas / Operadora de sistemas de gas"},{"codigo":"81312.017","nombre":"Operador de sistemas de llenado de gas / Operadora de sistemas de llenado de gas"},{"codigo":"81312.018","nombre":"Operador de trasiego de gas / Operadora de trasiego de gas"}],"conocimientos":[{"id":"35","nombre":"Interpretación de planos"},{"id":"38","nombre":"Mantenimiento"},{"id":"14","nombre":"Matemáticas"},{"id":"13","nombre":"Mecánica y metalistería"},{"id":"16","nombre":"Química"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"40","nombre":"Interpretación"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"38","nombre":"Seguir instrucciones"}],"ocupaciones_afines":[{"codigo":"31341","nombre":"Operadores de instalaciones de refinación de petróleo y gas natural / Operadoras de instalaciones de refinación de petróleo y gas natural"},{"codigo":"81311","nombre":"Operadores de máquinas de planta química / Operadoras de máquinas de planta química"}],"area_principal":{"sigla":"INQU","nombre":"Industria química"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"8131*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"8433","cno_obs":"Denominaciones completas"},{"ciuo08_codigo":"8189*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"9232*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"9321*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Operadores de máquinas y procesadores fotográficos y de películas / Operadoras de máquinas y procesadores fotográficos y de películas', '81320', 'Literatura y artes gráficas', 2, false, '{"codigo":"81320","nombre":"Operadores de máquinas y procesadores fotográficos y de películas / Operadoras de máquinas y procesadores fotográficos y de películas","descripcion":"Operan y supervisan equipos para fabricar, procesar y retocar películas fotográficas y cinematográficas, revelan las películas expuestas e imprimen copias según técnicas o especificaciones requeridas. Se pueden desempeñar en laboratorios de procesamiento de películas, establecimientos de revelado fotográfico, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"81","nombre":"OPERADORES DE INSTALACIONES FIJAS Y MÁQUINAS"},"subgrupo":{"codigo":"813","nombre":"Operadores de instalaciones y máquinas de productos químicos y fotográficos"},"grupo_primario":{"codigo":"8132","nombre":"Operadores de máquinas y procesadores fotográficos y de películas"}},"funciones":[{"consecutivo":1,"texto":"Operar y supervisar equipos utilizados para fabricar película y papel fotográficos."},{"consecutivo":2,"texto":"Operar y ajustar la configuración y el funcionamiento de equipos de revelado automático de películas a color o en blanco y negro, para obtener negativos o diapositivas e imprimir fotografías en blanco y negro."},{"consecutivo":3,"texto":"Operar y supervisar equipo fotográfico para producir, ampliar o retocar los defectos a partir de negativos o impresiones originales."},{"consecutivo":4,"texto":"Operar y ajustar equipo para revelar películas cinematográficas para seguir las distintas etapas de revelado, procesamiento en cuartos y cámaras oscuras."},{"consecutivo":5,"texto":"Operar equipos para transferir películas a cintas de vídeo u otros medios electrónicos."},{"consecutivo":6,"texto":"Inspeccionar imágenes, rollos fotográficos, películas, copias y sus especificaciones; detectar defectos y ajustar los parámetros de las máquinas impresoras para obtener el color, el brillo, el contraste, el número, el tamaño y el tipo de copias deseados."},{"consecutivo":7,"texto":"Operar y ajustar equipo automático de procesamiento fotográfico para revelar negativos en color y hacer copias y diapositivas en establecimientos de venta al por menor."},{"consecutivo":8,"texto":"Operar, supervisar y verificar equipos de procesamiento e impresión fotográfica y aplicar los procedimientos de trabajo."},{"consecutivo":9,"texto":"Medir y mezclar los químicos requeridos para el procesamiento fotográfico."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"81320.001","nombre":"Cortador de películas / Cortadora de películas"},{"codigo":"81320.002","nombre":"Impresor de fotografía / Impresora de fotografía"},{"codigo":"81320.003","nombre":"Impresor de película fotográfica / Impresora de película fotográfica"},{"codigo":"81320.004","nombre":"Operador de laboratorio fotográfico / Operadora de laboratorio fotográfico"},{"codigo":"81320.005","nombre":"Operador de máquina de ampliación de fotografías / Operadora de máquina de ampliación de fotografías"},{"codigo":"81320.006","nombre":"Operador de máquina de fabricación de papel fotográfico / Operadora de máquina de fabricación de papel fotográfico"},{"codigo":"81320.007","nombre":"Operador de máquina de fabricación de placas fotográficas / Operadora de máquina de fabricación de placas fotográficas"},{"codigo":"81320.008","nombre":"Operador de máquina de procesamiento fotográfico y de películas / Operadora de máquina de procesamiento fotográfico y de películas"},{"codigo":"81320.009","nombre":"Operador de máquina de revelado de películas de cine / Operadora de máquina de revelado de películas de cine"},{"codigo":"81320.010","nombre":"Operador de máquina de revelado fotográfico / Operadora de máquina de revelado fotográfico"},{"codigo":"81320.011","nombre":"Operador de máquina para fabricar películas fotográficas / Operadora de máquina para fabricar películas fotográficas"},{"codigo":"81320.013","nombre":"Procesador fotográfico / Procesadora fotográfica"},{"codigo":"81320.014","nombre":"Procesador de películas / Procesadora de películas"},{"codigo":"81320.015","nombre":"Revelador de fotografías / Reveladora de fotografías"},{"codigo":"81320.016","nombre":"Revelador de negativos a color / Reveladora de negativos a color"},{"codigo":"81320.017","nombre":"Revelador de película RX / Reveladora de película RX"},{"codigo":"81320.018","nombre":"Revelador de películas en color / Reveladora de películas en color"},{"codigo":"81320.019","nombre":"Revelador de películas / Reveladora de películas"},{"codigo":"81320.020","nombre":"Revelador de placas RX / Reveladora de placas RX"},{"codigo":"81320.021","nombre":"Sacador de copias de fotografías / Sacadora de copias de fotografías"},{"codigo":"81320.022","nombre":"Técnico de cuarto oscuro / Técnica de cuarto oscuro"}],"conocimientos":[{"id":"9","nombre":"Computadoras, electrónica y automatización"},{"id":"7","nombre":"Producción y procesamiento"},{"id":"16","nombre":"Química"},{"id":"5","nombre":"Servicio al cliente"},{"id":"90","nombre":"Técnicas audiovisuales y producción para medios de comunicación"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"2","nombre":"Escucha activa"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"24","nombre":"Mantenimiento de equipos"},{"id":"15","nombre":"Orientación al servicio"},{"id":"6","nombre":"Pensamiento crítico"}],"ocupaciones_afines":[{"codigo":"31225","nombre":"Supervisores de impresión y ocupaciones relacionadas / Supervisoras de impresión y ocupaciones relacionadas"},{"codigo":"73211","nombre":"Pre-impresores y pre-prensistas de artes gráficas / Pre-impresoras y pre-prensistas de artes gráficas"}],"area_principal":{"sigla":"LIAG","nombre":"Literatura y artes gráficas"},"areas_complementarias":[{"sigla":"AVEM","nombre":"Audiovisuales, Artes Escénicas y Música"}],"equivalencias":[{"ciuo08_codigo":"8132*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"9374","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Operadores de máquinas para fabricar y procesar productos de caucho / Operadoras de máquinas para fabricar y procesar productos de caucho', '81410', 'Industria química', 2, false, '{"codigo":"81410","nombre":"Operadores de máquinas para fabricar y procesar productos de caucho / Operadoras de máquinas para fabricar y procesar productos de caucho","descripcion":"Operan y supervisan máquinas para el procesamiento del caucho y productos del caucho, producen diversos componentes para ensamblar e inspeccionar productos de caucho natural o sintético como calzado de goma, artículos del hogar, materiales aislantes, accesorios industriales y neumáticos. Se pueden desempeñar en fábricas de llantas, empresas de fabricación de productos de caucho, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"81","nombre":"OPERADORES DE INSTALACIONES FIJAS Y MÁQUINAS"},"subgrupo":{"codigo":"814","nombre":"Operadores de máquinas para fabricar productos de caucho, de papel y de material plástico"},"grupo_primario":{"codigo":"8141","nombre":"Operadores de máquinas para fabricar y procesar productos de caucho"}},"funciones":[{"consecutivo":1,"texto":"Operar, supervisar y ajustar maquinaria para formular, mezclar, molinear, estirado, extrusión, moldeo, inmersión, procesamiento posterior, vulcanización y desmolde de materiales o productos de caucho."},{"consecutivo":2,"texto":"Operar y supervisar máquinas que producen láminas de caucho o telas encauchadas por medio de cilindros giratorios."},{"consecutivo":3,"texto":"Operar máquinas, equipos o herramientas manuales para cortar, empalmar y pegar materiales de caucho para fabricar o reparar partes y productos acabados."},{"consecutivo":4,"texto":"Operar y supervisar máquinas que fabrican neumáticos para ruedas en hormas especiales, vulcanizan neumáticos o vuelven a moldear o encauchar neumáticos gastados."},{"consecutivo":5,"texto":"Operar máquinas o equipo de acabado para recortar, pulir, adelgazar, lavar y secar productos de caucho en su proceso final."},{"consecutivo":6,"texto":"Inspeccionar los productos acabados para garantizar especificaciones y estándares de calidad y detectar defectos de fabricación, visualmente o utilizando instrumentos."},{"consecutivo":7,"texto":"Localizar y rotular productos defectuosos para reparar o reciclar aplicando técnicas de vulcanización o de otro tipo, o su disposición final."},{"consecutivo":8,"texto":"Llevar registros de inspección a productos, según especificaciones y estándares de calidad."},{"consecutivo":9,"texto":"Preparar los productos de caucho por medio de técnicas de cementado o aplicación de adhesivos."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"81410.001","nombre":"Amasador de caucho / Amasadora de caucho"},{"codigo":"81410.002","nombre":"Calandrador de caucho / Calandradora de caucho"},{"codigo":"81410.003","nombre":"Cementador de caucho / Cementadora de caucho"},{"codigo":"81410.004","nombre":"Confeccionador de neumáticos / Confeccionadora de neumáticos"},{"codigo":"81410.005","nombre":"Cortador de caucho / Cortadora de caucho"},{"codigo":"81410.006","nombre":"Extrusor de caucho / Extrusora de caucho"},{"codigo":"81410.007","nombre":"Moldeador de caucho / Moldeadora de caucho"},{"codigo":"81410.008","nombre":"Operador de calandra en caucho / Operadora de calandra en caucho"},{"codigo":"81410.009","nombre":"Operador de calandria de caucho / Operadora de calandria de caucho"},{"codigo":"81410.010","nombre":"Operador de máquina amasadora y mezcladora de caucho / Operadora de máquina amasadora y mezcladora de caucho"},{"codigo":"81410.011","nombre":"Operador de máquina batidora de caucho / Operadora de máquina batidora de caucho"},{"codigo":"81410.012","nombre":"Operador de máquina cortadora de caucho / Operadora de máquina cortadora de caucho"},{"codigo":"81410.013","nombre":"O