  ('rol_cuoc', 'Operadores de máquinas para fabricar productos de papel / Operadoras de máquinas para fabricar productos de papel', '81430', 'Industria química', 2, false, '{"codigo":"81430","nombre":"Operadores de máquinas para fabricar productos de papel / Operadoras de máquinas para fabricar productos de papel","descripcion":"Operan y supervisan máquinas para fabricar bolsas, empaques, cajas, sobres y otros productos de papel, cartón, cartulina y materiales similares. Se pueden desempeñar en empresas fabricantes de productos de papel, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"81","nombre":"OPERADORES DE INSTALACIONES FIJAS Y MÁQUINAS"},"subgrupo":{"codigo":"814","nombre":"Operadores de máquinas para fabricar productos de caucho, de papel y de material plástico"},"grupo_primario":{"codigo":"8143","nombre":"Operadores de máquinas para fabricar productos de papel"}},"funciones":[{"consecutivo":1,"texto":"Operar y supervisar máquinas que pegan, cortan y pliegan papel o elementos de cartulina o de cartón para fabricar cajas, en dimensiones requeridas y artículos de cartón corrugado y similares."},{"consecutivo":2,"texto":"Operar y supervisar máquinas que prensan cartón o cartulina para fabricar vasos y otros recipientes en dimensiones requeridas."},{"consecutivo":3,"texto":"Operar y supervisar máquinas que cortan, encolan, pliegan y pegan papel para fabricar sobres o bolsas, o fabricar bolsas a partir de otros materiales."},{"consecutivo":4,"texto":"Operar y supervisar otras máquinas convertidoras de papel para elaborar productos como conos, tarjetas, toallas de papel o pañales."},{"consecutivo":5,"texto":"Limpiar, lubricar y realizar el mantenimiento predictivo, preventivo y correctivo de rutina a la máquina."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"81430.001","nombre":"Confeccionador de bolsas y sobres de papel / Confeccionadora de bolsas y sobres de papel"},{"codigo":"81430.002","nombre":"Encolador de cajas de cartón / Encoladora de cajas de cartón"},{"codigo":"81430.003","nombre":"Fabricante de bolsas y sobres de papel"},{"codigo":"81430.004","nombre":"Fabricante de cajas de cartón"},{"codigo":"81430.005","nombre":"Moldeador de papel mache / Moldeadora de papel mache"},{"codigo":"81430.006","nombre":"Operador de corrugadora de papel / Operadora de corrugadora de papel"},{"codigo":"81430.007","nombre":"Operador de fabricación de empaques papel / Operadora de fabricación de empaques papel"},{"codigo":"81430.008","nombre":"Operador de máquina corrugadora de cartón / Operadora de máquina corrugadora de cartón"},{"codigo":"81430.009","nombre":"Operador de máquina cortadora de cajas de cartón / Operadora de máquina cortadora de cajas de cartón"},{"codigo":"81430.010","nombre":"Operador de máquina de cortar y plegar cartón / Operadora de máquina de cortar y plegar cartón"},{"codigo":"81430.011","nombre":"Operador de máquina de fabricación de artículos de cartón / Operadora de máquina de fabricación de artículos de cartón"},{"codigo":"81430.012","nombre":"Operador de máquina de fabricación de artículos de papel / Operadora de máquina de fabricación de artículos de papel"},{"codigo":"81430.013","nombre":"Operador de máquina de fabricación de bolsas de papel / Operadora de máquina de fabricación de bolsas de papel"},{"codigo":"81430.014","nombre":"Operador de máquina de fabricación de cajas de cartón / Operadora de máquina de fabricación de cajas de cartón"},{"codigo":"81430.015","nombre":"Operador de máquina de fabricación de sobres de papel / Operadora de máquina de fabricación de sobres de papel"},{"codigo":"81430.016","nombre":"Operador de máquina estampadora de papel / Operadora de máquina estampadora de papel"},{"codigo":"81430.017","nombre":"Operador de máquina fabricación cajas / Operadora de máquina fabricación cajas"},{"codigo":"81430.018","nombre":"Operador de máquina forradora de cartón / Operadora de máquina forradora de cartón"},{"codigo":"81430.019","nombre":"Operador de máquina para la fabricación de productos de papel / Operadora de máquina para la fabricación de productos de papel"},{"codigo":"81430.020","nombre":"Operador de máquina plegadora de cajas de cartón / Operadora de máquina plegadora de cajas de cartón"},{"codigo":"81430.021","nombre":"Operador de máquina plegadora de productos de papel / Operadora de máquina plegadora de productos de papel"},{"codigo":"81430.022","nombre":"Prensista troquelador de artículos de papel / Prensista troqueladora de artículos de papel"}],"conocimientos":[{"id":"38","nombre":"Mantenimiento"},{"id":"77","nombre":"Materiales (vidrio, papel, plástico y madera)"},{"id":"13","nombre":"Mecánica y metalistería"},{"id":"7","nombre":"Producción y procesamiento"}],"destrezas":[{"id":"22","nombre":"Análisis de control de calidad"},{"id":"24","nombre":"Mantenimiento de equipos"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"26","nombre":"Reparación"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"81711","nombre":"Operadores de máquinas para la fabricación de papel / Operadoras de máquinas para la fabricación de papel"}],"area_principal":{"sigla":"INQU","nombre":"Industria química"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"8143","ciuo08_obs":"Denominaciones completas","cno_codigo":"9334","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Operadores de máquinas de preparación de fibras, hilado y devanado / Operadoras de máquinas de preparación de fibras, hilado y devanado', '81510', 'Textil, cuero, confección y diseño de modas', 2, false, '{"codigo":"81510","nombre":"Operadores de máquinas de preparación de fibras, hilado y devanado / Operadoras de máquinas de preparación de fibras, hilado y devanado","descripcion":"Operan y supervisan máquinas que preparan fibras e hilan, doblan, retuercen o devanar hilos e hilazas procedentes de fibras textiles naturales según especificaciones requeridas. Se pueden desempeñar en fábricas de textiles, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"81","nombre":"OPERADORES DE INSTALACIONES FIJAS Y MÁQUINAS"},"subgrupo":{"codigo":"815","nombre":"Operadores de máquinas para fabricar productos textiles y artículos de piel y cuero"},"grupo_primario":{"codigo":"8151","nombre":"Operadores de máquinas de preparación de fibras, hilado y devanado"}},"funciones":[{"consecutivo":1,"texto":"Operar y supervisar las máquinas para desgarrar trapos y reducirlos a fibras."},{"consecutivo":2,"texto":"Operar y supervisar las máquinas para limpiar y convertir los residuos de hilaza en lana esponjosa."},{"consecutivo":3,"texto":"Operar y supervisar las máquinas que revuelven y lubrican las fibras textiles para obtener mezclas uniformes de las clases deseadas."},{"consecutivo":4,"texto":"Operar y supervisar las máquinas que limpian y esponjan las fibras textiles, las convierten en cintas de fibras (mechas) las peinan, las combinan para formar rollos de fibras o cintas."},{"consecutivo":5,"texto":"Operar y supervisar máquinas de estirado provistas de varios conjuntos de estirado, cada uno de los cuales combina varias fibras en una sola de un peso y grosor similares a los de las fibras originales."},{"consecutivo":6,"texto":"Operar y supervisar máquinas para fabricar hilos e hilazas a partir de las fibras; para enrollar dos o más hilos en una bobina o devanador; para retorcer dos o más mechas de hilo o hilaza hasta obtener fibras más fuertes, más suaves o uniformes, o para enrollar hilos o hilazas de un paquete a otro."},{"consecutivo":7,"texto":"Operar y supervisar máquinas de hilatura que extraen y retuercen fibras o mechas en hilazas."},{"consecutivo":8,"texto":"Operar y supervisar máquinas que extraen hilo de cintas procedentes de máquinas estiradoras, para el texturizado del hilo."},{"consecutivo":9,"texto":"Preparar aprestos para dar rigidez y cualidades de acabado a tejidos e hilos, mezclando ingredientes como almidón, sebo, resinas, jabones y agua e hirviendo la mezcla al vapor durante un tiempo determinado."},{"consecutivo":10,"texto":"Tratar los tejidos con productos químicos para hacerlos resistentes al agua."},{"consecutivo":11,"texto":"Detectar interrupciones y notificar al supervisor o mecánico sobre el mal funcionamiento de las máquinas."},{"consecutivo":12,"texto":"Limpiar los rodillos y cilindros de las máquinas de cardar para retirar los restos de lana."},{"consecutivo":13,"texto":"Tratar y volver a allanar la superficie de los rodillos de metal de diversas máquinas de hilar, peinar y lustrar aplicando nuevos recubrimientos de caucho o cuero."},{"consecutivo":14,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"81510.001","nombre":"Devanador de fibras textiles / Devanadora de fibras textiles"},{"codigo":"81510.002","nombre":"Devanador de textiles / Devanadora de textiles"},{"codigo":"81510.003","nombre":"Encanillador de textiles / Encanilladora de textiles"},{"codigo":"81510.004","nombre":"Lavador de lana con máquina / Lavadora de lana con máquina"},{"codigo":"81510.005","nombre":"Lavador de fibras de lana con máquina / Lavadora de fibras de lana con máquina"},{"codigo":"81510.006","nombre":"Lavador de fibras textiles con máquina / Lavadora de fibras textiles con máquina"},{"codigo":"81510.007","nombre":"Lavador de hilados y productos textiles / Lavadora de hilados y productos textiles"},{"codigo":"81510.010","nombre":"Operador de cardas textiles / Operadora de cardas textiles"},{"codigo":"81510.011","nombre":"Operador de engomadora de hilados / Operadora de engomadora de hilados"},{"codigo":"81510.012","nombre":"Operador de hilatura / Operadora de hilatura"},{"codigo":"81510.013","nombre":"Operador de máquina abridora y mezcladora textiles / Operadora de máquina abridora y mezcladora textiles"},{"codigo":"81510.014","nombre":"Operador de máquina acondicionadora de fibras / Operadora de máquina acondicionadora de fibras"},{"codigo":"81510.015","nombre":"Operador de máquina banco de estiraje de fibras textiles / Operadora de máquina banco de estiraje de fibras textiles"},{"codigo":"81510.016","nombre":"Operador de máquina bobinadora de hilo e hilaza / Operadora de máquina bobinadora de hilo e hilaza"},{"codigo":"81510.017","nombre":"Operador de máquina combinadora de fibras / Operadora de máquina combinadora de fibras"},{"codigo":"81510.018","nombre":"Operador de máquina continua de fibras textiles / Operadora de máquina continua de fibras textiles"},{"codigo":"81510.019","nombre":"Operador de máquina continua de hilados / Operadora de máquina continua de hilados"},{"codigo":"81510.020","nombre":"Operador de máquina de doblaje de hilo e hilaza / Operadora de máquina de doblaje de hilo e hilaza"},{"codigo":"81510.021","nombre":"Operador de máquina de estiraje de fibras textiles / Operadora de máquina de estiraje de fibras textiles"},{"codigo":"81510.022","nombre":"Operador de máquina de hilado de fibras sintéticas / Operadora de máquina de hilado de fibras sintéticas"},{"codigo":"81510.023","nombre":"Operador de máquina de hilado de fibras textiles / Operadora de máquina de hilado de fibras textiles"},{"codigo":"81510.024","nombre":"Operador de máquina de hilado de hilo e hilaza / Operadora de máquina de hilado de hilo e hilaza"},{"cod