  ('rol_cuoc', 'Operadores de máquinas de lavandería / Operadoras de máquinas de lavandería', '81570', 'Servicios Personales y a la Comunidad', 2, false, '{"codigo":"81570","nombre":"Operadores de máquinas de lavandería / Operadoras de máquinas de lavandería","descripcion":"Operan y supervisan máquinas de lavado, limpieza en seco, tratamiento de tejidos, tinturado y planchado de prendas de vestir y artículos del hogar, revisan prendas lavadas para garantizar que cumplan los requisitos de limpieza y planchado, organizan y empacan prendas lavadas. Se pueden desempeñar en lavanderías, tintorerías, lavanderías de hoteles, hospitales, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"81","nombre":"OPERADORES DE INSTALACIONES FIJAS Y MÁQUINAS"},"subgrupo":{"codigo":"815","nombre":"Operadores de máquinas para fabricar productos textiles y artículos de piel y cuero"},"grupo_primario":{"codigo":"8157","nombre":"Operadores de máquinas de lavandería"}},"funciones":[{"consecutivo":1,"texto":"Clasificar y colocar en recipientes y cintas transportadoras las prendas de vestir para limpiarlas según: tipo, color, tejido y tratamiento en zonas de reparación y limpieza."},{"consecutivo":2,"texto":"Operar y supervisar máquinas de lavado en seco para limpiar prendas, vestidos, chaquetas, sacos, cortinas, cojinería, alfombras, tapetes, muebles tapizados y otras prendas y artículos domésticos dependiendo del tratamiento de limpieza requerido."},{"consecutivo":3,"texto":"Operar y supervisar máquinas para secar, teñir, rociar, lubricar, planchar y pulir prendas de cuero y gamuza."},{"consecutivo":4,"texto":"Operar y supervisar máquinas lavadoras, secadoras y extractoras para lavar camisas, sábanas, cobijas, toallas y otras prendas y artículos de hogar."},{"consecutivo":5,"texto":"Operar y supervisar máquinas de limpieza y planchado para prendas de vestir, según: tipo, tejido, entre otros y retocar terminaciones."},{"consecutivo":6,"texto":"Organizar y empacar prendas de vestir y accesorios domésticos y organizar la entrega de pedidos, según protocolo del establecimiento."},{"consecutivo":7,"texto":"Añadir agentes de limpieza y almidones a las prendas de vestir, según tratamiento de limpieza requerido."},{"consecutivo":8,"texto":"Inspeccionar y registrar prendas dañadas y las que no han sido lavadas adecuadamente para garantizar estándares de planchado, limpieza e higiene."},{"consecutivo":9,"texto":"Poner en marcha y parar máquinas para desenredar, estirar y retirar prendas de vestir."},{"consecutivo":10,"texto":"Colocar artículos en estantes y colgarlos para su entrega y recogida, según protocolo del establecimiento."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"81570.001","nombre":"Auxiliar de lavandería"},{"codigo":"81570.002","nombre":"Clasificador de ropa de lavandería / Clasificadora de ropa de lavandería"},{"codigo":"81570.003","nombre":"Desmanchador de lavandería / Desmanchadora de lavandería"},{"codigo":"81570.004","nombre":"Lavador de cortinas a máquina / Lavadora de cortinas a máquina"},{"codigo":"81570.005","nombre":"Operador de equipo de lavandería / Operadora de equipo de lavandería"},{"codigo":"81570.006","nombre":"Operador de equipo de limpieza de alfombras / Operadora de equipo de limpieza de alfombras"},{"codigo":"81570.007","nombre":"Operador de máquina de lavado en seco / Operadora de máquina de lavado en seco"},{"codigo":"81570.008","nombre":"Operador de máquina de lavadora de textiles / Operadora de máquina de lavadora de textiles"},{"codigo":"81570.009","nombre":"Operador de máquina de lavandería / Operadora de máquina de lavandería"},{"codigo":"81570.010","nombre":"Operador de máquina de limpieza en seco / Operadora de máquina de limpieza en seco"},{"codigo":"81570.011","nombre":"Operador de máquina de planchado de lavandería / Operadora de máquina de planchado 