  ('rol_cuoc', 'Operadores de máquinas para fabricar productos textiles y artículos de piel y cuero no clasificadas en otras ocupaciones / Operadoras de máquinas para fabricar productos textiles y artículos de piel y cuero no clasificadas en otras ocupaciones', '81590', 'Textil, cuero, confección y diseño de modas', 2, false, '{"codigo":"81590","nombre":"Operadores de máquinas para fabricar productos textiles y artículos de piel y cuero no clasificadas en otras ocupaciones / Operadoras de máquinas para fabricar productos textiles y artículos de piel y cuero no clasificadas en otras ocupaciones","descripcion":"Esta ocupación abarca a operadores de máquinas para fabricar productos textiles y artículos de piel y cuero no clasificados en otras ocupaciones en el Subgrupo 815: Operadores de máquinas para fabricar productos textiles y artículos de piel y cuero. Por ejemplo, incluye a los encargados de manejar y supervisar las máquinas utilizadas para confeccionar sombreros, tiendas de campaña, colchones y artículos diversos, como trenzados y otros adornos. Se pueden desempeñar en empresas de textiles, empresas que fabrican prendas de vestir, acolchados, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"81","nombre":"OPERADORES DE INSTALACIONES FIJAS Y MÁQUINAS"},"subgrupo":{"codigo":"815","nombre":"Operadores de máquinas para fabricar productos textiles y artículos de piel y cuero"},"grupo_primario":{"codigo":"8159","nombre":"Operadores de máquinas para fabricar productos textiles y artículos de piel y cuero no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Operar y supervisar máquinas para fabricar sombreros hechos de materias textiles, piel o cuero."},{"consecutivo":2,"texto":"Operar y supervisar máquinas para confeccionar artículos de pasamanería o de punto de ganchillo y otros adornos."},{"consecutivo":3,"texto":"Operar y supervisar máquinas que doblan los tejidos a la longitud deseada."},{"consecutivo":4,"texto":"Operar y supervisar máquinas que enrollan los hilos, bramantes o hilazas en madejas a fin de preparar estos artículos para su expedición o posterior tratamiento."},{"consecutivo":5,"texto":"Operar y supervisar equipo para medir el tamaño de las piezas de cuero."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"81590.001","nombre":"Acabador y adornador de sombreros / Acabadora y adornadora de sombreros"},{"codigo":"81590.002","nombre":"Operador de máquina de fabricación de colchones / Operadora de máquina de fabricación de colchones"},{"codigo":"81590.003","nombre":"Operador de máquina de fabricación de conos de fieltro de sombreros / Operadora de máquina de fabricación de conos de fieltro de sombreros"},{"codigo":"81590.004","nombre":"Operador de máquina de fabricación de pasamanería / Operadora de máquina de fabricación de pasamanería"},{"codigo":"81590.005","nombre":"Operador de máquina de fabricación de patrones de cuero / Operadora de máquina de fabricación de patrones de cuero"},{"codigo":"81590.006","nombre":"Operador de máquina de fabricación de patrones textiles / Operadora de máquina de fabricación de patrones textiles"},{"codigo":"81590.007","nombre":"Operador de máquina de fabricación de sombreros de fieltro / Operadora de máquina de fabricación de sombreros de fieltro"},{"codigo":"81590.008","nombre":"Operador de máquina de fabricación de tiendas de campaña / Operadora de máquina de fabricación de tiendas de campaña"},{"codigo":"81590.009","nombre":"Operador de máquina de sombrerería / Operadora de máquina de sombrerería"},{"codigo":"81590.010","nombre":"Operador de máquina de trenzado / Operadora de máquina de trenzado"},{"codigo":"81590.011","nombre":"Operador en la confección de muñecos y juguetes de trapo / Operadora en la confección de muñecos y juguetes de trapo"}],"conocimientos":[{"id":"7","nombre":"Producción y procesamiento"},{"id":"84","nombre":"Productos textiles (ropa, calzado y artículos de cuero)"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"39","nombre":"Creatividad"},{"id":"36","nombre":"Ensamble"},{"id":"2","nombre":"Escucha activa"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"6","nombre":"Pensamiento crítico"},{"id":"38","nombre":"Seguir instrucciones"}],"ocupaciones_afines":[{"codigo":"75310","nombre":"Sastres, modistos, peleteros y sombrereros / Sastresas, modistas, peleteras y sombrereras"},{"codigo":"75322","nombre":"Cortadores de tela, cuero y piel / Cortadoras de tela, cuero y piel"},{"codigo":"81530","nombre":"Operadores de máquinas de coser y bordar / Operadoras de máquinas de coser y bordar"}],"area_principal":{"sigla":"TCCD","nombre":"Textil, cuero, confección y diseño de modas"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"8159","ciuo08_obs":"Denominaciones completas","cno_codigo":"8422*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"9342*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Operadores de máquinas para elaborar alimentos y productos afines / Operadoras de máquinas para elaborar alimentos y productos afines', '81600', 'Elaboración y transformación de alimentos', 2, false, '{"codigo":"81600","nombre":"Operadores de máquinas para elaborar alimentos y productos afines / Operadoras de máquinas para elaborar alimentos y productos afines","descripcion":"Aprestan, operan y supervisan el funcionamiento de máquinas utilizadas para el sacrificio, el faenado, el desposte, el desprese y el acondicionamiento de la carne de animales para consumo humano (bovinos, porcinos, aves, pescados, etc.); operan máquinas de control de proceso multifuncional o máquinas de función simple para procesar alimentos, bebidas, hojas de tabaco y sus derivados. Se pueden desempeñar en establecimientos de beneficio de animales, desposte, desprese y acondicionadores de carnes de abasto público, en plantas de procesamiento de frutas y verduras, lácteos, harineras, panaderías industriales, ingenios, plantas procesadoras de carne, cervecerías, pescado, fabricantes de cigarrillos y tabacos, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"81","nombre":"OPERADORES DE INSTALACIONES FIJAS Y MÁQUINAS"},"subgrupo":{"codigo":"816","nombre":"Operadores de máquinas para elaborar alimentos y productos afines"},"grupo_primario":{"codigo":"8160","nombre":"Operadores de máquinas para elaborar alimentos y productos afines"}},"funciones":[{"consecutivo":1,"texto":"Operar y supervisar máquinas de control de proceso multifuncional a través de tableros de control, terminales de computador, medidores y monitores para verificar las condiciones del procesamiento de productos alimenticios y hacer los ajustes necesarios del proceso como tiempos de cocción, adición de ingredientes, promedios de flujo y temperatura ambiente."},{"consecutivo":2,"texto":"Operar y supervisar máquinas de control de proceso multifuncional para moler, mezclar, salar, cocinar, extraer, deshidratar, liofilizar, revolver, destilar, fermentar y otras formas de procesar bebidas alcohólicas y no alcohólicas y para embotellar, enlatar y otras formas de envasar bebidas."},{"consecutivo":3,"texto":"Operar y supervisar máquinas para enfriar, calentar, secar, tostar, escaldar, pasteurizar, ahumar, esterilizar, congelar, evaporar, concentrar y otras formas de procesar productos alimenticios, líquidos y bebidas para envasar y empacar de diferentes formas."},{"consecutivo":4,"texto":"Operar y supervisar máquinas de control de proceso multifuncional e implementos usados para el proceso de beneficio de ganado, aves y peces, aplicando los protocolos, según la normatividad vigente para procesamiento y empaque."},{"consecutivo":5,"texto":"Operar y supervisar máquinas y equipos para limpiar, cortar, cocer, ahumar, deshidratar, perfilar, maquillar y otras formas de procesar y transformar pescados y mariscos."},{"consecutivo":6,"texto":"Operar y supervisar máquinas para enlatar, embolsar, embalar y otras formas de empacar productos alimenticios, cárnicos, pescado, mariscos, líquidos y bebidas."},{"consecutivo":7,"texto":"Operar y supervisar máquinas para pelar, desvenar, cortar, eviscerar, lavar, despinar, deshuesar, retirar escamas, separar filetes de pescado y mariscos y desprender la carne de crustáceos; arreglar el producto manteniendo la cadena de frio para enlatarla o para futuro procesamiento."},{"consecutivo":8,"texto":"Operar y supervisar máquinas para mezclar, aromatizar, humedecer, despalillar, secar, o cortar y otros procesos con hojas de tabaco."},{"consecutivo":9,"texto":"Operar y supervisar máquinas para fabricación y empaque de cigarrillos, cigarros, tabaco de pipa y otros productos."},{"consecutivo":10,"texto":"Operar y supervisar máquinas y hornos para mezclar, hornear y preparar de otra forma pan y productos de confitería, lácteos, grasas comestibles, almidón de maíz, embutidos, entre otros."},{"consecutivo":11,"texto":"Operar y supervisar máquinas para batir, prensar, colar, filtrar, mezclar, reducir a pulpa, triturar, amasar y separar productos de alimentación y líquidos."},{"consecutivo":12,"texto":"Implementar y garantizar el cumplimiento de los protocolos y procedimientos de los programas de buenas prácticas de manufactura y manejo de residuos sólidos y vertimientos."},{"consecutivo":13,"texto":"Inspeccionar y registrar la información de productos, variables de temperatura, empaque y etiquetado para detectar irregularidades a fin de garantizar los estándares de calidad y producción, de acuerdo con normativas del procedimiento."},{"consecutivo":14,"texto":"Realizar tareas de mantenimiento básico de las máquinas e informar al supervisor o mecánico sobre el mal funcionamiento si es necesario."},{"consecutivo":15,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"81600.001","nombre":"Ahumador de pescado de procesamiento / Ahumadora de pescado de procesamiento"},{"codigo":"81600.002","nombre":"Almacenador de carne en canal / Almacenadora de carne en canal"},{"codigo":"81600.004","nombre":"Cervecero / Cervecera"},{"codigo":"81600.005","nombre":"Cocedor de malta / Cocedora de malta"},{"codigo":"81600.006","nombre":"Conservero de pescado / Conservera de pescado"},{"codigo":"81600.007","nombre":"Cortador industrial de carnes con máquina / Cortadora industrial de carnes con máquina"},{"codigo":"81600.008","nombre":"Cristalero de refinación de azúcar / Cristalera de refinación de azúcar"},{"codigo":"81600.009","nombre":"Descascarador de mariscos / Descascaradora de mariscos"},{"codigo":"81600.010","nombre":"Desecador de malta / Desecadora de malta"},{"codigo":"81600.011","nombre":"Deshidratador de granos para el procesamiento de alimentos y bebidas / Deshidratadora de granos para el procesamiento de alimentos y bebidas"},{"codigo":"81600.013","nombre":"Deshuesador de carne / Deshuesadora de carne