  ('rol_cuoc', 'Operadores de máquinas de vapor y calderas / Operadoras de máquinas de vapor y calderas', '81820', 'Producción de energía y electricidad', 2, false, '{"codigo":"81820","nombre":"Operadores de máquinas de vapor y calderas / Operadoras de máquinas de vapor y calderas","descripcion":"Operan y mantienen diversos tipos de máquinas estacionarias de vapor, calderas, turbinas y equipo auxiliar, como generadores, compresores y otro equipo para proveer luz y energía para edificios, plantas industriales, otros sitios de trabajo y a bordo de buques o de otras embarcaciones autopropulsadas. Se pueden desempeñar en plantas industriales, hospitales, universidades y establecimientos gubernamentales y comerciales, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"81","nombre":"OPERADORES DE INSTALACIONES FIJAS Y MÁQUINAS"},"subgrupo":{"codigo":"818","nombre":"Otros operadores de máquinas y de instalaciones fijas"},"grupo_primario":{"codigo":"8182","nombre":"Operadores de máquinas de vapor y calderas"}},"funciones":[{"consecutivo":1,"texto":"Analizar y registrar las lecturas de los instrumentos, identificar averías de funcionamiento y realizar pequeñas reparaciones para prevenir fallas en los equipos o sistemas."},{"consecutivo":2,"texto":"Operar sistemas de control automatizado o computarizado, máquinas estacionarias y equipo auxiliar como calderas, turbinas, generadores, compresores y otros equipos para proveer luz y energía para edificaciones, plantas industriales y otros sitios de trabajo."},{"consecutivo":3,"texto":"Monitorear e inspeccionar equipo de planta, interruptores, válvulas, medidores, alarmas y otros instrumentos para medir temperatura, presión, flujo de combustible a fin de detectar niveles requeridos de agua de las calderas, de productos químicos, escapes o mal funcionamiento y garantizar una operación normal del equipo de planta."},{"consecutivo":4,"texto":"Operar, limpiar, lubricar y supervisar máquinas de vapor, calderas y equipos auxiliares, como generadores, turbinas, bombas, compresores, aire acondicionado, con el fin de mantener el suministro de vapor y energía a edificios, embarcaciones o herramientas neumáticas."},{"consecutivo":5,"texto":"Analizar lecturas de los indicadores de los motores, máquinas y equipos de los buques, registrar las variables y notificar toda anomalía observada al oficial de máquinas sobre el mal funcionamiento de las máquinas."},{"consecutivo":6,"texto":"Accionar y mantener en buen estado las bombas y válvulas de descarga de líquidos."},{"consecutivo":7,"texto":"Encender los hornos de carbón manualmente o con un cargador, y las calderas de gas o de petróleo con dispositivos de alimentación automática de gas o bombas de combustible."},{"consecutivo":8,"texto":"Asegurar la calidad del agua de las calderas, hacer las rectificaciones del caso y tomar medidas pertinentes como la adición de productos químicos para prevenir la corrosión y la deposición de sustancias nocivas."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"81820.001","nombre":"Calderista"},{"codigo":"81820.002","nombre":"Encargado de caldera / Encargada de caldera"},{"codigo":"81820.003","nombre":"Fogonero de buque / Fogonera de buque"},{"codigo":"81820.004","nombre":"Fogonero de máquina de vapor / Fogonera de máquina de vapor"},{"codigo":"81820.005","nombre":"Maquinista de equipos fijos"},{"codigo":"81820.006","nombre":"Operador de caldera / Operadora de caldera"},{"codigo":"81820.007","nombre":"Operador de caldera de buque / Operadora de caldera de buque"},{"codigo":"81820.008","nombre":"Operador de máquina de vapor y caldera / Operadora de máquina de vapor y caldera"},{"codigo":"81820.009","nombre":"Operador de máquina estacionaria vapor y caldera / Operadora de máquina estacionaria vapor y caldera"},{"codigo":"81820.010","nombre":"Operador de máquina est