  ('rol_cuoc', 'Ensambladores de aparatos y equipo eléctrico / Ensambladoras de aparatos y equipo eléctrico', '82122', 'Producción de energía y electricidad', 2, false, '{"codigo":"82122","nombre":"Ensambladores de aparatos y equipo eléctrico / Ensambladoras de aparatos y equipo eléctrico","descripcion":"Ensamblan partes prefabricadas para producir electrodomésticos, componentes, equipos y aparatos eléctricos de uso comercial de acuerdo con los procedimientos establecidos de producción. Revisan y prueban productos ensamblados. Se pueden desempeñar en empresas de fabricación de equipos y aparatos eléctricos, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"82","nombre":"ENSAMBLADORES"},"subgrupo":{"codigo":"821","nombre":"Ensambladores"},"grupo_primario":{"codigo":"8212","nombre":"Ensambladores de equipos eléctricos y electrónicos"}},"funciones":[{"consecutivo":1,"texto":"Ensamblar partes prefabricadas y productos eléctricos en línea de ensamble o en banco de trabajo, utilizando herramientas manuales o eléctricas, equipos de soldadura y micro- soldadura."},{"consecutivo":2,"texto":"Ensamblar pequeños transformadores y motores eléctricos, transmisiones usadas en los aparatos u otros productos eléctricos según especificaciones técnicas."},{"consecutivo":3,"texto":"Ensamblar interruptores de circuito u otros equipos de control eléctrico, colocar y fijar componentes como resortes y otras partes en el ensamble de cajas utilizando herramientas manuales o eléctricas, equipos de soldadura y microsoldadura."},{"consecutivo":4,"texto":"Operar y supervisar máquinas para enrollar las bobinas y dínamos, usadas en equipos, componentes eléctricos, pequeños motores y transformadores."},{"consecutivo":5,"texto":"Revisar las órdenes de trabajo y preparar línea de ensamble, según especificaciones, diagramas, planos e instrucciones de ensamblaje para determinar los materiales y suministros requeridos para la producción."},{"consecutivo":6,"texto":"Revisar y probar productos para detectar defectos y fallas en las conexiones eléctricas y mecánicas u operar equipo de prueba automático para garantizar la calidad del producto."},{"consecutivo":7,"texto":"Efectuar pequeñas reparaciones a productos rechazados desde la línea de ensamble."},{"consecutivo":8,"texto":"Registrar y mantener datos de producción y operacionales en formularios previstos para tal efecto."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"82122.001","nombre":"Ensamblador de accesorios eléctricos / Ensambladora de accesorios eléctricos"},{"codigo":"82122.002","nombre":"Ensamblador de aparatos eléctricos / Ensambladora de aparatos eléctricos"},{"codigo":"82122.003","nombre":"Ensamblador de armaduras de bobina / Ensambladora de armaduras de bobina"},{"codigo":"82122.004","nombre":"Ensamblador de bujías / Ensambladora de bujías"},{"codigo":"82122.005","nombre":"Ensamblador de componentes eléctricos / Ensambladora de componentes eléctricos"},{"codigo":"82122.006","nombre":"Ensamblador de condensadores electrónicos / Ensambladora de condensadores electrónicos"},{"codigo":"82122.007","nombre":"Ensamblador de electrodomésticos / Ensambladora de electrodomésticos"},{"codigo":"82122.008","nombre":"Ensamblador de equipo audiovisual / Ensambladora de equipo audiovisual"},{"codigo":"82122.009","nombre":"Ensamblador de equipo de microelectrónica / Ensambladora de equipo de microelectrónica"},{"codigo":"82122.010","nombre":"Ensamblador de equipos eléctricos / Ensambladora de equipos eléctricos"},{"codigo":"82122.011","nombre":"Ensamblador de equipos electromecánicos / Ensambladora de equipos electromecánicos"},{"codigo":"82122.012","nombre":"Ensamblador de instrumentos de precisión electrónica / Ensambladora de instrumentos de precisión electrónica"},{"codigo":"82122.013","nombre":"Ensamblador de interruptores / Ensambladora de interru