  ('rol_cuoc', 'Maquinistas de transporte ferroviario', '83110', 'Logística y transporte', 2, true, '{"codigo":"83110","nombre":"Maquinistas de transporte ferroviario","descripcion":"Conducen o ayudan a conducir locomotoras de trenes para el transporte de pasajeros, carga y operan sistemas para comunicarse con la tripulación de los trenes y los controladores del tráfico ferroviario. Se pueden desempeñar en compañías de transporte ferroviario, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"83","nombre":"CONDUCTORES DE VEHÍCULOS Y OPERADORES DE EQUIPOS PESADOS MÓVILES"},"subgrupo":{"codigo":"831","nombre":"Maquinistas de locomotoras y afines"},"grupo_primario":{"codigo":"8311","nombre":"Maquinistas de transporte ferroviario"}},"funciones":[{"consecutivo":1,"texto":"Conducir o ayudar a conducir locomotoras de vapor, eléctricas o motor diésel para transportar pasajeros y carga en vías férreas subterráneas o en la superficie de acuerdo reglamentación y procedimientos operativos."},{"consecutivo":2,"texto":"Inspeccionar las vías para detectar peligros, observar señales de acuerdo reglamentación y procedimientos operativos."},{"consecutivo":3,"texto":"Inspeccionar y probar los controles de operación, equipo, nivel de combustible y realizar el mantenimiento de rutina de las locomotoras asignadas."},{"consecutivo":4,"texto":"Operar sistemas para comunicarse con la tripulación de los trenes y los controladores del tráfico ferroviario, para garantizar la seguridad de sus operaciones y la programación de los trenes."},{"consecutivo":5,"texto":"Verificar, Identificar, reportar las condiciones preoperacionales y operacionales del tren."},{"consecutivo":6,"texto":"Cumplir con las normas de seguridad establecidas para la movilización de los trenes."},{"consecutivo":7,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"83110.001","nombre":"Auxiliar de conducción ferroviaria"},{"codigo":"83110.002","nombre":"Auxiliar de maquinista ferroviario"},{"codigo":"83110.003","nombre":"Conductor de ferrocarril metropolitano / Conductora de ferrocarril metropolitano"},{"codigo":"83110.004","nombre":"Conductor de locomotora / Conductora de locomotora"},{"codigo":"83110.005","nombre":"Conductor de tren / Conductora de tren"},{"codigo":"83110.006","nombre":"Maquinista de locomotora"},{"codigo":"83110.007","nombre":"Maquinista de locomotora de cantera"},{"codigo":"83110.008","nombre":"Maquinista de locomotora de maniobras"},{"codigo":"83110.010","nombre":"Maquinista de locomotoras de minas"},{"codigo":"83110.012","nombre":"Maquinista de patio ferroviario"},{"codigo":"83110.013","nombre":"Maquinista de transporte ferroviario"},{"codigo":"83110.014","nombre":"Maquinista de tren"},{"codigo":"83110.015","nombre":"Maquinista de tren de carga"},{"codigo":"83110.016","nombre":"Maquinista de tren de pasajeros"},{"codigo":"83110.017","nombre":"Maquinista de tren minero"},{"codigo":"83110.018","nombre":"Maquinista ferroviario / Maquinista ferroviaria"},{"codigo":"83110.019","nombre":"Operador de locomotora / Operadora de locomotora"},{"codigo":"83110.020","nombre":"Operador de locomotora en las esclusas / Operadora de locomotora en las esclusas"}],"conocimientos":[{"id":"38","nombre":"Mantenimiento"},{"id":"41","nombre":"Primeros auxilios"},{"id":"101","nombre":"Principios éticos"},{"id":"85","nombre":"Seguridad y salud en el trabajo"},{"id":"5","nombre":"Servicio al cliente"},{"id":"31","nombre":"Servicios de transporte"},{"id":"29","nombre":"Telecomunicación"}],"destrezas":[{"id":"17","nombre":"Análisis de necesidades"},{"id":"1","nombre":"Comprensión de lectura"},{"id":"4","nombre":"Comunicación asertiva"},{"id":"28","nombre":"Criterio y toma de decisiones"},{"id":"24","nombre":"Mantenimiento de equipos"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"34","nombre":"Trabajo bajo presión"}],"ocupaciones_afines":[{"codigo":"83310","nombre":"Conductores de buses, microbuses y tranvías / Conductoras de buses, microbuses y tranvías"}],"area_principal":{"sigla":"LOTR","nombre":"Logística y transporte"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"8311","ciuo08_obs":"Denominaciones completas","cno_codigo":"8461","cno_obs":"Denominaciones completas"}]}'::jsonb),
  ('rol_cuoc', 'Guardafrenos, guardagujas y agentes de maniobras', '83120', 'Logística y transporte', 2, false, '{"codigo":"83120","nombre":"Guardafrenos, guardagujas y agentes de maniobras","descripcion":"Velan por la buena marcha y la seguridad de los trenes de carga y pasajeros, revisan los sistemas de frenos, otros sistemas y equipos antes de la circulación y apoyan a los conductores en otras actividades de rutina. Efectúan operaciones de control del tráfico ferroviario accionando los sistemas de señales, hacen cambios de vía para el material rodante, forman trenes en los apartaderos de ferrocarril, enganchan vagonetas de carga para formar trenes que circulan en vías férreas. Se pueden desempeñar en compañías de transporte ferroviario, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"83","nombre":"CONDUCTORES DE VEHÍCULOS Y OPERADORES DE EQUIPOS PESADOS MÓVILES"},"subgrupo":{"codigo":"831","nombre":"Maquinistas de locomotoras y afines"},"grupo_primario":{"codigo":"8312","nombre":"Guardafrenos, guardagujas y agentes de maniobras"}},"funciones":[{"consecutivo":1,"texto":"Tomar el control y salvaguardar el tren de carga durante los recorridos de acuerdo con procedimiento establecidos."},{"consecutivo":2,"texto":"Controlar el tráfico ferroviario en diferentes tramos o empalmes de líneas, accionando señales, agujas e interruptores desde los puentes de control o de señalización, para garantizar las operaciones del tren se realicen de acuerdo con las programaciones y reglamentos de operación."},{"consecutivo":3,"texto":"Cambiar y ajustar material rodante en las estaciones del ferrocarril y apartaderos de acuerdo con instrucciones recibidas en cuanto a carga, descarga y formación de trenes."},{"consecutivo":4,"texto":"Revisar y hacer ajustes menores a los sistemas y equipos del tren, como aire acondicionado y sistemas de calefacción, frenos y mangueras de frenos antes de la partida."},{"consecutivo":5,"texto":"Colocar y liberar los frenos de mano y conectar las mangueras de frenos de aire para unir, enganchar y arrastrar los vagones de carga y pasajeros de acuerdo con normas y procedimientos establecidos."},{"consecutivo":6,"texto":"Recibir órdenes de los controladores de tráfico y observar las señales de acuerdo normativa y políticas de la empresa."},{"consecutivo":7,"texto":"Preparar los informes de recorrido de acuerdo con normas y procedimientos establecidos."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"83120.001","nombre":"Agente de maniobras de ferrocarril"},{"codigo":"83120.002","nombre":"Enganchador de trenes / Enganchadora de trenes"},{"codigo":"83120.003","nombre":"Enganchador de vagones de ferrocarril / Enganchadora de vagones de ferrocarril"},{"codigo":"83120.004","nombre":"Frenero de guarda frenos de tren / Frenera de guarda frenos de tren"},{"codigo":"83120.005","nombre":"Guardafreno"},{"codigo":"83120.006","nombre":"Guardafrenos de ferrocarril"},{"codigo":"83120.007","nombre":"Guardafrenos de tren"},{"codigo":"83120.008","nombre":"Guardafrenos de tren de vagonetas de minas"},{"codigo":"83120.009","nombre":"Guardagujas de ferrocarril"},{"codigo":"83120.010","nombre":"Guardagujas enganchador de minas y canteras / Guardagujas enganchadora de minas y canteras"},{"codigo":"83120.011","nombre":"Guardalíneas de paso a nivel"},{"codigo":"83120.012","nombre":"Operador de enganche de vagones de tren / Operadora de enganche de vagones de tren"},{"codigo":"83120.013","nombre":"Operador de puesto de control ferroviario / Operadora de puesto de control ferroviario"},{"codigo":"83120.014","nombre":"Operador de torre de señales de ferrocarril / Operadora de torre de señales de ferrocarril"},{"codigo":"83120.015","nombre":"Trabajador de patio de ferrocarril / Trabajadora de patio de ferrocarril"}],"conocimientos":[{"id":"38","nombre":"Mantenimiento"},{"id":"5","nomb