  ('rol_cuoc', 'Conductores de motocicletas / Conductoras de motocicletas', '83210', 'Logística y transporte', 2, true, '{"codigo":"83210","nombre":"Conductores de motocicletas / Conductoras de motocicletas","descripcion":"Conducen y mantienen en buen estado motocicletas o triciclos motorizados equipados para el transporte de materiales, mercancías o pasajeros. Se pueden desempeñar en empresas de correspondencia, mensajería y correo, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"83","nombre":"CONDUCTORES DE VEHÍCULOS Y OPERADORES DE EQUIPOS PESADOS MÓVILES"},"subgrupo":{"codigo":"832","nombre":"Conductores de automóviles, camionetas y motocicletas"},"grupo_primario":{"codigo":"8321","nombre":"Conductores de motocicletas"}},"funciones":[{"consecutivo":1,"texto":"Conducir y mantener en buen estado motocicletas o triciclos motorizados para transportar materiales, mercancías o pasajeros según servicio contratado."},{"consecutivo":2,"texto":"Respetar las reglas y señales de tráfico de acuerdo con normativa de convivencia y de tránsito y transporte."},{"consecutivo":3,"texto":"Realizar mantenimiento y reparaciones menores, y limpiar e higienizar los vehículos motocicletas o triciclos motorizados."},{"consecutivo":4,"texto":"Mantener registros y control de los desplazamientos."},{"consecutivo":5,"texto":"Entregar mensajería, correspondencia, paquetería, entre otros según servicio contratado."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"83210.001","nombre":"Conductor de bicitaxi motorizado / Conductora de bicitaxi motorizado"},{"codigo":"83210.002","nombre":"Conductor de motocicleta / Conductora de motocicleta"},{"codigo":"83210.003","nombre":"Conductor de motocicleta de reparto / Conductora de motocicleta de reparto"},{"codigo":"83210.004","nombre":"Conductor de mototaxi / Conductora de mototaxi"},{"cod