  ('rol_cuoc', 'Conductores de camionetas y vehículos livianos / Conductoras de camionetas y vehículos livianos', '83230', 'Logística y transporte', 2, true, '{"codigo":"83230","nombre":"Conductores de camionetas y vehículos livianos / Conductoras de camionetas y vehículos livianos","descripcion":"Conducen y mantienen en buen estado vehículos, camionetas y otros vehículos livianos adecuados para el transporte de pasajeros, correo, mercancías, alimentos y bebidas. Se pueden desempeñar en empresas de alimentos, transporte especializado, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"83","nombre":"CONDUCTORES DE VEHÍCULOS Y OPERADORES DE EQUIPOS PESADOS MÓVILES"},"subgrupo":{"codigo":"832","nombre":"Conductores de automóviles, camionetas y motocicletas"},"grupo_primario":{"codigo":"8323","nombre":"Conductores de camionetas y vehículos livianos"}},"funciones":[{"consecutivo":1,"texto":"Conducir y mantener en buen estado automóvil o camioneta (furgoneta) utilizado para el transporte de pasajeros de acuerdo con el servicio contratado."},{"consecutivo":2,"texto":"Conducir y mantener en buen estado el vehículo asignado como camioneta, furgoneta o camiones pequeños utilizados para distribuir correspondencia, documentos de negocios, paquetes, mercancías, alimentos y bebidas de acuerdo protocolos de entrega de documentos y mercancía."},{"consecutivo":3,"texto":"Seguir procedimientos, instrucciones y normas de buenas prácticas de manufactura para el transporte, almacenamiento, distribución y manipulación de alimentos y bebidas; aplicar los planes de contingencia en casos eventuales para garantizar la calidad del producto."},{"consecutivo":4,"texto":"Cobrar las tarifas, pagos por entregas o documentos que certifiquen las entregas, según el servicio contratado."},{"consecutivo":5,"texto":"Operar equipos de telecomunicaciones para informar la ubicación y la disponibilidad del vehículo y seguir las instrucciones del centro de control."},{"consecutivo":6,"texto":"Seguir rutas y coordinar entregas diseñadas por la empresa y notificar las modificaciones."},{"consecutivo":7,"texto":"Ayudar a los pasajeros a abordar o descender del vehículo y cargar el equipaje."},{"consecutivo":8,"texto":"Operar equipos para ayudar el ascenso y descenso pasajeros en situación de discapacidad."},{"consecutivo":9,"texto":"Registrar y mantener información de inventario, recolección y repartos, kilometraje, costo de combustible y problemas presentados."},{"consecutivo":10,"texto":"Mantener en condiciones óptimas de higiene y mecánicas; realizar reparaciones menores al vehículo o llevarlo a mantenimiento."},{"consecutivo":11,"texto":"Ayudar en el cargue y descargue del vehículo la correspondencia, mercancías, alimentos, bebidas, entre otros."},{"consecutivo":12,"texto":"Mantener los documentos en regla del vehículo e informar a las instancias requeridas sobre los documentos reglamentarios."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"83230.001","nombre":"Chofer particular"},{"codigo":"83230.002","nombre":"Conductor de ambulancia / Conductora de ambulancia"},{"codigo":"83230.003","nombre":"Conductor de automóvil / Conductora de automóvil"},{"codigo":"83230.004","nombre":"Conductor de automóvil particular / Conductora de automóvil particular"},{"codigo":"83230.005","nombre":"Conductor de camioneta / Conductora de camioneta"},{"codigo":"83230.006","nombre":"Conductor de camioneta de correos / Conductora de camioneta de correos"},{"codigo":"83230.007","nombre":"Conductor de camioneta de entregas / Conductora de camioneta de entregas"},{"codigo":"83230.008","nombre":"Conductor de camioneta de reparto / Conductora de camioneta de reparto"},{"codigo":"83230.009","nombre":"Conductor de carro blindado / Conductora de carro blindado"},{"codigo":"83230.010","nombre":"Conductor de carroza fúnebre / Conductora 