  ('rol_cuoc', 'Conductores de taxis / Conductoras de taxis', '83240', 'Logística y transporte', 2, true, '{"codigo":"83240","nombre":"Conductores de taxis / Conductoras de taxis","descripcion":"Conducen automóviles para el transporte público de pasajeros, cobrando conforme a tarifas establecidas y servicios contratados. Se pueden desempeñar en empresas de servicio de taxi, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"83","nombre":"CONDUCTORES DE VEHÍCULOS Y OPERADORES DE EQUIPOS PESADOS MÓVILES"},"subgrupo":{"codigo":"832","nombre":"Conductores de automóviles, camionetas y motocicletas"},"grupo_primario":{"codigo":"8324","nombre":"Conductores de taxis"}},"funciones":[{"consecutivo":1,"texto":"Recoger a los pasajeros y llevarlos a sus destinos en taxi según el servicio contratado."},{"consecutivo":2,"texto":"Cobrar la cantidad que indique el taxímetro y las tarifas suplementarias establecidas según normatividad legal vigente."},{"consecutivo":3,"texto":"Mantener contacto con la oficina despachadora de taxis."},{"consecutivo":4,"texto":"Ayudar a los pasajeros a abordar el vehículo y cargar el equipaje, garantizar la seguridad de los usuarios al subir y bajar del vehículo."},{"consecutivo":5,"texto":"Registrar y mantener información de kilometraje, costo de combustible y problemas presentados."},{"consecutivo":6,"texto":"Realizar mantenimiento y reparaciones menores al vehículo o llevarlo al taller de reparación si es necesario."},{"consecutivo":7,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"83240.001","nombre":"Conductor de taxi / Conductora de taxi"},{"codigo":"83240.002","nombre":"Conductor de taxi de aeropuerto / Conductora de taxi de aeropuerto"},{"codigo":"83240.003","nombre":"Taxista"},{"codigo":"83240.004","nombre":"Conductor de taxi intermunicipal / Conductora de taxi intermunicipal"}],"conocimientos":[{"id