  ('rol_cuoc', 'Conductores de buses, microbuses y tranvías / Conductoras de buses, microbuses y tranvías', '83310', 'Logística y transporte', 2, true, '{"codigo":"83310","nombre":"Conductores de buses, microbuses y tranvías / Conductoras de buses, microbuses y tranvías","descripcion":"Conducen buses, microbuses y trenes metropolitanos para transportar pasajeros, equipaje, correo o mercancías en rutas establecidas, realizan reparaciones menores al vehículo. Se pueden desempeñar en empresas de transporte, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"83","nombre":"CONDUCTORES DE VEHÍCULOS Y OPERADORES DE EQUIPOS PESADOS MÓVILES"},"subgrupo":{"codigo":"833","nombre":"Conductores de camiones pesados y buses"},"grupo_primario":{"codigo":"8331","nombre":"Conductores de buses, microbuses y tranvías"}},"funciones":[{"consecutivo":1,"texto":"Conducir y mantener en buen estado el bus asignado para transportar pasajeros, equipaje, correo o mercancías locales o de larga distancia de acuerdo con normatividad de tránsito y transporte terrestre automotor."},{"consecutivo":2,"texto":"Conducir y mantener en buen estado el tranvía, tren u otros sistemas de transporte de pasajeros metropolitano según normatividad técnica y legal vigente."},{"consecutivo":3,"texto":"Operar controles de iluminación, calefacción, ventilación, abrir y cerrar las puertas de los autobuses, vehículos articulados y vagones, según protocolo de seguridad y normatividad de tránsito y transporte terrestre."},{"consecutivo":4,"texto":"Observar y reportar las demoras, problemas mecánicos y accidentes de tránsito, para garantizar un recorrido o viaje seguro."},{"consecutivo":5,"texto":"Seguir los protocolos de seguridad y emergencia en la prestación del servicio de trasporte de pasajeros, carga o mercancías de acuerdo con procedimientos técnicos y normativa de tránsito y transporte."},{"consecutivo":6,"texto":"Recoger las tarifas o verificar tiquete de acuerdo servicio contratado e informar a los pasajeros sobre horarios y paradas."},{"consecutivo":7,"texto":"Realizar reparaciones menores al vehículo y reportan fallas, daños y accidentes a la unidad de control."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"83310.003","nombre":"Conductor de autocar o pullman de pasajeros / Conductora de autocar o pullman de pasajeros"},{"codigo":"83310.004","nombre":"Conductor de bus / Conductora de bus"},{"codigo":"83310.005","nombre":"Conductor de bus de turismo / Conductora de bus de turismo"},{"codigo":"83310.006","nombre":"Conductor de bus escolar / Conductora de bus escolar"},{"codigo":"83310.007","nombre":"Conductor de buseta / Conductora de buseta"},{"codigo":"83310.008","nombre":"Conductor de colectivo / Conductora de colectivo"},{"codigo":"83310.009","nombre":"Operador de metro / Operadora de metro"},{"codigo":"83310.010","nombre":"Conductor de microbús / Conductora de microbús"},{"codigo":"83310.011","nombre":"Conductor de microbús colegial / Conductora de microbús colegial"},{"codigo":"83310.012","nombre":"Conductor de microbús de pasajeros / Conductora de microbús de pasajeros"},{"codigo":"83310.015","nombre":"Operador de tranvía / Operadora de tranvía"},{"codigo":"83310.017","nombre":"Conductor de bus intermunicipal / Conductora de bus intermunicipal"},{"codigo":"83310.018","nombre":"Operador de bus / Operadora de bus"},{"codigo":"83310.019","nombre":"Operador de bus articulado / Operadora de bus articulado"},{"codigo":"83310.020","nombre":"Operador de bus biarticulado / Operadora de bus biarticulado"}],"conocimientos":[{"id":"38","nombre":"Mantenimiento"},{"id":"41","nombre":"Primeros auxilios"},{"id":"85","nombre":"Seguridad y salud en el trabajo"},{"id":"5","nombre":"Servicio al cliente"},{"id":"31","nombre":"Servicios de transporte"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombr