  ('rol_cuoc', 'Operadores de maquinaria agrícola y forestal móvil / Operadoras de maquinaria agrícola y forestal móvil', '83410', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 2, false, '{"codigo":"83410","nombre":"Operadores de maquinaria agrícola y forestal móvil / Operadoras de maquinaria agrícola y forestal móvil","descripcion":"Operan y conducen maquinas motorizadas o equipos móviles para actividades agrícolas, hortícolas, forestales y silvícolas; realizan mantenimiento y reparaciones menores. Se pueden desempeñar en compañías contratistas de maquinaria, empresas de explotación agrícola y forestal, ente otros, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"83","nombre":"CONDUCTORES DE VEHÍCULOS Y OPERADORES DE EQUIPOS PESADOS MÓVILES"},"subgrupo":{"codigo":"834","nombre":"Operadores de maquinaria agrícola móvil y de otras máquinas móviles"},"grupo_primario":{"codigo":"8341","nombre":"Operadores de maquinaria agrícola y forestal móvil"}},"funciones":[{"consecutivo":1,"texto":"Conducir y mantener en buen estado maquinaria y equipo agrícola, tirada por tractor o autopropulsada como sembradoras, combinadas, cosechadoras para arar, plantar, cosechar, embalar u otros fines especiales según manual técnico."},{"consecutivo":2,"texto":"Conducir y mantener en buen estado maquinaria y equipo forestal para usos específicos tirada por tractor o autopropulsada para limpiar la tierra, sembrar, cosechar, transportar los árboles y la madera o realizar otras operaciones forestales según manual técnico."},{"consecutivo":3,"texto":"Preparar, posicionar y disponer las instalaciones para el funcionamiento agrícola y forestal."},{"consecutivo":4,"texto":"Ajustar la velocidad, altura y profundidad de los instrumentos y aparatos utilizados para la explotación agrícola y forestal según especificaciones técnicas."},{"consecutivo":5,"texto":"Operar equipos y accesorios usados utilizados para levantar para sostener, mover, soltar cortar y apilar árboles, troncos o trozas desde el sitio de corte al área de procesamiento y transporte según manual técnico."},{"consecutivo":6,"texto":"Alimentar con árboles talados las máquinas procesadoras para quitar las ramas, la corteza y cortar las piezas en troncos, apilar y cargarlos en camiones según especificaciones técnicas."},{"consecutivo":7,"texto":"Realizar mantenimiento y reparaciones menores a la maquinaria y el equipo e informar al supervisor sobre cualquier daño."},{"consecutivo":8,"texto":"Cumplir el reglamento relacionado con protección ambiental, utilización de los recursos naturales, seguridad, prevención de accidentes según normatividad."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"83410.001","nombre":"Conductor de camión maderero / Conductora de camión maderero"},{"codigo":"83410.002","nombre":"Conductor de máquina forestal / Conductora de máquina forestal"},{"codigo":"83410.003","nombre":"Maquinista agrícola"},{"codigo":"83410.004","nombre":"Operador de combinada / Operadora de combinada"},{"codigo":"83410.005","nombre":"Operador de cosechadora / Operadora de cosechadora"},{"codigo":"83410.006","nombre":"Operador de equipo de escarificación / Operadora de equipo de escarificación"},{"codigo":"83410.007","nombre":"Operador de máquina agrícola / Operadora de máquina agrícola"},{"codigo":"83410.008","nombre":"Operador de máquina cosechadora / Operadora de máquina cosechadora"},{"codigo":"83410.009","nombre":"Operador de máquina desmotadora de algodón / Operadora de máquina desmotadora de algodón"},{"codigo":"83410.010","nombre":"Operador de máquina taladora de arboles / Operadora de máquina taladora de arboles"},{"codigo":"83410.011","nombre":"Operador de maquinaria agrícola / Operadora de maquinaria agrícola"},{"codigo":"83410.012","nombre":"Operador de maquinaria de explotación forestal / Operadora de maquinari