  ('rol_cuoc', 'Operadores de grúas, aparatos elevadores y afines / Operadoras de grúas, aparatos elevadores y afines', '83430', 'Logística y transporte', 2, false, '{"codigo":"83430","nombre":"Operadores de grúas, aparatos elevadores y afines / Operadoras de grúas, aparatos elevadores y afines","descripcion":"Operan y supervisan el funcionamiento de grúas fijas o móviles, dragas y otros aparatos elevadores para levantar, mover, posicionar o ubicar maquinaria, equipo y otros materiales de gran tamaño de acuerdo con el plan operativo y normativa. Se pueden desempeñar en constructoras, compañías de carga, ferroviarias y portuarias, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"83","nombre":"CONDUCTORES DE VEHÍCULOS Y OPERADORES DE EQUIPOS PESADOS MÓVILES"},"subgrupo":{"codigo":"834","nombre":"Operadores de maquinaria agrícola móvil y de otras máquinas móviles"},"grupo_primario":{"codigo":"8343","nombre":"Operadores de grúas, aparatos elevadores y afines"}},"funciones":[{"consecutivo":1,"texto":"Operar y supervisar el funcionamiento de grúas móviles o fijas, haciendo bajar y subir brazos y plumas para elevar, mover, posicionar o colocar equipos y materiales."},{"consecutivo":2,"texto":"Operar y supervisar el funcionamiento de grúas móviles y de torre para levantar, mover, ubicar equipo, materiales y trabajadores en los sitios de construcción, astilleros, instalaciones industriales, minas, puertos y lugares similares."},{"consecutivo":3,"texto":"Operar y supervisar teleféricos y aparatos similares según manual de operación."},{"consecutivo":4,"texto":"Operar y supervisar grúas locomotoras u otra maquinaria para remolcar o arrastrar mediante cables, balsas o barcazas con mercancías, pasajeros y vehículos en travesías cortas o estaciones ferroviarias."},{"consecutivo":5,"texto":"Operar y supervisar la maquinaria para abrir y cerrar puentes levadizos y esclusas que permiten la circulación fluvial y por carretera según manual de operación."},{"consecutivo":6,"texto":"Operar y supervisar el funcionamiento de grúas equipadas con accesorios de dragados para drenar vías fluviales y otras zonas."},{"consecutivo":7,"texto":"Operar y supervisar grúas instaladas sobre embarcaciones o barcazas para levantar, mover y colocar equipos y materiales."},{"consecutivo":8,"texto":"Operar y supervisar equipo y bandas transportadoras para trasladar materiales, desde los vehículos de transporte a los elevadores, silos y otras áreas de almacenamiento."},{"consecutivo":9,"texto":"Realizar trabajos de mantenimiento rutinario como limpieza y lubricación de las grúas, según manuales técnicos."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"83430.001","nombre":"Enganchador de jaula de extracción de minas / Enganchadora de jaula de extracción de minas"},{"codigo":"83430.002","nombre":"Maquinista en petróleo y gas"},{"codigo":"83430.003","nombre":"Operador de aparatos de izar / Operadora de aparatos de izar"},{"codigo":"83430.004","nombre":"Operador de banda transportadora / Operadora de banda transportadora"},{"codigo":"83430.005","nombre":"Operador de cabrestante / Operadora de cabrestante"},{"codigo":"83430.006","nombre":"Operador de cabrestante elevador / Operadora de cabrestante elevador"},{"codigo":"83430.007","nombre":"Operador de cabria de minas / Operadora de cabria de minas"},{"codigo":"83430.008","nombre":"Operador de cabria para construcción / Operadora de cabria para construcción"},{"codigo":"83430.009","nombre":"Operador de canasta elevadora / Operadora de canasta elevadora"},{"codigo":"83430.010","nombre":"Operador de equipo de arrastre portuario / Operadora de equipo de arrastre portuario"},{"codigo":"83430.011","nombre":"Operador de equipo de transporte de graneles / Operadora de equipo de transporte de graneles"},{"codigo":"83430.012","nombre":"Operador de esclusa / Operadora 