  ('rol_cuoc', 'Operadores de montacargas / Operadoras de montacargas', '83440', 'Logística y transporte', 2, false, '{"codigo":"83440","nombre":"Operadores de montacargas / Operadoras de montacargas","descripcion":"Conducen, operan y supervisan el funcionamiento de montacargas, vehículos de elevación y equipos utilizados para cargar y descargar, transportar, levantar y apilar mercancías. Realizan mantenimiento y reparaciones menores. Se pueden desempeñar en compañías de transporte, almacenamiento y movimiento de carga, compañías manufactureras, establecimientos de comercio, bodegas, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"83","nombre":"CONDUCTORES DE VEHÍCULOS Y OPERADORES DE EQUIPOS PESADOS MÓVILES"},"subgrupo":{"codigo":"834","nombre":"Operadores de maquinaria agrícola móvil y de otras máquinas móviles"},"grupo_primario":{"codigo":"8344","nombre":"Operadores de montacargas"}},"funciones":[{"consecutivo":1,"texto":"Conducir, operar y supervisar el funcionamiento de montacargas, vehículos de elevación y equipos utilizados para cargar y descargar, transportar, levantar, apilar mercancías y paletas o estibas cargadas, en estaciones terminales, instalaciones portuarias, almacenes, bodegas, fábricas y otros establecimientos."},{"consecutivo":2,"texto":"Colocar dispositivos elevadores debajo, encima o alrededor de paletas o estibas, fardos y cajas cargadas y sujetar firmemente los materiales o productos para el transporte a lugares designados."},{"consecutivo":3,"texto":"Llevar y mantener registros de trabajos realizados y del uso de los vehículos y equipos."},{"consecutivo":4,"texto":"Inspeccionar y supervisar el funcionamiento de los vehículos y equipos para detectar averías o fallas y realizarles el mantenimiento respectivo."},{"consecutivo":5,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"83440.001","nombre":"O