  ('rol_cuoc', 'Operadores de embarcaciones menores / Operadoras de embarcaciones menores', '83502', 'Logística y transporte', 2, false, '{"codigo":"83502","nombre":"Operadores de embarcaciones menores / Operadoras de embarcaciones menores","descripcion":"Operan botes o pequeñas embarcaciones tales como remolcadores, lanchas, entre otros para transportar pasajeros o carga, remolcar artefactos navales menores; realizan mantenimiento y reparaciones menores. Se pueden desempeñar en compañías marítimas o fluviales de servicio turístico, de transporte, compañías madereras, puertos o muelles, empresas de dragados, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"8","nombre":"OPERADORES DE INSTALACIONES Y MÁQUINAS Y ENSAMBLADORES"},"subgrupo_principal":{"codigo":"83","nombre":"CONDUCTORES DE VEHÍCULOS Y OPERADORES DE EQUIPOS PESADOS MÓVILES"},"subgrupo":{"codigo":"835","nombre":"Marineros de cubierta y afines"},"grupo_primario":{"codigo":"8350","nombre":"Marineros de cubierta y afines"}},"funciones":[{"consecutivo":1,"texto":"Operar botes motorizados, lanchas, pequeños transbordadores, remolcadores y otras embarcaciones similares para transportar pasajeros o carga."},{"consecutivo":2,"texto":"Seleccionar, coordinar y supervisar el personal a su cargo en pequeñas embarcaciones."},{"consecutivo":3,"texto":"Velar por la aplicación de normas de seguridad en operaciones de remolque, trasporte de pasajeros o carga a bordo de pequeñas embarcaciones."},{"consecutivo":4,"texto":"Realizar mantenimiento y reparaciones menores a los barcos y equipo a bordo como motores, aparejos, extinguidores de incendio, salvavidas, entre otros de acuerdo con manual técnico."},{"consecutivo":5,"texto":"Administrar la embarcación, sus recursos y la tripulación."},{"consecutivo":6,"texto":"Cumplir con las normas y regulaciones marítimas de las entidades nacionales correspondientes."},{"consecutivo":7,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"83502.00