  ('rol_cuoc', 'Personal de servicio doméstico', '91110', 'Servicios Personales y a la Comunidad', 1, false, '{"codigo":"91110","nombre":"Personal de servicio doméstico","descripcion":"Limpian residencias privadas, lavan y planchan ropa de cama y similares, tienden camas, compran provisiones y artículos para el hogar; preparan y cocinan alimentos en casas de familia Entre otras labores domésticas. Se pueden desempeñar en casas de familia, compañías de servicio de aseo, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"91","nombre":"PERSONAL DOMESTICO Y DE ASEO"},"subgrupo":{"codigo":"911","nombre":"Personal doméstico, aseadores de hoteles, oficinas y otros establecimientos"},"grupo_primario":{"codigo":"9111","nombre":"Personal de servicio doméstico"}},"funciones":[{"consecutivo":1,"texto":"Barrer, trapear y encerar pisos de instalaciones domésticas."},{"consecutivo":2,"texto":"Limpiar, brillar y sellar, puertas, muebles, ventanas y otros accesorios de instalaciones domésticas."},{"consecutivo":3,"texto":"Lavar, planchar y remendar lencería, ropa de cama y prendas de uso personal."},{"consecutivo":4,"texto":"Preparar, cocinar y servir alimentos y bebidas en instalaciones domésticas."},{"consecutivo":5,"texto":"Lavar vajillas y utensilios de cocina en instalaciones domésticas."},{"consecutivo":6,"texto":"Lavar, desinfectar y desodorizar cocinas, cuartos de baño, muebles y enseres en casas de familia."},{"consecutivo":7,"texto":"Tender camas, cambiar sábanas, poner toallas limpias y artículos de tocador en instalaciones domésticas."},{"consecutivo":8,"texto":"Desempolvar y aspirar muebles, alfombras, tapetes, cortinas y tapizados en instalaciones domésticas."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"91110.001","nombre":"Aseador / Aseadora"},{"codigo":"91110.002","nombre":"Aseador doméstico / Aseadora doméstica"},{"codigo":"91110.0