  ('rol_cuoc', 'Aseadores de oficinas, hoteles y otros establecimientos / Aseadoras de oficinas, hoteles y otros establecimientos', '91120', 'Servicios Personales y a la Comunidad', 1, false, '{"codigo":"91120","nombre":"Aseadores de oficinas, hoteles y otros establecimientos / Aseadoras de oficinas, hoteles y otros establecimientos","descripcion":"Realizan diversas tareas de limpieza con el fin de mantener limpios y ordenados áreas comunes, pasillos, salas de espera, zonas de producción, locales, instalaciones comerciales, oficinas, habitaciones, interiores de ascensores, y demás. Se pueden desempeñar en hoteles, hospitales, institutos de educación, oficinas, compañías de servicio de aseo, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"91","nombre":"PERSONAL DOMESTICO Y DE ASEO"},"subgrupo":{"codigo":"911","nombre":"Personal doméstico, aseadores de hoteles, oficinas y otros establecimientos"},"grupo_primario":{"codigo":"9112","nombre":"Aseadores de oficinas, hoteles y otros establecimientos"}},"funciones":[{"consecutivo":1,"texto":"Trasladar lencería sucia de las habitaciones a zonas de lavandería dentro de instalaciones de alojamiento."},{"consecutivo":2,"texto":"Recoger ropa particular de clientes para su higienización."},{"consecutivo":3,"texto":"Limpiar, descongelar y aprovisionar minibares dentro de habitaciones de alojamiento."},{"consecutivo":4,"texto":"Limpiar áreas públicas en hoteles y establecimientos de alojamiento."},{"consecutivo":5,"texto":"Reportar daños o averías y objetos olvidados al interior de las instalaciones."},{"consecutivo":6,"texto":"Arreglar tendidos de camas, poner toallas limpias y artículos de tocador, así como velar porque las habitaciones se encuentren provistas de estos implementos."},{"consecutivo":7,"texto":"Limpiar, preparar y mantener las habitaciones de acuerdo con los estándares técnicos."},{"consecutivo":8,"texto":"Limpiar y sanitizar equipos manuales y mecánicos de industrias."},{"consecutivo":9,"texto":"Apoyar el montaje de salones para eventos según requerimientos."},{"consecutivo":10,"texto":"Acondicionar y mezclar los implementos de aseo requeridos en el desarrollo de sus actividades."},{"consecutivo":11,"texto":"Limpiar y desinfectar paredes, pisos y otros divisorios de áreas críticas de instalaciones."},{"consecutivo":12,"texto":"Barrer, aspirar y trapear pisos de las instalaciones."},{"consecutivo":13,"texto":"Encerar, brillar y sellar pisos de las instalaciones."},{"consecutivo":14,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"91120.001","nombre":"Aseador de equipo industrial / Aseadora de equipo industrial"},{"codigo":"91120.002","nombre":"Aseador de establecimientos industriales / Aseadora de establecimientos industriales"},{"codigo":"91120.003","nombre":"Aseador de fabrica / Aseadora de fabrica"},{"codigo":"91120.004","nombre":"Aseador de hospital / Aseadora de hospital"},{"codigo":"91120.005","nombre":"Aseador de hotel / Aseadora de hotel"},{"codigo":"91120.006","nombre":"Aseador de oficina / Aseadora de oficina"},{"codigo":"91120.007","nombre":"Aseador de restaurante / Aseadora de restaurante"},{"codigo":"91120.008","nombre":"Aseador de sistemas de ventilación / Aseadora de sistemas de ventilación"},{"codigo":"91120.009","nombre":"Aseador de talleres / Aseadora de talleres"},{"codigo":"91120.010","nombre":"Aseador especializado / Aseadora especializada"},{"codigo":"91120.011","nombre":"Auxiliar de aseo"},{"codigo":"91120.012","nombre":"Auxiliar de aseo y cafetería"},{"codigo":"91120.013","nombre":"Auxiliar de aseo áreas comunes industria petrolera"},{"codigo":"91120.014","nombre":"Auxiliar de habitaciones"},{"codigo":"91120.015","nombre":"Auxiliar de servicios hoteleros"},{"codigo":"91120.016","nombre":"Auxiliar de limpieza y sanitización"},{"codigo":"91120.017","nombre":"Auxiliar de sanitización"},{"codigo":"91120.018","nombre":"Auxiliar de servicios g