  ('rol_cuoc', 'Lavanderos y planchadores manuales / Lavanderas y planchadoras manuales', '91210', 'Servicios Personales y a la Comunidad', 1, false, '{"codigo":"91210","nombre":"Lavanderos y planchadores manuales / Lavanderas y planchadoras manuales","descripcion":"Clasifican prendas sucias de acuerdo con su estado y material; lavan, planchan y almidonan a mano, quitan manchas y limpian en seco diversos tipos de prendas de vestir, lencería, ropa de cama y otros artículos de tela o tejido; organizan, empacan prendas lavadas y las revisan para garantizar que cumplan los requisitos de limpieza y planchado. Se pueden desempeñar en lavanderías, tintorerías, lavanderías de hoteles y hospitales, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"91","nombre":"PERSONAL DOMESTICO Y DE ASEO"},"subgrupo":{"codigo":"912","nombre":"Limpiadores de vehículos, ventanas, ropa y otra limpieza a mano"},"grupo_primario":{"codigo":"9121","nombre":"Lavanderos y planchadores manuales"}},"funciones":[{"consecutivo":1,"texto":"Lavar, planchar y arreglar a mano lencería, ropa de cama y prendas de uso personal."},{"consecutivo":2,"texto":"Utilizar planchas de vapor manual para alisar prendas y retocar terminaciones."},{"consecutivo":3,"texto":"Organizar y empacar prendas de vestir y accesorios domésticos en estanterías o colgarlos en perchas en espera de su entrega o recolección."},{"consecutivo":4,"texto":"Limpiar a mano o empleando soluciones químicas toda clase de prendas de vestir, telas o tejidos, de cuero o piel y artículos similares."},{"consecutivo":5,"texto":"Lavar y almidonar las prendas que así lo requieran."},{"consecutivo":6,"texto":"Recoger ropa particular de clientes para su higienización."},{"consecutivo":7,"texto":"Revisar prendas ya lavadas para garantizar que están correctamente lavadas, secas y planchadas."},{"consecutivo":8,"texto":"Registrar prendas dañadas y las que no han sido lavadas adecuadamente."},{"consecutivo":9,"texto":"Marcar prendas con etiquetas y pegarles facturas."},{"consecutivo":10,"texto":"Planchar de forma manual prendas finas o delicadas."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"91210.001","nombre":"Almidonador a mano en lavandería / Almidonadora a mano en lavandería"},{"codigo":"91210.002","nombre":"Cepillador de ropa a mano en lavandería / Cepilladora de ropa a mano en lavandería"},{"codigo":"91210.003","nombre":"Empleado de lavandería / Empleada de lavandería"},{"codigo":"91210.004","nombre":"Lavandero / Lavandera"},{"codigo":"91210.005","nombre":"Lavandero a mano / Lavandera a mano"},{"codigo":"91210.006","nombre":"Lavandero a mano lavandería / Lavandera a mano lavandería"},{"codigo":"91210.007","nombre":"Limpiador en seco a mano / Limpiadora en seco a mano"},{"codigo":"91210.008","nombre":"Auxiliar de planchado"},{"codigo":"91210.009","nombre":"Planchador / Planchadora"},{"codigo":"91210.010","nombre":"Planchador a mano / Planchadora a mano"},{"codigo":"91210.011","nombre":"Planchador doméstico / Planchadora doméstica"},{"codigo":"91210.012","nombre":"Planchador de lavandería / Planchadora de lavandería"}],"conocimientos":[{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"19","nombre":"Selección de equipo"}],"ocupaciones_afines":[{"codigo":"81540","nombre":"Operadores de máquinas de blanqueamiento, teñido y limpieza de tejidos / Operadoras de máquinas de blanqueamiento, teñido y limpieza de tejidos"},{"codigo":"81570","nombre":"Operadores de máquinas de lavandería / Operadoras de máquinas de lavandería"},{"codigo":"91110","nombre":"Personal de servicio doméstico"},{"codigo":"91290","nombre":"Otro