  ('rol_cuoc', 'Lavadores de vehículos / Lavadoras de vehículos', '91220', 'Servicios Personales y a la Comunidad', 1, false, '{"codigo":"91220","nombre":"Lavadores de vehículos / Lavadoras de vehículos","descripcion":"Lavan, aspiran, enceran y pulen el exterior y el interior de los vehículos, de forma manual o con maquinaria liviana, se pueden desempeñar en lavaderos de carros, talleres automotrices, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"91","nombre":"PERSONAL DOMESTICO Y DE ASEO"},"subgrupo":{"codigo":"912","nombre":"Limpiadores de vehículos, ventanas, ropa y otra limpieza a mano"},"grupo_primario":{"codigo":"9122","nombre":"Lavadores de vehículos"}},"funciones":[{"consecutivo":1,"texto":"Registrar la entrada y salida de vehículos a lavaderos de carros e indicar la ubicación de los carros en el sitio correspondiente."},{"consecutivo":2,"texto":"Limpiar, lavar, encerar, lustrar, pulir automóviles y otros vehículos, a mano o usando herramientas de mano eléctricas."},{"consecutivo":3,"texto":"Aspirar el interior de los vehículos y limpiar en seco alfombras y tapicerías."},{"consecutivo":4,"texto":"Aplicar productos de limpieza para quitar manchas de exteriores e interiores de vehículos."},{"consecutivo":5,"texto":"Lavar y pulir ventanas de vehículos."},{"consecutivo":6,"texto":"Vaciar y limpiar compartimentos de vehículos."},{"consecutivo":7,"texto":"Lavar neumáticos, rines, arcos de ruedas y ennegrecer neumáticos de vehículos."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"91220.001","nombre":"Aseador de aeronaves / Aseadora de aeronaves"},{"codigo":"91220.002","nombre":"Lavador de cristales de vehículos / Lavadora de cristales de vehículos"},{"codigo":"91220.003","nombre":"Lavador de aviones / Lavadora de aviones"},{"codigo":"91220.004","nombre":"Lavador de barcos / Lavadora de barcos"},{"codigo":"91220.005","nombre":"L