  ('rol_cuoc', 'Limpiadores de ventanas y vitrinas / Limpiadoras de ventanas y vitrinas', '91230', 'Servicios Personales y a la Comunidad', 1, false, '{"codigo":"91230","nombre":"Limpiadores de ventanas y vitrinas / Limpiadoras de ventanas y vitrinas","descripcion":"Lavan y limpian vidrios, cristales, ventanas, vitrinas, escaparates, al igual que otros accesorios de vidrio al interior y exterior de edificaciones utilizando equipo y herramientas manuales. Se pueden desempeñar en compañías de servicios de limpieza, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"91","nombre":"PERSONAL DOMESTICO Y DE ASEO"},"subgrupo":{"codigo":"912","nombre":"Limpiadores de vehículos, ventanas, ropa y otra limpieza a mano"},"grupo_primario":{"codigo":"9123","nombre":"Limpiadores de ventanas y vitrinas"}},"funciones":[{"consecutivo":1,"texto":"Lavar ventanas u otras superficies de vidrio o cristal con agua o soluciones de distintos tipos en el interior y exterior de las edificaciones."},{"consecutivo":2,"texto":"Utilizar escaleras, andamios colgantes, sillas de contramaestre, cestas o canastas hidráulicas de camión y otros equipos para alcanzar y limpiar ventanas de edificios de varios pisos."},{"consecutivo":3,"texto":"Seleccionar instrumentos adecuados para la limpieza y pulido de vidrios y cristales."},{"consecutivo":4,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"91230.001","nombre":"Lavador de ventanas / Lavadora de ventanas"},{"codigo":"91230.002","nombre":"Lavador de vitrinas en almacenes / Lavadora de vitrinas en almacenes"},{"codigo":"91230.003","nombre":"Limpiador de ventanas / Limpiadora de ventanas"}],"conocimientos":[{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"2","nombre":"Escucha activa"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"71330","nombre":"Limpiadores de fachadas y deshollinadores / Limpiadoras de fachadas y deshollinadores"},{"codigo":"91120","nombre":"Aseadores de oficinas, hoteles y otros establecimientos / Aseadoras de oficinas, hoteles y otros establecimientos"},{"codigo":"91220","nombre":"Lavadores de vehículos / Lavadoras de vehículos"}],"area_principal":{"sigla":"SEPC","nombre":"Servicios Personales y a la Comunidad"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"9123","ciuo08_obs":"Denominaciones completas","cno_codigo":"6632*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Otro personal de limpieza no clasificados en otras ocupaciones / Otra personal de limpieza no clasificados en otras ocupaciones', '91290', 'Servicios Personales y a la Comunidad', 1, false, '{"codigo":"91290","nombre":"Otro personal de limpieza no clasificados en otras ocupaciones / Otra personal de limpieza no clasificados en otras ocupaciones","descripcion":"Esta ocupación abarca a Otro personal de limpieza no clasificados en otras ocupaciones en el Subgrupo 912 Limpiadores de vehículos, ventanas, ropa y otra limpieza a mano. Por ejemplo, incluye aquellos que lavan y limpian exteriores de edificaciones, alfombras, moquetas, chimeneas, piscinas, equipos industriales, sistemas de ventilación, y otras superficies, utilizando equipos y técnicas manuales. Se pueden desempeñar en compañías de servicios de limpieza especializada, industrias, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"91","nombre":"PERSONAL DOMESTICO Y DE ASEO"},"subgrupo":{"codigo":"912","nombre":"Limpiadores de vehículos, ventanas, ropa y otra limpieza a mano"},"grupo_primario":{"codigo":"9129","nombre":"Otro personal de limpieza no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Utilizar máquinas livianas para limpieza y lavado de alfombras, tapetes, muebles y tapizados en el sitio donde se encuentran instalados o en el establecimiento de limpieza."},{"consecutivo":2,"texto":"Limpiar chimeneas, utilizando herramientas manuales y aspiradoras."},{"consecutivo":3,"texto":"Limpiar ductos, respiraderos y filtros en residencias y edificaciones comerciales utilizando herramientas manuales y aspiradoras."},{"consecutivo":4,"texto":"Tratar alfombras con productos químicos desodorantes y repelentes de suciedad y aplicarles tratamientos."},{"consecutivo":5,"texto":"Seleccionar, aplicar y disponer elementos de limpieza para eliminar manchas de alfombras, tapetes, muebles y tapizados."},{"consecutivo":6,"texto":"Limpiar paredes de piedra, superficies de metal y paneles utilizando equipos de limpieza con agua a alta presión y disolventes."},{"consecutivo":7,"texto":"Aplicar productos químicos y métodos de limpieza con líquidos o aire a alta presión para eliminar microorganismos de los sistemas de circulación y filtración de agua."},{"consecutivo":8,"texto":"Utilizar aspiradoras húmedas y otros equipos de succión para eliminar sarro, suciedad acumulada y otros depósitos incrustados en las paredes de piscinas, componentes de torres de refrigeración y desagües."},{"consecutivo":9,"texto":"Lavar fachadas, tanques y equipo industrial utilizando equipos a base vapor o agua."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"91290.001","nombre":"Houseman"},{"codigo":"91290.002","nombre":"Lavador de alfombras / Lavadora de alfombras"},{"codigo":"91290.003","nombre":"Lavador de tapicería / Lavadora de tapicería"},{"codigo":"91290.004","nombre":"Limpiador de alfombras / Limpiadora de alfombras"},{"codigo":"91290.005","nombre":"Limpiador de cunetas / Limpiadora de cunetas"},{"codigo":"91290.006","nombre":"Limpiador de drenaje / Limpiadora de drenaje"},{"codigo":"91290.007","nombre":"Limpiador de graffitis / Limpiadora de graffitis"},{"codigo":"91290.008","nombre":"Limpiador de piscinas / Limpiadora de piscinas"},{"codigo":"91290.009","nombre":"Limpiador de torres de refrigeración / Limpiadora de torres de refrigeración"},{"codigo":"91290.010","nombre":"Limpiador en seco de alfombras / Limpiadora en seco de alfombras"},{"codigo":"91290.011","nombre":"Operario de máquinas de agua a presión / Operaria de máquinas de agua a presión"},{"codigo":"91290.012","nombre":"Auxiliar de mantenimiento de piscinas"},{"codigo":"91290.013","nombre":"Piscinero / Piscinera"}],"conocimientos":[{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"91110","nombre":"Personal de servicio doméstico"},{"codigo":"91120","nombre":"Aseadores de oficinas, hoteles y otros establecimientos / Aseadoras de oficinas, hoteles y otros establecimientos"}],"area_principal":{"sigla":"SEPC","nombre":"Servicios Personales y a la Comunidad"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"9129","ciuo08_obs":"Denominaciones completas","cno_codigo":"6632*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"6645*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Obreros y peones de explotaciones agrícolas / Obreras y peonas de explotaciones agrícolas', '92110', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 1, false, '{"codigo":"92110","nombre":"Obreros y peones de explotaciones agrícolas / Obreras y peonas de explotaciones agrícolas","descripcion":"Preparan terrenos, plantan, siembran, cultivan y recogen cosechas, limpian, fumigan y cuidan los cultivos, además apoyan otras labores sencillas y rutinarias relacionadas con el mantenimiento de infraestructura y demás en explotaciones agrícola. Se pueden desempeñar en fincas, parcelas, haciendas, hatos y granjas, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"92","nombre":"OBREROS Y PEONES AGROPECUARIOS, PESQUEROS Y FORESTALES"},"subgrupo":{"codigo":"921","nombre":"Obreros y peones agropecuarios, pesqueros y forestales"},"grupo_primario":{"codigo":"9211","nombre":"Obreros y peones de explotaciones agrícolas"}},"funciones":[{"consecutivo":1,"texto":"Preparar suelos, cavar y abrir zanjas para fertilizar, sembrar y recoger cosechas."},{"consecutivo":2,"texto":"Cargar y descargar suministros, productos y otros materiales agrícolas."},{"consecutivo":3,"texto":"Clasificar, seleccionar, agrupar y envasar frutas, vegetales y demás productos agrícolas en recipientes."},{"consecutivo":4,"texto":"Revisar y detectar plagas en los cultivos y erradicarlas atendiendo instrucciones prestablecidas bajo el control de expertos."},{"consecutivo":5,"texto":"Rastrillar, levantar y apilar paja, heno y materiales similares."},{"consecutivo":6,"texto":"Recoger frutas, frutos secos, vegetales y otros cultivos."},{"consecutivo":7,"texto":"Retirar malezas, podar, aporcar, deschuponar, entresacar, entre otras labores, de acuerdo con la programación o prácticas en un cultivo."},{"consecutivo":8,"texto":"Almacenar productos agrícolas y realizar cierto grado de elaboración primaria."},{"consecutivo":9,"texto":"Realizar labores de postcosecha como clasificar, seleccionar, manipular, almacenar y empacar productos agrícolas."},{"consecutivo":10,"texto":"Almacenar cosechas, semillas y otros productos agrícolas, al igual que equipos y herramientas en los sitios establecidos."},{"consecutivo":11,"texto":"Escarbar, regar y desherbar cultivos a mano o utilizando herramientas de uso manual."},{"consecutivo":12,"texto":"Sembrar y cosechar a mano toda clase de cultivos de campo."},{"consecutivo":13,"texto":"Efectuar reparaciones menores en instalaciones, edificaciones, equipos, cercas y vallas de uso agrícola."},{"consecutivo":14,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"92110.001","nombre":"Alzador de fruto / Alzadora de fruto"},{"codigo":"92110.002","nombre":"Ayudante agrícola"},{"codigo":"92110.003","nombre":"Bagacero / Bagacera"},{"codigo":"92110.004","nombre":"Bracero agrícola / Bracera agrícola"},{"codigo":"92110.005","nombre":"Clasificador de frutas agrícola / Clasificadora de frutas agrícola"},{"codigo":"92110.006","nombre":"Clasificador de grano / Clasificadora de grano"},{"codigo":"92110.007","nombre":"Colero / Colera"},{"codigo":"92110.008","nombre":"Cortero / Cortera"},{"codigo":"92110.009","nombre":"Cortador de caña de azúcar / Cortadora de caña de azúcar"},{"codigo":"92110.010","nombre":"Cosechador / Cosechadora"},{"codigo":"92110.011","nombre":"Cosechero / Cosechera"},{"codigo":"92110.012","nombre":"Cuadrillero agrícola / Cuadrillera agrícola"},{"codigo":"92110.013","nombre":"Descuajador de plantas / Descuajadora de plantas"},{"codigo":"92110.014","nombre":"Escogedor de café en beneficiadero / Escogedora de café en beneficiadero"},{"codigo":"92110.015","nombre":"Estaquillador y alineador / Estaquilladora y alineadora"},{"codigo":"92110.016","nombre":"Garruchero / Garruchera"},{"codigo":"92110.017","nombre":"Jornalero agrícola / Jornalera agrícola"},{"codigo":"92110.018","nombre":"Obrero agrícola / Obrera agríco