  ('rol_cuoc', 'Obreros y peones de explotaciones ganaderas / Obreras y peonas de explotaciones ganaderas', '92120', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 1, false, '{"codigo":"92120","nombre":"Obreros y peones de explotaciones ganaderas / Obreras y peonas de explotaciones ganaderas","descripcion":"Realizan labores sencillas y rutinarias relacionadas con la producción de animales incluidas las aves de corral e insectos, igualmente, colaboran con el mantenimiento de infraestructura pecuaria. Se pueden desempeñar en fincas, parcelas, haciendas, hatos, granjas, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"92","nombre":"OBREROS Y PEONES AGROPECUARIOS, PESQUEROS Y FORESTALES"},"subgrupo":{"codigo":"921","nombre":"Obreros y peones agropecuarios, pesqueros y forestales"},"grupo_primario":{"codigo":"9212","nombre":"Obreros y peones de explotaciones ganaderas"}},"funciones":[{"consecutivo":1,"texto":"Mantener en buenas condiciones de estado y limpieza establos, corrales, graneros, canales, cercados, broches y galpones."},{"consecutivo":2,"texto":"Ayudar a mantener el ganado con buena salud y en condiciones de bienestar adecuadas."},{"consecutivo":3,"texto":"Rastrillar, levantar, apilar y almacenar heno, paja y otros tipos de alimentación y lecho para los animales."},{"consecutivo":4,"texto":"Clasificar, seleccionar y envasar productos de origen pecuario en recipientes, de acuerdo con especificaciones técnicas."},{"consecutivo":5,"texto":"Realizar reparaciones menores en instalaciones, edificaciones, equipos y cercas de uso pecuario."},{"consecutivo":6,"texto":"Recoger huevos en explotaciones pecuarias y colocarlos en incubadoras de acuerdo con especificaciones técnicas."},{"consecutivo":7,"texto":"Cargar y descargar animales, suministros y productos pecuarios de acuerdo con instrucciones."},{"consecutivo":8,"texto":"Alimentar, dar de beber, cuidar aves, ganado y otras especies menores de origen pecuario."},{"consecutivo":9,"texto":"Cuidar animales de origen pecuario, vigilar, dar cuenta de su condición e informar sobre su estado."},{"consecutivo":10,"texto":"Ayudar a reunir, arrear y separar el ganado para llevar a cabo el ordeño, la esquila, el transporte o el sacrificio en distintos lugares."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"92120.001","nombre":"Arriero / Arriera"},{"codigo":"92120.002","nombre":"Auxiliar de caballeriza"},{"codigo":"92120.003","nombre":"Ayudante de establos"},{"codigo":"92120.004","nombre":"Ayudante pecuario de ganadería / Ayudante pecuaria de ganadería"},{"codigo":"92120.005","nombre":"Boyero / Boyera"},{"codigo":"92120.006","nombre":"Caballerizo / Caballeriza"},{"codigo":"92120.007","nombre":"Obrero de establos / Obrera de establos"},{"codigo":"92120.008","nombre":"Obrero de explotación ganadera / Obrera de explotación ganadera"},{"codigo":"92120.009","nombre":"Ordeñador a mano / Ordeñadora a mano"},{"codigo":"92120.010","nombre":"Palafrenero / Palafrenera"},{"codigo":"92120.011","nombre":"Peón de productos lácteos / Peona de productos lácteos"}],"conocimientos":[{"id":"98","nombre":"Producción agrícola y pecuaria"}],"destrezas":[{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"61211","nombre":"Criadores de animales (excepto aves de corral) / Criadoras de animales (excepto aves de corral)"},{"codigo":"61221","nombre":"Avicultores / Avicultoras"},{"codigo":"61290","nombre":"Criadores y trabajadores pecuarios calificados, avicultores y criadores de insectos no clasificados en otras ocupaciones / Criadoras y trabajadoras pecuarias calificadas, avicultoras y criadoras de insectos no clasificadas en otras ocupaciones"},{"codigo":"61300","nombre":"Productores y trabajadores calificados de explotaciones agropecuarias mixtas cuya producción se destina al mercado / Productoras y trabajadoras calificadas de explotaciones agropecuarias mixtas cuya producción se destina al mercado"}],"area_principal":{"sigla":"AGVE","nombre":"Agropecuario, silvicultura, pesca, acuicultura y veterinaria"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"9212*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"7613*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Obreros y peones de explotaciones agropecuarias / Obreras y peonas de explotaciones agropecuarias', '92130', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 1, false, '{"codigo":"92130","nombre":"Obreros y peones de explotaciones agropecuarias / Obreras y peonas de explotaciones agropecuarias","descripcion":"Realizan tareas sencillas y habituales en explotaciones dedicadas tanto a la producción agrícola y pecuaria como limpieza, preparación de terrenos, siembra, cosecha, recolección, cuidado de cultivos, animales, actividades de criadero y mantenimiento a la infraestructura de uso agropecuaria. Se pueden desempeñar en hatos, fincas, granjas y haciendas, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"92","nombre":"OBREROS Y PEONES AGROPECUARIOS, PESQUEROS Y FORESTALES"},"subgrupo":{"codigo":"921","nombre":"Obreros y peones agropecuarios, pesqueros y forestales"},"grupo_primario":{"codigo":"9213","nombre":"Obreros y peones de explotaciones agropecuarias"}},"funciones":[{"consecutivo":1,"texto":"Limpiar, palear, cavar zanjas o hacer surcos para fines agrícolas y pecuarios."},{"consecutivo":2,"texto":"Rastrillar, levantar y apilar paja, heno y otros materiales similares que son utilizados en la producción agrícola y pecuaria."},{"consecutivo":3,"texto":"Realizar reparaciones menores en edificaciones, equipos, cercas e instalaciones de uso agrícola y pecuario."},{"consecutivo":4,"texto":"Realizar faenas y labores culturales relacionadas con la producción agrícola y pecuaria."},{"consecutivo":5,"texto":"Cargar, descargar, mantener y cuidar el inventario de suministros, productos, herramientas y otros materiales agrícolas y pecuarios."},{"consecutivo":6,"texto":"Clasificar, seleccionar, agrupar productos, equipos y herramientas de uso agrícola y pecuario."},{"consecutivo":7,"texto":"Usar guadañadoras, podadoras y otros equipos simples para realizar mantenimiento a prados y campos de uso agrícola y pecuario."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"92130.001","nombre":"Ayudante agropecuario / Ayudante agropecuaria"},{"codigo":"92130.002","nombre":"Ayudante de granja"},{"codigo":"92130.003","nombre":"Cuidandero de finca / Cuidandera de finca"},{"codigo":"92130.004","nombre":"Obrero agropecuario / Obrera agropecuaria"},{"codigo":"92130.005","nombre":"Obrero de explotación de gusano de seda / Obrera de explotación de gusano de seda"},{"codigo":"92130.006","nombre":"Peón agropecuario / Peona agropecuaria"},{"codigo":"92130.007","nombre":"Peón de cultivos y ganadería / Peona de cultivos y ganadería"},{"codigo":"92130.008","nombre":"Peón de explotación agropecuaria / Peona de explotación agropecuaria"},{"codigo":"92130.009","nombre":"Peón de explotación mixta / Peona de explotación mixta"},{"codigo":"92130.010","nombre":"Recolector de huevos / Recolectora de huevos"},{"codigo":"92130.011","nombre":"Trabajador agropecuario / Trabajadora agropecuaria"},{"codigo":"92130.012","nombre":"Trabajador de campo / Trabajadora de campo"},{"codigo":"92130.013","nombre":"Apilador agrícola / Apiladora agrícola"},{"codigo":"92130.014","nombre":"Cuatrero agrícola / Cuatrera agrícola"}],"conocimientos":[{"id":"98","nombre":"Producción agrícola y pecuaria"}],"destrezas":[{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"61111","nombre":"Agricultores de cultivos extensivos / Agricultoras de cultivos extensivos"},{"codigo":"61140","nombre":"Agricultores y trabajadores calificados de cultivos mixtos / Agricultoras y trabajadoras calificadas de cultivos mixtos"},{"codigo":"61300","nombre":"Productores y trabajadores calificados de explotaciones agropecuarias mixtas cuya producción se destina al mercado / Productoras y trabajadoras calificadas de explotaciones agropecuarias mixtas cuya producción se destina al mercado"},{"codigo":"63300","nombre":"Trabajadores agropecuarios de subsistencia / Trabajadoras agropecuarias de subsistencia"},{"codigo":"92110","nombre":"Obreros y peones de explotaciones agrícolas / Obreras y peonas de explotaciones agrícolas"},{"codigo":"92120","nombre":"Obreros y peones de explotaciones ganaderas / Obreras y peonas de explotaciones ganaderas"}],"area_principal":{"sigla":"AGVE","nombre":"Agropecuario, silvicultura, pesca, acuicultura y veterinaria"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"9212*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"7334*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"9213","ciuo08_obs":"Denominaciones completas","cno_codigo":"7613*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Obreros y peones de jardinería y horticultura / Obreras y peonas de jardinería y horticultura', '92140', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 1, false, '{"codigo":"92140","nombre":"Obreros y peones de jardinería y horticultura / Obreras y peonas de jardinería y horticultura","descripcion":"Realizan labores manuales, sencillas y rutinarias en actividades de cultivo y mantenimiento de árboles, arbustos, flores y otras plantas en viveros y jardines, así como en la producción de plántulas, plantones, bulbos y semillas para el cultivo de vegetales y flores mediante las técnicas de cultivo intensivo. Se pueden desempeñar en empresas de mantenimiento interior y exterior de jardines, viveros, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"92","nombre":"OBREROS Y PEONES AGROPECUARIOS, PESQUEROS Y FORESTALES"},"subgrupo":{"codigo":"921","nombre":"Obreros y peones agropecuarios, pesqueros y forestales"},"grupo_primario":{"codigo":"9214","nombre":"Obreros y peones de jardinería y horticultura"}},"funciones":[{"consecutivo":1,"texto":"Preparar sitios y parcelas de jardín utilizando herramientas manuales y máquinas simples."},{"consecutivo":2,"texto":"Cargar, descargar y transportar suministros, productos y equipos de jardinería y horticultura."},{"consecutivo":3,"texto":"Recolectar, cosechar, envasar y empacar plantas y productos hortícolas para la venta y el transporte."},{"consecutivo":4,"texto":"Realizar reparaciones menores en instalaciones, equipos, cercas y edificaciones de jardinería y horticultura."},{"consecutivo":5,"texto":"Usar equipos livianos y herramientas manuales para la poda del césped y arreglos de jardinería y horticultura."},{"consecutivo":6,"texto":"Cuidar, regar, fumigar, escardar plantas y remover malas hierbas a mano en jardines y cultivos hortícolas."},{"consecutivo":7,"texto":"Ayudar a sembrar, plantar y trasplantar césped, flores, árboles y arbustos en jardines y cultivos hortícolas."},{"consecutivo":8,"texto":"Realizar tareas de mantenimiento a jardines mediante riego, escarda, remoción de malas hierbas y siega de céspedes, plantas y prados."},{"consecutivo":9,"texto":"Limpiar jardines, eliminar basuras, cortar césped, podar árboles y arbustos en jardines y cultivos hortícolas."},{"consecutivo":10,"texto":"Ayudar a reproducir especies, plantando y trasplantando semillas, bulbos y esquejes en macetas y viveros."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"92140.001","nombre":"Auxiliar de jardinería"},{"codigo":"92140.002","nombre":"Auxiliar de vivero"},{"codigo":"92140.003","nombre":"Ayudante de invernadero"},{"codigo":"92140.004","nombre":"Ayudante de jardinería"},{"codigo":"92140.005","nombre":"Ayudante de vivero"},{"codigo":"92140.006","nombre":"Cortador de césped / Cortadora de césped"},{"codigo":"92140.007","nombre":"Cuidador de horticultura / Cuidadora de horticultura"},{"codigo":"92140.008","nombre":"Guadañador / Guadañadora"},{"codigo":"92140.009","nombre":"Obrero de horticultura / Obrera de horticultura"},{"codigo":"92140.010","nombre":"Obrero de jardinería / Obrera de jardinería"},{"codigo":"92140.011","nombre":"Obrero de vivero / Obrera de vivero"},{"codigo":"92140.012","nombre":"Podador de arboles en jardines / Podadora de arboles en jardines"},{"codigo":"92140.013","nombre":"Podador de prado / Podadora de prado"}],"conocimientos":[{"id":"72","nombre":"Horticultura (técnicas de huertas, invernaderos, viveros y jardines)"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"34","nombre":"Trabajo bajo presión"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"61121","nombre":"Agricultores de plantaciones de árboles y arbustos / Agricultoras de plantaciones de árboles y arbustos"},{"codigo":"61131","nombre":"Agricultores de huertas, invernaderos, viveros y jardines / Agricultoras de huertas, invernaderos, viveros y jardines"},{"codigo":"92110","nombre":"Obreros y peones de explotaciones agrícolas / Obreras y peonas de explotaciones agrícolas"},{"codigo":"92130","nombre":"Obreros y peones de explotaciones agropecuarias / Obreras y peonas de explotaciones agropecuarias"},{"codigo":"92150","nombre":"Obreros y peones forestales y de silvicultura / Obreras y peonas forestales y de silvicultura"}],"area_principal":{"sigla":"AGVE","nombre":"Agropecuario, silvicultura, pesca, acuicultura y veterinaria"},"areas_complementarias":[{"sigla":"SEPC","nombre":"Servicios Personales y a la Comunidad"}],"equivalencias":[{"ciuo08_codigo":"9214","ciuo08_obs":"Denominaciones completas","cno_codigo":"7333*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"7614*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Obreros y peones forestales y de silvicultura / Obreras y peonas forestales y de silvicultura', '92150', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 1, false, '{"codigo":"92150","nombre":"Obreros y peones forestales y de silvicultura / Obreras y peonas forestales y de silvicultura","descripcion":"Plantan, cultivan, mantienen y cosechan bosques naturales, árboles urbanos y plantaciones forestales, apoyan la tala y el aserrado, además de realizar diversas labores sencillas y habituales relacionadas con la reforestación, manejo, mejoramiento y conservación de bosques y reservas naturales. Se pueden desempeñar en compañías explotadoras de madera, entidades con fines de reforestación y conservación de bosques, gobierno, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"92","nombre":"OBREROS Y PEONES AGROPECUARIOS, PESQUEROS Y FORESTALES"},"subgrupo":{"codigo":"921","nombre":"Obreros y peones agropecuarios, pesqueros y forestales"},"grupo_primario":{"codigo":"9215","nombre":"Obreros y peones forestales y de silvicultura"}},"funciones":[{"consecutivo":1,"texto":"Usar arrastradores y herramientas manuales para la preparación del terreno en áreas de reforestación."},{"consecutivo":2,"texto":"Recolectar semillas, podar y marcar árboles de acuerdo con especificaciones técnicas."},{"consecutivo":3,"texto":"Cumplir los reglamentos relacionados con protección ambiental, uso de recursos naturales, seguridad, prevención de incendios y accidentes."},{"consecutivo":4,"texto":"Realizar reparaciones menores y trabajos de mantenimiento a caminos forestales, edificaciones e instalaciones de uso forestal."},{"consecutivo":5,"texto":"Recoger semillas, sembrar y propagar plántulas aplicando diferentes métodos de propagación."},{"consecutivo":6,"texto":"Cortar ramas y copas de árboles, aserrar, apilar, cargar troncos y maderos en instalaciones forestales."},{"consecutivo":7,"texto":"Determinar sitios, preparar el suelo, cavar hoyos para plantar árboles, bulbos, semillas y retoños utilizando herramientas manuales de plantación."},{"consecutivo":8,"texto":"Producir injertos, capullos, plantar y trasplantar árboles en áreas de reforestación, ."},{"consecutivo":9,"texto":"Controlar y quitar la maleza de bosques utilizando herramientas manuales y productos químicos, ralear plantaciones jóvenes en áreas de reforestación y aprovechamiento forestal."},{"consecutivo":10,"texto":"Realizar, Contribuir y apoyar labores de vigilancia relacionados con la prevención de incendios forestales."},{"consecutivo":11,"texto":"Manejar y mantener sierras manuales de tipo eléctrico y mecánico para talar, cortar, desbastar árboles, troncos y ramas en áreas de aprovechamiento forestal."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"92150.001","nombre":"Apilador de madera silvicultura / Apiladora de madera silvicultura"},{"codigo":"92150.002","nombre":"Ayudante de aserradero de monte"},{"codigo":"92150.003","nombre":"Ayudante forestal"},{"codigo":"92150.004","nombre":"Cuadrillero de forestación / Cuadrillera de forestación"},{"codigo":"92150.005","nombre":"Hachador / Hachadora"},{"codigo":"92150.006","nombre":"Leñador / Leñadora"},{"codigo":"92150.007","nombre":"Obrero forestal / Obrera forestal"},{"codigo":"92150.008","nombre":"Peón de silvicultura / Peona de silvicultura"},{"codigo":"92150.009","nombre":"Peón forestal / Peona forestal"},{"codigo":"92150.010","nombre":"Plantador de árboles / Plantadora de árboles"},{"codigo":"92150.011","nombre":"Trabajador del árbol / Trabajadora del árbol"},{"codigo":"92150.012","nombre":"Trasplantador / Trasplantadora"},{"codigo":"92150.013","nombre":"Trepador de árbol / Trepadora de árbol"}],"conocimientos":[{"id":"89","nombre":"Silvicultura y producción forestal"}],"destrezas":[{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"61121","nombre":"Agricultores de plantaciones de árboles y arbustos / Agricultoras de plantaciones de árboles y arbustos"},{"codigo":"62101","nombre":"Trabajadores calificados de explotación forestal / Trabajadoras calificadas de explotación forestal"},{"codigo":"62102","nombre":"Trabajadores de silvicultura y forestación / Trabajadoras de silvicultura y forestación"}],"area_principal":{"sigla":"AGVE","nombre":"Agropecuario, silvicultura, pesca, acuicultura y veterinaria"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"9215","ciuo08_obs":"Denominaciones completas","cno_codigo":"7322*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"7333*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"7613*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"7614*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"9614*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Obreros y peones de pesca y acuicultura / Obreras y peonas de pesca y acuicultura', '92160', 'Agropecuario, silvicultura, pesca, acuicultura y veterinaria', 1, false, '{"codigo":"92160","nombre":"Obreros y peones de pesca y acuicultura / Obreras y peonas de pesca y acuicultura","descripcion":"Realizan labores sencillas y habituales de cultivo, alimentación, cuidado, seguimiento y cosecha en la producción de especies acuáticas, tanto en granjas de acuicultura como en operaciones de pesca en agua dulce, marítimas, costeras y alta mar, cumpliendo las especificaciones técnicas y buenas prácticas de manufactura, normas de calidad y medio ambiente. Se pueden desempeñar en criaderos de peces comerciales, entidades de fomento, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"92","nombre":"OBREROS Y PEONES AGROPECUARIOS, PESQUEROS Y FORESTALES"},"subgrupo":{"codigo":"921","nombre":"Obreros y peones agropecuarios, pesqueros y forestales"},"grupo_primario":{"codigo":"9216","nombre":"Obreros y peones de pesca y acuicultura"}},"funciones":[{"consecutivo":1,"texto":"Realizar artes de pesca para recolectar peces, algas, musgos marinos, almejas, otros moluscos y especies marinas."},{"consecutivo":2,"texto":"Ayudar en operaciones de manejo de acuicultura y pesca para las etapas de producción, reproducción, levante y engorde, entre otras, de acuerdo con el programa del cultivo."},{"consecutivo":3,"texto":"Capturar, clasificar, contar y trasladar productos acuícolas y de pesca de acuerdo con los programas de manejo y desinfección."},{"consecutivo":4,"texto":"Preparar medios de cultivo y nutrientes para la elaboración de microalgas y alimento para suministrar a las especies acuáticas conforme a las etapas de producción."},{"consecutivo":5,"texto":"Realizar toma y registros para establecer los parámetros de calidad de agua y producción, de acuerdo con las instrucciones establecidas."},{"consecutivo":6,"texto":"Realizar observación permanente de las condiciones físicas y sanitarias de especies acuáticas en instalaciones acuícolas y de pesca."},{"consecutivo":7,"texto":"Aplicar tratamientos profilácticos, tratamientos preventivos y de control de enfermedades, de acuerdo con especificaciones técnicas."},{"consecutivo":8,"texto":"Implementar buenas prácticas y bioseguridad de producción en acuicultura y pesca en cada una de las etapas de producción."},{"consecutivo":9,"texto":"Limpiar, clasificar, envasar pescados y mariscos en hielo, sal y otras conservas para estibar y almacenar en bodegas."},{"consecutivo":10,"texto":"Limpiar el lecho marino y alimentar a los peces, mariscos y otras especies acuáticas que están siendo cultivadas."},{"consecutivo":11,"texto":"Operar botes, manipular las amarras durante el acoplamiento en operaciones de acuicultura y pesca."},{"consecutivo":12,"texto":"Revisar, limpiar, desinfectar y mantener los equipos e instalaciones de cubierta y bodega relacionadas con cada una de las etapas productivas de la acuicultura y pesca."},{"consecutivo":13,"texto":"Preparar sedales, reparar redes, equipos de cubierta, otros aparejos y materiales de pesca y producción."},{"consecutivo":14,"texto":"Apoyar el proceso de transporte del producto acuícola y de pesca desde el punto de recolección hasta su destino, garantizando la cadena de custodia."},{"consecutivo":15,"texto":"Recoger, almacenar y disponer los residuos generados en la etapa de incubación, levante y engorde, de acuerdo con el programa de residuos establecidos."},{"consecutivo":16,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"92160.001","nombre":"Ayudante acuícola"},{"codigo":"92160.002","nombre":"Ayudante de acuicultura"},{"codigo":"92160.003","nombre":"Ayudante de criadero peces"},{"codigo":"92160.004","nombre":"Ayudante de pesca"},{"codigo":"92160.005","nombre":"Ayudante de pesca agua dulce"},{"codigo":"92160.006","nombre":"Ayudante de pesca aguas costeras"},{"codigo":"92160.007","nombre":"Ayudante de pesca alta mar"},{"codigo":"92160.008","nombre":"Ayudante en explotación piscícola"},{"codigo":"92160.009","nombre":"Obrero de acuicultura / Obrera de acuicultura"},{"codigo":"92160.010","nombre":"Obrero de caza / Obrera de caza"},{"codigo":"92160.011","nombre":"Obrero de explotación acuícola / Obrera de explotación acuícola"},{"codigo":"92160.012","nombre":"Obrero de explotación piscícola / Obrera de explotación piscícola"},{"codigo":"92160.013","nombre":"Obrero de pesca / Obrera de pesca"},{"codigo":"92160.014","nombre":"Obrero de piscicultura / Obrera de piscicultura"},{"codigo":"92160.015","nombre":"Obrero trampero / Obrera trampera"},{"codigo":"92160.016","nombre":"Recolector de algas / Recolectora de algas"},{"codigo":"92160.017","nombre":"Recolector de especies acuáticas / Recolectora de especies acuáticas"},{"codigo":"92160.018","nombre":"Recolector de mariscos / Recolectora de mariscos"}],"conocimientos":[{"id":"83","nombre":"Acuicultura y pesca"}],"destrezas":[{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"62211","nombre":"Productores de acuicultura / Productoras de acuicultura"},{"codigo":"62222","nombre":"Pescadores de aguas dulces y costeras / Pescadoras de aguas dulces y costeras"},{"codigo":"62232","nombre":"Pescadores de alta mar / Pescadoras de alta mar"},{"codigo":"63400","nombre":"Pescadores, cazadores, tramperos y recolectores de subsistencia / Pescadoras, cazadoras, tramperas y recolectoras de subsistencia"}],"area_principal":{"sigla":"AGVE","nombre":"Agropecuario, silvicultura, pesca, acuicultura y veterinaria"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"9216","ciuo08_obs":"Denominaciones completas","cno_codigo":"7342*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Obreros y peones de minas y canteras / Obreras y peonas de minas y canteras', '93111', 'Exploración y extracción de minas, canteras, petróleo y gas', 1, false, '{"codigo":"93111","nombre":"Obreros y peones de minas y canteras / Obreras y peonas de minas y canteras","descripcion":"Realizan labores sencillas y rutinarias en canteras y minas relacionadas con la extracción de minerales, el suministro de otros servicios como construcción y mantenimiento de estructuras subterráneas, vías de acceso, la entrega de materiales y provisiones de apoyo a la explotación minera. Se pueden desempeñar en compañías de explotación minera, canteras, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"93","nombre":"OBREROS Y PEONES DE LA MINERIA, LA CONSTRUCCION, LA INDUSTRIA MANUFACTURERA Y EL TRANSPORTE"},"subgrupo":{"codigo":"931","nombre":"Obreros y peones de la minería y la construcción"},"grupo_primario":{"codigo":"9311","nombre":"Obreros y peones de minas, canteras y producción de hidrocarburos"}},"funciones":[{"consecutivo":1,"texto":"Ayudar a los mineros y canteros en el mantenimiento, instalación de máquinas de perforación, equipos de minería y construcción de instalaciones subterráneas."},{"consecutivo":2,"texto":"Montar, desmontar y restaurar piezas de madera o metal en secciones de minas, canteras y equipos de minería."},{"consecutivo":3,"texto":"Remover soportes usados en túneles de minas o canteras en desuso y limpiar los desbordamientos de carbón u otros minerales utilizando herramientas manuales."},{"consecutivo":4,"texto":"Limpiar espacios subterráneos, vías, áreas de trabajo, equipo de minería y transporte utilizando herramientas manuales."},{"consecutivo":5,"texto":"Eliminar las aristas salientes y obstrucciones que representen peligro en las excavaciones de minas y canteras utilizando herramientas manuales."},{"consecutivo":6,"texto":"Retirar desechos, materiales utilizables y equipos de las áreas de trabajo una vez finalizadas las actividades de extracción en excavaciones de minas y canteras."},{"consecutivo":7,"texto":"Clasificar, cargar, apilar y almacenar las herramientas, materiales y suministros usados por otros trabajadores de la mina o cantera."},{"consecutivo":8,"texto":"Ayudar en la extracción y el retiro de piedra caliza, arcilla, grava o arena y eliminar obstrucciones en canteras a cielo abierto."},{"consecutivo":9,"texto":"Limpiar y mantener áreas de almacenamiento, maquinaria, equipo, herramientas, caminos, vías de transporte de mercancías en instalaciones de minas y canteras."},{"consecutivo":10,"texto":"Suministrar y mantener la distribución de relleno de arena, roca y otros materiales."},{"consecutivo":11,"texto":"Palear o emplear bateas o cernidores en ríos para encontrar minerales preciosos como oro y esmeraldas."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"93111.001","nombre":"Ahoyador de canteras / Ahoyadora de canteras"},{"codigo":"93111.002","nombre":"Ayudante de explosivos de minería"},{"codigo":"93111.003","nombre":"Ayudante de mantenimiento en mina"},{"codigo":"93111.004","nombre":"Ayudante de minería"},{"codigo":"93111.005","nombre":"Ayudante de patio en mina"},{"codigo":"93111.006","nombre":"Ayudante de transporte de minerales"},{"codigo":"93111.007","nombre":"Cochero de minería / Cochera de minería"},{"codigo":"93111.008","nombre":"Guaquero / Guaquera"},{"codigo":"93111.009","nombre":"Guardalámparas"},{"codigo":"93111.010","nombre":"Lampistero / Lampistera"},{"codigo":"93111.011","nombre":"Lavador de oro / Lavadora de oro"},{"codigo":"93111.012","nombre":"Minero frentero / Minera frentera"},{"codigo":"93111.013","nombre":"Minero malacatero / Minera malacatera"},{"codigo":"93111.014","nombre":"Minero picador / Minera picadora"},{"codigo":"93111.015","nombre":"Minero raso / Minera rasa"},{"codigo":"93111.016","nombre":"Obrero carbonero / Obrera carbonera"},{"codigo":"93111.017","nombre":"Obrero de canteras / Obrera de canteras"},{"codigo":"93111.018","nombre":"Obrero de mina / Obrera de mina"},{"codigo":"93111.019","nombre":"Obrero general de sísmica / Obrera general de sísmica"},{"codigo":"93111.020","nombre":"Palero de mina / Palera de mina"},{"codigo":"93111.021","nombre":"Peón de labores mineras / Peona de labores mineras"},{"codigo":"93111.022","nombre":"Peón de mina / Peona de mina"},{"codigo":"93111.023","nombre":"Trabajador de mantenimiento de carrileras de minería subterránea / Trabajadora de mantenimiento de carrileras de minería subterránea"}],"conocimientos":[{"id":"79","nombre":"Minería y extracción"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"75420","nombre":"Dinamiteros y pegadores / Dinamiteras y pegadoras"},{"codigo":"81111","nombre":"Mineros y canteros / Mineras y canteras"},{"codigo":"81112","nombre":"Operadores de servicios e instalaciones mineras / Operadoras de servicios e instalaciones mineras"}],"area_principal":{"sigla":"EMCP","nombre":"Exploración y extracción de minas, canteras, petróleo y gas"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"9311*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"7311*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"7611*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8611*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Obreros y ayudantes de producción en pozos de petróleo y gas / Obreras y ayudantas de producción en pozos de petróleo y gas', '93112', 'Exploración y extracción de minas, canteras, petróleo y gas', 1, false, '{"codigo":"93112","nombre":"Obreros y ayudantes de producción en pozos de petróleo y gas / Obreras y ayudantas de producción en pozos de petróleo y gas","descripcion":"Montan, desmontan y mantienen sobre el área de extracción equipos para apoyar la perforación y el mantenimiento de pozos de gas y petróleo. Se pueden desempeñar en compañías de exploración y producción de petróleo y gas, empresas de perforación y mantenimiento de pozos, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"93","nombre":"OBREROS Y PEONES DE LA MINERIA, LA CONSTRUCCION, LA INDUSTRIA MANUFACTURERA Y EL TRANSPORTE"},"subgrupo":{"codigo":"931","nombre":"Obreros y peones de la minería y la construcción"},"grupo_primario":{"codigo":"9311","nombre":"Obreros y peones de minas, canteras y producción de hidrocarburos"}},"funciones":[{"consecutivo":1,"texto":"Ayudar en el mantenimiento de maquinaria, equipos e instalaciones relacionados con la producción de pozos de petróleo y gas."},{"consecutivo":2,"texto":"Eliminar obstrucciones o desbordamientos de minerales de conformidad con las instrucciones recibidas utilizando herramientas manuales relacionadas con la producción de pozos de petróleo y gas."},{"consecutivo":3,"texto":"Retirar desechos, materiales reutilizables, limpiar restos de rocas, minerales y equipos de las áreas de trabajo una vez finalizadas las actividades de extracción en la producción de pozos de petróleo y gas."},{"consecutivo":4,"texto":"Montar, desmontar y mantener sobre el área de perforación equipo relacionado con la producción de pozos de petróleo y gas."},{"consecutivo":5,"texto":"Limpiar y mantener espacios subterráneos, áreas de trabajo, maquinaria, herramientas, equipo de minería y transporte en la producción de pozos de petróleo y gas, utilizando herramientas manuales."},{"consecutivo":6,"texto":"Clasificar, cargar, movilizar y almacenar las herramientas, tuberías, suministros y demás materiales usados por otros trabajadores en la producción de pozos de petróleo y gas."},{"consecutivo":7,"texto":"Ayudar en el alineamiento de tubos, acoplar bombas y mangueras al pozo principal, apoyar mientras se realizan otras actividades de instalación de tuberías en la producción de pozos de petróleo y gas."},{"consecutivo":8,"texto":"Ayudar en la demolición de edificaciones usando barras, palancas y otras herramientas y clasificar, limpiar y apilar los materiales reutilizables."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"93112.001","nombre":"Aceitero en la industria petrolera / Aceitera en la industria petrolera"},{"codigo":"93112.002","nombre":"Auxiliar en mantenimiento de áreas comunes industria petrolera"},{"codigo":"93112.003","nombre":"Auxiliar de facilidades de producción de petróleo y gas"},{"codigo":"93112.004","nombre":"Auxiliar de flush by (servicios de campo) en la industria petrolera"},{"codigo":"93112.005","nombre":"Auxiliar de lavado de equipos de industria petrolera"},{"codigo":"93112.006","nombre":"Auxiliar técnico en coiled tubing, cementación, estimulación o fractura / Auxiliar técnica en coiled tubing, cementación, estimulación o fractura"},{"codigo":"93112.007","nombre":"Auxiliar técnico de campo de slick line / Auxiliar técnica de campo de slick line"},{"codigo":"93112.008","nombre":"Ayudante de bombeo de pozos de petróleo y gas"},{"codigo":"93112.009","nombre":"Ayudante de campo petrolero"},{"codigo":"93112.010","nombre":"Auxiliar de operación en hidrocarburos"},{"codigo":"93112.011","nombre":"Auxiliar de fontanería en petróleo y gas"},{"codigo":"93112.013","nombre":"Ayudante de producción de pozos de petróleo y gas"},{"codigo":"93112.014","nombre":"Ayudante de tratamiento de pozos de petróleo y gas"},{"codigo":"93112.015","nombre":"Ayudante de mantenimiento de pozos petróleo y gas"},{"codigo":"93112.016","nombre":"Ayudante pegador de tubería de polietileno en la industria petrolera"},{"codigo":"93112.017","nombre":"Ayudante en sandblasting en la industria petrolera"},{"codigo":"93112.018","nombre":"Ayudante técnico metalmecánico de petróleo y gas / Ayudante técnica metalmecánica en petróleo y gas"},{"codigo":"93112.019","nombre":"Ayudante tubero de petróleo y gas / Ayudante tubera de petróleo y gas"},{"codigo":"93112.020","nombre":"Ayudante wireline"},{"codigo":"93112.021","nombre":"Obrero ayudante de producción en pozos de petróleo y gas / Obrera ayudante de producción en pozos de petróleo y gas"},{"codigo":"93112.022","nombre":"Obrero de campo petrolero / Obrera de campo petrolero"},{"codigo":"93112.023","nombre":"Obrero de patio de industria de petróleo y gas / Obrera de patio de industria de petróleo y gas"},{"codigo":"93112.024","nombre":"Obrero en la industria petrolera / Obrera en la industria petrolera"},{"codigo":"93112.025","nombre":"Planillero en la industria petrolera / Planillera en la industria petrolera"}],"conocimientos":[{"id":"13","nombre":"Mecánica y metalistería"},{"id":"79","nombre":"Minería y extracción"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"81112","nombre":"Operadores de servicios e instalaciones mineras / Operadoras de servicios e instalaciones mineras"},{"codigo":"81131","nombre":"Perforadores de pozos de gas y petróleo / Perforadoras de pozos de gas y petróleo"},{"codigo":"81133","nombre":"Operadores de servicios en perforación de petróleo y gas / Operadoras de servicios en perforación de petróleo y gas"},{"codigo":"93111","nombre":"Obreros y peones de minas y canteras / Obreras y peonas de minas y canteras"}],"area_principal":{"sigla":"EMCP","nombre":"Exploración y extracción de minas, canteras, petróleo y gas"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"7126*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"2314*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"9311*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"7212*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"7312*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"7318*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"7612*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Obreros y ayudantes de obras públicas y mantenimiento / Obreras y ayudantas de obras públicas y mantenimiento', '93121', 'Construcción e infraestructura', 1, false, '{"codigo":"93121","nombre":"Obreros y ayudantes de obras públicas y mantenimiento / Obreras y ayudantas de obras públicas y mantenimiento","descripcion":"Realizan funciones rutinarias y sencillas relacionadas con trabajos de construcción y mantenimiento de obras públicas tales como carreteras, ferrocarriles, andenes, presas y obras semejantes; hacen parte de las cuadrillas de trabajo y apoyan a los demás trabajadores en el mantenimiento y la construcción de obras públicas. Se pueden desempeñar en compañías constructoras, entidades oficiales, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"93","nombre":"OBREROS Y PEONES DE LA MINERIA, LA CONSTRUCCION, LA INDUSTRIA MANUFACTURERA Y EL TRANSPORTE"},"subgrupo":{"codigo":"931","nombre":"Obreros y peones de la minería y la construcción"},"grupo_primario":{"codigo":"9312","nombre":"Obreros y peones de obras públicas, mantenimiento y cementerios"}},"funciones":[{"consecutivo":1,"texto":"Cargar y descargar materiales de construcción, material excavado y equipos utilizados en las obras públicas para moverlos alrededor de las áreas de trabajo utilizando carretillas y carros de mano."},{"consecutivo":2,"texto":"Limpiar, mantener y eliminar obstrucciones en andenes, calles, áreas públicas y demás lugares de trabajo, equipo y herramientas, como parte de una cuadrilla de mantenimiento o construcción en obras públicas."},{"consecutivo":3,"texto":"Aplicar normas de salud ocupacional, seguridad industrial y medio ambiente que regulan las actividades en la construcción y el mantenimiento de obras públicas."},{"consecutivo":4,"texto":"Ayudar en las actividades de topografía como sostener o movilizar estacas y jalones, limpiar el terreno y transportar las herramientas y los equipos de fotografía a los sitios de trabajo."},{"consecutivo":5,"texto":"Alimentar y cargar las máquinas y los equipos manuales utilizados en la construcción y el mantenimiento de obras públicas como mezcladores, compresores, bombas, entre otras."},{"consecutivo":6,"texto":"Ayudar en el levantamiento de obras temporales como campamentos, cerramientos y demás requeridos en la construcción de un proyecto."},{"consecutivo":7,"texto":"Acopiar o extender materiales propios de la construcción y el mantenimiento de obras públicas, utilizando herramientas menores como palas, rastrillos, pisones, entre otros."},{"consecutivo":8,"texto":"Ayudar a operadores de equipo pesado a asegurar los accesorios y los enganches especiales del equipo de construcción y mantenimiento de obras públicas."},{"consecutivo":9,"texto":"Orientar la salida, el ingreso, la señalización y las vías de circulación para vehículos, peatones y equipos en la obra de una manera segura."},{"consecutivo":10,"texto":"Cavar y rellenar hoyos, zanjas y cunetas usando palas y otras herramientas manuales para extender capas de grava y otros materiales de construcción y mantenimiento de obras públicas."},{"consecutivo":11,"texto":"Demoler superficies de concreto, pavimento, asfaltos y rocas de menor tamaño operando martillo neumático, taladros, entre otras herramientas manuales en la construcción y el mantenimiento de obras públicas."},{"consecutivo":12,"texto":"Señalizar y demarcar el área de construcción y mantenimiento de obras públicas."},{"consecutivo":13,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"93121.001","nombre":"Auxiliar vial de construcción de hidrocarburos"},{"codigo":"93121.002","nombre":"Ayudante de pavimento"},{"codigo":"93121.003","nombre":"Auxiliar técnico en obras civiles para la industria petrolera / Auxiliar técnica en obras civiles para la industria petrolera"},{"codigo":"93121.004","nombre":"Bracero / Bracera"},{"codigo":"93121.005","nombre":"Cadenero de a