  ('rol_cuoc', 'Obreros y peones de la construcción / Obreras y peonas de la construcción', '93130', 'Construcción e infraestructura', 1, false, '{"codigo":"93130","nombre":"Obreros y peones de la construcción / Obreras y peonas de la construcción","descripcion":"Ayudan a los trabajadores de las diferentes actividades de construcción a efectuar labores manuales, sencillas y rutinarias relacionadas con la construcción y demolición de edificaciones. Se pueden desempeñar en compañías constructoras, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"93","nombre":"OBREROS Y PEONES DE LA MINERIA, LA CONSTRUCCION, LA INDUSTRIA MANUFACTURERA Y EL TRANSPORTE"},"subgrupo":{"codigo":"931","nombre":"Obreros y peones de la minería y la construcción"},"grupo_primario":{"codigo":"9313","nombre":"Obreros y peones de la construcción"}},"funciones":[{"consecutivo":1,"texto":"Apoyar en el montaje y desmontaje de andamios y barricadas de acuerdo con normativa vigente para la ejecución de actividades de construcción y la aplicación de pintura o material de recubrimiento."},{"consecutivo":2,"texto":"Ayudar en la demolición de edificaciones usando barras, palancas y otras herramientas manuales para clasificar, limpiar y apilar los materiales reutilizables."},{"consecutivo":3,"texto":"Limpiar lugares de trabajo, ladrillos usados de edificios, retirar obstrucciones y hacer otras tareas sencillas en sitios de demolición."},{"consecutivo":4,"texto":"Retirar escombros y otros desechos de los sitios de construcción, utilizando rastrillos, palas, carretillas y otras herramientas manuales."},{"consecutivo":5,"texto":"Mezclar, verter y esparcir materiales como arena, tierra, grava, hormigón, yeso, cemento o mortero y otros materiales similares en los sitios de construcción."},{"consecutivo":6,"texto":"Cavar, rellenar y nivelar el terreno, hoyos y zanjas en los sitios de construcción utilizando herramientas de uso manual."},{"consecutivo":7,"texto":"Cargar y descargar equipos, materiales de construcción, material excavado para movilizarlos a las áreas de trabajo utilizando carretillas, carros de mano, capachos y otros equipos manuales."},{"consecutivo":8,"texto":"Abastecer de forma manual las máquinas y equipos utilizados en la construcción, tales como mezcladores, compresores, bombas, entre otros."},{"consecutivo":9,"texto":"Ayudar en los sitios de construcción a carpinteros, techadores, albañiles e instaladores de vidrios en actividades de rutina relacionadas con la construcción."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"93130.001","nombre":"Apilador de material de construcción / Apiladora de material de construcción"},{"codigo":"93130.002","nombre":"Ayudante de albañil"},{"codigo":"93130.003","nombre":"Ayudante de albañilería"},{"codigo":"93130.004","nombre":"Ayudante de carpintería"},{"codigo":"93130.005","nombre":"Ayudante de construcción"},{"codigo":"93130.006","nombre":"Ayudante de construcción con materiales tradicionales"},{"codigo":"93130.007","nombre":"Ayudante de obra"},{"codigo":"93130.008","nombre":"Ayudante de pintura de construcción"},{"codigo":"93130.009","nombre":"Ayudante de plomería"},{"codigo":"93130.010","nombre":"Auxiliar de techado"},{"codigo":"93130.011","nombre":"Auxiliar técnico en obras civiles / Auxiliar técnica en obras civiles"},{"codigo":"93130.012","nombre":"Auxiliar de trabajo en vidrio"},{"codigo":"93130.013","nombre":"Ayudante instalador de divisiones de aluminio / Ayudante instaladora de divisiones de aluminio"},{"codigo":"93130.014","nombre":"Ayudante instalador de divisiones de baño / Ayudante instaladora de divisiones de baño"},{"codigo":"93130.015","nombre":"Ayudante instalador de gabinetes de baño y cocina / Ayudante instaladora de gabinetes de baño y cocina"},{"codigo":"93130.016","nombre":"Ayudante instalador de puertas y ventanas de aluminio / Ayudante instaladora de puertas y