  ('rol_cuoc', 'Obreros y ayudantes en el procesamiento de la madera y producción de pulpa y papel / Obreras y ayudantas en el procesamiento de la madera y producción de pulpa y papel', '93291', 'Industria química', 1, false, '{"codigo":"93291","nombre":"Obreros y ayudantes en el procesamiento de la madera y producción de pulpa y papel / Obreras y ayudantas en el procesamiento de la madera y producción de pulpa y papel","descripcion":"Llevan a cabo varias actividades de rutina en el procesamiento de la madera y apoyan a los operadores de máquinas en la fabricación de pulpa y papel. Se pueden desempeñar en plantas de procesamiento de pulpa y papel, plantas de tratamiento de madera, aserraderos, empresas de procesamiento de la madera, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"93","nombre":"OBREROS Y PEONES DE LA MINERIA, LA CONSTRUCCION, LA INDUSTRIA MANUFACTURERA Y EL TRANSPORTE"},"subgrupo":{"codigo":"932","nombre":"Obreros y peones de la industria manufacturera"},"grupo_primario":{"codigo":"9329","nombre":"Obreros y peones de la industria manufacturera no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Alimentar los transportadores, sierras, máquinas de secado y otro equipo para procesamiento de láminas de madera, chapados y productos similares."},{"consecutivo":2,"texto":"Colocar troncos sobre el transportador y en la tolva de la máquina trituradora y alinearlos utilizando palancas, picas, equipos y otras herramientas manuales."},{"consecutivo":3,"texto":"Remover las virutas y desperdicios para el reprocesamiento de pulpa y papel utilizando equipos y herramientas manuales."},{"consecutivo":4,"texto":"Ayudar a otros trabajadores que operan máquinas y equipos en el procesamiento de la madera y el papel."},{"consecutivo":5,"texto":"Movilizar mercancías, materiales, equipos, otros artículos y retirar las piezas terminadas a los lugares de trabajo, utilizando carros de mano, carretas y otras herramientas manuales."},{"consecutivo":6,"texto":"Limpiar y eliminar las obstrucciones en máquinas, equipos, áreas de trabajo utilizando palas, mangueras y otras herramientas manuales."},{"consecutivo":7,"texto":"Clasificar, apilar y transportar de forma manual madera, hojas de madera, tablas y productos similares durante las diferentes etapas del procesamiento de madera y papel."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"93291.001","nombre":"Alimentador de máquina pulverizadora de pulpa y papel / Alimentadora de máquina pulverizadora de pulpa y papel"},{"codigo":"93291.002","nombre":"Ayudante de aserradero en el procesamiento o transformación de la madera"},{"codigo":"93291.003","nombre":"Auxiliar de operación en batido de pulpa y papel"},{"codigo":"93291.004","nombre":"Ayudante de procesamiento de madera"},{"codigo":"93291.005","nombre":"Ayudante de procesamiento de pulpa y papel"},{"codigo":"93291.006","nombre":"Ayudante operador de batidora de pulpa y papel / Ayudante operadora de batidora de pulpa y papel"},{"codigo":"93291.007","nombre":"Confeccionador de cajas cartón / Confeccionadora de cajas cartón"},{"codigo":"93291.008","nombre":"Limpiador de transportador de pulpa y papel / Limpiadora de transportador de pulpa y papel"},{"codigo":"93291.009","nombre":"Obrero de procesamiento de madera / Obrera de procesamiento de madera"},{"codigo":"93291.010","nombre":"Obrero y ayudante en el procesamiento de la madera y producción de pulpa y papel / Obrera y ayudanta en el procesamiento de la madera y producción de pulpa y papel"}],"conocimientos":[{"id":"77","nombre":"Materiales (vidrio, papel, plástico y madera)"},{"id":"89","nombre":"Silvicultura y producción forestal"}],"destrezas":[{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"75210","nombre":"Operarios del tratamiento de la madera / Operarias del tratamiento de la madera"},{"codigo":"75230","nombre":"Ajustadores y operadores de máquinas para trabajar madera / Ajustadoras y operadoras de máquinas para trabajar madera"},{"codigo":"75433","nombre":"Inspectores de control de calidad, procesamiento de la madera / Inspectoras de control de calidad, procesamiento de la madera"},{"codigo":"81430","nombre":"Operadores de máquinas para fabricar productos de papel / Operadoras de máquinas para fabricar productos de papel"},{"codigo":"81711","nombre":"Operadores de máquinas para la fabricación de papel / Operadoras de máquinas para la fabricación de papel"},{"codigo":"81712","nombre":"Operadores de máquinas para la producción de pulpa / Operadoras de máquinas para la producción de pulpa"},{"codigo":"81720","nombre":"Operadores de instalaciones de procesamiento de la madera / Operadoras de instalaciones de procesamiento de la madera"}],"area_principal":{"sigla":"INQU","nombre":"Industria química"},"areas_complementarias":[{"sigla":"TMFM","nombre":"Transformación de la madera y fabricación de muebles"}],"equivalencias":[{"ciuo08_codigo":"9329*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"9614*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Obreros y ayudantes en el tratamiento de metales y minerales / Obreras y ayudantas en el tratamiento de metales y minerales', '93292', 'Fabricación, transformación de materiales, instalación, mantenimiento y reparación', 1, false, '{"codigo":"93292","nombre":"Obreros y ayudantes en el tratamiento de metales y minerales / Obreras y ayudantas en el tratamiento de metales y minerales","descripcion":"Cargan materiales, limpian, empacan y realizan otras actividades elementales; remueven los excedentes y materiales sobrantes de las piezas fundidas y los productos de metal y realizan otras labores relacionadas con el procesamiento de metales y minerales. Se pueden desempeñar en talleres, empresas de fabricación de productos metálicos, plantas de procesamiento de metales y minerales, refinerías, plantas de fundición, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"93","nombre":"OBREROS Y PEONES DE LA MINERIA, LA CONSTRUCCION, LA INDUSTRIA MANUFACTURERA Y EL TRANSPORTE"},"subgrupo":{"codigo":"932","nombre":"Obreros y peones de la industria manufacturera"},"grupo_primario":{"codigo":"9329","nombre":"Obreros y peones de la industria manufacturera no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Ayudar a los montadores de estructuras, operadores de máquinas y otros trabajadores de metal a clasificar, apilar, enfardar, marcar materiales y realizar otras actividades de apoyo a los operarios en el procesamiento de metales y minerales."},{"consecutivo":2,"texto":"Alimentar transportadores, trituradores y otros equipos relacionados con el tratamiento de metales y minerales."},{"consecutivo":3,"texto":"Realizar el alistamiento y proveer el material, herramientas e insumos en forma oportuna, con las condiciones técnicas especificadas y de acuerdo con los requerimientos técnicos de la metalistería, pailería, tubería y soldadura."},{"consecutivo":4,"texto":"Abrir válvulas e iniciar bombeos y ajustar condiciones de operación de los equipos de acuerdo con los requerimientos propios de la metalistería, pailería, tubería, soldadura."},{"consecutivo":5,"texto":"Operar equipo de limpieza para remover residuos y suciedad de los hornos, exceso de soldadura, herrumbre, fundición y otros materiales de las superficies de las piezas de metal fundidas y otros productos."},{"consecutivo":6,"texto":"Sumergir productos de metal dentro de las soluciones limpiadoras relacionadas con el tratamiento de metales y minerales."},{"consecutivo":7,"texto":"Movilizar materias primas y productos acabados en el tratamiento de metales y minerales, de forma manual o utilizando carretillas elevadoras u otros aparatos simples."},{"consecutivo":8,"texto":"Movilizar materias primas, piezas y productos terminados, mercancías, equipos, materiales, material sobrante y otros artículos a los lugares de trabajo utilizando carretilla elevadora, de forma manual o con equipo mecánico."},{"consecutivo":9,"texto":"Cargar, alimentar y descargar vehículos, camiones, vagonetas utilizando carretillas y otros equipos manuales en el tratamiento de metales y minerales."},{"consecutivo":10,"texto":"Eliminar obstrucciones, limpiar áreas de trabajo, maquinaria, equipos y herramientas utilizados en el tratamiento de metales y minerales."},{"consecutivo":11,"texto":"Clasificar láminas, piezas, partes de metal sobrantes y otros materiales; adecuar mediante talladuras, cortes o partes a ensamblar en el tratamiento de metales y minerales."},{"consecutivo":12,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"93292.001","nombre":"Amasador de arcillas / Amasadora de arcillas"},{"codigo":"93292.002","nombre":"Auxiliar de soldadura"},{"codigo":"93292.003","nombre":"Ayudante de calcinación"},{"codigo":"93292.004","nombre":"Ayudante de fundición"},{"codigo":"93292.005","nombre":"Ayudante de horno de tratamiento de metales y minerales"},{"codigo":"93292.006","nombre":"Ayudante de metalistería"},{"codigo":"93292.007","nombre":"Ayudante de ornamentación"},{"codigo":"93292.008","nombre":"Ayudante de procesamiento de metales y minerales"},{"codigo":"93292.009","nombre":"Ayudante de tratamiento de metales y minerales"},{"codigo":"93292.010","nombre":"Ayudante en fabricación metálica"},{"codigo":"93292.011","nombre":"Ayudante en fabricación de productos de metal"},{"codigo":"93292.012","nombre":"Ayudante de forja"},{"codigo":"93292.013","nombre":"Ayudante de máquina de trabajo del metal"},{"codigo":"93292.014","nombre":"Ayudante metalistero / Ayudante metalistera"},{"codigo":"93292.015","nombre":"Ayudante metalmecánico / Ayudante metalmecánica"},{"codigo":"93292.016","nombre":"Ayudante de pailería"},{"codigo":"93292.017","nombre":"Ayudante soldador / Ayudante soldadora"},{"codigo":"93292.018","nombre":"Ayudante de soldadura"},{"codigo":"93292.019","nombre":"Ayudante en vertimiento de metales"},{"codigo":"93292.020","nombre":"Cargador de horno tratamiento metales / Cargadora de horno tratamiento metales"},{"codigo":"93292.021","nombre":"Extractor de arcillas / Extractora de arcillas"},{"codigo":"93292.022","nombre":"Lijador a mano / Lijadora a mano"},{"codigo":"93292.023","nombre":"Lijador manual de metales y minerales / Lijadora manual de metales y minerales"},{"codigo":"93292.024","nombre":"Limpiador de arcillas / Limpiadora de arcillas"},{"codigo":"93292.025","nombre":"Obrero ayudante en tratamiento de metales y minerales / Obrera ayudante en tratamiento de metales y minerales"},{"codigo":"93292.026","nombre":"Obrero de fundición / Obrera de fundición"},{"codigo":"93292.027","nombre":"Obrero enrollador de bobinas mano / Obrera enrolladora de bobinas mano"},{"codigo":"93292.028","nombre":"Obrero en fabricación metálica / Obrera en fabricación metálica"}],"conocimientos":[{"id":"13","nombre":"Mecánica y metalistería"}],"destrezas":[{"id":"2","nombre":"Escucha activa"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"19","nombre":"Selección de equipo"},{"id":"34","nombre":"Trabajo bajo presión"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"72120","nombre":"Soldadores y oxicortadores / Soldadoras y oxicortadoras"},{"codigo":"72210","nombre":"Herreros y forjadores / Herreras y forjadoras"},{"codigo":"72240","nombre":"Pulidores de metales y afiladores de herramientas / Pulidoras de metales y afiladores de herramientas"},{"codigo":"81120","nombre":"Operadores de instalaciones de procesamiento de minerales y rocas / Operadoras de instalaciones de procesamiento de minerales y rocas"},{"codigo":"81140","nombre":"Operadores de máquinas para fabricar cemento y otros productos minerales / Operadoras de máquinas para fabricar cemento y otros productos minerales"},{"codigo":"81210","nombre":"Operadores de instalaciones de procesamiento de metales / Operadoras de instalaciones de procesamiento de metales"},{"codigo":"81220","nombre":"Operadores de máquinas pulidoras, galvanizadoras y recubridoras de metales / Operadoras de máquinas pulidoras, galvanizadoras y recubridoras de metales"}],"area_principal":{"sigla":"FAMA","nombre":"Fabricación, transformación de materiales, instalación, mantenimiento y reparación"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"7212*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"8342*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"7221*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"8612*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"9329*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"9611*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"9612*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"9612*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Obreros y ayudantes de planta química / Obreras y ayudantas de planta química', '93293', 'Industria química', 1, false, '{"codigo":"93293","nombre":"Obreros y ayudantes de planta química / Obreras y ayudantas de planta química","descripcion":"Llevan a cabo una variedad de actividades manuales sencillas y habituales de manipulación de materiales, limpieza y labores generales de rutina, relacionadas en el procesamiento químico. Se pueden desempeñar en empresas farmacéuticas, químicas, petroquímicas, plantas de tratamiento de agua, plantas de procesamiento de petróleo y gas natural, entre otros. entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"93","nombre":"OBREROS Y PEONES DE LA MINERIA, LA CONSTRUCCION, LA INDUSTRIA MANUFACTURERA Y EL TRANSPORTE"},"subgrupo":{"codigo":"932","nombre":"Obreros y peones de la industria manufacturera"},"grupo_primario":{"codigo":"9329","nombre":"Obreros y peones de la industria manufacturera no clasificados en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Mover, clasificar y apilar mercancías, materiales, productos, componentes y piezas terminadas a los lugares de trabajo de forma manual o con equipo mecánico simple."},{"consecutivo":2,"texto":"Alimentar, cargar y descargar maquinaria, equipos de producción, vehículos y carretillas relacionados en procesos de planta química."},{"consecutivo":3,"texto":"Eliminar obstrucciones, limpiar áreas de producción, maquinaria, equipos y herramientas utilizadas en el procesamiento químico."},{"consecutivo":4,"texto":"Ayudar a otros trabajadores a operar, reparar, mantener equipos de distribución de gas, filtración de agua y tratamiento de desechos utilizados en el procesamiento químico."},{"consecutivo":5,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"93293.001","nombre":"Ayudante de fabricación de productos de plástico"},{"codigo":"93293.002","nombre":"Ayudante de fabricación de productos químicos"},{"codigo":"93293.003","nombre":"Ayudante de procesamiento químico"},{"codigo":"93293.004","nombre":"Limpiador de alambique en proceso químico / Limpiadora de alambique en proceso químico"},{"codigo":"93293.005","nombre":"Limpiador de alambique / Limpiadora de alambique"},{"codigo":"93293.006","nombre":"Limpiador de filtros proceso químico / Limpiadora de filtros proceso químico"},{"codigo":"93293.007","nombre":"Obrero de fabricación de plásticos / Obrera de fabricación de plásticos"},{"codigo":"93293.008","nombre":"Obrero en planta química / Obrera en planta química"},{"codigo":"93293.009","nombre":"Obrero y ayudante de planta química / Obrera y ayudanta de planta química"},{"codigo":"93293.010","nombre":"Ayudante de operación en planta de tratamiento de agua potable"},{"codigo":"93293.011","nombre":"Ayudante de operación en planta de tratamiento de agua residual"},{"codigo":"93293.012","nombre":"Ayudante de planta química"},{"codigo":"93293.013","nombre":"Ayudante en procesos químicos"},{"codigo":"93293.014","nombre":"Obrero de instalaciones de gas / Obrera de instalaciones de gas"},{"codigo":"93293.015","nombre":"Cargador de horno para tratamientos químicos / Cargadora de horno para tratamientos químicos"}],"conocimientos":[{"id":"7","nombre":"Producción y procesamiento"},{"id":"16","nombre":"Química"},{"id":"85","nombre":"Seguridad y salud en el trabajo"}],"destrezas":[{"id":"1","nombre":"Comprensión de lectura"},{"id":"2","nombre":"Escucha activa"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"81311","nombre":"Operadores de máquinas de planta química / Operadoras de máquinas de planta química"},{"codigo":"81312","nombre":"Operadores de planta de gas / Operadoras de planta de gas"}],"area_principal":{"sigla":"INQU","nombre":"Industria química"}