  ('rol_cuoc', 'Conductores de vehículos y maquinaria de tracción animal / Conductoras de vehículos y maquinaria de tracción animal', '93320', 'Logística y transporte', 1, true, '{"codigo":"93320","nombre":"Conductores de vehículos y maquinaria de tracción animal / Conductoras de vehículos y maquinaria de tracción animal","descripcion":"Conducen carros, carruajes, maquinarías y otros vehículos de tracción animal tirados por caballos, perros, mulas y demás para transportar pasajeros y/o carga, del mismo modo, brindan información sobre destinos turísticos de acuerdo con las expectativas del visitante y protocolos de servicio. Se pueden desempeñar en entidades gubernamentales, faenas agrícolas, establecimientos de turismo y comercio, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"93","nombre":"OBREROS Y PEONES DE LA MINERIA, LA CONSTRUCCION, LA INDUSTRIA MANUFACTURERA Y EL TRANSPORTE"},"subgrupo":{"codigo":"933","nombre":"Obreros y peones de transporte y almacenamiento"},"grupo_primario":{"codigo":"9332","nombre":"Conductores de vehículos y maquinaria de tracción animal"}},"funciones":[{"consecutivo":1,"texto":"Colocar arreos a los animales de tiro, engancharlos a vehículos o maquinaria, conducir, guiar, arrear y maniobrar zorras u otro tipo de vehículo de tracción animal en la dirección deseada, prestando atención a otros vehículos y respetando las normas de tránsito."},{"consecutivo":2,"texto":"Ayudar a los pasajeros a subir, descender, cobrar el pasaje o precio del transporte efectuado, así como cargar y descargar mercancías de un vehículo accionado por tracción animal."},{"consecutivo":3,"texto":"Conducir animales enganchados a maquinaria agrícola o artefactos de otra naturaleza utilizados para arrastrar vagones en minas, canteras, entre otros."},{"consecutivo":4,"texto":"Asear y alimentar los animales, hacer pequeñas reparaciones, colocar arneses de caballería y piezas de repuesto para mantener en buen estado de limpieza y marcha vehículos o máquinas impulsados por tracción animal."},{"consecutivo":5,"texto":"Informar sobre atractivos turísticos, servicios conexos del destino turístico de acuerdo con las necesidades y las expectativas del visitante y los protocolos de servicio."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"93320.001","nombre":"Cochero guía de turismo / Cochera guía de turismo"},{"codigo":"93320.002","nombre":"Cochero informador turístico / Cochera informadora turística"},{"codigo":"93320.003","nombre":"Conductor de maquinaria agrícola no motorizada / Conductora de maquinaria agrícola no motorizada"},{"codigo":"93320.004","nombre":"Conductor de tren de animales / Conductora de tren de animales"},{"codigo":"93320.005","nombre":"Conductor de vehículo de tracción animal / Conductora de vehículo de tracción animal"},{"codigo":"93320.006","nombre":"Zorrero / Zorrera"}],"conocimientos":[{"id":"5","nombre":"Servicio al cliente"},{"id":"31","nombre":"Servicios de transporte"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"26","nombre":"Reparación"},{"id":"38","nombre":"Seguir instrucciones"}],"ocupaciones_afines":[{"codigo":"51131","nombre":"Guías de turismo"},{"codigo":"93310","nombre":"Conductores de vehículos accionados a pedal o a brazo / Conductoras de vehículos accionados a pedal o a brazo"}],"area_principal":{"sigla":"LOTR","nombre":"Logística y transporte"},"areas_complementarias":[{"sigla":"AGVE","nombre":"Agropecuario, silvicultura, pesca, acuicultura y veterinaria"},{"sigla":"TUHG","nombre":"Turismo, hotelería y gastronomía"}],"equivalencias":[{"ciuo08_codigo":"9332","ciuo08_obs":"Denominaciones completas","cno_codigo":"6341*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8622*","cno_obs":"Denominaciones parciales"}]}'::js