  ('rol_cuoc', 'Obreros y peones de carga y descarga / Obreras y peonas de carga y descarga', '93331', 'Logística y transporte', 1, false, '{"codigo":"93331","nombre":"Obreros y peones de carga y descarga / Obreras y peonas de carga y descarga","descripcion":"Realizan una variedad de labores sencillas y rutinarias como manipular, mover, cargar y descargar materiales, mercancías, equipos y herramientas en forma manual o usando equipos simples. Se pueden desempeñar en compañías de transporte, almacenamiento y movimiento de carga, compañías manufactureras, establecimientos de comercio, bodegas, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"93","nombre":"OBREROS Y PEONES DE LA MINERIA, LA CONSTRUCCION, LA INDUSTRIA MANUFACTURERA Y EL TRANSPORTE"},"subgrupo":{"codigo":"933","nombre":"Obreros y peones de transporte y almacenamiento"},"grupo_primario":{"codigo":"9333","nombre":"Obreros y peones de carga, portuarios y de transporte"}},"funciones":[{"consecutivo":1,"texto":"Cargar, descargar y mover mercancías, productos y materiales en forma manual o utilizando equipo de mano de acuerdo con especificaciones técnicas."},{"consecutivo":2,"texto":"Clasificar y apilar mercancías, productos, materiales y herramientas en almacenes o depósitos antes de la carga o descarga de acuerdo con instrucciones."},{"consecutivo":3,"texto":"Realizar labores rutinarias en bodegas como ordenar, mantener y embalar mercancías, productos, materiales y herramientas para transportarlos de un lugar a otro."},{"consecutivo":4,"texto":"Revisar y controlar productos, mercancías, materiales y herramientas según naturaleza, protocolos y sistemas de almacenaje."},{"consecutivo":5,"texto":"Apoyar la entrega oportuna y en buen estado de las encomiendas solicitadas por los clientes."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"93331.001","nombre":"Auxiliar de carga"},{"