  ('rol_cuoc', 'Obreros y peones portuarios / Obreras y peonas portuarias', '93332', 'Logística y transporte', 1, false, '{"codigo":"93332","nombre":"Obreros y peones portuarios / Obreras y peonas portuarias","descripcion":"Realizan labores sencillas y rutinarias tales como cargar, descargar y trasladar carga, mercancías, materiales, herramientas, equipaje y apilarlos en almacenes, muelles y barcos para su transporte por vía marítima. Se pueden desempeñar en compañías transportadoras de carga marítima, agencias, líneas marítimas, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"93","nombre":"OBREROS Y PEONES DE LA MINERIA, LA CONSTRUCCION, LA INDUSTRIA MANUFACTURERA Y EL TRANSPORTE"},"subgrupo":{"codigo":"933","nombre":"Obreros y peones de transporte y almacenamiento"},"grupo_primario":{"codigo":"9333","nombre":"Obreros y peones de carga, portuarios y de transporte"}},"funciones":[{"consecutivo":1,"texto":"Conectar mangueras entre tuberías principales de distribución y tanques de almacenamiento en embarcaciones, costas, tanques de barcazas, buques cisterna y otros barcos para cargar o descargar combustibles, petróleo, materiales líquidos, productos químicos, gases licuados, entre otros."},{"consecutivo":2,"texto":"Cargar, descargar, mover y apilar mercancías, productos, materiales, herramientas, equipos y equipaje en almacenes o depósitos similares de buques de forma manual o utilizando equipo de mano."},{"consecutivo":3,"texto":"Realizar actividades rutinarias en bodegas como abrir contenedores y guacales, completar el diligenciamiento de órdenes de bodegaje, revisar y pesar los materiales."},{"consecutivo":4,"texto":"Clasificar y apilar mercancía antes de su carga o descarga en bodegas, depósitos o almacenes de acuerdo con instrucciones."},{"consecutivo":5,"texto":"Realizar actividades como amarrar y apuntalar carga abordo de barcos, abrir y cerrar escotillas, limpiar bodegas, depósitos, almacenes y aparejos de carga en tanques de barcazas, buques cisterna y otros barcos."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"93332.001","nombre":"Cargador de buques / Cargadora de buques"},{"codigo":"93332.002","nombre":"Cargador de buques cisterna / Cargadora de buques cisterna"},{"codigo":"93332.003","nombre":"Cargador de buques cisterna gases / Cargadora de buques cisterna gases"},{"codigo":"93332.004","nombre":"Cargador de buques cisterna líquidos / Cargadora de buques cisterna líquidos"},{"codigo":"93332.005","nombre":"Estibador / Estibadora"},{"codigo":"93332.006","nombre":"Obrero de carga buques cisterna gases / Obrera de carga buques cisterna gases"},{"codigo":"93332.007","nombre":"Obrero de carga de buques cisterna líquidos / Obrera de carga de buques cisterna líquidos"},{"codigo":"93332.008","nombre":"Obrero de carga en buques / Obrera de carga en buques"},{"codigo":"93332.009","nombre":"Obrero de muelle / Obrera de muelle"},{"codigo":"93332.010","nombre":"Obrero portuario / Obrera portuaria"},{"codigo":"93332.011","nombre":"Obrero portuario de carga / Obrera portuaria de carga"},{"codigo":"93332.012","nombre":"Tanquero portuario / Tanquera portuaria"}],"conocimientos":[{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"19","nombre":"Selección de equipo"}],"ocupaciones_afines":[{"codigo":"81891","nombre":"Operadores portuarios / Operadoras portuarias"},{"codigo":"83430","nombre":"Operadores de grúas, aparatos elevadores y afines / Operadoras de grúas, aparatos elevadores y afines"},{"codigo":"83440","nombre":"Operadores de montacargas / Operadoras de montacargas"},{"codigo":"93331","nombre":"Obreros y peones de carga y descarga / Obreras y peonas de carga y descarga"},{"codigo":"93333","nombre":"Operarios y auxiliares de rampa de transporte aéreo / Operarias y auxiliares de rampa de transporte aéreo"},{"codigo":"93334","nombre":"Ayudantes de transporte automotor"}],"area_principal":{"sigla":"LOTR","nombre":"Logística y transporte"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"9333*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"8491*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8492*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8622*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Operarios y auxiliares de rampa de transporte aéreo / Operarias y auxiliares de rampa de transporte aéreo', '93333', 'Logística y transporte', 2, true, '{"codigo":"93333","nombre":"Operarios y auxiliares de rampa de transporte aéreo / Operarias y auxiliares de rampa de transporte aéreo","descripcion":"Realizan funciones sencillas y rutinarias relacionadas con el servicio de rampa aérea, del mismo modo apoyan otras labores de soporte en tierra como apilar, manipular, cargar y descargar mercancía, equipos y equipaje de pasajeros en aeropuertos. Se pueden desempeñar en aerolíneas, compañías de servicio aéreo, entre otros.","nivel_competencia":2,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"93","nombre":"OBREROS Y PEONES DE LA MINERIA, LA CONSTRUCCION, LA INDUSTRIA MANUFACTURERA Y EL TRANSPORTE"},"subgrupo":{"codigo":"933","nombre":"Obreros y peones de transporte y almacenamiento"},"grupo_primario":{"codigo":"9333","nombre":"Obreros y peones de carga, portuarios y de transporte"}},"funciones":[{"consecutivo":1,"texto":"Limpiar, lavar y preparar la parte exterior e interior del avión para uso de los pasajeros de acuerdo con protocolos y especificaciones técnicas."},{"consecutivo":2,"texto":"Cargar, descargar, clasificar, mover y enrutar carga, mercancía y equipaje de los pasajeros de aeronaves."},{"consecutivo":3,"texto":"Clasificar y disponer carga, mercancía y equipaje de pasajeros antes de su carga o descarga de acuerdo con instrucciones dadas por el planeador de carga para obtener el balance apropiado."},{"consecutivo":4,"texto":"Cargar, apilar y transportar mercancía, cargamento y equipaje desde el avión hasta las bodegas, almacenes o depósitos del aeropuerto o hacia el avión."},{"consecutivo":5,"texto":"Conducir equipos manuales de servicio de rampa y ayudar a la carga y descarga de vehículos como tractores, remolcadores, camiones para el servicio de alimentos, servicio sanitario y fumigación, entre otros."},{"consecutivo":6,"texto":"Posicionar y operar escaleras y puertas de carga del avión de acuerdo con protocolos y especificaciones técnicas."},{"consecutivo":7,"texto":"Guiar o remolcar aviones a las puertas de abordaje de pasajeros o de carga y descarga de mercancía, maquinaria, equipos y equipaje, entre otros."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"93333.001","nombre":"Agente de rampa de transporte aéreo"},{"codigo":"93333.002","nombre":"Auxiliar de asistencia en tierra"},{"codigo":"93333.003","nombre":"Auxiliar de carga en aerolínea"},{"codigo":"93333.004","nombre":"Auxiliar de equipajes de transporte aéreo"},{"codigo":"93333.005","nombre":"Auxiliar de operaciones terrestres"},{"codigo":"93333.006","nombre":"Auxiliar de rampa en aeropuerto"},{"codigo":"93333.007","nombre":"Cargador de aviones / Cargadora de aviones"},{"codigo":"93333.008","nombre":"Manipulador de equipaje / Manipuladora de equipaje"},{"codigo":"93333.009","nombre":"Obrero de carga de aviones / Obrera de carga de aviones"},{"codigo":"93333.011","nombre":"Operario de carga de transporte aéreo / Operaria de carga de transporte aéreo"},{"codigo":"93333.012","nombre":"Operario de equipaje de transporte aéreo / Operaria de equipaje de transporte aéreo"},{"codigo":"93333.013","nombre":"Operario de mantenimiento y limpieza de aeronaves / Operaria de mantenimiento y limpieza de aeronaves"},{"codigo":"93333.014","nombre":"Operario de rampa aeropuerto / Operaria de rampa aeropuerto"},{"codigo":"93333.015","nombre":"Operario de rampa de transporte aéreo / Operaria de rampa de transporte aéreo"}],"conocimientos":[{"id":"5","nombre":"Servicio al cliente"},{"id":"31","nombre":"Servicios de transporte"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"51110","nombre":"Personal de servicio a pasajeros"},{"codigo":"83430","nombre":"Operadores de grúas, aparatos elevadores y afines / Operadoras de grúas, aparatos elevadores y afines"},{"codigo":"83440","nombre":"Operadores de montacargas / Operadoras de montacargas"},{"codigo":"93331","nombre":"Obreros y peones de carga y descarga / Obreras y peonas de carga y descarga"},{"codigo":"93332","nombre":"Obreros y peones portuarios / Obreras y peonas portuarias"},{"codigo":"93334","nombre":"Ayudantes de transporte automotor"}],"area_principal":{"sigla":"LOTR","nombre":"Logística y transporte"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"9333*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"8484*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Ayudantes de transporte automotor', '93334', 'Logística y transporte', 1, true, '{"codigo":"93334","nombre":"Ayudantes de transporte automotor","descripcion":"Realizan una variedad de labores sencillas y rutinarias de apoyo a los operadores de transporte automotor como embalar, acarrear, cargar y descargar muebles, enseres domésticos, mercancías, equipaje y otros tipos de carga. Se pueden desempeñar en compañías de transporte automotor, empresas de mudanza, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"93","nombre":"OBREROS Y PEONES DE LA MINERIA, LA CONSTRUCCION, LA INDUSTRIA MANUFACTURERA Y EL TRANSPORTE"},"subgrupo":{"codigo":"933","nombre":"Obreros y peones de transporte y almacenamiento"},"grupo_primario":{"codigo":"9333","nombre":"Obreros y peones de carga, portuarios y de transporte"}},"funciones":[{"consecutivo":1,"texto":"Cargar, descargar y mover productos, materiales, mercancías y equipos de forma manual o utilizando equipo de mano en camiones, camionetas, furgones, entre otros."},{"consecutivo":2,"texto":"Embalar y trastear muebles, enseres, máquinas, menaje doméstico, electrodomésticos y otros objetos afines sobre y fuera de camiones o camionetas para transportarlos de un lugar a otro."},{"consecutivo":3,"texto":"Cargar, descargar y apilar mercancías, electrodomésticos y muebles en vehículos de mudanzas, almacenes o depósitos similares."},{"consecutivo":4,"texto":"Realizar actividades de manipulación, clasificación, apilamiento, pesaje, empaque y desempaque de materiales y mercancía antes de su carga o descarga en su lugar de destino y vehículos de mudanza de acuerdo con instrucciones."},{"consecutivo":5,"texto":"Realizar labores rutinarias como abrir contenedores y guacales, diligenciar órdenes de mudanza, ayudar con el inventario, pesaje y revisión de los bienes transportados."},{"consecutivo":6,"texto":"Ayudar a camioneros y chóferes a cargar, descargar, apilar y clasificar bienes transportados en vehículos hasta su destino final."},{"consecutivo":7,"texto":"Descarpar, poner anjeo o malla y carpar correctamente los tractocamiones que se despachan a puerto."},{"consecutivo":8,"texto":"Revisar el tráiler y verificar que las compuertas estén enganchadas y se cumplan con todas las condiciones para cargar los vehículos."},{"consecutivo":9,"texto":"Aplicar normas de seguridad y salud en el trabajo requeridas para efectuar trabajo en alturas y demás labores."},{"consecutivo":10,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"93334.001","nombre":"Auxiliar de descargue"},{"codigo":"93334.002","nombre":"Auxiliar de transporte"},{"codigo":"93334.003","nombre":"Ayudante de camión"},{"codigo":"93334.004","nombre":"Ayudante de camión de trasteos"},{"codigo":"93334.005","nombre":"Ayudante de carrotanque"},{"codigo":"93334.006","nombre":"Ayudante de transporte automotor"},{"codigo":"93334.007","nombre":"Ayudante de trasteos"},{"codigo":"93334.008","nombre":"Ayudante de vehículo de reparto"},{"codigo":"93334.009","nombre":"Cargador de camiones / Cargadora de camiones"},{"codigo":"93334.010","nombre":"Cargador de vehículos de transporte ferroviario / Cargadora de vehículos de transporte ferroviario"},{"codigo":"93334.011","nombre":"Cargador de vehículos de transporte por carretera / Cargadora de vehículos de transporte por carretera"},{"codigo":"93334.012","nombre":"Carpero de vehículos / Carpera de vehículos"},{"codigo":"93334.013","nombre":"Cotero / Cotera"},{"codigo":"93334.014","nombre":"Obrero de carga en empresas de mudanzas / Obrera de carga en empresas de mudanzas"},{"codigo":"93334.015","nombre":"Auxiliar de mudanzas"},{"codigo":"93334.016","nombre":"Auxiliar de maquinaria pesada"}],"conocimientos":[{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"43211","nombre":"Auxiliares de almacén y pesaje"},{"codigo":"83440","nombre":"Operadores de montacargas / Operadoras de montacargas"},{"codigo":"93331","nombre":"Obreros y peones de carga y descarga / Obreras y peonas de carga y descarga"},{"codigo":"93332","nombre":"Obreros y peones portuarios / Obreras y peonas portuarias"},{"codigo":"93333","nombre":"Operarios y auxiliares de rampa de transporte aéreo / Operarias y auxiliares de rampa de transporte aéreo"}],"area_principal":{"sigla":"LOTR","nombre":"Logística y transporte"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"9333*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"8492*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8622*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Surtidores de estanterías / Surtidoras de estanterías', '93340', 'Comercio, mercadeo y publicidad', 1, false, '{"codigo":"93340","nombre":"Surtidores de estanterías / Surtidoras de estanterías","descripcion":"Surten mercancías en estantes, arcones, muebles y áreas de exhibición, mantienen las existencias en buenas condiciones de orden y limpieza en almacenes, supermercados, tiendas, ventas ambulantes y otros establecimientos. Se pueden desempeñar en establecimientos de ventas al por mayor y al detal, almacenes de cadena, supermercados, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"93","nombre":"OBREROS Y PEONES DE LA MINERIA, LA CONSTRUCCION, LA INDUSTRIA MANUFACTURERA Y EL TRANSPORTE"},"subgrupo":{"codigo":"933","nombre":"Obreros y peones de transporte y almacenamiento"},"grupo_primario":{"codigo":"9334","nombre":"Surtidores de estanterías"}},"funciones":[{"consecutivo":1,"texto":"Surtir, colocar y ordenar mercancías sobre el suelo, arcones, estantes y áreas de exhibición, ubicando adelante las mercancías con fechas de caducidad más próximas."},{"consecutivo":2,"texto":"Mantener en orden las estanterías, retirando mercancías caducadas y aquellas que deban ubicarse en otras secciones."},{"consecutivo":3,"texto":"Buscar en las estanterías, almacén o cuarto de depósito los artículos o las mercancías solicitadas por los clientes."},{"consecutivo":4,"texto":"Guiar y orientar a clientes al lugar donde se encuentran localizados los artículos, los productos o las mercancías requeridas."},{"consecutivo":5,"texto":"Llevar un registro de las mercancías vendidas y buscar en el almacén, la bodega o el depósito los artículos necesarios para la reposición."},{"consecutivo":6,"texto":"Recibir, abrir, desempacar e inspeccionar la mercancía entregada por el fabricante o el distribuidor para surtir estanterías, arcones, vitrinas y áreas de exhibición."},{"consecutivo":7,"texto":"Entregar muestras y vender productos de consumo en almacenes, tiendas o puerta a puerta."},{"consecutivo":8,"texto":"Surtir, exhibir y vender mercancía en calles, aceras o eventos públicos."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"93340.001","nombre":"Ayudante de surtido"},{"codigo":"93340.002","nombre":"Llenador de existencias / Llenadora de existencias"},{"codigo":"93340.003","nombre":"Manejador de existencias / Manejadora de existencias"},{"codigo":"93340.004","nombre":"Rellenador de estanterías en supermercados / Rellenadora de estanterías en supermercados"},{"codigo":"93340.005","nombre":"Reponedor de existencias / Reponedora de existencias"},{"codigo":"93340.006","nombre":"Surtidor de abarrotes / Surtidora de abarrotes"},{"codigo":"93340.007","nombre":"Surtidor de comestibles / Surtidora de comestibles"},{"codigo":"93340.008","nombre":"Surtidor de estantería / Surtidora de estantería"},{"codigo":"93340.009","nombre":"Surtidor de mercancías / Surtidora de mercancías"},{"codigo":"93340.010","nombre":"Surtidor de mostrador / Surtidora de mostrador"},{"codigo":"93340.011","nombre":"Surtidor nocturno / Surtidora nocturna"}],"conocimientos":[{"id":"4","nombre":"Mercadotecnia y publicidad"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"33220","nombre":"Representantes comerciales"},{"codigo":"52110","nombre":"Vendedores en quioscos y puestos de mercado / Vendedoras en quioscos y puestos de mercado"},{"codigo":"52420","nombre":"Demostradores de tiendas, almacenes y afines / Demostradoras de tiendas, almacenes y afines"},{"codigo":"93210","nombre":"Empacadores manuales / Empacadoras manuales"},{"codigo":"96250","nombre":"Recolectores de dinero y surtidores de máquinas de venta automática / Recolectoras de dinero y surtidores de máquinas de venta automática"}],"area_principal":{"sigla":"COMP","nombre":"Comercio, mercadeo y publicidad"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"9334","ciuo08_obs":"Denominaciones completas","cno_codigo":"6612*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Cocineros de comidas rápidas / Cocineras de comidas rápidas', '94110', 'Turismo, hotelería y gastronomía', 1, false, '{"codigo":"94110","nombre":"Cocineros de comidas rápidas / Cocineras de comidas rápidas","descripcion":"Preparan, cocinan y sirven una variedad de alimentos y bebidas que requieren procesos de preparación sencillos y la utilización de un pequeño número de ingredientes. Asimismo, pueden tomar los pedidos a los clientes y servirles en mostradores, mesas o para llevar. Se pueden desempeñar en restaurantes, cafeterías, negocios ambulantes de comidas, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"94","nombre":"AYUDANTES DE PREPARACION DE ALIMENTOS"},"subgrupo":{"codigo":"941","nombre":"Ayudantes de preparación de alimentos"},"grupo_primario":{"codigo":"9411","nombre":"Cocineros de comidas rápidas"}},"funciones":[{"consecutivo":1,"texto":"Preparar, acondicionar bebidas y alimentos sencillos o precocidos como empanadas, sándwiches, hamburguesas, pizzas, entre otros, de acuerdo con procedimientos técnicos y estándares del establecimiento."},{"consecutivo":2,"texto":"Efectuar operaciones de alistamiento como lavar, cortar, medir y mezclar alimentos para su cocción de acuerdo con procedimientos técnicos y estándares del establecimiento."},{"consecutivo":3,"texto":"Manejar equipos de cocción de proceso único y en grandes cantidades como parrillas, freidoras y planchas para preparar y recalentar alimentos."},{"consecutivo":4,"texto":"Limpiar áreas y superficies de preparación de alimentos y bebidas, así como aprovisionar utensilios y materiales de cocina según manual de procedimientos de limpieza y desinfección."},{"consecutivo":5,"texto":"Atender servicio, tomar órdenes de alimentos y bebidas, hacer entrega de pedidos tanto en el sitio de consumo como en locales especializados de comidas rápidas o de comidas para llevar según protocolos y estándares del establecimiento."},{"consecutivo":6,"texto":"Ordenar y tomar la entrega de ingredientes, utensilios y equipos necesarios para la elaboración de comidas rápidas."},{"consecutivo":7,"texto":"Recibir y registrar los pagos en la caja según políticas del establecimiento y normas de higiene."},{"consecutivo":8,"texto":"Cumplir las normas de higiene, salud y de seguridad en las zonas de trabajo y verificar que las comidas preparadas cumplan los requisitos de calidad y cantidad."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"94110.001","nombre":"Ayudante en comidas rápidas"},{"codigo":"94110.002","nombre":"Cocinero de comidas rápidas / Cocinera de comidas rápidas"},{"codigo":"94110.003","nombre":"Cocinero de platos rápidos en restaurantes / Cocinera de platos rápidos en restaurantes"},{"codigo":"94110.004","nombre":"Preparador de comidas rápidas / Preparadora de comidas rápidas"},{"codigo":"94110.005","nombre":"Preparador de hamburguesas / Preparadora de hamburguesas"},{"codigo":"94110.006","nombre":"Preparador de papa fritas / Preparadora de papa fritas"},{"codigo":"94110.007","nombre":"Preparador de pizzas / Preparadora de pizzas"}],"conocimientos":[{"id":"37","nombre":"Manipulación de alimentos"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"34340","nombre":"Chefs"},{"codigo":"51201","nombre":"Cocineros / Cocineras"},{"codigo":"52460","nombre":"Vendedores de comidas en mostrador / Vendedoras de comidas en mostrador"}],"area_principal":{"sigla":"TUHG","nombre":"Turismo, hotelería y gastronomía"},"areas_complementarias":[{"sigla":"COMP","nombre":"Comercio, mercadeo y publicidad"}],"equivalencias":[{"ciuo08_codigo":"9411","ciuo08_obs":"Denominaciones completas","cno_codigo":"6621*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Ayudantes de cocina', '94120', 'Turismo, hotelería y gastronomía', 1, false, '{"codigo":"94120","nombre":"Ayudantes de cocina","descripcion":"Limpian áreas de cocina, lavan platos, equipos de cocina, preparan ingredientes, retiran mesas y realizan otras labores de apoyo a los trabajadores encargados de preparar y servir alimentos y bebidas. Se pueden desempeñar en restaurantes, cafeterías, hoteles, hospitales, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"94","nombre":"AYUDANTES DE PREPARACION DE ALIMENTOS"},"subgrupo":{"codigo":"941","nombre":"Ayudantes de preparación de alimentos"},"grupo_primario":{"codigo":"9412","nombre":"Ayudantes de cocina"}},"funciones":[{"consecutivo":1,"texto":"Ordenar materias primas, productos e insumos en refrigeradores, alacenas y otras áreas de almacenamiento de acuerdo con protocolos de conservación y manipulación de alimentos y bebidas."},{"consecutivo":2,"texto":"Lavar vajillas, platos y utensilios de cocina, ponerlos en su lugar y montarlos para ser servidos."},{"consecutivo":3,"texto":"Limpiar, higienizar y desinfectar equipos, cocinas, plantas, áreas de preparación y servicio de alimentos, de acuerdo con procedimientos técnicos."},{"consecutivo":4,"texto":"Desempacar, alistar, pesar y verificar suministros, ponerlos en envases y guardarlos en frigoríficos, alacenas y otras zonas de almacenamiento de acuerdo con procedimientos técnicos."},{"consecutivo":5,"texto":"Clasificar, separar, manipular y aprovisionar productos, insumos e ingredientes para la elaboración de alimentos y bebidas, según protocolos de higiene, limpieza y desinfección."},{"consecutivo":6,"texto":"Medir, humedecer y mezclar ingredientes en máquinas mezcladoras, moledoras, tanques, tolvas, entre otros."},{"consecutivo":7,"texto":"Ayudar a cocineros y chefs en actividades como lavar, pelar, picar, cortar, medir, mezclar, tostar y calentar ingredientes relacionados con la preparación de alimentos."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"94120.001","nombre":"Auxiliar de cocina"},{"codigo":"94120.002","nombre":"Ayudante de cocina"},{"codigo":"94120.003","nombre":"Ayudante de cocina domestica"},{"codigo":"94120.004","nombre":"Ayudante de cocina no domestica"},{"codigo":"94120.005","nombre":"Ayudante de cocina y cafetería"},{"codigo":"94120.006","nombre":"Ayudante de establecimientos de alimentos y bebidas"},{"codigo":"94120.007","nombre":"Ayudante de la despensa"},{"codigo":"94120.008","nombre":"Empacador de productos de panadería / Empacadora de productos de panadería"},{"codigo":"94120.009","nombre":"Lavador de platos a mano / Lavadora de platos a mano"},{"codigo":"94120.010","nombre":"Lavador de platos y utensilios / Lavadora de platos y utensilios"},{"codigo":"94120.011","nombre":"Lavaplatos"},{"codigo":"94120.012","nombre":"Manipulador de pescado en procesamiento / Manipuladora de pescado en procesamiento"},{"codigo":"94120.013","nombre":"Steward"},{"codigo":"94120.014","nombre":"Ayudante de cocina fría"}],"conocimientos":[{"id":"37","nombre":"Manipulación de alimentos"},{"id":"8","nombre":"Procesamiento de alimentos"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"34340","nombre":"Chefs"},{"codigo":"51201","nombre":"Cocineros / Cocineras"},{"codigo":"81600","nombre":"Operadores de máquinas para elaborar alimentos y productos afines / Operadoras de máquinas para elaborar alimentos y productos afines"}],"area_principal":{"sigla":"TUHG","nombre":"Turismo, hotelería y gastronomía"},"areas_complementarias":[{"sigla":"ETAL","nombre":"Elaboración y transformación de alimentos"}],"equivalencias":[{"ciuo08_codigo":"9112*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"6621*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"9412","ciuo08_obs":"Denominaciones completas","cno_codigo":"9615*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Trabajadores ambulantes de servicios y afines / Trabajadoras ambulantes de servicios y afines', '95100', 'Servicios Personales y a la Comunidad', 1, false, '{"codigo":"95100","nombre":"Trabajadores ambulantes de servicios y afines / Trabajadoras ambulantes de servicios y afines","descripcion":"Proporcionan una variedad de servicios elementales en calles y otros lugares públicos; limpian zapatos; lavan ventanas de automóviles; hacen mandados o recados; distribuyen folletos, cuidan bienes y proveen otros servicios donde se encuentre el cliente. Se pueden desempeñar en establecimientos de ventas al por mayor y al detal, de cooperativas de trabajo asociado, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"95","nombre":"VENDEDORES AMBULANTES DE SERVICIOS Y AFINES (EXCLUYENDO COMIDAS DE PREPARACION INMEDIATA)"},"subgrupo":{"codigo":"951","nombre":"Trabajadores ambulantes de servicios y afines"},"grupo_primario":{"codigo":"9510","nombre":"Trabajadores ambulantes de servicios y afines"}},"funciones":[{"consecutivo":1,"texto":"Vocear y repartir folletos, periódicos, materiales publicitario y propaganda en la calle o lugares públicos."},{"consecutivo":2,"texto":"Exhibir en espacios urbanos, aceras o eventos públicos y abordar a la gente en la calle para ofrecerle sus servicios."},{"consecutivo":3,"texto":"Realizar por encargo mandados, compras, pago de recibos y llevar recados escritos o verbales a diferentes sitios, entre otros."},{"consecutivo":4,"texto":"Cobrar por los servicios prestados y recibir el pago inmediato."},{"consecutivo":5,"texto":"Registrar la entrada y salida de vehículos en zonas de parqueo públicos, ayudar a conductores a encontrar un lugar de estacionamiento, expedir tiquetes de parqueo y vigilar que los automóviles no sufran daños en ausencia de los conductores."},{"consecutivo":6,"texto":"Conseguir los materiales necesarios para prestar servicios de forma ambulante."},{"consecutivo":7,"texto":"Limpiar, aplicar betún, silicona u otros productos y materiales para lustrar zapatos, carteras, maletas, entre otros."},{"consecutivo":8,"texto":"Lavar y limpiar parabrisas, ventanas, farolas y espejos de automóviles de forma ambulante en semáforos, calles y vías públicas."},{"consecutivo":9,"texto":"Reparar, acondicionar y remediar en la calle sombrillas, ollas, persianas, relojes, celulares, entre otras cosas."},{"consecutivo":10,"texto":"Entregar muestras de consumo y ofrecer servicios en forma ambulante o puerta a puerta."},{"consecutivo":11,"texto":"Ayudar de forma ambulante en la orientación a personas que entran y salen de edificios, hoteles, teatros, establecimientos o similares."},{"consecutivo":12,"texto":"Prestar servicio de vigilancia ambulante a vehículos, muebles y enseres en cuadras, calles y barrios residenciales."},{"consecutivo":13,"texto":"Ordenar materiales publicitarios o de comunicación, según rutas de reparto, horarios de entrega o públicos objetivos."},{"consecutivo":14,"texto":"Mantener un adecuado control de inventario de los productos entregados para reparto."},{"consecutivo":15,"texto":"Clasificar el material a repartir para su adecuada distribución durante la jornada de trabajo."},{"consecutivo":16,"texto":"Llevar documentación y control de entregas realizadas, productos entregados o materiales no repartidos."},{"consecutivo":17,"texto":"Informar sobre estados de entregas, materiales repartidos e inconvenientes presentados durante la jornada."},{"consecutivo":18,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"95100.001","nombre":"Cuidador de carros / Cuidadora de carros"},{"codigo":"95100.002","nombre":"Distribuidor de folletos / Distribuidora de folletos"},{"codigo":"95100.003","nombre":"Embolador / Emboladora"},{"codigo":"95100.004","nombre":"Lavador de ventanas de carro en la calle / Lavadora de ventanas de carro en la calle"},{"codigo":"95100.005","nombre":"Limpiabotas"},{"codigo":"95100.006","nombre":"Limpiador ambulante de ventanas de automóviles / Limpiadora ambulante de ventanas de automóviles"},{"codigo":"95100.007","nombre":"Lustrabotas"},{"codigo":"95100.008","nombre":"Lustrador de calzado / Lustradora de calzado"},{"codigo":"95100.009","nombre":"Pegador de carteles / Pegadora de carteles"},{"codigo":"95100.010","nombre":"Pulidor de zapatos / Pulidora de zapatos"},{"codigo":"95100.011","nombre":"Recadero / Recadera"},{"codigo":"95100.012","nombre":"Repartidor de folletos en la calle / Repartidora de folletos en la calle"},{"codigo":"95100.013","nombre":"Repartidor de prensa gratuita en la calle / Repartidora de prensa gratuita en la calle"},{"codigo":"95100.014","nombre":"Repartidor de propaganda / Repartidora de propaganda"},{"codigo":"95100.015","nombre":"Vigilante de carros en la calle"},{"codigo":"95100.016","nombre":"Facilitador de zonas de parqueo pago / Facilitadora de zonas de parqueo pago"}],"conocimientos":[{"id":"4","nombre":"Mercadotecnia y publicidad"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"15","nombre":"Orientación al servicio"},{"id":"12","nombre":"Persuasión"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"52110","nombre":"Vendedores en quioscos y puestos de mercado / Vendedoras en quioscos y puestos de mercado"},{"codigo":"52210","nombre":"Comerciantes de tiendas"},{"codigo":"52230","nombre":"Vendedores y auxiliares de venta en tiendas, almacenes y afines / Vendedoras y auxiliares de venta en tiendas, almacenes y afines"},{"codigo":"52430","nombre":"Vendedores puerta a puerta / Vendedoras puerta a puerta"},{"codigo":"54142","nombre":"Vigilantes, guardas y personal operativo de seguridad privada"},{"codigo":"95200","nombre":"Vendedores ambulantes (excluyendo comidas de preparación inmediata) / Vendedoras ambulantes (excluyendo comidas de preparación inmediata)"},{"codigo":"96211","nombre":"Mandaderos, maleteros y repartidores / Mandaderas, maleteras y repartidoras"},{"codigo":"96212","nombre":"Mensajeros / Mensajeras"},{"codigo":"96291","nombre":"Auxiliares de servicios de recreación y deporte"}],"area_principal":{"sigla":"SEPC","nombre":"Servicios Personales y a la Comunidad"},"areas_complementarias":[{"sigla":"COMP","nombre":"Comercio, mercadeo y publicidad"},{"sigla":"LOTR","nombre":"Logística y transporte"},{"sigla":"SEGU","nombre":"Seguridad"}],"equivalencias":[{"ciuo08_codigo":"9510","ciuo08_obs":"Denominaciones completas","cno_codigo":"6612*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"6644*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Vendedores ambulantes (excluyendo comidas de preparación inmediata) / Vendedoras ambulantes (excluyendo comidas de preparación inmediata)', '95200', 'Comercio, mercadeo y publicidad', 1, true, '{"codigo":"95200","nombre":"Vendedores ambulantes (excluyendo comidas de preparación inmediata) / Vendedoras ambulantes (excluyendo comidas de preparación inmediata)","descripcion":"Venden en forma ambulante bienes y mercancías (excluyendo alimentos de preparación inmediata) en calles, aceras, vías, lugares públicos, entre otros. Se pueden desempeñar en establecimientos de ventas al por mayor y al detal, cooperativas de trabajo asociado, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"95","nombre":"VENDEDORES AMBULANTES DE SERVICIOS Y AFINES (EXCLUYENDO COMIDAS DE PREPARACION INMEDIATA)"},"subgrupo":{"codigo":"952","nombre":"Vendedores ambulantes (excluyendo comidas de preparación inmediata)"},"grupo_primario":{"codigo":"9520","nombre":"Vendedores ambulantes (excluyendo comidas de preparación inmediata)"}},"funciones":[{"consecutivo":1,"texto":"Exhibir, pregonar, ofrecer y vender mercancías en calles, aceras, vías, puerta a puerta o en eventos públicos."},{"consecutivo":2,"texto":"Mostrar mercancías, entregar muestras, atraer la atención de clientes y vender productos de forma ambulante o puerta a puerta."},{"consecutivo":3,"texto":"Comprar, recibir o fabricar artículos simples con el fin de venderlos posteriormente en forma ambulante."},{"consecutivo":4,"texto":"Cargar y descargar cestas, bandejas, carros de mano, bicicletas, triciclos u otros vehículos para llevar mercancías a los sitios de venta en lugares públicos, calles, aceras, entre otros."},{"consecutivo":5,"texto":"Cobrar de inmediato las ventas realizadas de forma ambulante."},{"consecutivo":6,"texto":"Vocear periódico, vender lotería, revistas, libros, esferos, entre otros, y repartir propaganda de forma ambulante."},{"consecutivo":7,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"95200.001","nombre":"Buhonero / Buhonera"},{"codigo":"95200.003","nombre":"Lotero ambulante / Lotera ambulante"},{"codigo":"95200.004","nombre":"Paletero vendedor ambulante / Paletera vendedora ambulante"},{"codigo":"95200.006","nombre":"Vendedor ambulante de periódicos / Vendedora ambulante de periódicos"},{"codigo":"95200.007","nombre":"Vendedor ambulante de productos no comestibles / Vendedora ambulante de productos no comestibles"},{"codigo":"95200.009","nombre":"Vendedor de chance callejero / Vendedora de chance callejero"},{"codigo":"95200.010","nombre":"Vendedor de lotería ambulante / Vendedora de lotería ambulante"},{"codigo":"95200.012","nombre":"Vendedor de periódicos ambulante / Vendedora de periódicos ambulante"},{"codigo":"95200.013","nombre":"Voceador de periódicos / Voceadora de periódicos"}],"conocimientos":[{"id":"4","nombre":"Mercadotecnia y publicidad"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"2","nombre":"Escucha activa"},{"id":"15","nombre":"Orientación al servicio"},{"id":"12","nombre":"Persuasión"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"52110","nombre":"Vendedores en quioscos y puestos de mercado / Vendedoras en quioscos y puestos de mercado"},{"codigo":"52120","nombre":"Vendedores ambulantes de alimentos preparados para consumo inmediato / Vendedoras ambulantes de alimentos preparados para consumo inmediato"},{"codigo":"52230","nombre":"Vendedores y auxiliares de venta en tiendas, almacenes y afines / Vendedoras y auxiliares de venta en tiendas, almacenes y afines"},{"codigo":"52430","nombre":"Vendedores puerta a puerta / Vendedoras puerta a puerta"},{"codigo":"95100","nombre":"Trabajadores ambulantes de servicios y afines / Trabajadoras ambulantes de