  ('rol_cuoc', 'Recolectores de basura y material reciclable / Recolectoras de basura y material reciclable', '96110', 'Conservación, protección y saneamiento ambiental', 1, false, '{"codigo":"96110","nombre":"Recolectores de basura y material reciclable / Recolectoras de basura y material reciclable","descripcion":"Realizan actividades de recolección, recuperación, clasificación y transformación de residuos sólidos que serán sometidos posteriormente a procesos de reutilización, reciclaje y venta. Se pueden desempeñar en empresas de reciclaje, agremiaciones de recicladores, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"96","nombre":"RECOLECTORES DE DESECHOS Y OTRAS OCUPACIONES ELEMENTALES"},"subgrupo":{"codigo":"961","nombre":"Recolectores de desechos"},"grupo_primario":{"codigo":"9611","nombre":"Recolectores de basura y material reciclable"}},"funciones":[{"consecutivo":1,"texto":"Recuperar, recolectar y clasificar los residuos sólidos aprovechables, de acuerdo con condiciones del servicio público y especificaciones de clasificación y aprovechamiento."},{"consecutivo":2,"texto":"Recoger basura, desechos y material reciclable de forma manual y depositarlo en contenedores, canecas y camiones."},{"consecutivo":3,"texto":"Cargar, descargar y vaciar canecas, recipientes, bolsas de basura, camiones y contenedores donde se deposite el material aprovechable y de rechazo."},{"consecutivo":4,"texto":"Contactar compradores para venderles residuos aprovechables para la reincorporación de estos materiales a la cadena productiva."},{"consecutivo":5,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"96110.001","nombre":"Basurero / Basurera"},{"codigo":"96110.002","nombre":"Cargador de camión de la basura / Cargadora de camión de la basura"},{"codigo":"96110.003","nombre":"Cartonero reciclador / Cartonera recicladora"},{"codigo":"96110.004","nombre":"Obrero de recolección de desechos / Obrera de recolección de desechos"},{"codigo":"96110.005","nombre":"Obrero recolector de desechos / Obrera recolectora de desechos"},{"codigo":"96110.006","nombre":"Patiero de recolección de desechos de hidrocarburos / Patiera de recolección de desechos de hidrocarburos"},{"codigo":"96110.007","nombre":"Recolector de basura / Recolectora de basura"},{"codigo":"96110.008","nombre":"Recolector de material de reciclaje / Recolectora de material de reciclaje"},{"codigo":"96110.009","nombre":"Recuperador de oficio / Recuperadora de oficio"}],"conocimientos":[{"id":"86","nombre":"Saneamiento de la comunidad"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"31","nombre":"Gestión de recursos materiales"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"25","nombre":"Manejo de imprevistos"},{"id":"37","nombre":"Proactividad"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"93320","nombre":"Conductores de vehículos y maquinaria de tracción animal / Conductoras de vehículos y maquinaria de tracción animal"},{"codigo":"96120","nombre":"Clasificadores de desechos / Clasificadoras de desechos"}],"area_principal":{"sigla":"CPSA","nombre":"Conservación, protección y saneamiento ambiental"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"9611","ciuo08_obs":"Denominaciones completas","cno_codigo":"6633*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"7612*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"","ciuo08_obs":"","cno_codigo":"8621*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Clasificadores de desechos / Clasificadoras de desechos', '96120', 'Conservación, protección y saneamiento ambiental', 1, false, '{"codigo":"96120","nombre":"Clasificadores de desechos / Clasificadoras de desechos","descripcion":"Recogen en empresas, vertederos, inmuebles o lugares públicos elementos como papel, cartón, vidrio, chatarra, plástico, entre otros, que se pueden reutilizar o aprovechar; igualmente, seleccionan, clasifican y venden estos materiales para someterlos a procesos de reutilización y reciclaje. Se pueden desempeñar en empresas de reciclaje, cooperativas de recicladores, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"96","nombre":"RECOLECTORES DE DESECHOS Y OTRAS OCUPACIONES ELEMENTALES"},"subgrupo":{"codigo":"961","nombre":"Recolectores de desechos"},"grupo_primario":{"codigo":"9612","nombre":"Clasificadores de desechos"}},"funciones":[{"consecutivo":1,"texto":"Recolectar y clasificar cartón, papel, vidrio, plástico, aluminio, metal y otros materiales de reciclaje, por tipo de composición."},{"consecutivo":2,"texto":"Contactar a compradores potenciales para vender materiales recolectados, clasificados, reciclables o reutilizables."},{"consecutivo":3,"texto":"Identificar y apartar los artículos de mobiliario, equipo, maquinaria o componentes que son apropiados para la reparación o reutilización."},{"consecutivo":4,"texto":"Seleccionar y recoger en calles, sitios de acumulación de desechos, vertederos, edificaciones, domicilios particulares, locales comerciales e industriales y lugares públicos para recuperar artículos y materiales reciclables o reutilizables como cartón, vidrio, revistas, papel, latas, telas, aluminio, hierro, cables, entre otros."},{"consecutivo":5,"texto":"Alistar en diferentes formas de embalaje el material reutilizable clasificado y recolectado para su entrega en lugares de recepción como depósitos, bodegas, chatarrerías, entre otros."},{"consecutivo":6,"texto":"Alistar, seleccionar y colocar los materiales para reciclaje en compartimentos o contenedores especiales para su almacenamiento o transporte."},{"consecutivo":7,"texto":"Transportar los artículos y materiales reciclables de forma manual o utilizando vehículos no motorizados, accionados a brazo, pedal o de tracción animal."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"96120.001","nombre":"Chatarrero / Chatarrera"},{"codigo":"96120.002","nombre":"Clasificador de basura / Clasificadora de basura"},{"codigo":"96120.003","nombre":"Clasificador de desechos / Clasificadora de desechos"},{"codigo":"96120.004","nombre":"Clasificador de reciclaje / Clasificadora de reciclaje"},{"codigo":"96120.005","nombre":"Comerciante de chatarra"},{"codigo":"96120.006","nombre":"Reciclador / Recicladora"},{"codigo":"96120.007","nombre":"Seleccionador de reciclaje / Seleccionadora de reciclaje"},{"codigo":"96120.008","nombre":"Selector de residuos / Selectora de residuos"}],"conocimientos":[{"id":"59","nombre":"Ciencias del medio ambiente"},{"id":"77","nombre":"Materiales (vidrio, papel, plástico y madera)"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"19","nombre":"Selección de equipo"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"96110","nombre":"Recolectores de basura y material reciclable / Recolectoras de basura y material reciclable"},{"codigo":"96130","nombre":"Ayudantes y operarios de barrido y limpieza de vías y áreas públicas / Ayudantes y operarias de barrido y limpieza de vías y áreas públicas"}],"area_principal":{"sigla":"CPSA","nombre":"Conservación, protección y saneamiento ambiental"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"9612*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"6633*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Ayudantes y operarios de barrido y limpieza de vías y áreas públicas / Ayudantes y operarias de barrido y limpieza de vías y áreas públicas', '96130', 'Conservación, protección y saneamiento ambiental', 1, false, '{"codigo":"96130","nombre":"Ayudantes y operarios de barrido y limpieza de vías y áreas públicas / Ayudantes y operarias de barrido y limpieza de vías y áreas públicas","descripcion":"Realizan varias labores básicas y rutinarias relacionadas con barrer, lavar, deshierbar, desarenar, limpiar y recoger residuos y desperdicios en calles, sumideros, parques, aeropuertos, estaciones de transporte y otros lugares públicos. Se pueden desempeñar en empresas de servicios públicos, empresas de aseo, cooperativas de trabajo asociado, entre otros","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"96","nombre":"RECOLECTORES DE DESECHOS Y OTRAS OCUPACIONES ELEMENTALES"},"subgrupo":{"codigo":"961","nombre":"Recolectores de desechos"},"grupo_primario":{"codigo":"9613","nombre":"Ayudantes y operarios de barrido y limpieza de vías y áreas públicas"}},"funciones":[{"consecutivo":1,"texto":"Barrer calles, parques, vías, aeropuertos, estaciones de transporte, lugares públicos, entre otros y depositar los residuos, basura y desperdicios en recipientes, canecas, camiones o similares."},{"consecutivo":2,"texto":"Barrer, recoger basura y mantener limpias calles, vías, caminos de acceso, andenes, playas, áreas públicas y otras superficies peatonales, trabajando como parte de una cuadrilla o individualmente."},{"consecutivo":3,"texto":"Manipular herramientas y equipos manuales móviles en labores de limpieza y barrido de calles, vías, caminos de acceso, andenes, playas, áreas públicas y otras superficies peatonales."},{"consecutivo":4,"texto":"Golpear alfombras, tapetes, cubre tapices y demás mobiliario para quitar el polvo y efectuar labores de limpieza y barrido."},{"consecutivo":5,"texto":"Lavar áreas públicas como calles, vías, caminos, andenes y otras superficies."},{"consecutivo":6,"texto":"Verificar la ruta que debe atender y alistar el plano respectivo."},{"consecutivo":7,"texto":"Retirar maleza y deshierbar vías, caminos, andenes y otras áreas públicas."},{"consecutivo":8,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"96130.001","nombre":"Barrendero / Barrendera"},{"codigo":"96130.002","nombre":"Barrendero de áreas públicas / Barrendera de áreas públicas"},{"codigo":"96130.003","nombre":"Barrendero de calles / Barrendera de calles"},{"codigo":"96130.004","nombre":"Barrendero de parques / Barrendera de parques"},{"codigo":"96130.005","nombre":"Escobita"},{"codigo":"96130.006","nombre":"Escobita barrendero / Escobita barrendera"},{"codigo":"96130.007","nombre":"Limpiador de parques / Limpiadora de parques"},{"codigo":"96130.008","nombre":"Rastrillador de playa / Rastrilladora de playa"},{"codigo":"96130.009","nombre":"Ayudante de mantenimiento de áreas públicas"},{"codigo":"96130.010","nombre":"Ayudante de mantenimiento de redes de acueducto"},{"codigo":"96130.011","nombre":"Ayudante de mantenimiento de redes de alcantarillado"},{"codigo":"96130.012","nombre":"Operario de aseo de áreas públicas / Operaria de aseo de áreas públicas"},{"codigo":"96130.013","nombre":"Operario de barrido / Operaria de barrido"},{"codigo":"96130.014","nombre":"Operario de barrido y limpieza de áreas públicas / Operaria de barrido y limpieza de áreas públicas"},{"codigo":"96130.015","nombre":"Operario de barrido y limpieza vial / Operaria de barrido y limpieza vial"},{"codigo":"96130.016","nombre":"Operario de lavado de áreas públicas / Operaria de lavado de áreas públicas"},{"codigo":"96130.017","nombre":"Operario de limpieza de alcantarillas / Operaria de limpieza de alcantarillas"},{"codigo":"96130.018","nombre":"Operario de limpieza de áreas públicas / Operaria de limpieza de áreas públicas"}],"conocimientos":[{"id":"85","nombre":"Segurida