  ('rol_cuoc', 'Mandaderos, maleteros y repartidores / Mandaderas, maleteras y repartidoras', '96211', 'Logística y transporte', 1, false, '{"codigo":"96211","nombre":"Mandaderos, maleteros y repartidores / Mandaderas, maleteras y repartidoras","descripcion":"Realizan funciones de apoyo en oficinas, establecimientos comerciales y afines; cargan el equipaje de huéspedes o viajeros en hoteles, aeropuertos, terminales de transporte, entre otros; entregan paquetes y otros artículos a sus destinatarios desplazándose dentro de un mismo establecimiento, o de un lugar a otro. Se pueden desempeñar en hoteles, compañías de transporte, terminales de transporte, aeropuertos, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"96","nombre":"RECOLECTORES DE DESECHOS Y OTRAS OCUPACIONES ELEMENTALES"},"subgrupo":{"codigo":"962","nombre":"Otras ocupaciones elementales"},"grupo_primario":{"codigo":"9621","nombre":"Mensajeros, mandaderos, maleteros y repartidores"}},"funciones":[{"consecutivo":1,"texto":"Entregar mercancías, paquetes y objetos dentro de un mismo establecimiento y desplazándose de un lugar a otro a domicilio."},{"consecutivo":2,"texto":"Recibir, marcar, gestionar y distribuir equipaje en hoteles, clubes, aeropuertos, terminales de transporte, entre otros, completando y adjuntando el comprobante de reclamación de equipajes."},{"consecutivo":3,"texto":"Acompañar los huéspedes a sus habitaciones, cargar sus equipajes y entregarlos en estaciones de transporte, aeropuertos, vehículos transportadores, entre otros."},{"consecutivo":4,"texto":"Recibir, guardar y devolver prendas, paquetes y similares a las personas que entran y salen de edificios, hoteles, teatros y establecimientos similares."},{"consecutivo":5,"texto":"Clasificar, programar y seguir los elementos que se entregarán de acuerdo con el trayecto más eficiente y la ruta de entrega."},{"consecutivo":6,"texto":"Distribuir los artículos que los clientes envían a distintas empresas, tiendas, domicilios particulares y otros lugares, o que reciben de dichas entidades y lugares."},{"consecutivo":7,"texto":"Entregar periódicos, directorios telefónicos y otros artículos similares dentro de un mismo establecimiento y desplazándose de un lugar a otro a domicilio."},{"consecutivo":8,"texto":"Operar ascensores aplicando procedimientos establecidos para transportar y facilitar el acceso de personas y carga."},{"consecutivo":9,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"96211.001","nombre":"Ascensorista"},{"codigo":"96211.002","nombre":"Auxiliar de ascensor"},{"codigo":"96211.003","nombre":"Botones"},{"codigo":"96211.004","nombre":"Equipajero / Equipajera"},{"codigo":"96211.005","nombre":"Maletero / Maletera"},{"codigo":"96211.006","nombre":"Maletero de hotel / Maletera de hotel"},{"codigo":"96211.007","nombre":"Mandadero / Mandadera"},{"codigo":"96211.008","nombre":"Mandadero de tienda / Mandadera de tienda"},{"codigo":"96211.009","nombre":"Operario de ascensor / Operaria de ascensor"},{"codigo":"96211.010","nombre":"Repartidor de documentos / Repartidora de documentos"},{"codigo":"96211.011","nombre":"Repartidor de domicilios / Repartidora de domicilios"},{"codigo":"96211.012","nombre":"Repartidor de folletos / Repartidora de folletos"},{"codigo":"96211.013","nombre":"Repartidor de periódico en establecimientos / Repartidora de periódico en establecimientos"},{"codigo":"96211.014","nombre":"Repartidor de prensa en establecimientos / Repartidora de prensa en establecimientos"},{"codigo":"96211.015","nombre":"Repartidor de periódicos / Repartidora de periódicos"}],"conocimientos":[{"id":"85","nombre":"Seguridad y salud en el trabajo"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"37","nombre":"Proactividad"},{"id":"10","nombre