  ('rol_cuoc', 'Mensajeros / Mensajeras', '96212', 'Logística y transporte', 1, false, '{"codigo":"96212","nombre":"Mensajeros / Mensajeras","descripcion":"Llevan mensajes, recogen y distribuyen correo, cartas, paquetes, encomiendas y los entregan a sus destinatarios desplazándose dentro de un mismo establecimiento o de un establecimiento a otro. Se pueden desempeñar en empresas de correo, mensajería, establecimientos del sector público, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"96","nombre":"RECOLECTORES DE DESECHOS Y OTRAS OCUPACIONES ELEMENTALES"},"subgrupo":{"codigo":"962","nombre":"Otras ocupaciones elementales"},"grupo_primario":{"codigo":"9621","nombre":"Mensajeros, mandaderos, maleteros y repartidores"}},"funciones":[{"consecutivo":1,"texto":"Recoger, distribuir y entregar mensajes, cartas, documentos, comunicaciones, paquetes, encomiendas, cheques, entre otros, y asistir en actividades de mensajería postal."},{"consecutivo":2,"texto":"Entregar periódicos, encomiendas, directorios telefónicos y otros artículos similares en residencias y empresas."},{"consecutivo":3,"texto":"Dejar nota del correo que no pudo ser entregado y devolverlo al sitio donde puede ser recogido."},{"consecutivo":4,"texto":"Organizar y clasificar elementos y correo que será entregado por direcciones de acuerdo con la ruta respectiva."},{"consecutivo":5,"texto":"Planear y seguir el trayecto más eficiente en la entrega de correo y llevar registro de los documentos entregados y recibidos."},{"consecutivo":6,"texto":"Recoger y entregar mensajes, correspondencia, paquetes y otros objetos dentro de un mismo establecimiento o desplazándose de un establecimiento a otro en rutas establecidas."},{"consecutivo":7,"texto":"Distribuir la correspondencia que los clientes envían a empresas, tiendas, domicilios y otros lugares, o que reciben de dichas entidades o personas."},{"consecutivo":8,"texto":"R