  ('rol_cuoc', 'Personas que realizan trabajos varios', '96220', 'Servicios Personales y a la Comunidad', 1, false, '{"codigo":"96220","nombre":"Personas que realizan trabajos varios","descripcion":"Ayudan a realizar labores sencillas de reparación manual de plomería, electricidad, limpieza, pintura y mantenimiento de edificios, terrenos e instalaciones, de acuerdo con instrucciones recibidas. Se pueden desempeñar en conjuntos residenciales, hoteles, empresas manufactureras, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"96","nombre":"RECOLECTORES DE DESECHOS Y OTRAS OCUPACIONES ELEMENTALES"},"subgrupo":{"codigo":"962","nombre":"Otras ocupaciones elementales"},"grupo_primario":{"codigo":"9622","nombre":"Personas que realizan trabajos varios"}},"funciones":[{"consecutivo":1,"texto":"Realizar reparaciones menores de ventanas, paneles, puertas, vallas, cercados, barbacoas, mesas de picnic, estanterías, armarios, entre otros, de acuerdo con instrucciones recibidas."},{"consecutivo":2,"texto":"Medir y marcar guías para la instalación de puertas, ventanas, barandillas y pasamanos utilizando herramientas manuales de acuerdo con instrucciones."},{"consecutivo":3,"texto":"Reemplazar artículos defectuosos de plomería y electricidad como bombillas, lámparas, interruptores, extractores, grifos, entre otros, usando herramientas de uso manual, de acuerdo con instrucciones recibidas."},{"consecutivo":4,"texto":"Alistar, reparar y pintar de forma manual o con equipos simples superficies interiores y exteriores, como paredes, techos, cielos rasos, vallas y cercas, de acuerdo con instrucciones recibidas."},{"consecutivo":5,"texto":"Cargar, descargar y almacenar carbón, madera y otros materiales en sótanos, carboneras y bodegas de hogares o establecimientos, de acuerdo con instrucciones recibidas."},{"consecutivo":6,"texto":"Realizar otras labores elementales como limpiar, ordenar y adecua