  ('rol_cuoc', 'Recolectores de dinero y surtidores de máquinas de venta automática / Recolectoras de dinero y surtidores de máquinas de venta automática', '96250', 'Logística y transporte', 1, false, '{"codigo":"96250","nombre":"Recolectores de dinero y surtidores de máquinas de venta automática / Recolectoras de dinero y surtidores de máquinas de venta automática","descripcion":"Reabastecen máquinas de venta automática con artículos y productos para la venta, del mismo modo, recogen y suministran dinero en parquímetros, teléfonos, máquinas dispensadoras y otros aparatos similares. Se pueden desempeñar en casinos, almacenes de cadena, estaciones de servicio, parqueaderos, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"96","nombre":"RECOLECTORES DE DESECHOS Y OTRAS OCUPACIONES ELEMENTALES"},"subgrupo":{"codigo":"962","nombre":"Otras ocupaciones elementales"},"grupo_primario":{"codigo":"9625","nombre":"Recolectores de dinero y surtidores de máquinas de venta automática"}},"funciones":[{"consecutivo":1,"texto":"Reabastecer máquinas de venta automática con productos de acuerdo con especificaciones técnicas."},{"consecutivo":2,"texto":"Verificar las existencias y fecha de caducidad de productos y mercancías depositadas en máquinas dispensadoras de venta automática."},{"consecutivo":3,"texto":"Suministrar y recoger monedas y dinero depositado en parquímetros, teléfonos y cajas de máquinas expendedoras automáticas."},{"consecutivo":4,"texto":"Mantener registros de las mercancías distribuidas y el dinero recaudado en parquímetros, teléfonos y máquinas expendedoras de venta automática."},{"consecutivo":5,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"96250.001","nombre":"Distribuidor de dinero en cajeros automáticos / Distribuidora de dinero en cajeros automáticos"},{"codigo":"96250.002","nombre":"Recolector de dinero de aparatos de venta automática / Reco