  ('rol_cuoc', 'Lectores de medidores / Lectoras de medidores', '96260', 'Logística y transporte', 1, false, '{"codigo":"96260","nombre":"Lectores de medidores / Lectoras de medidores","descripcion":"Observan, anotan, registran y verifican datos relacionados con el consumo de gas, electricidad o agua mediante la lectura periódica de medidores, del mismo modo, verifican el flujo vehicular, peatonal y de pasajeros, donde se requiera. Se pueden desempeñar en empresas de servicios públicos, departamentos gubernamentales, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"96","nombre":"RECOLECTORES DE DESECHOS Y OTRAS OCUPACIONES ELEMENTALES"},"subgrupo":{"codigo":"962","nombre":"Otras ocupaciones elementales"},"grupo_primario":{"codigo":"9626","nombre":"Lectores de medidores"}},"funciones":[{"consecutivo":1,"texto":"Observar y registrar información sobre flujos de tráfico vehicular, peatonal y similar."},{"consecutivo":2,"texto":"Leer y registrar los consumos en medidores de gas, electricidad y agua de instalaciones domiciliarias."},{"consecutivo":3,"texto":"Seguir trayectos preestablecidos para realizar lectura de medidores y aparatos registradores de tráfico vehicular."},{"consecutivo":4,"texto":"Verificar lecturas de medidores en los casos donde el consumo parece ser anormal y registrar las posibles razones de las fluctuaciones."},{"consecutivo":5,"texto":"Inspeccionar medidores de servicios públicos para detectar conexiones no autorizadas, defectos y daños tales como alteraciones, sellos rotos, entre otros."},{"consecutivo":6,"texto":"Revisar la información registrada en la lectura de aparatos medidores para saber si está completa y exacta."},{"consecutivo":7,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"96260.001","nombre":"Lector de contadores de servicios públicos / Lectora de contadores de servicios públicos"},{"codigo":"96260.002","nombre":"Lector de medidores / Lectora de medidores"},{"codigo":"96260.003","nombre":"Lector de medidores de servicios públicos / Lectora de medidores de servicios públicos"},{"codigo":"96260.004","nombre":"Registrador de medidores de tráfico vehicular / Registradora de medidores de tráfico vehicular"},{"codigo":"96260.005","nombre":"Registrador de tráfico vehicular / Registradora de tráfico vehicular"}],"conocimientos":[{"id":"85","nombre":"Seguridad y salud en el trabajo"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"37","nombre":"Proactividad"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"41321","nombre":"Grabadores de datos / Grabadoras de datos"}],"area_principal":{"sigla":"LOTR","nombre":"Logística y transporte"},"areas_complementarias":[],"equivalencias":[{"ciuo08_codigo":"9626","ciuo08_obs":"Denominaciones completas","cno_codigo":"1354*","cno_obs":"Denominaciones parciales"}]}'::jsonb),
  ('rol_cuoc', 'Auxiliares de servicios de recreación y deporte', '96291', 'Actividades físicas, deportivas y recreativas', 1, false, '{"codigo":"96291","nombre":"Auxiliares de servicios de recreación y deporte","descripcion":"Ayudan a clientes a encontrar asiento o ubicación en eventos de entretenimiento, reciben y entregan prendas y artículos personales de clientes en guardarropas; emiten y cobran entradas de admisión, tiquetes, pases, estacionamientos y vigilan el uso de aparatos, equipos e instalaciones de recreación y deporte. Se pueden desempeñar en parques de diversiones, estadios, billares, boleras, campos de golf, club de tenis, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"96","nombre":"RECOLECTORES DE DESECHOS Y OTRAS OCUPACIONES ELEMENTALES"},"subgrupo":{"codigo":"962","nombre":"Otras ocupaciones elementales"},"grupo_primario":{"codigo":"9629","nombre":"Otras ocupaciones elementales no clasificadas en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Orientar a los clientes en el uso de servicios de recreación y deporte, sanitarios, puestos de venta, teléfonos, entre otros."},{"consecutivo":2,"texto":"Guiar y ayudar a clientes en casos de emergencia, prestarles asistencia y facilitarles instrucciones en los sitios de recreación y deporte."},{"consecutivo":3,"texto":"Calcular y cobra tarifas de aparcamiento a clientes y orientar a los conductores de vehículos hacia las zonas de aparcamiento disponibles."},{"consecutivo":4,"texto":"Registrar la entrada y salida de vehículos a parqueaderos, expedir tiquetes de parqueo, indicar la ubicación y patrullar por zonas de aparcamiento para prevenir robos o daños."},{"consecutivo":5,"texto":"Recibir tiquetes de entrada y admitir visitantes a espectáculos de recreación y deporte, acomodar a las personas en sus sillas y asegurar cinturones, barras de seguridad y elementos de protección."},{"consecutivo":6,"texto":"Vender y recoger distintivos de identidad, boletos y pases de entrada a los clientes en eventos de recreación y deporte."},{"consecutivo":7,"texto":"Examinar distintivos de identidad, billetes y pases para verificar su autenticidad, aplicando criterios técnicos como el color o fecha de expedición. Asignar vestuarios, zapatos, cabinas, armarios, equipos deportivos, entre otros y diligenciar planillas de puntaje a los clientes de establecimientos de recreación y deporte."},{"consecutivo":8,"texto":"Programar el uso de campos de golf, pistas de bolos, canchas de tenis, gimnasios, clubes y demás instalaciones recreativas y deportivas."},{"consecutivo":9,"texto":"Cambiar fichas, repartir y vender cartones de bingo y apoyar en la realización de otros juegos como tenis, bolos, billar, golf, entre otros, instalaciones recreativas y deportivas."},{"consecutivo":10,"texto":"Recibir, guardar y devolver prendas, paquetes y similares a las personas que utilizan atracciones mecánicas y servicios de recreación y deporte."},{"consecutivo":11,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"96291.001","nombre":"Acomodador / Acomodadora"},{"codigo":"96291.002","nombre":"Acomodador en espectáculos públicos / Acomodadora en espectáculos públicos"},{"codigo":"96291.003","nombre":"Acomodador en sala cine / Acomodadora en sala cine"},{"codigo":"96291.004","nombre":"Acomodador en teatro / Acomodadora en teatro"},{"codigo":"96291.005","nombre":"Auxiliar de bolera"},{"codigo":"96291.006","nombre":"Auxiliar de salón de billar"},{"codigo":"96291.007","nombre":"Auxiliar de salón de bingo"},{"codigo":"96291.008","nombre":"Auxiliar de parque de diversiones"},{"codigo":"96291.009","nombre":"Auxiliar de servicios de recreación y deporte"},{"codigo":"96291.010","nombre":"Boleador de tenis / Boleadora de tenis"},{"codigo":"96291.011","nombre":"Caddie de golf"},{"codigo":"96291.012","nombre":"Caddie de tenis"},{"codigo":"96291.013","nombre":"Guarda de parque de atracciones"},{"codigo":"96291.014","nombre":"Orientador en eventos / Orientadora en eventos"},{"codigo":"96291.015","nombre":"Proveedor de programas de teatro / Proveedora de programas de teatro"},{"codigo":"96291.016","nombre":"Recolector de boletos / Recolectora de boletos"},{"codigo":"96291.017","nombre":"Recolector de pelotas / Recolectora de pelotas"},{"codigo":"96291.018","nombre":"Revisor de boletos / Revisora de boletos"},{"codigo":"96291.019","nombre":"Asistente de magia / Asistenta de magia"}],"conocimientos":[{"id":"61","nombre":"Deportes"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"35","nombre":"Flexibilidad y adaptabilidad"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"19","nombre":"Selección de equipo"}],"ocupaciones_afines":[{"codigo":"42120","nombre":"Receptores de apuestas y afines / Receptoras de apuestas y afines"},{"codigo":"52300","nombre":"Cajeros de comercio, taquilleros y expendedores de boletas / Cajeras de comercio, taquilleros y expendedores de boletas"},{"codigo":"95100","nombre":"Trabajadores ambulantes de servicios y afines / Trabajadoras ambulantes de servicios y afines"},{"codigo":"96299","nombre":"Otras ocupaciones elementales no clasificadas en otras ocupaciones"}],"area_principal":{"sigla":"AFIR","nombre":"Actividades físicas, deportivas y recreativas"},"areas_complementarias":[{"sigla":"AVEM","nombre":"Audiovisuales, Artes Escénicas y Música"}],"equivalencias":[{"ciuo08_codigo":"4212*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"6642","cno_obs":"Denominaciones completas"},{"ciuo08_codigo":"9621*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"6644*","cno_obs":"Denominaciones parciales"},{"ciuo08_codigo":"9629*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"","cno_obs":""}]}'::jsonb),
  ('rol_cuoc', 'Ayudantes de mecánica y servicio automotriz', '96292', 'Fabricación, transformación de materiales, instalación, mantenimiento y reparación', 1, false, '{"codigo":"96292","nombre":"Ayudantes de mecánica y servicio automotriz","descripcion":"Ayudan a trabajadores a realizar labores sencillas y rutinarias relacionadas con ajuste, instalación, adecuación, mantenimiento y reparación de vehículos, maquinaria, equipo pesado y transporte. Se pueden desempeñar en talleres de mantenimiento automotriz, empresas manufactureras, ente otros, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"96","nombre":"RECOLECTORES DE DESECHOS Y OTRAS OCUPACIONES ELEMENTALES"},"subgrupo":{"codigo":"962","nombre":"Otras ocupaciones elementales"},"grupo_primario":{"codigo":"9629","nombre":"Otras ocupaciones elementales no clasificadas en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Prestar servicios de mantenimiento programado como cambio de aceite, lubricación de vehículos, reemplazo de bombillas, filtros, plumillas, revisión de niveles de combustible y aire, entre otros, de acuerdo con normativa vigente."},{"consecutivo":2,"texto":"Ayudar en el examen, prueba y ajuste de reparaciones mecánicas y latonería de camiones, buses, motocicletas, aviones y equipo pesado."},{"consecutivo":3,"texto":"Cargar, descargar, mover y alistar herramientas, materiales, equipos e insumos que se requieran en forma oportuna en los sitios de trabajo."},{"consecutivo":4,"texto":"Realizar actividades básicas relacionadas con mecánica de motores pequeños, maquinaría, equipos rotativos, industriales y otros equipos similares de acuerdo con normativa y procedimientos establecidos por la empresa."},{"consecutivo":5,"texto":"Realizar la disposición adecuada de residuos generados durante el desarrollo de actividades de asistencia mecánica y servicio automotriz, siguiendo normatividad ambiental."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"96292.001","nombre":"Auxiliar de mecánica"},{"codigo":"96292.002","nombre":"Auxiliar de mecánica automotriz"},{"codigo":"96292.003","nombre":"Auxiliar de taller de mecánica"},{"codigo":"96292.004","nombre":"Ayudante automotriz"},{"codigo":"96292.005","nombre":"Ayudante de latonería"},{"codigo":"96292.006","nombre":"Ayudante de mecánica automotriz"},{"codigo":"96292.007","nombre":"Ayudante de mecánica diésel"},{"codigo":"96292.008","nombre":"Ayudante de pintura automotriz"},{"codigo":"96292.009","nombre":"Ayudante técnico de mecánica / Ayudante técnica de mecánica"},{"codigo":"96292.010","nombre":"Ayudante técnico de mecánica automotriz en industria petrolera / Ayudante técnica de mecánica automotriz en industria petrolera"},{"codigo":"96292.011","nombre":"Llantero de montallantas / Llantera de montallantas"},{"codigo":"96292.012","nombre":"Montallantero / Montallantera"}],"conocimientos":[{"id":"38","nombre":"Mantenimiento"},{"id":"94","nombre":"Mecánica e ingeniería de vehículos, barcos y aeronaves de motor"},{"id":"13","nombre":"Mecánica y metalistería"},{"id":"5","nombre":"Servicio al cliente"},{"id":"92","nombre":"Tecnologías de protección y gestión del medio ambiente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"15","nombre":"Orientación al servicio"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"31150","nombre":"Técnicos en ingeniería mecánica / Técnicas en ingeniería mecánica"},{"codigo":"72310","nombre":"Mecánicos y reparadores de vehículos de motor / Mecánicas y reparadoras de vehículos de motor"},{"codigo":"72331","nombre":"Mecánicos industriales / Mecánicas industriales"},{"codigo":"72332","nombre":"Mecánicos de equipo pesado / Mecánicas de equipo pesado"},{"codigo":"72333","nombre":"Mecánicos de maquinaria textil, confección, c