  ('rol_cuoc', 'Otras ocupaciones elementales no clasificadas en otras ocupaciones', '96299', 'Servicios Personales y a la Comunidad', 1, false, '{"codigo":"96299","nombre":"Otras ocupaciones elementales no clasificadas en otras ocupaciones","descripcion":"Esta ocupación abarca a Otras ocupaciones elementales no clasificadas en otras ocupaciones del Grupo Primario 9629 Otras ocupaciones elementales no clasificadas en otros grupos primarios. por ejemplo, incluye aquellos que realizan labores elementales, sencillas y rutinarias en la prestación de servicios tales como emisión, admisión y cobro de estacionamiento, recibo y entrega de prendas y artículos personales en guardarropas, armarios o roperos y la ayuda a clientes a encontrar su ubicación en eventos de entretenimiento. Se pueden desempeñar en establecimientos de servicios, parqueaderos, entre otros.","nivel_competencia":1,"jerarquia":{"gran_grupo":{"codigo":"9","nombre":"OCUPACIONES ELEMENTALES"},"subgrupo_principal":{"codigo":"96","nombre":"RECOLECTORES DE DESECHOS Y OTRAS OCUPACIONES ELEMENTALES"},"subgrupo":{"codigo":"962","nombre":"Otras ocupaciones elementales"},"grupo_primario":{"codigo":"9629","nombre":"Otras ocupaciones elementales no clasificadas en otros grupos primarios"}},"funciones":[{"consecutivo":1,"texto":"Ayudar a las personas que entran y salen de establecimientos comerciales, guiarlas hacia los servicios sanitarios, puestos de venta, puntos de pago, entre otros, y dar instrucciones en casos de emergencia."},{"consecutivo":2,"texto":"Prestar servicio de vigilancia y patrullar por zonas de aparcamiento para prevenir robos de vehículos o daños a éstos."},{"consecutivo":3,"texto":"Recibir tiquetes, distintivos y pases de entrada a eventos, examinarlos para verificar su autenticidad aplicando criterios de color, fecha de expedición, entre otros, y acomodar a los asistentes en su lugar."},{"consecutivo":4,"texto":"Recibir, guardar y devolver prendas, paquetes y similares en cabinas o armarios a clientes de establecimientos comerciales."},{"consecutivo":5,"texto":"Registrar la entrada y salida a zonas de parqueo, expedir tiquetes, indicar la ubicación, calcular y cobrar a clientes las tarifas de parqueo de vehículos."},{"consecutivo":6,"texto":"Desempeñar funciones afines."}],"denominaciones":[{"codigo":"96299.001","nombre":"Auxiliar de estacionamiento"},{"codigo":"96299.002","nombre":"Auxiliar de guardarropa"},{"codigo":"96299.003","nombre":"Auxiliar de parqueadero"},{"codigo":"96299.004","nombre":"Ayudante de parking"}],"conocimientos":[{"id":"27","nombre":"Seguridad pública"},{"id":"5","nombre":"Servicio al cliente"}],"destrezas":[{"id":"4","nombre":"Comunicación asertiva"},{"id":"29","nombre":"Gestión del tiempo"},{"id":"15","nombre":"Orientación al servicio"},{"id":"37","nombre":"Proactividad"},{"id":"10","nombre":"Relaciones interpersonales"},{"id":"38","nombre":"Seguir instrucciones"},{"id":"11","nombre":"Trabajo en equipo"}],"ocupaciones_afines":[{"codigo":"52300","nombre":"Cajeros de comercio, taquilleros y expendedores de boletas / Cajeras de comercio, taquilleros y expendedores de boletas"},{"codigo":"95100","nombre":"Trabajadores ambulantes de servicios y afines / Trabajadoras ambulantes de servicios y afines"},{"codigo":"96291","nombre":"Auxiliares de servicios de recreación y deporte"}],"area_principal":{"sigla":"SEPC","nombre":"Servicios Personales y a la Comunidad"},"areas_complementarias":[{"sigla":"AFIR","nombre":"Actividades físicas, deportivas y recreativas"},{"sigla":"SEGU","nombre":"Seguridad"}],"equivalencias":[{"ciuo08_codigo":"9629*","ciuo08_obs":"Denominaciones parciales","cno_codigo":"6644*","cno_obs":"Denominaciones parciales"}]}'::jsonb)
